### 参考代码

```cpp
// ABC470 G - ΣШX
// 求所有子区间的 mex 之和。
//
// 关键恒等式：mex >= k  <=>  区间里 0..k-1 全部出现。
// 所以 答案 = Σ_{k>=1} f(k)，f(k) = 含有 0..k-1 全部值的子区间个数。
//
// 固定右端点 r，记 last_v(r) = 值 v 在 [1,r] 中最后一次出现的位置（没出现为 0）。
// 则 [l,r] 含全部 0..k-1  <=>  l <= min_{v<k} last_v(r)。
// 于是 f(k) = Σ_r G_k[r]，其中 G_k[r] = min_{v<k} last_v(r)。
//
// 做法：k 从小到大（即依次加入值 0,1,2,...）维护数组 G[r]。
// 加入值 v 时 G[r] = min(G[r], last_v(r))。
// last_v(r) 是阶梯函数：在 [p_i, p_{i+1}-1] 上等于 p_i（p 为 v 的出现位置）。
// 而 G[r] 关于 r 单调不降，所以每个区间里 "G[r] > p_i" 的是一段后缀，
// 把这段后缀整体赋成 p_i 即可 —— 线段树（区间赋值 + 区间最大值 + 全局和）。
// 加完值 v 后 f(v+1) = G 的总和，累加；只加到 mex(A) 为止（之后全为 0）。

#include <bits/stdc++.h>
using namespace std;

// 线段树：支持「区间整体赋值」「区间最大值」「全局求和」
struct SegTree {
    int n;
    vector<long long> sum, mx, lazy; // lazy = -1 表示该点没有待下传的赋值标记

    SegTree(int n_) : n(n_) {
        sum.assign(4 * n + 4, 0);
        mx.assign(4 * n + 4, 0);
        lazy.assign(4 * n + 4, -1);
    }

    // 把整棵树初始化成常量 v
    void build(int node, int l, int r, long long v) {
        sum[node] = v * (r - l + 1);
        mx[node] = v;
        lazy[node] = v;
        if (l == r)
            return;
        int mid = (l + r) >> 1;
        build(node << 1, l, mid, v);
        build(node << 1 | 1, mid + 1, r, v);
    }

    // 对节点 node（管 [l,r]）整体赋成 v
    void apply(int node, int l, int r, long long v) {
        sum[node] = v * (r - l + 1);
        mx[node] = v;
        lazy[node] = v;
    }

    // 下传懒标记
    void push(int node, int l, int r) {
        if (lazy[node] != -1 && l != r) {
            int mid = (l + r) >> 1;
            apply(node << 1, l, mid, lazy[node]);
            apply(node << 1 | 1, mid + 1, r, lazy[node]);
            lazy[node] = -1;
        }
    }

    // 区间赋值 [ql,qr] = v
    void assign(int node, int l, int r, int ql, int qr, long long v) {
        if (qr < l || r < ql)
            return;
        if (ql <= l && r <= qr) {
            apply(node, l, r, v);
            return;
        }
        push(node, l, r);
        int mid = (l + r) >> 1;
        assign(node << 1, l, mid, ql, qr, v);
        assign(node << 1 | 1, mid + 1, r, ql, qr, v);
        sum[node] = sum[node << 1] + sum[node << 1 | 1];
        mx[node] = max(mx[node << 1], mx[node << 1 | 1]);
    }

    // 在 [ql,qr] 里找第一个值 > w 的下标，找不到返回 -1
    int findFirst(int node, int l, int r, int ql, int qr, long long w) {
        if (qr < l || r < ql || mx[node] <= w)
            return -1;
        if (l == r)
            return l;
        push(node, l, r);
        int mid = (l + r) >> 1;
        int res = findFirst(node << 1, l, mid, ql, qr, w);
        if (res != -1)
            return res;
        return findFirst(node << 1 | 1, mid + 1, r, ql, qr, w);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n + 1);
    vector<char> present(n + 2, 0); // present[v] = 值 v 是否出现过
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        if (a[i] <= n)
            present[a[i]] = 1;
    }

    // mex(A)：整场只加到它为止（更大的 k 因为缺了 mex(A) 这个值，f(k)=0）
    int mexAll = 0;
    while (present[mexAll])
        mexAll++;

    if (mexAll == 0) { // 连 0 都没有，所有子区间 mex 都是 0
        cout << 0 << "\n";
        return 0;
    }

    // 每个值的出现位置（只需 0..mexAll-1，这些值保证出现过）
    vector<vector<int>> pos(mexAll);
    for (int i = 1; i <= n; i++)
        if (a[i] < mexAll)
            pos[a[i]].push_back(i);

    const long long INF = n + 1; // 比任何合法 last 值都大
    SegTree st(n);
    st.build(1, 1, n, INF);

    long long ans = 0;
    for (int v = 0; v < mexAll; v++) {
        const vector<int> &p = pos[v];
        int t = (int)p.size();

        // 位置 p[0] 之前，值 v 还没出现过，last_v(r)=0 → G[r] 压到 0
        if (p[0] > 1) {
            int f = st.findFirst(1, 1, n, 1, p[0] - 1, 0);
            if (f != -1)
                st.assign(1, 1, n, f, p[0] - 1, 0);
        }
        // 每个 [p[i], p[i+1]-1] 上 last_v(r) = p[i]，对 G 取 min
        for (int i = 0; i < t; i++) {
            int L = p[i];
            int R = (i + 1 < t) ? p[i + 1] - 1 : n;
            int f = st.findFirst(1, 1, n, L, R, (long long)p[i]);
            if (f != -1)
                st.assign(1, 1, n, f, R, (long long)p[i]);
        }

        // 加完值 v 后，G 的总和就是 f(v+1)
        ans += st.sum[1];
    }

    cout << ans << "\n";
    return 0;
}
```

### 易错点

首次出现之前最后位置为 $0$，这一段也要更新。树中保存的是合法左端点的数量，全局和及最终答案用 `long long`。

## A. Nine or Nein

### 题意

给定正整数 $A,B$，若 $A+B,A-B,AB,A/B$ 中至少一个恰好为 $9$，输出 Nine，否则输出 Nein。

<!-- reusable-foundations:start -->

### 从零讲：枚举与模拟：让代码和允许的动作一一对应

枚举是系统地检查所有候选；模拟是按题目规则推进状态。先写清一个候选是什么、有哪些动作、执行后哪些量改变，再决定循环边界。

例如从集合 $\{1,2,3\}$ 中选两个不同数：有序选择可枚举 $(i,j)$ 且 $i\ne j$，共六项；如果只关心无序的一对，就规定 $i<j$，得到 $(1,2)$、$(1,3)$、$(2,3)$，避免重复计数。同一个双循环，边界表达的是不同对象。

```cpp
for (int i = 0; i < n; i++)
    for (int j = i + 1; j < n; j++) {
        // 每一对不同位置恰好出现一次
    }
```

模拟例如计数器初始为零，依次读动作“加二、减一、加二”，状态为 $0\to2\to1\to3$。每一步都只读取该时刻允许的信息；若规则要求同时更新多个量，应先用旧状态算全部新量，不能让后一个更新误读前一个新值。

时间要数实际候选数和每个候选的工作。双循环可能是 $O(n^2)$，枚举长度为 $k$ 的二进制选择是 $O(2^k)$；候选少但每次又扫描全数组，也要乘上扫描成本。空间取决于是否需要保存历史。

全枚举的优势是思路直接，容易作为独立校验程序。剪枝必须证明被略去的分支不可能合法或更优，不能只因一个小例子没遇到答案就删候选。若直接枚举超时，先找重复工作、对称性、可维护的量或单调边界，再选择优化方法。

<!-- reusable-foundations:end -->

### 思路

直接检查四个条件。除法等于 $9$ 可改写为 $A=9B$，这样避免整数除法将小数部分截去。例如 $A=19,B=2$ 的商为 $9.5$，不能算作 $9$。时间、空间均为 $O(1)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a, b;
    cin >> a >> b;
    bool ok = a + b == 9 || a - b == 9 || a * b == 9 || a == 9 * b;
    cout << (ok ? "Nine" : "Nein") << '\n';
}
```

### 易错点

减法与除法有顺序，只检查题目给出的 $A-B$ 与 $A/B$。

## B. Survey Tabulation

### 题意

统计调查回答字符串的最大相同人数，忽略英文字母大小写。

<!-- reusable-foundations:start -->

### 从零讲：枚举与模拟：让代码和允许的动作一一对应

枚举是系统地检查所有候选；模拟是按题目规则推进状态。先写清一个候选是什么、有哪些动作、执行后哪些量改变，再决定循环边界。

