### 参考代码

```cpp
// ABC472 G - Cascading Grid
// 做法：把每一行里的极长非 # 连续段缩成一个点，得到一张只向下连边的 DAG；
//       一次操作 = 选一个点，删掉它的所有可达点（含自己）。
//       若干次操作的删除集恰好是「后代封闭集」，于是问题变成
//       在 DAG 上求权值和最小的后代封闭点集 —— 最小权闭合子图，用最小割求解。
#include <bits/stdc++.h>
using namespace std;

// ---------------------------------------------------------------- Dinic 最大流
struct Dinic {
    struct Edge {
        int to, rev;
        long long cap;
    };
    int n;
    vector<vector<Edge>> g;  // 邻接表
    vector<int> level, iter; // 层次图 / 当前弧

    explicit Dinic(int n) : n(n), g(n), level(n), iter(n) {}

    // 加一条 from -> to 容量 cap 的有向边（同时加反向 0 容量边）
    void addEdge(int from, int to, long long cap) {
        g[from].push_back({to, (int)g[to].size(), cap});
        g[to].push_back({from, (int)g[from].size() - 1, 0});
    }

    // BFS 给残量网络分层
    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (const auto &e : g[v])
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
        }
        return level[t] >= 0;
    }

    // 在层次图上找一条增广路
    long long dfs(int v, int t, long long f) {
        if (v == t)
            return f;
        for (int &i = iter[v]; i < (int)g[v].size(); ++i) {
            Edge &e = g[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                long long d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    long long maxflow(int s, int t) {
        long long flow = 0;
        while (bfs(s, t)) {
            fill(iter.begin(), iter.end(), 0);
            long long f;
            while ((f = dfs(s, t, (long long)4e18)) > 0)
                flow += f;
        }
        return flow;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for (int i = 0; i < H; i++)
        cin >> S[i];

    // 1) 把每行的极长非 # 连续段编号（seg[i][j] = 该格所在段编号）
    vector<vector<int>> seg(H, vector<int>(W, -1));
    vector<int> w; // 每段的权值 = 段内 '+' 数 - '-' 数
    int K = 0;     // 段总数
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (S[i][j] == '#' || seg[i][j] != -1)
                continue;
            int val = 0, k = j;
            while (k < W && S[i][k] != '#') {
                seg[i][k] = K;
                val += (S[i][k] == '+') ? 1 : -1;
                ++k;
            }
            w.push_back(val);
            ++K;
        }
    }

    long long T = 0; // 全图权值和
    for (int x : w)
        T += x;

    // 2) 建图：源点 0，段 1..K，汇点 K+1
    int src = 0, snk = K + 1;
    Dinic din(K + 2);
    const long long INF = (long long)1e15;
    long long negSum = 0; // 所有权值为负的段的 |权值| 之和
    for (int u = 0; u < K; u++) {
        // 最小权闭合子图 -> 取权值相反数的最大权闭合子图
        // a_u = -w_u：a_u > 0 时加 src->u（容量 a_u），a_u < 0 时加 u->snk（容量 -a_u）
        if (w[u] < 0) {
            din.addEdge(src, u + 1, -(long long)w[u]);
            negSum += -(long long)w[u];
        } else if (w[u] > 0)
            din.addEdge(u + 1, snk, (long long)w[u]);
    }
    // 相邻两行里列区间有交叠的段连一条 INF 边（选上面的段就必须选下面的段）
    for (int i = 0; i + 1 < H; i++)
        for (int j = 0; j < W; j++) {
            if (S[i][j] == '#' || S[i + 1][j] == '#')
                continue;
            int a = seg[i][j], b = seg[i + 1][j];
            if (a >= 0 && b >= 0)
                din.addEdge(a + 1, b + 1, INF);
        }

    long long minCut = din.maxflow(src, snk);
    // 最小删除代价 = minCut - negSum；答案 = 全图权值和 - 最小删除代价
    long long answer = T - (minCut - negSum);
    cout << answer << "\n";
    return 0;
}
```

### 易错点

强制边方向与删除传播方向相同，从上往下。无限容量取大于所有有限容量之和即可；空删除集始终允许。

## A. Second Half Sum

### 题意

数组长度 $N$ 为偶数，求后半段 $A_{N/2+1},\ldots,A_N$ 的和。

<!-- reusable-foundations:start -->

### 从零讲：枚举与模拟：让代码和允许的动作一一对应

枚举是系统地检查所有候选；模拟是按题目规则推进状态。先写清一个候选是什么、有哪些动作、执行后哪些量改变，再决定循环边界。

例如从集合 $\{1,2,3\}$ 中选两个不同数：有序选择可枚举 $(i,j)$ 且 $i\ne j$，共六项；如果只关心无序的一对，就规定 $i<j$，得到 $(1,2)$、$(1,3)$、$(2,3)$，避免重复计数。同一个双循环，边界表达的是不同对象。

```cpp
for (int i = 0; i < n; i++)
    for (int j = i + 1; j < n; j++) {
        // 每一对不同位置恰好出现一次
    }
```

模拟例如计数器初始为零，依次读动作“加二、减一、加二”，状态为 $0\to2\to1\to3$。每一步都只读取该时刻允许的信息；若规则要求同时更新多个量，应先用旧状态算全部新量，不能让后一个更新误读前一个新值。

时间要数实际候选数和每个候选的工作。双循环可能是 $O(n^2)$，枚举长度为 $k$ 的二进制选择是 $O(2^k)$；候选少但每次又扫描全数组，也要乘上扫描成本。空间取决于是否需要保存历史。

全枚举的优势是思路直接，容易作为独立校验程序。剪枝必须证明被略去的分支不可能合法或更优，不能只因一个小例子没遇到答案就删候选。若直接枚举超时，先找重复工作、对称性、可维护的量或单调边界，再选择优化方法。

<!-- reusable-foundations:end -->

### 思路

依次读入，使用 0 起下标时只累加 $i\ge N/2$ 的数。例如四个数的后半段是第三、第四个。时间 $O(N)$，额外空间 $O(1)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    int ans = 0;
    for (int i = 0, x; i < n; i++) {
        cin >> x;
        if (i >= n / 2)
            ans += x;
    }
    cout << ans << '\n';
}
```

### 易错点

分界右侧的第一个元素必须计入，前半段正好有 $N/2$ 个。

## B. Old Maid

### 题意

反复删除数字相同的两张牌，直到不能删除，求剩余牌数字之和。

<!-- reusable-foundations:start -->

### 从零讲：计数：先确定一个方案包含哪些选择

加法用于互斥类别，乘法用于逐步选择，除法用于消除确切的重复。公式每一项都应能对应一个实际对象，不能只凭“看起来有几个位置”相乘。

三个人中选两人且指定先后：第一人三种选择，第二人只能从剩下两人中选，得到六种。若只选一个无序小组，AB 和 BA 表示同组，每组恰数两次，除以二得到三组。

![六个有序选择按同一无序对配成三组，每组恰好出现两次](assets/foundations/counting.svg)

一般地，$n$ 个不同对象选 $k$ 个且排序有 $n(n-1)\cdots(n-k+1)$ 种；不区分内部顺序，恰有 $k!$ 个排列表示同一子集，所以

$$\binom nk=\frac{n!}{k!(n-k)!}.$$

这个除法成立依赖“每个最终对象被数同样多次”。若含相同元素、对称或禁用条件，重复倍数可能改变，要重新证明。比如组的内部无序和组之间无序是两种不同的对称性，不应混成一句“除去重复”。

互相独立不是乘法原则唯一的表述；逐步计数只需每种前序选择都有相同数量的后续选择。若后续数量随前序变化，就应分别计算后求和。

在模数下计算组合数时，普通整数除法不能直接替代分母逆元。若用阶乘和逆阶乘，须满足逆元存在等前提。答案可能指数增长，先确定取模或大整数方式；数值范围也决定预处理是否可行。

### 从零讲：枚举与模拟：让代码和允许的动作一一对应

