### 从零讲：把块数数成事件

集合 $\{1,2,5,7,8\}$ 有三块，块的开头是一个在集合内、但前一个整数不在集合内的值；值一单独处理。因此
$$\#\text{块}(S)=[1\in S]+\sum_{v=2}^n[v\in S,\ v-1\notin S].$$
圆盘上一个前缀对应从起点 $s$ 到终点 $x$ 的顺时针闭弧。固定值对 $(v-1,v)$，要只包含后者，终点必须从 $r_v$ 出发、尚未走到 $r_{v-1}$；起点则必须在 $r_{v-1}$ 之后到 $r_v$ 之间。这把两个点的成员关系转成独立的起点弧与终点弧。

固定终点后，每个有效值对向一整段起点贡献一，便是区间加。终点移动一格时，只有刚读到的值及其后继值对应的两项改变。这样无需为每个起点重新读一整圈，就能同时维护全部起点的块数。

### 思路

下节将块数转成对起点的一批区间贡献。记值 $v$ 的位置为 $r_v$，定义顺时针弧
$$C_v=[r_v,r_{v-1}),\qquad A_v=(r_{v-1},r_v]\quad(v\ge2).$$
终点 $x\in C_v$ 且起点 $s\in A_v$ 时，前缀弧 $[s,x]$ 恰好含 $v$ 而不含 $v-1$，于是多一个整数块。注意两条弧的开闭不同，不能直接当作互不相交的集合补集。

![值对的出现条件拆成两条弧](assets/e-arcs.svg)

旋转坐标，使值一在位置零。初始终点为零，直接检查哪些 $C_v$ 覆盖零，对其 $A_v$ 加一；因为所有以零结束的前缀弧都含值一，再全体加一。

终点逐格移动到 $j>0$，设该格值为 $u$。先对起点 $j$ 减一，表示这些前缀不再包含值一；再令 $A_u$ 加一、$A_{u+1}$ 减一，忽略越界值。它们分别对应新激活与刚结束的值对贡献。跨环区间拆成两段。

线段树维护每个起点的当前块数，支持区间加和全局最大值。每处理完一个终点，反复找到值至少三的起点并永久标坏，将其值改为足够小的负数。每个起点只删除一次，总事件与删除次数均为 $O(n)$，所以时间 $O(n\log n)$、空间 $O(n)$。

### 参考代码

```cpp
// Codeforces Div.2 1112 E. Double-Rift Dial
// 题意：排列 p 写在圆盘上，从起点 s 顺时针读一圈得到 q；若 q 的每个非空前缀的取值集合
//       都能拆成不超过 2 段连续整数（"块"），则 s 是好的。数好起点的个数。
//
// 思路（把"块数"化成圆上的区间覆盖，O(n log n)）：
// 1. 前缀长度 k 对应圆上一段顺时针弧 [s, x]（x 是当前读到的位置）。集合的块数
//    = #{v >= 2 : v 在弧内、v-1 不在弧内} + [值 1 在弧内]。
// 2. 记 r_v 为值 v 的位置，C_v = [r_v, r_{v-1})（顺时针半开），A_v = (r_{v-1}, r_v]（闭弧），
//    两者互补。对固定的弧终点 x：值对 (v-1, v) 贡献 1 ⟺ x ∈ C_v；此时它对「哪些起点 s 有贡献」
//    恰好是 s ∈ A_v。于是弧终点为 x 时，起点 s 的块数 = cov_x(s) + [s ∈ (x, r_1]]，
//    其中 cov_x(s) = #{v >= 2 : x ∈ C_v 且 s ∈ A_v}。
// 3. s 坏 ⟺ 存在 x 使上式 >= 3。让 x 从 r_1 起顺时针扫一圈：x 每越过 r_v 就把 A_v 加进
//    覆盖数组、越过 r_{v-1} 就撤回，另加一项随 x 逐格减 1 的 [s ∈ (x, r_1]]；
//    用「区间加 + 全局 max + 找任意 >=3 位置」的线段树，把每次冒出来的 >=3 起点标记为坏即可。
// 答案 = n - 坏起点数。

#include <bits/stdc++.h>
using namespace std;

// 线段树：区间加、全局最大值、找任意一个值 >= th 的叶子、单点赋值
struct SegTree {
    int n;
    vector<int> mx, lz;
    void init(int n_) {
        n = n_;
        mx.assign(4 * n + 4, 0);
        lz.assign(4 * n + 4, 0);
    }
    void apply(int o, int v) {
        mx[o] += v;
        lz[o] += v;
    }
    void push(int o) {
        if (lz[o]) {
            apply(2 * o, lz[o]);
            apply(2 * o + 1, lz[o]);
            lz[o] = 0;
        }
    }
    void add(int o, int l, int r, int ql, int qr, int v) {
        if (qr < l || r < ql)
            return;
        if (ql <= l && r <= qr) {
            apply(o, v);
            return;
        }
        push(o);
        int m = (l + r) >> 1;
        add(2 * o, l, m, ql, qr, v);
        add(2 * o + 1, m + 1, r, ql, qr, v);
        mx[o] = max(mx[2 * o], mx[2 * o + 1]);
    }
    void setp(int o, int l, int r, int pos, int val) {
        if (l == r) {
            mx[o] = val;
            lz[o] = 0;
            return;
        }
        push(o);
        int m = (l + r) >> 1;
        if (pos <= m)
            setp(2 * o, l, m, pos, val);
        else
            setp(2 * o + 1, m + 1, r, pos, val);
        mx[o] = max(mx[2 * o], mx[2 * o + 1]);
    }
    int findGe(int o, int l, int r, int th) {
        if (mx[o] < th)
            return -1;
        if (l == r)
            return l;
        push(o);
        int m = (l + r) >> 1;
        if (mx[2 * o] >= th)
            return findGe(2 * o, l, m, th);
        return findGe(2 * o + 1, m + 1, r, th);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    if (!(cin >> T))
        return 0;
    const int NEG = -1000000000;
    while (T--) {
        int n;
        cin >> n;
        vector<int> p(n + 1, 0);
        for (int i = 1; i <= n; i++)
            cin >> p[i];
        if (n == 1) {
            cout << 1 << '\n';
            continue;
        } // 单点集合只有 1 块
        int r1 = 1;
        for (int i = 1; i <= n; i++)
            if (p[i] == 1)
                r1 = i;
        // 旋转坐标：让值 1 落在下标 0，则扫 x 就是 j = 0..n-1
        vector<int> q(n), r(n + 1, 0);
        for (int j = 0; j < n; j++)
            q[j] = p[(r1 - 1 + j) % n + 1];
        for (int j = 0; j < n; j++)
            r[q[j]] = j;
        SegTree st;
        st.init(n);
        // 初始（x = 0）就活跃的弧：0 ∈ C_v = [r_v, r_{v-1})
        for (int v = 2; v <= n; v++) {
            int len = ((r[v - 1] - r[v]) % n + n) % n; // C_v 的顺时针长度
            int d0 = ((0 - r[v]) % n + n) % n;         // r_v 顺时针走到 0 的步数
            if (d0 < len) {
                int a = (r[v - 1] + 1) % n, b = r[v]; // A_v = 顺时针闭弧 [a, b]
                if (a <= b)
                    st.add(1, 0, n - 1, a, b, 1);
                else {
                    st.add(1, 0, n - 1, a, n - 1, 1);
                    st.add(1, 0, n - 1, 0, b, 1);
                }
            }
        }
        st.add(1, 0, n - 1, 0, n - 1, 1); // [s ∈ (x, r_1]]：x = r_1 时恒为 1
        int bad = 0;
        for (int j = 0; j < n; j++) {
            // j = 0 处不处理事件：初始覆盖数组就是 x = r_1 的活跃集合，
            // 而 v = 2 的"A_2 离开"发生在 x = r_1 时刻之前，重复撤回会把它误减掉。
            if (j > 0) {
                st.add(1, 0, n - 1, j, j, -1); // x 前进一步，该项在下标 j 处变 0
                int u = q[j];
                if (u >= 2) { // 弧 A_u 在 x = r_u 处进入
                    int a = (r[u - 1] + 1) % n, b = r[u];
                    if (a <= b)
                        st.add(1, 0, n - 1, a, b, 1);
                    else {
                        st.add(1, 0, n - 1, a, n - 1, 1);
                        st.add(1, 0, n - 1, 0, b, 1);
                    }
                }
                if (u + 1 <= n) { // 弧 A_{u+1} 在 x = r_u 处离开
                    int a = (r[u] + 1) % n, b = r[u + 1];
                    if (a <= b)
                        st.add(1, 0, n - 1, a, b, -1);
                    else {
                        st.add(1, 0, n - 1, a, n - 1, -1);
                        st.add(1, 0, n - 1, 0, b, -1);
                    }
                }
            }
            // 当前 x 下凡是覆盖数 >= 3 的起点都是坏起点；标记过的置成极小值，不会重复计入
            while (st.mx[1] >= 3) {
                int s = st.findGe(1, 0, n - 1, 3);
                st.setp(1, 0, n - 1, s, NEG);
                bad++;
            }
        }
        cout << n - bad << '\n';
    }
    return 0;
}
```

### 易错点

初始终点已直接建立完整状态，不再重复执行该位置的进入、离开事件。坏起点要永久排除，避免重复计数。

## F. Xor Permutation Matrix

### 题意

构造 $n\times n$ 矩阵，每行每列都是 $0\ldots n-1$ 的排列，相邻 $2\times2$ 四格异或恒为 $x$；无解输出负一。

