### 思路

设可凑出的购买总价集合为 $D$，返现函数为 $r(x)$。一次余额变化为 $h\to h-x+r(x)$，且须 $x\le h$。最后一单必须无返现，所以若最便宜商品已不低于首个返现阈值，所有答案都是否。

从零反向看：若 $v$ 已能清零，则只要 $v\ge r(x)$，余额 $v+x-r(x)$ 也能清零，因为这恰好等价于正向买得起这单。记首次产生净利润的可凑总价为
$$P=\min\{x\in D:r(x)>x\}.$$
在 $v<P$ 区域，所有可用反向步长 $x-r(x)$ 非负。更大消费也无法从这里反向使用，因为返现单调，$x\ge P$ 时有 $r(x)\ge r(P)>P>v$。因此低余额可以从小到大一次扫描。

同一步长 $d=x-r(x)$ 只保留最低返现门槛 $\operatorname{need}[d]$。随着扫描余额增加，把已满足门槛的步长加入位集 $A$；若当前余额 $v$ 可清零，则将 $A$ 左移 $v$ 位并入可清零位集。这一次批量标记所有反向后继。

余额至少 $P$ 时，可反复购买盈利单把余额抬到任意大。此后只剩全部变化量的最大公约数限制。令商品价格最大公约数为 $g_c$，末档返现为 $b_m$，计算
$$g=\gcd\left(g_c,b_m,\{|x-r(x)|:x\in D,\ x\le V\}\right),\quad V=\max(s,a_m).$$
更大购买总价都处于固定返现 $b_m$，其变化量的公约数由 $g_c,b_m$ 完整表示，所以不必枚举无界总价。

必要性很直接：每次余额变化都为 $g$ 的倍数。充分性要处理买得起的门槛。记可无返现购买的最便宜商品价格为 $c$。从零反向可反复加 $c$，到达任意高的 $c$ 倍数；在足够高余额处，有限组变化量都能使用。模 $c$ 意义下，它们生成的恰是 $g$ 的倍数剩余类，负次数可通过有限循环改为非负次数。对每个这类剩余类，都能先抬高再走一条有限路径到达，之后继续加 $c$，得到该类所有足够大的余额。因此所有足够大的 $g$ 倍数都能清零。原余额若是 $g$ 倍数且至少 $P$，先用盈利单抬到这里即可。

参考实现用位集生成可凑总价：已知 $x$ 可凑时，将整个可凑集合左移 $x$ 位并入。每次位移和反向批量扩展以机器字并行，保守时间 $O(V^2/w+V\log V+n+m)$，空间 $O(V)$，$w$ 为机器字位数。若不存在盈利单，全部查询都走低余额判定。

### 参考代码

```cpp
// G. No Balance Left —— 正解
//
// 【建模】把「余额能否清零」反过来看：若余额 v 能清零，且某一单花 x（x ∈ D，D 为可凑出的花费集合）
//   拿到返利 r(x)，那么 v - x + r(x) 也能清零；该单买得起要求 x <= v，等价于 v >= r(x)。
//   于是从 0 反向搜索：v -> v + x - r(x)，条件是 v >= r(x)。答案就是「v 能否被反向搜到」。
//
// 【两个分支】令 mnip = 最小的 x ∈ D 且 r(x) > x（即买这一单余额不降反升）：
//   ① 余额 < mnip：买得起的每一单都满足 r(x) <= x，余额单调不增；反向看就是单调递增，
//      可以按 v 从小到大扫一遍。把每一单的「净减少」d = x - r(x) 当作一步：
//      从 v 出发，只要 v >= r(x) 就能到 v + d。同一个 d 只保留要求 r 最小的那单即可，
//      于是扫描时维护一个「当前可用的 d 集合」（bitset），扫到 v 可达就 v |= 可用集合 << v。
//   ② 余额 >= mnip：反复买 mnip 能让余额无限增长，于是由裴蜀定理 / 弗罗贝尼乌斯定理，
//      「h 能清零」等价于 g | h，其中 g = gcd(b_m, gcd{c_i}, gcd{|x - r(x)|})。
//      （大额花费的净变化是 (若干 c_i 之和) - b_m，它们与 b_m 的 gcd 正好补齐这一项。）
//
// 复杂度：O(V^2 / 64)，V = max(s, a_m) <= 125000，6 秒足够。
#include <bits/stdc++.h>
using namespace std;

static const int MAXN = 125005;        // 上界：s, a_m, c_i, b_m <= 125000
static const int WN = (MAXN >> 6) + 2; // 64 位字的个数

static unsigned long long bInv[WN]; // 可凑出的花费集合 D
static unsigned long long bWin[WN]; // 反向可达的余额集合
static unsigned long long bAva[WN]; // 当前可用的「净减少量」集合

static inline bool bitGet(const unsigned long long *a, int i) {
    return (a[i >> 6] >> (i & 63)) & 1ULL;
}
static inline void bitSet(unsigned long long *a, int i) { a[i >> 6] |= 1ULL << (i & 63); }
// a |= b << sh，只更新到第 lim 位（lim 取到所在字），支持 a 与 b 是同一个数组（从高字往低字做）
static void orShift(unsigned long long *a, const unsigned long long *b, int sh, int lim) {
    int pw = sh >> 6, off = sh & 63, last = lim >> 6;
    for (int w = last - pw; w >= 0; --w) {
        if (pw + w >= WN)
            continue;
        unsigned long long cur = b[w] << off;
        if (off && w > 0)
            cur |= b[w - 1] >> (64 - off);
        a[pw + w] |= cur;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, s;
    cin >> n >> m >> s;
    vector<int> c(n);
    int cmin = INT_MAX;
    for (int i = 0; i < n; i++) {
        cin >> c[i];
        cmin = min(cmin, c[i]);
    }
    vector<int> a(m), b(m);
    for (int i = 0; i < m; i++)
        cin >> a[i] >> b[i];

    // 最后一单必须没有返利（否则余额不会正好到 0），所以必须有花费 < a_1 的买法，
    // 这等价于最小的商品价格 cmin < a_1；否则全是 NO。
    if (cmin >= a[0]) {
        string out;
        for (int h = 1; h <= s; h++)
            out += "NO\n";
        cout << out;
        return 0;
    }

    int V = max(s, a[m - 1]); // 余额、花费都只需关心 <= V

    // 1) 完全背包（bitset）：D[x] = x 能否由若干商品凑出
    bitSet(bInv, 0);
    for (int i = 0; i < n; i++)
        if (c[i] <= V)
            bitSet(bInv, c[i]);
    for (int i = 1; i <= V; i++)
        if (bitGet(bInv, i))
            orShift(bInv, bInv, i, V + 1);

    // 2) 双指针求 r(x)，同时定出 mnip 与「净减少量表」bestR[d] = 该 d 需要的最小 r
    vector<int> rv(V + 1, 0);
    vector<int> bestR(V + 1, INT_MAX);
    int mnip = INT_MAX, maxD = 0;
    for (int i = 1, pos = 0; i <= V; i++) {
        if (!bitGet(bInv, i))
            continue;
        while (pos < m && a[pos] <= i)
            pos++;
        int r = pos ? b[pos - 1] : 0;
        rv[i] = r;
        if (r > i) {
            mnip = min(mnip, i);
        } else if (r < i) { // 净减少 d = i - r > 0 才有用
            int d = i - r;
            if (r < bestR[d])
                bestR[d] = r;
            maxD = max(maxD, d);
        }
    }

    // 3) 低位（余额 < mnip）：反向单调扫描
    vector<pair<int, int>> trans; // (需求 r, 净减少量 d)，按需求排序
    for (int d = 1; d <= V; d++)
        if (bestR[d] != INT_MAX)
            trans.push_back(make_pair(bestR[d], d));
    sort(trans.begin(), trans.end());
    bitSet(bWin, 0); // 余额 0 可达
    int lim = (int)min<long long>(mnip, (long long)s + 1);
    size_t ptr = 0;
    for (int p = 0; p < lim; p++) {
        while (ptr < trans.size() && trans[ptr].first <= p) {
            bitSet(bAva, trans[ptr].second);
            ptr++;
        }
        if (!bitGet(bWin, p))
            continue;
        // 走到 p + d（只关心 <= s 的部分）
        orShift(bWin, bAva, p, min(s, p + maxD) + 1);
    }

    // 4) 高位（余额 >= mnip）：答案为 g 的倍数
    int g = b[m - 1];
    for (int i = 0; i < n; i++)
        g = gcd(g, c[i]);
    for (int i = 1; i <= V; i++)
        if (bitGet(bInv, i) && rv[i] != i)
            g = gcd(g, abs(i - rv[i]));

    string out;
    out.reserve((size_t)s * 4);
    for (int h = 1; h <= s; h++) {
        bool ok = (h < mnip) ? bitGet(bWin, h) : (h % g == 0);
        out += ok ? "YES\n" : "NO\n";
    }
    cout << out;
    return 0;
}
```

### 易错点

不能只检查余额是否整除某个公约数：低余额可能买不起需要的单。反向边的门槛是返现金额，正向边的门槛才是消费金额。

## A. Boss Fight

### 题意

任意重排伤害牌，第一次出现相邻同值时，该张仍造成伤害，之后全部伤害为零。求最大有效前缀伤害和。

<!-- reusable-foundations:start -->

### 从零讲：贪心：先证明当前选择不会丢掉最优解

贪心每一步确定一个局部选择，不再撤回。它能省去搜索，但必须解释为什么始终存在一个最优方案也做这个选择。

例如选择最多个互不重叠的活动（这里允许后一活动起点等于前一活动终点）。每次选结束最早的活动：若最优方案的首项结束更晚，把它换成最早结束者，后续原本能接的活动仍能接，数量不变。这就是交换论证；换完首项，剩余问题仍为同类问题。

![结束更早的首项留下不少于另一选择的可用时间](assets/foundations/greedy.svg)

实现时按结束时间升序排序，维护上一次选中活动的结束时刻，依次选合法项。排序 $O(n\log n)$，扫描 $O(n)$，保存活动为 $O(n)$。若题目不允许端点相接，判断须从大于等于改成严格大于。

“选最长”“选价值最高”“选最靠左”都是不同策略。没有交换、支配关系或不变量的依据，不能只凭排序键直觉宣布正确。比如有容量和价值的物品选择，眼前价值最高者可能挡住两个总价值更高的小物品。

写题解时说明被替换的是哪一项、替换后什么约束仍满足、目标为何不变差，并说明余下状态为何允许重复同样论证。若选择还影响未保存的条件，就可能需要更丰富的状态或动态规划。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cpp
vector<int> a(3, 7); // 三个元素，内容是 7、7、7
a.push_back(9);      // 在末尾追加，现在长度为 4
int x = a[1];        // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

### 从零讲：sort 与比较器：先建立统一的顺序

排序把原来任意排列的数据，按照可比较的键整理成有序序列，便于查边界、比较相邻项和按顺序处理。头文件 `<algorithm>`；普通数组和 `vector` 可用 `sort(first,last)`，范围为左闭右开。

```cpp
vector<int> a{5, 2, 5, 1};
sort(a.begin(), a.end());                 // 变成 1、2、5、5，重复值仍保留
sort(a.begin(), a.end(), greater<int>()); // 降序
```

`sort` 时间 $O(n\log n)$，不是每次比较都扫描整个数组。C++ 标准规定复杂度要求，不规定必须使用某一固定内部排序实现，不能统一称它为快速排序。

对 `pair`，默认先比较 `first`，相同再比较 `second`，都是升序。自定义比较器 `cmp(a,b)` 返回真表示“$a$ 必须排在 $b$ 前面”。例如按分数降序、同分按编号升序：

```cpp
sort(students.begin(), students.end(), [](const auto &a, const auto &b) {
    if (a.score != b.score)
        return a.score > b.score;
    return a.id < b.id;
});
```

规则必须自洽：元素不能排在自己前面，不能出现 $a$ 在 $b$ 前、$b$ 在 $c$ 前、$c$ 又在 $a$ 前的循环。`<=` 会让相同元素也必须互相在前，因此不是合法的严格比较器。排序过程中也不能改变比较依据。

排序会改变原位置；若编号或两项的配对有意义，应将完整记录一起排序或另存查询副本，不能把两个相关字段各自排序后继续当作原配对。普通 `sort` 不保证同键元素保持输入先后；确需稳定顺序时用 `stable_sort` 或将原编号纳入比较键。排序只建立顺序，不能代替贪心策略的正确性证明。

### 从零讲：map 与 unordered_map：按键保存信息

需要按数值、字符串或状态查“次数、最优值、编号”时，可以用键值表。`map<Key,Value>` 保持键有序，查找、插入和删除为 $O(\log n)$；`unordered_map<Key,Value>` 用哈希分桶，常见情况下平均 $O(1)$，最坏可能 $O(n)$，也不保持键顺序。

```cpp
map<int, int> count;
for (int x : vector<int>{4, 2, 4})
    ++count[x];
auto it = count.find(4);
if (it != count.end())
    cout << it->second; // 2
```

`count[x]` 在键不存在时会插入一项，整数值初始化为零，适合计数。只想查询是否存在应使用 `find` 或 C++17 的 `count`，避免查询改变表。`find` 返回迭代器，读取前检查不是 `end()`。

`map` 的成员 `lower_bound(x)` 查首个不小于 `x` 的键，为 $O(\log n)$；无序表没有这种大小边界。键是一对或复杂结构时，需要与比较规则一致的排序规则，或合适的哈希与相等规则。

空间随不同键数量增长，为 $O(n)$。遍历 `map` 按键递增，遍历无序表没有稳定的大小顺序。哈希表扩容可能使迭代器失效；删除当前项后也不能继续读取它。若键范围很小且连续，用数组计数通常更直接，避免树或哈希的额外开销。

### 从零讲：数值工具：连续编号、累加与最值

这些工具分别处理“填连续编号”“合并数值”“比较候选”，使用前要看返回类型和范围。`iota`、`accumulate` 在 `<numeric>`，`min`、`max` 在 `<algorithm>`。

```cpp
vector<int> id(4);
iota(id.begin(), id.end(), 0); // 0、1、2、3，容器本来就要有 4 项
vector<int> a{1000000000, 1000000000, 1000000000};
long long sum = accumulate(a.begin(), a.end(), 0LL); // 3000000000
int best = max(3, 7);                                // 返回 7，不会修改原参数
```

`accumulate` 的初始值决定累加器类型；写零会先按 `int` 累加，即使最终接收变量是 `long long` 也来不及修复溢出。`min`、`max` 的候选通常应为同一类型；更新变量须写 `best=max(best,candidate)`，只调用 `max` 不会自动赋值。

`fill(a.begin(),a.end(),value)` 给每个已有元素赋值，时间 $O(n)$。`memset` 逐字节填充，不适合填任意整数一或大哨兵；用 `fill` 更能直接表达意图。初始化一个长为 $n$ 的数组也需要 $O(n)$，把它放进每轮循环可能成为主要耗时。

极大或极小哨兵要与合法答案范围区分，并给后续加法留下余地。若不可达值为 `INF`，不能不检查就算 `INF+weight`；计数题、最短路和最大值问题的初值含义不同，应从“尚未选任何东西”或“尚未到达”的状态推出来。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cpp
int a = 100000, b = 100000;
long long wrong = a * b;       // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

<!-- reusable-foundations:end -->

### 思路

先考虑全部牌都生效：最大频次不超过 $\lceil n/2\rceil$ 时，能排成相邻互异，答案可取总和。否则枚举首次触发的前缀长度 $k$ 与触发值 $x$，最后两张必须都是 $x$。

从有效前缀中去掉末张 $x$，剩下 $k-1$ 张要相邻互异且以 $x$ 结束。设 $c=\lfloor(k-1)/2\rfloor$。其他值最多出现 $c$ 次；若 $k$ 为偶数，$x$ 最多出现 $c+2$ 次，若 $k$ 为奇数，最多 $c+1$ 次。这些条件也充分：在偶数长的交替排列中，各值至多一半且可指定一个出现的值结尾；奇数长时，若某值占一半再多一，它必须占首尾，因此只能是 $x$。这是把相同牌用其他牌隔开的计数条件。

固定 $(k,x)$ 后，先拿两张 $x$，再按伤害从大到小，在各值容量允许范围内补满 $k$ 张。若取了较小牌却漏掉容量仍允许的较大牌，交换能增加和，故该贪心最优；不足 $k$ 张则跳过。

例如 $[5,5,5,2]$ 可排成 $5,2,5,5$，触发张也计入，全部十七点伤害生效。枚举上述所有触发方式与不触发方式即可。参考代码使用映射计数，最坏时间上界 $O(n^3\log n)$，空间 $O(n)$。

#### 容量满足之后，为什么真的排得出有效前缀

需要的不是“选到 $k$ 张牌就按降序打出”，而是先选一份牌，再安排出牌次序。用一个长度为 $m$、要求最后为 $x$ 的相邻互异序列说明容量的充分性：$x$ 出现至少一次、至多 $\lceil m/2\rceil$ 次，其余每种至多 $\lfloor m/2\rfloor$ 次，恰好就是可行条件。

可以对长度归纳。长度一直接放 $x$。长度更长时先拿走最后一张 $x$，让剩余序列以某个 $y\ne x$ 结尾，再追加它。原长度为奇数时，拿走后每种数量均不超过新长度的一半，任取存在的非 $x$ 值 $y$ 即可；原长度为偶数时，非 $x$ 值中至多一个达到原长度的一半，若有就指定它为 $y$，否则任选。两种情况都满足较短序列的同一容量条件，归纳便能排出它，追加 $x$ 也不产生相邻重复。非 $x$ 值必然存在，否则长度大于一时 $x$ 的数量已超上限。

现在令 $m=k-1$，再加回最后一张触发牌 $x$，就得到代码的 `capo`、`capx`。所以 `got==k` 时选出的牌集能排成前 $k-1$ 张相邻互异、最后两张同为 $x$；`s` 才是一份真正可实现的伤害，允许拿它更新 `ans`。

#### 降序选牌与实际出牌是两种顺序

取七张牌 $[9,9,9,9,9,6,1]$，检查 $k=6,x=9$。容量为其他值各至多二张、九至多四张。先计两张九，再扫描排序数组：跳过已计的两张九，接受接下来的两张九，拒绝第五张九，然后接受六、一，得到六张牌，总和 $43$。

![九六九一九九产生四十三伤害，最后一张九触发后，剩下的九伤害为零；选牌顺序不等于出牌顺序](assets/editorial-reasoning/arrays3-boss-prefix.svg)

图中实际打出 $9,6,9,1,9,9$，最后再放剩下的九：第六张触发且照常伤害，第七张才变零。若照排序结果先打两个九，就会过早触发。检查 $k=7,x=9$ 时容量仍只准四张九，连同六、一共六张，`got<k`，于是不能把不存在的七张有效前缀加入答案。

固定 $k,x$ 后，先扣掉已强制选择的两张 $x$；剩余每种值可用的张数就是“实际剩余张数”和“剩余容量”的较小者。这形成一份确定的可选副本集合；降序扫描恰好取其中最大的 $k-2$ 张。任何选得更小的方案都能换入漏掉的较大副本而不超过该值的上限，因此不会丢掉最优牌集。枚举覆盖每个可能的首次触发长度和触发值；不触发的方案另由总和候选覆盖。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

// A. Boss Fight
// 伤害 = 打到第一处「相邻两张伤害相同」为止（含触发的那张）的前缀和；
// 全程不触发时 n 张全部结算。
//
// 设触发发生在第 k 张，真正结算的牌集为 S（|S| = k，触发值 x，末尾两张都是 x）。
// 前缀 S \ {x} 必须能排成「相邻互异」且以 x 收尾：
//   一个多重集能排成相邻互异（长度 m）<=> 每个值出现次数 <= ceil(m/2)；
//   还要求以 x 收尾（反过来等价于以 x 开头）要再加一条：
//   m 为奇数时，出现 (m+1)/2 次的那个值只能是 x。
// 翻成 S 上每个值的张数上限（记 capo = floor((k-1)/2)）：
//   k 为偶数：x <= capo + 2，其它每个值 <= capo；
//   k 为奇数：x <= capo + 1，其它每个值 <= capo；且 x 至少 2 张。
// 全程不触发：最多的一种值不超过 ceil(n/2) 时可全结算，答案 = 总和。
//
// 「每个值张数 <= 上限」是划分拟阵，故按伤害降序贪心取，同规模下和最大；
// 枚举 k = 2..n 与触发值 x（每个 x 先强制放 2 张，再对剩余牌贪心）取最大值。
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n);
        map<int, int> cnt; // 每种伤害的张数
        for (int i = 0; i < n; i++) {
            cin >> a[i];
            ++cnt[a[i]];
        }
        sort(a.rbegin(), a.rend()); // 伤害从大到小
        long long total = accumulate(a.begin(), a.end(), 0LL);
        int f = 0; // 最大出现次数
        for (auto &p : cnt)
            f = max(f, p.second);

        long long ans = 0;
        if (f <= (n + 1) / 2)
            ans = total;                        // 能全程不触发：全部结算
        for (int k = 2; k <= n; k++) {          // 触发在第 k 张
            int capo = (k - 1) / 2;             // 非触发值的上限
            int capx = capo + 1 + (k % 2 == 0); // 触发值的上限
            for (auto &pr : cnt) {
                if (pr.second < 2)
                    continue; // 触发值至少要有 2 张
                int x = pr.first;
                map<int, int> used;
                used[x] = 2; // 强制放进两张 x（末尾那对）
                long long s = 2LL * x;
                int got = 2, skipped = 0;
                for (int v : a) {
                    if (got >= k)
                        break;
                    if (v == x && skipped < 2) {
                        ++skipped;
                        continue;
                    } // 这两张已算过
                    int cap = (v == x) ? capx : capo;
                    if (used[v] < cap) {
                        ++used[v];
                        s += v;
                        ++got;
                    }
                }
                if (got == k)
                    ans = max(ans, s);
            }
        }
        cout << ans << '\n';
    }
    return 0;
}
```

### 易错点

首次相邻相同的第二张仍造成伤害。强制选择两张触发牌后，后续扫描要跳过这两个副本，防止重复计数。

## B. Always Changing

### 题意

可以任意删除字符，但删除的零、一必须严格交替。求将原二进制串变成交替串的最少删除数，无解输出负一。

<!-- reusable-foundations:start -->

### 从零讲：离散化、扫描线与连续区间

坐标可达十亿但只出现少量位置时，如果问题只依赖相对顺序，就可以把不同坐标排序去重，映射为连续排名。例如 $[100,5,100,20]$ 的不同坐标为 $[5,20,100]$，排名为 $[2,0,2,1]$。

```cpp
vector<int> values = a;
sort(values.begin(), values.end());
values.erase(unique(values.begin(), values.end()), values.end());
int rank = int(lower_bound(values.begin(), values.end(), x) - values.begin());
```

`unique` 把不同值移到前面，返回新的逻辑末尾；`erase` 才真正缩短长度。映射保留相等性与大小关系，不保留距离：五到二十距离十五，排名却只差一。几何长度、空隙数量或相邻整数关系须保留原值或带权间隙，不能直接用排名差。

扫描线将左右端点等事件按坐标排序，沿轴移动时只处理变化，避免扫描所有空坐标。例如闭区间在位置 $x$ 查询覆盖次数，应先加入左端等于 $x$ 的区间，查询时还保留右端等于 $x$ 的区间，之后才移除它们。相同坐标的事件先后取决于闭开边界，不能统一按任意事件编号排序。

连续段指满足某条件的一串相邻位置。相邻位置是原数组下标相差一，还是不同整数值相差一，要先明确；去重排序后相邻两个值未必是连续整数。扫描一段时常维护段首和段尾，变化处结算，最后一段也须处理。

排序预处理 $O(n\log n)$，映射每次二分 $O(\log n)$，扫描事件 $O(n)$ 加维护结构成本，空间通常 $O(n)$。若本来就有两个排序端点数组，纯计数查询可能不需另建离散坐标数组。

### 从零讲：计数：先确定一个方案包含哪些选择

加法用于互斥类别，乘法用于逐步选择，除法用于消除确切的重复。公式每一项都应能对应一个实际对象，不能只凭“看起来有几个位置”相乘。

三个人中选两人且指定先后：第一人三种选择，第二人只能从剩下两人中选，得到六种。若只选一个无序小组，AB 和 BA 表示同组，每组恰数两次，除以二得到三组。

![六个有序选择按同一无序对配成三组，每组恰好出现两次](assets/foundations/counting.svg)

一般地，$n$ 个不同对象选 $k$ 个且排序有 $n(n-1)\cdots(n-k+1)$ 种；不区分内部顺序，恰有 $k!$ 个排列表示同一子集，所以

$$\binom nk=\frac{n!}{k!(n-k)!}.$$

这个除法成立依赖“每个最终对象被数同样多次”。若含相同元素、对称或禁用条件，重复倍数可能改变，要重新证明。比如组的内部无序和组之间无序是两种不同的对称性，不应混成一句“除去重复”。

互相独立不是乘法原则唯一的表述；逐步计数只需每种前序选择都有相同数量的后续选择。若后续数量随前序变化，就应分别计算后求和。

在模数下计算组合数时，普通整数除法不能直接替代分母逆元。若用阶乘和逆阶乘，须满足逆元存在等前提。答案可能指数增长，先确定取模或大整数方式；数值范围也决定预处理是否可行。

### 从零讲：贪心：先证明当前选择不会丢掉最优解

贪心每一步确定一个局部选择，不再撤回。它能省去搜索，但必须解释为什么始终存在一个最优方案也做这个选择。

例如选择最多个互不重叠的活动（这里允许后一活动起点等于前一活动终点）。每次选结束最早的活动：若最优方案的首项结束更晚，把它换成最早结束者，后续原本能接的活动仍能接，数量不变。这就是交换论证；换完首项，剩余问题仍为同类问题。

![结束更早的首项留下不少于另一选择的可用时间](assets/foundations/greedy.svg)

实现时按结束时间升序排序，维护上一次选中活动的结束时刻，依次选合法项。排序 $O(n\log n)$，扫描 $O(n)$，保存活动为 $O(n)$。若题目不允许端点相接，判断须从大于等于改成严格大于。

“选最长”“选价值最高”“选最靠左”都是不同策略。没有交换、支配关系或不变量的依据，不能只凭排序键直觉宣布正确。比如有容量和价值的物品选择，眼前价值最高者可能挡住两个总价值更高的小物品。

写题解时说明被替换的是哪一项、替换后什么约束仍满足、目标为何不变差，并说明余下状态为何允许重复同样论证。若选择还影响未保存的条件，就可能需要更丰富的状态或动态规划。

### 从零讲：string：字符、下标与子串

`string` 保存字符序列。`string s="abca";` 的长度为四，下标从零开始，`s[0]=='a'`、`s[3]=='a'`。字符用单引号，字符串用双引号；二者类型不同。需要 `<string>`。

`cin >> s` 读到空白停止；整行含空格时使用 `getline`，并留意前一次格式化输入残留的换行。`s.size()` 是字符单元数量，不一定等于 UTF-8 中文字数；竞赛英文小写字母题通常一个字符对应一个单元。

```cpp
string s = "abca";
string middle = s.substr(1, 2); // 从下标 1 开始取 2 个字符，得到 bc
size_t pos = s.find('c');       // 得到 2；找不到是 string::npos
if (pos != string::npos)
    cout << s[pos];
```

`substr(start,length)` 的第二项是长度，不是右端点。普通下标访问为 $O(1)$；复制长为 $k$ 的子串需要 $O(k)$ 时间和空间，循环里反复截取可能累积成平方成本。字符串比较按第一个不同字符决定字典序，公共前缀可能需要线性比较。

常见字符转数字是 `c-'0'`，前提 `c` 在 `'0'` 到 `'9'`。修改原串可用 `for(char& c:s)`，只读使用 `char c`。`reverse(s.begin(),s.end())` 原地翻转；若还需要原串，应先复制。空串不能访问首尾，尾后位置不能当普通字符读取。

<!-- reusable-foundations:end -->

### 连续块怎样限制可保留的交替子序列

串 $\texttt{000110111}$ 可拆成四个同字符块，依次为零、一、零、一。交替子序列在同一块中最多取一项，因为块内两个相同字符之间没有另一种字符可供穿插；每块取一项又确实交替，所以最长长度就是块数。

![连续块与交替子序列](assets/b-blocks.svg)

若需要指定首字符，而第一块不是它，就必须从下一块开始，最大长度少一。若还要求最终长度为奇数，可能再少一块。这解释了本题只需试块数附近的几个长度。

不过“保留串交替”只是条件的一半：被删字符也要能排成零一交替。其数量差至多一便是充要条件，将两种数量规则一起检查才能得到答案。

### 思路

删除顺序可以任意安排，所以只要被删除的零、一数量相差至多一，就能交替删除。设原串零减一的数量差为 $d$，保留串的差为 $d'$，要求 $|d-d'|\le1$。

交替串偶数长度时 $d'=0$，奇数长度时由首字符决定 $d'=1$ 或负一。前面的连续块观察说明最大可保留长度由块数 $B$ 限制。于是逐类找最长合法长度：

- $|d|\ge3$：任何交替串都不满足数量差，无解。
- $d=0$：直接保留 $B$ 项。
- $|d|=1$：偶数长无额外要求，奇数长必须以原多数字符开始；不满足时从 $B$ 减一。
- $|d|=2$：只能保留奇数长，并以原多数字符开始。$B$ 偶时取 $B-1$；$B$ 奇且首块正确时取 $B$；否则需删去两端各一块，取 $B-2$。

答案为 $n-L$，扫描时间 $O(n)$，空间 $O(1)$。

#### 从原下标选删除集合，再安排交替删除顺序

取原串 `100001`，原位置二的零保留，其余五格按图中编号删除：

![原位置三、一、四、六、五依次删除零一零一零；保留第二位零，最长保留长度为一](assets/editorial-reasoning/arrays11-changing-order.svg)

原串零比一多二、共有三块，首块却是一。保留三项时只能得到 `101`，其差为负一，待删差会变成三，无法交替；跳过首块只剩两项，偶数保留差为零，待删差仍是二，也不行。还要去掉末块，才能保留一个零。图中待删的三个零、两个一确实能按零、一、零、一、零执行，答案为五。

这个顺序不要求原下标递增，删除前一格也不会删除我们事先指定的其它格。一般地，固定任何交替保留子序列后，其余零、一数量差不超过一，就可从较多的一类开始轮流任选一格删除；两类相等时任一类先删均可。因此“保留子序列能取到”与“删除集合能交替执行”能够在同一方案中同时成立。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

// 题目：二进制串 s，可以删字符，但被删字符的值必须严格交替（0101... 或 1010...）。
// 问最少删几个字符能让剩下的串成为交替串，做不到输出 -1。
//
// 关键 1：删除的先后顺序由我们决定，所以一个「删除集合」可行 当且仅当
//         其中 0 的个数 c0 与 1 的个数 c1 满足 |c0 - c1| <= 1。
// 关键 2：设保留的交替串长度为 L，起点字符为 b。则它的
//         (0 的个数 - 1 的个数) 只能是 +1（b=0 且 L 奇）、-1（b=1 且 L 奇）、0（L 偶）。
//         记 d = cnt0(s) - cnt1(s)，要求 |d - x| <= 1，其中 x 取上面三种之一。
//         |x| <= 1 且 |d - x| <= 1  =>  |d| >= 3 时直接无解。
// 关键 3：把 s 按连续相同字符分块，块数记 B（最长交替子序列 = B，且任意长度 L <= B 都能取到）。
//         - d == 0：任意长度都合法（偶长 x=0，奇长 x=±1），保留 L = B。
//         - |d| == 1：偶长合法；奇长必须以 need = (d>0 ? '0' : '1') 开头。
//                     若 B 为偶数 => L = B；否则看首块字符是否为 need，是则 L = B，否则 L = B-1。
//         - |d| == 2：只有奇长且以 need 开头合法（x 必须等于 sign(d)）。
//                     B 奇且首块是 need => L = B；B 偶 => L = B-1；B 奇且首块不是 need => L = B-2。
//         答案 = n - L。
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        string s;
        cin >> n >> s;

        int c1 = 0;
        for (char ch : s)
            if (ch == '1')
                ++c1;
        int c0 = n - c1;
        int d = c0 - c1; // 原串里 0 比 1 多几个

        int B = 1; // 连续段（块）个数
        for (int i = 1; i < n; i++)
            if (s[i] != s[i - 1])
                ++B;
        char first = s[0]; // 首块字符

        if (d >= 3 || d <= -3) {
            cout << -1 << "\n";
            continue;
        }

        int keep; // 最多能保留多少字符
        if (d == 0) {
            keep = B;
        } else if (d == 1 || d == -1) {
            char need = (d == 1) ? '0' : '1'; // 奇数长度时唯一允许的开头字符
            if (B % 2 == 1 && first != need)
                keep = B - 1; // 退而求其次，取偶数长度 B-1
            else
                keep = B;
        } else { // |d| == 2
            char need = (d == 2) ? '0' : '1';
            if (B % 2 == 1 && first == need)
                keep = B;
            else if (B % 2 == 0)
                keep = B - 1;
            else
                keep = B - 2;
        }
        cout << n - keep << "\n";
    }
    return 0;
}
```

### 易错点

限制作用于删除顺序，而不是删除位置从左到右的字符顺序；不要把问题误作只能从端点删除。

## C. Risky Tower

### 题意

塔的每行有稳定度与若干块，抽掉第 $i$ 行一块，会按该块数值减少第 $1\ldots i$ 行稳定度。任意行稳定度不正，或被抽空，塔即倒塌。求最少抽块数。

<!-- reusable-foundations:start -->

### 从零讲：贪心：先证明当前选择不会丢掉最优解

贪心每一步确定一个局部选择，不再撤回。它能省去搜索，但必须解释为什么始终存在一个最优方案也做这个选择。

例如选择最多个互不重叠的活动（这里允许后一活动起点等于前一活动终点）。每次选结束最早的活动：若最优方案的首项结束更晚，把它换成最早结束者，后续原本能接的活动仍能接，数量不变。这就是交换论证；换完首项，剩余问题仍为同类问题。

![结束更早的首项留下不少于另一选择的可用时间](assets/foundations/greedy.svg)

