### 从零讲：笛卡尔树

最大值笛卡尔树按数组顺序建树：整个区间的最大值当根，左侧区间递归作左子树，右侧作右子树。每个节点的子树始终对应连续区间，父节点值不小于子节点。相同最大值用统一规则，例如始终取最左。

任意区间 $[l,r]$ 的最大值位置，是它的两个端点在树上的最近公共祖先。等价地，对根位置 $v$，跨过 $v$ 的区间都在这一层处理；不跨过的区间完全落在左边或右边，交给子问题。因此全部区间不重不漏地分到某个最大值节点。

本题一旦固定最大值，就只剩两侧前缀异或能否互补。单次把左右所有位置两两配对仍很慢，但一个侧面存成频次表，另一侧逐个查补数，就把乘法复杂度变成两侧较小者的大小。保留大侧、重扫小侧，便是这里的启发式合并。

### 思路

按位与对异或分配，令前缀异或为 $P$，区间能量为 $(P_{l-1}\oplus P_r)\mathbin{\&}m$。从高位到低位贪心，尝试让答案包含候选掩码 $M$ 的全部位；若有区间可行就保留该位。

按最大值笛卡尔树分配区间。节点 $v$ 的子树范围为 $[L,R]$，归它负责的区间包含 $v$，最大值为 $a_v$。必须先有 $a_v\mathbin{\&}M=M$。再令 $s_i=P_i\mathbin{\&}M$，要求两边前缀端点满足
$$x\in[L-1,v-1],\ y\in[v,R],\qquad s_x\oplus s_y=M.$$

![最大值节点两侧的前缀端点范围](assets/e-cartesian.svg)

判定时保留较大孩子的前缀值频次，枚举较小一侧，在大侧查找 $s_x\oplus M$。同值必须存次数，因为合法性取决于是否还有其他位置可选。唯一非法端点对 $(v-1,v)$ 对应单点区间，先暂时去掉对应边界、检查完再恢复。

小侧的每个点每被枚举一次，所处区间至少大约翻倍，因此一轮判定 $O(n\log n)$。代码用稀疏表找区间最大位置、显式栈处理这棵隐式树，总时间 $O(18n\log n)$，空间 $O(n\log n+2^{18})$。最后与整段能量取最大不会改变正确贪心结果，整段本身已在判定范围内。

### 参考代码

```cpp
// E. KiaKio and Energy Intervals
//
// 关键链条：
//  1) 记前缀异或 p_i = a_1 ^ ... ^ a_i。因为按位与对异或满足分配律，
//     区间 [l,r]（最大值 m）的能量 = (p_{l-1} ^ p_r) & m。
//  2) 建最大值笛卡尔树（严格按“区间最大值位置”递归建，并列取最左，规则统一即可）：
//     对任意区间 [l,r]，其 LCA 就是区间最大值所在位置 v，于是能量 = (p_{l-1} ^ p_r) & a_v。
//  3) 从高位到低位贪心：维护候选掩码 mask，判定「是否存在长度 ≥ 2 的区间，能量包含 mask 的每一位」。
//     判定：把前缀异或按 mask 掩掉，s_i = p_i & mask。对每个 a_v ⊇ mask 的结点 v
//     （子树范围 [L,R]），需要 x = l-1 ∈ [L-1, v-1]、y = r ∈ [v, R] 使 s_x ^ s_y = mask；
//     唯一要排除的是 (x,y) = (v-1, v)，它对应被禁止的单元素区间 [v,v]。
//  4) 每个结点用「小往大并」：把较大孩子那半边的 s 值留在频次数组里，枚举较小半边（外加边界点）查补数。
//     每个下标每次被扫到，它所在子树大小至少翻倍，故每个 mask 判定 O(n log n)，18 位共 O(18 n log n)。
//     频次数组用计数而非布尔，值相同的不同端点才不会互相吃掉。
// 实现用显式栈而非递归：有序数组的笛卡尔树深度可达 n。
#include <bits/stdc++.h>
using namespace std;

static const int MAXN = 200005;
static const int BITS = 18;        // a_i < 2^18
static const int MAXV = 1 << BITS; // 掩码后的前缀异或值域

int n;
int a[MAXN];      // 1 下标
int s[MAXN];      // s_i = p_i & mask
int cntArr[MAXV]; // 频次数组：值 -> 出现次数
int lgOf[MAXN];
int sp[BITS + 1][MAXN]; // 稀疏表：区间最大值所在下标

// 返回 [l,r] 里最大值所在下标（并列取最左）
static inline int argmaxRange(int l, int r) {
    int k = lgOf[r - l + 1];
    int x = sp[k][l], y = sp[k][r - (1 << k) + 1];
    return a[x] >= a[y] ? x : y;
}

// 判定：是否存在长度 >= 2 的区间，其能量包含 mask 的所有位
static bool feasible(int mask) {
    int cur = 0; // 掩码后的前缀异或
    s[0] = 0;
    for (int i = 1; i <= n; i++) {
        cur ^= a[i];
        s[i] = cur & mask;
    }

    struct Frame {
        int l, r, phase;
    };
    static Frame stk[MAXN]; // 栈深不超过笛卡尔树深度
    int top = 0;
    stk[top++] = {1, n, 0};
    bool found = false;

    while (top > 0) {
        Frame f = stk[top - 1];
        int l = f.l, r = f.r;

        if (l == r) { // 叶子：把 s_l 记进频次数组
            cntArr[s[l]]++;
            top--;
            continue;
        }
        if (r == l + 1) { // 只有两个元素：唯一合法区间就是 [l,r]
            cntArr[s[l]]++;
            cntArr[s[r]]++;
            int m = max(a[l], a[r]);
            if ((m & mask) == mask && (s[l - 1] ^ s[r]) == mask)
                found = true;
            top--;
            continue;
        }

        int mid = argmaxRange(l, r);               // 根 = 区间最大值
        bool leftSmaller = (mid - l) <= (r - mid); // 左孩子小就往左并

        if (f.phase == 0) {
            stk[top - 1].phase = 1;
            if (leftSmaller) { // 先处理较小的左孩子
                if (l <= mid - 1)
                    stk[top++] = {l, mid - 1, 0};
            } else { // 先处理较小的右孩子
                if (mid + 1 <= r)
                    stk[top++] = {mid + 1, r, 0};
            }
        } else if (f.phase == 1) {
            stk[top - 1].phase = 2;
            // 撤掉小孩子的 s 值，保证大孩子处理期间数组里只有它自己的值
            if (leftSmaller) {
                for (int i = l; i < mid; i++)
                    cntArr[s[i]]--;
            } else {
                for (int i = mid + 1; i <= r; i++)
                    cntArr[s[i]]--;
            }
        } else if (f.phase == 2) {
            stk[top - 1].phase = 3;
            if (leftSmaller)
                stk[top++] = {mid + 1, r, 0}; // 大孩子：右
            else
                stk[top++] = {l, mid - 1, 0}; // 大孩子：左
        } else if (f.phase == 3) {
            stk[top - 1].phase = 4;
            bool ok = ((a[mid] & mask) == mask); // 能量 ⊆ a_mid，必须 a_mid ⊇ mask
            if (leftSmaller) {
                // 此刻数组里是右孩子 [mid+1, r] 的 s 值；枚举 x = mid-1 ... l-1
                for (int x = mid - 1; x >= l - 1; x--) {
                    if (ok && cntArr[s[x] ^ mask] > 0)
                        found = true;
                    // x = mid-1 检查完才放 s_mid：这样正好排除非法的 (mid-1, mid)
                    if (x == mid - 1)
                        cntArr[s[mid]]++;
                }
            } else {
                // 此刻数组里是左孩子 [l, mid-1] 的 s 值；枚举 y = mid ... r
                cntArr[s[mid - 1]]--; // 先禁掉 x = mid-1
                cntArr[s[l - 1]]++;   // 边界点 x = l-1 临时放进数组
                for (int y = mid; y <= r; y++) {
                    if (ok && cntArr[s[y] ^ mask] > 0)
                        found = true;
                    if (y == mid)
                        cntArr[s[mid - 1]]++; // y = mid 查完就恢复 x = mid-1
                }
                cntArr[s[l - 1]]--;
            }
        } else {
            // phase 4：补回小孩子与 s_mid，维持「子树内 s 值全在数组里」的不变量
            if (leftSmaller) {
                for (int i = l; i < mid; i++)
                    cntArr[s[i]]++;
            } else {
                for (int i = mid + 1; i <= r; i++)
                    cntArr[s[i]]++;
                cntArr[s[mid]]++;
            }
            top--;
        }
    }

    // 收尾：处理完根之后数组里恰好是 s_1..s_n 各一份，全部清掉
    for (int i = 1; i <= n; i++)
        cntArr[s[i]] = 0;
    return found;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    lgOf[1] = 0;
    for (int i = 2; i < MAXN; i++)
        lgOf[i] = lgOf[i >> 1] + 1;

    int t;
    cin >> t;
    while (t--) {
        cin >> n;
        for (int i = 1; i <= n; i++)
            cin >> a[i];

        // 稀疏表：区间最大值位置
        for (int i = 1; i <= n; i++)
            sp[0][i] = i;
        for (int j = 1; j <= BITS; j++) {
            int half = 1 << (j - 1);
            for (int i = 1; i + (1 << j) - 1 <= n; i++) {
                int x = sp[j - 1][i], y = sp[j - 1][i + half];
                sp[j][i] = (a[x] >= a[y]) ? x : y;
            }
        }

        // 整段 [1,n] 一定合法，它的能量给答案兜个底
        int mx = 0;
        for (int i = 1; i <= n; i++)
            mx = max(mx, a[i]);
        int whole = 0;
        for (int i = 1; i <= n; i++)
            whole ^= (a[i] & mx);

        int ans = 0;
        for (int b = BITS - 1; b >= 0; b--) {
            int cand = ans | (1 << b);
            if (feasible(cand))
                ans = cand;
        }
        cout << max(ans, whole) << '\n';
    }
    return 0;
}
```

### 易错点

只存在某个数含候选位还不够，区间异或也必须保留这些位。单点区间一定要排除，不能因为它能量较大而纳入答案。

## F. AghaBalaSar and Hamed

### 题意

排列中从位置 $i$ 可一步到任意更小下标，或到右边第一个比 $p_i$ 大的位置 $R_i$。求所有有序点对最短距离之和，不可达及原地距离记零。

<!-- reusable-foundations:start -->

### 从零讲：动态规划：保存明确子问题的答案

若多个决策会反复遇到相同的剩余问题，可以为每个不同问题保存一次答案。状态不是“当前操作到了哪儿”的模糊描述，而是一个有完整条件、能独立提问的问题。

例如台阶一次走一或二级，求到达第 $i$ 级的方式数。令 $f_i$ 为恰好到第 $i$ 级的方案数。最后一步只有两类：从 $i-1$ 走一级，或从 $i-2$ 走两级，类别互斥且覆盖所有方案，所以 $f_i=f_{i-1}+f_{i-2}$。

![每个状态读取已经确定的两个更小状态，箭头表示依赖](assets/foundations/dp.svg)

起点 $f_0=1$ 表示原地不走的一种空方案，$f_1=1$。于是 $f_2=2,f_3=3,f_4=5$。从小到大计算，因为当前格依赖的格都已经完成。`f[0]=0` 会把“空方案”错误删掉。

```cpp
vector<long long> f(n + 1, 0);
f[0] = 1;
for (int i = 1; i <= n; i++) {
    f[i] = f[i - 1];
    if (i >= 2)
        f[i] += f[i - 2];
}
```

另一个问题若问最小费用，就应对候选取 `min`；问最大收益取 `max`；问数量才在不重不漏的分类下相加。不能只把加号替换掉，初值也要随状态含义重新决定。不可达状态应与合法的零答案区别。

时间通常为状态数乘每个状态枚举的转移数，本例 $O(n)$；保存整表用 $O(n)$。只依赖最近两格时可滚动到 $O(1)$ 空间，但要先保存仍需读取的旧值。若下标不够决定后续可选动作，就缺少状态维度，不能把不同问题混在同一格。

检查一份 DP 时依次核对：状态的问题、基础答案、最后一步分类、依赖计算顺序、最终读哪一格。记忆化搜索使用同样的子问题，只是按递归需要计算；它也需要终止条件并避免状态依赖成环。

### 从零讲：单调栈与单调队列：删去以后不会更优的候选

若某个新候选在所有未来场景都不劣于一个旧候选，就可以永久删去旧候选。这种支配关系使栈或双端队列中的值保持单调，而不是仅仅为了“看上去有序”。

#### 单调栈找下一个更大项

从左扫描 $[2,1,3]$，栈保存尚未找到答案的下标。读三时，它大于栈顶的一，故一的首个右侧更大值为三；再大于二，二的答案也是三。每个值在自己的答案被首次发现时出栈。

![三到来时依次解决一、二的询问，每个下标只入栈出栈一次](assets/foundations/monotonic.svg)

```cpp
for (int i = 0; i < n; i++) {
    while (!st.empty() && a[st.back()] < a[i]) {
        answer[st.back()] = i;
        st.pop_back();
    }
    st.push_back(i);
}
```

严格大于用 `<` 弹出；若问大于等于，等号处理会改变。栈里保存下标，才能计算距离和识别相同数的不同位置。没有答案的项保留约定哨兵。

#### 单调队列维护固定窗口最大值

队首保存当前最大项的下标。新值到来，从队尾删除不大于它的旧值：新值更晚过期且不小，不会比这些旧值差；再把过期下标从队首移走。查询最大值读队首。

每个下标都只入、出一次，所以两者总时间 $O(n)$，空间最坏 $O(n)$。这是摊还分析，不能把“一个 while 里有时弹很多项”误算为必然平方，也不能把每次操作都说成严格常数。删候选之前应证明它在剩余有效期内永远不更优；窗口范围改变或查询目标不同，支配关系也要重证。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cpp
int a = 100000, b = 100000;
long long wrong = a * b;       // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

<!-- reusable-foundations:end -->

### 思路

先用单调栈求 $R_i$。这些“下一个更大值”边有嵌套性质：若 $i<j<R_i$，则 $p_j<p_i<p_{R_i}$，从而 $R_j\le R_i$。一条右跳边覆盖的内部位置，不能凭一次右跳越过它的终点，这是后续递推的依据。

所有没有右跳边的位置是后缀最大值，把它们作为分块右端。每块 $[l,r]$ 内的值均不超过 $p_r$，左边块的终点又更大，任何左跳绕路也不能越过当前块右端。因此去右边块不可达，去左边任意位置都是一步。只需计算块内距离和 $dp_i$，最后加上每个起点对左侧 $l-1$ 个点的贡献。

对当前 $i$，称满足 $j>i$ 且存在 $k\le i$、$R_k=j$ 的位置为标记点。它们通过“先左跳，再右跳”至多两步可达。令最右标记为 $z$，其数量为 $c$，并令 $a=R_i$、$b=R_a$。

利用嵌套性质，所有标记点都不在 $a$ 左侧。若 $z=a$，通往 $a$ 右侧的最短路径可以先走到 $a$：开头绕到左边再右跳也无法超过它，换成经过 $a$ 不增加步数。于是对 $j>a$，$f(i,j)=1+f(a,j)$。直接统计 $i$ 左侧的一步点、$(i,a)$ 内的两步点与 $a$，可得
$$dp_i=dp_a+r-i-1.$$

若 $z>a$，则 $b\le z$；右跳边的嵌套还保证，在越过 $z$ 前的任何绕路都可压缩为两步到 $z$，所以对 $j>z$ 有 $f(i,j)=2+f(z,j)$。区间 $(i,z]$ 内，$a$ 一步可达；恰好两步的点来自三类：$(i,a)$、存在时的 $b$、除 $a$ 外的标记点。$b$ 若也被标记，去重一次，故
$$c_2=(a-i-1)+[b\text{ 存在}]+(c-1)-[b\text{ 也被标记}].$$
其余点均可“两步到 $z$，再左跳”，恰需三步。将这些贡献与 $dp_z$ 对齐，得到
$$dp_i=dp_z+2(r-i)-2-c_2.$$

块内从右向左递推，初始 $dp_r=r-l$。预处理 $L_j=\min\{k:R_k=j\}$，标记条件就是 $L_j\le i<j$。把相同 $L_j$ 的点挂桶，扫描时撤销失效标记、加入新进入右侧的点，最右标记指针只向左移动。所有指针、桶和栈操作总计 $O(n)$，空间 $O(n)$。

### 参考代码

```cpp
// F. AghaBalaSar and Hamed
//
// 题意：p 是长度 n 的排列。从 i 出发一步可以走到
//   (a) 任意 j < i；
//   (b) R_i = i 右边第一个满足 p_j > p_i 的位置（不存在就不能往右走）。
// f(i,j) = 最少步数（不可达记 0，f(i,i)=0），求 Σ f(i,j)。
//
// 结论（官方题解思路）：
//  1) 最短路形如 L,R,R,…,R,L：至多先往左走一步，之后的向右走全是被迫的 R，最后至多再往左走一步。
//  2) 按「R_r = n+1」的位置 r 分块（r 是后缀最大值）。块内的点向右只能走到块内，
//     所以「i 到右边更远的块」一律不可达；而左边所有点都能一步到达（往左随便走）。
//     于是答案 = Σ_块 Σ_{i∈块}（块内距离和 + (l-1)），最后那项就是块左侧每个点贡献的 1 步。
//  3) 块内递推（i 从 r-1 递减到 l）。设 dp_i = i 到本块所有点的距离和：
//       标记点：存在 k ≤ i 使 R_k = j 且 j > i 的 j（等价于 L_j ≤ i < j，L_j = min{k: R_k = j}）。
//       lst = 最右的标记点（就是「从 i 两步内能到的最右位置」），cnt = 标记点个数。
//       情况 1（lst == R_i）：右边没有更远的点能在两步内到达，
//            所有 j > R_i 都必须先走到 R_i，逐项相减得 dp_i = dp_{R_i} + (r-i-1)。
//       情况 2（lst > R_i）：x = lst，
//            dp_i = dp_x + 2(r-i) - 2 - c2，c2 = (i,x] 内恰好 2 步可达的个数
//                 = (R_i-i-1) 个夹在 i 与 R_i 之间的点
//                 + [R_{R_i} 存在]（两步右走）
//                 + (cnt-1)（所有标记点去掉 R_i 自己，R_i 是 1 步）
//                 - 重复计数（R_{R_i} 本身也被标记时）。
//            排除单元素区间那类重复的办法是：先查 x = mid-1 再放 R_i 进集合（这里对应先剔除再恢复）。
//  4) 复杂度 O(n)。
#include <bits/stdc++.h>
using namespace std;

static const int MAXN = 1000005;

int n;
int p[MAXN];
int Rj[MAXN]; // R[i]：右边第一个比 p[i] 大的位置，不存在记 n+1
int Lj[MAXN]; // L[j]：满足 R[k] = j 的最小 k，不存在记 n+1
long long dp[MAXN];
unsigned char mk[MAXN];    // 标记数组
int head[MAXN], nxt[MAXN]; // 桶链表：L[j]==k 的 j 串在 head[k] 上
int stk[MAXN];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        cin >> n;
        for (int i = 1; i <= n; i++)
            cin >> p[i];

        // 单调栈求右边第一个更大值（从右往左扫）
        int top = 0;
        for (int i = n; i >= 1; i--) {
            while (top > 0 && p[stk[top - 1]] < p[i])
                top--;
            Rj[i] = (top > 0) ? stk[top - 1] : n + 1;
            stk[top++] = i;
        }

        // L[j] = min{k : R[k] = j}：k 从大到小写，后写的更小
        for (int j = 1; j <= n + 1; j++)
            Lj[j] = n + 1;
        for (int k = n; k >= 1; k--)
            Lj[Rj[k]] = k;

        // 桶链表 + 清空标记
        for (int k = 1; k <= n; k++)
            head[k] = 0;
        for (int j = 1; j <= n; j++) {
            mk[j] = 0;
            if (Lj[j] <= n) {
                nxt[j] = head[Lj[j]];
                head[Lj[j]] = j;
            }
        }

        long long total = 0;
        int l = 1;
        for (int r = 1; r <= n; r++) {
            if (Rj[r] != n + 1)
                continue; // 只在这些位置收块
            // ---- 处理块 [l, r] ----
            dp[r] = r - l; // r 往左一步到块内每个点
            int lst = r, cnt = 0;
            if (Lj[r] <= n) {
                mk[r] = 1;
                cnt = 1;
            }
            for (int i = r - 1; i >= l; i--) {
                while (!mk[lst])
                    lst--; // lst = 最右标记点
                if (lst == Rj[i]) {
                    dp[i] = dp[Rj[i]] + (r - i - 1);
                } else {
                    int a = Rj[i];
                    int b = (a <= n) ? Rj[a] : n + 1; // R_{R_i}
                    int c2 = (a - i - 1) + (b <= n ? 1 : 0) + (cnt - 1);
                    if (b <= n && Lj[b] <= i)
                        c2--; // R_{R_i} 被重复计了一次
                    dp[i] = dp[lst] + 2LL * (r - i) - 2 - c2;
                }
                // 撤销 L[j] == i 的标记（这些点对更小的 i 不再「两步可达」）
                for (int j = head[i]; j != 0; j = nxt[j]) {
                    mk[j] = 0;
                    cnt--;
                }
                if (Lj[i] <= n) {
                    mk[i] = 1;
                    cnt++;
                }
            }
            // 块左侧的点每个恰好 1 步
            for (int i = l; i <= r; i++)
                total += dp[i] + (l - 1);
            l = r + 1;
        }
        cout << total << '\n';
    }
    return 0;
}
```

### 易错点

最右标记只表示“左跳后右跳”可到的最右点；在第一种情况中，连续右跳两次仍可能更远，不能直接把它称为所有两步路径的最右点。两步点计数中的 $b$ 要去重。

