```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    char task;
    cin >> task;
    if (task == 'A') {
        int value = 0;
        for (char c : string("2022"))
            value = value * 9 + (c - '0');
        cout << value << '\n';
    } else {
        int days[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
