```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    char task;
    cin >> task;
    if (task == 'A') {
        const string digits =
            "5686916124919823647759503875815861830379270588570991944686338516346707827689565614010094809128502533";
        int days[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        int answer = 0;
        for (int month = 1; month <= 12; month++)
            for (int day = 1; day <= days[month]; day++) {
                string target = "2023";
                target += char('0' + month / 10);
                target += char('0' + month % 10);
                target += char('0' + day / 10);
                target += char('0' + day % 10);
                int matched = 0;
                for (char c : digits)
                    if (matched < 8 && c == target[matched])
                        ++matched;
                answer += (matched == 8);
            }
        cout << answer << '\n';
    } else {
        const long long n = 23333333;
        const long double target = 11625907.5798L;
        long double bestDifference = 1e100L;
        long long answer = -1;
        for (long long x = 1; x * 2 < n; x++) {
            long double p = (long double)x / n, q = 1 - p;
            long double entropy = -x * p * log2l(p) - (n - x) * q * log2l(q);
            long double difference = fabsl(entropy - target);
            if (difference < bestDifference) {
                bestDifference = difference;
                answer = x;
            }
        }
        cout << answer << '\n';
    }
}
```

