```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string s;
    cin >> n >> s;
    long long left = 0, right = 0, value = 0;
    for (char c : s) {
        if (c == 'L')
            ++left;
        else {
            value += left;
            ++right;
        }
    }
    long long best = value;
    left = 0;
    for (char c : s) {
        if (c == 'L')
            ++left;
        else {
            --right;
            if (c == '?') {
                value += right - left;
                ++left;
                best = max(best, value);
            }
        }
    }
    cout << best << '\n';
}
```

