### 思路

把已复制点称为红点。红点间每条原边对应两条平行的“上下两层边”；红黑边对应两条汇到同一黑点的边；黑黑边是桥，必须保留。

每个红点连通块独立计算。设它向黑点连出的原边有 $b$ 条。在红点树中删若干边成森林，每个分块恰选一条红黑边作为连接两层的出口。若删了 $t$ 条红边，则选 $t+1$ 个出口，实际图中单留一层边的选择共 $2^{t+b-(t+1)}=2^{b-1}$ 种。

因此每个红块的答案为 $2^{b-1}$ 乘以“每个森林分块恰有一个出口”的方案数。树形 DP 维护当前根块无出口、有一个出口两个状态：初值 $g=1,f=d_v$，$d_v$ 为该点黑邻居数；合并孩子 $u$ 时，$g'=g(g_u+f_u)$、$f'=f(g_u+f_u)+gf_u$。块根取 $f$，最后把各块答案相乘。每轮重算 $O(n)$，总 $O(n^2)$、空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 998244353;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> adj(n);
    for (int i = 1, u, v; i < n; i++) {
        cin >> u >> v;
        --u;
        --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector<int> parent(n, -1), order{0};
    parent[0] = 0;
    for (size_t i = 0; i < order.size(); i++)
        for (int u : adj[order[i]])
            if (parent[u] < 0) {
                parent[u] = order[i];
                order.push_back(u);
            }
    vector<long long> power(n + 1, 1), f(n), g(n);
    for (int i = 1; i <= n; i++)
        power[i] = power[i - 1] * 2 % MOD;
    vector<int> boundary(n);
    vector<char> red(n);
    for (int step = 1; step < n; step++) {
        int x;
        cin >> x;
        red[x - 1] = true;
        long long answer = 1;
        for (int oi = n - 1; oi >= 0; --oi) {
            int v = order[oi];
            if (!red[v])
                continue;
            int d = 0;
            for (int u : adj[v])
                d += !red[u];
            g[v] = 1;
            f[v] = d;
            boundary[v] = d;
            for (int u : adj[v])
                if (parent[u] == v && u != v && red[u]) {
                    long long total = (g[u] + f[u]) % MOD;
                    long long nf = (f[v] * total + g[v] * f[u]) % MOD, ng = g[v] * total % MOD;
                    f[v] = nf;
                    g[v] = ng;
                    boundary[v] += boundary[u];
                }
            if (v == 0 || !red[parent[v]])
                answer = answer * f[v] % MOD * power[boundary[v] - 1] % MOD;
        }
        cout << answer << '\n';
    }
}
```

### 易错点

红红边最终是原点连原点、副本连副本。两个 DP 转移须同时用旧父状态。出口数按边计，一个点多个黑邻居是多个选择。块间答案相乘。只有 $n-1$ 次操作，不能假设所有点都会复制。

