### 思路

将正一格的保留标记记为 $y$，负一格的删除标记记为 $y$。于是格子的贡献统一为 $y-[\text{原数为负一}]$，目标变成一个零一矩阵的行和 $R_i=r_i+\text{该行负数个数}$、列和 $C_j=c_j+\text{该列负数个数}$。

先检查范围和总和。依次处理每行，选择剩余列需求最大的 $R_i$ 个不同列，各放一并将需求减一；若不够正需求列则无解。交换论证保证该贪心保留可行性。列需求在零至 $n$ 之间，每行用计数排序选择，时间与输出规模相同，均为 $O(n^2)$；最后将负数格的标记翻转还原。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<string> answer(n);
    vector<int> row(n), col(n);
    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        answer[i] = string(n, '0');
        for (int j = 0; j < n; j++)
            if (s[j] == '-') {
                ++row[i];
                ++col[j];
                answer[i][j] = '1';
            }
    }
    bool valid = true;
    long long sr = 0, sc = 0;
    for (int i = 0, x; i < n; i++) {
        cin >> x;
        row[i] += x;
        valid &= 0 <= row[i] && row[i] <= n;
        sr += row[i];
    }
    for (int j = 0, x; j < n; j++) {
        cin >> x;
        col[j] += x;
        valid &= 0 <= col[j] && col[j] <= n;
        sc += col[j];
    }
    if (!valid || sr != sc) {
        cout << "No\n";
        return 0;
    }
    vector<int> count(n + 1), position(n + 1), order(n);
    for (int i = 0; i < n; i++) {
        // 一次排出所有列，确保本行每列至多选择一次。
        fill(count.begin(), count.end(), 0);
        for (int x : col)
            ++count[x];
        position[0] = count[0];
        for (int x = 1; x <= n; x++)
            position[x] = position[x - 1] + count[x];
        for (int j = 0; j < n; j++)
            order[--position[col[j]]] = j;
        for (int k = n - row[i]; k < n; k++) {
            int j = order[k];
            if (col[j] == 0) {
                cout << "No\n";
                return 0;
            }
            --col[j];
            answer[i][j] ^= 1;
        }
    }
    for (int x : col)
        if (x) {
            cout << "No\n";
            return 0;
        }
    cout << "Yes\n";
    for (const string &s : answer)
        cout << s << '\n';
}
```

### 易错点

负数格变换后采用删除标记，输出时需要翻转。检查目标范围、行列总和以及最终剩余需求。每行只选互不相同的列，不能更新后重复选择。存在多个解，样例输出不要求逐字符相同。

