### 从零讲：位运算：把非负整数看成一组二进制开关

五写成二进制为 $0101_2$，三为 $0011_2$。同一列各代表一位：按位与 `&` 两边都为一才得一，按位或 `|` 任一为一就得一，按位异或 `^` 不同才为一。所以 $5\mathbin{\&}3=1$，$5\mathbin{|}3=7$，$5\mathbin{\oplus}3=6$。

![相同数值分别写成每一位，逐列计算与、或、异或](assets/foundations/bits.svg)

`1ULL << k` 把一移到第 $k$ 位。对非负无符号整数，`(mask >> k) & 1ULL` 读该位，`mask | (1ULL<<k)` 置一，`mask & ~(1ULL<<k)` 清零，`mask ^ (1ULL<<k)` 翻转。最低位编号为零。

```cpp
unsigned long long mask = 5;   // 第 0、2 位为一
bool has = (mask >> 2) & 1ULL; // true
mask |= 1ULL << 1;             // 变成 7
```

位移次数必须小于类型位宽，且不能为负；不要用普通 `1` 去移到超出 int 范围的位置。C++17 有符号负数右移和溢出的规则不适合直接套“乘除二的幂”，用明确范围的无符号数更容易保证行为。`^` 是异或，绝不是乘方。

逻辑与 `&&`、逻辑或 `||` 将整体条件视为真假，并会短路；按位 `&`、`|` 逐位计算，不会因此跳过右侧表达式。运算符优先级可能与直觉不同，写 `(mask & bit) != 0`，别省掉关键括号。

固定机器字内的一次位运算按 $O(1)$ 估算；枚举全部 $k$ 位状态仍有 $2^k$ 种，不能因为每次运算快就忽略状态数。`x & (x-1)` 对正无符号数清掉最低的一位；GCC 的 `__builtin_popcountll(x)` 统计一的数量，注意实参位宽与具体编译器支持。

<!-- reusable-foundations:end -->

### 思路

Lucas 定理把组合数拆成 $k$ 位上的小组合数之积。目标非零，所以每位都必须 $b_i\le a_i$。先用 Pascal 递推统计一位时各非零余数的次数 $c_r$，花 $O(p^2)$。

取模 $p$ 的原根 $g$，把非零余数写成 $g^t$，余数乘法就变成指数模 $p-1$ 相加。令多项式 $C_t=c_{g^t}$，所求即 $C(z)^k$ 在模 $z^{p-1}-1$ 下、第 $\log_gx$ 项的系数。

直接按二进制指数快速幂，用 NTT 做卷积、把次数按 $p-1$ 折回。每一位把平方和可选乘底数合成一次普通多项式乘积，长度取至少 $3(p-1)-2$，避免三次乘积发生循环混叠。时间 $O(p^2+p\log p\log k)$，空间 $O(p)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
const int MOD = 998244353;
int modular_power(int a, int e, int mod = MOD) {
    int result = 1;
    for (; e; e >>= 1, a = 1LL * a * a % mod)
        if (e & 1)
            result = 1LL * result * a % mod;
    return result;
}
struct Transform {
    int size, inverse_size;
    vector<int> reverse_index, roots;
    Transform(int length)
        : size(length), inverse_size(modular_power(length, MOD - 2)), reverse_index(length),
          roots(length) {
        for (int i = 1; i < size; i++)
            reverse_index[i] = (reverse_index[i >> 1] >> 1) | ((i & 1) ? size >> 1 : 0);
        for (int half = 1; half < size; half *= 2) {
            int step = modular_power(3, (MOD - 1) / (2 * half));
            roots[half] = 1;
            for (int j = 1; j < half; j++)
                roots[half + j] = 1LL * roots[half + j - 1] * step % MOD;
        }
    }
    void forward(vector<int> &a) {
        for (int i = 0; i < size; i++)
            if (i < reverse_index[i])
                swap(a[i], a[reverse_index[i]]);
        for (int half = 1; half < size; half *= 2)
            for (int begin = 0; begin < size; begin += 2 * half)
                for (int j = 0; j < half; j++) {
                    int u = a[begin + j], v = 1LL * a[begin + half + j] * roots[half + j] % MOD;
                    int plus = u + v, minus = u - v;
                    if (plus >= MOD)
                        plus -= MOD;
                    if (minus < 0)
                        minus += MOD;
                    a[begin + j] = plus;
                    a[begin + half + j] = minus;
                }
    }
    void inverse(vector<int> &a) {
        reverse(a.begin() + 1, a.end());
        forward(a);
        for (int &v : a)
            v = 1LL * v * inverse_size % MOD;
    }
};
vector<int> cyclic_power(vector<int> base, const string &exponent) {
    int m = base.size();
    vector<int> result = base;
    if (m == 1) {
        for (size_t i = 1; i < exponent.size(); i++) {
            result[0] = 1LL * result[0] * result[0] % MOD;
            if (exponent[i] == '1')
                result[0] = 1LL * result[0] * base[0] % MOD;
        }
        return result;
    }
    int length = 1;
    while (length < 3 * m - 2)
        length *= 2;
    Transform ntt(length);
    vector<int> frequency(length), buffer(length);
    copy(base.begin(), base.end(), frequency.begin());
    ntt.forward(frequency);
    for (size_t bit = 1; bit < exponent.size(); bit++) {
        fill(buffer.begin(), buffer.end(), 0);
        copy(result.begin(), result.end(), buffer.begin());
        ntt.forward(buffer);
        // 一次完成平方和可选的乘底数，普通乘积的次数小于三倍环长。
        for (int i = 0; i < length; i++) {
            buffer[i] = 1LL * buffer[i] * buffer[i] % MOD;
            if (exponent[bit] == '1')
                buffer[i] = 1LL * buffer[i] * frequency[i] % MOD;
        }
        ntt.inverse(buffer);
        fill(result.begin(), result.end(), 0);
        for (int i = 0; i < length; i++) {
            int &target = result[i % m];
            target += buffer[i];
            if (target >= MOD)
                target -= MOD;
        }
    }
    return result;
}
vector<int> count_answers(const string &exponent, int prime) {
    int order = prime - 1, remainder = order;
    vector<int> factors;
    for (int q = 2; q * q <= remainder; q++)
        if (remainder % q == 0) {
            factors.push_back(q);
            while (remainder % q == 0)
                remainder /= q;
        }
    if (remainder > 1)
        factors.push_back(remainder);
    int generator = 1;
    for (;; ++generator) {
        bool good = true;
        for (int q : factors)
            if (modular_power(generator, order / q, prime) == 1)
                good = false;
        if (good)
            break;
    }
    vector<int> logarithm(prime), base(order), row(prime);
    int value = 1;
    for (int i = 0; i < order; i++) {
        logarithm[value] = i;
        value = value * generator % prime;
    }
    row[0] = 1;
    for (int a = 0; a < prime; a++) {
        for (int b = a; b >= 1; --b) {
            row[b] += row[b - 1];
            if (row[b] >= prime)
                row[b] -= prime;
        }
        for (int b = 0; b <= a; b++)
            ++base[logarithm[row[b]]];
    }
    vector<int> coefficients = cyclic_power(base, exponent), answer(prime);
    value = 1;
    for (int i = 0; i < order; i++) {
        answer[value] = coefficients[i];
        value = value * generator % prime;
    }
    return answer;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string k;
    int p, x;
    cin >> k >> p >> x;
    cout << count_answers(k, p)[x] << '\n';
    return 0;
}
```

