### 思路

解析两行 range 的括号参数，缺少第三项时补一步长一，字母参数表示引用外层变量。外层最多约一百万次，逐次模拟；内层是一段等差数列，可用首项、步长和右端严格不含的规则求项数，再用首末项和乘项数除二累加。

正步长且首项小于终点时，项数为 $\lceil(b-a)/c\rceil$；负步长且首项大于终点时，项数为 $\lceil(a-b)/(-c)\rceil$；其余为空。末项为 $a+(t-1)c$，贡献 $(a+\text{末项})t/2$。总时间 $O(10^6)$、空间 $O(1)$，使用 64 位整数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using i64 = long long;
struct Argument {
    bool variable;
    i64 constant;
    i64 get(i64 outer) const { return variable ? outer : constant; }
};
vector<Argument> parse_range(const string &line) {
    size_t begin = line.find("range(") + 6, end = line.find(')', begin);
    string inside = line.substr(begin, end - begin);
    vector<string> tokens;
    string token;
    for (char c : inside) {
        if (c == ',') {
            tokens.push_back(token);
            token.clear();
        } else if (!isspace((unsigned char)c))
            token += c;
    }
    tokens.push_back(token);
    if (tokens.size() == 2)
        tokens.push_back("1");
    vector<Argument> result;
    for (const string &t : tokens) {
        bool variable = t.size() == 1 && islower((unsigned char)t[0]);
        result.push_back({variable, variable ? 0 : stoll(t)});
    }
    return result;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    getline(cin, line);
    auto outer = parse_range(line);
    getline(cin, line);
    auto inner = parse_range(line);
    i64 begin = outer[0].get(0), end = outer[1].get(0), step = outer[2].get(0), answer = 0;
    for (i64 i = begin; step > 0 ? i < end : i > end; i += step) {
        i64 a = inner[0].get(i), b = inner[1].get(i), c = inner[2].get(i), count = 0;
        if (c > 0 && a < b)
            count = (b - a + c - 1) / c;
        else if (c < 0 && a > b)
            count = (a - b - c - 1) / (-c);
        // 用等差数列一次求和，保留 Python range 严格不含终点的含义。
        if (count)
            answer += (2 * a + (count - 1) * c) * count / 2;
    }
    cout << answer << '\n';
}
```

### 易错点

range 终点严格不含，负步长与空区间都要处理。省略步长表示一。内层参数可能在起点、终点或步长处引用外层变量。用整行读取保留两行循环，变量名不固定。

