### 思路

把一种灯阵编码为四位整数，把仍未得到过全亮提示的可能灯阵集合编码为十六位整数 $S$。操作掩码为 $k$ 时，集合中每个灯阵 $u$ 变为 $u\oplus k$，再移除全亮状态十五。

反向从空集跑一次 Dijkstra。一个不含十五的目标集合 $T$，在操作 $k$ 之前的集合只有两个可能：把 $T$ 全部异或 $k$，或在此基础上再加入 $15\oplus k$。两条反边费用相同。有十五的状态不可能是操作后的状态，不向外扩展反边。预处理全部 $2^{16}$ 个集合后，各组直接查表；初始全亮也不能预先移除。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    array<long long, 4> cost;
    cin >> tests;
    for (auto &x : cost)
        cin >> x;
    vector<int> operation{1, 2, 4, 8, 3, 12, 5, 10, 15};
    vector<long long> weight{cost[0], cost[0], cost[0], cost[0], cost[1],
                             cost[1], cost[2], cost[2], cost[3]};
    constexpr int STATES = 1 << 16;
    vector<vector<unsigned>> permutation(9, vector<unsigned>(STATES));
    for (int k = 0; k < 9; k++)
        for (unsigned mask = 1; mask < STATES; mask++) {
            unsigned bit = mask & -mask;
            permutation[k][mask] =
                permutation[k][mask ^ bit] | (1u << (__builtin_ctz(bit) ^ operation[k]));
        }
    const long long INF = 1LL << 60;
    vector<long long> distance(STATES, INF);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>,
                   greater<pair<long long, int>>>
        q;
    distance[0] = 0;
    q.emplace(0, 0);
    while (!q.empty()) {
        auto [d, state] = q.top();
        q.pop();
        if (d != distance[state] || (state & (1 << 15)))
            continue;
        for (int k = 0; k < 9; k++) {
            unsigned base = permutation[k][state], completed = 1u << (15 ^ operation[k]);
            // 操作前可能没有新成功的状态，也可能多出本轮刚变全亮的一个。
            for (unsigned previous : {base, base | completed})
                if (d + weight[k] < distance[previous]) {
                    distance[previous] = d + weight[k];
                    q.emplace(distance[previous], previous);
                }
        }
    }
    while (tests--) {
        int m;
        cin >> m;
        unsigned state = 0;
        while (m--) {
            string a, b;
            cin >> a >> b;
            int grid = 0;
            for (char c : a + b)
                grid = grid * 2 + c - '0';
            state |= 1u << grid;
        }
        cout << distance[state] << '\n';
    }
}
```

### 易错点

全亮初态必须真的操作后再次全亮才算成功。只删除本轮操作后的全亮状态。九个具体掩码的费用按四类分别对应，行列费用不能混淆。空行用字符串流提取自然跳过。

