### 思路

每条合法路径对应一个零一系数向量，表示它经过了哪些未知点，根点的已知零直接删去。枚举全部合法路径，用异或消元选出线性无关的向量。

若秩小于 $n-1$，即便问完所有合法路径也有不同点权给出同样回答，应直接输出 No。否则选出的 $n-1$ 条独立路径已足够，在一份询问包中全部输出，读取回答后对同一系数矩阵消元、回代。回答的三十位可作为一个整数共同异或，时间 $O(n^3+n^4/64)$，空间 $O(n^2/64+n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using Bits = bitset<250>;
int main() {
    int n, k;
    cin >> n >> k;
    vector<vector<int>> g(n);
    for (int i = 1, u, v; i < n; i++) {
        cin >> u >> v;
        --u;
        --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    int variables = n - 1;
    vector<Bits> basis(variables), original;
    vector<pair<int, int>> queries;
    for (int source = 0; source < n && int(queries.size()) < variables; source++) {
        vector<int> parent(n, -1), distance(n);
        queue<int> q;
        q.push(source);
        parent[source] = source;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : g[u])
                if (parent[v] < 0) {
                    parent[v] = u;
                    distance[v] = distance[u] + 1;
                    q.push(v);
                }
        }
        for (int target = source + 1; target < n && int(queries.size()) < variables; target++)
            if (distance[target] == k) {
                Bits row;
                for (int u = target;; u = parent[u]) {
                    if (u)
                        row.set(u - 1);
                    if (u == source)
                        break;
                }
                Bits reduced = row;
                for (int pivot = variables - 1; pivot >= 0; --pivot)
                    if (reduced[pivot]) {
                        if (basis[pivot].any())
                            reduced ^= basis[pivot];
                        else {
                            basis[pivot] = reduced;
                            original.push_back(row);
                            queries.emplace_back(source, target);
                            break;
                        }
                    }
            }
    }
    if (int(queries.size()) < variables) {
        cout << "No" << endl;
        return 0;
    }
    cout << "Yes" << endl;
    cout << "? " << queries.size();
    for (auto [u, v] : queries)
        cout << ' ' << u + 1 << ' ' << v + 1;
    cout << endl;
    fill(basis.begin(), basis.end(), Bits{});
    vector<int> right(variables);
    for (int i = 0; i < variables; i++) {
        int value;
        if (!(cin >> value) || value < 0)
            return 0;
        Bits row = original[i];
        for (int pivot = variables - 1; pivot >= 0; --pivot)
            if (row[pivot]) {
                if (basis[pivot].any()) {
                    row ^= basis[pivot];
                    value ^= right[pivot];
                } else {
                    basis[pivot] = row;
                    right[pivot] = value;
                    break;
                }
            }
    }
    // 主元是行内最高位，所以从低位开始回代，三十个权值位一起异或。
    vector<int> answer(variables);
    for (int i = 0; i < variables; i++) {
        answer[i] = right[i];
        for (int j = 0; j < i; j++)
            if (basis[i][j])
                answer[i] ^= answer[j];
    }
    cout << '!';
    for (int value : answer)
        cout << ' ' << value;
    cout << endl;
}
```

### 易错点

路径长度按边数，异或按点权且包含端点。根点是已知零，不能当额外未知变量。No 时不能发询问。所有问题必须一次性打包输出后再读回答，遇到负数回答应停止。

