### 思路

若可配对，最小值必须和最大值配对，公共和为 $s=\min+\max$；整个多重集合应在映射 $a\mapsto s-a$ 下不变。维护指数哈希

$$H_+=\sum b^{a_i},\qquad H_-=\sum b^{-a_i},$$

以 $H_+=b^sH_-$ 检查这种对称。区间加 $v$ 时，两者分别乘 $b^v,b^{-v}$，可用懒标记线段树维护，同时维护最小值、最大值、元素和。先用 $2\sum a_i=s\cdot\text{长度}$ 排除显然不合法的区间。

代码在素数 $2^{61}-1$ 下取两个随机底数，双哈希降低误判概率；它是有极小碰撞风险的随机算法。更新值范围有限，可预处理四张幂表；查询另做快速幂。时间 $O(V_0+(n+q)\log n+q\log V)$，空间 $O(n+V_0)$，其中 $V_0=200000$，$V$ 是当前最大值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;
using ll = long long;
const ull MOD = (1ULL << 61) - 1;
const int MAXV = 200000;
using Hash = array<ull, 4>;
ull addMod(ull a, ull b) {
    ull s = a + b;
    return s >= MOD ? s - MOD : s;
}
ull multiply(ull a, ull b) {
    __uint128_t z = (__uint128_t)a * b;
    ull result = ((ull)z & MOD) + (ull)(z >> 61);
    return result >= MOD ? result - MOD : result;
}
ull power(ull a, ull e) {
    ull result = 1;
    for (; e; e >>= 1, a = multiply(a, a))
        if (e & 1)
            result = multiply(result, a);
    return result;
}
struct Data {
    Hash hash{};
    ll minimum = LLONG_MAX, maximum = LLONG_MIN, sum = 0;
};
Data mergeData(const Data &a, const Data &b) {
    Data result;
    for (int j = 0; j < 4; j++)
        result.hash[j] = addMod(a.hash[j], b.hash[j]);
    result.minimum = min(a.minimum, b.minimum);
    result.maximum = max(a.maximum, b.maximum);
    result.sum = a.sum + b.sum;
    return result;
}
struct Node {
    Data data;
    Hash factor{1, 1, 1, 1};
    ll addition = 0;
};
struct SegmentTree {
    int n;
    vector<Node> tree;
    array<vector<ull>, 4> powers;
    array<ull, 2> base;
    SegmentTree(const vector<int> &a) : n((int)a.size() - 1), tree(4 * n + 8) {
        random_device rd;
        mt19937_64 generator(((ull)rd() << 32) ^ rd() ^
                             (ull)chrono::steady_clock::now().time_since_epoch().count());
        uniform_int_distribution<ull> choose(2, MOD - 2);
        base = {choose(generator), choose(generator)};
        Hash roots = {base[0], power(base[0], MOD - 2), base[1], power(base[1], MOD - 2)};
        for (int j = 0; j < 4; j++) {
            powers[j].resize(MAXV + 1);
            powers[j][0] = 1;
            for (int v = 1; v <= MAXV; v++)
                powers[j][v] = multiply(powers[j][v - 1], roots[j]);
        }
        build(1, 1, n, a);
    }
    void build(int p, int l, int r, const vector<int> &a) {
        if (l == r) {
            for (int j = 0; j < 4; j++)
                tree[p].data.hash[j] = powers[j][a[l]];
            tree[p].data.minimum = tree[p].data.maximum = tree[p].data.sum = a[l];
            return;
        }
        int middle = (l + r) / 2;
        build(p * 2, l, middle, a);
        build(p * 2 + 1, middle + 1, r, a);
        pull(p);
    }
    void pull(int p) { tree[p].data = mergeData(tree[p * 2].data, tree[p * 2 + 1].data); }
    void apply(int p, int length, ll value, const Hash &factor) {
        auto &node = tree[p];
        for (int j = 0; j < 4; j++) {
            node.data.hash[j] = multiply(node.data.hash[j], factor[j]);
            node.factor[j] = multiply(node.factor[j], factor[j]);
        }
        node.data.minimum += value;
        node.data.maximum += value;
        node.data.sum += value * length;
        node.addition += value;
    }
    void push(int p, int l, int r) {
        if (!tree[p].addition)
            return;
        int middle = (l + r) / 2;
        apply(p * 2, middle - l + 1, tree[p].addition, tree[p].factor);
        apply(p * 2 + 1, r - middle, tree[p].addition, tree[p].factor);
        tree[p].addition = 0;
        tree[p].factor = {1, 1, 1, 1};
    }
    void update(int p, int l, int r, int L, int R, int value, const Hash &factor) {
        if (L <= l && r <= R) {
            apply(p, r - l + 1, value, factor);
            return;
        }
        push(p, l, r);
        int middle = (l + r) / 2;
        if (L <= middle)
            update(p * 2, l, middle, L, R, value, factor);
        if (R > middle)
            update(p * 2 + 1, middle + 1, r, L, R, value, factor);
        pull(p);
    }
    void update(int l, int r, int value) {
        if (!value)
            return;
        Hash factor;
        for (int j = 0; j < 4; j++)
            factor[j] = powers[j][value];
        update(1, 1, n, l, r, value, factor);
    }
    Data query(int p, int l, int r, int L, int R) {
        if (L <= l && r <= R)
            return tree[p].data;
        push(p, l, r);
        int middle = (l + r) / 2;
        if (R <= middle)
            return query(p * 2, l, middle, L, R);
        if (L > middle)
            return query(p * 2 + 1, middle + 1, r, L, R);
        return mergeData(query(p * 2, l, middle, L, R), query(p * 2 + 1, middle + 1, r, L, R));
    }
    bool possible(int l, int r) {
        Data d = query(1, 1, n, l, r);
        ll sumOfPair = d.minimum + d.maximum;
        if (d.sum * 2 != sumOfPair * (r - l + 1LL))
            return false;
        for (int j = 0; j < 2; j++)
            if (d.hash[j * 2] != multiply(power(base[j], sumOfPair), d.hash[j * 2 + 1]))
                return false;
        return true;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++)
        cin >> a[i];
    SegmentTree tree(a);
    while (q--) {
        int type, l, r;
        cin >> type >> l >> r;
        if (type == 1) {
            int v;
            cin >> v;
            tree.update(l, r, v);
        } else
            cout << (tree.possible(l, r) ? "YES\n" : "NO\n");
    }
}
```

### 易错点

区间长度保证为偶数，仍要比较出现次数而非不同值集合。负指数使用乘法逆元。懒加数下推时，四个哈希乘法因子必须一起传递并重置。模乘不能直接用六十四位相乘后取模。双哈希仍是概率判定。

参考：[资料 1](https://contest.ucup.ac/contest/1873?v=1)、[资料 2](https://contest.ucup.ac/download.php?id=1873&r=1&type=attachments)。代码与讲解为独立编写。

## L. Z-order Curve

[题目](https://codeforces.com/gym/105632/problem/L)

### 题意

把自然数的二进制偶数位、奇数位分别抽出来作为平面横纵坐标，顺序连线得到 Z 曲线。给定有向片段 $[L,R]$，求平移后与它相同的片段最早从哪个编号开始。$R\le10^{18}$。

<!-- reusable-foundations:start -->

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cpp
int a = 100000, b = 100000;
long long wrong = a * b;       // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

### 从零讲：位运算：把非负整数看成一组二进制开关

五写成二进制为 $0101_2$，三为 $0011_2$。同一列各代表一位：按位与 `&` 两边都为一才得一，按位或 `|` 任一为一就得一，按位异或 `^` 不同才为一。所以 $5\mathbin{\&}3=1$，$5\mathbin{|}3=7$，$5\mathbin{\oplus}3=6$。

![相同数值分别写成每一位，逐列计算与、或、异或](assets/foundations/bits.svg)

`1ULL << k` 把一移到第 $k$ 位。对非负无符号整数，`(mask >> k) & 1ULL` 读该位，`mask | (1ULL<<k)` 置一，`mask & ~(1ULL<<k)` 清零，`mask ^ (1ULL<<k)` 翻转。最低位编号为零。

```cpp
unsigned long long mask = 5;   // 第 0、2 位为一
bool has = (mask >> 2) & 1ULL; // true
mask |= 1ULL << 1;             // 变成 7
```

位移次数必须小于类型位宽，且不能为负；不要用普通 `1` 去移到超出 int 范围的位置。C++17 有符号负数右移和溢出的规则不适合直接套“乘除二的幂”，用明确范围的无符号数更容易保证行为。`^` 是异或，绝不是乘方。

逻辑与 `&&`、逻辑或 `||` 将整体条件视为真假，并会短路；按位 `&`、`|` 逐位计算，不会因此跳过右侧表达式。运算符优先级可能与直觉不同，写 `(mask & bit) != 0`，别省掉关键括号。

固定机器字内的一次位运算按 $O(1)$ 估算；枚举全部 $k$ 位状态仍有 $2^k$ 种，不能因为每次运算快就忽略状态数。`x & (x-1)` 对正无符号数清掉最低的一位；GCC 的 `__builtin_popcountll(x)` 统计一的数量，注意实参位宽与具体编译器支持。

<!-- reusable-foundations:end -->

### 思路

从最高位开始比较 $L,R$。相同的高位只决定整个片段的共同平移，可以清掉；遇到第一处不同就停止。设最高不同位为 $p$，答案为

$$L\bmod 2^{p+1}.$$

这处不同位使片段经过一次“进位到第 $p$ 位”的跳跃。相同有向片段必须在相同相对位置出现同样的跳跃，不能再把起点左移到更小编号。用异或求最高不同位，再保留下面的位即可。每组 $O(\log R)$ 时间、$O(1)$ 空间。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        ull L, R;
        cin >> L >> R;
        ull different = L ^ R, limit = 1;
        while (limit <= different)
            limit <<= 1;
        cout << (L & (limit - 1)) << '\n';
    }
}
```

### 易错点

曲线带方向，不能把反向走或旋转也视为相同。遇到最高不同位就停止，不能继续清掉后面偶然相同的位。用六十四位整数处理掩码和输入。

参考：[资料 1](https://contest.ucup.ac/contest/1873?v=1)、[资料 2](https://contest.ucup.ac/download.php?id=1873&r=1&type=attachments)。代码与讲解为独立编写。

## M. Rejection Sampling

[题目](https://codeforces.com/gym/105632/problem/M)

### 题意

独立地以概率 $p_i$ 选择每个元素，只在恰好选中 $k$ 个时接受，否则重试。要求输出每个大小为 $k$ 的集合的概率正比于集合权值乘积，并且 $\sum p_i=k$。求所有选择概率，允许绝对误差 $10^{-6}$。

<!-- reusable-foundations:start -->

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cpp
vector<int> a(3, 7); // 三个元素，内容是 7、7、7
a.push_back(9);      // 在末尾追加，现在长度为 4
int x = a[1];        // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

<!-- reusable-foundations:end -->

### 思路

一次尝试恰好选中 $S$ 的概率为

$$\prod_i(1-p_i)\prod_{i\in S}\frac{p_i}{1-p_i}.$$

所以令所有概率的赔率满足 $p_i/(1-p_i)=a_i/t$，就使同样大小集合的概率正比于权值乘积，得到 $p_i=a_i/(a_i+t)$。

当 $t>0$ 增大时，$\sum a_i/(a_i+t)$ 连续严格递减，由 $n$ 降到零，因此有唯一值令它等于 $k$。在 $[0,10^{14}]$ 二分一百次，输出各概率即可。时间 $O(100n)$，空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<long double> a(n);
    for (auto &x : a)
        cin >> x;
    long double low = 0, high = 1e14L;
    for (int round = 0; round < 100; round++) {
        long double middle = (low + high) / 2, sum = 0;
        for (auto x : a)
            sum += x / (x + middle);
        if (sum > k)
            low = middle;
        else
            high = middle;
    }
    long double t = (low + high) / 2;
    cout << fixed << setprecision(12);
    for (auto x : a)
        cout << x / (x + t) << '\n';
}
```

### 易错点

不能令概率直接与权值成正比，应该令赔率与权值成正比。二分的参数增大时概率和减小。固定很少次二分可能无法覆盖跨度，代码使用一百次并保留足够输出位数。

参考：[资料 1](https://contest.ucup.ac/contest/1873?v=1)、[资料 2](https://contest.ucup.ac/download.php?id=1873&r=1&type=attachments)。代码与讲解为独立编写。

## A. AUS

[题目](https://codeforces.com/gym/105657/problem/A)

### 题意

用同一个小写字母映射函数逐字符加密三个串，判断能否使前两串加密后相等，同时与第三串加密后的结果不同。映射不要求一一对应。

<!-- reusable-foundations:start -->

### 从零讲：并查集：维护哪些对象已属于同一组

从每个元素独立成组开始，反复合并两组、判断两项是否连通。并查集用父指针形成若干棵树，每棵树的根代表一组；根的编号只是代表，不一定是最小编号或有特殊题意。

![合并两个根后，同组元素沿父指针到达同一代表；路径压缩缩短后续查找](assets/foundations/dsu.svg)

```cpp
struct DSU {
    vector<int> parent, size;
    DSU(int n) : parent(n), size(n, 1) { iota(parent.begin(), parent.end(), 0); }
    int find(int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); }
    bool merge(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
};
```

合并 $0,1$ 再合并 $1,2$ 后，三者的 `find` 相同，即使零和二没有直接边。这表示路径连通，不表示两项相邻。路径压缩将访问链上的父亲直接改为根；按大小合并把小树挂到大树，避免人为形成长链。

初始化 $O(n)$，两种优化一起使用时，一连串操作的摊还成本为 $O(\alpha(n))$ 每次，常见规模近似常数；不能说每一次都严格 $O(1)$。数组空间 $O(n)$。

普通并查集擅长增加连通关系，不直接支持删边和拆组。回滚版本通常不用路径压缩，并保存每次合并改变的值；带权版本还需维护到父亲的关系，不能只合并普通 parent。分组大小等统计应读根上的记录。

### 从零讲：lambda：定义、捕获和调用一个局部函数

#### 它解决什么问题

一段操作在当前函数里需要调用多次，或者某个算法需要你提供“怎样比较”的规则，可以把这段操作写成 lambda。lambda 表达式产生一个可以像函数一样调用的对象；“匿名”指它没有普通函数声明中的函数名，仍可以用变量保存并命名。

```cpp
auto add = [](int a, int b) -> int { return a + b; };
int answer = add(2, 3); // 调用后得到 5；定义本身不会执行函数体
```

读法是：用 `auto` 保存对象；`[]` 是捕获列表；圆括号是每次调用传入的参数；`-> int` 指定返回类型；花括号里写执行过程；定义后的分号结束赋值。返回类型能够推导时可省略，所以也常见 `auto add = [](int a,int b) { return a+b; };`。

![参数在调用时传入，捕获连接定义位置可见的外部变量](assets/foundations/lambda.svg)

#### 参数和捕获有什么区别

参数每次调用都由调用者提供；捕获让函数体使用定义位置附近的局部变量，调用时不用重复传它。例如阈值来自当前环境，待判断的值每次变化：

```cpp
int threshold = 10;
auto enough = [threshold](int value) { return value >= threshold; };
bool a = enough(12); // true，value 是本次传入的 12
```

这里 `threshold` 是捕获，`value` 是参数。常用的捕获方式如下：

| 写法 | 意思 | 适合的需要 |
|---|---|---|
| `[]` | 不捕获局部变量 | 只依赖参数的计算或比较 |
| `[x]` | 保存定义时 `x` 的副本 | 需要固定一份快照 |
| `[&x]` | 引用外面的 `x` | 读取最新值或修改原变量 |
| `[=]` | 按值捕获实际需要的局部变量 | 需要多个快照 |
| `[&]` | 按引用捕获实际需要的局部变量 | 当前作用域内的辅助函数 |
| `[&a, limit]` | 引用 `a`，复制 `limit` | 显式区分共享数据和快照 |

`[&]` 不是“把参数按引用传递”；是否按引用传参由圆括号里的 `int&`、`const vector<int>&` 等类型决定。全局变量可以直接访问，无需捕获。

#### 用可观察的结果区分复制与引用

```cpp
int base = 10;
auto snapshot = [base](int x) { return base + x; };
auto current = [&base](int x) { return base + x; };
base = 20;
int a = snapshot(1); // 11：使用定义时保存的 10
int b = current(1);  // 21：使用外面的最新值 20
```

默认情况下不能在 lambda 内修改按值捕获的副本。加 `mutable` 才能修改副本，但仍不会改外面的原变量：`auto next = [base]() mutable { return ++base; };`。对大数组按值捕获可能复制整个数组；如果只在数组仍然存活时查询，显式引用可避免这份复制。

#### 两种常见用法

**局部辅助函数。** 把“给一个参数就求出结果”的操作命名后，主流程只写调用。外层数组保持原处，辅助函数按引用读取，能减少重复代码，并让环境依赖集中在定义附近。对多个调用位置修正一处逻辑即可。普通独立函数也能做到复用，但外层局部数据通常需要显式传参。

**作为算法的规则。** 把比较方式直接交给 `sort`，能在调用处看到排序依据：

```cpp
sort(items.begin(), items.end(), [](const auto &a, const auto &b) {
    if (a.first != b.first)
        return a.first < b.first;
    return a.second > b.second;
});
```

先按第一项升序，第一项相同时按第二项降序。比较器必须形成严格弱序，同一个元素与自己比较应为假；写成 `<=` 可能破坏排序前提。传 `const auto&` 可以避免每次比较都复制元素。

#### 递归时怎样引用自己

在 `auto f = ...` 的初始化表达式中不能直接假定 `f` 的类型已确定。C++17 可以把自己作为参数传进去：

```cpp
auto factorial = [](auto &&self, int n) -> long long {
    if (n <= 1)
        return 1;
    return n * self(self, n - 1);
};
long long value = factorial(factorial, 5); // 120
```

也可先声明 `std::function<long long(int)> f` 再赋 lambda，通过引用调用 `f`；需要 `<functional>`。`std::function` 用统一类型包装可调用对象，便于存储和传递，但可能有间接调用、分配等额外开销。只在当前地方使用时，`auto` 常更直接。这些是组织代码的选择，不会改变原算法的复杂度。

#### 生命周期和复杂度

引用捕获不会延长被引用变量的生命。把引用局部数组的 lambda 返回到函数外，局部数组已经销毁，再调用就会访问失效对象；放入异步任务或长久保存时，也须检查这一点。必要时捕获一份拥有数据的副本，或设计明确的共享所有权。

调用一次 lambda 的时间取决于函数体：内部扫描 $n$ 个元素就是 $O(n)$，做两次有序数组二分就是 $O(\log n)$。创建时复制大容器还会有与数据量相关的成本。lambda 的优势是局部表达、复用和传递行为，本身不保证运行更快。

规范核对：[C++ 工作草案：捕获](https://eel.is/c++draft/expr.prim.lambda.capture)、[函数对象](https://eel.is/c++draft/function.objects)。示例均为 C++17 写法。

### 从零讲：string：字符、下标与子串

`string` 保存字符序列。`string s="abca";` 的长度为四，下标从零开始，`s[0]=='a'`、`s[3]=='a'`。字符用单引号，字符串用双引号；二者类型不同。需要 `<string>`。

`cin >> s` 读到空白停止；整行含空格时使用 `getline`，并留意前一次格式化输入残留的换行。`s.size()` 是字符单元数量，不一定等于 UTF-8 中文字数；竞赛英文小写字母题通常一个字符对应一个单元。

```cpp
string s = "abca";
string middle = s.substr(1, 2); // 从下标 1 开始取 2 个字符，得到 bc
size_t pos = s.find('c');       // 得到 2；找不到是 string::npos
if (pos != string::npos)
    cout << s[pos];
```

`substr(start,length)` 的第二项是长度，不是右端点。普通下标访问为 $O(1)$；复制长为 $k$ 的子串需要 $O(k)$ 时间和空间，循环里反复截取可能累积成平方成本。字符串比较按第一个不同字符决定字典序，公共前缀可能需要线性比较。

常见字符转数字是 `c-'0'`，前提 `c` 在 `'0'` 到 `'9'`。修改原串可用 `for(char& c:s)`，只读使用 `char c`。`reverse(s.begin(),s.end())` 原地翻转；若还需要原串，应先复制。空串不能访问首尾，尾后位置不能当普通字符读取。

### 从零讲：数值工具：连续编号、累加与最值

这些工具分别处理“填连续编号”“合并数值”“比较候选”，使用前要看返回类型和范围。`iota`、`accumulate` 在 `<numeric>`，`min`、`max` 在 `<algorithm>`。

```cpp
vector<int> id(4);
iota(id.begin(), id.end(), 0); // 0、1、2、3，容器本来就要有 4 项
vector<int> a{1000000000, 1000000000, 1000000000};
long long sum = accumulate(a.begin(), a.end(), 0LL); // 3000000000
int best = max(3, 7);                                // 返回 7，不会修改原参数
```

`accumulate` 的初始值决定累加器类型；写零会先按 `int` 累加，即使最终接收变量是 `long long` 也来不及修复溢出。`min`、`max` 的候选通常应为同一类型；更新变量须写 `best=max(best,candidate)`，只调用 `max` 不会自动赋值。

`fill(a.begin(),a.end(),value)` 给每个已有元素赋值，时间 $O(n)$。`memset` 逐字节填充，不适合填任意整数一或大哨兵；用 `fill` 更能直接表达意图。初始化一个长为 $n$ 的数组也需要 $O(n)$，把它放进每轮循环可能成为主要耗时。

极大或极小哨兵要与合法答案范围区分，并给后续加法留下余地。若不可达值为 `INF`，不能不检查就算 `INF+weight`；计数题、最短路和最大值问题的初值含义不同，应从“尚未选任何东西”或“尚未到达”的状态推出来。

<!-- reusable-foundations:end -->

### 思路

前两串长度不同则无解；它们等长、第三串长度不同则一定有解。剩下三个串等长时，为使前两串加密后相等，每个相同位置的两个字符必须映射为同一个字母，使用并查集合并这些等价关系。

若第三串每个位置的字符都与第一串对应字符在同一集合中，就被迫相同，无解；只要有一处不在同一集合，让不同集合映射为不同字母即可有解。时间与总串长线性相关，额外空间 $O(26)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        string a, b, c;
        cin >> a >> b >> c;
        if (a.size() != b.size()) {
            cout << "NO\n";
            continue;
        }
        if (a.size() != c.size()) {
            cout << "YES\n";
            continue;
        }
        array<int, 26> parent;
        iota(parent.begin(), parent.end(), 0);
        auto find = [&](int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };
        for (int i = 0; i < (int)a.size(); i++)
            parent[find(a[i] - 'a')] = find(b[i] - 'a');
        bool possible = false;
        // 不同等价类可以选不同密文字母，从而制造一个不相同的位置。
        for (int i = 0; i < (int)a.size(); i++)
            if (find(a[i] - 'a') != find(c[i] - 'a'))
                possible = true;
        cout << (possible ? "YES" : "NO") << '\n';
    }
}
```

### 易错点

映射不是排列，不同原字符允许映到相同字母。等价关系需要传递，不能只检查每对字符是否曾直接出现。

