### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
struct SegmentTree {
    static constexpr int V = 1000000;
    int base = 1;
    vector<int> odd, even;
    SegmentTree() {
        while (base < V)
            base *= 2;
        odd.resize(2 * base);
        even.resize(2 * base);
    }
    int query(const vector<int> &tree, int left, int right) {
        left = max(left, 1);
        right = min(right, V);
        if (left > right)
            return 0;
        int answer = 0, l = left - 1 + base, r = right + base;
        while (l < r) {
            if (l & 1)
                answer = max(answer, tree[l++]);
            if (r & 1)
                answer = max(answer, tree[--r]);
            l /= 2;
            r /= 2;
        }
        return answer;
    }
    void update(int value, int newOdd, int newEven) {
        int p = value - 1 + base;
        odd[p] = max(odd[p], newOdd);
        even[p] = max(even[p], newEven);
        for (p /= 2; p; p /= 2) {
            odd[p] = max(odd[p * 2], odd[p * 2 + 1]);
            even[p] = max(even[p * 2], even[p * 2 + 1]);
        }
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k1, k2;
    cin >> n >> k1 >> k2;
    SegmentTree tree;
    int answer = 0;
    for (int i = 0, x; i < n; i++) {
        cin >> x;
        int newOdd = 1 + tree.query(tree.even, x - k1, x + k1);
        int previousOdd =
            max(tree.query(tree.odd, 1, x - k2), tree.query(tree.odd, x + k2, SegmentTree::V));
        int newEven = previousOdd ? previousOdd + 1 : 0;
        // 两种状态都查完后才加入当前元素，避免同一位置被重复使用
        tree.update(x, newOdd, newEven);
        answer = max({answer, newOdd, newEven});
    }
    cout << answer << '\n';
}
```

### 易错点

第一个被接出的第二项用“至少 $k_2$”，不是“至多 $k_1$”。新奇、偶状态的查询必须都在更新之前完成。同末值要分别保留两种奇偶；空旧奇数状态不能生成长度一的偶数状态。

