        vector<i64> cost(n + 2);
        for (int i = 1; i <= n; i++)
            cin >> cost[i];
        string middle;
        cin >> middle;
        string required = "1" + middle + "1";
        vector<i64> prefix(n + 2), suffix(n + 2), skip(n + 2, -1);
        deque<int> q;
        q.push_back(0);
        for (int i = 1; i <= n + 1; i++) {
            while (q.front() < i - k)
                q.pop_front();
            prefix[i] = cost[i] + prefix[q.front()];
            if (required[i] == '1')
                q.clear();
            while (!q.empty() && prefix[q.back()] >= prefix[i])
                q.pop_back();
            q.push_back(i);
        }
        q.clear();
        q.push_back(n + 1);
        for (int i = n; i >= 0; --i) {
            while (q.front() > i + k)
                q.pop_front();
            suffix[i] = cost[i] + suffix[q.front()];
            if (required[i] == '1')
                q.clear();
            while (!q.empty() && suffix[q.back()] >= suffix[i])
                q.pop_back();
            q.push_back(i);
        }
        vector<int> left(n + 2), right(n + 2);
        int last = 0;
        for (int i = 1; i <= n; i++) {
            left[i] = last;
            if (required[i] == '1')
                last = i;
        }
        last = n + 1;
        for (int i = n; i >= 1; --i) {
            right[i] = last;
            if (required[i] == '1')
                last = i;
        }
        int queries;
        cin >> queries;
        while (queries--) {
            int p;
            i64 value;
            cin >> p >> value;
            i64 answer = prefix[p] + suffix[p] - 2 * cost[p] + value;
            if (required[p] == '0') {
                if (skip[p] == -1) {
                    i64 best_right = INF;
                    skip[p] = INF;
                    int j = p;
                    for (int i = max(left[p], p - k + 1); i < p; i++) {
                        int limit = min(right[p], i + k);
                        while (j < limit) {
                            ++j;
                            best_right = min(best_right, suffix[j]);
                        }
                        skip[p] = min(skip[p], prefix[i] + best_right);
                    }
                }
                answer = min(answer, skip[p]);
            }
            cout << answer << '\n';
        }
    }
}
```

### 易错点

查询互相独立，不写回原数组。$F_p,G_p$ 各包含一份旧价，减两份后加一次新价。必选点算完状态再清队列。跳过时同时满足距离与中间无必选点。

