### 从零讲：DP 入门 —— 把「所有可能的操作序列」数成一格一格的状态

计数 DP 合并对所统计事件具有相同后续影响的历史。例如只关心队列已弹出数时，两段历史虽有不同栈内容，下一步操作一或二都会让已弹出数增加一，操作三不影响它，因此可以合并。若改为追踪某个栈元素能否弹出，就还需记录它上方有多少元素。状态应保留决定目标事件的全部信息，而不必保留整个容器。多个操作到同一状态仍分别累加，因为它们是不同操作序列。

### 思路

把总分按元素拆开：每个 $a_{i+1}$ 只在从队列取出那一步决定直接进入集合或压栈。令 $fp[t][i]$ 为前 $t-1$ 步已从队列取出 $i$ 个元素的方案数；它不需要记录栈，因为操作是否被允许仅由输入决定，空操作也仍合法。

再令 $tot[t]$ 为从第 $t$ 步起任意选择的总数，即允许选项数的后缀乘积。若第 $t$ 步直接放入集合，后缀所有 $tot[t+1]$ 种选择都贡献该元素。若压栈，则减去它直到结束都未弹出的后缀。

为此定义 $suf[t][i][d]$：已取出 $i$ 个队列元素，目标元素及其上方共 $d$ 个栈元素，从第 $t$ 步起目标始终不弹出的后缀数。直接入集合不改 $d$；队列未空的压栈令 $d+1$；出栈令 $d-1$，但 $d=1$ 时会弹出目标，这条转移禁止。队列为空时前两种操作各自作为原地转移，不能合并成一次选择。末尾所有 $d\ge1$ 的状态值为一。

因此第 $t$ 步取出 $a_{i+1}$ 的贡献为

$$a_{i+1}fp[t][i]\left([1\text{ 可选}]tot[t+1]+[2\text{ 可选}]\bigl(tot[t+1]-suf[t+1][i+1][1]\bigr)\right).$$

三个相乘部分分别是元素权值、到此为止的前缀选择数、使它进入集合的后缀选择数。每个元素的取出时刻唯一，因此求和不重不漏。后缀表倒序滚动，时间 $O(mn^2)$，空间 $O(n^2+mn)$。

### 参考代码

```cpp
// D. 靈
//
// 题意：队列 A（队首到队尾 a1..an）、空栈 B、空多重集 C。三种操作：
//   1) 弹出 A 队首放进 C（A 空则忽略）  2) 弹出 A 队首压入 B（A 空则忽略）
//   3) 弹出 B 栈顶放进 C（B 空则忽略）
//   一个操作序列的得分 = 结束后 C 中元素之和。第 i 步允许的操作由 o_i 决定：
//   o_i ∈ {1,3,5,7} 可为操作 1；∈ {2,3,6,7} 可为操作 2；∈ {4,5,6,7} 可为操作 3。
//   求所有可能操作序列的得分之和，模 998244353。
//
// 关键观察（把"得分"拆到每个元素上）：
//   元素 a_k 只可能被第 k 个"操作 1/2"弹走（前 n 个这样的操作才有元素可弹，
//   再往后 A 已空、这些操作全是空转）。于是
//       答案 = Σ_k a_k × #{该序列里 a_k 最终落在 C 中}
//   而 a_k 落在 C 中 ⟺ 它那一步选的是操作 1，或者选的是操作 2 且**此后被操作 3 弹出**。
//
// 于是只需回答一个问题：站在第 t 步、已知此前恰好弹出了 i 个元素，
//   "第 t 步压进去的那个元素最终会被弹出来"的后续方案数是多少？
//   把栈看成一格一格的高度：以压入那一刻的栈高为基准，此后的操作 2 让高度 +1
//   （A 已空时是空转、不动），操作 3 让高度 -1，操作 1 不动。元素被弹出
//   ⟺ 高度从 1 掉到 0。所以问题变成"后面的走法里，高度始终不掉到基准"的计数，
//   这是一个只有 (已弹出个数 i, 高度 d) 两维的线性 DP，倒着推即可。
//
// 时间 O(n^2 m)，空间 O(n^2 + n m)。

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T, c;
    if (!(cin >> T >> c))
        return 0; // c 只是子任务编号，读掉不用
    while (T--) {
        int n, m;
        cin >> n >> m;

        vector<long long> a(n + 1); // a[1..n]，1-based 方便按"第几个元素"取
        for (int i = 1; i <= n; i++) {
            cin >> a[i];
            a[i] %= MOD;
        }
        vector<int> o(m + 1);
        for (int i = 1; i <= m; i++)
            cin >> o[i];

        // 每步允许哪几种操作（允许 = 1，不允许 = 0）
        vector<int> ok1(m + 2, 0), ok2(m + 2, 0), ok3(m + 2, 0);
        for (int s = 1; s <= m; s++) {
            int v = o[s];
            ok1[s] = (v == 1 || v == 3 || v == 5 || v == 7);
            ok2[s] = (v == 2 || v == 3 || v == 6 || v == 7);
            ok3[s] = (v == 4 || v == 5 || v == 6 || v == 7);
        }

        // tot[s] = 第 s..m 步随便选的方案总数（后缀乘积）
        vector<long long> tot(m + 3, 1);
        for (int s = m; s >= 1; s--) {
            long long w = (long long)ok1[s] + ok2[s] + ok3[s];
            tot[s] = tot[s + 1] * w % MOD;
        }

        // fp[t][i] = 前 t-1 步里"真正从 A 弹出了 i 个元素"的方案数。
        // 操作 1/2 才是弹元素，但 A 一空（i = n）它们就只是空转，方案数照乘。
        vector<vector<long long>> fp(m + 2, vector<long long>(n + 1, 0));
        fp[1][0] = 1;
        for (int t = 1; t <= m; t++) {
            long long w12 = (long long)ok1[t] + ok2[t];
            for (int i = 0; i <= n; i++) {
                long long v = fp[t][i];
                if (!v)
                    continue;
                if (ok3[t])
                    fp[t + 1][i] = (fp[t + 1][i] + v) % MOD; // 选操作 3
                if (i < n) {
                    if (w12)
                        fp[t + 1][i + 1] = (fp[t + 1][i + 1] + v * w12) % MOD;
                } else {
                    if (w12)
                        fp[t + 1][i] = (fp[t + 1][i] + v * w12) % MOD; // A 已空，空转
                }
            }
        }

        // suf[i][d] = 从"已弹出 i 个元素、基准之上的栈高为 d"出发，走完剩下的步、
        //             高度始终 ≥ 1（即基准上那些元素一个都没被弹掉）的方案数。
        vector<vector<long long>> suf(n + 1, vector<long long>(n + 2, 0));
        vector<vector<long long>> nxt(n + 1, vector<long long>(n + 2, 0));
        for (int i = 1; i <= n; i++)
            for (int d = 1; d <= i; d++)
                suf[i][d] = 1; // 第 m+1 步：无步可走，恒不落基准

        long long ans = 0;
        for (int t = m; t >= 1; t--) {
            long long w12 = (long long)ok1[t] + ok2[t];
            long long allFree = tot[t + 1]; // 第 t 步之后的方案总数

            // ---- 结算"第 t 步弹走的那个元素是 a_{i+1}"的贡献 ----
            for (int i = 0; i < n; i++) {
                long long ways = fp[t][i];
                if (!ways)
                    continue;
                long long term = 0;
                if (ok1[t])
                    term += allFree; // 操作 1：直接进 C
                if (ok2[t])
                    term += (allFree - suf[i + 1][1] + MOD) % MOD; // 操作 2：之后被弹出
                if (!term)
                    continue;
                ans = (ans + a[i + 1] % MOD * ways % MOD * (term % MOD)) % MOD;
            }

            // ---- 把 suf 从"第 t+1 步起"推到"第 t 步起" ----
            for (int i = 0; i <= n; i++) {
                int dmax = (i < n ? i : n);
                for (int d = 1; d <= dmax; d++) {
                    long long v = 0;
                    if (i < n) {
                        if (ok1[t])
                            v += suf[i + 1][d]; // 操作 1：弹掉下面一个，高度不变
                        if (ok2[t])
                            v += suf[i + 1][d + 1]; // 操作 2：又压一个，高度 +1
                    } else {
                        if (w12)
                            v += suf[i][d] * w12; // A 已空：操作 1/2 都是空转
                    }
                    if (ok3[t] && d >= 2)
                        v += suf[i][d - 1]; // 操作 3：高度 -1（掉到 0 就是被弹走）
                    nxt[i][d] = v % MOD;
                }
            }
            swap(suf, nxt);
        }

        cout << ans % MOD << '\n';
    }
    return 0;
}
```

### 易错点

目标压入时相对高度为一，原栈在目标下方的元素不影响它何时弹出；减法要按模数归一。

