### 从零讲：棋子扩散 = 「长度恰好 $n$ 的走法」

把本轮有棋子的点记成集合 $S_t$，题面恰好等价于 $v\in S_{t+1}\iff\exists(v\to u),u\in S_t$。因此是沿棋盘边的反方向传播：只有边 $v\to u$ 且棋子在 $u$，下一轮 $v$ 才获得棋子。连续展开可得，$v$ 在第 $t$ 轮有棋子，当且仅当棋盘图中存在一条从 $v$ 到 $k$、长度恰为 $t$ 的走法；等价地，在反向图中从 $k$ 到 $v$ 走 $t$ 步。图中边 $4\to5$ 使棋子从 $5$ 移向 $4$。构造一个永远只有一种下一步的反向图，就能保证每轮只有一枚。

### 思路

![棋盘箭头与棋子的移动方向相反](assets/d-reverse-walk.svg)

暂时把“棋子能够从这里走到那里”画成移动箭头，最后再把所有箭头反过来作为棋盘边。若 $k$ 所在无向连通块是树，则任意定向都没有有向环，走法最多经过块内点数减一条边，小于 $n$，所以最终一定全空。

有环时，找距离 $k$ 最近的环上点 $u$，取最短路 $P$ 连接 $k,u$，再取经过 $u$ 的最短环 $C$。在移动图中将 $P$ 指向 $u$，将 $C$ 顺着环定向，走廊 $P\cup C$ 与外界之间的边都指向走廊。这样棋子先走入环，再一直绕环。

为什么走廊不会存在多余的内部边？最短路不会有跳跃边；经过 $u$ 的最短环不会有弦，否则取含 $u$ 的较短一侧得到更短环。路径中 $u$ 之前的点若还连着环的其他点，就会与路径后段和环合成一个环，使更靠近 $k$ 的路径点也在环上，矛盾。因此走廊每点恰有一条移动出边，棋子从不分叉，也走不出走廊。

实现中用 Tarjan 找桥：DFS 树边 $(x,y)$ 若满足 $low[y]>dfn[x]$，则子树无法绕回 $x$，该边是桥；非桥边的端点就是环上点。BFS 找最近的 $u$；再删去 $u$，从它的所有邻居分别标记不同来源做多源 BFS，两种来源在一条边上相遇即可组成经过 $u$ 的环，取最短者。最后将构造的移动方向整体反转，换算成题目要求的反转位。代码还扫描一次环内弦，故总时间为 $O(n+m+|C|^2)$，空间 $O(n+m)$；哈希查询按期望常数计。

### 参考代码

```cpp
// D 题：判据 = k 所在连通分量含环；构造 = 从 k 到「最近的环上点」的路径 + 一个经过它的无弦环
#include <bits/stdc++.h>
using namespace std;

// ---------- 桥（Tarjan）需要的全局量 ----------
static vector<int> gEu, gEv;
static vector<vector<int>> gAdj;
static vector<int> gDisc, gLow;
static vector<char> gBridge;
static int gTimer;

static void dfsBridge(int u, int p) {
    gDisc[u] = gLow[u] = ++gTimer;
    for (int id : gAdj[u]) {
        int v = (gEu[id] == u) ? gEv[id] : gEu[id];
        if (v == p)
            continue; // 简单图：跳过来时的那条边
        if (!gDisc[v]) {
            dfsBridge(v, u);
            gLow[u] = min(gLow[u], gLow[v]);
            if (gLow[v] > gDisc[u])
                gBridge[id] = 1; // 割边
        } else {
            gLow[u] = min(gLow[u], gDisc[v]);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n, m, k;
        cin >> n >> m >> k;
        --k; // 输入 1-based，转成 0-based 下标
        gEu.assign(m, 0);
        gEv.assign(m, 0);
        gAdj.assign(n, {});
        for (int i = 0; i < m; i++) {
            int u, v;
            cin >> u >> v;
            --u;
            --v;
            gEu[i] = u;
            gEv[i] = v;
            gAdj[u].push_back(i);
            gAdj[v].push_back(i);
        }

        // 1) 取出 k 所在的连通分量（无向）
        vector<int> comp(n, -1), order;
        vector<int> stk{k};
        comp[k] = 0;
        while (!stk.empty()) {
            int u = stk.back();
            stk.pop_back();
            order.push_back(u);
            for (int id : gAdj[u]) {
                int v = (gEu[id] == u) ? gEv[id] : gEu[id];
                if (comp[v] < 0) {
                    comp[v] = 0;
                    stk.push_back(v);
                }
            }
        }
        long long c = (long long)order.size(), ec = 0;
        for (int i = 0; i < m; i++)
            if (comp[gEu[i]] == 0)
                ec++;
        if (ec == c - 1) { // 分量是一棵树 -> 走不出恰好 n 步，无解
            cout << "No\n";
            continue;
        }

        // 2) 求桥，标记「在某个环上」的点 = 至少挨着一条非桥边
        gDisc.assign(n, 0);
        gLow.assign(n, 0);
        gBridge.assign(m, 0);
        gTimer = 0;
        for (int v = 0; v < n; v++)
            if (!gDisc[v])
                dfsBridge(v, -1);
        vector<char> onCycle(n, 0);
        for (int i = 0; i < m; i++)
            if (!gBridge[i]) {
                onCycle[gEu[i]] = 1;
                onCycle[gEv[i]] = 1;
            }

        // 3) 从 k 做 BFS，取「离 k 最近的环上点」u
        vector<int> dist(n, -1), par(n, -1);
        queue<int> q;
        dist[k] = 0;
        q.push(k);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int id : gAdj[u]) {
                int v = (gEu[id] == u) ? gEv[id] : gEu[id];
                if (dist[v] < 0) {
                    dist[v] = dist[u] + 1;
                    par[v] = u;
                    q.push(v);
                }
            }
        }
        int u = -1;
        for (int v : order)
            if (onCycle[v] && (u < 0 || dist[v] < dist[u]))
                u = v;

        // 4) 多源 BFS 求经过 u 的最短环：从 u 的每个邻居出发，两个不同源相撞即成环
        vector<int> d2(n, -1), src(n, -1), p2(n, -1);
        queue<int> q2;
        for (int id : gAdj[u]) {
            int v = (gEu[id] == u) ? gEv[id] : gEu[id];
            if (d2[v] < 0) {
                d2[v] = 1;
                src[v] = v;
                p2[v] = u;
                q2.push(v);
            }
        }
        int best = INT_MAX, bx = -1, by = -1;
        while (!q2.empty()) {
            int x = q2.front();
            q2.pop();
            for (int id : gAdj[x]) {
                int y = (gEu[id] == x) ? gEv[id] : gEu[id];
                if (y == u)
                    continue;
                if (d2[y] < 0) {
                    d2[y] = d2[x] + 1;
                    src[y] = src[x];
                    p2[y] = x;
                    q2.push(y);
                } else if (src[y] != src[x] && d2[x] + d2[y] + 1 < best) {
                    best = d2[x] + d2[y] + 1;
                    bx = x;
                    by = y;
                }
            }
        }
        vector<int> pathX, pathY;
        for (int v = bx; v != u; v = p2[v])
            pathX.push_back(v);
        reverse(pathX.begin(), pathX.end());
        for (int v = by; v != u; v = p2[v])
            pathY.push_back(v);
        vector<int> cyc;
        cyc.push_back(u);
        for (int v : pathX)
            cyc.push_back(v);
        for (int v : pathY)
            cyc.push_back(v);

        // 5) 把环收缩到「无弦」：有弦就换成含 u 的那一段，保证环内只剩环边
        //    （理论上「经过 u 的最短环」本身无弦，这一步是保险，正常一遍扫完就退出）
        unordered_set<long long> edgeSet;
        for (int i = 0; i < m; i++) {
            int a = gEu[i], b = gEv[i];
            edgeSet.insert((long long)min(a, b) * n + max(a, b));
        }
        auto hasEdge = [&](int a, int b) {
            return edgeSet.count((long long)min(a, b) * n + max(a, b)) > 0;
        };
        bool changed = true;
        while (changed) {
            changed = false;
            int L = (int)cyc.size();
            for (int i = 0; i < L && !changed; i++) {
                for (int j = i + 2; j < L; j++) {
                    if (i == 0 && j == L - 1)
                        continue; // 环上的相邻边，不是弦
                    if (!hasEdge(cyc[i], cyc[j]))
                        continue;
                    vector<int> nc;
                    if (i == 0) {
                        for (int t = 0; t <= j; t++)
                            nc.push_back(cyc[t]);
                    } else {
                        for (int t = j; t < L; t++)
                            nc.push_back(cyc[t]);
                        for (int t = 0; t <= i; t++)
                            nc.push_back(cyc[t]);
                    }
                    cyc = nc;
                    changed = true;
                    break;
                }
            }
        }

        // 6) 走廊 W = 从 k 到 u 的最短路 + 环；把每条边走成「指向走廊」或「走廊上的走法」
        vector<int> path;
        for (int v = u; v != -1; v = par[v])
            path.push_back(v);
        reverse(path.begin(), path.end()); // path[0] = k, path.back() = u
        int d = (int)path.size() - 1;

        vector<char> inW(n, 0);
        for (int v : path)
            inW[v] = 1;
        for (int v : cyc)
            inW[v] = 1;

        unordered_set<long long> walkEdge;
        auto key = [&](int x, int y) { return (long long)x * (n + 1) + y; };
        for (int t = 0; t < d; t++)
            walkEdge.insert(key(path[t], path[t + 1]));
        int L = (int)cyc.size();
        for (int j = 0; j < L; j++)
            walkEdge.insert(key(cyc[j], cyc[(j + 1) % L]));

        string ans(m, '0');
        for (int i = 0; i < m; i++) {
            int a = gEu[i], b = gEv[i];
            bool wa = inW[a], wb = inW[b];
            int from, to;
            if (wa && wb) { // 走廊内部只允许是走法边
                if (walkEdge.count(key(a, b))) {
                    from = a;
                    to = b;
                } else {
                    from = b;
                    to = a;
                }
            } else if (wb) { // a 在走廊外 -> 指向走廊
                from = a;
                to = b;
            } else if (wa) { // b 在走廊外 -> 指向走廊
                from = b;
                to = a;
            } else { // 两边都在走廊外，随便
                from = a;
                to = b;
            }
            // 上面构造的是棋子的移动方向；题目沿入边传播，棋盘箭头必须全部反过来。
            ans[i] = (from == a && to == b) ? '1' : '0';
        }
        cout << "Yes\n" << ans << "\n";
    }
    return 0;
}
```

### 易错点

题目沿入边传播，不能直接输出移动图的方向。官方环接链样例应使棋子从 $5$ 走向 $4$，棋盘对应边必须为 $4\to5$。

## A. 时间复杂度分析

### 题意

每秒允许 $5\times10^8$ 次运算，在常数、线性、平方三档中输出能通过的最高复杂度，$n\le10^{18}$。

<!-- reusable-foundations:start -->

### 从零讲：枚举与模拟：让代码和允许的动作一一对应

枚举是系统地检查所有候选；模拟是按题目规则推进状态。先写清一个候选是什么、有哪些动作、执行后哪些量改变，再决定循环边界。

例如从集合 $\{1,2,3\}$ 中选两个不同数：有序选择可枚举 $(i,j)$ 且 $i\ne j$，共六项；如果只关心无序的一对，就规定 $i<j$，得到 $(1,2)$、$(1,3)$、$(2,3)$，避免重复计数。同一个双循环，边界表达的是不同对象。

```cpp
for (int i = 0; i < n; i++)
    for (int j = i + 1; j < n; j++) {
        // 每一对不同位置恰好出现一次
    }
```

模拟例如计数器初始为零，依次读动作“加二、减一、加二”，状态为 $0\to2\to1\to3$。每一步都只读取该时刻允许的信息；若规则要求同时更新多个量，应先用旧状态算全部新量，不能让后一个更新误读前一个新值。

时间要数实际候选数和每个候选的工作。双循环可能是 $O(n^2)$，枚举长度为 $k$ 的二进制选择是 $O(2^k)$；候选少但每次又扫描全数组，也要乘上扫描成本。空间取决于是否需要保存历史。

全枚举的优势是思路直接，容易作为独立校验程序。剪枝必须证明被略去的分支不可能合法或更优，不能只因一个小例子没遇到答案就删候选。若直接枚举超时，先找重复工作、对称性、可维护的量或单调边界，再选择优化方法。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cpp
int a = 100000, b = 100000;
long long wrong = a * b;       // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

<!-- reusable-foundations:end -->

### 思路

平方档要求 $n\le22360$，因为 $22360^2=499969600$，而 $22361^2=500014321$。否则若 $n\le5\times10^8$ 就选线性档，再大只选常数档。直接比较这两个门槛，时间 $O(1)$。

### 参考代码

```cpp
// A. 时间复杂度分析
// 评测机 1 秒能跑 5e8 次运算；对给定的 n，找最高能通过的复杂度。
// 1 秒上限 5e8：O(n^2) 要 n^2 <= 5e8，O(n) 要 n <= 5e8，O(1) 恒可。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    if (!(cin >> n))
        return 0;

    // 22360^2 = 499969600 <= 5e8，22361^2 = 500014321 > 5e8
    if (n <= 22360) {
        cout << "O(n^2)" << '\n';
    } else if (n <= 500000000LL) {
        cout << "O(n)" << '\n';
    } else {
        cout << "O(1)" << '\n';
    }
    return 0;
}
```

### 易错点

不要直接用 64 位计算 $n^2$；输入用 64 位，输出严格使用题目的字符串。

## B. 贴吧 82 号

### 题意

选择一个下标 $x$，同时翻转所有下标为 $x$ 倍数的位置。求把 01 串变成全一的最少操作数。

<!-- reusable-foundations:start -->

### 从零讲：贪心：先证明当前选择不会丢掉最优解

贪心每一步确定一个局部选择，不再撤回。它能省去搜索，但必须解释为什么始终存在一个最优方案也做这个选择。

例如选择最多个互不重叠的活动（这里允许后一活动起点等于前一活动终点）。每次选结束最早的活动：若最优方案的首项结束更晚，把它换成最早结束者，后续原本能接的活动仍能接，数量不变。这就是交换论证；换完首项，剩余问题仍为同类问题。

![结束更早的首项留下不少于另一选择的可用时间](assets/foundations/greedy.svg)

实现时按结束时间升序排序，维护上一次选中活动的结束时刻，依次选合法项。排序 $O(n\log n)$，扫描 $O(n)$，保存活动为 $O(n)$。若题目不允许端点相接，判断须从大于等于改成严格大于。

“选最长”“选价值最高”“选最靠左”都是不同策略。没有交换、支配关系或不变量的依据，不能只凭排序键直觉宣布正确。比如有容量和价值的物品选择，眼前价值最高者可能挡住两个总价值更高的小物品。

写题解时说明被替换的是哪一项、替换后什么约束仍满足、目标为何不变差，并说明余下状态为何允许重复同样论证。若选择还影响未保存的条件，就可能需要更丰富的状态或动态规划。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cpp
vector<int> a(3, 7); // 三个元素，内容是 7、7、7
a.push_back(9);      // 在末尾追加，现在长度为 4
int x = a[1];        // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

### 从零讲：string：字符、下标与子串

`string` 保存字符序列。`string s="abca";` 的长度为四，下标从零开始，`s[0]=='a'`、`s[3]=='a'`。字符用单引号，字符串用双引号；二者类型不同。需要 `<string>`。

`cin >> s` 读到空白停止；整行含空格时使用 `getline`，并留意前一次格式化输入残留的换行。`s.size()` 是字符单元数量，不一定等于 UTF-8 中文字数；竞赛英文小写字母题通常一个字符对应一个单元。

```cpp
string s = "abca";
string middle = s.substr(1, 2); // 从下标 1 开始取 2 个字符，得到 bc
size_t pos = s.find('c');       // 得到 2；找不到是 string::npos
if (pos != string::npos)
    cout << s[pos];
```

`substr(start,length)` 的第二项是长度，不是右端点。普通下标访问为 $O(1)$；复制长为 $k$ 的子串需要 $O(k)$ 时间和空间，循环里反复截取可能累积成平方成本。字符串比较按第一个不同字符决定字典序，公共前缀可能需要线性比较。

常见字符转数字是 `c-'0'`，前提 `c` 在 `'0'` 到 `'9'`。修改原串可用 `for(char& c:s)`，只读使用 `char c`。`reverse(s.begin(),s.end())` 原地翻转；若还需要原串，应先复制。空串不能访问首尾，尾后位置不能当普通字符读取。

### 从零讲：位运算：把非负整数看成一组二进制开关

五写成二进制为 $0101_2$，三为 $0011_2$。同一列各代表一位：按位与 `&` 两边都为一才得一，按位或 `|` 任一为一就得一，按位异或 `^` 不同才为一。所以 $5\mathbin{\&}3=1$，$5\mathbin{|}3=7$，$5\mathbin{\oplus}3=6$。

![相同数值分别写成每一位，逐列计算与、或、异或](assets/foundations/bits.svg)

`1ULL << k` 把一移到第 $k$ 位。对非负无符号整数，`(mask >> k) & 1ULL` 读该位，`mask | (1ULL<<k)` 置一，`mask & ~(1ULL<<k)` 清零，`mask ^ (1ULL<<k)` 翻转。最低位编号为零。

```cpp
unsigned long long mask = 5;   // 第 0、2 位为一
bool has = (mask >> 2) & 1ULL; // true
mask |= 1ULL << 1;             // 变成 7
```

位移次数必须小于类型位宽，且不能为负；不要用普通 `1` 去移到超出 int 范围的位置。C++17 有符号负数右移和溢出的规则不适合直接套“乘除二的幂”，用明确范围的无符号数更容易保证行为。`^` 是异或，绝不是乘方。

逻辑与 `&&`、逻辑或 `||` 将整体条件视为真假，并会短路；按位 `&`、`|` 逐位计算，不会因此跳过右侧表达式。运算符优先级可能与直觉不同，写 `(mask & bit) != 0`，别省掉关键括号。

固定机器字内的一次位运算按 $O(1)$ 估算；枚举全部 $k$ 位状态仍有 $2^k$ 种，不能因为每次运算快就忽略状态数。`x & (x-1)` 对正无符号数清掉最低的一位；GCC 的 `__builtin_popcountll(x)` 统计一的数量，注意实参位宽与具体编译器支持。

### 从零讲：条件表达式 ?:：按条件选择一个结果

需要在两个结果中选一个时，可写 `条件 ? 条件成立时的表达式 : 条件不成立时的表达式`。例如下面求两个整数中较小的一个：

```cpp
int a = 4, b = 9;
int smaller = (a < b ? a : b); // 条件成立，结果为4
```

条件会转换为真假：零为假，非零为真；比较式本身就产生真假。先求条件，然后只计算被选中的一支，另一支不执行。它是有结果的表达式，可以赋给变量或放到输出中；`if/else` 则用来选择执行语句块。

```cpp
bool ready = false;
cout << (ready ? "ready" : "waiting"); // 输出waiting
```

两个分支须能形成兼容的结果类型，不要把文字与数值随意混成两支。输出时给整个条件表达式加括号，明确先选结果再输出，避免与 `<<` 的优先级混淆。条件、两支都保持简短最容易读；多层嵌套或要执行多条操作时，改用清楚的 `if/else`。

一次求值的成本是检查条件，再加实际执行的那一支。比较两个普通整数、选择固定文字通常为常数时间；分支若调用线性扫描函数，条件表达式不会把它变成常数时间。它是表达选择的语法，不会自动优化算法。

<!-- reusable-foundations:end -->

### 本题按位置确定必须使用的操作

翻转两次会抵消，因此只需讨论每个操作用零次或一次。位置 $i$ 只受其约数对应的操作影响，严格大于 $i$ 的操作永远碰不到它。扫描到 $i$ 时，小于 $i$ 的操作已决定，剩下唯一能改变它的是操作 $i$。例如图中先用操作一，位置二变成零，于是操作二必选；这不是局部猜测，而是任何可行解都必须满足的决定。

### 思路

![每次决定最小的尚未确定位置](assets/b-forced.svg)

从小到大扫描 $i$，维护此前操作造成的翻转奇偶。若当前位置仍为零，就必须使用操作 $i$，并将 $i,2i,3i,\ldots$ 的奇偶标记异或一；若已经为一就不用。每个操作至多一次，得到唯一可行的奇偶方案，也就达到最少次数。总更新次数不超过 $\sum_{i=1}^n\lfloor n/i\rfloor=O(n\log n)$，空间 $O(n)$。

### 原来是1的位置，为什么还可能必须操作

![同一个六位串从010011经过操作一二四五到全一，每步真实字符与need flip use同步](assets/editorial-reasoning/core35-toggle-states.svg)

图中初串010011。操作1翻全部位置，变101100；此时第2位原来虽是1，却已被翻成0，必须操作2，得到111001。第3位已经是1，不操作；再操作4、5，依次得到111101、111111，共4次。计数的是选了几种操作，不是翻动了多少个位置。

到位置i时，flip[i]记录前面已选操作造成的翻转奇偶，need由原字符决定：原0需奇数次、原1需偶数次。若二者相同，当前位已经是1，use为0；若不同，必须再翻一次，use为1。四种(need,flip)的结果是(0,0)不选、(0,1)选、(1,0)选、(1,1)不选，这正是异或。不能只检查原字符是不是0。

为什么这一次选择足以且必须？比i大的操作只碰自己的正倍数，永远碰不到位置i；更小的操作已确定；而操作i会碰到i，却不会碰到之前的位置。因此不选/选恰好二选一，选完后前i位全部正确，更新它的所有倍数又把未来的flip维护准确。任何可行解在每个位置都被这样唯一确定；同一操作做两次可抵消，且翻转顺序不影响结果，故重复操作只会增加次数。逐位确定的0/1操作集合就是最少次数解。

### 参考代码

```cpp
// B. 贴吧 82 号
// 每次操作选 x，翻转所有 x 的倍数的位置；求把 01 串全变 1 的最少操作数。
// 同一个 x 用两次等于没用，所以每个 x 只用 0 或 1 次。
// 位置 i 只受「i 的约数 x」影响：从小往大扫，a_i 由前面更小的约数唯一确定。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    // flip[i] = 下标 i 当前被前面已选操作翻转过几次的奇偶（1 = 翻过奇数次）
    vector<int> flip(n + 1, 0);
    int ans = 0;
    for (int i = 1; i <= n; i++) {
        // 位置 i 想变成 '1'：'0' 需要翻奇数次，'1' 需要翻偶数次
        int need = (s[i - 1] == '0') ? 1 : 0;
        int use = need ^ flip[i]; // 前面已定的翻转奇偶 xor 目标 = 操作 i 必须取的值
        if (use) {
            ++ans;
            for (int j = i; j <= n; j += i)
                flip[j] ^= 1; // 把 i 的倍数位置都翻一次
        }
    }
    cout << ans << '\n';
    return 0;
}
```

### 易错点

判断的是经过此前翻转后的当前位，不能只看原字符串；一次操作必须更新它的所有倍数。

## C. 帮助她玩游戏

### 题意

依次经过兑换机，够钱时普通机必须用，特殊机可不用，使用后有两种可能收益。各机器门槛 $a_i\le20$，特殊机至多三十台。多次询问最终能否恰有给定币数。

<!-- reusable-foundations:start -->

### 从零讲：动态规划：保存明确子问题的答案

若多个决策会反复遇到相同的剩余问题，可以为每个不同问题保存一次答案。状态不是“当前操作到了哪儿”的模糊描述，而是一个有完整条件、能独立提问的问题。

例如台阶一次走一或二级，求到达第 $i$ 级的方式数。令 $f_i$ 为恰好到第 $i$ 级的方案数。最后一步只有两类：从 $i-1$ 走一级，或从 $i-2$ 走两级，类别互斥且覆盖所有方案，所以 $f_i=f_{i-1}+f_{i-2}$。

![每个状态读取已经确定的两个更小状态，箭头表示依赖](assets/foundations/dp.svg)

起点 $f_0=1$ 表示原地不走的一种空方案，$f_1=1$。于是 $f_2=2,f_3=3,f_4=5$。从小到大计算，因为当前格依赖的格都已经完成。`f[0]=0` 会把“空方案”错误删掉。

以下示例要求 $0\le n\le91$：按 $f_0=f_1=1$，$f_{91}=7540113804746346429$ 仍在常见有符号64位范围内，$f_{92}=12200160415121876738$ 已超出；更大的输入须改用取模或大整数，不能继续依赖此类型。

```cpp
vector<long long> f(n + 1, 0);
f[0] = 1;
for (int i = 1; i <= n; i++) {
    f[i] = f[i - 1];
    if (i >= 2)
        f[i] += f[i - 2];
}
```

另一个问题若问最小费用，就应对候选取 `min`；问最大收益取 `max`；问数量才在不重不漏的分类下相加。不能只把加号替换掉，初值也要随状态含义重新决定。不可达状态应与合法的零答案区别。

时间通常为状态数乘每个状态枚举的转移数，本例 $O(n)$；保存整表用 $O(n)$。只依赖最近两格时可滚动到 $O(1)$ 空间，但要先保存仍需读取的旧值。若下标不够决定后续可选动作，就缺少状态维度，不能把不同问题混在同一格。

检查一份 DP 时依次核对：状态的问题、基础答案、最后一步分类、依赖计算顺序、最终读哪一格。记忆化搜索使用同样的子问题，只是按递归需要计算；它也需要终止条件并避免状态依赖成环。

### 从零讲：位运算：把非负整数看成一组二进制开关

五写成二进制为 $0101_2$，三为 $0011_2$。同一列各代表一位：按位与 `&` 两边都为一才得一，按位或 `|` 任一为一就得一，按位异或 `^` 不同才为一。所以 $5\mathbin{\&}3=1$，$5\mathbin{|}3=7$，$5\mathbin{\oplus}3=6$。

![相同数值分别写成每一位，逐列计算与、或、异或](assets/foundations/bits.svg)

`1ULL << k` 把一移到第 $k$ 位。对非负无符号整数，`(mask >> k) & 1ULL` 读该位，`mask | (1ULL<<k)` 置一，`mask & ~(1ULL<<k)` 清零，`mask ^ (1ULL<<k)` 翻转。最低位编号为零。

```cpp
unsigned long long mask = 5;   // 第 0、2 位为一
bool has = (mask >> 2) & 1ULL; // true
mask |= 1ULL << 1;             // 变成 7
```

位移次数必须小于类型位宽，且不能为负；不要用普通 `1` 去移到超出 int 范围的位置。C++17 有符号负数右移和溢出的规则不适合直接套“乘除二的幂”，用明确范围的无符号数更容易保证行为。`^` 是异或，绝不是乘方。

逻辑与 `&&`、逻辑或 `||` 将整体条件视为真假，并会短路；按位 `&`、`|` 逐位计算，不会因此跳过右侧表达式。运算符优先级可能与直觉不同，写 `(mask & bit) != 0`，别省掉关键括号。

固定机器字内的一次位运算按 $O(1)$ 估算；枚举全部 $k$ 位状态仍有 $2^k$ 种，不能因为每次运算快就忽略状态数。`x & (x-1)` 对正无符号数清掉最低的一位；GCC 的 `__builtin_popcountll(x)` 统计一的数量，注意实参位宽与具体编译器支持。

### 从零讲：概率与期望：按事件或按贡献计算

概率描述某事件发生的机会；等可能的有限样本空间里，概率为合法结果数除总结果数。先写清哪些结果等可能，不能把不同生成路径自然当作等可能。

随机变量给每个结果一个数值，期望是按概率加权的平均。公平骰子的点数期望为 $(1+2+3+4+5+6)/6=3.5$，不要求期望本身是可出现的整数结果。

#### 指示变量把总量拆成贡献

若总分为每次成功加一，令 $I_i$ 在第 $i$ 次成功时为一，否则零，则总分 $X=\sum I_i$。每项期望就是成功概率，故 $E[X]=\sum P(I_i=1)$。期望的线性性不要求各项独立；但计算联合成功概率时，直接相乘需要独立或正确使用条件概率。

例如三项成功概率分别为二分之一、三分之一、四分之一，总成功数期望为十二分之十三，即使三件事有关联，这个和仍成立。若问“至少成功一次”的概率，则不能只把三项概率相加，事件可能重叠。

#### 期望递推要包含当前消耗

若每轮以概率 $p$ 完成，否则回到原状态，每轮都消耗一步，则 $E=1+(1-p)E$，得到 $E=1/p$。这里的一来自本轮无论成败都执行的一步；$p=0$ 时永远不能完成，不能除零得有限值。

一般期望 DP 应说明状态、转移概率和每步即时费用。含自环时要把同状态项移到等式一边，不能按普通无环 DP 直接读取尚未确定的自己。模意义的概率还要求分母可逆；输出浮点期望则要按误差要求选择类型，不可把普通实数平均与模逆计算混用。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cpp
vector<int> a(3, 7); // 三个元素，内容是 7、7、7
a.push_back(9);      // 在末尾追加，现在长度为 4
int x = a[1];        // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

### 从零讲：string：字符、下标与子串

`string` 保存字符序列。`string s="abca";` 的长度为四，下标从零开始，`s[0]=='a'`、`s[3]=='a'`。字符用单引号，字符串用双引号；二者类型不同。需要 `<string>`。

`cin >> s` 读到空白停止；整行含空格时使用 `getline`，并留意前一次格式化输入残留的换行。`s.size()` 是字符单元数量，不一定等于 UTF-8 中文字数；竞赛英文小写字母题通常一个字符对应一个单元。

```cpp
string s = "abca";
string middle = s.substr(1, 2); // 从下标 1 开始取 2 个字符，得到 bc
size_t pos = s.find('c');       // 得到 2；找不到是 string::npos
if (pos != string::npos)
    cout << s[pos];
```

`substr(start,length)` 的第二项是长度，不是右端点。普通下标访问为 $O(1)$；复制长为 $k$ 的子串需要 $O(k)$ 时间和空间，循环里反复截取可能累积成平方成本。字符串比较按第一个不同字符决定字典序，公共前缀可能需要线性比较。

常见字符转数字是 `c-'0'`，前提 `c` 在 `'0'` 到 `'9'`。修改原串可用 `for(char& c:s)`，只读使用 `char c`。`reverse(s.begin(),s.end())` 原地翻转；若还需要原串，应先复制。空串不能访问首尾，尾后位置不能当普通字符读取。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cpp
int a = 100000, b = 100000;
long long wrong = a * b;       // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

### 从零讲：用多个六十四位整数保存可平移的集合

一个机器整数只能保存固定数量的位。若集合含更大的非负编号，可以用 `<vector>` 保存多个 `<cstdint>` 的 `std::uint64_t`：第w个字保存编号64w至64w+63，第p个编号位于字p/64的第p%64位。每位只表示“存在”，按位或合并重复来源，不统计产生次数。

![编号六十三跨过六十四位字边界，左移一后到六十四，原六十四到六十五；取并集保留六十三六十四六十五](assets/editorial-reasoning/counting17-word-shift.svg)

例如旧集合只有63、64。左移一后是64、65：目标第二字同时接收旧第一字最高位移出的1，以及旧第二字最低位左移后的2，合成二进制11。左移64则整字移动，得到127、128，不能再执行一次“字内移64”。

下面是独立教学函数。dst和src长度相同，且必须是不同vector对象；dst可已有内容，函数只把src平移后的结果并入它。left为真向左移，否则向右移，s总为非负。固定分配的字数以外会被截掉。

```cpp
using Word = std::uint64_t;
void or_shift(std::vector<Word> &dst, const std::vector<Word> &src, unsigned s, bool left) {
    std::size_t whole = s / 64;
    unsigned part = s % 64;
    for (std::size_t i = 0; i < src.size(); i++) {
        if (left) {
            std::size_t j = i + whole;
            if (j < dst.size())
                dst[j] |= src[i] << part;
            if (part && j + 1 < dst.size())
                dst[j + 1] |= src[i] >> (64 - part);
        } else if (i >= whole) {
            std::size_t j = i - whole;
            if (j < dst.size())
                dst[j] |= src[i] >> part;
            if (part && j > 0 && j - 1 < dst.size())
                dst[j - 1] |= src[i] << (64 - part);
        }
    }
}
```

part为零时只做整字平移，两个跨字表达式都不执行，避免未定义的移位64。unsigned右移在高位补零；左移丢掉字宽之外的位，溢出的那部分由相邻字接住。whole与part将每个旧编号的位置分成整字距离和字内余数，所以每个旧的一位恰到自己的目标位置，多个来源合并仍只占一位。

若要模拟负的数值变化，应调用右移并传入其非负绝对值，不能把负数直接交给移位运算符。调用者还要保证whole和下标加法不溢出。两个结果都要来自同一旧集合时，先按值复制src；不能把第一次扩展后的dst用作第二个src，否则会组合出两次变化。

W个机器字的一次平移花 $O(W)$ 时间，集合占 $O(W)$ 字，另存快照再花 $O(W)$ 空间。位移快不意味着状态或方案数减少：这只能合并同一个编号的存在性。选择足够范围、检查每次变换的真实编号不会错误截掉，仍是使用者必须证明的条件。

### 从零讲：resize、assign 与整份 vector 复制

`<vector>` 的 `std::vector<T>` 按值保存一串同类型元素。需要改变长度、覆盖整串或保留一份旧数据时，要区分下面三个动作：

```cpp
std::vector<int> values{4, 7, 9};
values.resize(2);    // 现在是4、7，末项被删除
values.resize(4, 5); // 现在是4、7、5、5；已有项没有重新初始化
std::vector<int> old = values;
values.assign(3, 0); // 覆盖整串，变成三个零
// old仍是4、7、5、5
```

resize增长时只构造新增项，省略第二参数时整数新增项为零；缩短时删除尾部，不能再访问删掉的下标。assign(count,value)则替换全部现有内容，长度也改成count。reserve只请求容量，不构造元素，与这两种操作不同。

同类型vector之间的赋值，例如 `old=values`，复制当时的元素值；随后修改values不改变old。嵌套vector会继续复制内部vector。若元素本身是指针，复制的是指针值，不会因此复制所指的外部对象。需要一次转移从旧状态产生多个分支时，可先保存旧副本，再修改目标，避免后一个分支误读新结果。

复制n项需要 $O(n)$ 时间与保存副本的空间；assign与新增、删除元素的成本应按处理的元素数估计，扩容还可能搬移已有项。扩容会使旧迭代器、指针和引用失效；缩短后的被删元素也已不存在。仅容量可能保留，不代表旧元素还能访问。



### 从零讲：逐个或成段追加字符与预留容量

`std::string` 保存一串有顺序的字符。已有字符串后面加一个字符可写 `s += 'b'`；追加某个字符的多次重复可写 `s.append(count, ch)`，参数次序先次数、后字符。

```cpp
std::string s = "A";
s.reserve(20);
s += 'b';
s.append(3, 'c'); // 现在是 Abccc，长度五
s.append(0, 'x'); // 追加零次，不改变内容
```

`reserve(20)` 请求容量至少为二十，容量可以更大；它不把长度改成二十，也不产生可访问的二十个字符。例中预留后长度仍是一，直到追加才增长。下标访问要求小于当前 `size()`，不能访问尚未构造的预留空间。次数类型是无符号的大小类型，原来的有符号次数必须先证明非负；负数转换后会成为巨大请求。

已知最终长度时预留容量，可减少反复增长和复制。追加 $k$ 个字符至少需写入 $k$ 次，时间为 $O(k)$；逐个尾部追加按扩容策略有摊还常数成本。字符串总占用随其容量增长。扩容可能使原来的指针、引用、迭代器失效，不应跨追加保存它们继续使用。这里始终按值保存索引或字符，不依赖这些旧引用。

