// A. Flower_Rainbow_and_Magic
// 题意：给定中点 C，构造两个不同的整点 A、B 使其中点恰为 C。
// 做法：沿 x 轴关于 C 对称取两点，A = C + (1,0,0)，B = C - (1,0,0)。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x, y, z;
    cin >> x >> y >> z;

    // 两点关于 C 对称，中点自然就是 C；两点 x 坐标差 2，必不相同。
    // |x| ≤ 2，所以 x±1 落在 [-3,3] ⊂ [-10,10]，输出范围一定合法。
    cout << x + 1 << ' ' << y << ' ' << z << ' ' << x - 1 << ' ' << y << ' ' << z << '\n';
    return 0;
}
