### 参考程序 · C++17

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k, q;
    cin >> n >> k >> q;
    const int U = 200000;
    vector<int> delta(U + 2), good(U + 1);
    for (int i = 0; i < n; i++) {
        int l, r;
        cin >> l >> r;
        ++delta[l];
        --delta[r + 1];
    }
    int cover = 0;
    for (int t = 1; t <= U; t++) {
        cover += delta[t];
        good[t] = good[t - 1] + (cover >= k);
    }
    while (q--) {
        int a, b;
        cin >> a >> b;
        cout << good[b] - good[a - 1] << '\n';
    }
}
```

复杂度：U=200000，O(n+U+q) 时间，O(U) 空间。

