### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll INF = (1LL << 62);
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    vector<vector<int>> g(n + 1);
    for (int i = 0, u, v; i < m; i++) {
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    ll N = n + 1;
    auto key = [&](ll a, ll b, ll c) { return (a * N + b) * N + c; };
    unordered_set<ll> bad;
    for (int i = 0, a, b, c; i < k; i++) {
        cin >> a >> b >> c;
        bad.insert(key(a, b, c));
    }
    vector<int> parent(N * N, -1);
    queue<pair<int, int>> q;
    q.push({0, 1});
    parent[1] = 0;
    pair<int, int> end = {-1, -1};
    while (!q.empty()) {
        auto [p, u] = q.front();
        q.pop();
        if (u == n) {
            end = {p, u};
            break;
        }
        for (int v : g[u])
            if (!bad.count(key(p, u, v)) && parent[u * N + v] < 0) {
                parent[u * N + v] = p;
                q.push({u, v});
            }
    }
    if (end.first < 0) {
        cout << -1;
        return 0;
    }
    vector<int> path;
    auto [p, u] = end;
    while (!(p == 0 && u == 1)) {
        path.push_back(u);
        int pp = parent[p * N + u];
        u = p;
        p = pp;
    }
    path.push_back(1);
    reverse(path.begin(), path.end());
    cout << path.size() - 1 << '\n';
    for (int v : path)
        cout << v << ' ';
}
```

### 易错点

错误程序把上面路径按不同城市数减一来计算长度，得到多少？

错误写法得到 3。长度是实际走过的边数，不能将重复访问的城市去掉。

- 同一城市来自不同前驱
- 不存在合法路径
- 合法答案需要重复经过城市

