    int s = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        for (int j = 0; j < m; j++)
            if (a[i][j] == '.') {
                s++;
                if (st.empty())
                    st.push_back({i, j});
            }
    }
    seen[st[0].first][st[0].second] = true;
    int dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1};
    while (!st.empty()) {
        auto [x, y] = st.back();
        st.pop_back();
        order.push_back({x, y});
        for (int d = 0; d < 4; d++) {
            int u = x + dx[d], v = y + dy[d];
            if (u >= 0 && u < n && v >= 0 && v < m && a[u][v] == '.' && !seen[u][v]) {
                seen[u][v] = true;
                st.push_back({u, v});
            }
        }
    }
    for (int i = s - k; i < s; i++)
        a[order[i].first][order[i].second] = 'X';
    for (auto &row : a)
        cout << row << '\n';
}
```

