### 思路

把员工当元素，共用语言的员工合并。只要有人会语言，c 个员工分量可用 c-1 次学习接起来；如果所有人都不会语言，则每个人都必须学一次，答案 n。

![会共同语言的人属于同一块](assets/graph-lab/277A.svg)

甲乙丙已连通；让丁学英语即可把两个块合成一个。

### 复杂度

用每种语言的首个员工合并其余人，时间 O(总语言记录数·α(n))，空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll INF = (1LL << 62);
struct DSU {
    vector<int> p, sz;
    DSU(int n) : p(n), sz(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (sz[a] < sz[b])
            swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        return true;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    DSU d(n);
    vector<int> first(m + 1, -1);
    bool any = false;
    int c = n;
    for (int i = 0; i < n; i++) {
        int k;
        cin >> k;
        while (k--) {
            int language;
            cin >> language;
            any = true;
            if (first[language] < 0)
                first[language] = i;
            else if (d.unite(i, first[language]))
                c--;
        }
    }
    cout << (any ? c - 1 : n);
}
```

