    vector<int> a(n);
    for (int &x : a)
        cin >> x;
    int l = 0;
    while (l + 1 < n && a[l] < a[l + 1])
        l++;
    int r = l;
    while (r + 1 < n && a[r] > a[r + 1])
        r++;
    reverse(a.begin() + l, a.begin() + r + 1);
    if (is_sorted(a.begin(), a.end()))
        cout << "yes\n" << l + 1 << ' ' << r + 1 << '\n';
    else
        cout << "no\n";
}
```

