int solveA() {
    const int NEG = -1000000000;
    int f[32];
    for (int m = 0; m < 32; m++)
        f[m] = NEG;
    f[0] = 0;
    for (int i = 0; i < 20; i++) {
        int g[32];
        for (int m = 0; m < 32; m++)
            g[m] = f[m]; // 该球员不选
        for (int m = 0; m < 32; m++) {
            if (f[m] == NEG)
                continue;
            for (int j = 0; j < 5; j++) {
                if (m & (1 << j))
                    continue;
                int nm = m | (1 << j);
                g[nm] = max(g[nm], f[m] + SCORE[i][j]);
            }
        }
        for (int m = 0; m < 32; m++)
            f[m] = g[m];
    }
    return f[31];
}

string solveB() {
