        n = (n - 1) / 26;
    }
    reverse(s.begin(), s.end());
    return s;
}

int solveC() {
    const int MOD = 10000;
    long long a = 1, b = 1, c = 1;
    for (long long i = 4; i <= 20190324LL; i++) {
        long long d = (a + b + c) % MOD;
        a = b;
        b = c;
        c = d;
    }
    return (int)c;
}

bool ok(int x) {
    while (x > 0) {
        int d = x % 10;
        if (d == 2 || d == 4)
            return false;
        x /= 10;
    }
    return true;
}

long long solveD() {
    long long cnt = 0;
    for (int a = 1; a <= 2017; a++) {
        if (!ok(a))
            continue;
        for (int b = a + 1; b <= 2018; b++) {
            if (!ok(b))
                continue;
            int c = 2019 - a - b;
            if (c <= b)
                continue;
            if (ok(c))
                ++cnt;
        }
    }
    return cnt;
}

