            if (nx < 0 || nx >= 30 || ny < 0 || ny >= 50)
                continue;
            if (MAZE[nx][ny] == '1')
                continue;
            if (dist[nx][ny] != -1)
                continue;
            dist[nx][ny] = dist[x][y] + 1;
            pre[nx][ny] = dc[k];
            q.push({nx, ny});
        }
    }
    string path;
    int x = 29, y = 49;
    while (!(x == 0 && y == 0)) {
        char d = pre[x][y];
        path.push_back(d);
        if (d == 'D')
            x -= 1;
        else if (d == 'U')
            x += 1;
        else if (d == 'L')
            y += 1;
        else
            y -= 1;
    }
    reverse(path.begin(), path.end());
    return path;
}

int main() {
    char T;
    if (!(cin >> T))
        return 0;
    if (T == 'A')
        cout << solveA() << endl;
    else if (T == 'B')
        cout << solveB() << endl;
    else if (T == 'C')
        cout << solveC() << endl;
    else if (T == 'D')
        cout << solveD() << endl;
    else if (T == 'E')
        cout << solveE() << endl;
    return 0;
}
```

## 特别数的和

### 题意
给定正整数 n，求 1 到 n 中所有十进制表示里至少含有一个数字 2、0、1 或 9 的整数之和。

<!-- reusable-foundations:start -->

### 从零讲：枚举与模拟：让代码和允许的动作一一对应

枚举是系统地检查所有候选；模拟是按题目规则推进状态。先写清一个候选是什么、有哪些动作、执行后哪些量改变，再决定循环边界。

例如从集合 $\{1,2,3\}$ 中选两个不同数：有序选择可枚举 $(i,j)$ 且 $i\ne j$，共六项；如果只关心无序的一对，就规定 $i<j$，得到 $(1,2)$、$(1,3)$、$(2,3)$，避免重复计数。同一个双循环，边界表达的是不同对象。

```cpp
for (int i = 0; i < n; i++)
    for (int j = i + 1; j < n; j++) {
        // 每一对不同位置恰好出现一次
    }
```

模拟例如计数器初始为零，依次读动作“加二、减一、加二”，状态为 $0\to2\to1\to3$。每一步都只读取该时刻允许的信息；若规则要求同时更新多个量，应先用旧状态算全部新量，不能让后一个更新误读前一个新值。

时间要数实际候选数和每个候选的工作。双循环可能是 $O(n^2)$，枚举长度为 $k$ 的二进制选择是 $O(2^k)$；候选少但每次又扫描全数组，也要乘上扫描成本。空间取决于是否需要保存历史。

全枚举的优势是思路直接，容易作为独立校验程序。剪枝必须证明被略去的分支不可能合法或更优，不能只因一个小例子没遇到答案就删候选。若直接枚举超时，先找重复工作、对称性、可维护的量或单调边界，再选择优化方法。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cpp
int a = 100000, b = 100000;
long long wrong = a * b;       // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

<!-- reusable-foundations:end -->

### 思路
直接枚举 1 到 n 的每个整数 i。对每个 i，用临时变量 t 反复取末位（t % 10）并去掉末位（t /= 10），检查取出的数字是否等于 2、0、1 或 9。只要某一位命中，就说明 i 是“特别数”，把 i 累加到答案中，并立即停止检查该数。若所有位都不命中，则跳过。

由于整数没有前导零，逐位取模不会额外产生题目排除的前导 0，检查结果与题意一致。

### 正确性
对任意 i，循环依次取出其个位、十位、百位……直到最高位，恰好覆盖 i 的全部十进制位且不重复。若其中某一位是 2、0、1、9，则 i 满足条件并被累加；若所有位都不是这四个数字，则 i 不满足条件且不被累加。因此每个 1 到 n 的整数都被正确判定，答案恰为所有满足条件数之和。

### 复杂度
每个数最多检查其十进制位数，n ≤ 10000 时位数不超过 5。总时间复杂度为 O(n log n)，空间复杂度 O(1)。

### 易错点
- 累加变量应使用 long long，避免大 n 时和溢出 int。
- 检查某一位命中后可直接跳出，不必继续检查剩余位。
- 临时变量 t 初始化为 i，不能直接修改循环变量 i。
- 数字 0 本身不在 1 到 n 范围内，无需特殊处理。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    long long ans = 0;
    for (int i = 1; i <= n; i++) {
        int t = i;
        bool special = false;
        while (t > 0) {
            int d = t % 10;
            if (d == 2 || d == 0 || d == 1 || d == 9) {
                special = true;
                break;
            }
            t /= 10;
        }
        if (special)
            ans += i;
    }

    cout << ans << '\n';
    return 0;
}
```

