### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
struct WeightedDSU {
    vector<int> parent, size;
    vector<long long> offset;
    WeightedDSU(int n) : parent(n + 1), size(n + 1, 1), offset(n + 1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] == x)
            return x;
        int old = parent[x];
        parent[x] = find(old);
        offset[x] += offset[old];
        return parent[x];
    }
    bool constrain(int x, int y, long long value) {
        int a = find(x), b = find(y);
        long long difference = value + offset[x] - offset[y];
        if (a == b)
            return difference == 0;
        if (size[a] >= size[b]) {
            parent[b] = a;
            offset[b] = difference;
            size[a] += size[b];
        } else {
            parent[a] = b;
            offset[a] = -difference;
            size[b] += size[a];
        }
        return true;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n, m;
        cin >> n >> m;
        WeightedDSU groups(n);
        bool possible = true;
        for (int i = 0; i < m; i++) {
            int s, t;
            long long value;
            cin >> s >> t >> value;
            if (!groups.constrain(s - 1, t, value))
                possible = false;
        }
        cout << (possible ? "true" : "false") << '\n';
    }
    return 0;
}
```

### 易错点

前缀下标是 $s-1$ 与 $t$；压缩时累计偏移；反向挂根需反号；负收入合法；读完全部记录。

## P1196. 银河英雄传说

> 原题：[P1196](https://www.luogu.com.cn/problem/P1196)
> 解法：带权并查集存相对位置，队首位置与代表分开维护 · C++17

### 题意

三万艘舰船初始各成一列。$M i j$ 把 $i$ 所在整列接到 $j$ 所在列尾部，不改变列内顺序；$C i j$ 询问两舰之间的舰船数，不同列输出负一。

