int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long N, K;
    cin >> N >> K;
    const long long P = 2019201997;
    cout << P - 84 * (K - 1) - 48 * N << '\n';
    return 0;
}
