### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
struct Fenwick {
    int n;
    vector<int> tree;
    explicit Fenwick(int size) : n(size), tree(size + 1) {}
    void add(int p, int v) {
        for (; p <= n; p += p & -p)
            tree[p] += v;
    }
    int sum(int p) const {
        int value = 0;
        for (; p; p -= p & -p)
            value += tree[p];
        return value;
    }
    int kth(int k) const {
        int p = 0;
        for (int step = 1 << 20; step; step >>= 1) {
            int q = p + step;
            if (q <= n && tree[q] < k) {
                p = q;
                k -= tree[q];
            }
        }
        return p + 1;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string a, b;
    cin >> n >> a >> b;
    array<vector<int>, 26> positions;
    array<int, 26> next = {};
    for (int i = 0; i < n; i++)
        positions[b[i] - 'A'].push_back(i + 1);
    Fenwick bit(n);
    long long answer = 0;
    for (int i = 0; i < n; i++) {
        int letter = a[i] - 'A', p = positions[letter][next[letter]++];
        answer += i - bit.sum(p);
        bit.add(p, 1);
    }
    cout << answer << '\n';
    return 0;
}
```

### 易错点

同字母稳定匹配；目标位置从一编号；先查询后插入；统计此前更大位置；总逆序对六十四位；不能只数字符不在原位置的数量。

## P2161. 会场预约

> 原题：[P2161](https://www.luogu.com.cn/problem/P2161)
> 解法：有序维护互不相交的预约，只取消与新闭区间相交者 · C++17

### 题意

A操作取消所有与新预约相交的旧预约并报告取消数，然后加入新预约；B操作报告当前预约总数。

