## P1766 液体滴落

原题：[P1766](https://www.luogu.com.cn/problem/P1766)

### 思路

在非水平、非竖直且每次首次命中唯一的情形，枚举下落时的最高交点，再滑到轨道较低端。交点用有理数比较。原题未定义同时命中多条轨道的选择，详细题解保留反例，代码不猜定该规则。

### 复杂度

唯一命中情形时间 O(N²)，空间 O(N)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long x;
    cin >> n >> x;
    struct Segment {
        long long l, yl, r, yr;
    };
    vector<Segment> a(n);
    for (auto &s : a) {
        cin >> s.l >> s.yl >> s.r >> s.yr;
        if (s.l > s.r) {
            swap(s.l, s.r);
            swap(s.yl, s.yr);
        }
    }
    long long y = 1000000001LL;
    vector<char> used(n);
    for (int step = 0; step <= n; step++) {
        int best = -1;
        long long bestNum = 0, bestDen = 1;
        bool tie = false;
        for (int i = 0; i < n; i++)
            if (!used[i]) {
                auto s = a[i];
                if (s.l == s.r) {
                    if (x == s.l && min(s.yl, s.yr) < y)
                        return 0;
                    continue;
                }
                if (!(s.l < x && x < s.r))
                    continue;
                if (s.yl == s.yr && s.yl <= y)
                    return 0;
                long long den = s.r - s.l, num = s.yl * den + (s.yr - s.yl) * (x - s.l);
                if ((__int128)num > (__int128)y * den)
                    continue;
                if (best < 0 || (__int128)num * bestDen > (__int128)bestNum * den) {
                    best = i;
                    bestNum = num;
                    bestDen = den;
                    tie = false;
                } else if ((__int128)num * bestDen == (__int128)bestNum * den)
                    tie = true;
            }
        if (best < 0) {
            cout << x << '\n';
            return 0;
        }
        if (tie)
            return 0;
        used[best] = 1;
        auto s = a[best];
        if (s.yl < s.yr) {
            x = s.l;
            y = s.yl;
        } else {
            x = s.r;
            y = s.yr;
        }
    }

    return 0;
}
```

### 实现提醒

端点严格排除；同高内部可再次命中；高度比较用 __int128；同时首次命中仍需原题补充规则。

## P1850 换教室

原题：[P1850](https://www.luogu.com.cn/problem/P1850)

### 思路

Floyd 求教室间最短路，dp[天数][申请次数][当天是否申请] 维护最小期望路程。相邻两天按各自成功或失败的概率组合四种距离转移。

### 复杂度

时间 O(v³+nm)，空间 O(v²+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, v, e;
    cin >> n >> m >> v >> e;
    vector<int> c(n), d(n);
    vector<long double> p(n);
    for (int &x : c) {
        cin >> x;
        x--;
    }
    for (int &x : d) {
        cin >> x;
        x--;
    }
    for (auto &x : p)
        cin >> x;
    const long double INF = 1e80L;
    vector<vector<long double>> dist(v, vector<long double>(v, INF));
    for (int i = 0; i < v; i++)
        dist[i][i] = 0;
    while (e--) {
        int a, b;
        long double w;
        cin >> a >> b >> w;
        a--;
        b--;
        dist[a][b] = dist[b][a] = min(dist[a][b], w);
    }
    for (int k = 0; k < v; k++)
        for (int i = 0; i < v; i++)
            for (int j = 0; j < v; j++)
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
    vector<array<long double, 2>> dp(m + 1, {INF, INF});
    dp[0][0] = 0;
    if (m)
        dp[1][1] = 0;
    for (int day = 1; day < n; day++) {
        long double cost[2][2]{};
        for (int before = 0; before < 2; before++)
            for (int now = 0; now < 2; now++)
                for (int a = 0; a < 2; a++)
                    for (int b = 0; b < 2; b++) {
                        long double pa = before ? (a ? p[day - 1] : 1 - p[day - 1]) : (a ? 0 : 1),
                                    pb = now ? (b ? p[day] : 1 - p[day]) : (b ? 0 : 1);
                        cost[before][now] +=
                            pa * pb * dist[a ? d[day - 1] : c[day - 1]][b ? d[day] : c[day]];
                    }
        vector<array<long double, 2>> next(m + 1, {INF, INF});
        for (int used = 0; used <= m; used++)
            for (int before = 0; before < 2; before++)
                for (int now = 0; now < 2; now++)
                    if (used + now <= m)
                        next[used + now][now] =
                            min(next[used + now][now], dp[used][before] + cost[before][now]);
        dp.swap(next);
    }
    long double ans = INF;
    for (auto state : dp)
        ans = min({ans, state[0], state[1]});
    cout << fixed << setprecision(2) << ans << '\n';

    return 0;
}
```

### 实现提醒

申请决定不能依据随机结果；第一天也可申请；最多 m 次而非恰好。

## P1854 花店橱窗布置

原题：[P1854](https://www.luogu.com.cn/problem/P1854)

### 思路

dp[i][j] 表示前 i 束花放进前 j 个花瓶的最大价值。第 j 瓶可以空着，也可以放第 i 束花。记录取舍后从 dp[F][V] 回溯方案。

### 复杂度

时间 O(FV)，空间 O(FV)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int F, V;
    cin >> F >> V;
    vector<vector<int>> a(F + 1, vector<int>(V + 1));
    for (int i = 1; i <= F; i++)
        for (int j = 1; j <= V; j++)
            cin >> a[i][j];
    const int NEG = -1000000000;
    vector<vector<int>> dp(F + 1, vector<int>(V + 1, NEG));
    vector<vector<char>> take(F + 1, vector<char>(V + 1));
    for (int j = 0; j <= V; j++)
        dp[0][j] = 0;
    for (int i = 1; i <= F; i++)
        for (int j = 1; j <= V; j++) {
            dp[i][j] = dp[i][j - 1];
            if (dp[i - 1][j - 1] != NEG && dp[i - 1][j - 1] + a[i][j] > dp[i][j]) {
                dp[i][j] = dp[i - 1][j - 1] + a[i][j];
                take[i][j] = 1;
            }
        }
    cout << dp[F][V] << '\n';
    vector<int> path;
    for (int i = F, j = V; i;) {
        if (take[i][j]) {
            path.push_back(j);
            i--;
        }
        j--;
    }
    reverse(path.begin(), path.end());
    for (int i = 0; i < F; i++)
        cout << path[i] << (i + 1 == F ? '\n' : ' ');

    return 0;
}
```

### 实现提醒

必须放完所有花；价值可能为负；输出方案也需核对最优值。

## P1858 多人背包

原题：[P1858](https://www.luogu.com.cn/problem/P1858)

### 思路

每个容量维护前 K 大方案价值，归并不取与取当前物品的两份有序列表。相同价值、不同清单分别保留。这里求至少存在 K 种装满方案时的最优和；不足 K 种的输出原题未规定，详细题解明确标注。

### 复杂度

时间 O(NVK)，空间 O(VK)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int K, V, N;
    cin >> K >> V >> N;
    vector<vector<long long>> dp(V + 1);
    dp[0] = {0};
    for (int i = 0; i < N; i++) {
        int w;
        long long value;
        cin >> w >> value;
        for (int capacity = V; capacity >= w; capacity--) {
            const auto &left = dp[capacity];
            const auto &right = dp[capacity - w];
            vector<long long> next;
            int a = 0, b = 0;
            while ((int)next.size() < K && (a < (int)left.size() || b < (int)right.size())) {
                if (b == (int)right.size() || (a < (int)left.size() && left[a] >= right[b] + value))
                    next.push_back(left[a++]);
                else
                    next.push_back(right[b++] + value);
            }
            dp[capacity].swap(next);
        }
    }
    if ((int)dp[V].size() < K)
        return 0;
    cout << accumulate(dp[V].begin(), dp[V].end(), 0LL) << '\n';

    return 0;
}
```

### 实现提醒

恰好装满；容量倒序；等值不同清单不去重；不存在的方案不用零填充。

## P1878 舞蹈课

原题：[P1878](https://www.luogu.com.cn/problem/P1878)

### 思路

用双向链表表示还在队伍中的人，把相邻异性对按技术差、左端编号放入最小堆。弹出时检查是否仍相邻，删除有效的一对，并加入新产生的邻接对。

### 复杂度

时间 O(n log n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string gender;
    cin >> n >> gender;
    vector<int> a(n), left(n), right(n);
    vector<char> alive(n, 1);
    for (int &x : a)
        cin >> x;
    for (int i = 0; i < n; i++) {
        left[i] = i - 1;
        right[i] = i + 1 < n ? i + 1 : -1;
    }
    using P = tuple<int, int, int>;
    priority_queue<P, vector<P>, greater<P>> heap;
    auto push = [&](int l, int r) {
        if (l >= 0 && r >= 0 && gender[l] != gender[r])
            heap.push({abs(a[l] - a[r]), l, r});
    };
    for (int i = 1; i < n; i++)
        push(i - 1, i);
    vector<pair<int, int>> ans;
    while (!heap.empty()) {
        auto [diff, l, r] = heap.top();
        heap.pop();
        if (!alive[l] || !alive[r] || right[l] != r)
            continue;
        ans.push_back({l + 1, r + 1});
        alive[l] = alive[r] = 0;
        int L = left[l], R = right[r];
        if (L >= 0)
            right[L] = R;
        if (R >= 0)
            left[R] = L;
        push(L, R);
    }
    cout << ans.size() << '\n';
    for (auto [l, r] : ans)
        cout << l << ' ' << r << '\n';

    return 0;
}
```

### 实现提醒

技术差取绝对值；同差按左端编号；堆内过期对必须跳过。

## P1883 三分 / 函数 / [ICPC 2010 Chengdu R] Error Curves

原题：[P1883](https://www.luogu.com.cn/problem/P1883)

### 思路

每个二次函数在定义区间上凸，它们的逐点最大值也凸。对最大值函数在 [0,1000] 上三分，收缩到最小值附近，再输出函数值。

### 复杂度

时间 O(T·n·迭代次数)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        cin >> n;
        vector<array<double, 3>> a(n);
        for (auto &v : a)
            cin >> v[0] >> v[1] >> v[2];
        auto value = [&](double x) {
            double answer = -1e100;
            for (auto v : a)
                answer = max(answer, (v[0] * x + v[1]) * x + v[2]);
            return answer;
        };
        double l = 0, r = 1000;
        for (int i = 0; i < 120; i++) {
            double x = (2 * l + r) / 3, y = (l + 2 * r) / 3;
            if (value(x) < value(y))
                r = y;
            else
                l = x;
        }
        cout << fixed << setprecision(4) << value((l + r) / 2) << '\n';
    }

    return 0;
}
```

### 实现提醒

评估的是所有二次函数的最大值；搜索区间 [0,1000]；输出四位小数。

## P1937 Barn Allocation G

原题：[P1937](https://www.luogu.com.cn/problem/P1937)

### 思路

优先考虑结束较早的申请，并列时优先起点较晚的。若申请区间内剩余容量最小值大于零，就接受并把整段容量减一；线段树维护区间最小值和区间加。

### 复杂度

时间 O((n+m) log n+m log m)，空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct MinTree {
    int n;
    vector<long long> value, tag;
    MinTree(const vector<long long> &a) : n(a.size()), value(4 * n), tag(4 * n) {
        build(1, 0, n - 1, a);
    }
    void build(int p, int l, int r, const vector<long long> &a) {
        if (l == r) {
            value[p] = a[l];
            return;
        }
        int m = (l + r) / 2;
        build(p * 2, l, m, a);
        build(p * 2 + 1, m + 1, r, a);
        value[p] = min(value[p * 2], value[p * 2 + 1]);
    }
    void apply(int p, long long x) {
        value[p] += x;
        tag[p] += x;
    }
    void push(int p) {
        if (tag[p]) {
            apply(p * 2, tag[p]);
            apply(p * 2 + 1, tag[p]);
            tag[p] = 0;
        }
    }
    void add(int p, int l, int r, int a, int b, long long x) {
        if (a <= l && r <= b) {
            apply(p, x);
            return;
        }
        push(p);
        int m = (l + r) / 2;
        if (a <= m)
            add(p * 2, l, m, a, b, x);
        if (b > m)
            add(p * 2 + 1, m + 1, r, a, b, x);
        value[p] = min(value[p * 2], value[p * 2 + 1]);
    }
    long long query(int p, int l, int r, int a, int b) {
        if (a <= l && r <= b)
            return value[p];
        push(p);
        int m = (l + r) / 2;
        long long ans = LLONG_MAX / 4;
        if (a <= m)
            ans = min(ans, query(p * 2, l, m, a, b));
        if (b > m)
            ans = min(ans, query(p * 2 + 1, m + 1, r, a, b));
        return ans;
    }
    void add(int l, int r, long long x) { add(1, 0, n - 1, l, r, x); }
    long long query(int l, int r) { return query(1, 0, n - 1, l, r); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n);
    for (auto &x : a)
        cin >> x;
    vector<pair<int, int>> requests(m);
    for (auto &[r, l] : requests) {
        cin >> l >> r;
        l--;
        r--;
    }
    sort(requests.begin(), requests.end(), [](auto a, auto b) {
        if (a.first != b.first)
            return a.first < b.first;
        return a.second > b.second;
    });
    MinTree tree(a);
    int ans = 0;
    for (auto [r, l] : requests)
        if (tree.query(l, r) > 0) {
            ans++;
            tree.add(l, r, -1);
        }
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

每个申请会占整段容量；并列右端优先更晚左端；查询大于零才接受。

## P1949 聪明的打字员

原题：[P1949](https://www.luogu.com.cn/problem/P1949)

### 思路

相同密码在不同光标位置的下一步不同，必须把六位密码与光标位置一起编码。六种按键均为一步，BFS 首次遇到目标密码时就是最少击键次数，目标光标任意。

### 复杂度

时间 O(6·10^6)，空间 O(6·10^6)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;
    int start = stoi(s), goal = stoi(t);
    if (start == goal) {
        cout << 0 << '\n';
        return 0;
    }
    int power[6] = {100000, 10000, 1000, 100, 10, 1};
    vector<unsigned char> distance(6000000, 255);
    vector<int> queue;
    queue.reserve(6000000);
    queue.push_back(start * 6);
    distance[start * 6] = 0;
    for (size_t front = 0; front < queue.size(); front++) {
        int state = queue[front], code = state / 6, p = state % 6, depth = distance[state];
        if (code == goal) {
            cout << depth << '\n';
            return 0;
        }
        auto push = [&](int next) {
            if (distance[next] == 255) {
                distance[next] = depth + 1;
                queue.push_back(next);
            }
        };
        if (p)
            push(code * 6 + p - 1);
        if (p < 5)
            push(code * 6 + p + 1);
        int digit = code / power[p] % 10;
        if (digit < 9)
            push((code + power[p]) * 6 + p);
        if (digit > 0)
            push((code - power[p]) * 6 + p);
        for (int q : {0, 5}) {
            int other = code / power[q] % 10;
            int next = code + (other - digit) * power[p] + (digit - other) * power[q];
            push(next * 6 + p);
        }
    }

    return 0;
}
```

### 实现提醒

密码与光标共同编码；up/down 不循环；允许前导零；目标光标任意。

## P1967 货车运输

原题：[P1967](https://www.luogu.com.cn/problem/P1967)

### 思路

按边权降序做 Kruskal，得到最大生成森林。原图两点间能承受的最大瓶颈，等于森林中路径最小边。用倍增维护祖先和沿途最小值回答多次查询。

### 复杂度

时间 O(m log m+(n+q) log n)，空间 O(m+n log n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, size;
    explicit DSU(int n) : p(n), size(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    bool join(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        p[b] = a;
        size[a] += size[b];
        return true;
    }
};

struct TreePaths {
    int n, levels;
    vector<int> depth, root;
    vector<vector<int>> up;
    vector<vector<long long>> minimum;
    TreePaths(const vector<vector<pair<int, long long>>> &g)
        : n(g.size()), levels(1), depth(n, -1), root(n) {
        while ((1 << levels) <= n)
            levels++;
        up.assign(levels, vector<int>(n));
        minimum.assign(levels, vector<long long>(n, LLONG_MAX));
        for (int start = 0; start < n; start++)
            if (depth[start] < 0) {
                depth[start] = 0;
                root[start] = start;
                for (int j = 0; j < levels; j++)
                    up[j][start] = start;
                vector<int> q = {start};
                for (int i = 0; i < (int)q.size(); i++) {
                    int v = q[i];
                    for (auto [u, w] : g[v])
                        if (depth[u] < 0) {
                            depth[u] = depth[v] + 1;
                            root[u] = start;
                            up[0][u] = v;
                            minimum[0][u] = w;
                            for (int j = 1; j < levels; j++) {
                                up[j][u] = up[j - 1][up[j - 1][u]];
                                minimum[j][u] =
                                    min(minimum[j - 1][u], minimum[j - 1][up[j - 1][u]]);
                            }
                            q.push_back(u);
                        }
                }
            }
    }
    int lca(int a, int b) const {
        if (depth[a] < depth[b])
            swap(a, b);
        int difference = depth[a] - depth[b];
        for (int j = 0; j < levels; j++)
            if ((difference >> j) & 1)
                a = up[j][a];
        if (a == b)
            return a;
        for (int j = levels - 1; j >= 0; j--)
            if (up[j][a] != up[j][b]) {
                a = up[j][a];
                b = up[j][b];
            }
        return up[0][a];
    }
    long long bottleneck(int a, int b) const {
        if (a == b)
            return 0;
        long long answer = LLONG_MAX;
        if (depth[a] < depth[b])
            swap(a, b);
        int difference = depth[a] - depth[b];
        for (int j = 0; j < levels; j++)
            if ((difference >> j) & 1) {
                answer = min(answer, minimum[j][a]);
                a = up[j][a];
            }
        if (a == b)
            return answer;
        for (int j = levels - 1; j >= 0; j--)
            if (up[j][a] != up[j][b]) {
                answer = min({answer, minimum[j][a], minimum[j][b]});
                a = up[j][a];
                b = up[j][b];
            }
        return min({answer, minimum[0][a], minimum[0][b]});
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<tuple<long long, int, int>> edges(m);
    for (auto &[w, a, b] : edges) {
        cin >> a >> b >> w;
        a--;
        b--;
    }
    sort(edges.rbegin(), edges.rend());
    DSU d(n);
    vector<vector<pair<int, long long>>> g(n);
    for (auto [w, a, b] : edges)
        if (d.join(a, b)) {
            g[a].push_back({b, w});
            g[b].push_back({a, w});
        }
    TreePaths paths(g);
    int q;
    cin >> q;
    while (q--) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        if (d.find(a) != d.find(b))
            cout << -1 << '\n';
        else
            cout << paths.bottleneck(a, b) << '\n';
    }

    return 0;
}
```

### 实现提醒

最大生成树按权值降序；查询取路径最小边；先判断是否连通。

## P1990 覆盖墙壁

原题：[P1990](https://www.luogu.com.cn/problem/P1990)

### 思路

完整覆盖数满足 f[n]=2f[n−1]+f[n−3]，初值 f[0]=f[1]=1、f[2]=2。由完整状态与两种对称缺角状态转移并消元得到，按模 10000 递推。

### 复杂度

时间 O(n)，空间 O(n)，也可滚动到 O(1)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> f(max(n + 1, 3));
    f[0] = f[1] = 1;
    f[2] = 2;
    for (int i = 3; i <= n; i++)
        f[i] = (2 * f[i - 1] + f[i - 3]) % 10000;
    cout << f[n] << '\n';

    return 0;
}
```

### 实现提醒

初值包含空墙；模数 10000；横竖砖与 L 形缺角不能漏。

## P1996 约瑟夫问题

原题：[P1996](https://www.luogu.com.cn/problem/P1996)

### 思路

保存仍在圈中的编号，当前报数起点为位置 p。本轮删除位置 (p+m−1)%人数，删除后该位置自动指向下一位报数者，依次输出。

### 复杂度

时间 O(n²)，空间 O(n)，适用于本题的小规模人数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;
    vector<int> a(n);
    iota(a.begin(), a.end(), 1);
    long long p = 0;
    while (!a.empty()) {
        p = (p + m - 1) % a.size();
        cout << a[p] << (a.size() == 1 ? '\n' : ' ');
        a.erase(a.begin() + p);
    }

    return 0;
}
```

### 实现提醒

报第 m 人要加 m−1；删除后从下一人开始；编号从 1 输出。

## P2024 食物链

原题：[P2024](https://www.luogu.com.cn/problem/P2024)

### 思路

为每种动物建立本类、它吃的类、吃它的类三个副本。每句话先查矛盾，合法时合并三组对应关系；不合法只计数，不改并查集。

### 复杂度

时间 O((n+k)α(n))，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, size;
    explicit DSU(int n) : p(n), size(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    bool join(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        p[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    DSU d(3 * n);
    int ans = 0;
    while (k--) {
        int type, x, y;
        cin >> type >> x >> y;
        x--;
        y--;
        if (x < 0 || x >= n || y < 0 || y >= n) {
            ans++;
            continue;
        }
        if (type == 1) {
            if (d.find(x) == d.find(y + n) || d.find(x) == d.find(y + 2 * n)) {
                ans++;
                continue;
            }
            for (int j = 0; j < 3; j++)
                d.join(x + j * n, y + j * n);
        } else {
            if (d.find(x) == d.find(y) || d.find(x) == d.find(y + 2 * n)) {
                ans++;
                continue;
            }
            d.join(x, y + n);
            d.join(x + n, y + 2 * n);
            d.join(x + 2 * n, y);
        }
    }
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

三个副本方向一致；假话不合并；编号越界也是假话。

## P2036 PERKET

原题：[P2036](https://www.luogu.com.cn/problem/P2036)

### 思路

每种配料选或不选，枚举所有非空子集。酸度连乘、苦度相加，比较二者差的绝对值，取最小。

### 复杂度

时间 O(n·2^n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> s(n), b(n);
    for (int i = 0; i < n; i++)
        cin >> s[i] >> b[i];
    long long ans = LLONG_MAX;
    for (int mask = 1; mask < (1 << n); mask++) {
        long long sour = 1, bitter = 0;
        for (int i = 0; i < n; i++)
            if ((mask >> i) & 1) {
                sour *= s[i];
                bitter += b[i];
            }
        ans = min(ans, llabs(sour - bitter));
    }
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

不枚举空集；酸度乘积初始为 1，苦度和初始为 0。

## P2080 增进感情

原题：[P2080](https://www.luogu.com.cn/problem/P2080)

### 思路

每件事贡献差值 a−b 和总值 a+b。用 0/1 背包维护每个差值下能得到的最大总值，最后在总值达到 v 的状态中取差值绝对值最小者。

### 复杂度

时间 O(n²A)，空间 O(nA)，A 为单项差值的上界。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, v;
    cin >> n >> v;
    vector<pair<int, int>> events(n);
    int bound = 0;
    for (auto &[a, b] : events) {
        cin >> a >> b;
        bound += abs(a - b);
    }
    const int neg = INT_MIN / 4;
    vector<int> dp(2 * bound + 1, neg);
    dp[bound] = 0;
    for (auto [a, b] : events) {
        auto next = dp;
        int difference = a - b;
        for (int i = 0; i < (int)dp.size(); i++)
            if (dp[i] != neg && i + difference >= 0 && i + difference < (int)dp.size())
                next[i + difference] = max(next[i + difference], dp[i] + a + b);
        dp.swap(next);
    }
    int ans = INT_MAX;
    for (int i = 0; i < (int)dp.size(); i++)
        if (dp[i] >= v)
            ans = min(ans, abs(i - bound));
    cout << (ans == INT_MAX ? -1 : ans) << '\n';

    return 0;
}
```

### 实现提醒

好感可负；保留最大总和而非最小；转移使用旧数组，防止重复选事件。

## P2085 最小函数值

原题：[P2085](https://www.luogu.com.cn/problem/P2085)

### 思路

每个二次函数在正整数 x 上给出一个递增序列。先把各函数的 f(1) 入堆，弹出最小值后输出，并把同一函数的下一个 x 对应值放回。

### 复杂度

时间 O((n+m) log n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<array<long long, 3>> f(n);
    for (auto &v : f)
        cin >> v[0] >> v[1] >> v[2];
    auto value = [&](int i, long long x) { return f[i][0] * x * x + f[i][1] * x + f[i][2]; };
    using Item = tuple<long long, int, int>;
    priority_queue<Item, vector<Item>, greater<Item>> q;
    for (int i = 0; i < n; i++)
        q.push({value(i, 1), i, 1});
    for (int step = 0; step < m; step++) {
        auto [v, i, x] = q.top();
        q.pop();
        cout << v << (step + 1 == m ? '\n' : ' ');
        q.push({value(i, x + 1), i, x + 1});
    }

    return 0;
}
```

### 实现提醒

依赖函数单调；重复值保留；堆中保存函数身份和 x。

## P2163 园丁的烦恼

原题：[P2163](https://www.luogu.com.cn/problem/P2163)

### 思路

将闭矩形计数拆为四个左下无穷前缀。按横坐标排序查询事件和树木，扫描时用树状数组维护已加入点的纵坐标数量，按符号累加答案。

### 复杂度

时间 O((n+m) log(n+m))，空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> t;
    explicit Fenwick(int n) : n(n), t(n + 1) {}
    void add(int x, long long v) {
        for (; x <= n; x += x & -x)
            t[x] += v;
    }
    long long sum(int x) const {
        long long s = 0;
        for (; x; x -= x & -x)
            s += t[x];
        return s;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<pair<int, int>> points(n);
    vector<int> ys;
    for (auto &[x, y] : points) {
        cin >> x >> y;
        ys.push_back(y);
    }
    sort(points.begin(), points.end());
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    struct E {
        int x, y, id, sign;
    };
    vector<E> events;
    for (int i = 0; i < m; i++) {
        int a, b, c, d;
        cin >> a >> b >> c >> d;
        events.push_back({c, d, i, 1});
        events.push_back({a - 1, d, i, -1});
        events.push_back({c, b - 1, i, -1});
        events.push_back({a - 1, b - 1, i, 1});
    }
    sort(events.begin(), events.end(), [](E a, E b) { return a.x < b.x; });
    Fenwick bit(ys.size());
    vector<long long> ans(m);
    int p = 0;
    for (auto e : events) {
        while (p < n && points[p].first <= e.x) {
            int r = lower_bound(ys.begin(), ys.end(), points[p].second) - ys.begin() + 1;
            bit.add(r, 1);
            p++;
        }
        int r = upper_bound(ys.begin(), ys.end(), e.y) - ys.begin();
        ans[e.id] += e.sign * bit.sum(r);
    }
    for (auto x : ans)
        cout << x << '\n';

    return 0;
}
```

### 实现提醒

闭区间使用 a−1、b−1；同横坐标的点先加入；重复点分别计数。

## P2169 正则表达式

原题：[P2169](https://www.luogu.com.cn/problem/P2169)

### 思路

局域网内部互相可达，传输费用为零。先缩强连通分量，只保留跨分量的原权边，再求 1 所在分量到 n 所在分量的最短路。

### 复杂度

时间 O((n+m) log n)，空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SCC {
    int n, count = 0;
    vector<vector<int>> g, rev;
    vector<int> component;
    explicit SCC(int n) : n(n), g(n), rev(n), component(n, -1) {}
    void edge(int a, int b) {
        g[a].push_back(b);
        rev[b].push_back(a);
    }
    void build() {
        vector<char> seen(n);
        vector<int> order;
        for (int start = 0; start < n; start++)
            if (!seen[start]) {
                vector<pair<int, int>> st = {{start, 0}};
                seen[start] = true;
                while (!st.empty()) {
                    int v = st.back().first;
                    int &i = st.back().second;
                    if (i < (int)g[v].size()) {
                        int u = g[v][i++];
                        if (!seen[u]) {
                            seen[u] = true;
                            st.push_back({u, 0});
                        }
                    } else {
                        order.push_back(v);
                        st.pop_back();
                    }
                }
            }
        reverse(order.begin(), order.end());
        for (int start : order)
            if (component[start] < 0) {
                vector<int> st = {start};
                component[start] = count;
                while (!st.empty()) {
                    int v = st.back();
                    st.pop_back();
                    for (int u : rev[v])
                        if (component[u] < 0) {
                            component[u] = count;
                            st.push_back(u);
                        }
                }
                count++;
            }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    SCC s(n);
    vector<tuple<int, int, int>> edges;
    while (m--) {
        int a, b, w;
        cin >> a >> b >> w;
        a--;
        b--;
        s.edge(a, b);
        edges.push_back({a, b, w});
    }
    s.build();
    vector<vector<pair<int, int>>> g(s.count);
    for (auto [a, b, w] : edges)
        if (s.component[a] != s.component[b])
            g[s.component[a]].push_back({s.component[b], w});
    const long long inf = LLONG_MAX / 4;
    vector<long long> d(s.count, inf);
    int start = s.component[0], goal = s.component[n - 1];
    d[start] = 0;
    priority_queue<pair<long long, int>, vector<pair<long long, int>>,
                   greater<pair<long long, int>>>
        q;
    q.push({0, start});
    while (!q.empty()) {
        auto [dist, v] = q.top();
        q.pop();
        if (dist != d[v])
            continue;
        for (auto [u, w] : g[v])
            if (d[u] > dist + w) {
                d[u] = dist + w;
                q.push({d[u], u});
            }
    }
    cout << d[goal] << '\n';

    return 0;
}
```

### 实现提醒

只把强连通分量内部费用置零；优先队列过期项跳过。

## P2180 摆石子

原题：[P2180](https://www.luogu.com.cn/problem/P2180)

### 思路

行列压缩后，同一列的石子可以尽量对齐。最优形状可取一个满矩形，再在一行或一列上放剩余石子。枚举满列高度 h，令 q=K/h、r=K%h，贡献为 C(h,2)C(q,2)+qC(r,2)，再交换两维检查。

### 复杂度

时间 O(N+M)，空间 O(1)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m, k;
    cin >> n >> m >> k;
    auto choose2 = [](long long x) { return x * (x - 1) / 2; };
    long long answer = 0;
    for (int direction = 0; direction < 2; direction++) {
        for (long long h = 1; h <= n; h++) {
            long long q = k / h, r = k % h;
            if (q > m || (r && q == m))
                continue;
            answer = max(answer, choose2(h) * choose2(q) + q * choose2(r));
        }
        swap(n, m);
    }
    cout << answer << '\n';

    return 0;
}
```

### 实现提醒

两个方向都检查；短列需要额外列位置；取两行两列，使用组合数。

