## P2303 Longge 的问题

原题：[P2303](https://www.luogu.com.cn/problem/P2303)

### 思路

若 gcd(i,n)=d，约去 d 后共有 φ(n/d) 个合法 i，所以答案为 Σ(d|n) d·φ(n/d)。成对枚举约数并计算欧拉函数即可。

### 复杂度

时间 O(sqrt n + τ(n)·ω(n))，空间 O(ω(n))，τ 是约数数，ω 是不同质因数数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    long long x = n;
    vector<long long> primes;
    for (long long p = 2; p <= x / p; p++)
        if (x % p == 0) {
            primes.push_back(p);
            while (x % p == 0)
                x /= p;
        }
    if (x > 1)
        primes.push_back(x);
    auto phi = [&](long long x) {
        long long r = x;
        for (long long p : primes)
            if (x % p == 0)
                r = r / p * (p - 1);
        return r;
    };
    long long ans = 0;
    for (long long d = 1; d <= n / d; d++)
        if (n % d == 0) {
            ans += d * phi(n / d);
            if (d != n / d)
                ans += (n / d) * phi(d);
        }
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

平方因数只算一次；φ(1)=1；先除再乘。

## P2324 骑士精神

原题：[P2324](https://www.luogu.com.cn/problem/P2324)

### 思路

逐步增加允许移动次数，用“不在目标位置的非空棋子数”作为剩余步数下界。每次交换空格和一个马步可达棋子，跳过立即撤销上一步的移动。最多搜索到十五步。

### 复杂度

最坏指数时间，深度最多十五且使用可采纳下界剪枝；空间 O(25+15)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    string goal = "111110111100*110000100000";
    while (T--) {
        string a;
        for (int i = 0; i < 5; i++) {
            string row;
            cin >> row;
            a += row;
        }
        int hole = a.find('*'), h = 0;
        for (int i = 0; i < 25; i++)
            if (a[i] != '*' && a[i] != goal[i])
                h++;
        vector<vector<int>> g(25);
        for (int i = 0; i < 25; i++)
            for (auto [dx, dy] : vector<pair<int, int>>{
                     {1, 2}, {1, -2}, {-1, 2}, {-1, -2}, {2, 1}, {2, -1}, {-2, 1}, {-2, -1}}) {
                int x = i / 5 + dx, y = i % 5 + dy;
                if (x >= 0 && x < 5 && y >= 0 && y < 5)
                    g[i].push_back(x * 5 + y);
            }
        function<bool(int, int, int, int, int)> dfs = [&](int p, int prev, int used, int lower,
                                                          int limit) {
            if (used + lower > limit)
                return false;
            if (a == goal)
                return true;
            if (used == limit)
                return false;
            vector<pair<int, int>> moves;
            for (int u : g[p])
                if (u != prev)
                    moves.push_back({lower - (a[u] != goal[u]) + (a[u] != goal[p]), u});
            sort(moves.begin(), moves.end());
            for (auto [nh, u] : moves) {
                swap(a[p], a[u]);
                bool found = dfs(u, p, used + 1, nh, limit);
                swap(a[p], a[u]);
                if (found)
                    return true;
            }
            return false;
        };
        int parity = (hole / 5 + hole % 5) % 2, ans = -1;
        for (int limit = h; limit <= 15; limit++)
            if (limit % 2 == parity && dfs(hole, -1, 0, h, limit)) {
                ans = limit;
                break;
            }
        cout << ans << '\n';
    }

    return 0;
}
```

### 实现提醒

下界不计空格；每次交换后恢复；目标中心为 *。

## P2325 王室联邦

原题：[P2325](https://www.luogu.com.cn/problem/P2325)

### 思路

后序遍历中把尚未归省的点留在栈上。处理一个孩子后，若当前根累计的待分配点不少于 B，就把这一段整体划为一省，以当前根为省会。最后剩余点并入最后一省。

### 复杂度

时间 O(n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, B;
    cin >> n >> B;
    vector<vector<int>> g(n);
    for (int i = 1; i < n; i++) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<int> st, belong(n), capitals;
    function<void(int, int)> dfs = [&](int v, int p) {
        int base = st.size();
        for (int u : g[v])
            if (u != p) {
                dfs(u, v);
                if ((int)st.size() - base >= B) {
                    capitals.push_back(v);
                    int id = capitals.size();
                    while ((int)st.size() > base) {
                        belong[st.back()] = id;
                        st.pop_back();
                    }
                }
            }
        st.push_back(v);
    };
    dfs(0, -1);
    if (capitals.empty())
        capitals.push_back(0);
    for (int v : st)
        belong[v] = capitals.size();
    cout << capitals.size() << '\n';
    for (int i = 0; i < n; i++)
        cout << belong[i] << (i + 1 == n ? '\n' : ' ');
    for (int i = 0; i < (int)capitals.size(); i++)
        cout << capitals[i] + 1 << (i + 1 == (int)capitals.size() ? '\n' : ' ');

    return 0;
}
```

### 实现提醒

省会可以在省外；只弹当前根积累的栈段；末尾剩余不能独立形成过小省。

## P2341 受欢迎的牛 G

原题：[P2341](https://www.luogu.com.cn/problem/P2341)

### 思路

能被所有牛到达的顶点必须位于缩点图的汇分量。只有一个出度为零的分量时，答案是它的大小；有多个时答案为零。

### 复杂度

时间 O(n+m)，空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SCC {
    int n, count = 0;
    vector<vector<int>> g, rev;
    vector<int> component;
    explicit SCC(int n) : n(n), g(n), rev(n), component(n, -1) {}
    void edge(int a, int b) {
        g[a].push_back(b);
        rev[b].push_back(a);
    }
    void build() {
        vector<char> seen(n);
        vector<int> order;
        for (int start = 0; start < n; start++)
            if (!seen[start]) {
                vector<pair<int, int>> st = {{start, 0}};
                seen[start] = true;
                while (!st.empty()) {
                    int v = st.back().first;
                    int &i = st.back().second;
                    if (i < (int)g[v].size()) {
                        int u = g[v][i++];
                        if (!seen[u]) {
                            seen[u] = true;
                            st.push_back({u, 0});
                        }
                    } else {
                        order.push_back(v);
                        st.pop_back();
                    }
                }
            }
        reverse(order.begin(), order.end());
        for (int start : order)
            if (component[start] < 0) {
                vector<int> st = {start};
                component[start] = count;
                while (!st.empty()) {
                    int v = st.back();
                    st.pop_back();
                    for (int u : rev[v])
                        if (component[u] < 0) {
                            component[u] = count;
                            st.push_back(u);
                        }
                }
                count++;
            }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    SCC s(n);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        s.edge(a - 1, b - 1);
    }
    s.build();
    vector<int> size(s.count), in(s.count), out(s.count);
    for (int v = 0; v < n; v++) {
        size[s.component[v]]++;
        for (int u : s.g[v])
            if (s.component[u] != s.component[v]) {
                out[s.component[v]]++;
                in[s.component[u]]++;
            }
    }
    int target = -1;
    for (int c = 0; c < s.count; c++)
        if (!out[c]) {
            if (target != -1) {
                cout << 0 << '\n';
                return 0;
            }
            target = c;
        }
    cout << size[target] << '\n';
    return 0;
}
```

### 实现提醒

判断出度，不是入度；多个汇分量时输出 0。

## P2375 动物园

原题：[P2375](https://www.luogu.com.cn/problem/P2375)

### 思路

先用前缀函数计算每个前缀的 border 链长度，再用第二次 KMP 扫描维护不超过当前长度一半的最长 border。它的整条 border 链都合法，按题意将数量加一后相乘。

### 复杂度

每组时间 O(n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> prefix(const string &s) {
    vector<int> p(s.size());
    for (int i = 1; i < (int)s.size(); i++) {
        int j = p[i - 1];
        while (j && s[i] != s[j])
            j = p[j - 1];
        if (s[i] == s[j])
            j++;
        p[i] = j;
    }
    return p;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tests;
    cin >> tests;
    while (tests--) {
        string s;
        cin >> s;
        int n = s.size();
        auto p = prefix(s);
        vector<int> count(n + 1);
        for (int len = 1; len <= n; len++)
            count[len] = count[p[len - 1]] + 1;
        long long ans = 1;
        int j = 0;
        for (int len = 2; len <= n; len++) {
            while (j && s[len - 1] != s[j])
                j = p[j - 1];
            if (s[len - 1] == s[j])
                j++;
            while (2 * j > len)
                j = p[j - 1];
            ans = ans * (count[j] + 1) % 1000000007;
        }
        cout << ans << '\n';
    }

    return 0;
}
```

### 实现提醒

count[0]=0；先限制不重叠，再乘数量加一；模数为 1000000007。

## P2424 约数和

原题：[P2424](https://www.luogu.com.cn/problem/P2424)

### 思路

约数 d 在 1 到 N 中出现 floor(N/d) 次，因此前缀约数和为 Σ d·floor(N/d)。同一商对应一段连续的 d，用等差数列求和，区间答案是 F(y)−F(x−1)。

### 复杂度

时间 O(sqrt y)，空间 O(1)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x, y;
    cin >> x >> y;
    auto solve = [](long long n) {
        __int128 ans = 0;
        for (long long l = 1, r; l <= n; l = r + 1) {
            long long q = n / l;
            r = n / q;
            ans += (__int128)(l + r) * (r - l + 1) / 2 * q;
        }
        return ans;
    };
    __int128 v = solve(y) - solve(x - 1);
    string s;
    do {
        s.push_back('0' + v % 10);
        v /= 10;
    } while (v);
    reverse(s.begin(), s.end());
    cout << s << '\n';

    return 0;
}
```

### 实现提醒

右端是 N/(N/l)；x=1 时前缀为 0；乘积先转宽整数。

## P2441 角色属性树

原题：[P2441](https://www.luogu.com.cn/problem/P2441)

### 思路

一次静态 DFS 中，为每个质因子维护当前祖先链上最近的结点。查询点的所有质因子取深度最大的祖先。修改最多五十次，可以修改后延迟重建全部答案。

### 复杂度

设不同值数 U、每值不同质因子最多 F、修改数 C≤50，重建总计 O((C+1)nF)，试除最坏 O(U√A/log A)；空间 O(nF+k+UF)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

long long pow32(long long a, long long d, long long mod) {
    long long r = 1;
    for (; d; d >>= 1, a = a * a % mod)
        if (d & 1)
            r = r * a % mod;
    return r;
}
bool prime32(int x) {
    if (x < 2)
        return false;
    for (int p : {2, 3, 5, 7, 11}) {
        if (x % p == 0)
            return x == p;
    }
    int s = 0;
    long long d = x - 1;
    while (!(d & 1)) {
        d >>= 1;
        s++;
    }
    for (int a : {2, 3, 5, 7}) {
        long long y = pow32(a, d, x);
        if (y == 1 || y == x - 1)
            continue;
        bool ok = false;
        for (int i = 1; i < s; i++) {
            y = y * y % x;
            if (y == x - 1) {
                ok = true;
                break;
            }
        }
        if (!ok)
            return false;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int &x : a)
        cin >> x;
    vector<vector<int>> children(n);
    vector<int> parent(n, -1);
    for (int i = 1; i < n; i++) {
        int x, y;
        cin >> x >> y;
        x--;
        y--;
        children[x].push_back(y);
        parent[y] = x;
    }
    struct Op {
        int type, u, x;
    };
    vector<Op> ops(k);
    vector<int> values = a;
    for (auto &op : ops) {
        cin >> op.type >> op.u;
        op.u--;
        op.x = 0;
        if (op.type == 2) {
            cin >> op.x;
            values.push_back(op.x);
        }
    }
    vector<int> primes;
    vector<bool> composite(46341);
    for (int i = 2; i <= 46340; i++)
        if (!composite[i]) {
            primes.push_back(i);
            if (1LL * i * i <= 46340)
                for (int j = i * i; j <= 46340; j += i)
                    composite[j] = 1;
        }
    unordered_map<int, int> profileId, primeId;
    vector<vector<int>> profiles;
    for (int value : values)
        if (!profileId.count(value)) {
            int x = value;
            vector<int> factor;
            if (prime32(x))
                factor.push_back(x);
            else {
                for (int p : primes) {
                    if (1LL * p * p > x)
                        break;
                    if (x % p == 0) {
                        factor.push_back(p);
                        while (x % p == 0)
                            x /= p;
                        if (prime32(x))
                            break;
                    }
                }
                if (x > 1)
                    factor.push_back(x);
            }
            vector<int> ids;
            for (int p : factor) {
                if (!primeId.count(p))
                    primeId[p] = primeId.size();
                ids.push_back(primeId[p]);
            }
            profileId[value] = profiles.size();
            profiles.push_back(move(ids));
        }
    vector<int> current(n);
    for (int i = 0; i < n; i++)
        current[i] = profileId[a[i]];
    int root = find(parent.begin(), parent.end(), -1) - parent.begin();
    vector<int> depth(n), events, order = {root};
    for (int i = 0; i < n; i++)
        for (int u : children[order[i]]) {
            depth[u] = depth[order[i]] + 1;
            order.push_back(u);
        }
    vector<pair<int, bool>> stack = {{root, false}};
    while (!stack.empty()) {
        auto [v, leave] = stack.back();
        stack.pop_back();
        events.push_back(leave ? -v - 1 : v + 1);
        if (!leave) {
            stack.push_back({v, true});
            for (int u : children[v])
                stack.push_back({u, false});
        }
    }
    vector<int> answer(n), last(primeId.size(), -1);
    vector<array<int, 10>> saved(n);
    bool dirty = true;
    auto rebuild = [&]() {
        fill(last.begin(), last.end(), -1);
        for (int event : events) {
            int v = abs(event) - 1;
            auto &f = profiles[current[v]];
            if (event > 0) {
                int best = -1;
                for (int j = 0; j < (int)f.size(); j++) {
                    int p = f[j], u = last[p];
                    if (u >= 0 && (best < 0 || depth[u] > depth[best]))
                        best = u;
                    saved[v][j] = u;
                    last[p] = v;
                }
                answer[v] = best;
            } else
                for (int j = 0; j < (int)f.size(); j++)
                    last[f[j]] = saved[v][j];
        }
        dirty = false;
    };
    for (auto op : ops)
        if (op.type == 2) {
            current[op.u] = profileId[op.x];
            dirty = true;
        } else {
            if (dirty)
                rebuild();
            cout << (answer[op.u] < 0 ? -1 : answer[op.u] + 1) << '\n';
        }

    return 0;
}
```

### 实现提醒

只找严格祖先，先查询 last 再写自己；重复质因子只算一次；修改后查询前才重建。

## P2532 树屋阶梯

原题：[P2532](https://www.luogu.com.cn/problem/P2532)

### 思路

阶梯最外层的一块钢材把剩余阶梯分成左右两个独立部分，方案数满足 C_n=Σ C_iC_(n−1−i)，即 Catalan 数。用等价的相邻项乘除递推高精度计算。

### 复杂度

O(n) 次高精度小整数乘除，空间 O(答案位数)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Big {
    static const int base = 1000000000;
    vector<int> d;
    Big(long long x = 0) {
        do {
            d.push_back(x % base);
            x /= base;
        } while (x);
    }
    explicit Big(string s) {
        for (int r = s.size(); r > 0; r -= 9)
            d.push_back(stoi(s.substr(max(0, r - 9), min(9, r))));
        trim();
    }
    void trim() {
        while (d.size() > 1 && d.back() == 0)
            d.pop_back();
    }
    void multiply(long long x) {
        long long carry = 0;
        for (int &v : d) {
            long long z = v * x + carry;
            v = z % base;
            carry = z / base;
        }
        while (carry) {
            d.push_back(carry % base);
            carry /= base;
        }
        trim();
    }
    long long divide(long long x) {
        long long rem = 0;
        for (int i = (int)d.size() - 1; i >= 0; i--) {
            long long z = rem * base + d[i];
            d[i] = z / x;
            rem = z % x;
        }
        trim();
        return rem;
    }
    void add(long long x) {
        long long carry = x;
        for (int i = 0; carry; i++) {
            if (i == (int)d.size())
                d.push_back(0);
            long long z = d[i] + carry;
            d[i] = z % base;
            carry = z / base;
        }
    }
    void addBig(const Big &b) {
        int n = max(d.size(), b.d.size());
        d.resize(n, 0);
        long long carry = 0;
        for (int i = 0; i < n; i++) {
            long long z = (long long)d[i] + (i < (int)b.d.size() ? b.d[i] : 0) + carry;
            d[i] = z % base;
            carry = z / base;
        }
        if (carry)
            d.push_back(carry);
    }
    void subtract(const Big &b) {
        int borrow = 0;
        for (int i = 0; i < (int)d.size(); i++) {
            long long z = (long long)d[i] - (i < (int)b.d.size() ? b.d[i] : 0) - borrow;
            borrow = z < 0;
            if (borrow)
                z += base;
            d[i] = z;
        }
        trim();
    }
    friend ostream &operator<<(ostream &out, const Big &b) {
        out << b.d.back();
        for (int i = (int)b.d.size() - 2; i >= 0; i--)
            out << setw(9) << setfill('0') << b.d[i];
        return out;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    Big answer(1);
    for (int i = 1; i <= n; i++) {
        answer.multiply(4 * i - 2);
        answer.divide(i + 1);
    }
    cout << answer << '\n';

    return 0;
}
```

### 实现提醒

初始 C_0=1；不能用浮点近似；除法必须在乘法之后。

## P2536 病毒检测

原题：[P2536](https://www.luogu.com.cn/problem/P2536)

### 思路

令 dp[j] 表示模式当前前缀能否匹配 DNA 前 j 个字符。普通字符或 ? 从上一行 j−1 转移，* 则可不匹配字符，或在本行继续吞掉一个字符。

### 复杂度

时间 O(N·模式长度·DNA长度)，空间 O(DNA长度)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string pattern;
    int n;
    cin >> pattern >> n;
    int ans = 0;
    while (n--) {
        string s;
        cin >> s;
        vector<char> dp(s.size() + 1), next(s.size() + 1);
        dp[0] = 1;
        for (char c : pattern) {
            fill(next.begin(), next.end(), 0);
            if (c == '*') {
                next[0] = dp[0];
                for (int j = 1; j <= (int)s.size(); j++)
                    next[j] = dp[j] || next[j - 1];
            } else
                for (int j = 1; j <= (int)s.size(); j++)
                    next[j] = dp[j - 1] && (c == '?' || c == s[j - 1]);
            dp.swap(next);
        }
        ans += !dp.back();
    }
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

* 可匹配零个字符；星号行从左往右；输出不匹配的数量。

## P2568 GCD

原题：[P2568](https://www.luogu.com.cn/problem/P2568)

### 思路

若 gcd(x,y)=p，令 x=pa、y=pb，则 a、b 在一到 floor(n/p) 中互质。这个范围的有序互质对数为 2·Σφ(i)−1，筛出欧拉函数前缀和后对所有质数求和。

### 复杂度

时间 O(n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> phi(n + 1);
    vector<bool> composite(n + 1);
    vector<int> primes;
    phi[1] = 1;
    for (int i = 2; i <= n; i++) {
        if (!composite[i]) {
            primes.push_back(i);
            phi[i] = i - 1;
        }
        for (int p : primes) {
            long long x = 1LL * i * p;
            if (x > n)
                break;
            composite[x] = true;
            if (i % p == 0) {
                phi[x] = phi[i] * p;
                break;
            }
            phi[x] = phi[i] * (p - 1);
        }
    }
    for (int i = 1; i <= n; i++)
        phi[i] += phi[i - 1];
    long long ans = 0;
    for (int p : primes)
        ans += 2 * phi[n / p] - 1;
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

统计有序点对；φ(1)=1；前缀和和答案用 long long。

