## P2638 安全系统

原题：[P2638](https://www.luogu.com.cn/problem/P2638)

### 思路

把没有使用的零也看成放在一个额外储存区，分配 a 个相同零到 n+1 区有 C(n+a,n) 种。一的分配独立，答案为 C(n+a,n)·C(n+b,n)。

### 复杂度

时间 O(50²)，空间 O(50²)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, a, b;
    cin >> n >> a >> b;
    __int128 C[51][51]{};
    for (int i = 0; i <= 50; i++) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; j++)
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
    }
    __int128 ans = C[n + a][n] * C[n + b][n];
    string out;
    do {
        out += char('0' + ans % 10);
        ans /= 10;
    } while (ans);
    reverse(out.begin(), out.end());
    cout << out << '\n';

    return 0;
}
```

### 实现提醒

未用信号也参与一一对应；两种信号独立；答案不能只用 unsigned long long。

## P2656 采蘑菇

原题：[P2656](https://www.luogu.com.cn/problem/P2656)

### 思路

同一个强连通块里的每条边都能反复经过，将其衰减到零前的蘑菇总数计入块权。跨块边只能经过一次，保留初始数量，缩点后从起点做最长路。

### 复杂度

时间 O(n+m log W)，其中 W 为初始边权上界；空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SCC {
    int n, count = 0;
    vector<vector<int>> g, rev;
    vector<int> component;
    explicit SCC(int n) : n(n), g(n), rev(n), component(n, -1) {}
    void edge(int a, int b) {
        g[a].push_back(b);
        rev[b].push_back(a);
    }
    void build() {
        vector<char> seen(n);
        vector<int> order;
        for (int start = 0; start < n; start++)
            if (!seen[start]) {
                vector<pair<int, int>> st = {{start, 0}};
                seen[start] = true;
                while (!st.empty()) {
                    int v = st.back().first;
                    int &i = st.back().second;
                    if (i < (int)g[v].size()) {
                        int u = g[v][i++];
                        if (!seen[u]) {
                            seen[u] = true;
                            st.push_back({u, 0});
                        }
                    } else {
                        order.push_back(v);
                        st.pop_back();
                    }
                }
            }
        reverse(order.begin(), order.end());
        for (int start : order)
            if (component[start] < 0) {
                vector<int> st = {start};
                component[start] = count;
                while (!st.empty()) {
                    int v = st.back();
                    st.pop_back();
                    for (int u : rev[v])
                        if (component[u] < 0) {
                            component[u] = count;
                            st.push_back(u);
                        }
                }
                count++;
            }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    SCC s(n);
    struct E {
        int u, v, w, k;
    };
    vector<E> edges;
    for (int i = 0; i < m; i++) {
        int u, v, w;
        string k;
        cin >> u >> v >> w >> k;
        u--;
        v--;
        int rate = 0;
        auto dot = k.find('.');
        if (dot != string::npos && dot + 1 < k.size())
            rate = k[dot + 1] - '0';
        edges.push_back({u, v, w, rate});
        s.edge(u, v);
    }
    int start;
    cin >> start;
    start--;
    s.build();
    vector<long long> value(s.count), dp(s.count, LLONG_MIN / 4);
    vector<vector<pair<int, int>>> g(s.count);
    vector<int> in(s.count);
    for (auto e : edges) {
        int u = s.component[e.u], v = s.component[e.v];
        if (u == v) {
            long long w = e.w;
            while (w) {
                value[u] += w;
                w = w * e.k / 10;
            }
        } else {
            g[u].push_back({v, e.w});
            in[v]++;
        }
    }
    queue<int> q;
    for (int i = 0; i < s.count; i++)
        if (!in[i])
            q.push(i);
    dp[s.component[start]] = value[s.component[start]];
    long long ans = dp[s.component[start]];
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        ans = max(ans, dp[v]);
        for (auto [u, w] : g[v]) {
            if (dp[v] >= 0)
                dp[u] = max(dp[u], dp[v] + w + value[u]);
            if (!--in[u])
                q.push(u);
        }
    }
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

内部边累加全部衰减值；跨块边只取一次；不可达块不参与转移。

## P2709 莫队 / 小 B 的询问

原题：[P2709](https://www.luogu.com.cn/problem/P2709)

### 思路

把询问离线排序，让相邻询问的区间端点缓慢移动。维护每个值的出现次数，每次只增删一个位置，常数时间更新答案。某个数的频数从 c 改为 c+delta 时，它的贡献从 c² 变为 (c+delta)²。先减旧平方再加新平方，即可在常数时间更新整个答案。

### 复杂度

时间 O((n+q)sqrt n)，空间 O(n+q)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    int k;
    cin >> k;
    vector<int> a(n + 1), values;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        values.push_back(a[i]);
    }
    sort(values.begin(), values.end());
    values.erase(unique(values.begin(), values.end()), values.end());
    for (int i = 1; i <= n; i++)
        a[i] = lower_bound(values.begin(), values.end(), a[i]) - values.begin();

    struct Query {
        int l, r, id;
    };
    vector<Query> queries(q);
    for (int i = 0; i < q; i++) {
        cin >> queries[i].l >> queries[i].r;
        queries[i].id = i;
    }
    int block = max(1, (int)sqrt(n));
    sort(queries.begin(), queries.end(), [&](Query a, Query b) {
        if (a.l / block != b.l / block)
            return a.l < b.l;
        return (a.l / block) & 1 ? a.r > b.r : a.r < b.r;
    });

    vector<int> freq(values.size());
    vector<long long> answer(q), length(q);
    long long current = 0;
    auto change = [&](int p, int delta) {
        int &c = freq[a[p]];
        current -= 1LL * c * c;
        c += delta;
        current += 1LL * c * c;
    };
    int l = 1, r = 0;
    for (auto query : queries) {
        while (l > query.l)
            change(--l, 1);
        while (r < query.r)
            change(++r, 1);
        while (l < query.l)
            change(l++, -1);
        while (r > query.r)
            change(r--, -1);
        answer[query.id] = current;
        length[query.id] = query.r - query.l + 1;
    }
    for (long long x : answer)
        cout << x << '\n';
    return 0;
}
```

### 实现提醒

平方运算先转 long long；k 是值域上限，不是查询数量。

## P2742 二维凸包 / [USACO5.1] 圈奶牛Fencing the Cows

原题：[P2742](https://www.luogu.com.cn/problem/P2742)

### 思路

按坐标排序，分别维护下凸壳和上凸壳。新点使末尾转向不再凸时弹出中间点。合并得到凸包，循环累加相邻点距离。

### 复杂度

时间 O(n log n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Point {
    double x, y;
};
double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Point> a(n);
    for (auto &v : a)
        cin >> v.x >> v.y;
    sort(a.begin(), a.end(), [](Point a, Point b) { return tie(a.x, a.y) < tie(b.x, b.y); });
    a.erase(unique(a.begin(), a.end(), [](Point a, Point b) { return a.x == b.x && a.y == b.y; }),
            a.end());
    vector<Point> h;
    for (auto p : a) {
        while (h.size() >= 2 && cross(h[h.size() - 2], h.back(), p) <= 0)
            h.pop_back();
        h.push_back(p);
    }
    int lower = h.size();
    for (int i = (int)a.size() - 2; i >= 0; i--) {
        auto p = a[i];
        while ((int)h.size() > lower && cross(h[h.size() - 2], h.back(), p) <= 0)
            h.pop_back();
        h.push_back(p);
    }
    if (h.size() > 1)
        h.pop_back();
    double ans = 0;
    for (int i = 0; i < (int)h.size(); i++) {
        auto p = h[i], q = h[(i + 1) % h.size()];
        ans += hypot(p.x - q.x, p.y - q.y);
    }
    cout << fixed << setprecision(2) << ans << '\n';

    return 0;
}
```

### 实现提醒

先排序并去重；周长包含闭合边；共线中间点不影响长度。

## P2783 有机化学之神偶尔会做作弊

原题：[P2783](https://www.luogu.com.cn/problem/P2783)

### 思路

先合并重复边，再用桥判断找出所有处于环中的连接，将这些非桥边两端合并。压缩图上两点路径的顶点数等于距离加一，最后转成二进制输出。

### 复杂度

时间 O(m log m+(n+q) log n)，空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Lowlink {
    int n, timer = 0;
    vector<vector<pair<int, int>>> g;
    vector<pair<int, int>> edges;
    vector<int> tin, low, parent, parentEdge, children, size;
    vector<char> bridge, cut;
    vector<vector<int>> blocks;
    Lowlink(int n)
        : n(n), g(n), tin(n), low(n), parent(n, -1), parentEdge(n, -1), children(n), size(n, 1),
          cut(n) {}
    void edge(int a, int b) {
        int id = edges.size();
        edges.push_back({a, b});
        g[a].push_back({b, id});
        g[b].push_back({a, id});
    }
    void build() {
        bridge.assign(edges.size(), 0);
        vector<int> vertices;
        for (int root = 0; root < n; root++)
            if (!tin[root]) {
                vector<pair<int, int>> st = {{root, 0}};
                tin[root] = low[root] = ++timer;
                vertices.push_back(root);
                while (!st.empty()) {
                    int v = st.back().first;
                    int &next = st.back().second;
                    if (next < (int)g[v].size()) {
                        auto [u, id] = g[v][next++];
                        if (id == parentEdge[v])
                            continue;
                        if (!tin[u]) {
                            parent[u] = v;
                            parentEdge[u] = id;
                            children[v]++;
                            tin[u] = low[u] = ++timer;
                            vertices.push_back(u);
                            st.push_back({u, 0});
                        } else
                            low[v] = min(low[v], tin[u]);
                    } else {
                        st.pop_back();
                        int p = parent[v];
                        if (p >= 0) {
                            size[p] += size[v];
                            low[p] = min(low[p], low[v]);
                            bridge[parentEdge[v]] = low[v] > tin[p];
                            if (low[v] >= tin[p]) {
                                if (parent[p] >= 0)
                                    cut[p] = 1;
                                vector<int> block = {p};
                                while (true) {
                                    int u = vertices.back();
                                    vertices.pop_back();
                                    block.push_back(u);
                                    if (u == v)
                                        break;
                                }
                                blocks.push_back(move(block));
                            }
                        } else {
                            cut[v] = children[v] > 1;
                            if (children[v] == 0)
                                blocks.push_back({v});
                            vertices.pop_back();
                        }
                    }
                }
            }
    }
};

struct DSU {
    vector<int> p, size;
    explicit DSU(int n) : p(n), size(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    bool join(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        p[b] = a;
        size[a] += size[b];
        return true;
    }
};

struct HLD {
    int n;
    vector<int> parent, depth, size, heavy, head, pos, at, order;
    HLD(const vector<vector<int>> &g, int root = 0)
        : n(g.size()), parent(n, -1), depth(n), size(n, 1), heavy(n, -1), head(n), pos(n), at(n) {
        parent[root] = root;
        order = {root};
        for (int i = 0; i < (int)order.size(); i++) {
            int v = order[i];
            for (int u : g[v])
                if (parent[u] < 0) {
                    parent[u] = v;
                    depth[u] = depth[v] + 1;
                    order.push_back(u);
                }
        }
        for (int i = n - 1; i > 0; i--) {
            int v = order[i], p = parent[v];
            size[p] += size[v];
            if (heavy[p] < 0 || size[v] > size[heavy[p]])
                heavy[p] = v;
        }
        vector<pair<int, int>> st = {{root, root}};
        int timer = 0;
        while (!st.empty()) {
            auto [v, h] = st.back();
            st.pop_back();
            for (; v >= 0; v = heavy[v]) {
                head[v] = h;
                pos[v] = timer;
                at[timer++] = v;
                for (int u : g[v])
                    if (parent[u] == v && u != heavy[v])
                        st.push_back({u, u});
            }
        }
    }
    int lca(int a, int b) const {
        while (head[a] != head[b]) {
            if (depth[head[a]] < depth[head[b]])
                swap(a, b);
            a = parent[head[a]];
        }
        return depth[a] < depth[b] ? a : b;
    }
    int jump(int v, int d) const {
        while (d > depth[v] - depth[head[v]]) {
            d -= depth[v] - depth[head[v]] + 1;
            v = parent[head[v]];
        }
        return at[pos[v] - d];
    }
    int distance(int a, int b) const { return depth[a] + depth[b] - 2 * depth[lca(a, b)]; }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<pair<int, int>> e;
    while (m--) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        if (a > b)
            swap(a, b);
        if (a != b)
            e.push_back({a, b});
    }
    sort(e.begin(), e.end());
    e.erase(unique(e.begin(), e.end()), e.end());
    Lowlink graph(n);
    for (auto [a, b] : e)
        graph.edge(a, b);
    graph.build();
    DSU d(n);
    for (int i = 0; i < (int)e.size(); i++)
        if (!graph.bridge[i])
            d.join(e[i].first, e[i].second);
    vector<int> ids(n, -1), belong(n);
    int z = 0;
    for (int i = 0; i < n; i++) {
        int r = d.find(i);
        if (ids[r] < 0)
            ids[r] = z++;
        belong[i] = ids[r];
    }
    vector<vector<int>> g(z);
    for (int i = 0; i < (int)e.size(); i++)
        if (graph.bridge[i]) {
            int a = belong[e[i].first], b = belong[e[i].second];
            g[a].push_back(b);
            g[b].push_back(a);
        }
    HLD tree(g);
    int q;
    cin >> q;
    while (q--) {
        int a, b;
        cin >> a >> b;
        int value = tree.distance(belong[a - 1], belong[b - 1]) + 1;
        string ans;
        while (value) {
            ans += char('0' + value % 2);
            value /= 2;
        }
        reverse(ans.begin(), ans.end());
        cout << ans << '\n';
    }

    return 0;
}
```

### 实现提醒

先去重再判桥；相同压缩点的答案为二进制 1；路径点数需要加一。

## P2789 直线交点数

原题：[P2789](https://www.luogu.com.cn/problem/P2789)

### 思路

没有三线共点时，每对不平行直线产生唯一交点。将直线按斜率分组，添加 k 条新平行线到已有 i 条线时增加 ik 个交点。布尔 DP 记录每种线数可达到的交点数。

### 复杂度

时间 O(n⁴)，空间 O(n³)，n<=25。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    int maximum = n * (n - 1) / 2;
    vector<vector<char>> dp(n + 1, vector<char>(maximum + 1));
    dp[0][0] = 1;
    for (int i = 0; i < n; i++)
        for (int s = 0; s <= maximum; s++)
            if (dp[i][s])
                for (int k = 1; i + k <= n; k++)
                    dp[i + k][s + i * k] = 1;
    cout << count(dp[n].begin(), dp[n].end(), 1) << '\n';

    return 0;
}
```

### 实现提醒

只问不同交点数量有几种；新组内部平行；不能把三线共点计为一种压缩方式。

## P2804 神秘数字

原题：[P2804](https://www.luogu.com.cn/problem/P2804)

### 思路

把每项减去 M，原子段平均值严格大于 M 等价于新子段和大于 0，也就是右前缀和大于左前缀和。离散化后用树状数组统计此前更小前缀的数量。

### 复杂度

时间 O(n log n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> t;
    explicit Fenwick(int n) : n(n), t(n + 1) {}
    void add(int x, long long v) {
        for (; x <= n; x += x & -x)
            t[x] += v;
    }
    long long sum(int x) const {
        long long s = 0;
        for (; x; x -= x & -x)
            s += t[x];
        return s;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> p(n + 1), values;
    for (int i = 1; i <= n; i++) {
        int x;
        cin >> x;
        p[i] = p[i - 1] + x - m;
    }
    values = p;
    sort(values.begin(), values.end());
    values.erase(unique(values.begin(), values.end()), values.end());
    Fenwick bit(values.size());
    long long ans = 0;
    for (long long x : p) {
        int rank = lower_bound(values.begin(), values.end(), x) - values.begin() + 1;
        ans += bit.sum(rank - 1);
        bit.add(rank, 1);
    }
    cout << ans % 92084931 << '\n';

    return 0;
}
```

### 实现提醒

严格小于，查询排名减一；插入 p[0]；每项先减 M。

## P2812 校园网络 / [IOI 1996 / USACO5.3] 校园网 Network of Schools 加强版

原题：[P2812](https://www.luogu.com.cn/problem/P2812)

### 思路

第一问是缩点图中入度为零的分量数；第二问若只有一个分量为 0，否则是源分量数与汇分量数的较大者。

### 复杂度

时间 O(n+m)，空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SCC {
    int n, count = 0;
    vector<vector<int>> g, rev;
    vector<int> component;
    explicit SCC(int n) : n(n), g(n), rev(n), component(n, -1) {}
    void edge(int a, int b) {
        g[a].push_back(b);
        rev[b].push_back(a);
    }
    void build() {
        vector<char> seen(n);
        vector<int> order;
        for (int start = 0; start < n; start++)
            if (!seen[start]) {
                vector<pair<int, int>> st = {{start, 0}};
                seen[start] = true;
                while (!st.empty()) {
                    int v = st.back().first;
                    int &i = st.back().second;
                    if (i < (int)g[v].size()) {
                        int u = g[v][i++];
                        if (!seen[u]) {
                            seen[u] = true;
                            st.push_back({u, 0});
                        }
                    } else {
                        order.push_back(v);
                        st.pop_back();
                    }
                }
            }
        reverse(order.begin(), order.end());
        for (int start : order)
            if (component[start] < 0) {
                vector<int> st = {start};
                component[start] = count;
                while (!st.empty()) {
                    int v = st.back();
                    st.pop_back();
                    for (int u : rev[v])
                        if (component[u] < 0) {
                            component[u] = count;
                            st.push_back(u);
                        }
                }
                count++;
            }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    SCC s(n);
    for (int i = 0; i < n; i++) {
        int x;
        while (cin >> x && x)
            s.edge(i, x - 1);
    }
    s.build();
    vector<int> in(s.count), out(s.count);
    for (int v = 0; v < n; v++)
        for (int u : s.g[v])
            if (s.component[u] != s.component[v]) {
                in[s.component[u]]++;
                out[s.component[v]]++;
            }
    int a = count(in.begin(), in.end(), 0), b = count(out.begin(), out.end(), 0);
    cout << a << '\n' << (s.count == 1 ? 0 : max(a, b)) << '\n';

    return 0;
}
```

### 实现提醒

每行的 0 只是结束标记；一分量时答案是 1 和 0。

## P2820 局域网

原题：[P2820](https://www.luogu.com.cn/problem/P2820)

### 思路

将边按权值从小到大排序，用并查集判断两端是否已连通。连接两个不同连通块的边才能进入生成树。累计被删除边权等于全部边权减去最小生成树权值。

### 复杂度

时间 O(m log m)，空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, size;
    explicit DSU(int n) : p(n), size(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    bool join(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        p[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    struct E {
        int u, v;
        long long w;
    };
    vector<E> e(m);
    long long total = 0;
    for (auto &x : e) {
        cin >> x.u >> x.v >> x.w;
        total += x.w;
    }
    sort(e.begin(), e.end(), [](E a, E b) { return a.w < b.w; });
    DSU d(n + 1);
    long long answer = 0;
    int used = 0;
    for (auto x : e)
        if (d.join(x.u, x.v)) {
            answer += x.w;
            used++;
        }
    cout << total - answer << '\n';
    return 0;
}
```

### 实现提醒

并查集按顶点编号开空间；总权值使用六十四位整数；相同权值任意处理。

## P2835 刻录光盘

原题：[P2835](https://www.luogu.com.cn/problem/P2835)

### 思路

互相可达的人中只需给一张光盘。将强连通分量缩成有向无环图，每个入度为零的分量必须直接获得一张，且这些光盘足以传播给所有人。

### 复杂度

时间 O(N+E)，空间 O(N+E)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SCC {
    int n, count = 0;
    vector<vector<int>> g, rev;
    vector<int> component;
    explicit SCC(int n) : n(n), g(n), rev(n), component(n, -1) {}
    void edge(int a, int b) {
        g[a].push_back(b);
        rev[b].push_back(a);
    }
    void build() {
        vector<char> seen(n);
        vector<int> order;
        for (int start = 0; start < n; start++)
            if (!seen[start]) {
                vector<pair<int, int>> st = {{start, 0}};
                seen[start] = true;
                while (!st.empty()) {
                    int v = st.back().first;
                    int &i = st.back().second;
                    if (i < (int)g[v].size()) {
                        int u = g[v][i++];
                        if (!seen[u]) {
                            seen[u] = true;
                            st.push_back({u, 0});
                        }
                    } else {
                        order.push_back(v);
                        st.pop_back();
                    }
                }
            }
        reverse(order.begin(), order.end());
        for (int start : order)
            if (component[start] < 0) {
                vector<int> st = {start};
                component[start] = count;
                while (!st.empty()) {
                    int v = st.back();
                    st.pop_back();
                    for (int u : rev[v])
                        if (component[u] < 0) {
                            component[u] = count;
                            st.push_back(u);
                        }
                }
                count++;
            }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    SCC s(n);
    for (int i = 0; i < n; i++) {
        int x;
        while (cin >> x && x)
            s.edge(i, x - 1);
    }
    s.build();
    vector<char> in(s.count);
    for (int i = 0; i < n; i++)
        for (int j : s.g[i])
            if (s.component[i] != s.component[j])
                in[s.component[j]] = 1;
    cout << count(in.begin(), in.end(), 0) << '\n';

    return 0;
}
```

### 实现提醒

有向边按资料传播方向；统计源分量，不是汇分量；每行以零结束。

## P2846 Light Switching G

原题：[P2846](https://www.luogu.com.cn/problem/P2846)

### 思路

每个节点保存亮灯数量。翻转整段后，亮灯数变成区间长度减去原亮灯数；翻转标记按异或合并，两次翻转抵消。

动图中，整段翻转后根节点已经正确，孩子仍保留旧值；只有查询左半时才下传。再翻转左半，它的待翻转标记从 1 异或为 0，说明两次翻转抵消。

![整段翻转与延迟下传](assets/lazy-flip.svg)

### 复杂度

每次操作 O(log n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Tree {
    int n;
    vector<int> sum;
    vector<char> tag;
    Tree(int n) : n(n), sum(4 * n), tag(4 * n) {}
    void apply(int p, int l, int r) {
        sum[p] = r - l + 1 - sum[p];
        tag[p] ^= 1;
    }
    void push(int p, int l, int r) {
        if (tag[p] && l < r) {
            int m = (l + r) / 2;
            apply(p * 2, l, m);
            apply(p * 2 + 1, m + 1, r);
            tag[p] = 0;
        }
    }
    void change(int p, int l, int r, int a, int b) {
        if (a <= l && r <= b) {
            apply(p, l, r);
            return;
        }
        push(p, l, r);
        int m = (l + r) / 2;
        if (a <= m)
            change(p * 2, l, m, a, b);
        if (b > m)
            change(p * 2 + 1, m + 1, r, a, b);
        sum[p] = sum[p * 2] + sum[p * 2 + 1];
    }
    int query(int p, int l, int r, int a, int b) {
        if (a <= l && r <= b)
            return sum[p];
        push(p, l, r);
        int m = (l + r) / 2, ans = 0;
        if (a <= m)
            ans += query(p * 2, l, m, a, b);
        if (b > m)
            ans += query(p * 2 + 1, m + 1, r, a, b);
        return ans;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    Tree t(n);
    while (m--) {
        int op, l, r;
        cin >> op >> l >> r;
        if (op == 0)
            t.change(1, 1, n, l, r);
        else
            cout << t.query(1, 1, n, l, r) << '\n';
    }

    return 0;
}
```

### 实现提醒

标记使用异或；下传时同步改变孩子计数；初始全灭。

## P2855 River Hopscotch S

原题：[P2855](https://www.luogu.com.cn/problem/P2855)

### 思路

给定最小跳距 D，从起点开始尽量保留最靠左的可用石头；与上个保留点距离不足 D 的石头移走。所需移走数不超过 M 时 D 可行，二分最大可行值。

### 复杂度

时间 O(n log L+n log n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int length, n, m;
    cin >> length >> n >> m;
    vector<int> a(n + 1);
    for (int i = 0; i < n; i++)
        cin >> a[i];
    sort(a.begin(), a.begin() + n);
    a[n] = length;
    auto ok = [&](int gap) {
        int removed = 0, last = 0;
        for (int x : a)
            if (x - last < gap)
                removed++;
            else
                last = x;
        return removed <= m;
    };
    int l = 0, r = length;
    while (l < r) {
        int mid = l + (r - l + 1) / 2;
        if (ok(mid))
            l = mid;
        else
            r = mid - 1;
    }
    cout << l << '\n';

    return 0;
}
```

### 实现提醒

终点必须保留；最后一段冲突需要计一次删除；求最大可行值。

## P2858 Treats for the Cows G/S

原题：[P2858](https://www.luogu.com.cn/problem/P2858)

### 思路

剩余区间长度确定今天是第几天。每次只能卖左端或右端，取两种选择的较大收益。按区间长度递增计算，可压缩为一维。

### 复杂度

时间 O(n²)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> a(n), dp(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        dp[i] = a[i] * n;
    }
    for (int len = 2; len <= n; len++) {
        long long day = n - len + 1;
        for (int l = 0; l + len <= n; l++) {
            int r = l + len - 1;
            dp[l] = max(a[l] * day + dp[l + 1], a[r] * day + dp[l]);
        }
    }
    cout << dp[0] << '\n';

    return 0;
}
```

### 实现提醒

年龄从一开始增加；单点是在第 n 天卖；一维左端必须递增枚举。

