## P2982 Slowing down G

原题：[P2982](https://www.luogu.com.cn/problem/P2982)

### 思路

一头已到达牧场的牛，会使以后所有目的地位于该牧场子树的奶牛减速一次。Euler 序把子树变成区间，用差分树状数组区间加、单点查询。

### 复杂度

时间 O(n log n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct HLD {
    int n;
    vector<int> parent, depth, size, heavy, head, pos, at, order;
    HLD(const vector<vector<int>> &g, int root = 0)
        : n(g.size()), parent(n, -1), depth(n), size(n, 1), heavy(n, -1), head(n), pos(n), at(n) {
        parent[root] = root;
        order = {root};
        for (int i = 0; i < (int)order.size(); i++) {
            int v = order[i];
            for (int u : g[v])
                if (parent[u] < 0) {
                    parent[u] = v;
                    depth[u] = depth[v] + 1;
                    order.push_back(u);
                }
        }
        for (int i = n - 1; i > 0; i--) {
            int v = order[i], p = parent[v];
            size[p] += size[v];
            if (heavy[p] < 0 || size[v] > size[heavy[p]])
                heavy[p] = v;
        }
        vector<pair<int, int>> st = {{root, root}};
        int timer = 0;
        while (!st.empty()) {
            auto [v, h] = st.back();
            st.pop_back();
            for (; v >= 0; v = heavy[v]) {
                head[v] = h;
                pos[v] = timer;
                at[timer++] = v;
                for (int u : g[v])
                    if (parent[u] == v && u != heavy[v])
                        st.push_back({u, u});
            }
        }
    }
    int lca(int a, int b) const {
        while (head[a] != head[b]) {
            if (depth[head[a]] < depth[head[b]])
                swap(a, b);
            a = parent[head[a]];
        }
        return depth[a] < depth[b] ? a : b;
    }
    int jump(int v, int d) const {
        while (d > depth[v] - depth[head[v]]) {
            d -= depth[v] - depth[head[v]] + 1;
            v = parent[head[v]];
        }
        return at[pos[v] - d];
    }
    int distance(int a, int b) const { return depth[a] + depth[b] - 2 * depth[lca(a, b)]; }
};

struct Fenwick {
    int n;
    vector<long long> t;
    explicit Fenwick(int n) : n(n), t(n + 1) {}
    void add(int x, long long v) {
        for (; x <= n; x += x & -x)
            t[x] += v;
    }
    long long sum(int x) const {
        long long s = 0;
        for (; x; x -= x & -x)
            s += t[x];
        return s;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> g(n);
    for (int i = 1; i < n; i++) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    HLD tree(g);
    Fenwick bit(n + 1);
    for (int i = 0; i < n; i++) {
        int p;
        cin >> p;
        p--;
        int l = tree.pos[p] + 1, r = l + tree.size[p] - 1;
        cout << bit.sum(l) << '\n';
        bit.add(l, 1);
        bit.add(r + 1, -1);
    }

    return 0;
}
```

### 实现提醒

先查后加；根上的牛会影响所有后来奶牛；Euler 子树区间包含根。

## P3007 The Continental Cowngress G

原题：[P3007](https://www.luogu.com.cn/problem/P3007)

### 思路

先建立每头牛的两个投票至少满足一个的 2-SAT 图。无矛盾后，若 N 能推出 Y，则议案必须通过；若 Y 能推出 N，则必须否决；都不能推出时两种取值均可。

### 复杂度

时间 O(n(n+m))，空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SCC {
    int n, count = 0;
    vector<vector<int>> g, rev;
    vector<int> component;
    explicit SCC(int n) : n(n), g(n), rev(n), component(n, -1) {}
    void edge(int a, int b) {
        g[a].push_back(b);
        rev[b].push_back(a);
    }
    void build() {
        vector<char> seen(n);
        vector<int> order;
        for (int start = 0; start < n; start++)
            if (!seen[start]) {
                vector<pair<int, int>> st = {{start, 0}};
                seen[start] = true;
                while (!st.empty()) {
                    int v = st.back().first;
                    int &i = st.back().second;
                    if (i < (int)g[v].size()) {
                        int u = g[v][i++];
                        if (!seen[u]) {
                            seen[u] = true;
                            st.push_back({u, 0});
                        }
                    } else {
                        order.push_back(v);
                        st.pop_back();
                    }
                }
            }
        reverse(order.begin(), order.end());
        for (int start : order)
            if (component[start] < 0) {
                vector<int> st = {start};
                component[start] = count;
                while (!st.empty()) {
                    int v = st.back();
                    st.pop_back();
                    for (int u : rev[v])
                        if (component[u] < 0) {
                            component[u] = count;
                            st.push_back(u);
                        }
                }
                count++;
            }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    SCC s(2 * n);
    while (m--) {
        int a, b;
        char x, y;
        cin >> a >> x >> b >> y;
        int u = 2 * (a - 1) + (x == 'Y'), v = 2 * (b - 1) + (y == 'Y');
        s.edge(u ^ 1, v);
        s.edge(v ^ 1, u);
    }
    s.build();
    for (int i = 0; i < n; i++)
        if (s.component[2 * i] == s.component[2 * i + 1]) {
            cout << "IMPOSSIBLE\n";
            return 0;
        }
    auto reach = [&](int a, int b) {
        vector<char> seen(2 * n);
        vector<int> st = {a};
        seen[a] = 1;
        while (!st.empty()) {
            int v = st.back();
            st.pop_back();
            if (v == b)
                return true;
            for (int u : s.g[v])
                if (!seen[u]) {
                    seen[u] = 1;
                    st.push_back(u);
                }
        }
        return false;
    };
    for (int i = 0; i < n; i++)
        cout << (reach(2 * i, 2 * i + 1) ? 'Y' : reach(2 * i + 1, 2 * i) ? 'N' : '?');
    cout << '\n';

    return 0;
}
```

### 实现提醒

无解先输出 IMPOSSIBLE；可行时强制方向不能反；未知输出 ?。

## P3047 Nearby Cows G

原题：[P3047](https://www.luogu.com.cn/problem/P3047)

### 思路

先求每个点子树内距离恰为 d 的牛数，再向下换根。孩子距离 d 的外部贡献来自父亲距离 d−1 的总量，并扣掉重复落在孩子子树中的距离 d−2 部分。

### 复杂度

时间 O(nK)，空间 O(nK)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<vector<int>> g(n);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        u--;
        v--;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    int width = k + 1;
    vector<int> down(n * width), all(n * width), parent(n, -1), order = {0};
    for (int i = 0; i < n; i++)
        cin >> down[i * width];
    parent[0] = 0;
    for (int i = 0; i < n; i++)
        for (int u : g[order[i]])
            if (u != parent[order[i]]) {
                parent[u] = order[i];
                order.push_back(u);
            }
    for (int i = n - 1; i > 0; i--) {
        int v = order[i], p = parent[v];
        for (int d = 1; d <= k; d++)
            down[p * width + d] += down[v * width + d - 1];
    }
    all = down;
    for (int i = 1; i < n; i++) {
        int v = order[i], p = parent[v];
        for (int d = 1; d <= k; d++)
            all[v * width + d] += all[p * width + d - 1] - (d >= 2 ? down[v * width + d - 2] : 0);
    }
    for (int v = 0; v < n; v++) {
        long long ans = 0;
        for (int d = 0; d <= k; d++)
            ans += all[v * width + d];
        cout << ans << '\n';
    }

    return 0;
}
```

### 实现提醒

距离是边数；d<2 不减子树项；子树数组和全树数组分开。

## P3065 First! G

原题：[P3065](https://www.luogu.com.cn/problem/P3065)

### 思路

要让某词排第一，沿它的字典树路径遇到其它分支时，当前字母必须比那些分支字母更小。若有更短单词是它的前缀，立即不行；否则检查字母约束图是否有环。

### 复杂度

时间 O(L·26+n·26²)，空间 O(L+n)，L 为总词长。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Node {
    array<int, 26> child = {};
    bool end = false;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<string> words(n);
    vector<Node> trie(1);
    for (auto &s : words) {
        cin >> s;
        int v = 0;
        for (char c : s) {
            int b = c - 'a';
            if (!trie[v].child[b]) {
                trie[v].child[b] = trie.size();
                trie.push_back(Node());
            }
            v = trie[v].child[b];
        }
        trie[v].end = true;
    }
    vector<string> ans;
    for (auto &s : words) {
        bool edge[26][26] = {};
        bool ok = true;
        int v = 0;
        for (char c : s) {
            if (trie[v].end) {
                ok = false;
                break;
            }
            int x = c - 'a';
            for (int y = 0; y < 26; y++)
                if (y != x && trie[v].child[y])
                    edge[x][y] = true;
            v = trie[v].child[x];
        }
        int in[26] = {};
        for (int x = 0; x < 26; x++)
            for (int y = 0; y < 26; y++)
                in[y] += edge[x][y];
        queue<int> q;
        for (int x = 0; x < 26; x++)
            if (!in[x])
                q.push(x);
        int count = 0;
        while (!q.empty()) {
            int x = q.front();
            q.pop();
            count++;
            for (int y = 0; y < 26; y++)
                if (edge[x][y] && --in[y] == 0)
                    q.push(y);
        }
        if (ok && count == 26)
            ans.push_back(s);
    }
    cout << ans.size() << '\n';
    for (auto &s : ans)
        cout << s << '\n';

    return 0;
}
```

### 实现提醒

前缀冲突单独判断；约束是候选字母→其它字母；重边不重复加入入度。

## P3080 The Cow Run G/S

原题：[P3080](https://www.luogu.com.cn/problem/P3080)

### 思路

把零位置一起排序，已访问的奶牛总形成一个包含零的区间。状态记录区间和停在左端或右端；向外扩展时，路程乘尚未安抚奶牛数就是增加的损失。

### 复杂度

时间 O(n²)，空间 O(n²)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> a(n + 1);
    for (int i = 0; i < n; i++)
        cin >> a[i];
    a[n] = 0;
    sort(a.begin(), a.end());
    int N = n + 1, start = lower_bound(a.begin(), a.end(), 0) - a.begin();
    const long long INF = 1LL << 62;
    vector<vector<array<long long, 2>>> dp(N, vector<array<long long, 2>>(N, {INF, INF}));
    dp[start][start] = {0, 0};
    for (int len = 1; len <= N; len++)
        for (int l = 0; l + len <= N; l++) {
            int r = l + len - 1;
            if (l > start || r < start)
                continue;
            long long remaining = N - len;
            for (int side = 0; side < 2; side++)
                if (dp[l][r][side] < INF) {
                    int pos = side ? r : l;
                    if (l)
                        dp[l - 1][r][0] =
                            min(dp[l - 1][r][0], dp[l][r][side] + (a[pos] - a[l - 1]) * remaining);
                    if (r + 1 < N)
                        dp[l][r + 1][1] =
                            min(dp[l][r + 1][1], dp[l][r][side] + (a[r + 1] - a[pos]) * remaining);
                }
        }
    cout << min(dp[0][n][0], dp[0][n][1]) << '\n';

    return 0;
}
```

### 实现提醒

零是虚拟起点，不是奶牛；增加损失乘所有未安抚奶牛；从区间当前端点量路程。

## P3120 Cow Hopscotch G

原题：[P3120](https://www.luogu.com.cn/problem/P3120)

### 思路

按行扫描，用全局树状数组统计更早行、较小列的所有路径数，再减去当前颜色的同类统计。同一行先计算完再一起加入，保证行坐标严格增加。

### 复杂度

时间 O(RC log C)，空间 O(RC+K)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Bit {
    vector<int> t;
    Bit(int n) : t(n + 1) {}
    void add(int x, int v) {
        for (; x < (int)t.size(); x += x & -x) {
            t[x] += v;
            if (t[x] >= 1000000007)
                t[x] -= 1000000007;
        }
    }
    int sum(int x) const {
        int r = 0;
        for (; x; x -= x & -x) {
            r += t[x];
            if (r >= 1000000007)
                r -= 1000000007;
        }
        return r;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int R, C, K;
    cin >> R >> C >> K;
    vector<vector<int>> a(R, vector<int>(C)), columns(K + 1);
    for (int i = 0; i < R; i++)
        for (int j = 0; j < C; j++) {
            cin >> a[i][j];
            columns[a[i][j]].push_back(j + 1);
        }
    vector<Bit> colored;
    colored.reserve(K + 1);
    for (int c = 0; c <= K; c++) {
        auto &v = columns[c];
        sort(v.begin(), v.end());
        v.erase(unique(v.begin(), v.end()), v.end());
        colored.emplace_back(v.size());
    }
    Bit all(C);
    vector<int> row(C);
    int ans = 0;
    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            int c = a[i][j],
                r = lower_bound(columns[c].begin(), columns[c].end(), j + 1) - columns[c].begin();
            row[j] = (all.sum(j) - colored[c].sum(r) + 1000000007) % 1000000007;
            if (i == 0 && j == 0)
                row[j] = 1;
        }
        for (int j = 0; j < C; j++) {
            int c = a[i][j], r = lower_bound(columns[c].begin(), columns[c].end(), j + 1) -
                                 columns[c].begin() + 1;
            all.add(j + 1, row[j]);
            colored[c].add(r, row[j]);
        }
        ans = row[C - 1];
    }
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

行列必须都严格增加；同色贡献相减后规范化；同一行延迟更新。

## P3177 树上染色

原题：[P3177](https://www.luogu.com.cn/problem/P3177)

### 思路

一条边下方有 size 个点，其中 j 个黑点，它对同色点对距离的贡献是 w·[j(k−j)+(size−j)(n−k−size+j)]。树形背包决定每棵子树的黑点数，并累加各边贡献。

### 复杂度

时间 O(n²)，空间 O(nk)，实现中按实际子树大小限制状态。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<vector<pair<int, int>>> g(n);
    for (int i = 1; i < n; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        u--;
        v--;
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }
    vector<int> parent(n, -1), size(n, 1), weight(n), order = {0};
    parent[0] = 0;
    for (int i = 0; i < n; i++)
        for (auto [u, w] : g[order[i]])
            if (u != parent[order[i]]) {
                parent[u] = order[i];
                weight[u] = w;
                order.push_back(u);
            }
    const long long neg = LLONG_MIN / 4;
    vector<vector<long long>> dp(n);
    for (int i = n - 1; i >= 0; i--) {
        int v = order[i];
        if (dp[v].empty()) {
            dp[v] = {0};
            if (k)
                dp[v].push_back(0);
        }
        if (v == 0)
            break;
        int p = parent[v];
        if (dp[p].empty()) {
            dp[p] = {0};
            if (k)
                dp[p].push_back(0);
        }
        vector<long long> next(min(k, size[p] + size[v]) + 1, neg);
        for (int a = 0; a < (int)dp[p].size(); a++)
            if (dp[p][a] != neg)
                for (int b = 0; b < (int)dp[v].size() && a + b <= k; b++)
                    if (dp[v][b] != neg) {
                        long long outsideWhite = n - k - size[v] + b;
                        if (outsideWhite < 0)
                            continue;
                        long long pairs = 1LL * b * (k - b) + 1LL * (size[v] - b) * outsideWhite;
                        next[a + b] = max(next[a + b], dp[p][a] + dp[v][b] + pairs * weight[v]);
                    }
        size[p] += size[v];
        dp[p].swap(next);
        vector<long long>().swap(dp[v]);
    }
    cout << dp[0][k] << '\n';

    return 0;
}
```

### 实现提醒

计无序同色点对；白点外侧数是 n−k−s+j；不可行状态不参与转移。

## P3194 水平可见直线

原题：[P3194](https://www.luogu.com.cn/problem/P3194)

### 思路

同斜率只保留最高一条。按斜率递增加入直线，维护每条线开始成为最高线的横坐标；新交点不在上条线可见区间右侧时弹掉上条线。

### 复杂度

时间 O(n log n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Line {
    long long k, b;
    int id;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Line> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i].k >> a[i].b;
        a[i].id = i + 1;
    }
    sort(a.begin(), a.end(), [](Line a, Line b) {
        if (a.k != b.k)
            return a.k < b.k;
        return a.b > b.b;
    });
    vector<Line> h;
    vector<long double> start;
    for (auto line : a) {
        if (!h.empty() && line.k == h.back().k)
            continue;
        long double x = -numeric_limits<long double>::infinity();
        while (!h.empty()) {
            x = (long double)(h.back().b - line.b) / (line.k - h.back().k);
            if (x > start.back())
                break;
            h.pop_back();
            start.pop_back();
        }
        if (h.empty())
            x = -numeric_limits<long double>::infinity();
        h.push_back(line);
        start.push_back(x);
    }
    vector<int> ans;
    for (auto line : h)
        ans.push_back(line.id);
    sort(ans.begin(), ans.end());
    for (int id : ans)
        cout << id << ' ';
    cout << '\n';

    return 0;
}
```

### 实现提醒

同斜率保留最高截距；只在单个交点出现不算可见；输出原编号。

## P3197 越狱

原题：[P3197](https://www.luogu.com.cn/problem/P3197)

### 思路

全部安排有 m^n 种。没有相邻同教派的安排中，第一个人有 m 种选择，后面每个人有 m−1 种，所以答案为 m^n−m(m−1)^(n−1)。

### 复杂度

时间 O(log n)，空间 O(1)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

long long power(long long a, long long b, long long mod) {
    long long r = 1;
    for (; b; b >>= 1, a = a * a % mod)
        if (b & 1)
            r = r * a % mod;
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m, n;
    cin >> m >> n;
    const long long mod = 100003;
    cout << (power(m % mod, n, mod) - (m % mod) * power((m - 1) % mod, n - 1, mod) % mod + mod) %
                mod
         << '\n';

    return 0;
}
```

### 实现提醒

模数为 100003；减法规范化；n=1 时答案为 0。

## P3366 最小生成树

原题：[P3366](https://www.luogu.com.cn/problem/P3366)

### 思路

将边按权值从小到大排序，用并查集判断两端是否已连通。连接两个不同连通块的边才能进入生成树。选满 n−1 条边得到最小生成树；不能选满则图不连通。

### 复杂度

时间 O(m log m)，空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, size;
    explicit DSU(int n) : p(n), size(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    bool join(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        p[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    struct E {
        int u, v;
        long long w;
    };
    vector<E> e(m);
    long long total = 0;
    for (auto &x : e) {
        cin >> x.u >> x.v >> x.w;
        total += x.w;
    }
    sort(e.begin(), e.end(), [](E a, E b) { return a.w < b.w; });
    DSU d(n + 1);
    long long answer = 0;
    int used = 0;
    for (auto x : e)
        if (d.join(x.u, x.v)) {
            answer += x.w;
            used++;
        }
    if (used != n - 1)
        cout << "orz\n";
    else
        cout << answer << '\n';
    return 0;
}
```

### 实现提醒

并查集按顶点编号开空间；总权值使用六十四位整数；相同权值任意处理。

## P3370 字符串哈希

原题：[P3370](https://www.luogu.com.cn/problem/P3370)

### 思路

把每个输入字符串插入 unordered_set，最后输出集合大小。标准容器遇到哈希冲突仍会比较完整字符串，因此不会把不同字符串误认为相同。

