        int a, b;
        cin >> a >> b;
        graph.edge(a - 1, b - 1);
    }
    graph.build();

    vector<long long> answer(n, 2LL * (n - 1)), separated(n);
    for (int v = 0; v < n; v++) {
        int p = graph.parent[v];
        if (p >= 0 && graph.low[v] >= graph.tin[p]) {
            long long s = graph.size[v];
            answer[p] += s * (n - 1 - s);
            separated[p] += s;
        }
    }
    for (int v = 0; v < n; v++) {
        long long rest = n - 1 - separated[v];
        answer[v] += rest * (n - 1 - rest);
        cout << answer[v] << '\n';
    }

    return 0;
}
```

### 实现提醒

统计有序点对；包含被封锁点作为端点的情况；答案用 long long。

## P3612 Secret Cow Code S

原题：[P3612](https://www.luogu.com.cn/problem/P3612)

### 思路

每轮新串是原串加上“末字符移到最前”的原串。查询在后一半时，第一位对应前一半末位，其余位置向前错一位；反复倒推直到落进初始串。

### 复杂度

时间 O(log N)，空间 O(初始串长度)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    long long p;
    cin >> s >> p;
    long long length = s.size();
    while (length < p)
        length *= 2;
    while (length > (long long)s.size()) {
        long long half = length / 2;
        if (p > half)
            p = p == half + 1 ? half : p - half - 1;
        length = half;
    }
    cout << s[p - 1] << '\n';

    return 0;
}
```

### 实现提醒

后一半第一位单独映射；下标从 1；只增长长度，不生成长串。

## P3616 富金森林公园

原题：[P3616](https://www.luogu.com.cn/problem/P3616)

### 思路

露出的石头在链上形成森林，连通块数等于点数减边数。每个石头高度贡献加一，每对相邻石头的较小高度贡献减一；水位查询转为高度不小于水位的权值和。

### 复杂度

时间 O((N+M) log(N+M))，空间 O(N+M)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> t;
    explicit Fenwick(int n) : n(n), t(n + 1) {}
    void add(int x, long long v) {
        for (; x <= n; x += x & -x)
            t[x] += v;
    }
    long long sum(int x) const {
        long long s = 0;
        for (; x; x -= x & -x)
            s += t[x];
        return s;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n), values;
    for (auto &x : a) {
        cin >> x;
        values.push_back(x);
    }
    struct Op {
        int type, p;
        long long x;
    };
    vector<Op> ops;
    for (int i = 0; i < m; i++) {
        int type;
        cin >> type;
        if (type == 1) {
            long long B;
            cin >> B;
            ops.push_back({1, 0, B});
        } else {
            int p;
            long long x;
            cin >> p >> x;
            ops.push_back({2, p - 1, x});
            values.push_back(x);
        }
    }
    sort(values.begin(), values.end());
    values.erase(unique(values.begin(), values.end()), values.end());
    Fenwick bit(values.size());
    auto change = [&](long long h, int delta) {
        int r = lower_bound(values.begin(), values.end(), h) - values.begin() + 1;
        bit.add(r, delta);
    };
    for (int i = 0; i < n; i++) {
        change(a[i], 1);
        if (i)
            change(min(a[i - 1], a[i]), -1);
    }
    for (auto op : ops)
        if (op.type == 1) {
            int r = lower_bound(values.begin(), values.end(), op.x) - values.begin();
            cout << bit.sum(values.size()) - bit.sum(r) << '\n';
        } else {
            int p = op.p;
            change(a[p], -1);
            if (p)
                change(min(a[p - 1], a[p]), 1);
            if (p + 1 < n)
                change(min(a[p], a[p + 1]), 1);
            a[p] = op.x;
            change(a[p], 1);
            if (p)
                change(min(a[p - 1], a[p]), -1);
            if (p + 1 < n)
                change(min(a[p], a[p + 1]), -1);
        }

    return 0;
}
```

### 实现提醒

与水面持平仍可见；边贡献为负一；修改时先移除旧相邻边。

## P3645 雅加达的摩天楼

原题：[P3645](https://www.luogu.com.cn/problem/P3645)

### 思路

小跳长 p 建立“仍持有 p”的位置状态，可左右一步跳并随时换狗；大跳长从当前楼直接枚举所有可到楼，边权为跳数。对隐式分层图运行 Dijkstra。

### 复杂度

时间 O((nB+mn/B) log(nB))，空间 O(nB+m)，B≈sqrt(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int B = max(2, (int)sqrt(n) + 1), start = 0, goal = 0;
    vector<vector<int>> dogs(n);
    for (int i = 0; i < m; i++) {
        int b, p;
        cin >> b >> p;
        dogs[b].push_back(p);
        if (i == 0)
            start = b;
        if (i == 1)
            goal = b;
    }
    for (auto &v : dogs) {
        sort(v.begin(), v.end());
        v.erase(unique(v.begin(), v.end()), v.end());
    }
    const int INF = 1000000000;
    vector<int> d(n * B, INF);
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> heap;
    d[start] = 0;
    heap.push({0, start});
    auto relax = [&](int state, int value) {
        if (value < d[state]) {
            d[state] = value;
            heap.push({value, state});
        }
    };
    while (!heap.empty()) {
        auto [dist, state] = heap.top();
        heap.pop();
        if (d[state] != dist)
            continue;
        int p = state / n, v = state % n;
        if (!p) {
            if (v == goal) {
                cout << dist << '\n';
                return 0;
            }
            for (int jump : dogs[v]) {
                if (jump < B)
                    relax(jump * n + v, dist);
                else {
                    int cost = 1;
                    for (int u = v + jump; u < n; u += jump, cost++)
                        relax(u, dist + cost);
                    cost = 1;
                    for (int u = v - jump; u >= 0; u -= jump, cost++)
                        relax(u, dist + cost);
                }
            }
        } else {
            relax(v, dist);
            if (v + p < n)
                relax(p * n + v + p, dist + 1);
            if (v - p >= 0)
                relax(p * n + v - p, dist + 1);
        }
    }
    cout << -1 << '\n';

    return 0;
}
```

### 实现提醒

进入小跳层不花步数；普通状态才能换狗；起终来自前两条记录。

## P3802 小魔女帕琪

原题：[P3802](https://www.luogu.com.cn/problem/P3802)

### 思路

总晶体数为 S，每个连续七次施法成为七重奏的概率相同，为 7!∏a_i/[S(S−1)…(S−6)]。共有 S−6 个窗口，乘起来就是期望。

### 复杂度

时间 O(1)，空间 O(1)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a[7], sum = 0;
    for (auto &x : a) {
        cin >> x;
        sum += x;
    }
    long double ans = 0;
    if (sum >= 7) {
        ans = 5040.0L * (sum - 6);
        for (int i = 0; i < 7; i++)
            ans = ans * a[i] / (sum - i);
    }
    cout << fixed << setprecision(3) << ans << '\n';

    return 0;
}
```

### 实现提醒

