## P4171 满汉全席

原题：[P4171](https://www.luogu.com.cn/problem/P4171)

### 思路

一个评审要求的两道菜至少做一道，即子句 A 或 B。加入非 A→B、非 B→A 两条蕴含边；某食材的满式与汉式在同一个强连通分量时无解。

### 复杂度

每组时间 O(n+m)，空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SCC {
    int n, count = 0;
    vector<vector<int>> g, rev;
    vector<int> component;
    explicit SCC(int n) : n(n), g(n), rev(n), component(n, -1) {}
    void edge(int a, int b) {
        g[a].push_back(b);
        rev[b].push_back(a);
    }
    void build() {
        vector<char> seen(n);
        vector<int> order;
        for (int start = 0; start < n; start++)
            if (!seen[start]) {
                vector<pair<int, int>> st = {{start, 0}};
                seen[start] = true;
                while (!st.empty()) {
                    int v = st.back().first;
                    int &i = st.back().second;
                    if (i < (int)g[v].size()) {
                        int u = g[v][i++];
                        if (!seen[u]) {
                            seen[u] = true;
                            st.push_back({u, 0});
                        }
                    } else {
                        order.push_back(v);
                        st.pop_back();
                    }
                }
            }
        reverse(order.begin(), order.end());
        for (int start : order)
            if (component[start] < 0) {
                vector<int> st = {start};
                component[start] = count;
                while (!st.empty()) {
                    int v = st.back();
                    st.pop_back();
                    for (int u : rev[v])
                        if (component[u] < 0) {
                            component[u] = count;
                            st.push_back(u);
                        }
                }
                count++;
            }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tests;
    cin >> tests;
    while (tests--) {
        int n, m;
        cin >> n >> m;
        SCC s(2 * n);
        while (m--) {
            string a, b;
            cin >> a >> b;
            auto id = [](string v) { return 2 * (stoi(v.substr(1)) - 1) + (v[0] == 'm'); };
            int x = id(a), y = id(b);
            s.edge(x ^ 1, y);
            s.edge(y ^ 1, x);
        }
        s.build();
        bool ok = true;
        for (int i = 0; i < n; i++)
            if (s.component[2 * i] == s.component[2 * i + 1])
                ok = false;
        cout << (ok ? "GOOD" : "BAD") << '\n';
    }

    return 0;
}
```

### 实现提醒

m 表示满式，h 表示汉式；否定文字用 ^1；每组重新建图。

## P4284 概率充电器

原题：[P4284](https://www.luogu.com.cn/problem/P4284)

### 思路

先求每个子树都无法使根点通电的概率，再从根向下传递来自子树外的断电概率。点未通电概率是两者乘积，期望通电数为 Σ(1−未通电概率)。

### 复杂度

时间 O(n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<pair<int, long double>>> g(n);
    for (int i = 1; i < n; i++) {
        int a, b;
        long double p;
        cin >> a >> b >> p;
        a--;
        b--;
        p /= 100;
        g[a].push_back({b, p});
        g[b].push_back({a, p});
    }
    vector<long double> self(n), down(n), outside(n, 1), edge(n);
    for (auto &x : self) {
        cin >> x;
        x /= 100;
    }
    vector<int> parent(n, -1), order = {0};
    parent[0] = 0;
    for (int i = 0; i < n; i++)
        for (auto [u, p] : g[order[i]])
            if (parent[u] < 0) {
                parent[u] = order[i];
                edge[u] = p;
                order.push_back(u);
            }
    for (int i = n - 1; i >= 0; i--) {
        int v = order[i];
        down[v] = 1 - self[v];
        for (auto [u, p] : g[v])
            if (parent[u] == v)
                down[v] *= 1 - p + p * down[u];
    }
    long double ans = 0;
    for (int v : order) {
        ans += 1 - down[v] * outside[v];
        vector<int> children;
        vector<long double> factors;
        for (auto [u, p] : g[v])
            if (parent[u] == v) {
                children.push_back(u);
                factors.push_back(1 - p + p * down[u]);
            }
        int z = children.size();
        vector<long double> prefix(z + 1, 1), suffix(z + 1, 1);
        for (int i = 0; i < z; i++)
            prefix[i + 1] = prefix[i] * factors[i];
        for (int i = z - 1; i >= 0; i--)
            suffix[i] = suffix[i + 1] * factors[i];
        for (int i = 0; i < z; i++) {
            int u = children[i];
            long double no = outside[v] * (1 - self[v]) * prefix[i] * suffix[i + 1];
            outside[u] = 1 - edge[u] + edge[u] * no;
        }
    }
    cout << fixed << setprecision(6) << ans << '\n';

    return 0;
}
```

### 实现提醒

输入百分数除以一百；零因子用前后缀乘积；答案保留六位小数。

## P4391 Radio Transmission 无线传输

原题：[P4391](https://www.luogu.com.cn/problem/P4391)

### 思路

求整个字符串的最长真前后缀长度 b，答案为 n−b。电台发送的最后一轮可以不完整，因此不要求周期长度整除 n。

### 复杂度

时间 O(n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> prefix(const string &s) {
    vector<int> p(s.size());
    for (int i = 1; i < (int)s.size(); i++) {
        int j = p[i - 1];
        while (j && s[i] != s[j])
            j = p[j - 1];
        if (s[i] == s[j])
            j++;
        p[i] = j;
    }
    return p;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;
    auto p = prefix(s);
    cout << n - p.back() << '\n';

    return 0;
}
```

### 实现提醒

无需检验 n%周期；输入含给定长度。

## P4398 Blue Mary的战役地图

原题：[P4398](https://www.luogu.com.cn/problem/P4398)

### 思路

固定第二张图相对第一张图的平移后，每对对齐格子的相等关系固定。对重叠区域求全为相等格的最大正方形，枚举所有平移取最大值。

### 复杂度

时间 O(n⁴)，空间 O(n²)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> a(n, vector<int>(n)), b = a;
    for (auto &row : a)
        for (int &x : row)
            cin >> x;
    for (auto &row : b)
        for (int &x : row)
            cin >> x;
    int ans = 0;
    for (int dx = 1 - n; dx < n; dx++)
        for (int dy = 1 - n; dy < n; dy++) {
            vector<vector<int>> dp(n + 1, vector<int>(n + 1));
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++) {
                    int x = i + dx, y = j + dy;
                    if (x >= 0 && x < n && y >= 0 && y < n && a[i][j] == b[x][y]) {
                        dp[i + 1][j + 1] = 1 + min({dp[i][j + 1], dp[i + 1][j], dp[i][j]});
                        ans = max(ans, dp[i + 1][j + 1]);
                    }
                }
        }
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

只允许平移，不旋转；越界格当不相等；DP 取三个方向最小值。

## P4407 电子字典

原题：[P4407](https://www.luogu.com.cn/problem/P4407)

### 思路

若查询词已在字典中，输出 -1。否则枚举删除一个字符、替换一个字符、插入一个字符产生的所有字符串，用字典查找，并把命中的单词去重计数。

### 复杂度

平均时间 O(M·26L²+NL)，空间 O(NL+26L²)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    unordered_set<string> dict;
    while (n--) {
        string s;
        cin >> s;
        dict.insert(s);
    }
    while (m--) {
        string s;
        cin >> s;
        if (dict.count(s)) {
            cout << -1 << '\n';
            continue;
        }
        unordered_set<string> found;
        auto test = [&](const string &v) {
            if (dict.count(v))
                found.insert(v);
        };
        for (int i = 0; i < (int)s.size(); i++) {
            test(s.substr(0, i) + s.substr(i + 1));
            string v = s;
            for (char c = 'a'; c <= 'z'; c++) {
                v[i] = c;
                test(v);
            }
        }
        for (int i = 0; i <= (int)s.size(); i++)
            for (char c = 'a'; c <= 'z'; c++)
                test(s.substr(0, i) + c + s.substr(i));
        cout << found.size() << '\n';
    }

    return 0;
}
```

### 实现提醒

先判断完全相等；命中单词要去重；插入位置包含末尾。

## P4408 逃学的小孩 / 数据生成器

原题：[P4408](https://www.luogu.com.cn/problem/P4408)

### 思路

求树直径端点 A、B，保留所有点到两端的距离。答案是直径长度加上 max_v min(dist(A,v),dist(B,v))。

### 复杂度

时间 O(n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<vector<pair<int, long long>>> g(n);
    while (m--) {
        int a, b;
        long long w;
        cin >> a >> b >> w;
        a--;
        b--;
        g[a].push_back({b, w});
        g[b].push_back({a, w});
    }
    auto distances = [&](int s) {
        vector<long long> d(n, -1);
        vector<int> q = {s};
        d[s] = 0;
        for (int i = 0; i < (int)q.size(); i++)
            for (auto [u, w] : g[q[i]])
                if (d[u] < 0) {
                    d[u] = d[q[i]] + w;
                    q.push_back(u);
                }
        return d;
    };
    auto d = distances(0);
    int A = max_element(d.begin(), d.end()) - d.begin();
    auto x = distances(A);
    int B = max_element(x.begin(), x.end()) - x.begin();
    auto y = distances(B);
    long long extra = 0;
    for (int i = 0; i < n; i++)
        extra = max(extra, min(x[i], y[i]));
    cout << x[B] + extra << '\n';

    return 0;
}
```

### 实现提醒

边权可为零；答案和路径长度用 long long；按较近的朋友先找。

## P4462 异或序列

原题：[P4462](https://www.luogu.com.cn/problem/P4462)

### 思路

定义前缀异或 p，子区间异或等于 k 等价于两个前缀值异或为 k。把 [l,r] 改为前缀下标区间 [l−1,r]，用莫队维护其中符合条件的不同下标对数。

### 复杂度

时间 O((n+q)sqrt n+n log n)，空间 O(n+q)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q, k;
    cin >> n >> q >> k;
    vector<int> p(n + 1), values;
    for (int i = 1, x; i <= n; i++) {
        cin >> x;
        p[i] = p[i - 1] ^ x;
    }
    for (int v : p) {
        values.push_back(v);
        values.push_back(v ^ k);
    }
    sort(values.begin(), values.end());
    values.erase(unique(values.begin(), values.end()), values.end());
    vector<int> id(n + 1), partner(n + 1);
    for (int i = 0; i <= n; i++) {
        id[i] = lower_bound(values.begin(), values.end(), p[i]) - values.begin();
        partner[i] = lower_bound(values.begin(), values.end(), p[i] ^ k) - values.begin();
    }

    struct Query {
        int l, r, id;
    };
    vector<Query> queries(q);
    for (int i = 0; i < q; i++) {
        cin >> queries[i].l >> queries[i].r;
        queries[i].id = i;
    }
    int block = max(1, (int)sqrt(n));
    sort(queries.begin(), queries.end(), [&](Query a, Query b) {
        if (a.l / block != b.l / block)
            return a.l < b.l;
        return (a.l / block) & 1 ? a.r > b.r : a.r < b.r;
    });

    vector<int> freq(values.size());
    vector<long long> ans(q);
    long long current = 0;
    auto add = [&](int i) {
        current += freq[partner[i]];
        freq[id[i]]++;
    };
    auto remove = [&](int i) {
        freq[id[i]]--;
        current -= freq[partner[i]];
    };
    int l = 0, r = -1;
    for (auto x : queries) {
        x.l--;
        while (l > x.l)
            add(--l);
        while (r < x.r)
            add(++r);
        while (l < x.l)
            remove(l++);
        while (r > x.r)
            remove(r--);
        ans[x.id] = current;
    }
    for (long long x : ans)
        cout << x << '\n';

    return 0;
}
```

### 实现提醒

左端要减一；包含 p[0]=0；删除先减频次，尤其注意 k=0。

