## P4551 最长异或路径

原题：[P4551](https://www.luogu.com.cn/problem/P4551)

### 思路

任选根，记录根到每点的边权异或 d。两点路径异或为 d[u] xor d[v]。把所有 d 插入二进制字典树，逐位优先走相反位，求最大异或值。

### 复杂度

时间 O(n log W)，空间 O(n log W)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<pair<int, int>>> g(n);
    for (int i = 1; i < n; i++) {
        int a, b, w;
        cin >> a >> b >> w;
        a--;
        b--;
        g[a].push_back({b, w});
        g[b].push_back({a, w});
    }
    vector<int> d(n), parent(n, -1), order = {0};
    parent[0] = 0;
    for (int i = 0; i < (int)order.size(); i++) {
        int v = order[i];
        for (auto [u, w] : g[v])
            if (u != parent[v]) {
                parent[u] = v;
                d[u] = d[v] ^ w;
                order.push_back(u);
            }
    }
    vector<array<int, 2>> t(1);
    for (int x : d) {
        int v = 0;
        for (int b = 30; b >= 0; b--) {
            int bit = (x >> b) & 1;
            if (!t[v][bit]) {
                t[v][bit] = t.size();
                t.push_back({0, 0});
            }
            v = t[v][bit];
        }
    }
    int ans = 0;
    for (int x : d) {
        int v = 0, value = 0;
        for (int b = 30; b >= 0; b--) {
            int bit = (x >> b) & 1;
            if (t[v][bit ^ 1]) {
                value |= 1 << b;
                v = t[v][bit ^ 1];
            } else
                v = t[v][bit];
        }
        ans = max(ans, value);
    }
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

先求根路径异或而非距离和；高位优先；非递归遍历避免长链栈溢出。

## P4683 Type Printer

原题：[P4683](https://www.luogu.com.cn/problem/P4683)

### 思路

所有单词组成 Trie。每条非最终路径边至少走去回两次，最终停留路径只需走一次，所以选择最长根路径最后访问。遇到单词结点输出打印操作。

### 复杂度

设总字符数为 S，时间 O(26S)，空间 O(S)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    struct Node {
        array<int, 26> next{};
        bool terminal = false;
        int height = 0;
    };
    vector<Node> trie(1);
    while (n--) {
        string s;
        cin >> s;
        int v = 0;
        for (char c : s) {
            int x = c - 'a';
            if (!trie[v].next[x]) {
                trie[v].next[x] = trie.size();
                trie.emplace_back();
            }
            v = trie[v].next[x];
        }
        trie[v].terminal = true;
    }
    for (int v = (int)trie.size() - 1; v >= 0; v--)
        for (int u : trie[v].next)
            if (u)
                trie[v].height = max(trie[v].height, trie[u].height + 1);
    string ops;
    function<void(int)> dfs = [&](int v) {
        if (trie[v].terminal)
            ops += 'P';
        int last = -1;
        for (int c = 0; c < 26; c++)
            if (trie[v].next[c] &&
                (last < 0 || trie[trie[v].next[c]].height > trie[trie[v].next[last]].height))
                last = c;
        for (int c = 0; c < 26; c++)
            if (trie[v].next[c] && c != last) {
                ops += char('a' + c);
                dfs(trie[v].next[c]);
                ops += '-';
            }
        if (last >= 0) {
            ops += char('a' + last);
            dfs(trie[v].next[last]);
            ops += '-';
        }
    };
    dfs(0);
    while (!ops.empty() && ops.back() == '-')
        ops.pop_back();
    cout << ops.size() << '\n';
    for (char c : ops)
        cout << c << '\n';

    return 0;
}
```

### 实现提醒

最终不要求清空；最长分支最后走；P 也是一次操作。

## P4799 世界冰球锦标赛 (Day2)

原题：[P4799](https://www.luogu.com.cn/problem/P4799)

### 思路

分别枚举两半装备的价格和并保留不超过预算的值。排序右半，对每个左半价格 x，用 upper_bound 统计右半中不超过 M−x 的个数。

### 复杂度

时间 O(n·2^(n/2))，空间 O(2^(n/2))。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;
    vector<long long> a(n);
    for (auto &x : a)
        cin >> x;
    auto generate = [&](int l, int r) {
        vector<long long> s = {0};
        for (int i = l; i < r; i++) {
            int size = s.size();
            for (int j = 0; j < size; j++)
                if (a[i] <= m - s[j])
                    s.push_back(s[j] + a[i]);
        }
        return s;
    };
    auto l = generate(0, n / 2), r = generate(n / 2, n);
    sort(r.begin(), r.end());
    long long ans = 0;
    for (long long x : l)
        ans += upper_bound(r.begin(), r.end(), m - x) - r.begin();
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

相同价格的不同子集不能去重；答案和预算都用 long long。

## P4819 杀人游戏

原题：[P4819](https://www.luogu.com.cn/problem/P4819)

### 思路

每个源强连通分量通常必须查证一人，风险人数为源分量数。若存在单点源，且它指向的每个分量还有其它入边，就能把此人留到最后推断，风险人数再减一。

### 复杂度

时间 O((n+m) log m)，空间 O(n+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SCC {
    int n, count = 0;
    vector<vector<int>> g, rev;
    vector<int> component;
    explicit SCC(int n) : n(n), g(n), rev(n), component(n, -1) {}
    void edge(int a, int b) {
        g[a].push_back(b);
        rev[b].push_back(a);
    }
    void build() {
        vector<char> seen(n);
        vector<int> order;
        for (int start = 0; start < n; start++)
            if (!seen[start]) {
                vector<pair<int, int>> st = {{start, 0}};
                seen[start] = true;
                while (!st.empty()) {
                    int v = st.back().first;
                    int &i = st.back().second;
                    if (i < (int)g[v].size()) {
                        int u = g[v][i++];
                        if (!seen[u]) {
                            seen[u] = true;
                            st.push_back({u, 0});
                        }
                    } else {
                        order.push_back(v);
                        st.pop_back();
                    }
                }
            }
        reverse(order.begin(), order.end());
        for (int start : order)
            if (component[start] < 0) {
                vector<int> st = {start};
                component[start] = count;
                while (!st.empty()) {
                    int v = st.back();
                    st.pop_back();
                    for (int u : rev[v])
                        if (component[u] < 0) {
                            component[u] = count;
                            st.push_back(u);
                        }
                }
                count++;
            }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    SCC s(n);
    while (m--) {
        int a, b;
        cin >> a >> b;
        s.edge(a - 1, b - 1);
    }
    s.build();
    vector<int> size(s.count), in(s.count);
    vector<pair<int, int>> edges;
    for (int v = 0; v < n; v++) {
        size[s.component[v]]++;
        for (int u : s.g[v])
            if (s.component[v] != s.component[u])
                edges.push_back({s.component[v], s.component[u]});
    }
    sort(edges.begin(), edges.end());
    edges.erase(unique(edges.begin(), edges.end()), edges.end());
    vector<vector<int>> g(s.count);
    for (auto [a, b] : edges) {
        g[a].push_back(b);
        in[b]++;
    }
    int risk = count(in.begin(), in.end(), 0);
    for (int c = 0; c < s.count; c++)
        if (!in[c] && size[c] == 1) {
            bool ok = true;
            for (int u : g[c])
                if (in[u] == 1)
                    ok = false;
            if (ok) {
                risk--;
                break;
            }
        }
    cout << fixed << setprecision(6) << 1.0 - (double)risk / n << '\n';

    return 0;
}
```

### 实现提醒

统计不同来源的入边，重边去重；最多省一次；输出六位小数。

## P4822 冻结

原题：[P4822](https://www.luogu.com.cn/problem/P4822)

### 思路

状态记录城市和已使用卡片数。走一条路可以保持层数、支付原价，也可以在卡片够用时进入下一层、支付一半。对这些状态跑 Dijkstra，取终点各层的最小距离。

### 复杂度

时间 O((nK+mK) log(nK))，空间 O(nK+m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, K;
    cin >> n >> m >> K;
    vector<vector<pair<int, int>>> g(n);
    while (m--) {
        int u, v, w;
        cin >> u >> v >> w;
        u--;
        v--;
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }
    const long long INF = 1LL << 60;
    vector<long long> d(n * (K + 1), INF);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>,
                   greater<pair<long long, int>>>
        q;
    d[0] = 0;
    q.push({0, 0});
    while (!q.empty()) {
        auto [dist, state] = q.top();
        q.pop();
        if (dist != d[state])
            continue;
        int used = state / n, v = state % n;
        for (auto [u, w] : g[v])
            for (int take = 0; take <= 1 && used + take <= K; take++) {
                int next = (used + take) * n + u;
                long long nd = dist + (take ? w / 2 : w);
                if (nd < d[next]) {
                    d[next] = nd;
                    q.push({nd, next});
                }
            }
    }
    long long ans = INF;
    for (int k = 0; k <= K; k++)
        ans = min(ans, d[k * n + n - 1]);
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

同一条路不能连续叠卡；允许少用卡；道路双向。

## P4824 Censoring S

原题：[P4824](https://www.luogu.com.cn/problem/P4824)

### 思路

逐字读入原串，把字符与当前模式匹配长度一起压栈。每当匹配完整个待删串，就弹出对应长度；新的匹配状态从栈顶恢复。

看原串 aababa、模式 aba：第一次删掉末尾 aba 后，栈里还剩 a，匹配长度应恢复为 1；后面读入 ba 会再次删除。若错误地清零，就会漏掉第二次匹配。

![删除后为什么要恢复栈顶状态](assets/stack-kmp.svg)

### 复杂度

时间 O(|原串|+|待删串|)，空间 O(|原串|+|待删串|)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> prefix(const string &s) {
    vector<int> p(s.size());
    for (int i = 1; i < (int)s.size(); i++) {
        int j = p[i - 1];
        while (j && s[i] != s[j])
            j = p[j - 1];
        if (s[i] == s[j])
            j++;
        p[i] = j;
    }
    return p;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;
    auto p = prefix(t);
    string out;
    vector<int> state;
    for (char c : s) {
        int j = state.empty() ? 0 : state.back();
        while (j && c != t[j])
            j = p[j - 1];
        if (c == t[j])
            j++;
        out.push_back(c);
        state.push_back(j);
        if (j == (int)t.size()) {
            out.resize(out.size() - t.size());
            state.resize(state.size() - t.size());
        }
    }
    cout << out << '\n';

    return 0;
}
```

### 实现提醒

删除后恢复旧栈顶状态；模式可能重叠；不要每次重新扫描完整结果。

## P4863 JerryC Loves Driving

原题：[P4863](https://www.luogu.com.cn/problem/P4863)

### 思路

用前缀函数 F(N) 表示 1 到 N 的总愉悦值。交换求和顺序后，对每个 j 计算 Σ(i=1..N) floor(i/j)，再按 j 奇偶加减；区间答案为 F(B)−F(A−1)。

### 复杂度

时间 O(B)，空间 O(1)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b;
    cin >> a >> b;
    auto solve = [](long long n) {
        long long ans = 0;
        for (long long j = 1; j <= n; j++) {
            long long q = n / j;
            long long value = j * q * (q - 1) / 2 + q * (n - q * j + 1);
            ans += (j % 2 ? -value : value);
        }
        return ans;
    };
    cout << solve(b) - solve(a - 1) << '\n';

    return 0;
}
```

### 实现提醒

(-1)^j 对奇数是负；F(0)=0；乘法先用六十四位。

## P4884 多少个 1？

原题：[P4884](https://www.luogu.com.cn/problem/P4884)

### 思路

全一数 R_N=(10^N−1)/9，因质数 m≥7，9 在模 m 下可逆，所以原式等价于 10^N≡9K+1(mod m)。用 BSGS 求最小指数。

### 复杂度

平均时间 O(sqrt m)，空间 O(sqrt m)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

long long multiply(long long a, long long b, long long mod) { return (__int128)a * b % mod; }
long long modularPower(long long a, long long b, long long mod) {
    long long ans = 1;
    for (; b; b >>= 1, a = multiply(a, a, mod))
        if (b & 1)
            ans = multiply(ans, a, mod);
    return ans;
}
long long logarithm(long long base, long long target, long long mod) {
    long long block = sqrt((long double)mod) + 1;
    unordered_map<long long, int> baby;
    baby.reserve(2 * block);
    long long value = 1;
    for (int j = 0; j < block; j++) {
        baby.emplace(value, j);
        value = multiply(value, base, mod);
    }
    long long inverse = modularPower(value, mod - 2, mod);
    value = target;
    for (long long i = 0; i <= block; i++) {
        auto it = baby.find(value);
        if (it != baby.end())
            return i * block + it->second;
        value = multiply(value, inverse, mod);
    }
    return -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long k, m;
    cin >> k >> m;
    cout << logarithm(10, (9 * k + 1) % m, m) << '\n';

    return 0;
}
```

### 实现提醒

利用质数保证九可逆；模乘使用 __int128；答案要求正整数。

## P4888 三去矩阵

原题：[P4888](https://www.luogu.com.cn/problem/P4888)

### 思路

每次询问分别沿所在行和列向两侧同步扩展，只要两侧字母相同就继续。中心固定为一个格子，因此只需检查奇数长度回文，取水平和竖直的最大值。

### 复杂度

每次 O(l)，总时间 O(l²+ql)，空间 O(l²)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    vector<string> a(n);
    for (auto &s : a)
        cin >> s;
    while (q--) {
        int x, y;
        cin >> x >> y;
        x--;
        y--;
        int horizontal = 0, vertical = 0;
        while (y - horizontal - 1 >= 0 && y + horizontal + 1 < n &&
               a[x][y - horizontal - 1] == a[x][y + horizontal + 1])
            horizontal++;
        while (x - vertical - 1 >= 0 && x + vertical + 1 < n &&
               a[x - vertical - 1][y] == a[x + vertical + 1][y])
            vertical++;
        cout << 2 * max(horizontal, vertical) + 1 << '\n';
    }

    return 0;
}
```

### 实现提醒

坐标转为 0 起始；只取水平或竖直，不能走对角线；中心本身长度为 1。

## P4961 小埋与扫雷

原题：[P4961](https://www.luogu.com.cn/problem/P4961)

### 思路

先计算每个非雷格周围雷数。每个八连通零格块只需点一次，并会自动展开周围数字；最后仍未展开的非雷数字格各需再点一次。

### 复杂度

时间 O(nm)，空间 O(nm)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<vector<int>> a(n, vector<int>(m)), near = a;
    for (auto &row : a)
        for (int &x : row)
            cin >> x;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            for (int dx = -1; dx <= 1; dx++)
                for (int dy = -1; dy <= 1; dy++) {
                    int x = i + dx, y = j + dy;
                    if (x >= 0 && x < n && y >= 0 && y < m)
                        near[i][j] += a[x][y];
                }
    vector<vector<char>> seen(n, vector<char>(m));
    int ans = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (!a[i][j] && !near[i][j] && !seen[i][j]) {
                ans++;
                queue<pair<int, int>> q;
                q.push({i, j});
                seen[i][j] = 1;
                while (!q.empty()) {
                    auto [x, y] = q.front();
                    q.pop();
                    for (int dx = -1; dx <= 1; dx++)
                        for (int dy = -1; dy <= 1; dy++) {
                            int u = x + dx, v = y + dy;
                            if (u >= 0 && u < n && v >= 0 && v < m && !a[u][v] && !seen[u][v]) {
                                seen[u][v] = 1;
                                if (!near[u][v])
                                    q.push({u, v});
                            }
                        }
                }
            }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (!a[i][j] && !seen[i][j])
                ans++;
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

使用八邻域；数字只标记，不继续入队扩张；雷格始终不点击。

## P5018 对称二叉树

原题：[P5018](https://www.luogu.com.cn/problem/P5018)

### 思路

自底向上为 (点权,左子树编号,右子树编号) 分配唯一编号，同时计算交换左右后的镜像编号。两编号相等时，该子树对称；取其中最大节点数。

### 复杂度

时间 O(n log n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> w(n + 1), l(n + 1), r(n + 1), id(n + 1), mirror(n + 1), size(n + 1);
    for (int i = 1; i <= n; i++)
        cin >> w[i];
    for (int i = 1; i <= n; i++) {
        cin >> l[i] >> r[i];
        l[i] = max(l[i], 0);
        r[i] = max(r[i], 0);
    }
    vector<int> order = {1};
    for (int i = 0; i < (int)order.size(); i++) {
        int v = order[i];
        if (l[v])
            order.push_back(l[v]);
        if (r[v])
            order.push_back(r[v]);
    }
    map<tuple<int, int, int>, int> ids;
    auto intern = [&](int value, int a, int b) {
        auto key = make_tuple(value, a, b);
        auto it = ids.find(key);
        if (it != ids.end())
            return it->second;
        int index = ids.size() + 1;
        ids.emplace(key, index);
        return index;
    };
    int ans = 0;
    for (int i = n - 1; i >= 0; i--) {
        int v = order[i];
        id[v] = intern(w[v], id[l[v]], id[r[v]]);
        mirror[v] = intern(w[v], mirror[r[v]], mirror[l[v]]);
        size[v] = size[l[v]] + size[r[v]] + 1;
        if (id[v] == mirror[v])
            ans = max(ans, size[v]);
    }
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

孩子 -1 转为空树 0；点权也属于结构；使用真实遍历顺序倒序处理。

## P5335 补退选

原题：[P5335](https://www.luogu.com.cn/problem/P5335)

### 思路

维护每个前缀当前学生数。人数第一次升到 h 时，记录事件编号。查询人数曾经超过 v 的最早时间，直接取第一次达到 v+1 的记录；退课只改当前人数。

### 复杂度

设所有操作字符串总长为 S，时间 O(10S)，空间 O(S)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    struct Node {
        int child = -1, next = -1, letter = 0, count = 0, first = 0, history = -1;
    };
    vector<Node> trie(1);
    trie.reserve(60LL * n + 1);
    vector<vector<int>> history;
    long long last = 0;
    for (int event = 1; event <= n; event++) {
        int type;
        string s;
        cin >> type >> s;
        int v = 0;
        bool found = true;
        for (char c : s) {
            int u = trie[v].child;
            while (u >= 0 && trie[u].letter != c - 'a')
                u = trie[u].next;
            if (u < 0) {
                if (type == 3) {
                    found = false;
                    break;
                }
                u = trie.size();
                Node node;
                node.letter = c - 'a';
                node.next = trie[v].child;
                trie.push_back(node);
                trie[v].child = u;
            }
            v = u;
            if (type != 3) {
                trie[v].count += type == 1 ? 1 : -1;
                if (trie[v].count == 1 && !trie[v].first)
                    trie[v].first = event;
                else if (trie[v].count >= 2) {
                    int h = trie[v].history;
                    if (h < 0) {
                        h = history.size();
                        history.push_back({});
                        trie[v].history = h;
                    }
                    if (trie[v].count > (int)history[h].size() + 1)
                        history[h].push_back(event);
                }
            }
        }
        if (type == 3) {
            long long a, b, c;
            cin >> a >> b >> c;
            long long threshold = ((__int128)a * llabs(last) + b) % c;
            last = -1;
            if (found) {
                if (threshold == 0 && trie[v].first)
                    last = trie[v].first;
                else if (threshold >= 1 && trie[v].history >= 0) {
                    auto &h = history[trie[v].history];
                    if (threshold - 1 < (long long)h.size())
                        last = h[threshold - 1];
                }
            }
            cout << last << '\n';
        }
    }

    return 0;
}
```

### 实现提醒

查询也占事件编号；退课保留历史；解码用上次答案绝对值；同名学生分别计数。

## P5426 Balancing Inversions G

原题：[P5426](https://www.luogu.com.cn/problem/P5426)

### 思路

不跨中线时用两半逆序数差的绝对值补齐。跨中线只需考虑同一方向，把左侧最靠右的一类字符与右侧最靠左的另一类字符依次交换，维护必要代价和新的逆序差。

样例中把中线的 01 换成 10，只需一次交换便使两半逆序数相等。跨中线操作可能同时改变两侧逆序数，计算时使用推导的固定差值。

![跨中线交换对逆序差的影响](assets/central-inversion-swap.svg)

### 复杂度

时间 O(n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(2 * n);
    int ones = 0;
    for (int &x : a) {
        cin >> x;
        ones += x;
    }
    auto inversions = [&](int l, int r) {
        long long count = 0, answer = 0;
        for (int i = l; i < r; i++)
            if (a[i])
                count++;
            else
                answer += count;
        return answer;
    };
    long long initial = inversions(0, n) - inversions(n, 2 * n), ans = llabs(initial);
    for (int bit = 0; bit < 2; bit++) {
        vector<int> left, right;
        for (int i = n - 1; i >= 0; i--)
            if (a[i] == bit)
                left.push_back(i);
        for (int i = 0; i < n; i++)
            if (a[n + i] != bit)
                right.push_back(i);
        long long delta = initial, cost = 0;
        int sign = bit ? 1 : -1;
        for (int i = 0; i < (int)min(left.size(), right.size()); i++) {
            long long q = left[i], z = right[i];
            cost += n - q + z;
            delta += sign * (q + z - 2 * n + 1 + ones);
            ans = min(ans, cost + llabs(delta));
        }
    }
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

z 使用右半局部下标；两种跨线方向均枚举；代价和逆序差用 long long。

