## P5446 绿绿和串串

原题：[P5446](https://www.luogu.com.cn/problem/P5446)

### 思路

初始长度 m>1 时，反复翻转得到周期 2(m−1) 的无限镜像串。候选 m 必须满足这个周期，并且以 m−1 为中心的可见部分是回文；用 Z 函数与 Manacher 常数时间检查每个 m。

### 复杂度

时间 O(n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

pair<vector<int>, vector<int>> manacher(const string &s) {
    int n = s.size();
    vector<int> odd(n), even(n);
    for (int i = 0, l = 0, r = -1; i < n; i++) {
        int k = i > r ? 1 : min(odd[l + r - i], r - i + 1);
        while (i - k >= 0 && i + k < n && s[i - k] == s[i + k])
            k++;
        odd[i] = k;
        if (i + k - 1 > r) {
            l = i - k + 1;
            r = i + k - 1;
        }
    }
    for (int i = 0, l = 0, r = -1; i < n; i++) {
        int k = i > r ? 0 : min(even[l + r - i + 1], r - i + 1);
        while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k])
            k++;
        even[i] = k;
        if (i + k - 1 > r) {
            l = i - k;
            r = i + k - 1;
        }
    }
    return {move(odd), move(even)};
}

vector<int> zfunction(const string &s) {
    int n = s.size();
    vector<int> z(n);
    z[0] = n;
    for (int i = 1, l = 0, r = 0; i < n; i++) {
        if (i <= r)
            z[i] = min(r - i + 1, z[i - l]);
        while (i + z[i] < n && s[z[i]] == s[i + z[i]])
            z[i]++;
        if (i + z[i] - 1 > r) {
            l = i;
            r = i + z[i] - 1;
        }
    }
    return z;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        string s;
        cin >> s;
        int n = s.size();
        auto z = zfunction(s);
        auto [odd, even] = manacher(s);
        vector<int> ans;
        if (all_of(s.begin(), s.end(), [&](char c) { return c == s[0]; }))
            ans.push_back(1);
        for (int m = 2; m <= n; m++) {
            int L = m - 1;
            if (odd[L] < min(L + 1, n - L))
                continue;
            if (2 * L < n && z[2 * L] < n - 2 * L)
                continue;
            ans.push_back(m);
        }
        for (int i = 0; i < (int)ans.size(); i++)
            cout << ans[i] << (i + 1 == (int)ans.size() ? '\n' : ' ');
    }

    return 0;
}
```

### 实现提醒

镜像不重复末字符；周期是 2(m−1)；长度一单独处理。

## P5451 密码学第三次小作业

原题：[P5451](https://www.luogu.com.cn/problem/P5451)

### 思路

扩展欧几里得求 a·e1+b·e2=1，则 m≡c1^a·c2^b mod N。负指数改用密文的模逆元，所有模乘用 __int128。

### 复杂度

每组时间 O(log N+log e1+log e2)，空间 O(log N) 递归栈。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

long long egcd(long long a, long long b, __int128 &x, __int128 &y) {
    if (!b) {
        x = 1;
        y = 0;
        return a;
    }
    __int128 u, v;
    long long g = egcd(b, a % b, u, v);
    x = v;
    y = u - (__int128)(a / b) * v;
    return g;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        long long c1, c2, e1, e2, N;
        cin >> c1 >> c2 >> e1 >> e2 >> N;
        __int128 a, b;
        egcd(e1, e2, a, b);
        auto inverse = [&](long long x) {
            __int128 u, v;
            egcd(x, N, u, v);
            u %= N;
            if (u < 0)
                u += N;
            return (long long)u;
        };
        auto power = [&](long long x, __int128 exponent) {
            if (exponent < 0) {
                x = inverse(x);
                exponent = -exponent;
            }
            long long r = 1;
            for (; exponent; exponent >>= 1, x = (__int128)x * x % N)
                if (exponent & 1)
                    r = (__int128)r * x % N;
            return r;
        };
        cout << (long long)((__int128)power(c1, a) * power(c2, b) % N) << '\n';
    }

    return 0;
}
```

### 实现提醒

负指数先求逆；所有余数规范化；不能用普通 long long 乘法直接取模。

## P5521 梅深不见冬

原题：[P5521](https://www.luogu.com.cn/problem/P5521)

### 思路

设 f[v] 为完成孩子 v 的最少花数，完成后只需保留 w[v]。按 f[v]−w[v] 从大到小处理孩子，维护已保留花数；最后还要同时放上当前点的 w[u]。

### 复杂度

时间 O(n log n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> g(n);
    for (int i = 1; i < n; i++) {
        int p;
        cin >> p;
        g[p - 1].push_back(i);
    }
    vector<long long> w(n), f(n);
    for (auto &x : w)
        cin >> x;
    for (int v = n - 1; v >= 0; v--) {
        sort(g[v].begin(), g[v].end(), [&](int a, int b) { return f[a] - w[a] > f[b] - w[b]; });
        long long saved = 0, best = 0;
        for (int u : g[v]) {
            best = max(best, saved + f[u]);
            saved += w[u];
        }
        f[v] = max(best, saved + w[v]);
    }
    for (int i = 0; i < n; i++)
        cout << f[i] << (i + 1 == n ? '\n' : ' ');

    return 0;
}
```

### 实现提醒

先完成孩子且保留其根；最终要同时拥有孩子与当前点的花；按 f−w 而非 f 排序。

## P5568 校门外的区间

原题：[P5568](https://www.luogu.com.cn/problem/P5568)

### 思路

整数点映射到偶数位置，两个整数间的开区间映射到奇数位置。五种集合运算变成区间置零、置一、翻转及清空区间外，最后合并连续被选位置。

### 复杂度

设坐标域 V=131071，时间 O(M log V+V)，空间 O(V)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const int V = 131071;
    vector<int> assign(4 * V, 0);
    vector<char> flip(4 * V);
    auto apply = [&](int v, int type) {
        if (type < 2) {
            assign[v] = type;
            flip[v] = 0;
        } else if (assign[v] >= 0)
            assign[v] ^= 1;
        else
            flip[v] ^= 1;
    };
    function<void(int)> push = [&](int v) {
        if (assign[v] >= 0) {
            apply(v * 2, assign[v]);
            apply(v * 2 + 1, assign[v]);
            assign[v] = -1;
        }
        if (flip[v]) {
            apply(v * 2, 2);
            apply(v * 2 + 1, 2);
            flip[v] = 0;
        }
    };
    function<void(int, int, int, int, int, int)> update = [&](int v, int l, int r, int L, int R,
                                                              int type) {
        if (L > R)
            return;
        if (L <= l && r <= R) {
            apply(v, type);
            return;
        }
        push(v);
        int mid = (l + r) / 2;
        if (L <= mid)
            update(v * 2, l, mid, L, R, type);
        if (R > mid)
            update(v * 2 + 1, mid + 1, r, L, R, type);
    };
    char op, left, right, comma;
    int a, b;
    while (cin >> op >> left >> a >> comma >> b >> right) {
        int L = 2 * a + (left == '('), R = 2 * b - (right == ')');
        if (L > R) {
            if (op == 'I' || op == 'C')
                apply(1, 0);
            continue;
        }
        if (op == 'I' || op == 'C') {
            update(1, 0, V - 1, 0, L - 1, 0);
            update(1, 0, V - 1, R + 1, V - 1, 0);
        }
        if (op == 'U')
            update(1, 0, V - 1, L, R, 1);
        if (op == 'D')
            update(1, 0, V - 1, L, R, 0);
        if (op == 'S' || op == 'C')
            update(1, 0, V - 1, L, R, 2);
    }
    vector<char> chosen(V);
    function<void(int, int, int)> collect = [&](int v, int l, int r) {
        if (assign[v] >= 0) {
            fill(chosen.begin() + l, chosen.begin() + r + 1, assign[v]);
            return;
        }
        push(v);
        int mid = (l + r) / 2;
        collect(v * 2, l, mid);
        collect(v * 2 + 1, mid + 1, r);
    };
    collect(1, 0, V - 1);
    bool any = false;
    for (int l = 0; l < V;) {
        if (!chosen[l]) {
            l++;
            continue;
        }
        int r = l;
        while (r + 1 < V && chosen[r + 1])
            r++;
        if (any)
            cout << ' ';
        any = true;
        cout << (l % 2 ? '(' : '[') << l / 2 << ',' << (r + 1) / 2 << (r % 2 ? ')' : ']');
        l = r + 1;
    }
    if (!any)
        cout << "empty set";
    cout << '\n';

    return 0;
}
```

### 实现提醒

C 是 T−S；开端点调整一格；空区间的 I/C 清空所有内容。

## P5686 和积和

原题：[P5686](https://www.luogu.com.cn/problem/P5686)

### 思路

设前缀和为 A、B。固定右端 r，所有左端贡献为 rArBr−ArΣBl−BrΣAl+ΣAlBl，其中 l 从零到 r−1。维护这三个前缀统计量即可线性求和。

### 复杂度

时间 O(n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;
long long power(long long a, long long b) {
    long long r = 1;
    for (; b; b >>= 1, a = a * a % MOD)
        if (b & 1)
            r = r * a % MOD;
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> A(n + 1);
    for (int i = 1; i <= n; i++) {
        long long x;
        cin >> x;
        A[i] = (A[i - 1] + x) % MOD;
    }
    long long B = 0, sumA = 0, sumB = 0, sumAB = 0, ans = 0;
    for (int r = 1; r <= n; r++) {
        long long x;
        cin >> x;
        B = (B + x) % MOD;
        long long term = (r * A[r] % MOD * B - A[r] * sumB % MOD - B * sumA % MOD + sumAB) % MOD;
        ans = (ans + term + 2 * MOD) % MOD;
        sumA = (sumA + A[r]) % MOD;
        sumB = (sumB + B) % MOD;
        sumAB = (sumAB + A[r] * B) % MOD;
    }
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

前缀零也在历史中；先计贡献再插入；乘积及时取模。

## P5694 陨石的秘密

原题：[P5694](https://www.luogu.com.cn/problem/P5694)

### 思路

先统计深度不超过 D 的串，再减去不超过 D−1 的串。一个非空表达式唯一拆为第一对完整外括号、其内部表达式、以及后续表达式，并按括号种类限制内部可用类型。

### 复杂度

时间 O(D·(L1+1)²(L2+1)²(L3+1)²)，空间 O(D·(L1+1)(L2+1)(L3+1))。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int A, B, C, D;
    cin >> A >> B >> C >> D;
    const int P = 11380;
    int S = (A + 1) * (B + 1) * (C + 1);
    vector<vector<int>> f(D + 1, vector<int>(S));
    auto id = [&](int a, int b, int c) { return (a * (B + 1) + b) * (C + 1) + c; };
    for (int d = 0; d <= D; d++)
        f[d][0] = 1;
    for (int d = 1; d <= D; d++)
        for (int a = 0; a <= A; a++)
            for (int b = 0; b <= B; b++)
                for (int c = 0; c <= C; c++) {
                    if (!a && !b && !c)
                        continue;
                    long long ans = 0;
                    if (a)
                        for (int x = 0; x < a; x++)
                            for (int y = 0; y <= b; y++)
                                for (int z = 0; z <= c; z++)
                                    ans = (ans + 1LL * f[d - 1][id(x, y, z)] *
                                                     f[d][id(a - 1 - x, b - y, c - z)]) %
                                          P;
                    if (b)
                        for (int y = 0; y < b; y++)
                            for (int z = 0; z <= c; z++)
                                ans = (ans + 1LL * f[d - 1][id(0, y, z)] *
                                                 f[d][id(a, b - 1 - y, c - z)]) %
                                      P;
                    if (c)
                        for (int z = 0; z < c; z++)
                            ans =
                                (ans + 1LL * f[d - 1][id(0, 0, z)] * f[d][id(a, b, c - 1 - z)]) % P;
                    f[d][id(a, b, c)] = ans;
                }
    int ans = f[D][id(A, B, C)];
    if (D)
        ans = (ans - f[D - 1][id(A, B, C)] + P) % P;
    cout << ans << '\n';

    return 0;
}
```

### 实现提醒

统计上界后作差；第一完整括号唯一拆分；中小括号对内部类型有限制。

## P5736 质数筛

原题：[P5736](https://www.luogu.com.cn/problem/P5736)

### 思路

小于二的数不是质数。对每个输入整数检查是否存在 2 到平方根之间的因子，没有就按原顺序输出。

### 复杂度

时间 O(n sqrt A)，空间 O(1)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    bool first = true;
    while (n--) {
        long long x;
        cin >> x;
        bool prime = x >= 2;
        for (long long d = 2; prime && d <= x / d; d++)
            if (x % d == 0)
                prime = false;
        if (prime) {
            if (!first)
                cout << ' ';
            first = false;
            cout << x;
        }
    }
    cout << '\n';

    return 0;
}
```

### 实现提醒

1 不是质数；保留顺序与重复；平方根条件避免乘法溢出。

