## UVA11426 拿行李（极限版） GCD - Extreme (II)

原题：[UVA11426](https://www.luogu.com.cn/problem/UVA11426)

### 思路

固定右端点 j，按 gcd(i,j)=d 分组，其和为 Σ(d|j,d<j)d·φ(j/d)。用倍数枚举一次加入所有 j，再前缀求和，回答多组 n。

### 复杂度

时间 O(A log A)，空间 O(A)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<int> queries;
    int n, maximum = 0;
    while (cin >> n && n) {
        queries.push_back(n);
        maximum = max(maximum, n);
    }
    vector<int> phi(maximum + 1);
    iota(phi.begin(), phi.end(), 0);
    for (int p = 2; p <= maximum; p++)
        if (phi[p] == p)
            for (int j = p; j <= maximum; j += p)
                phi[j] = phi[j] / p * (p - 1);
    vector<long long> sum(maximum + 1);
    for (int d = 1; d <= maximum / 2; d++)
        for (int j = d + d; j <= maximum; j += d)
            sum[j] += 1LL * d * phi[j / d];
    for (int i = 1; i <= maximum; i++)
        sum[i] += sum[i - 1];
    for (int x : queries)
        cout << sum[x] << '\n';

    return 0;
}
```

### 实现提醒

只统计 i<j，倍数系数从 2 起；先求单个右端贡献，再做前缀和。

## UVA11475 Extend to Palindrome

原题：[UVA11475](https://www.luogu.com.cn/problem/UVA11475)

### 思路

只允许向末尾添加字符，故保留原串最长的回文后缀，把前面剩余部分反转后追加。用反串与原串构造 KMP 前缀函数求该后缀长度。

### 复杂度

每串时间 O(n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> prefix(const string &s) {
    vector<int> p(s.size());
    for (int i = 1; i < (int)s.size(); i++) {
        int j = p[i - 1];
        while (j && s[i] != s[j])
            j = p[j - 1];
        if (s[i] == s[j])
            j++;
        p[i] = j;
    }
    return p;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    while (cin >> s) {
        string rev = s;
        reverse(rev.begin(), rev.end());
        int len = prefix(rev + '#' + s).back();
        cout << s << rev.substr(len) << '\n';
    }

    return 0;
}
```

### 实现提醒

求最长回文后缀而非前缀；输入到 EOF；保留原串。

## UVA1151 买还是建 Buy or Build

原题：[UVA1151](https://www.luogu.com.cn/problem/UVA1151)

### 思路

套餐至多八个，枚举购买子集，把每个套餐城市先合并，再用最小生成树边补齐网络。基础道路的 MST 可先用 Prim 求出；加入零费用套餐边后，只在这棵 MST 上继续 Kruskal 就足够。

### 复杂度

时间 O(n²+2^q·(n+套餐总人数))，空间 O(n+套餐总人数)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, size;
    explicit DSU(int n) : p(n), size(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    bool join(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        p[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tests;
    cin >> tests;
    for (int test = 0; test < tests; test++) {
        int n, q;
        cin >> n >> q;
        vector<vector<int>> packages(q);
        vector<long long> price(q);
        for (int i = 0; i < q; i++) {
            int size;
            cin >> size >> price[i];
            packages[i].resize(size);
            for (int &v : packages[i]) {
                cin >> v;
                v--;
            }
        }
        vector<long long> x(n), y(n);
        for (int i = 0; i < n; i++)
            cin >> x[i] >> y[i];
        vector<long long> distance(n, LLONG_MAX);
        vector<int> from(n, -1);
        vector<char> used(n);
        vector<tuple<long long, int, int>> edges;
        distance[0] = 0;
        for (int step = 0; step < n; step++) {
            int v = -1;
            for (int i = 0; i < n; i++)
                if (!used[i] && (v < 0 || distance[i] < distance[v]))
                    v = i;
            used[v] = 1;
            if (from[v] >= 0)
                edges.push_back({distance[v], from[v], v});
            for (int u = 0; u < n; u++)
                if (!used[u]) {
                    long long dx = x[u] - x[v], dy = y[u] - y[v], cost = dx * dx + dy * dy;
                    if (cost < distance[u]) {
                        distance[u] = cost;
                        from[u] = v;
                    }
                }
        }
        sort(edges.begin(), edges.end());
        long long answer = LLONG_MAX;
        for (int mask = 0; mask < (1 << q); mask++) {
            DSU d(n);
            long long cost = 0;
            for (int i = 0; i < q; i++)
                if ((mask >> i) & 1) {
                    cost += price[i];
                    for (int v : packages[i])
                        d.join(packages[i][0], v);
                }
            for (auto [w, a, b] : edges)
                if (d.join(a, b))
                    cost += w;
            answer = min(answer, cost);
        }
        if (test)
            cout << '\n';
        cout << answer << '\n';
    }

    return 0;
}
```

### 实现提醒

套餐费一次支付；普通路费为平方距离；每个子集重建并查集。

## UVA116 单向TSP Unidirectional TSP

原题：[UVA116](https://www.luogu.com.cn/problem/UVA116)

### 思路

dp[r][c] 表示从该格走到最后一列的最小代价。把下一列的三个可选行排序，费用相同时选编号最小者，记录路径；最后选择最小费用且起始行最小的起点。

### 复杂度

每组时间 O(mn)，空间 O(mn)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m, n;
    while (cin >> m >> n) {
        vector<vector<long long>> a(m, vector<long long>(n)), dp = a;
        vector<vector<int>> next(m, vector<int>(n));
        for (auto &r : a)
            for (auto &x : r)
                cin >> x;
        for (int r = 0; r < m; r++)
            dp[r][n - 1] = a[r][n - 1];
        for (int c = n - 2; c >= 0; c--)
            for (int r = 0; r < m; r++) {
                array<int, 3> rows = {(r + m - 1) % m, r, (r + 1) % m};
                sort(rows.begin(), rows.end());
                int best = rows[0];
                for (int u : rows)
                    if (dp[u][c + 1] < dp[best][c + 1])
                        best = u;
                dp[r][c] = a[r][c] + dp[best][c + 1];
                next[r][c] = best;
            }
        int root = 0;
        for (int r = 1; r < m; r++)
            if (dp[r][0] < dp[root][0])
                root = r;
        int r = root;
        for (int c = 0; c < n; c++) {
            cout << r + 1 << (c + 1 == n ? '\n' : ' ');
            if (c + 1 < n)
                r = next[r][c];
        }
        cout << dp[root][0] << '\n';
    }

    return 0;
}
```

### 实现提醒

行循环取模；负权也能 DP；费用相等按行号而非几何方向选择。

## UVA11626 Convex Hull

原题：[UVA11626](https://www.luogu.com.cn/problem/UVA11626)

### 思路

筛出标记 Y 的点，构造保留共线边界点的凸包。叉积为负才弹出，等于零时保留，按最左且最低点开始逆时针输出。

### 复杂度

时间 O(n log n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Point {
    long long x, y;
    bool operator==(const Point &o) const { return x == o.x && y == o.y; }
};
__int128 cross(Point a, Point b, Point c) {
    return (__int128)(b.x - a.x) * (c.y - a.y) - (__int128)(b.y - a.y) * (c.x - a.x);
}
vector<Point> hull(vector<Point> a, bool keep = false) {
    sort(a.begin(), a.end(), [](Point a, Point b) { return tie(a.x, a.y) < tie(b.x, b.y); });
    a.erase(unique(a.begin(), a.end()), a.end());
    if (a.size() < 3)
        return a;
    if (keep) {
        bool line = true;
        for (auto p : a)
            if (cross(a[0], a[1], p) != 0)
                line = false;
        if (line)
            return a;
    }
    vector<Point> h;
    for (auto p : a) {
        while (h.size() >= 2 && (keep ? cross(h[h.size() - 2], h.back(), p) < 0
                                      : cross(h[h.size() - 2], h.back(), p) <= 0))
            h.pop_back();
        h.push_back(p);
    }
    int lower = h.size();
    for (int i = (int)a.size() - 2; i >= 0; i--) {
        auto p = a[i];
        while ((int)h.size() > lower && (keep ? cross(h[h.size() - 2], h.back(), p) < 0
                                              : cross(h[h.size() - 2], h.back(), p) <= 0))
            h.pop_back();
        h.push_back(p);
    }
    h.pop_back();
    return h;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        cin >> n;
        vector<Point> a;
        for (int i = 0; i < n; i++) {
            Point p;
            char c;
            cin >> p.x >> p.y >> c;
            if (c == 'Y')
                a.push_back(p);
        }
        auto h = hull(a, true);
        cout << h.size() << '\n';
        for (auto p : h)
            cout << p.x << ' ' << p.y << '\n';
    }

    return 0;
}
```

### 实现提醒

保留共线边界点；先过滤 N；全共线时只输出一次。

## UVA11732 "strcmp()" Anyone?

原题：[UVA11732](https://www.luogu.com.cn/problem/UVA11732)

### 思路

两串比较次数为 2·LCP+1，相同字符串再多一次结束判断。排序后任意两串 LCP 等于其间相邻 LCP 的最小值，用单调栈求所有区间最小值之和。

### 复杂度

设输入总长度为 S，时间 O(S log n+n)，空间 O(S+n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, caseNo = 0;
    while (cin >> n && n) {
        vector<string> a(n);
        for (auto &s : a)
            cin >> s;
        sort(a.begin(), a.end());
        long long same = 0;
        for (int l = 0; l < n;) {
            int r = l + 1;
            while (r < n && a[r] == a[l])
                r++;
            same += 1LL * (r - l) * (r - l - 1) / 2;
            l = r;
        }
        vector<pair<int, int>> st;
        long long ending = 0, totalLcp = 0;
        for (int i = 1; i < n; i++) {
            int h = 0;
            while (h < (int)min(a[i].size(), a[i - 1].size()) && a[i][h] == a[i - 1][h])
                h++;
            int count = 1;
            while (!st.empty() && st.back().first >= h) {
                ending -= 1LL * st.back().first * st.back().second;
                count += st.back().second;
                st.pop_back();
            }
            st.push_back({h, count});
            ending += 1LL * h * count;
            totalLcp += ending;
        }
        cout << "Case " << ++caseNo << ": " << 1LL * n * (n - 1) / 2 + 2 * totalLcp + same << '\n';
    }

    return 0;
}
```

### 实现提醒

相同串额外补一次；输入含大小写字母和数字；答案六十四位。

## UVA11895 抽奖 Honorary Tickets

原题：[UVA11895](https://www.luogu.com.cn/problem/UVA11895)

### 思路

之前结果不公开，一个袋子被选 r 次后，下次中奖概率为 (l/t)((t−1)/t)^r。每个人都会选择当前概率最大的袋子，用堆取最大并更新，取第 K 次的概率。

### 复杂度

时间 O((N+K) log N)，空间 O(N)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Bag {
    long long numerator, denominator, total;
};
struct Compare {
    bool operator()(const Bag &a, const Bag &b) const {
        return (__int128)a.numerator * b.denominator < (__int128)b.numerator * a.denominator;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tests;
    cin >> tests;
    while (tests--) {
        int n, k;
        cin >> n >> k;
        priority_queue<Bag, vector<Bag>, Compare> q;
        for (int i = 0; i < n; i++) {
            long long t, l;
            cin >> t >> l;
            long long g = gcd(t, l);
            q.push({l / g, t / g, t});
        }
        for (int step = 1; step < k; step++) {
            Bag b = q.top();
            q.pop();
            long long a = b.total - 1, d = b.total, g = gcd(a, b.denominator);
            a /= g;
            b.denominator /= g;
            g = gcd(d, b.numerator);
            d /= g;
            b.numerator /= g;
            b.numerator *= a;
            b.denominator *= d;
            if (!b.numerator)
                b.denominator = 1;
            q.push(b);
        }
        auto b = q.top();
        long long g = gcd(b.numerator, b.denominator);
        cout << b.numerator / g << '/' << b.denominator / g << '\n';
    }

    return 0;
}
```

### 实现提醒

信封放回但奖票不放回；前面结果不可见；比较分数用宽整数；最后约分输出。

## UVA1222 Bribing FIPA

原题：[UVA1222](https://www.luogu.com.cn/problem/UVA1222)

### 思路

贿赂一个国家会获得其全部后代的票。树上 DP 维护各票数的最低费用：不贿赂当前国就合并孩子，贿赂则直接用当前价格覆盖整棵子树。加虚拟根合并森林。

### 复杂度

时间 O(n²)，空间 O(n²)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string line;
    while (getline(cin, line)) {
        if (line == "#")
            break;
        if (line.empty())
            continue;
        istringstream header(line);
        int n, m;
        header >> n >> m;
        map<string, int> ids;
        int used = 0;
        auto get = [&](const string &s) {
            auto it = ids.find(s);
            if (it != ids.end())
                return it->second;
            return ids[s] = ++used;
        };
        vector<vector<int>> g(n + 1);
        vector<int> parent(n + 1), size(n + 1);
        vector<long long> cost(n + 1);
        for (int i = 0; i < n; i++) {
            getline(cin, line);
            istringstream in(line);
            string name;
            long long value;
            in >> name >> value;
            int u = get(name);
            cost[u] = value;
            while (in >> name) {
                int v = get(name);
                g[u].push_back(v);
                parent[v] = u;
            }
        }
        for (int i = 1; i <= n; i++)
            if (!parent[i])
                g[0].push_back(i);
        vector<int> order = {0};
        for (int i = 0; i < (int)order.size(); i++)
            for (int u : g[order[i]])
                order.push_back(u);
        const long long INF = 1LL << 60;
        vector<vector<long long>> dp(n + 1);
        for (int i = n; i >= 0; i--) {
            int v = order[i];
            dp[v] = {0};
            for (int u : g[v]) {
                vector<long long> next(size[v] + size[u] + 1, INF);
                for (int a = 0; a <= size[v]; a++)
                    for (int b = 0; b <= size[u]; b++)
                        next[a + b] = min(next[a + b], dp[v][a] + dp[u][b]);
                size[v] += size[u];
                dp[v].swap(next);
            }
            if (v) {
                size[v]++;
                dp[v].resize(size[v] + 1, INF);
                dp[v][size[v]] = min(dp[v][size[v]], cost[v]);
            }
        }
        cout << *min_element(dp[0].begin() + m, dp[0].end()) << '\n';
    }

    return 0;
}
```

### 实现提醒

要求至少 m 票；虚拟根不计票且不能购买；国家名称按整行解析。

## UVA12345 Dynamic len(set(a[L:R]))

原题：[UVA12345](https://www.luogu.com.cn/problem/UVA12345)

### 思路

把每次查询记录为左端、右端和此前修改次数。离线排序后，移动两个区间端点以及时间指针，维护当前各值频数，统计频数大于 0 的值数。查询使用从 0 开始的左闭右开区间。

### 复杂度

时间 O((n+q)·n^(2/3))，空间 O(n+q+A)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Change {
    int position, before, after;
};
struct Query {
    int l, r, time, id;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    vector<int> a(n), working;
    for (int &x : a)
        cin >> x;
    working = a;
    vector<Change> changes;
    vector<Query> queries;
    for (int i = 0; i < q; i++) {
        char op;
        int l, r;
        cin >> op >> l >> r;
        if (op == 'M') {
            changes.push_back({l, working[l], r});
            working[l] = r;
        } else
            queries.push_back({l, r - 1, (int)changes.size(), (int)queries.size()});
    }
    int limit = 0;
    for (int x : a)
        limit = max(limit, x);
    for (auto c : changes)
        limit = max(limit, c.after);
    int block = max(1, (int)pow(n, 2.0 / 3));
    sort(queries.begin(), queries.end(), [&](Query a, Query b) {
        if (a.l / block != b.l / block)
            return a.l < b.l;
        if (a.r / block != b.r / block)
            return a.r < b.r;
        return a.time < b.time;
    });
    vector<int> freq(limit + 1), answer(queries.size());
    int current = 0, l = 0, r = -1, time = 0;
    auto adjust = [&](int x, int delta) {
        current -= freq[x] > 0;
        freq[x] += delta;
        current += freq[x] > 0;
    };
    auto apply = [&](Change c, bool forward) {
        if (l <= c.position && c.position <= r)
            adjust(a[c.position], -1);
        a[c.position] = forward ? c.after : c.before;
        if (l <= c.position && c.position <= r)
            adjust(a[c.position], 1);
    };
    for (auto query : queries) {
        while (time < query.time) {
            apply(changes[time], true);
            time++;
        }
        while (time > query.time) {
            time--;
            apply(changes[time], false);
        }
        while (l > query.l)
            adjust(a[--l], 1);
        while (r < query.r)
            adjust(a[++r], 1);
        while (l < query.l)
            adjust(a[l++], -1);
        while (r > query.r)
            adjust(a[r--], -1);
        answer[query.id] = current;
    }
    for (int x : answer)
        cout << x << '\n';

    return 0;
}
```

### 实现提醒

修改须保存旧值；时间撤销要对称；下标从 0 开始。

## UVA1303 Wall

原题：[UVA1303](https://www.luogu.com.cn/problem/UVA1303)

### 思路

先求城堡顶点凸包的周长，再加上安全距离 L 的一整圈圆周长 2πL。凸包每条边平移不改变长度，各拐角圆弧的转角之和为 2π。

### 复杂度

时间 O(n log n)，空间 O(n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Point {
    long long x, y;
    bool operator==(const Point &o) const { return x == o.x && y == o.y; }
};
__int128 cross(Point a, Point b, Point c) {
    return (__int128)(b.x - a.x) * (c.y - a.y) - (__int128)(b.y - a.y) * (c.x - a.x);
}
vector<Point> hull(vector<Point> a, bool keep = false) {
    sort(a.begin(), a.end(), [](Point a, Point b) { return tie(a.x, a.y) < tie(b.x, b.y); });
    a.erase(unique(a.begin(), a.end()), a.end());
    if (a.size() < 3)
        return a;
    if (keep) {
        bool line = true;
        for (auto p : a)
            if (cross(a[0], a[1], p) != 0)
                line = false;
        if (line)
            return a;
    }
    vector<Point> h;
    for (auto p : a) {
        while (h.size() >= 2 && (keep ? cross(h[h.size() - 2], h.back(), p) < 0
                                      : cross(h[h.size() - 2], h.back(), p) <= 0))
            h.pop_back();
        h.push_back(p);
    }
    int lower = h.size();
    for (int i = (int)a.size() - 2; i >= 0; i--) {
        auto p = a[i];
        while ((int)h.size() > lower && (keep ? cross(h[h.size() - 2], h.back(), p) < 0
                                              : cross(h[h.size() - 2], h.back(), p) <= 0))
            h.pop_back();
        h.push_back(p);
    }
    h.pop_back();
    return h;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tests;
    cin >> tests;
    for (int test = 0; test < tests; test++) {
        int n;
        long long radius;
        cin >> n >> radius;
        vector<Point> a(n);
        for (auto &p : a)
            cin >> p.x >> p.y;
        auto h = hull(a);
        long double perimeter = 2 * acosl(-1.0L) * radius;
        for (int i = 0; i < (int)h.size(); i++) {
            auto a = h[i], b = h[(i + 1) % h.size()];
            perimeter += hypotl(a.x - b.x, a.y - b.y);
        }
        if (test)
            cout << '\n';
        cout << llround(perimeter) << '\n';
    }

    return 0;
}
```

### 实现提醒

不能直接使用凹多边形原周长；圆弧加一整圈；输出整数并保留组间空行。

## UVA1390 互联 Interconnect

原题：[UVA1390](https://www.luogu.com.cn/problem/UVA1390)

### 思路

道路的具体形状只影响当前连通块。把状态压成排序后的各块大小，随机选中不同块的概率为 size[i]·size[j]/C(n,2)，合并这两块；选中同一块的原地项移到等式左边。

### 复杂度

状态数至多整数分拆 p(n)，每状态 O(n³) 内处理合并与排序，空间 O(n·p(n))。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, size;
    explicit DSU(int n) : p(n), size(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    bool join(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        p[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    while (cin >> n >> m) {
        DSU d(n);
        while (m--) {
            int a, b;
            cin >> a >> b;
            d.join(a - 1, b - 1);
        }
        vector<int> state;
        for (int i = 0; i < n; i++)
            if (d.find(i) == i)
                state.push_back(d.size[i]);
        sort(state.begin(), state.end());
        map<vector<int>, double> memo;
        function<double(vector<int>)> solve = [&](vector<int> s) -> double {
            if (s.size() == 1)
                return 0;
            auto found = memo.find(s);
            if (found != memo.end())
                return found->second;
            double cross = 0, numerator = 1.0 * n * (n - 1) / 2;
            for (int i = 0; i < (int)s.size(); i++)
                for (int j = i + 1; j < (int)s.size(); j++) {
                    double weight = s[i] * s[j];
                    cross += weight;
                    vector<int> next;
                    for (int k = 0; k < (int)s.size(); k++)
                        if (k != i && k != j)
                            next.push_back(s[k]);
                    next.push_back(s[i] + s[j]);
                    sort(next.begin(), next.end());
                    numerator += weight * solve(next);
                }
            return memo[s] = numerator / cross;
        };
        cout << fixed << setprecision(9) << solve(state) << '\n';
    }

    return 0;
}
```

### 实现提醒

随机选的是不同城市，不是不同连通块；同块新路仍耗一年；输入到 EOF。

## UVA1401 Remember the Word

原题：[UVA1401](https://www.luogu.com.cn/problem/UVA1401)

### 思路

dp[i] 表示后缀 i..末尾的分词数。从每个 i 沿字典 Trie 向右匹配，遇到一个完整单词就把后面的 dp 加进来，模 20071027。

### 复杂度

设最长词长 L、字典总长 S，时间 O(S+nL)，空间 O(S+n)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    int caseNo = 0;
    while (cin >> s) {
        int count;
        cin >> count;
        struct Node {
            array<int, 26> next{};
            bool terminal = false;
        };
        vector<Node> trie(1);
        int maxLength = 0;
        while (count--) {
            string word;
            cin >> word;
            maxLength = max(maxLength, (int)word.size());
            int v = 0;
            for (char c : word) {
                int x = c - 'a';
                if (!trie[v].next[x]) {
                    trie[v].next[x] = trie.size();
                    trie.emplace_back();
                }
                v = trie[v].next[x];
            }
            trie[v].terminal = true;
        }
        const int P = 20071027;
        int n = s.size();
        vector<int> dp(n + 1);
        dp[n] = 1;
        for (int i = n - 1; i >= 0; i--) {
            int v = 0;
            for (int j = i; j < n && j < i + maxLength; j++) {
                v = trie[v].next[s[j] - 'a'];
                if (!v)
                    break;
                if (trie[v].terminal) {
                    dp[i] += dp[j + 1];
                    if (dp[i] >= P)
                        dp[i] -= P;
                }
            }
        }
        cout << "Case " << ++caseNo << ": " << dp[0] << '\n';
    }

    return 0;
}
```

### 实现提醒

空后缀为一；词与词可以相接；每次累加取模。

## UVA1665 岛屿 Islands

原题：[UVA1665](https://www.luogu.com.cn/problem/UVA1665)

### 思路

把格子按高度降序、询问按海平面降序处理。高于当前海平面的格子才是陆地，逐个激活并与四邻陆地合并，维护连通块数。

### 复杂度

时间 O(nm log(nm)+T log T)，空间 O(nm+T)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, size;
    explicit DSU(int n) : p(n), size(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    bool join(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        p[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tests;
    cin >> tests;
    while (tests--) {
        int n, m;
        cin >> n >> m;
        int count = n * m;
        vector<int> height(count), order(count);
        for (int &x : height)
            cin >> x;
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) { return height[a] > height[b]; });
        int q;
        cin >> q;
        vector<pair<int, int>> queries(q);
        for (int i = 0; i < q; i++) {
            cin >> queries[i].first;
            queries[i].second = i;
        }
        sort(queries.rbegin(), queries.rend());
        DSU d(count);
        vector<char> active(count);
        vector<int> answer(q);
        int position = 0, islands = 0;
        for (auto [water, id] : queries) {
            while (position < count && height[order[position]] > water) {
                int v = order[position++], x = v / m, y = v % m;
                active[v] = 1;
                islands++;
                for (auto [dx, dy] : vector<pair<int, int>>{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
                    int a = x + dx, b = y + dy;
                    if (a >= 0 && a < n && b >= 0 && b < m && active[a * m + b] &&
                        d.join(v, a * m + b))
                        islands--;
                }
            }
            answer[id] = islands;
        }
        for (int i = 0; i < q; i++)
            cout << answer[i] << (i + 1 == q ? '\n' : ' ');
    }

    return 0;
}
```

### 实现提醒

海水能进入所有低格，无需从边界灌水；严格高于水位才激活；使用四邻域。

## UVA439 骑士的移动 Knight Moves

原题：[UVA439](https://www.luogu.com.cn/problem/UVA439)

### 思路

将 a1 到 h8 映射到 8×8 数组，按八种马步 BFS，输出终点第一次被访问时的距离。

### 复杂度

每组时间 O(64)，空间 O(64)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string a, b;
    while (cin >> a >> b) {
        int d[8][8];
        memset(d, -1, sizeof d);
        queue<pair<int, int>> q;
        int sx = a[0] - 'a', sy = a[1] - '1';
        d[sx][sy] = 0;
        q.push({sx, sy});
        int dx[] = {1, 1, -1, -1, 2, 2, -2, -2}, dy[] = {2, -2, 2, -2, 1, -1, 1, -1};
        while (!q.empty()) {
            auto [x, y] = q.front();
            q.pop();
            for (int k = 0; k < 8; k++) {
                int u = x + dx[k], v = y + dy[k];
                if (u >= 0 && u < 8 && v >= 0 && v < 8 && d[u][v] < 0) {
                    d[u][v] = d[x][y] + 1;
                    q.push({u, v});
                }
            }
        }
        cout << "To get from " << a << " to " << b << " takes " << d[b[0] - 'a'][b[1] - '1']
             << " knight moves.\n";
    }

    return 0;
}
```

### 实现提醒

读到 EOF；保留原坐标字符串用于输出；每组清空距离。

## UVA675 Convex Hull of the Polygon

原题：[UVA675](https://www.luogu.com.cn/problem/UVA675)

### 思路

按坐标排序求严格凸包，再在原输入顺序中寻找第一个凸包顶点，把凸包旋转到这里开始，逆时针输出并重复起点闭合。

### 复杂度

时间 O(n log n+n·h)，空间 O(n)，h 为凸包点数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Point {
    long long x, y;
    bool operator==(const Point &o) const { return x == o.x && y == o.y; }
};
__int128 cross(Point a, Point b, Point c) {
    return (__int128)(b.x - a.x) * (c.y - a.y) - (__int128)(b.y - a.y) * (c.x - a.x);
}
vector<Point> hull(vector<Point> a, bool keep = false) {
    sort(a.begin(), a.end(), [](Point a, Point b) { return tie(a.x, a.y) < tie(b.x, b.y); });
    a.erase(unique(a.begin(), a.end()), a.end());
    if (a.size() < 3)
        return a;
    if (keep) {
        bool line = true;
        for (auto p : a)
            if (cross(a[0], a[1], p) != 0)
                line = false;
        if (line)
            return a;
    }
    vector<Point> h;
    for (auto p : a) {
        while (h.size() >= 2 && (keep ? cross(h[h.size() - 2], h.back(), p) < 0
                                      : cross(h[h.size() - 2], h.back(), p) <= 0))
            h.pop_back();
        h.push_back(p);
    }
    int lower = h.size();
    for (int i = (int)a.size() - 2; i >= 0; i--) {
        auto p = a[i];
        while ((int)h.size() > lower && (keep ? cross(h[h.size() - 2], h.back(), p) < 0
                                              : cross(h[h.size() - 2], h.back(), p) <= 0))
            h.pop_back();
        h.push_back(p);
    }
    h.pop_back();
    return h;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<Point> points;
    bool first = true;
    auto output = [&]() {
        if (points.empty())
            return;
        auto h = hull(points);
        int start = 0;
        for (auto p : points) {
            auto it = find(h.begin(), h.end(), p);
            if (it != h.end()) {
                start = it - h.begin();
                break;
            }
        }
        rotate(h.begin(), h.begin() + start, h.end());
        if (!first)
            cout << '\n';
        first = false;
        for (int i = 0; i <= (int)h.size(); i++) {
            auto p = h[i % h.size()];
            cout << p.x << ", " << p.y << '\n';
        }
        points.clear();
    };
    string line;
    while (getline(cin, line)) {
        if (line.find_first_not_of(" \t\r") == string::npos) {
            output();
            continue;
        }
        for (char &c : line)
            if (c == ',')
                c = ' ';
        stringstream input(line);
        Point p;
        if (input >> p.x >> p.y)
            points.push_back(p);
    }
    output();

    return 0;
}
```

### 实现提醒

按原输入挑起点；逆时针；重复首点闭合；组间空行。

