#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n, q;
        cin >> n >> q;
        vector<int> rt(n), ct(n), rv(n), cv(n);
        for (int time = 1; time <= q; time++) {
            int op, k, v;
