using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n;
    cin >> n;
    string ans;
    while (n > 0) {
        if (n % 2) {
            ans += 'N';
            n = (n - 1) / 2;
        } else {
            ans += 'G';
            n = (n - 2) / 2;
        }
