    reverse(ans.begin(), ans.end());
    cout << ans;
    return 0;
}
```

### 复杂度

时间与输出字符串空间均为 $O(\log(n+1))$。

### 易错点

偶数逆推不是直接除二，还需先减二；不反转字符串会把按键顺序颠倒。

## 装进肚子

### 题意

恰好 K 个巧克力早上吃，其余晚上吃，最大化总甜蜜值。

### 思路

先假设全部晚上吃，得到基准 sum(B)。把第 i 个改到早上，收益只改变 A[i]-B[i]。因此选差值最大的 K 个，累加这些增量即可。即使增量为负，恰好 K 个的要求也仍需选择。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<long long> a(n), delta(n);
    for (auto &x : a)
        cin >> x;
    long long answer = 0;
    for (int i = 0; i < n; i++) {
        long long b;
        cin >> b;
        answer += b;
        delta[i] = a[i] - b;
    }
    sort(delta.rbegin(), delta.rend());
    for (int i = 0; i < k; i++)
        answer += delta[i];
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，数组空间 $O(n)$。

### 易错点

不能只按早上甜蜜值排序，选到早上意味着同时失去晚上甜蜜值。总和可达百亿，要用 long long。

## 逆序对

### 题意

累计全部长度 n 的零一串中，前一后一零的下标对总数。

### 思路

先固定一对位置 i<j，它们必须分别是一、零，其余 n-2 位任意，所以每对贡献 2^(n-2) 个串。位置对有 n(n-1)/2 个，答案为该组合数乘 2^(n-2)，模 10^9+7。n<2 时没有位置对，单独输出零。组合数中的除二用模逆元 500000004。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long mod = 1000000007;
    long long n;
    cin >> n;
    if (n < 2) {
        cout << 0;
        return 0;
    }
    long long power = 1, base = 2, exponent = n - 2;
    while (exponent) {
        if (exponent & 1)
            power = power * base % mod;
        base = base * base % mod;
        exponent >>= 1;
    }
    cout << (n % mod) * ((n - 1) % mod) % mod * 500000004 % mod * power % mod;
    return 0;
}
```

### 复杂度

时间 $O(\log n)$，额外空间 $O(1)$。

### 易错点

n 可达 10^18，不能直接先算 n(n-1)。指数保存原始值，不能无条件先对模数取余。

## 锁

### 题意

居民权值和至少m才可打开全部锁，求最少锁数。

### 思路

没有达到阈值的集合称失败集合。考虑其中“再加任何一个外部居民就成功”的极大失败集合S：它必须至少缺一把钥匙，而所有不在S中的居民都必须持有这把钥匙，否则S再加那个人仍打不开。故这把锁的无钥匙者集合恰好是S。两个不同极大失败集合不能共用此锁，所以至少需要极大失败集合个数把锁。

反过来，为每个极大失败集合各建一锁，只给其外部居民钥匙。所有失败集合都包含于某个极大失败集合而缺该钥匙；任意成功集合不包含于失败集合，故每锁都至少有一名持钥匙者，构造成立。

枚举全部掩码，求权值和；未达m且加上补集中最小权值后达到m，就恰为极大失败集合。补集为空时也算极大失败。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long threshold;
    cin >> n >> threshold;
    vector<long long> weight(n);
    for (auto &x : weight)
        cin >> x;
    int size = 1 << n;
    vector<long long> sum(size), minimum(size, LLONG_MAX / 4);
    for (int mask = 1; mask < size; mask++) {
        int bit = __builtin_ctz((unsigned)mask), rest = mask & (mask - 1);
        sum[mask] = sum[rest] + weight[bit];
        minimum[mask] = min(minimum[rest], weight[bit]);
    }
    int answer = 0;
    for (int mask = 0; mask < size; mask++)
        if (sum[mask] < threshold &&
            (mask == size - 1 || sum[mask] + minimum[(size - 1) ^ mask] >= threshold))
            answer++;
    cout << answer;
    return 0;
}
```

### 复杂度

时间、空间均 $O(2^n)$。

### 易错点

权值均正，所以只需检查最小外部权值。所有人总权仍不足m时，完整集合是唯一极大失败集合，一把无人有钥匙的锁即可。

## 完全平方数

### 题意

多次统计闭非负整数区间中的完全平方数，零也算平方。

### 思路

定义 count(x) 为零到 x 中的平方数个数。x<0 时为零，否则平方根的整数取值为零到 floor(sqrt(x))，所以 count(x)=floor(sqrt(x))+1。查询答案为 count(r)-count(l-1)。用整数二分找最大的根，平方在 long long 中计算，避免浮点临界误差。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    auto count = [](long long x) {
        if (x < 0)
            return 0LL;
        long long low = 0, high = 100000;
        while (low < high) {
            long long mid = (low + high + 1) / 2;
            if (mid * mid <= x)
                low = mid;
            else
                high = mid - 1;
        }
        return low + 1;
    };
    int q;
    cin >> q;
    while (q--) {
        long long l, r;
        cin >> l >> r;
        cout << count(r) - count(l - 1) << '\n';
    }
    return 0;
}
```

### 复杂度

每次查询时间 $O(\log r)$，额外空间 $O(1)$。

### 易错点

零的平方根为零，[0,0] 应得到一。l=0 时，辅助函数应支持 -1。

