    cin.tie(nullptr);
    int l, r;
    cin >> l >> r;
    int ans = 0;
    for (int x = l; x <= r; x++)
        for (int n = x; n > 0; n /= 10)
            if (n % 10 == 2)
                ans++;
    cout << ans;
    return 0;
