时间 $O(n)$，额外空间 $O(1)$。

### 易错点

不同课程的学分不同，不能直接对绩点做普通平均。

## 排列式

### 题意

找出乘数、乘积合起来恰好使用一次数字一到九的所有乘法式，交换乘数只算一次。

### 思路

乘积一定是四位数：若乘数总位数至多四，乘积至多四位，总位数不足九；若总位数至少六，乘积至少五位，总位数超过九。因此只枚举一位乘四位、两位乘三位。拼接两个乘数和乘积，检查长度为九、没有零且每个数位只出现一次。最后按乘积、较小乘数排序。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<tuple<int, int, int>> ans;
    auto check = [&](int a, int b) {
        int c = a * b;
        string s = to_string(a) + to_string(b) + to_string(c);
        if (s.size() != 9)
            return;
        int mask = 0;
        for (char ch : s) {
            int d = ch - '0';
            if (d == 0 || (mask & (1 << d)))
                return;
            mask |= 1 << d;
        }
        if (mask == 1022)
            ans.emplace_back(c, a, b);
    };
    for (int a = 1; a <= 9; a++)
        for (int b = 1234; b <= 9876 && a * b <= 9876; b++)
            check(a, b);
    for (int a = 12; a <= 98; a++)
        for (int b = 123; b <= 987 && a * b <= 9876; b++)
            check(a, b);
    sort(ans.begin(), ans.end());
    for (auto [c, a, b] : ans)
        cout << c << " = " << a << " x " << b << '\n';
    return 0;
}
```

### 复杂度

数位上限固定，枚举与排序的总开销为常数；保存九条结果。

### 易错点

同一个乘积可以对应不同乘数，不能只对乘积去重。两种枚举都令较小乘数在前。

## 树上路径

### 题意

子树加、路径加，查询路径所有不同节点对的权值乘积和。

### 思路

重链剖分使每条重链在DFS序连续，整棵子树也连续。路径被拆成O(log n)个重链区间，子树是一个区间，因此两种加法都交给区间加线段树。

节点维护S=Σa、Q=Σa²；长len区间加v时Q+=2vS+len*v²，随后S+=len*v。路径查询分别累加各段S、Q，所求无序不同节点对乘积和=(S²−Q)/2，模P下乘500000004。若把查询拆段，必须先合并全部S再平方，这样才包含跨段节点对。

父子关系、重儿子、重链编号均由显式栈和逆序计算，避免十万长链递归遍历。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct EulerTree {
    int n;
    vector<vector<int>> edge;
    vector<int> parent, depth, in, out, order;
    EulerTree(int n) : n(n), edge(n + 1), parent(n + 1), depth(n + 1), in(n + 1), out(n + 1) {}
    void add(int u, int v) {
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    void root(int start) {
        vector<int> stack = {start};
        parent[start] = 0;
        order.clear();
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            in[u] = order.size() + 1;
            order.push_back(u);
            for (int v : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack.push_back(v);
                }
        }
        vector<int> size(n + 1, 1);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            out[u] = in[u] + size[u] - 1;
            if (parent[u])
                size[parent[u]] += size[u];
        }
    }
};

struct SquareTree {
    static constexpr long long mod = 1000000007;
    int n;
    vector<long long> sum, square, tag;
    SquareTree(const vector<long long> &a)
        : n((int)a.size() - 1), sum(4 * n + 4), square(4 * n + 4), tag(4 * n + 4) {
        build(1, 1, n, a);
    }
    void pull(int u) {
        sum[u] = (sum[u * 2] + sum[u * 2 + 1]) % mod;
        square[u] = (square[u * 2] + square[u * 2 + 1]) % mod;
    }
    void build(int u, int l, int r, const vector<long long> &a) {
        if (l == r) {
            sum[u] = (a[l] % mod + mod) % mod;
            square[u] = sum[u] * sum[u] % mod;
            return;
        }
        int mid = (l + r) / 2;
        build(u * 2, l, mid, a);
        build(u * 2 + 1, mid + 1, r, a);
        pull(u);
    }
    void apply(int u, int l, int r, long long v) {
        v = (v % mod + mod) % mod;
        square[u] = (square[u] + 2 * v * sum[u] + (r - l + 1) * v % mod * v) % mod;
        sum[u] = (sum[u] + (r - l + 1) * v) % mod;
        tag[u] = (tag[u] + v) % mod;
    }
    void push(int u, int l, int r) {
        if (!tag[u] || l == r)
            return;
        int mid = (l + r) / 2;
        apply(u * 2, l, mid, tag[u]);
        apply(u * 2 + 1, mid + 1, r, tag[u]);
        tag[u] = 0;
    }
    void change(int u, int l, int r, int ql, int qr, long long v) {
        if (ql <= l && r <= qr) {
            apply(u, l, r, v);
            return;
        }
        push(u, l, r);
        int mid = (l + r) / 2;
        if (ql <= mid)
            change(u * 2, l, mid, ql, qr, v);
        if (qr > mid)
            change(u * 2 + 1, mid + 1, r, ql, qr, v);
        pull(u);
    }
    long long query(int u, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr)
            return square[u];
        push(u, l, r);
        int mid = (l + r) / 2;
        long long value = 0;
        if (ql <= mid)
            value += query(u * 2, l, mid, ql, qr);
        if (qr > mid)
            value += query(u * 2 + 1, mid + 1, r, ql, qr);
        return value % mod;
    }
    long long querySum(int u, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr)
            return sum[u];
        push(u, l, r);
        int mid = (l + r) / 2;
        long long value = 0;
        if (ql <= mid)
            value += querySum(u * 2, l, mid, ql, qr);
        if (qr > mid)
            value += querySum(u * 2 + 1, mid + 1, r, ql, qr);
        return value % mod;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<long long> weight(n + 1);
    for (int i = 1; i <= n; i++)
        cin >> weight[i];
    EulerTree tree(n);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        tree.add(u, v);
    }
    tree.root(1);
    vector<int> size(n + 1, 1), heavy(n + 1), head(n + 1);
    size[0] = 0;
    for (int i = n - 1; i >= 0; i--) {
        int u = tree.order[i];
        for (int v : tree.edge[u])
            if (tree.parent[v] == u) {
                size[u] += size[v];
                if (size[v] > size[heavy[u]])
                    heavy[u] = v;
            }
    }
    vector<pair<int, int>> stack = {{1, 1}};
    int timer = 0;
    vector<long long> a(n + 1);
    while (!stack.empty()) {
        auto [start, h] = stack.back();
        stack.pop_back();
        for (int u = start; u; u = heavy[u]) {
            head[u] = h;
            tree.in[u] = ++timer;
            a[timer] = weight[u];
            for (int v : tree.edge[u])
                if (tree.parent[v] == u && v != heavy[u])
                    stack.push_back({v, v});
        }
    }
    SquareTree segment(a);
    const long long mod = 1000000007;
    auto path = [&](int u, int v, auto process) {
        while (head[u] != head[v]) {
            if (tree.depth[head[u]] < tree.depth[head[v]])
                swap(u, v);
            process(tree.in[head[u]], tree.in[u]);
            u = tree.parent[head[u]];
        }
        if (tree.depth[u] > tree.depth[v])
            swap(u, v);
        process(tree.in[u], tree.in[v]);
    };
    while (m--) {
        int op, u;
        cin >> op >> u;
        if (op == 1) {
            long long value;
            cin >> value;
            segment.change(1, 1, n, tree.in[u], tree.in[u] + size[u] - 1, value);
        } else if (op == 2) {
            int v;
            long long value;
            cin >> v >> value;
            path(u, v, [&](int l, int r) { segment.change(1, 1, n, l, r, value); });
        } else {
            int v;
            cin >> v;
            long long sum = 0, square = 0;
            path(u, v, [&](int l, int r) {
                sum = (sum + segment.querySum(1, 1, n, l, r)) % mod;
                square = (square + segment.query(1, 1, n, l, r)) % mod;
            });
            cout << (sum * sum % mod - square + mod) % mod * 500000004 % mod << '\n';
        }
    }
    return 0;
}
```

### 复杂度

子树修改 $O(\log n)$，路径操作 $O(\log² n)$，空间 $O(n)$。

### 易错点

重儿子比较前size[0]应为0；这里空儿子0初始化后需显式清零。单点路径的不同点对数为0。

## 纸牌

### 题意

两张初始均为 n 的牌，交替操作三次，减数不能大于另一张，求最后总和最小值。

### 思路

设第一次后操作牌剩 x，则第二张最少剩 n-x。第三次结束时，总和至少为 max(x,n-x)，最小值是 n 的一半向上取整。取 x=floor(n/2)，第二次把另一张减到 n-x，第三次清空第一张即可达到。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n;
    cin >> n;
    cout << (n + 1) / 2;
    return 0;
}
```

### 复杂度

时间与额外空间均为 $O(1)$。

### 易错点

第一次直接减到零会使第二次无法减少另一张牌，并非最优。每次可减零。

## 毒瘤xor

### 题意

每次查询选一个最小的非负 31 位整数 x，最大化区间内各数与 x 异或的总和。

### 思路

每个二进制位独立贡献。若该位原数组中零更多，令 x 的该位为一，就让更多结果位为一；若一更多，令 x 该位为零。两种数量相同则收益相同，为使 x 最小应选零。预处理每一位上一的前缀数量，每次查询在三十一位分别比较。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<array<int, 31>> prefix(n + 1);
    prefix[0].fill(0);
    for (int i = 1; i <= n; i++) {
        int x;
        cin >> x;
        for (int b = 0; b <= 30; b++)
            prefix[i][b] = prefix[i - 1][b] + (x >> b & 1);
    }
    int q;
    cin >> q;
    while (q--) {
        int l, r;
        cin >> l >> r;
        long long answer = 0;
        for (int b = 0; b <= 30; b++) {
            int ones = prefix[r][b] - prefix[l - 1][b];
            if (2 * ones < r - l + 1)
                answer |= 1LL << b;
        }
        cout << answer << '\n';
    }
    return 0;
}
```

### 复杂度

时间 $O(31(n+q))$，空间 $O(31n)$。

### 易错点

即使 a[i] 小于 2^30，x 仍允许第 30 位为一；必须检查零到三十共三十一位。平票时选零。

## 数字权重

### 题意

首位非零的n位数，其相邻位差之和为K，求方案数。

### 思路

所有中间项消去，相邻位差之和恰为末位减首位。枚举首位a=1..9，只要0≤a+K≤9，就确定了合法末位。其余n−2位完全自由，各有10种选择，因此答案是合法首位数乘10^(n−2)。指数至10^13，用快速幂。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, k;
    cin >> n >> k;
    const long long mod = 1000000007;
    long long count = 0;
    for (int first = 1; first <= 9; first++)
        if (0 <= first + k && first + k <= 9)
            count++;
    long long power = 1, base = 10, exponent = n - 2;
    while (exponent) {
        if (exponent & 1)
            power = power * base % mod;
        base = base * base % mod;
        exponent >>= 1;
    }
    cout << count * power % mod;
    return 0;
}
```

### 复杂度

时间 $O(\log n)$，空间 $O(1)$。

### 易错点

K可以为负数，最高位不能为0。n=2时中间没有位置，幂应为1。

## 粉嘤花之恋

### 题意

每次新花瓣替换旧花瓣，求树上和地上的总数。

### 思路

第i次新长花瓣数为1+Σ(j=1..i−1)F[j]=F[i+1]。旧花瓣落地后仍计入，所以k次后总数是初始1加Σ(i=1..k)F[i+1]=F[k+3]−1。用快速倍增求F[k+3]：由(F[t],F[t+1])得到F[2t]=F[t]*(2F[t+1]−F[t])、F[2t+1]=F[t]²+F[t+1]²。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

pair<long long, long long> fibonacci(unsigned long long n, long long mod) {
    if (!n)
        return {0, 1};
    auto [a, b] = fibonacci(n / 2, mod);
    long long c = a * ((2 * b - a + mod) % mod) % mod;
    long long d = (a * a % mod + b * b % mod) % mod;
    if (n & 1)
        return {d, (c + d) % mod};
    return {c, d};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    unsigned long long k;
    cin >> k;
    const long long mod = 998244353;
    cout << (fibonacci(k + 3, mod).first + mod - 1) % mod;
    return 0;
}
```

### 复杂度

时间、递归空间均为 $O(\log k)$。

### 易错点

初始花瓣也在总数内，不能只加各次净增长。减1后规范到非负余数。

## 硬币游戏

### 题意

双方轮流选同一组列位置，各取自己那一行硬币，比较得到的二进制串。

### 思路

把每列分成UU、UD、DU、DD。当前位优先取U；同为U时优先UU，因为还能阻止对手获得一个U。自己没有U时优先拿走对手的U。这三条优先级可通过交换首个不同选择证明：不降低自己的当前位，同时只减少对手未来可取的1。

设UU有c个、UD有a个、DU有b个。双方先轮流消耗UU。c为偶数时回到先手轮，双方再各自取独有U：a>b先手胜；a=b平局；a<b时先手先耗尽，但还能取走对手一个DU，所以b=a+1也平局，b≥a+2才后手胜。

c为奇数时，后手必须先取一个DU来匹配先手刚取得的最后一个UU，否则立刻输；取后等价于偶数情况中把b减1。统一令d=a−b+(c mod 2)：d>0先手胜，d=0或−1平局，d<−1后手胜。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string a, b;
    cin >> n >> a >> b;
    int both = 0, first = 0, second = 0;
    for (int i = 0; i < 2 * n; i++) {
        if (a[i] == 'U' && b[i] == 'U')
            both++;
        else if (a[i] == 'U')
            first++;
        else if (b[i] == 'U')
            second++;
    }
    int difference = first - second + (both % 2);
    if (difference > 0)
        cout << "clccle trl!";
    else if (difference < -1)
        cout << "sarlendy tql!";
    else
        cout << "orz sarlendy!";
    return 0;
}
```

### 复杂度

时间 $O(n)$，空间 $O(n)$ 存输入。

### 易错点

每选一列就同时占用双方对应位置，不是从两行任取一枚。相等时输出指定平局字符串。

## 选择颜色

### 题意

n 个有顺序的人围成环，相邻颜色不同，使用 c 种颜色计数。

### 思路

环的染色数为 (c-1)^n+(-1)^n(c-1)。可用递推证明：把 n 点环最后一条边先去掉，路径有 c(c-1)^(n-1) 种染法；其中首尾同色者把首尾合并后对应 n-1 点环，所以 C[n]=c(c-1)^(n-1)-C[n-1]。从 C[2]=c(c-1) 开始代入即可归纳得到公式。用快速幂算第一项，再按 n 奇偶加减 c-1。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long mod = 10007;
    long long n, c;
    cin >> n >> c;
    long long base = c - 1, exponent = n, answer = 1;
    while (exponent) {
        if (exponent & 1)
            answer = answer * base % mod;
        base = base * base % mod;
        exponent >>= 1;
    }
    answer += n % 2 ? -(c - 1) : c - 1;
    cout << (answer % mod + mod) % mod;
    return 0;
}
```

### 复杂度

时间 $O(\log n)$，额外空间 $O(1)$。

### 易错点

人有固定顺序，旋转后的着色仍算不同，不要再除以 n。奇数环减法后应规范到非负模值。

## 石子游戏

### 题意

奇堆可分成两堆，偶堆两堆可合并，不能操作者输。

### 思路

奇数分裂后恰有一奇一偶，奇堆的总数不变；每次分裂新增一个偶堆，每次合并减少一个偶堆。终局所有奇堆都是1，偶堆至多一个。若最初至少有偶堆，或存在大于1的奇堆，过程中必出现偶堆，终局恰剩一个。

设初始偶堆E，分裂S次，则合并E+S−1次，总步数2S+E−1，奇偶仅由E决定。E为偶数时总步数奇，先手胜；E为奇数时后手胜。若所有堆都是1，则没有任何操作，直接后手胜。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    int even = 0;
    bool activeOdd = false;
    while (n--) {
        int x;
        cin >> x;
        if (x % 2 == 0)
            even++;
        else if (x > 1)
            activeOdd = true;
    }
    cout << ((even % 2 == 0 && (even > 0 || activeOdd)) ? "Alice" : "Bob");
    return 0;
}
```

### 复杂度

时间 $O(n)$，空间 $O(1)$。

### 易错点

分裂次数可以不同，但总步数奇偶固定。全是1时不能套用终局存在一个偶堆的公式。

## 失衡天平

### 题意

每次可拿走天平两侧差不超过m的武器，允许多次操作，最大化带走总重量。

### 思路

多次操作不比一次更强：每组的重量差绝对值≤m，把下一组较重侧朝向目前较轻侧合并，总差变成两个差的绝对值，仍≤m。因此可把所有拿走的武器放在一次称量中。

用dp[d]记录当前左右重量差绝对值为d时，能选出的最大总重。每件武器有不选、放较重侧、放较轻侧三种选择，差分别为d、d+x、|d−x|，后两者总重加x。用新数组转移保证每件一次。最后在0到m的差值中取最大总重。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    int sum = 0;
    for (int &x : a) {
        cin >> x;
        sum += x;
    }
    vector<int> dp(sum + 1, -1);
    dp[0] = 0;
    int processed = 0;
    for (int x : a) {
        vector<int> next = dp;
        for (int d = 0; d <= processed; d++)
            if (dp[d] >= 0) {
                next[d + x] = max(next[d + x], dp[d] + x);
                next[abs(d - x)] = max(next[abs(d - x)], dp[d] + x);
            }
        processed += x;
        dp.swap(next);
    }
    cout << *max_element(dp.begin(), dp.begin() + min(sum, m) + 1);
    return 0;
}
```

### 复杂度

总重量 $S\le10000$，时间 $O(nS)$，空间 $O(S)$。

### 易错点

m不是背包容量，是两侧重量差上限。必须允许武器暂不选择；同一件不可从本轮新状态再用一次。

## 生日宴

### 题意

查询某个月日生日的人中，年龄第 k 大者的名字。

### 思路

用日期对一万取余得到月日，把朋友按月日分组。每组按完整出生日期从小到大排序，出生越早年龄越大；查询 (k,s) 直接输出 s 组的第 k-1 项。题目保证日期不重复且询问有答案。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    map<int, vector<pair<int, string>>> groups;
    for (int i = 0; i < n; i++) {
        string name;
        int date;
        cin >> name >> date;
        groups[date % 10000].push_back({date, name});
    }
    for (auto &[day, people] : groups)
        sort(people.begin(), people.end());
    while (m--) {
        int k, day;
        cin >> k >> day;
        cout << groups[day][k - 1].second << '\n';
    }
    return 0;
