```

### 复杂度

排序总时间 $O(n\log n)$，每次定位分组 $O(\log n)$，空间 $O(n)$。

### 易错点

输入询问的顺序是 k、月日。用 cin 读入十进制整数 0220 会得到 220，和分组键一致，不要把它手写为 C++ 八进制常量。

## 数据结构

### 题意

支持区间乘、区间加，以及区间和、平方和查询。

### 思路

统一把修改写成 x→ax+b。一个长 len 的节点维护 S=Σx、Q=Σx²，应用修改后 S′=aS+b len，Q′=a²Q+2abS+b²len。懒标记也按先后顺序复合：原标记 (m,c) 后再执行 (a,b)，变成 (am,ac+b)。求平方和时必须使用修改前的 S。

题目只保证查询结果落在有符号64位，未保证长时间未查询的中间量与懒乘积不溢出。代码把全部维护量放在模 2^64 的环中：unsigned long long 的加乘溢出有明确定义，所有上述多项式等式仍成立。查询结果既然保证在有符号64位范围，其模 2^64 余数就唯一决定真实答案；最高位为一时按负数的绝对值输出。这也处理先多次放大、再乘零、最后查询等情况。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct AffineTree {
    using U = unsigned long long;
    struct Node {
        U sum = 0, squares = 0, multiply = 1, add = 0;
    };
    int n;
    U modulus;
    vector<Node> tree;
    AffineTree(const vector<U> &a, U mod) : n((int)a.size() - 1), modulus(mod), tree(4 * n + 4) {
        build(1, 1, n, a);
    }
    U plus(U a, U b) const { return modulus ? (a + b) % modulus : a + b; }
    U times(U a, U b) const { return modulus ? a * b % modulus : a * b; }
    U length(int len) const { return modulus ? (U)len % modulus : (U)len; }
    void pull(int p) {
        tree[p].sum = plus(tree[p * 2].sum, tree[p * 2 + 1].sum);
        tree[p].squares = plus(tree[p * 2].squares, tree[p * 2 + 1].squares);
    }
    void build(int p, int l, int r, const vector<U> &a) {
        if (l == r) {
            tree[p].sum = a[l];
            tree[p].squares = times(a[l], a[l]);
            return;
        }
        int mid = (l + r) / 2;
        build(p * 2, l, mid, a);
        build(p * 2 + 1, mid + 1, r, a);
        pull(p);
    }
    void apply(int p, int len, U a, U b) {
        U old = tree[p].sum;
        tree[p].squares =
            plus(plus(times(times(a, a), tree[p].squares), times(times(times(2, a), b), old)),
                 times(times(b, b), length(len)));
        tree[p].sum = plus(times(a, old), times(b, length(len)));
        tree[p].multiply = times(tree[p].multiply, a);
        tree[p].add = plus(times(tree[p].add, a), b);
    }
    void push(int p, int l, int r) {
        if (tree[p].multiply == 1 && tree[p].add == 0)
            return;
        int mid = (l + r) / 2;
        apply(p * 2, mid - l + 1, tree[p].multiply, tree[p].add);
        apply(p * 2 + 1, r - mid, tree[p].multiply, tree[p].add);
        tree[p].multiply = 1;
        tree[p].add = 0;
    }
    void change(int p, int l, int r, int ql, int qr, U a, U b) {
        if (ql <= l && r <= qr) {
            apply(p, r - l + 1, a, b);
            return;
        }
        push(p, l, r);
        int mid = (l + r) / 2;
        if (ql <= mid)
            change(p * 2, l, mid, ql, qr, a, b);
        if (qr > mid)
            change(p * 2 + 1, mid + 1, r, ql, qr, a, b);
        pull(p);
    }
    pair<U, U> query(int p, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr)
            return {tree[p].sum, tree[p].squares};
        push(p, l, r);
        int mid = (l + r) / 2;
        pair<U, U> result{0, 0};
        if (ql <= mid)
            result = query(p * 2, l, mid, ql, qr);
        if (qr > mid) {
            auto other = query(p * 2 + 1, mid + 1, r, ql, qr);
            result.first = plus(result.first, other.first);
            result.second = plus(result.second, other.second);
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    using U = unsigned long long;
    int n, m;
    cin >> n >> m;
    vector<U> a(n + 1);
    for (int i = 1; i <= n; i++) {
        long long x;
        cin >> x;
        a[i] = (U)x;
    }
    AffineTree tree(a, 0);
    while (m--) {
        int op, l, r;
        cin >> op >> l >> r;
        if (op <= 2) {
            auto result = tree.query(1, 1, n, l, r);
            U value = op == 1 ? result.first : result.second;
            if (value <= (U)LLONG_MAX)
                cout << value << '\n';
            else
                cout << '-' << (~value + 1ULL) << '\n';
        } else {
            long long x;
            cin >> x;
            if (op == 3)
                tree.change(1, 1, n, l, r, (U)x, 0);
            else
                tree.change(1, 1, n, l, r, 1, (U)x);
        }
    }
    return 0;
}
```

### 复杂度

每个操作 $O(\log n)$，空间 $O(n)$。

### 易错点

有符号整数溢出在 C++ 中不可依赖；这里刻意使用无符号环，最终再根据题目保证还原有符号值。此技巧只因查询输出范围已知且运算全是整数多项式才成立。

## 游戏

### 题意

三人轮流把左上矩形按R→G→B→R变色，选点必须非B，求最终不能操作的人。

### 思路

每次操作必包含左上角，所以它每步都沿R→G→B→R变化。终局全B，因此总操作数L模3仅由初始左上角决定：R需2步、G需1步、B需0步。下一位即失败者，分别为dreagonm、fengxunling、BLUESKY007。

还需确认不会无限循环：把格子按从右下到左上的行优先顺序作为三进制位，令R=2、G=1、B=0，越靠右下权越高。选中格是本次影响范围内权最高的格，它从2降1或1降0，所有更高位不变，因此整个势能严格下降。游戏必结束，策略不影响失败者。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n, m;
        cin >> n >> m;
        string row;
        char first = 'B';
        for (int i = 0; i < n; i++) {
            cin >> row;
            if (i == 0)
                first = row[0];
        }
        if (first == 'R')
            cout << "dreagonm\n";
        else if (first == 'G')
            cout << "fengxunling\n";
        else
            cout << "BLUESKY007\n";
    }
    return 0;
}
```

### 复杂度

读入时间 $O(nm)$，空间 $O(m)$。

### 易错点

左上角一开始为B并不表示立即结束，但最终总步数必为3的倍数。

## 好朋友

### 题意

统计十进制表示中含子序列007的数，多个区间答案异或。

### 思路

状态0、1、2、3表示已经依次匹配007的长度，3为吸收态。当前数码等于下一个所需字符时匹配长度加1，不相等则保持。还需started区分前导0，未开始的0不能用于匹配。按剩余位数、匹配状态、started缓存自由状态，十万组询问共用；每问两个前缀差，异或进最终结果。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long memo[20][4][2];
    memset(memo, -1, sizeof(memo));
    auto count = [&](long long bound) {
        if (bound < 0)
            return 0LL;
        string s = to_string(bound), pattern = "007";
        auto dfs = [&](auto &&self, int p, int state, bool started, bool tight) -> long long {
            if (p == (int)s.size())
                return state == 3;
            long long &cache = memo[s.size() - p][state][started];
            if (!tight && cache != -1)
                return cache;
            int maximum = tight ? s[p] - '0' : 9;
            long long result = 0;
            for (int d = 0; d <= maximum; d++) {
                bool begun = started || d;
                int next = state;
                if (begun && next < 3 && d == pattern[next] - '0')
                    next++;
                result += self(self, p + 1, next, begun, tight && d == maximum);
            }
            if (!tight)
                cache = result;
            return result;
        };
        return dfs(dfs, 0, 0, false, true);
    };
    int tests;
    cin >> tests;
    long long answer = 0;
    while (tests--) {
        long long l, r;
        cin >> l >> r;
        answer ^= count(r) - count(l - 1);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

预处理自由状态 $O(D\cdot8\cdot10)$，每次边界 $O(10D)$，总 $O(TD)$，空间 $O(8D)$。

### 易错点

007是子序列，可以不连续；前导0不属于名字。匹配成功后不可被后续数码取消。

## 换个角度思考

### 题意

静态数组，询问[l,r]中≤x的元素数。

### 思路

将数组元素按值升序，询问按阈值x升序。处理一个询问前，把所有值≤x的元素在其原下标上加1。此时树状数组的区间计数就是答案。询问保留编号，最后按原顺序输出。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> tree;
    Fenwick(int n) : n(n), tree(n + 1) {}
    void add(int p, long long v) {
        for (; p <= n; p += p & -p)
            tree[p] += v;
    }
    long long sum(int p) {
        long long result = 0;
        for (; p; p -= p & -p)
            result += tree[p];
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<pair<int, int>> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i].first;
        a[i].second = i + 1;
    }
    vector<array<int, 4>> query(m);
    for (int i = 0; i < m; i++) {
        int l, r, x;
        cin >> l >> r >> x;
        query[i] = {x, l, r, i};
    }
    sort(a.begin(), a.end());
    sort(query.begin(), query.end());
    Fenwick bit(n);
    vector<int> answer(m);
    int p = 0;
    for (auto [x, l, r, id] : query) {
        while (p < n && a[p].first <= x) {
            bit.add(a[p].second, 1);
            p++;
        }
        answer[id] = bit.sum(r) - bit.sum(l - 1);
    }
    for (int x : answer)
        cout << x << '\n';
    return 0;
}
```

### 复杂度

时间 $O((n+m)\log(n+m))$，空间 $O(n+m)$。

### 易错点

阈值相等的数组元素要先全部插入，条件是≤而非<。离线排序不能改变输出顺序。

## 树上求和

### 题意

子树加，查询子树权值平方和模23333。

### 思路

DFS序把子树化为区间。线段树同时维护总和S与平方和Q；长度len的一段加v后，Q新=Q+2vS+len*v²，S新=S+len*v。区间加懒标记累加，下传后再做部分修改或查询，始终模23333。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct EulerTree {
    int n;
    vector<vector<int>> edge;
    vector<int> parent, depth, in, out, order;
    EulerTree(int n) : n(n), edge(n + 1), parent(n + 1), depth(n + 1), in(n + 1), out(n + 1) {}
    void add(int u, int v) {
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    void root(int start) {
        vector<int> stack = {start};
        parent[start] = 0;
        order.clear();
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            in[u] = order.size() + 1;
            order.push_back(u);
            for (int v : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack.push_back(v);
                }
        }
        vector<int> size(n + 1, 1);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            out[u] = in[u] + size[u] - 1;
            if (parent[u])
                size[parent[u]] += size[u];
        }
    }
};

struct SquareTree {
    static constexpr long long mod = 23333;
    int n;
    vector<long long> sum, square, tag;
    SquareTree(const vector<long long> &a)
        : n((int)a.size() - 1), sum(4 * n + 4), square(4 * n + 4), tag(4 * n + 4) {
        build(1, 1, n, a);
    }
    void pull(int u) {
        sum[u] = (sum[u * 2] + sum[u * 2 + 1]) % mod;
        square[u] = (square[u * 2] + square[u * 2 + 1]) % mod;
    }
    void build(int u, int l, int r, const vector<long long> &a) {
        if (l == r) {
            sum[u] = (a[l] % mod + mod) % mod;
            square[u] = sum[u] * sum[u] % mod;
            return;
        }
        int mid = (l + r) / 2;
        build(u * 2, l, mid, a);
        build(u * 2 + 1, mid + 1, r, a);
        pull(u);
    }
    void apply(int u, int l, int r, long long v) {
        v = (v % mod + mod) % mod;
        square[u] = (square[u] + 2 * v * sum[u] + (r - l + 1) * v % mod * v) % mod;
        sum[u] = (sum[u] + (r - l + 1) * v) % mod;
        tag[u] = (tag[u] + v) % mod;
    }
    void push(int u, int l, int r) {
        if (!tag[u] || l == r)
            return;
        int mid = (l + r) / 2;
        apply(u * 2, l, mid, tag[u]);
        apply(u * 2 + 1, mid + 1, r, tag[u]);
        tag[u] = 0;
    }
    void change(int u, int l, int r, int ql, int qr, long long v) {
        if (ql <= l && r <= qr) {
            apply(u, l, r, v);
            return;
        }
        push(u, l, r);
        int mid = (l + r) / 2;
        if (ql <= mid)
            change(u * 2, l, mid, ql, qr, v);
        if (qr > mid)
            change(u * 2 + 1, mid + 1, r, ql, qr, v);
        pull(u);
    }
    long long query(int u, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr)
            return square[u];
        push(u, l, r);
        int mid = (l + r) / 2;
        long long value = 0;
        if (ql <= mid)
            value += query(u * 2, l, mid, ql, qr);
        if (qr > mid)
            value += query(u * 2 + 1, mid + 1, r, ql, qr);
        return value % mod;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> value(n + 1);
    for (int i = 1; i <= n; i++)
        cin >> value[i];
    EulerTree tree(n);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        tree.add(u, v);
    }
    tree.root(1);
    vector<long long> a(n + 1);
    for (int u = 1; u <= n; u++)
        a[tree.in[u]] = value[u];
    SquareTree segment(a);
    while (q--) {
        int op, u;
        cin >> op >> u;
        if (op == 1) {
            long long v;
            cin >> v;
            segment.change(1, 1, n, tree.in[u], tree.out[u], v);
        } else
            cout << segment.query(1, 1, n, tree.in[u], tree.out[u]) << '\n';
    }
    return 0;
}
```

### 复杂度

构建 $O(n)$，每次操作 $O(\log n)$，空间 $O(n)$。

### 易错点

Q的更新使用修改前的S。平方和与和的平方不同，不能只维护总和。

## 红球进黑洞

### 题意

区间异或、区间和，数值和异或掩码至10^5。

### 思路

每个节点按二进制位记录1的个数。第b位异或1时，计数变成区间长度−原计数，其他位不变；懒标记按异或合并。数值小于2^17，记录17位即可。区间和是Σ count[b]*2^b。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<array<int, 17>> count(4 * n + 4);
    vector<int> tag(4 * n + 4);
    auto pull = [&](int u) {
        for (int b = 0; b < 17; b++)
            count[u][b] = count[u * 2][b] + count[u * 2 + 1][b];
    };
    auto build = [&](auto &&self, int u, int l, int r) -> void {
        if (l == r) {
            int x;
            cin >> x;
            for (int b = 0; b < 17; b++)
                count[u][b] = x >> b & 1;
            return;
        }
        int mid = (l + r) / 2;
        self(self, u * 2, l, mid);
        self(self, u * 2 + 1, mid + 1, r);
        pull(u);
    };
    build(build, 1, 1, n);
    auto apply = [&](int u, int l, int r, int x) {
        for (int b = 0; b < 17; b++)
            if (x >> b & 1)
                count[u][b] = r - l + 1 - count[u][b];
        tag[u] ^= x;
    };
    auto push = [&](int u, int l, int r) {
        if (tag[u]) {
            int mid = (l + r) / 2;
            apply(u * 2, l, mid, tag[u]);
            apply(u * 2 + 1, mid + 1, r, tag[u]);
            tag[u] = 0;
        }
    };
    auto update = [&](auto &&self, int u, int l, int r, int ql, int qr, int x) -> void {
        if (ql <= l && r <= qr) {
            apply(u, l, r, x);
            return;
        }
        push(u, l, r);
        int mid = (l + r) / 2;
        if (ql <= mid)
            self(self, u * 2, l, mid, ql, qr, x);
        if (qr > mid)
            self(self, u * 2 + 1, mid + 1, r, ql, qr, x);
        pull(u);
    };
    auto query = [&](auto &&self, int u, int l, int r, int ql, int qr) -> long long {
        if (ql <= l && r <= qr) {
            long long result = 0;
            for (int b = 0; b < 17; b++)
                result += 1LL * count[u][b] * (1 << b);
            return result;
        }
        push(u, l, r);
        int mid = (l + r) / 2;
        long long result = 0;
        if (ql <= mid)
            result += self(self, u * 2, l, mid, ql, qr);
        if (qr > mid)
            result += self(self, u * 2 + 1, mid + 1, r, ql, qr);
        return result;
    };
    while (m--) {
        int op, l, r;
        cin >> op >> l >> r;
        if (op == 2) {
            int k;
            cin >> k;
            update(update, 1, 1, n, l, r, k);
        } else
            cout << query(query, 1, 1, n, l, r) << '\n';
    }
    return 0;
}
```

### 复杂度

每次操作 $O(17\log n)$，空间 $O(17n)$。

### 易错点

异或两次同一掩码应抵消，所以懒标记用xor。不要只记录区间异或值，它无法恢复区间和。

## Tobaku Mokushiroku Kaiji

### 题意

双方各有石头、剪刀、布若干张，求第一人最多能获胜几局。

### 思路

石头只能靠对方的剪刀取得胜场，贡献 min(a,e)；剪刀对布贡献 min(b,f)；布对石头贡献 min(c,d)。三类配对互不争用同一种牌，所以三个最大值可以同时取到，直接相加。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a, b, c, d, e, f;
    cin >> a >> b >> c >> d >> e >> f;
    cout << min(a, e) + min(b, f) + min(c, d);
    return 0;
}
```

### 复杂度

时间与额外空间均为 $O(1)$。

### 易错点

目标只是最大胜场，剩余牌如何输或平不会增加胜场，也不影响已选出的获胜配对。

## Eustia of the Tarnished Wings

### 题意

领导人属性差不超过 m 的两势力可合并，并保留两位领导人之一。

### 思路

把属性升序排序。相邻差不超过 m 的一段可全部合并：从左到右合并，每次保留右侧较大的领导人，它就能继续与下一个相邻领导人连接。相邻差大于 m 的地方两边任何属性差都大于 m，领导人又始终来自原集合，因此永远无法跨过。答案就是这些段的数量。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long m;
    cin >> n >> m;
    vector<long long> a(n);
    for (auto &x : a)
        cin >> x;
    sort(a.begin(), a.end());
    int answer = 1;
    for (int i = 1; i < n; i++)
        if (a[i] - a[i - 1] > m)
            answer++;
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，保存输入的空间 $O(n)$。

### 易错点

合并后可以主动保留新的领导人，所以一段的最大值减最小值可以远大于 m。不能直接按整段极差分组。

## 卡牌游戏

### 题意

N种卡中M种稀有，已抽过的稀有从池中移除，求集齐K种的期望次数。

### 思路

已收集i种稀有时，抽卡池剩N−i种，稀有剩M−i种，下一次获得新稀有的概率为(M−i)/(N−i)。几何分布等待次数期望是其倒数，所以总期望Σ(i=0..K−1)(N−i)/(M−i)。普通卡会重复，不能从抽卡池删掉。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    cout << fixed << setprecision(10);
    for (int tc = 1; tc <= tests; tc++) {
        int n, m, k;
        cin >> n >> m >> k;
        long double answer = 0;
        for (int i = 0; i < k; i++)
            answer += (long double)(n - i) / (m - i);
        cout << "Case #" << tc << ": " << answer << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O(K)$，空间 $O(1)$。

### 易错点

分母随已收集稀有卡数量变化，分子也变化；不是固定池的优惠券模型。

## Tree

### 题意

对每个结点分别统计包含它的连通点集数量，模十亿加七，n至一百万。

### 思路

固定一棵根树。down[u]表示只在u子树里、包含u的连通集合数。每个孩子方向可以不选，或选一个包含孩子的连通集合，所以down[u]=Π(down[v]+1)。再定义up[u]为父亲方向、包含父亲的连通集合数，则答案为down[u]*(up[u]+1)。给孩子v传递时，up[v]=(up[u]+1)*Π其他孩子(down[child]+1)。

乘积中可能有0，不能用模逆元除掉当前孩子。对每个u的孩子列表建前缀乘积，再从后往前用后缀乘积组合，线性求出所有排除单个孩子的积。树遍历和换根都用迭代，邻接表用连续数组减少百万结点的内存开销。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> head(n, -1), to(max(0, 2 * n - 2)), next(to.size());
    int edges = 0;
    auto addEdge = [&](int a, int b) {
        to[edges] = b;
        next[edges] = head[a];
        head[a] = edges++;
    };
    for (int i = 1; i < n; i++) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        addEdge(a, b);
        addEdge(b, a);
    }
    vector<int> parent(n, -1), order{0};
    parent[0] = 0;
    order.reserve(n);
    for (size_t i = 0; i < order.size(); i++) {
        int u = order[i];
        for (int e = head[u]; e != -1; e = next[e])
            if (to[e] != parent[u]) {
                parent[to[e]] = u;
                order.push_back(to[e]);
            }
    }
    const long long mod = 1000000007;
    vector<long long> down(n, 1), up(n);
    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];
        for (int e = head[u]; e != -1; e = next[e])
            if (to[e] != parent[u])
                down[u] = down[u] * (down[to[e]] + 1) % mod;
    }
    vector<int> children;
    vector<long long> prefix;
    for (int u : order) {
        children.clear();
        for (int e = head[u]; e != -1; e = next[e])
            if (to[e] != parent[u])
                children.push_back(to[e]);
        prefix.assign(children.size() + 1, 1);
        for (size_t i = 0; i < children.size(); i++)
            prefix[i + 1] = prefix[i] * (down[children[i]] + 1) % mod;
        long long suffix = 1;
        for (int i = (int)children.size() - 1; i >= 0; i--) {
            int v = children[i];
            up[v] = (up[u] + 1) * prefix[i] % mod * suffix % mod;
            suffix = suffix * (down[v] + 1) % mod;
        }
    }
    for (int u = 0; u < n; u++)
        cout << down[u] * (up[u] + 1) % mod << '\n';
    return 0;
}
```

### 复杂度

时间、空间均为 $O(n)$。

### 易错点

每个方向可以整个不选，但只要选就必须包含邻点以保持连通。先把原方向值全部求好，再换根，不能覆盖down原值。

## Shopping

### 题意

最多 m 辆购物车，每辆含凳子的车可将最贵的一件商品半价。

### 思路

设凳子有 s 件，最多可得到 k=min(m,s) 次折扣。任意方案省下的钱不超过全体最贵 k 件价格之和的一半。这个上界可达：给这 k 件商品各放一辆车，若某件本身是凳子就已有资格，否则从剩余凳子中给它配一件。因为总凳子数至少 k，必能配齐；剩余商品都不比这 k 件贵，放进其中任一车不会降低折扣。没有凳子时原价购买。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n, m, stools = 0;
        cin >> n >> m;
        vector<long long> prices(n);
        long long total = 0;
        for (auto &price : prices) {
            int isStool;
            cin >> price >> isStool;
            total += price;
            stools += isStool;
        }
        sort(prices.begin(), prices.end(), greater<long long>());
        long long twice = 2 * total;
        for (int i = 0; i < min(m, stools); i++)
            twice -= prices[i];
        cout << twice / 2 << (twice % 2 ? ".5\n" : ".0\n");
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

凳子本身也可成为半价商品。用金额的两倍做整数运算，避免浮点格式误差；购物车不要求全都使用。

## Graph Coloring I

### 题意

输出图的二染色或任意简单奇环。

### 思路

BFS用深度奇偶染色，同时保存父节点。若每条边两端异色，直接输出染色。否则找到同色边(u,v)，在BFS树中把u、v分别沿父链上移到公共祖先，合并成树上简单路径，再用原边闭合。两端同色意味着树路径长度为偶数，加闭合边形成奇环。公共祖先只放一次，保证简单。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> edge(n);
    while (m--) {
        int u, v;
        cin >> u >> v;
        u--;
        v--;
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    vector<int> color(n, -1), parent(n, -1), depth(n);
    vector<int> queue = {0};
    color[0] = 0;
    int a = -1, b = -1;
    for (size_t h = 0; h < queue.size() && a < 0; h++) {
        int u = queue[h];
        for (int v : edge[u]) {
            if (color[v] < 0) {
                color[v] = color[u] ^ 1;
                parent[v] = u;
                depth[v] = depth[u] + 1;
                queue.push_back(v);
            } else if (color[v] == color[u]) {
                a = u;
                b = v;
                break;
            }
        }
    }
    if (a < 0) {
        cout << 0 << '\n';
        for (int i = 0; i < n; i++)
            cout << color[i] << (i + 1 == n ? '\n' : ' ');
        return 0;
    }
    vector<int> left, right;
    while (a != b) {
        if (depth[a] >= depth[b]) {
            left.push_back(a);
            a = parent[a];
        } else {
            right.push_back(b);
            b = parent[b];
        }
    }
    left.push_back(a);
    reverse(right.begin(), right.end());
    left.insert(left.end(), right.begin(), right.end());
    cout << left.size() << '\n';
    for (int i = 0; i < (int)left.size(); i++)
        cout << left[i] + 1 << (i + 1 == (int)left.size() ? '\n' : ' ');
    return 0;
}
```

### 复杂度

时间、空间均 $O(n+m)$。

### 易错点

同色边加树路径是奇环，不应输出整个DFS访问序列。图保证连通，二分图与有奇环恰好二选一。

## Mountain

### 题意

借助等高滑索穿过一列山，最小化海拔累计上升与下降量。

### 思路

设最高山高 H。必然至少到达 H：不能在低于 H 的高度直接越过这座更高的山。起终点都为零，因此累计变化至少 2H。上界也可实现：向最高山前进时，每次从当前山顶滑到右边第一座不低于它的山，途中山都不高于滑索，符合条件；这样海拔只升不降。越过最高山后，按反方向同样构造单调下降路线。故答案恰为 2H。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, highest = 0;
    cin >> n;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        highest = max(highest, x);
    }
    cout << highest * 2;
    return 0;
}
```

### 复杂度

时间 $O(n)$，额外空间 $O(1)$。

### 易错点

幅度在这里按题目所求的累计海拔变化理解，单座高 H 的山需要上升 H 再下降 H。无需真的计算滑索端点。

## 1408

### 题意

两种颜色各含1到n的球，最少相邻交换让各自编号递增。

### 思路

合法结果是白球递增序列和黑球递增序列的任意交错。构造最终顺序，每次只能选下一白球或下一黑球。将它从原序列尚未取出的部分移到最前，需要交换的次数就是它前面剩余球数；逐次这样抽取恰好计算该最终顺序相对原序列的逆序数。

dp[i][j]为取走前i个白球、前j个黑球的最小代价。白i的同色贡献固定为“原来在它前面且编号更大的白球数”，异色贡献为前面编号大于j的黑球数。黑球同理。外层递增i时，维护每个黑球前仍未取的球数；内层递增j时滚动扣除已取黑球对白i的贡献。于是每个状态常数时间，dp只保留一行。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> white(n + 1), black(n + 1);
    for (int p = 0; p < 2 * n; p++) {
        char color;
        int label;
        cin >> color >> label;
        (color == 'W' ? white : black)[label] = p;
    }
    vector<int> fixedWhite(n + 1), blackCost(n + 1);
    for (int i = 1; i <= n; i++) {
        for (int j = i + 1; j <= n; j++) {
            fixedWhite[i] += white[j] < white[i];
            blackCost[i] += black[j] < black[i];
        }
        for (int j = 1; j <= n; j++)
            blackCost[i] += white[j] < black[i];
    }
    vector<long long> dp(n + 1);
    for (int j = 1; j <= n; j++)
        dp[j] = dp[j - 1] + blackCost[j];
    for (int i = 1; i <= n; i++) {
        int whiteCost = fixedWhite[i];
        for (int j = 1; j <= n; j++) {
            whiteCost += black[j] < white[i];
            if (white[i] < black[j])
                blackCost[j]--;
        }
        long long old = dp[0];
        dp[0] = old + whiteCost;
        for (int j = 1; j <= n; j++) {
            whiteCost -= black[j] < white[i];
            old = dp[j];
            dp[j] = min(old + whiteCost, dp[j - 1] + blackCost[j]);
        }
    }
    cout << dp[n];
    return 0;
}
```

### 复杂度

时间 $O(n^2)$，空间 $O(n)$。

### 易错点

同色编号顺序固定，只有两色之间的交错可选。向右更新时dp[j]仍是上一行，dp[j−1]已经是当前行。

## 可持久化动态图上树状数组维护01背包

### 题意

删除当前位置 i 的元素付出 a[i]i，后面的下标减一，求总费用最小值。

### 思路

原来第 i 个元素删除时的位置一定在一到 i 之间。正数的最小贡献不小于 a[i]，负数的最小贡献不小于 i*a[i]。这组逐项下界能同时实现：先从右往左删所有负数，它们前面的原元素全都还在，下标正好是原 i；再从左往右删非负数，每次下标都是一。因此把负数乘原下标、非负数原值直接求和即可。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    long long answer = 0;
    for (long long i = 1; i <= n; i++) {
        long long x;
        cin >> x;
        answer += x < 0 ? x * i : x;
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n)$，额外空间 $O(1)$。

### 易错点

负数希望在更大的下标删除，不能把所有元素都从左到右删。标题中列出的数据结构并非解题所需。

## 最后的晚餐(dinner)

### 题意

n对情侣围圆桌而坐，任何一对不相邻，旋转视为相同，n至三千万。

### 思路

n≥2时，容斥选k对必须相邻，把每对合成块并考虑两种方向，得到c[n]=Σ(-2)^k*C(n,k)*(2n−k−1)!。直接算组合数会使用大数组，下面把此式化为常数空间递推。

同时定义直线排列计数l[n]=Σ(-2)^k*C(n,k)*(2n−k)!。为推导，记q=t(t−2)，用∫₀∞e^(−t)t^r dt=r!将两式分别写成c[n]=∫e^(−t)q^n/t、l[n]=∫e^(−t)q^n。对q^n及t*q^n分部积分，令B[n]=∫e^(−t)t*q^n，得到l[n]=2n*(B[n−1]−l[n−1])、B[n]=(2n+1)l[n]+2n*B[n−1]。再用c[n]=B[n−1]−2l[n−1]消去B，便有：

l[n]=2n*(c[n]+l[n−1])；c[n+1]=4n²*c[n]+2n(2n+1)*l[n−1]。

从形式容斥值c[1]=−1、l[0]=1开始滚动。c[1]只是递推初值；真实n=1仅两个人，必然相邻，答案单独输出0。每步都在模数下计算系数，再乘旧状态。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n == 1) {
        cout << 0;
        return 0;
    }
    constexpr long long mod = 1000000007;
    long long circle = mod - 1, previousLine = 1;
    for (long long i = 1; i < n; i++) {
        long long coefficientA = (4 * i % mod) * i % mod;
        long long coefficientB = (2 * i % mod) * ((2 * i + 1) % mod) % mod;
        long long nextCircle = (coefficientA * circle + coefficientB * previousLine) % mod;
        long long line = (2 * i % mod) * ((circle + previousLine) % mod) % mod;
        circle = nextCircle;
        previousLine = line;
    }
    cout << circle;
    return 0;
}
```

### 复杂度

时间 $O(n)$，空间 $O(1)$。

### 易错点

圆桌只把旋转视为相同，镜像仍不同。初值−1是代数辅助量，不是n=1的实际方案数。4n²先取模，再乘状态，避免溢出。

## [AHOI2005]SHUFFLE 洗牌

### 题意

偶数张牌进行M次交错洗牌，求最终第L张的原编号。

### 思路

原位置i在前半叠时进入2i，后半叠时进入2i−N−1，统一为2i mod(N+1)。因此M次后原位置乘2^M。题目反查最终位置L的来源，应乘逆置换：N+1为奇数，2的逆元是(N+2)/2。答案L*((N+2)/2)^M mod(N+1)。N+1未必为素数，这个显式逆元仍成立。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, l;
    cin >> n >> m >> l;
    long long mod = n + 1, base = (n + 2) / 2, inversePower = 1;
    while (m) {
        if (m & 1)
            inversePower = (__int128)inversePower * base % mod;
        base = (__int128)base * base % mod;
        m >>= 1;
    }
    cout << (long long)((__int128)l * inversePower % mod);
    return 0;
}
```

### 复杂度

时间 $O(\log(M+1))$，空间 $O(1)$。

### 易错点

问的是最终位置的牌面，方向要取逆。乘积可达10^20，使用128位中间乘法。M=0自然输出L。

## [AHOI2009]CHESS 中国象棋

### 题意

棋盘上任意放若干中国象棋炮，使任何两炮不能隔恰好一炮互攻。

### 思路

同一行或列若至少三炮，其中按位置相邻的第一、第三炮恰有一个炮架，必互攻；反之每行每列至多两炮就安全。逐行放置，每行只放0、1、2炮。dp[one][two]记录已有one列放一炮、two列放两炮的方案，剩余empty列无炮。

放一炮可选空列（empty种）或一炮列（one种）；放两炮有两空列、空列加一炮列、两一炮列三类，组合系数分别C(empty,2)、empty*one、C(one,2)。两炮列不能再放。按类型更新列计数并乘选择数，最后对全部列状态求和，含全空棋盘。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    const long long mod = 9999973;
    vector<vector<long long>> dp(m + 1, vector<long long>(m + 1));
    dp[0][0] = 1;
    for (int r = 0; r < n; r++) {
        vector<vector<long long>> next(m + 1, vector<long long>(m + 1));
        for (int one = 0; one <= m; one++)
            for (int two = 0; one + two <= m; two++)
                if (dp[one][two]) {
                    int empty = m - one - two;
                    long long ways = dp[one][two];
                    auto add = [&](int a, int b, long long choices) {
                        next[a][b] = (next[a][b] + ways * choices) % mod;
                    };
                    add(one, two, 1);
                    if (empty)
                        add(one + 1, two, empty);
                    if (one)
                        add(one - 1, two + 1, one);
                    if (empty >= 2)
                        add(one + 2, two, 1LL * empty * (empty - 1) / 2);
                    if (empty && one)
                        add(one, two + 1, 1LL * empty * one);
                    if (one >= 2)
                        add(one - 2, two + 2, 1LL * one * (one - 1) / 2);
                }
        dp.swap(next);
    }
    long long answer = 0;
    for (auto &row : dp)
        for (long long x : row)
            answer = (answer + x) % mod;
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(NM^2)$，空间 $O(M^2)$。

### 易错点

两炮同一行但中间没有炮架时不互攻，所以不能误用普通车的每行每列最多一个。模数为9999973。

## [CQOI2007]涂色PAINT

### 题意

一次可把任意连续段刷成同色，后刷覆盖前刷，求达到目标的最少次数。

### 思路

dp[l][r]为从空白刷出目标区间的最少次数。先考虑单独刷l，代价1+dp[l+1][r]。若某个k>l与l同色，可让刷到k的那一笔同时覆盖l，再单独修复中间[l+1,k−1]，代价dp[l+1][k−1]+dp[k][r]。枚举所有同色k取最小，空区间代价0，按长度递增计算。这样的合并对应最优方案中最后留下l颜色的那笔所覆盖的后续同色位置。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    cin >> s;
    int n = s.size();
    vector<vector<int>> dp(n, vector<int>(n));
    for (int l = n - 1; l >= 0; l--) {
        dp[l][l] = 1;
        for (int r = l + 1; r < n; r++) {
            dp[l][r] = 1 + dp[l + 1][r];
            for (int k = l + 1; k <= r; k++)
                if (s[k] == s[l])
                    dp[l][r] = min(dp[l][r], (k == l + 1 ? 0 : dp[l + 1][k - 1]) + dp[k][r]);
        }
    }
    cout << dp[0][n - 1];
    return 0;
}
```

### 复杂度

时间 $O(n^3)$，空间 $O(n^2)$。

### 易错点

颜色可以覆盖，不能只统计相邻色块数。刷同色两端时，中间可以先被一起刷后再重刷。

## [CQOI2007]矩形RECT

### 题意

沿格线把矩形分成两个均连通、均接触原边界的非空部分，求不区分两部分的方案数。

### 思路

两部分都连通且都碰外边界时，它们之间的分界线必须是一条从外边界到外边界、不自交的简单格线路径。闭环会把一块包在内部；多条分界弧会让某一块分裂。因此可枚举这条线：两个端点在边界非角点，中间仅经过内部格点，每个内部格点至多一次。每条这样的弧恰好分出两块合法区域。

把内部格点建四邻接图。boundary[u]记录它有几个外边界邻点，作为进入或离开端点的选择数。枚举起始内部点，DFS不重复内部点，随时按boundary[当前]计结束方案。起点未走时要排除“从同一端点进出”，贡献为b*(b−1)。最终除二去掉路径的两个方向。左右、上下反射对称的起点只算一个，再乘轨道大小，减少重复搜索。若一边宽度为1，只有逐条直线切割，答案a*b−1。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a, b;
    cin >> a >> b;
    if (a == 1 || b == 1) {
        cout << a * b - 1;
        return 0;
    }
    int rows = a - 1, cols = b - 1, n = rows * cols;
    vector<unsigned long long> adjacent(n);
    vector<int> boundary(n);
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++) {
            int u = r * cols + c;
            boundary[u] = (r == 0) + (r + 1 == rows) + (c == 0) + (c + 1 == cols);
            if (r)
                adjacent[u] |= 1ULL << (u - cols);
            if (r + 1 < rows)
                adjacent[u] |= 1ULL << (u + cols);
            if (c)
                adjacent[u] |= 1ULL << (u - 1);
            if (c + 1 < cols)
                adjacent[u] |= 1ULL << (u + 1);
        }
    auto dfs = [&](auto &&self, int u, unsigned long long used) -> long long {
        long long count = boundary[u];
        unsigned long long next = adjacent[u] & ~used;
        while (next) {
            int v = __builtin_ctzll(next);
            next &= next - 1;
            count += self(self, v, used | (1ULL << v));
        }
        return count;
    };
    long long oriented = 0;
    for (int r = 0; r <= (rows - 1) / 2; r++)
        for (int c = 0; c <= (cols - 1) / 2; c++) {
            int u = r * cols + c;
            if (!boundary[u])
                continue;
            int symmetry = (r == rows - 1 - r ? 1 : 2) * (c == cols - 1 - c ? 1 : 2);
            oriented += symmetry * boundary[u] * (dfs(dfs, u, 1ULL << u) - 1);
        }
    cout << oriented / 2;
    return 0;
}
```

### 复杂度

内部格点数 $V=(a-1)(b-1)\le30$，时间为简单路径枚举的指数级，可界为 $O(V3^V)$，栈及图空间 $O(V)$。

### 易错点

枚举的是格线交点，不是单元格染色。边界只能作为首尾，不能沿外边界继续走；路径方向不构成不同划分。

## [CQOI2009]中位数图

### 题意

1到n的排列，统计奇数长度连续段中位数为b的数量。

### 思路

b只出现一次，合格区间必含其位置p。将大于b的数记+1、小于b记−1，b记0，中位数为b恰是区间总和0，因为左右两类数量相等，也自然保证总长度为奇数。枚举从p往左扩展的平衡值，统计各值出现次数（含只留p的平衡0）；再从p向右扩展，当前平衡为x时，左侧需−x，将其频次加入答案。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, b;
    cin >> n >> b;
    vector<int> a(n);
    int position = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        if (a[i] == b)
            position = i;
    }
    vector<long long> count(2 * n + 1);
    count[n] = 1;
    int balance = 0;
    for (int i = position - 1; i >= 0; i--) {
        balance += a[i] > b ? 1 : -1;
        count[n + balance]++;
    }
    long long answer = count[n];
    balance = 0;
    for (int i = position + 1; i < n; i++) {
        balance += a[i] > b ? 1 : -1;
        answer += count[n - balance];
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间、空间均为 $O(n)$。

### 易错点

只统计平衡0，不要套用下中位数计数中的平衡0或1。先将空左侧计一次，避免漏掉从b开始的区间。

## [CQOI2010]扑克牌

### 题意

n 种普通牌与 m 张百搭牌，每套至多用一张百搭，最多组成多少套。

### 思路

若要组成 x 套，第 i 类普通牌的缺口为 max(0,x-c[i])，总缺口 need 必须不超过百搭总数 m，也必须不超过套数 x，因为每套至多一张百搭。条件也充分：给每个缺口安排不同的套，所有缺口总数不超过 x，不会让一套出现两个百搭；余下位置用对应普通牌填满。判定对 x 单调，可二分最大可行值。上界为所有牌数除以 n。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long m;
    cin >> n >> m;
    vector<long long> count(n);
    long long total = m;
    for (auto &x : count) {
        cin >> x;
        total += x;
    }
    auto possible = [&](long long sets) {
        long long need = 0;
        for (long long x : count) {
            need += max(0LL, sets - x);
            if (need > m || need > sets)
                return false;
        }
        return true;
    };
    long long low = 0, high = total / n;
    while (low < high) {
        long long mid = low + (high - low + 1) / 2;
        if (possible(mid))
            low = mid;
        else
            high = mid - 1;
    }
    cout << low;
    return 0;
}
```

### 复杂度

最大可能套数为 $U$，时间 $O(n\log(U+1))$，空间 $O(n)$。

### 易错点

只比较缺口与 m 不够，还要比较缺口与套数；同一套中不能用两张 Joker。所有总量使用 long long。

## [CQOI2013]新数独

### 题意

只有相邻格大小关系的数独，要求每行、列、宫均为1到9排列，输出唯一解。

### 思路

每格保存九位候选集，初始为1到9。将全部大小关系统一为a<b。传播两类约束：已确定格的数字从同行、同列、同宫的其他格删除；每个排列单位内，某数字若只剩一个可放位置就强制放入。对a<b，删除a中不小于b最大候选的值，并删除b中不大于a最小候选的值。反复传播直到没有变化，任何候选集为空或某单位某数字无处可放就判矛盾。

若仍未填完，选候选数最少且多于一个的格，逐一固定候选后递归。每个分支复制候选数组，回退无需逐项撤销。传播仅删除已经不可能的值，分支枚举其余全部值，因此保持完备性。输入按每个宫带的五行读取：横、竖、横、竖、横。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<array<int, 9>> units;
    for (int r = 0; r < 9; r++) {
        array<int, 9> row{}, column{}, block{};
        for (int j = 0; j < 9; j++) {
            row[j] = r * 9 + j;
            column[j] = j * 9 + r;
            block[j] = (r / 3 * 3 + j / 3) * 9 + r % 3 * 3 + j % 3;
        }
        units.push_back(row);
        units.push_back(column);
        units.push_back(block);
    }
    vector<pair<int, int>> less;
    for (int band = 0; band < 3; band++)
        for (int local = 0; local < 3; local++) {
            int r = band * 3 + local;
            for (int box = 0; box < 3; box++)
                for (int j = 0; j < 2; j++) {
                    char sign;
                    cin >> sign;
                    int a = r * 9 + box * 3 + j, b = a + 1;
                    less.push_back(sign == '<' ? make_pair(a, b) : make_pair(b, a));
                }
            if (local < 2)
                for (int c = 0; c < 9; c++) {
                    char sign;
                    cin >> sign;
                    int a = r * 9 + c, b = a + 9;
                    less.push_back(sign == '^' ? make_pair(a, b) : make_pair(b, a));
                }
        }
    auto propagate = [&](array<int, 81> &domain) {
        bool changed = true;
        while (changed) {
            changed = false;
            for (auto &unit : units) {
                for (int p : unit) {
                    int mask = domain[p];
                    if (!mask)
                        return false;
                    if ((mask & (mask - 1)) == 0)
                        for (int q : unit)
                            if (p != q && (domain[q] & mask)) {
                                domain[q] &= ~mask;
                                if (!domain[q])
                                    return false;
                                changed = true;
                            }
                }
                for (int digit = 0; digit < 9; digit++) {
                    int position = -1, count = 0;
                    for (int p : unit)
                        if (domain[p] >> digit & 1) {
                            position = p;
                            count++;
                        }
                    if (!count)
                        return false;
                    if (count == 1 && domain[position] != (1 << digit)) {
                        domain[position] = 1 << digit;
                        changed = true;
                    }
                }
            }
            for (auto [a, b] : less) {
                if (!domain[a] || !domain[b])
                    return false;
                int maxB = 31 - __builtin_clz((unsigned)domain[b]);
                int nextA = domain[a] & ((1 << maxB) - 1);
                if (!nextA)
                    return false;
                if (nextA != domain[a]) {
                    domain[a] = nextA;
                    changed = true;
                }
                int minA = __builtin_ctz((unsigned)domain[a]);
                int nextB = domain[b] & ~((1 << (minA + 1)) - 1);
                if (!nextB)
                    return false;
                if (nextB != domain[b]) {
                    domain[b] = nextB;
                    changed = true;
                }
            }
        }
        return true;
    };
    array<int, 81> answer{};
    auto dfs = [&](auto &&self, array<int, 81> domain) -> bool {
        if (!propagate(domain))
            return false;
        int selected = -1, fewest = 10;
        for (int p = 0; p < 81; p++) {
            int count = __builtin_popcount((unsigned)domain[p]);
            if (count > 1 && count < fewest) {
                selected = p;
                fewest = count;
            }
        }
        if (selected == -1) {
            answer = domain;
            return true;
        }
        int options = domain[selected];
        while (options) {
            int bit = options & -options;
            options ^= bit;
            domain[selected] = bit;
            if (self(self, domain))
                return true;
        }
        return false;
    };
    array<int, 81> initial;
    initial.fill(511);
    dfs(dfs, initial);
    for (int r = 0; r < 9; r++)
        for (int c = 0; c < 9; c++)
            cout << (__builtin_ctz((unsigned)answer[r * 9 + c]) + 1) << (c == 8 ? '\n' : ' ');
    return 0;
}
```

### 复杂度

固定81格，最坏仍为指数搜索。每次传播至少删除一个候选，共至多729次删除，单次扫描至多 $O(27\cdot9^2+108)$；递归栈保存至多81个候选数组。

### 易错点

v表示上格大于下格，^表示上格小于下格；只给每宫内部的相邻关系，不存在跨宫的额外符号。候选集用0到8位代表数字1到9。

## [CQOI2016]手机号码

> 原题：[P4124](https://www.luogu.com.cn/problem/P4124)
> 解法：把相邻重复长度、出现过三连与四八标记分开记 · C++17

### 题意

统计十一位无前导零手机号，要求出现至少三个相邻相同数字，并且不能同时出现四和八。



### 思路



![三个实际十一位号码分别展示三连成功、四八冲突和从未形成三连；换数字不清除已经成功的标记。](data:image/svg+xml;base64,)

固定十一位从高到低填，首位只能一至九。状态保存前一个数字、末尾连续相同长度（封顶三）、是否已经出现过三连、四八出现掩码和上界关系。新数字更新这些量，四和八同时出现就丢弃；末尾只要求曾有三连，不要求三连正好在末尾。前缀F(R)减F(L减一)，短于十一位的前缀为零。

设长度为D、数码数为十，时间 $O(D\cdot10\cdot4\cdot2\cdot4\cdot10)$，空间为同一状态量级去掉最后一个枚举十。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long l, r;
    cin >> l >> r;
    auto prefix = [&](long long x) {
        if (x < 10000000000LL)
            return 0LL;
        string digits = to_string(x);
        long long memo[12][11][4][2][4];
        memset(memo, -1, sizeof(memo));
        function<long long(int, int, int, bool, int, bool)> dfs =
            [&](int pos, int previous, int run, bool found, int seen, bool tight) -> long long {
            if (pos == 11)
                return found;
            long long &saved = memo[pos][previous][run][found][seen];
            if (!tight && saved >= 0)
                return saved;
            long long result = 0;
            int limit = tight ? digits[pos] - '0' : 9;
            for (int d = (pos == 0 ? 1 : 0); d <= limit; d++) {
                int nextSeen = seen | (d == 4 ? 1 : 0) | (d == 8 ? 2 : 0);
                if (nextSeen == 3)
                    continue;
                int nextRun = d == previous ? min(3, run + 1) : 1;
                result +=
                    dfs(pos + 1, d, nextRun, found || nextRun == 3, nextSeen, tight && d == limit);
            }
            if (!tight)
                saved = result;
            return result;
        };
        return dfs(0, 10, 0, false, 0, true);
    };
    cout << prefix(r) - prefix(l - 1) << '\n';
    return 0;
}
```

### 易错点

固定十一位；首位非零；三连出现后永久保留；run封顶三即可；四和八各自可出现；两者同时出现才拒绝；下界减一可能短一位。

## [HAOI2006]受欢迎的牛

### 题意

有向关系可传递，统计所有点都能到达的点数。

### 思路

缩点DAG中，若有两个不同出度0分量，它们无法彼此到达，无人能被全体到达。若恰有一个汇分量，DAG中任一点沿出边最终必到某个汇，故全部会到这个唯一汇。答案就是该SCC大小。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

pair<int, vector<int>> components(const vector<vector<int>> &graph,
                                  const vector<vector<int>> &reverse) {
    int n = graph.size();
    vector<bool> seen(n);
    vector<int> finish;
    for (int start = 0; start < n; start++)
        if (!seen[start]) {
            vector<pair<int, int>> stack{{start, 0}};
            seen[start] = true;
            while (!stack.empty()) {
                int u = stack.back().first, &position = stack.back().second;
                if (position == (int)graph[u].size()) {
                    finish.push_back(u);
                    stack.pop_back();
                } else {
                    int v = graph[u][position++];
                    if (!seen[v]) {
                        seen[v] = true;
                        stack.push_back({v, 0});
                    }
                }
            }
        }
    vector<int> component(n, -1);
    int count = 0;
    for (int i = n - 1; i >= 0; i--) {
        int start = finish[i];
        if (component[start] != -1)
            continue;
        vector<int> stack{start};
        component[start] = count;
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            for (int v : reverse[u])
                if (component[v] == -1) {
                    component[v] = count;
                    stack.push_back(v);
                }
        }
        count++;
    }
    return {count, component};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> graph(n), reverse(n);
    while (m--) {
        int u, v;
        cin >> u >> v;
        u--;
        v--;
        graph[u].push_back(v);
        reverse[v].push_back(u);
    }
    auto [count, component] = components(graph, reverse);
    vector<int> size(count), out(count);
    for (int u = 0; u < n; u++) {
        size[component[u]]++;
        for (int v : graph[u])
            if (component[u] != component[v])
                out[component[u]]++;
    }
    int target = -1;
    for (int c = 0; c < count; c++)
        if (!out[c]) {
            if (target >= 0) {
                cout << 0;
                return 0;
            }
            target = c;
        }
    cout << size[target];
    return 0;
}
```

### 复杂度

时间、空间均 $O(n+m)$。

### 易错点

所求是所有点都能到它，关注汇分量，而不是入度0源分量。重复边不影响是否为0。

## [HAOI2006]聪明的猴子

### 题意

不同猴子有不同跳距，判断有多少能在全部树冠间来回觅食。

### 思路

跳距d可觅食全部树，等价于只保留长度≤d的树冠连边后图连通。完整欧氏图的任一最小生成树，其最大边长是所有生成树中最小的瓶颈；故只需求MST的最大边，再比较每只猴子跳距。N≤1000，使用稠密Prim，不显式存百万条边。全程比较平方距离，无需浮点开根。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m;
    cin >> m;
    vector<long long> jump(m);
    for (auto &x : jump)
        cin >> x;
    int n;
    cin >> n;
    vector<array<long long, 2>> point(n);
    for (auto &p : point)
        cin >> p[0] >> p[1];
    vector<long long> best(n, 1LL << 60);
    vector<bool> used(n);
    best[0] = 0;
    long long threshold = 0;
    for (int step = 0; step < n; step++) {
        int u = -1;
        for (int v = 0; v < n; v++)
            if (!used[v] && (u == -1 || best[v] < best[u]))
                u = v;
        used[u] = true;
        threshold = max(threshold, best[u]);
        for (int v = 0; v < n; v++)
            if (!used[v]) {
                long long dx = point[u][0] - point[v][0], dy = point[u][1] - point[v][1];
                best[v] = min(best[v], dx * dx + dy * dy);
            }
    }
    int answer = 0;
    for (long long d : jump)
        answer += d * d >= threshold;
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(N^2+M)$，空间 $O(N+M)$。

### 易错点

只要求可经中间树冠到所有树，不要求一跳到任意树。比较MST最大边，不是MST总长或最远两树距离。

## [HAOI2008]木棍分割

### 题意

最多m刀分木棍，最小最长段长度并统计全部最优切法。

### 思路

先二分最大段长X，贪心从左向右尽量装满一段，所得段数最少；若≤m+1则可行。求得最优X后计数：dp[k][i]为前i根分成恰k个非空段且段长都≤X的方案数，转移Σdp[k−1][j]，其中prefix[i]−prefix[j]≤X、j<i。

长度正数使合法j形成移动窗口，维护上一行DP窗口和，每层O(n)。答案是k=1..m+1的dp[k][n]之和，因为允许最多m刀，最优切法不一定刀数相同。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<long long> prefix(n + 1);
    long long low = 0;
    for (int i = 1; i <= n; i++) {
        int x;
        cin >> x;
        prefix[i] = prefix[i - 1] + x;
        low = max(low, (long long)x);
    }
    long long high = prefix[n];
    auto feasible = [&](long long limit) {
        int groups = 1;
        long long sum = 0;
        for (int i = 1; i <= n; i++) {
            long long x = prefix[i] - prefix[i - 1];
            if (sum + x > limit) {
                groups++;
                sum = 0;
            }
            sum += x;
        }
        return groups <= m + 1;
    };
    while (low < high) {
        long long mid = (low + high) / 2;
        if (feasible(mid))
            high = mid;
        else
            low = mid + 1;
    }
    const int mod = 10007;
    vector<int> previous(n + 1), current(n + 1);
    previous[0] = 1;
    int answer = 0;
    for (int groups = 1; groups <= m + 1; groups++) {
        fill(current.begin(), current.end(), 0);
        int left = 0, sum = 0;
        for (int i = 1; i <= n; i++) {
            sum = (sum + previous[i - 1]) % mod;
            while (prefix[i] - prefix[left] > low) {
                sum = (sum - previous[left] + mod) % mod;
                left++;
            }
            current[i] = sum;
        }
        answer = (answer + current[n]) % mod;
        previous.swap(current);
    }
    cout << low << ' ' << answer;
    return 0;
}
```

### 复杂度

时间 $O(n\log(\sum L)+nm)$，空间 $O(n)$。

### 易错点

不能只统计恰好m刀；样例最优长度10既有一刀也有两刀，共2种。

## [HAOI2008]移动玩具

> 原题：[P4289](https://www.luogu.com.cn/problem/P4289)
> 解法：十六位掩码保存玩具布局，BFS 搜索交换空位 · C++17

### 题意

四乘四棋盘上的玩具完全相同，一步把某个玩具移到四邻空格，求从初始布局到目标布局的最少步数。



### 思路

用十六位整数记录哪些格有玩具。每步选一位一与相邻的一位零，把两位同时翻转得到新布局。每种布局是一个状态，移动代价一，用 BFS 首次到目标即最少次数。玩具相同，不要为每个玩具另编号增加状态。

![圆点表示玩具，空格表示空位；它从编号零移到编号一，其余十四格与玩具总数都不变。](data:image/svg+xml;base64,)

圆点表示玩具，空格表示空位；它从编号零移到编号一，其余十四格与玩具总数都不变。

状态数至多 $2^{16}$，时间 $O(16\cdot2^{16})$、空间 $O(2^{16})$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int start = 0, target = 0, start_count = 0, target_count = 0;
    char c;
    for (int i = 0; i < 16; i++) {
        cin >> c;
        if (c == '1') {
            start |= 1 << i;
            ++start_count;
        }
    }
    for (int i = 0; i < 16; i++) {
        cin >> c;
        if (c == '1') {
            target |= 1 << i;
            ++target_count;
        }
    }
    if (start_count != target_count) {
        cout << -1 << '\n';
        return 0;
    }
    vector<int> distance(1 << 16, -1);
    queue<int> todo;
    todo.push(start);
    distance[start] = 0;
    int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    while (!todo.empty()) {
        int state = todo.front();
        todo.pop();
        if (state == target) {
            cout << distance[state] << '\n';
            return 0;
        }
        for (int p = 0; p < 16; p++)
            if (state & (1 << p))
                for (int d = 0; d < 4; d++) {
                    int r = p / 4 + dr[d], col = p % 4 + dc[d];
                    if (r < 0 || r >= 4 || col < 0 || col >= 4)
                        continue;
                    int q = r * 4 + col;
                    if (state & (1 << q))
                        continue;
                    int next = state ^ (1 << p) ^ (1 << q); // 一位搬空，另一空位放入，玩具数不变。
                    if (distance[next] == -1) {
                        distance[next] = distance[state] + 1;
                        todo.push(next);
                    }
                }
    }
    cout << -1 << '\n';
    return 0;
}
```

### 易错点

同种玩具只记录占用，不编号；必须四向相邻；异或翻转的一位原本为一、另一位原本为零。

## [HAOI2010]最长公共子序列

### 题意

求LCS长度及匹配方案数模一亿。

### 思路

长度f[i][j]按标准LCS求。计数g[i][j]汇总所有达到该长度的来源：若末字符相同，加入对角子问题的匹配方案；若上方或左方长度也等于当前最优，分别加入它们。上、左共有的对角方案若长度同样最优，要减去一次避免重复。空前缀的空匹配计数为1。

这里计数按两串中选取的位置区分。样例最长长度4，不同字面字符串只有5种，但有7组位置匹配，所以不能用“不同LCS字符串”算法代替。滚动两行保存长度和计数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string a, b;
    cin >> a >> b;
    if (!a.empty() && a.back() == '.')
        a.pop_back();
    if (!b.empty() && b.back() == '.')
        b.pop_back();
    int n = a.size(), m = b.size();
    const int mod = 100000000;
    vector<int> previousLength(m + 1), currentLength(m + 1), previousCount(m + 1, 1),
        currentCount(m + 1, 1);
    for (int i = 1; i <= n; i++) {
        currentLength[0] = 0;
        currentCount[0] = 1;
        for (int j = 1; j <= m; j++) {
            int best = max(previousLength[j], currentLength[j - 1]);
            if (a[i - 1] == b[j - 1])
                best = max(best, previousLength[j - 1] + 1);
            long long count = 0;
            if (a[i - 1] == b[j - 1] && previousLength[j - 1] + 1 == best)
                count += previousCount[j - 1];
            if (previousLength[j] == best)
                count += previousCount[j];
            if (currentLength[j - 1] == best)
                count += currentCount[j - 1];
            if (previousLength[j - 1] == best)
                count -= previousCount[j - 1];
            currentLength[j] = best;
            currentCount[j] = (count % mod + mod) % mod;
        }
        previousLength.swap(currentLength);
        previousCount.swap(currentCount);
    }
    cout << previousLength[m] << '\n' << previousCount[m];
    return 0;
}
```

### 复杂度

时间 $O(nm)$，空间 $O(m)$。

### 易错点

字符串末尾点号是终止符，不能参与LCS。减法后取非负模；空LCS有一种空匹配。

## [HAOI2011]PROBLEM A

### 题意

每人声称比自己高、低分人数，最少说谎人数。

### 思路

声称(a,b)的人若说真话，其所在同分组占据排序名次[a+1,n−b]，长度为n−a−b。相同声明可同时为真，但至多选该长度的人数，权重为min(声明次数,区间长度)。不同真实同分组的名次区间必须互不重叠。

因此合并相同声明后，变成带权区间调度：dp[r]为前r个名次最多真实人数，dp[r]先继承dp[r−1]，再对所有以r结束的组更新dp[l−1]+weight。未选名次由说谎者补齐，不影响已选组。答案n−dp[n]。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    map<pair<int, int>, int> count;
    for (int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        if (a + b < n)
            count[{a + 1, n - b}]++;
    }
    vector<vector<pair<int, int>>> ending(n + 1);
    for (auto [interval, frequency] : count) {
        auto [l, r] = interval;
        ending[r].push_back({l, min(frequency, r - l + 1)});
    }
    vector<int> dp(n + 1);
    for (int r = 1; r <= n; r++) {
        dp[r] = dp[r - 1];
        for (auto [l, w] : ending[r])
            dp[r] = max(dp[r], dp[l - 1] + w);
    }
    cout << n - dp[n];
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

a+b≥n时同分组长度非正，该声明必假。相同声明人数超过组大小，只能让其中一部分为真。

## [HAOI2012]ROAD

### 题意

对每条有向边统计它经过多少条任意起终点的不同最短路，模十亿加七。

### 思路

枚举起点s做Dijkstra，取出满足d[u]+w=d[v]的最短路DAG。正边权保证距离递增是拓扑序。prefix[u]为从s到u的最短路数，按正序相加；suffix[u]为从u出发、沿这个DAG到任意终点的路径数，包含终点就是u的空后缀，故suffix[u]=1+Σsuffix[v]，反序计算。

对DAG中的每条原边u→v，经过它且起点为s的最短路有prefix[u]*suffix[v]条：任选到u的最短前缀、这条边、从v起的后缀，因DAG不会重复点且整路均在最短路结构中，一一对应。对所有s累加。重边按不同原道路分别保留，符合道路序列区分路径的定义。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    struct Edge {
        int from, to, w;
    };
    vector<Edge> edges(m);
    vector<vector<int>> graph(n);
    for (int i = 0; i < m; i++) {
        auto &e = edges[i];
        cin >> e.from >> e.to >> e.w;
        --e.from;
        --e.to;
        graph[e.from].push_back(i);
    }
    const long long mod = 1000000007, inf = 1LL << 60;
    vector<long long> answer(m);
    for (int start = 0; start < n; start++) {
        vector<long long> distance(n, inf), prefix(n), suffix(n, 1);
        vector<int> order;
        priority_queue<pair<long long, int>, vector<pair<long long, int>>,
                       greater<pair<long long, int>>>
            heap;
        distance[start] = 0;
        heap.push({0, start});
        while (!heap.empty()) {
            auto [cost, u] = heap.top();
            heap.pop();
            if (cost != distance[u])
                continue;
            order.push_back(u);
            for (int id : graph[u]) {
                auto e = edges[id];
                if (distance[e.to] > cost + e.w) {
                    distance[e.to] = cost + e.w;
                    heap.push({distance[e.to], e.to});
                }
            }
        }
        prefix[start] = 1;
        for (int u : order)
            for (int id : graph[u]) {
                auto e = edges[id];
                if (distance[u] + e.w == distance[e.to])
                    prefix[e.to] = (prefix[e.to] + prefix[u]) % mod;
            }
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            for (int id : graph[u]) {
                auto e = edges[id];
                if (distance[u] + e.w == distance[e.to]) {
                    suffix[u] = (suffix[u] + suffix[e.to]) % mod;
                    answer[id] = (answer[id] + prefix[u] * suffix[e.to]) % mod;
                }
            }
        }
    }
    for (long long x : answer)
        cout << x << '\n';
    return 0;
}
```

### 复杂度

时间 $O(n(n+m)\log n)$，空间 $O(n+m)$。

### 易错点

suffix必须加1，表示在当前点结束，不然会漏掉以v为终点的路径。只计算从当前s可达的DAG结点，边不是无向的。

## [HAOI2012]容易题(EASY)

### 题意

各位置可取1到n并排除指定值，求全部合法序列的乘积之和。

### 思路

由乘法分配律，所有序列的乘积之和等于各位置“允许值之和”的乘积。无约束位置的值和S=n(n+1)/2，共有m−不同受限位置数个，用S的快速幂一次处理。受限位置则从S减掉所有不同禁用值。把(x,y)排序去重，按x分组计算，避免重复限制重复扣减。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m;
    int k;
    cin >> n >> m >> k;
    vector<pair<long long, long long>> forbidden(k);
    for (auto &[x, y] : forbidden)
        cin >> x >> y;
    sort(forbidden.begin(), forbidden.end());
    forbidden.erase(unique(forbidden.begin(), forbidden.end()), forbidden.end());
    const long long mod = 1000000007;
    long long total = n * (n + 1) / 2 % mod, answer = 1, groups = 0;
    for (int i = 0; i < (int)forbidden.size();) {
        int j = i;
        long long allowed = total;
        while (j < (int)forbidden.size() && forbidden[j].first == forbidden[i].first) {
            allowed = (allowed - forbidden[j].second % mod + mod) % mod;
            j++;
        }
        answer = answer * allowed % mod;
        groups++;
        i = j;
    }
    long long exponent = m - groups, base = total;
    while (exponent) {
        if (exponent & 1)
            answer = answer * base % mod;
        base = base * base % mod;
        exponent >>= 1;
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(k\log k+\log m)$，空间 $O(k)$。

### 易错点

同一条限制可重复出现。某位置允许值之和模P为0时，直接让总乘积变0，无需做除法。

## [HAOI2012]音量调节

### 题意

每首歌前必须按指定幅度调高或调低，过程不越界，求最后最大音量。

### 思路

用布尔数组记录当前所有可达音量。初始只有begin。每个变化c从旧音量v分别转移到v−c、v+c，越界的不加入。用新数组替换，全部歌曲结束后从最大音量向下找首个可达者，没有则−1。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, begin, limit;
    cin >> n >> begin >> limit;
    vector<bool> can(limit + 1);
    can[begin] = true;
    while (n--) {
        int change;
        cin >> change;
        vector<bool> next(limit + 1);
        for (int v = 0; v <= limit; v++)
            if (can[v]) {
                if (v >= change)
                    next[v - change] = true;
                if (v + change <= limit)
                    next[v + change] = true;
            }
        can.swap(next);
    }
    int answer = -1;
    for (int v = limit; v >= 0; v--)
        if (can[v]) {
            answer = v;
            break;
        }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(nM)$，空间 $O(M)$。

### 易错点

每次必须调整，不能保留原音量作为“不操作”。更新必须基于上一首歌状态。

## [HAOI2015]树上染色

### 题意

恰染K个黑点，最大化黑黑距离和加白白距离和。

### 思路

按边计贡献。孩子子树大小s、其中黑点j时，经过父子边的同色点对数为 j*(K−j)+(s−j)*(N−K−s+j)，乘边长就是这条边对全局距离和的贡献。

树上背包dp[u][j]维护u子树恰有j黑点的最大内部边贡献，合并孩子时枚举其黑点数，把孩子dp及这条边的贡献加进来。子树计数还不能超过全局白点总数，非法状态设负无穷。黑白对称，先将K替成min(K,N−K)可缩小状态。点只初始化成黑或白，边的贡献在合并其下方子树时恰算一次。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Tree {
    vector<vector<pair<int, long long>>> edge;
    vector<int> parent, order;
    vector<long long> incoming;
    explicit Tree(int n) : edge(n), parent(n, -1), incoming(n) {}
    void add(int u, int v, long long w = 1) {
        edge[u].push_back({v, w});
        edge[v].push_back({u, w});
    }
    void root(int start) {
        order = {start};
        parent[start] = start;
        for (size_t i = 0; i < order.size(); i++) {
            int u = order[i];
            for (auto [v, w] : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    incoming[v] = w;
                    order.push_back(v);
                }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    k = min(k, n - k);
    Tree tree(n);
    for (int i = 1; i < n; i++) {
        int a, b;
        long long w;
        cin >> a >> b >> w;
        tree.add(a - 1, b - 1, w);
    }
    tree.root(0);
    const long long neg = -(1LL << 60);
    vector<int> size(n, 1);
    vector<vector<long long>> dp(n);
    for (int index = n - 1; index >= 0; index--) {
        int u = tree.order[index];
        dp[u].assign(min(k, 1) + 1, 0);
        for (auto [v, w] : tree.edge[u])
            if (v != tree.parent[u]) {
                int cap = min(k, size[u] + size[v]);
                vector<long long> next(cap + 1, neg);
                for (int a = 0; a < (int)dp[u].size(); a++)
                    if (dp[u][a] != neg)
                        for (int b = 0; b < (int)dp[v].size() && a + b <= cap; b++)
                            if (dp[v][b] != neg && size[u] + size[v] - a - b <= n - k) {
                                long long white = size[v] - b;
                                long long contribution =
                                    (1LL * b * (k - b) + white * (n - k - white)) * w;
                                next[a + b] = max(next[a + b], dp[u][a] + dp[v][b] + contribution);
                            }
                size[u] += size[v];
                dp[u].swap(next);
            }
    }
    cout << dp[0][k];
    return 0;
}
```

### 复杂度

按实际子树大小做卷积，全部分叉规模乘积合计 $O(n^2)$，时间 $O(n^2)$，空间上界 $O(nK)$。

### 易错点

只统计同色无序点对，不能把黑白点对算入。贡献公式用全局K与N−K，不能用当前已合并部分代替。

## [HEOI2014]南园满地堆轻絮

### 题意

将生成序列改为不下降，最小化单个音符的最大改变量。

### 思路

若 i<j 且 A[i]>A[j]，两端各最多改 d 后仍要不下降，必须有 A[i]-A[j]<=2d。因此最大前后下降量 drop 给出下界 ceil(drop/2)。它也充分：令 B[i]=max(1,所有 j<=i 的 A[j]-d)，这样 B 单调不降；当 d 已覆盖最大下降量时，B[i] 不超过 A[i]+d，也不低于 A[i]-d。初始音符为正，后续若生成零，最大下降量已经保证 d 至少为一，所以正整数下界也能满足。

只需流式生成序列、维护此前最大值与 drop，无须存五百万项或反复二分。多项式用秦九韶形式逐步取模，每个乘积都在 64 位范围内。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, sa, sb, sc, sd, first, mod;
    cin >> n >> sa >> sb >> sc >> sd >> first >> mod;
    auto f = [&](long long x) { return (((sa * x + sb) % mod * x + sc) % mod * x + sd) % mod; };
    long long previousPrevious = 0, previous = first, maximum = first, drop = 0;
    for (long long i = 2; i <= n; i++) {
        long long current = (f(previous) + f(previousPrevious)) % mod;
        drop = max(drop, maximum - current);
        maximum = max(maximum, current);
        previousPrevious = previous;
        previous = current;
    }
    cout << (drop + 1) / 2;
    return 0;
}
```

### 复杂度

时间 $O(n)$，额外空间 $O(1)$。

### 易错点

输入实际有七个数，题面“六个数”是笔误。给定的 A[1] 就是初始项，之后从 A[0]=0、A[1] 按递推生成。

## 牛妹和01串

### 题意

把整个零一串切为最多段，每段都至少有一个零和一个一。

### 思路

从左到右累积当前段出现过的数字，一旦零和一都出现，就立刻切一段并清空标记。任何合法第一段的终点都不会比这个最早位置更早，提前结束第一段会给后续留下更多字符，因此不会减少后面可切段数。末尾若只剩一种数字，把它并入上一段，不改变段数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    cin >> s;
    int mask = 0, answer = 0;
    for (char c : s) {
        mask |= 1 << (c - '0');
        if (mask == 3) {
            answer++;
            mask = 0;
        }
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(|s|)$，额外空间 $O(1)$。

### 易错点

必须覆盖全串，末尾剩余字符要并入已有最后一段。题目保证全串同时含零和一，所以至少可形成一段。

## 斐波那契

### 题意

n至10^18，求前n项斐波那契平方和模十亿加七。

### 思路

由F[i+1]−F[i−1]=F[i]，有F[i]²=F[i]F[i+1]−F[i−1]F[i]，相加后中间项抵消，平方和恰为F[n]F[n+1]。快速倍增同时求(F[k],F[k+1])：F[2k]=F[k]*(2F[k+1]−F[k])，F[2k+1]=F[k]²+F[k+1]²，再按n奇偶返回相邻两项，递归每次减半。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    unsigned long long n;
    cin >> n;
    const long long mod = 1000000007;
    auto fibonacci = [&](auto &&self, unsigned long long index) -> pair<long long, long long> {
        if (index == 0)
            return {0, 1};
        auto [a, b] = self(self, index / 2);
        long long c = a * ((2 * b - a + mod) % mod) % mod, d = (a * a + b * b) % mod;
        if (index % 2)
            return {d, (c + d) % mod};
        return {c, d};
    };
    auto [a, b] = fibonacci(fibonacci, n);
    cout << a * b % mod;
    return 0;
}
```

### 复杂度

时间、递归栈空间均为 $O(\log n)$。

### 易错点

斐波那契从F1=F2=1开始，公式中F0=0。模减法先加模数，乘法使用64位。

## 矩阵消除游戏

### 题意

矩阵k次选择行或列清零，最大得分。

### 思路

所有权值为正，重复清零不会再加分，结果只由选中的行、列集合决定。枚举行子集，先取得这些行全部权值；每列只计算未被选中行的剩余和，再选最大的k−行数列。k≥min(n,m)可直接清空所有行或所有列，答案为全矩阵和。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    vector<vector<long long>> a(n, vector<long long>(m));
    long long total = 0;
    for (auto &row : a)
        for (auto &x : row) {
            cin >> x;
            total += x;
        }
    if (k >= min(n, m)) {
        cout << total;
        return 0;
    }
    long long answer = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        int rows = __builtin_popcount((unsigned)mask);
        if (rows > k)
            continue;
        vector<long long> column(m);
        long long score = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                if (mask >> i & 1)
                    score += a[i][j];
                else
                    column[j] += a[i][j];
            }
        sort(column.rbegin(), column.rend());
        for (int j = 0; j < k - rows && j < m; j++)
            score += column[j];
        answer = max(answer, score);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(2^n(nm+m\log m))$，空间 $O(nm)$。

### 易错点

行列交点只计一次，选列时必须用删去所选行后的剩余列和。多余回合可重复清零，不会降低分数。

## 区区区间

### 题意

区间覆盖为k,k+1,...并查询区间和。

### 思路

对本次左端l，目标值可写为a[i]=i+b，其中b=k−l。因此懒标记只保存全局偏移b，不必给每个子区间另算首项。覆盖节点[L,R]后，区间和=(L+R+2b)*(R−L+1)/2。新覆盖直接替换旧标记；部分访问前把标记下传，子节点继续使用相同b。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SegmentTree {
    int n;
    vector<long long> sum, tag;
    vector<bool> marked;
    SegmentTree(const vector<long long> &a)
        : n((int)a.size() - 1), sum(4 * n + 4), tag(4 * n + 4), marked(4 * n + 4) {
        build(1, 1, n, a);
    }
    void build(int u, int l, int r, const vector<long long> &a) {
        if (l == r) {
            sum[u] = a[l];
            return;
        }
        int mid = (l + r) / 2;
        build(u * 2, l, mid, a);
        build(u * 2 + 1, mid + 1, r, a);
        sum[u] = sum[u * 2] + sum[u * 2 + 1];
    }
    void apply(int u, int l, int r, long long b) {
        sum[u] = (1LL * (l + r) + 2 * b) * (r - l + 1) / 2;
        marked[u] = true;
        tag[u] = b;
    }
    void push(int u, int l, int r) {
        if (!marked[u] || l == r)
            return;
        int mid = (l + r) / 2;
        apply(u * 2, l, mid, tag[u]);
        apply(u * 2 + 1, mid + 1, r, tag[u]);
        marked[u] = false;
    }
    void change(int u, int l, int r, int ql, int qr, long long b) {
        if (ql <= l && r <= qr) {
            apply(u, l, r, b);
            return;
        }
        push(u, l, r);
        int mid = (l + r) / 2;
        if (ql <= mid)
            change(u * 2, l, mid, ql, qr, b);
        if (qr > mid)
            change(u * 2 + 1, mid + 1, r, ql, qr, b);
        sum[u] = sum[u * 2] + sum[u * 2 + 1];
    }
    long long query(int u, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr)
            return sum[u];
        push(u, l, r);
        int mid = (l + r) / 2;
        long long result = 0;
        if (ql <= mid)
            result += query(u * 2, l, mid, ql, qr);
        if (qr > mid)
            result += query(u * 2 + 1, mid + 1, r, ql, qr);
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<long long> a(n + 1);
    for (int i = 1; i <= n; i++)
        cin >> a[i];
    SegmentTree tree(a);
    while (m--) {
        int op, l, r;
        cin >> op >> l >> r;
        if (op == 1) {
            long long k;
            cin >> k;
            tree.change(1, 1, n, l, r, k - l);
        } else
            cout << tree.query(1, 1, n, l, r) << '\n';
    }
    return 0;
}
```

### 复杂度

构建 $O(n)$，每次操作 $O(\log n)$，空间 $O(n)$。

### 易错点

偏移b可能为0或负数，必须独立保存“是否存在覆盖”的布尔标记，不能用tag==0判断。

## 装备合成

### 题意

两种配方分别消耗 (2,3) 与 (4,1) 件材料，最大化装备数量。

### 思路

假设共做 z 件，其中 q 件使用第二种配方，则材料用量为 2z+2q 与 3z-2q。因此 q 至少为 max(0,ceil((3z-y)/2))，至多为 min(z,floor((x-2z)/2))。先确保 x>=2z，再比较整数上下界是否相交即可判定。能做 z 件就能少做，二分最大 z，上界 min(x/2,y)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        long long x, y;
        cin >> x >> y;
        auto possible = [&](long long count) {
            if (2 * count > x)
                return false;
            long long lower = max(0LL, (3 * count - y + 1) / 2),
                      upper = min(count, (x - 2 * count) / 2);
            return lower <= upper;
        };
        long long low = 0, high = min(x / 2, y);
        while (low < high) {
            long long mid = low + (high - low + 1) / 2;
            if (possible(mid))
                low = mid;
            else
                high = mid - 1;
        }
        cout << low << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O(\log\min(x,y))$，额外空间 $O(1)$。

### 易错点

不能只看材料总数除五，配方需要满足两种材料各自的整数约束。例如 x=3、y=2 虽合计五件，却一件装备也做不了。

## [HNOI2003]激光炸弹

### 题意

用轴对齐、边长 r 的开正方形覆盖最多目标价值，同坐标价值累加。

### 思路

整数坐标的两个点若相差 r 就不能同时落在开区间内；一边能覆盖的恰是至多 r 个连续整数坐标。按 x 维护宽为 r 的竖条，把条内各点价值累计到 y 数组。竖条右移一格，移出一列并移入一列。每个竖条内，再用长度 r 的 y 滑动窗口求最大和。目标均非负，边缘不足 r 的窗口可向外延伸，不影响合法性。这样不必保存完整的五千平方前缀和表。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, radius;
    cin >> n >> radius;
    const int limit = 5000;
    vector<vector<pair<int, int>>> columns(limit + 1);
    int maxX = 0, maxY = 0;
    for (int i = 0; i < n; i++) {
        int x, y, value;
        cin >> x >> y >> value;
        columns[x].push_back({y, value});
        maxX = max(maxX, x);
        maxY = max(maxY, y);
    }
    vector<int> band(maxY + 1);
    auto change = [&](int x, int sign) {
        for (auto [y, value] : columns[x])
            band[y] += sign * value;
    };
    for (int x = 0; x <= min(maxX, radius - 1); x++)
        change(x, 1);
    int answer = 0;
    for (int x = 0; x <= maxX; x++) {
        if (x > 0) {
            change(x - 1, -1);
            if (x + radius - 1 <= maxX)
                change(x + radius - 1, 1);
        }
        int sum = 0;
        for (int y = 0; y <= maxY; y++) {
            sum += band[y];
            if (y >= radius)
                sum -= band[y - radius];
            answer = max(answer, sum);
        }
    }
    cout << answer;
    return 0;
}
```

### 复杂度

坐标上限为 $M=5000$，时间 $O(M^2+n)$，空间 $O(M+n)$。

### 易错点

同位置可能有多目标，必须累加。窗口含 r 个整数位置，不含 r+1 个；可以把正方形边放在半整数上来避开边界。

## [HNOI2004]宠物收养所

### 题意

宠物与领养人依次到来，异类按最近特点值匹配，同差优先较小值，累计不满意度。

### 思路

任意时刻等待者只会是一种类型。用 multiset 保存他们的特点值：新来者同类就加入；异类就找 lower_bound(x)，它是第一个不小于 x 的候选，再检查其前驱。最接近的值只可能是这两个，距离相同时取较小的前驱。配对后从集合中删掉被匹配的一项，累计距离并对一百万取模。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    multiset<long long> waiting;
    int kind = -1;
    long long answer = 0;
    while (n--) {
        int type;
        long long x;
        cin >> type >> x;
        if (waiting.empty() || type == kind) {
            kind = type;
            waiting.insert(x);
            continue;
        }
        auto right = waiting.lower_bound(x), chosen = right;
        if (right == waiting.end())
            chosen = prev(right);
        else if (right != waiting.begin()) {
            auto left = prev(right);
            if (x - *left <= *right - x)
                chosen = left;
        }
        answer = (answer + llabs(x - *chosen)) % 1000000;
        waiting.erase(chosen);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

同差时选较小特点值。集合为空时重新设置等待类型；没有配对的人或宠物不产生费用。

## 四舍五入

### 题意

最多四舍五入 t 次，每次只能处理小数部分，求最大的最终数并去除小数尾零。

### 思路

先找小数部分最靠左的至少为五的数字。直接在这里舍入，比先处理更右位置更有利。删去该位及其右侧，将前一位加一；若前一位变成五且还有机会，继续向左舍入。由于起点已经是最靠左的五以上数字，其左边小数位原来都不超过四，向左传递时不会遇到小数九的长进位；只有进到整数部分时，单独处理整数进位并结束。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long t;
    string s;
    cin >> n >> t >> s;
    int dot = s.find('.');
    if (dot < 0) {
        cout << s;
        return 0;
    }
    int p = dot + 1;
    while (p < (int)s.size() && s[p] < '5')
        p++;
    int cut = s.size();
    while (p < (int)s.size() && p > dot && s[p] >= '5' && t > 0) {
        t--;
        cut = p;
        if (p == dot + 1) {
            s.resize(dot);
            int j = (int)s.size() - 1;
            while (j >= 0 && s[j] == '9') {
                s[j] = '0';
                j--;
            }
            if (j >= 0)
                s[j]++;
            else
                s.insert(s.begin(), '1');
            cout << s;
            return 0;
        }
        s[p - 1]++;
        p--;
    }
    s.resize(cut);
    while (!s.empty() && s.back() == '0')
        s.pop_back();
    if (!s.empty() && s.back() == '.')
        s.pop_back();
    cout << s;
    return 0;
}
```

### 复杂度

每个字符最多向左处理一次，时间与字符串空间均为 $O(n)$，不按可能十亿次的 t 循环。

### 易错点

每次舍入只耗一次机会，之后新出现的五才需要再耗一次。整数中的末尾零不能删；代码只有在仍含小数点的分支删小数尾零。

## Tic-Tac-Toe

### 题意

只按是否存在三子连线判断井字棋结果，不检查正常轮流落子的合法性。

### 思路

分别检查三行、三列和两条对角线，共八条线。如果某条线的三个位置都是 A 或 B，就标记对应玩家获胜。两人都赢输出 invalid，只有 A 赢输出 Yes，只有 B 赢输出 No，否则 draw。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        char a[3][3];
        for (auto &row : a)
            for (char &c : row)
                cin >> c;
        bool winA = false, winB = false;
        auto check = [&](char x, char y, char z) {
            if (x == y && y == z) {
                if (x == 'A')
                    winA = true;
                if (x == 'B')
                    winB = true;
            }
        };
        for (int i = 0; i < 3; i++) {
            check(a[i][0], a[i][1], a[i][2]);
            check(a[0][i], a[1][i], a[2][i]);
        }
        check(a[0][0], a[1][1], a[2][2]);
        check(a[0][2], a[1][1], a[2][0]);
        cout << (winA && winB ? "invalid" : winA ? "Yes" : winB ? "No" : "draw") << '\n';
    }
    return 0;
}
```

### 复杂度

每组固定九格与八条线，时间与空间均为常数。

### 易错点

空格三个点连成线也不算获胜。题目明确允许一人连下多手，不能额外用棋子个数判 invalid。

## [HNOI2007]分裂游戏

### 题意

从瓶i取一豆，在更后j、k各加一豆，统计获胜首步。

### 思路

把每颗豆视为独立游戏子项，位于瓶i的豆可变成位于j、k的两个子项，因此sg[i]=mex{sg[j] xor sg[k]，i<j≤k}。从最后瓶向前计算。瓶i有p颗相同豆时，偶数份SG抵消，只在p为奇数时异或sg[i]。

枚举每个有豆的i及j、k，操作后的总异或为X xor sg[i] xor sg[j] xor sg[k]；为0就是获胜首步。按i、j、k升序枚举自然得到字典序首解，并统计全部三元组。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        cin >> n;
        vector<int> count(n), sg(n);
        for (int &x : count)
            cin >> x;
        for (int i = n - 1; i >= 0; i--) {
            set<int> reachable;
            for (int j = i + 1; j < n; j++)
                for (int k = j; k < n; k++)
                    reachable.insert(sg[j] ^ sg[k]);
            while (reachable.count(sg[i]))
                sg[i]++;
        }
        int total = 0;
        for (int i = 0; i < n; i++)
            if (count[i] % 2)
                total ^= sg[i];
        array<int, 3> first = {-1, -1, -1};
        int ways = 0;
        for (int i = 0; i < n; i++)
            if (count[i])
                for (int j = i + 1; j < n; j++)
                    for (int k = j; k < n; k++)
                        if ((total ^ sg[i] ^ sg[j] ^ sg[k]) == 0) {
                            if (!ways)
                                first = {i, j, k};
                            ways++;
                        }
        cout << first[0] << ' ' << first[1] << ' ' << first[2] << '\n' << ways << '\n';
    }
    return 0;
}
```

### 复杂度

每组 $O(n³\log n)$，空间 $O(n²)$ 临时mex集合。

### 易错点

同瓶豆不可区分，首步按三元组计数，不乘p[i]。j=k合法，会给同一瓶加两豆，SG异或抵消。

## [HNOI2008]玩具装箱TOY

### 题意

连续玩具分箱，箱内相邻玩具间隔一单位，费用为箱长与L之差的平方，求最少费用。

### 思路

令S[i]=前i件玩具长度和+i，分界在j后时，该箱长度为S[i]−S[j]−1。记x=S[i]−L−1，则dp[i]=x²+min(dp[j]+S[j]²−2S[j]x)。每个已求出的j是一条斜率−2S[j]、截距dp[j]+S[j]²的直线。S严格增加，所以斜率递减、查询x递增，可用单调凸壳线性完成。

直线斜率按非增顺序加入，查询横坐标非减。维护下凸壳：新线使末尾两线的交点顺序逆转时，删除中间线，交点顺序用交叉乘积精确比较。斜率相同时只保留截距更小者。查询时若第二条线不劣于第一条，就弹掉第一条；随着横坐标变大，它也不会重新更优。每条线至多进出队一次。代码用128位处理中间乘积，避免平方及交点比较溢出。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

using Wide = __int128;
struct MonotoneHull {
    struct Line {
        Wide slope, intercept;
        Wide at(Wide x) const { return slope * x + intercept; }
    };
    deque<Line> lines;
    void add(Wide slope, Wide intercept) {
        Line line{slope, intercept};
        while (!lines.empty() && lines.back().slope == slope) {
            if (lines.back().intercept <= intercept)
                return;
            lines.pop_back();
        }
        while (lines.size() >= 2) {
            auto a = lines[lines.size() - 2], b = lines.back();
            if ((b.intercept - a.intercept) * (b.slope - line.slope) <
                (line.intercept - b.intercept) * (a.slope - b.slope))
                break;
            lines.pop_back();
        }
        lines.push_back(line);
    }
    Wide minimum(Wide x) {
        while (lines.size() >= 2 && lines[1].at(x) <= lines[0].at(x))
            lines.pop_front();
        return lines.front().at(x);
    }
};
void printWide(Wide value) {
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string digits;
    do {
        digits += char('0' + value % 10);
        value /= 10;
    } while (value);
    reverse(digits.begin(), digits.end());
    cout << digits;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long target;
    cin >> n >> target;
    MonotoneHull hull;
    hull.add(0, 0);
    Wide prefix = 0, best = 0;
    for (int i = 1; i <= n; i++) {
        long long length;
        cin >> length;
        prefix += length + 1;
        Wide x = prefix - target - 1;
        best = x * x + hull.minimum(x);
        hull.add(-2 * prefix, best + prefix * prefix);
    }
    printWide(best);
    return 0;
}
```

### 复杂度

时间 $O(n)$，空间 $O(n)$。

### 易错点

相邻填充物数量为本箱玩具数减一，所以常数是L+1。即使最终费用能装64位，前缀平方和交叉乘积也可能超出，必须先转128位。

## [HNOI2015]菜肴制作

> 原题：[P3243](https://www.luogu.com.cn/problem/P3243)
> 解法：从结尾安排当前可做终点的最大编号，再反转 · C++17

### 题意

约束 $x$ 必须先于 $y$；优先让一号的位置最早，在此基础上让二号最早，再依次考虑。输出最优顺序，有环则输出 Impossible!。这个目标不同于直接最小化输出排列的字典序。



### 思路

从序列末尾向前填。当前能放在末尾的点是没有未安排后继的点，在其中选编号最大的点放到最后。用原图出度和反向邻接表维护候选，最大堆取点，最后反转所得序列。尽量把大编号放晚，才能优先改善小编号的位置；若未取满 $n$ 个点则有环。

![唯一限制为三必须在一前。两个顺序都合法，但下方让一号的位置更早。](data:image/svg+xml;base64,)

唯一限制为三必须在一前。两个顺序都合法，但下方让一号的位置更早。

每组时间 $O(n\log n+m)$，空间 $O(n+m)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n, m;
        cin >> n >> m;
        vector<vector<int>> previous(n + 1);
        vector<int> outdegree(n + 1), reversed;
        for (int i = 0; i < m; i++) {
            int u, v;
            cin >> u >> v;
            previous[v].push_back(u);
            ++outdegree[u];
        }
        priority_queue<int> ready;
        for (int u = 1; u <= n; u++)
            if (!outdegree[u])
                ready.push(u);
        while (!ready.empty()) {
            int u = ready.top();
            ready.pop();
            reversed.push_back(u);
            for (int v : previous[u])
                if (--outdegree[v] == 0)
                    ready.push(v);
        }
        if (int(reversed.size()) != n) {
            cout << "Impossible!\n";
            continue;
        }
        reverse(reversed.begin(), reversed.end());
        for (int u : reversed)
            cout << u << ' ';
        cout << '\n';
    }
    return 0;
}
```

### 易错点

使用反向边与原出度；最大堆取当前汇点；最终反转；不是正向最小字典序；重复边增减次数一致；注意感叹号。

## [JLOI2014]松鼠的新家

### 题意

树上批量路径计数。

### 思路

对每次相邻参观点u→v，先给整条点路径加1：diff[u]++、diff[v]++、diff[LCA]−−、diff[parent(LCA)]−−，再逆序把子树差分累加到父亲，得到路径经过次数。相邻两段会在连接点重复计数，最后到餐厅也不吃糖，所以对指南中的第2到第n个终点各减1，保留每段出发点到终点之前的贡献。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct EulerTree {
    int n;
    vector<vector<int>> edge;
    vector<int> parent, depth, in, out, order;
    EulerTree(int n) : n(n), edge(n + 1), parent(n + 1), depth(n + 1), in(n + 1), out(n + 1) {}
    void add(int u, int v) {
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    void root(int start) {
        vector<int> stack = {start};
        parent[start] = 0;
        order.clear();
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            in[u] = order.size() + 1;
            order.push_back(u);
            for (int v : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack.push_back(v);
                }
        }
        vector<int> size(n + 1, 1);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            out[u] = in[u] + size[u] - 1;
            if (parent[u])
                size[parent[u]] += size[u];
        }
    }
};

struct Ancestors {
    const EulerTree &tree;
    vector<vector<int>> up;
    Ancestors(const EulerTree &tree) : tree(tree) {
        int levels = 1;
        while ((1LL << levels) <= tree.n)
            levels++;
        up.assign(levels, vector<int>(tree.n + 1));
        up[0] = tree.parent;
        for (int b = 1; b < levels; b++)
            for (int u = 1; u <= tree.n; u++)
                up[b][u] = up[b - 1][up[b - 1][u]];
    }
    int lca(int u, int v) const {
        if (tree.depth[u] < tree.depth[v])
            swap(u, v);
        int gap = tree.depth[u] - tree.depth[v];
        for (int b = 0; b < (int)up.size(); b++)
            if (gap >> b & 1)
                u = up[b][u];
        if (u == v)
            return u;
        for (int b = (int)up.size() - 1; b >= 0; b--)
            if (up[b][u] != up[b][v]) {
                u = up[b][u];
                v = up[b][v];
            }
        return up[0][u];
    }
    int distance(int u, int v) const {
        return tree.depth[u] + tree.depth[v] - 2 * tree.depth[lca(u, v)];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> visit;
    visit.resize(n);
    for (int &x : visit)
        cin >> x;
    EulerTree tree(n);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        tree.add(u, v);
    }
    tree.root(1);
    Ancestors ancestor(tree);
    vector<long long> difference(n + 1);
    auto addPath = [&](int u, int v) {
        int a = ancestor.lca(u, v);
        difference[u]++;
        difference[v]++;
        difference[a]--;
        difference[tree.parent[a]]--;
    };
    for (int i = 1; i < n; i++)
        addPath(visit[i - 1], visit[i]);
    for (int i = n - 1; i > 0; i--) {
        int u = tree.order[i];
        difference[tree.parent[u]] += difference[u];
    }
    for (int i = 1; i < n; i++)
        difference[visit[i]]--;
    for (int u = 1; u <= n; u++)
        cout << difference[u] << '\n';
    return 0;
}
```

### 复杂度

时间 $O((n+q)\log n)$，空间 $O(n\log n)$。

### 易错点

这里统计点而非边，LCA本身必须保留一次；根的父亲用0哨兵，不向它继续累加。

## 树学

### 题意

任选树根，使所有节点深度和最小。

### 思路

先以1为根求深度和W[1]及每棵子树大小size。根从u移到儿子v时，v子树的size[v]个点距离各减1，其余n−size[v]个点各加1，所以W[v]=W[u]+n−2*size[v]。一次逆序求size，再按先序换根，取全部W最小值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct EulerTree {
    int n;
    vector<vector<int>> edge;
    vector<int> parent, depth, in, out, order;
    EulerTree(int n) : n(n), edge(n + 1), parent(n + 1), depth(n + 1), in(n + 1), out(n + 1) {}
    void add(int u, int v) {
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    void root(int start) {
        vector<int> stack = {start};
        parent[start] = 0;
        order.clear();
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            in[u] = order.size() + 1;
            order.push_back(u);
            for (int v : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack.push_back(v);
                }
        }
        vector<int> size(n + 1, 1);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            out[u] = in[u] + size[u] - 1;
            if (parent[u])
                size[parent[u]] += size[u];
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    EulerTree tree(n);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        tree.add(u, v);
    }
    tree.root(1);
    vector<int> size(n + 1, 1);
    vector<long long> value(n + 1);
    for (int u : tree.order)
        value[1] += tree.depth[u];
    for (int i = n - 1; i > 0; i--) {
        int u = tree.order[i];
        size[tree.parent[u]] += size[u];
    }
    long long answer = value[1];
    for (int u : tree.order)
        if (u != 1) {
            value[u] = value[tree.parent[u]] + n - 2LL * size[u];
            answer = min(answer, value[u]);
        }
    cout << answer;
    return 0;
}
```

### 复杂度

时间、空间均 $O(n)$。

### 易错点

距离和长链可达n(n−1)/2，需64位。树百万节点，使用迭代遍历。

