}
```

### 复杂度

最长串长为 $L$ 时，时间 $O(nL\log n)$，字符串存储空间 $O(nL)$。

### 易错点

不能排序字符串内部字符；aaa 与 aa 也必须区分。

## 纸牌游戏

### 题意

对方出牌顺序已知，可重排自己的牌，使所有 max(自己的牌-对方的牌,0) 之和最大。

### 思路

把对方牌升序排，自己的牌降序排，逐项累加正差。可从获胜的 k 轮看出上界：总分至多为自己的最大 k 张之和，减对方最小 k 张之和。这两个序列一降一升，逐项差单调不增，取所有正差正好最大化该上界；把其余牌任意配给剩下的轮次即可达到。只求分数，原出牌顺序可以通过重新安排自己的牌还原，不影响最优值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n), b(n);
    for (auto &x : a)
        cin >> x;
    for (auto &x : b)
        cin >> x;
    sort(a.begin(), a.end());
    sort(b.begin(), b.end(), greater<long long>());
    __int128 answer = 0;
    for (int i = 0; i < n; i++)
        if (b[i] > a[i])
            answer += b[i] - a[i];
    if (!answer)
        cout << 0;
    else {
        string s;
        while (answer) {
            s += char('0' + answer % 10);
            answer /= 10;
        }
        reverse(s.begin(), s.end());
        cout << s;
    }
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

单张牌可达 10^18，总分可能超过 64 位；用 __int128 累加并按十进制输出。目标不是获胜轮数。

## [JSOI2008]最大数MAXNUMBER

### 题意

末尾加入反馈取模后的数，查询最后L项最大值。

### 思路

维护下标递增、数值严格递减的候选栈。新值v加入时，栈尾值≤v的候选可以永久删除：未来任何包含旧下标的后缀也包含更新、更大的v。查询最后L项，就是找栈中第一个下标≥长度−L+1的候选，它是区间最大值，二分即可。每次把答案记录为t，供下次插入使用。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m;
    long long d;
    cin >> m >> d;
    vector<int> position;
    vector<long long> value;
    int length = 0;
    long long last = 0;
    while (m--) {
        char op;
        long long x;
        cin >> op >> x;
        if (op == 'A') {
            long long v = ((x % d) + last) % d;
            length++;
            while (!value.empty() && value.back() <= v) {
                value.pop_back();
                position.pop_back();
            }
            position.push_back(length);
            value.push_back(v);
        } else {
            int start = length - (int)x + 1;
            int index = lower_bound(position.begin(), position.end(), start) - position.begin();
            last = value[index];
            cout << last << '\n';
        }
    }
    return 0;
}
```

### 复杂度

插入总计 $O(M)$，每问 $O(\log M)$，空间 $O(M)$。

### 易错点

被支配候选可删，历史查询答案t仍独立保存。先对输入x取模，再加t，避免长整数输入相加溢出。

## 牛牛的Link Power I

### 题意

所有标记1位置之间的无序距离和。

### 思路

从左向右遇到位置i为1时，它与之前所有1的距离和为count*i−sumPosition。将此值加入答案后，更新count与位置和。每对恰在右端点处理一次。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string s;
    cin >> n >> s;
    const long long mod = 1000000007;
    long long count = 0, position = 0, answer = 0;
    for (int i = 0; i < n; i++)
        if (s[i] == '1') {
            answer = (answer + count * i - position) % mod;
            count++;
            position += i;
        }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n)$，空间 $O(n)$ 存输入。

### 易错点

无序对只统计一次，不乘2。使用64位保存计数与位置乘积。

## 圆凸包

### 题意

求多个圆盘凸包的周长，圆之间可包含或相交。

### 思路

方向$u=(\cos\theta,\sin\theta)$上的支撑值是$h(\theta)=\max_i(x_i\cos\theta+y_i\sin\theta+r_i)$。凸体周长等于$\int_0^{2\pi}h(\theta)\,d\theta$；平移产生的正弦、余弦积分恰抵消。

两圆支撑值相等时满足Δx*cosθ+Δy*sinθ=Δr，最多两个解。枚举所有这样的角，再加0和2π排序；相邻事件间最外圆固定，用中点找它并精确积分：x(sin右−sin左)−y(cos右−cos左)+r(右−左)。被包含的圆从不成为严格最大，自然不贡献；相同圆也不影响结果。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    const long double pi = acosl(-1.0L);
    while (tests--) {
        int n;
        cin >> n;
        struct Disc {
            Point c;
            long double r;
        };
        vector<Disc> p(n);
        for (auto &d : p)
            cin >> d.c.x >> d.c.y >> d.r;
        vector<long double> event = {0, 2 * pi};
        auto normalize = [&](long double a) {
            a = fmodl(a, 2 * pi);
            if (a < 0)
                a += 2 * pi;
            return a;
        };
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) {
                Point d = p[i].c - p[j].c;
                long double length = norm(d), value = p[j].r - p[i].r;
                if (length > 0 && fabsl(value) <= length) {
                    long double base = atan2l(d.y, d.x),
                                delta = acosl(clamp(value / length, -1.0L, 1.0L));
                    event.push_back(normalize(base + delta));
                    event.push_back(normalize(base - delta));
                }
            }
        sort(event.begin(), event.end());
        long double answer = 0;
        for (int j = 1; j < (int)event.size(); j++) {
            long double l = event[j - 1], r = event[j], mid = (l + r) / 2;
            int best = 0;
            auto support = [&](int i) {
                return p[i].c.x * cosl(mid) + p[i].c.y * sinl(mid) + p[i].r;
            };
            for (int i = 1; i < n; i++)
                if (support(i) > support(best))
                    best = i;
            auto d = p[best];
            answer += d.c.x * (sinl(r) - sinl(l)) - d.c.y * (cosl(r) - cosl(l)) + d.r * (r - l);
        }
        cout << fixed << setprecision(12) << answer << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n^3+n^2\log n)$，空间 $O(n^2)$。

### 易错点

仅对圆心求凸包再加某个统一半径，只适用于所有半径相同。这里每个圆的半径都参与支撑值比较。

## [JSOI2010]缓存交换

### 题意

已知全部访问请求，求容量固定的空缓存的最少缺失次数。

### 思路

先将任意大编号离散化，再倒序求每次访问的下次位置，不再访问记为 n。缓存满时淘汰下次使用最晚的页面。交换理由：若某最优策略先淘汰较早再用的页面，可改为淘汰较晚者；直到较早者再次被请求前都不增加缺失，届时再对齐两种缓存，故最优值不会变差。

大根堆存下次位置与页面，命中后也更新。旧的堆记录延迟删除，淘汰前跳过已不在缓存或下次位置过期的记录。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, capacity;
    cin >> n >> capacity;
    vector<int> a(n), values;
    for (int &x : a)
        cin >> x;
    values = a;
    sort(values.begin(), values.end());
    values.erase(unique(values.begin(), values.end()), values.end());
    for (int &x : a)
        x = lower_bound(values.begin(), values.end(), x) - values.begin();
    int kinds = values.size();
    vector<int> next(n), last(kinds, n), current(kinds, -1);
    for (int i = n - 1; i >= 0; i--) {
        next[i] = last[a[i]];
        last[a[i]] = i;
    }
    vector<bool> present(kinds);
    priority_queue<pair<int, int>> heap;
    int size = 0, misses = 0;
    for (int i = 0; i < n; i++) {
        int x = a[i];
        if (!present[x]) {
            misses++;
            if (size == capacity) {
                while (!present[heap.top().second] ||
                       current[heap.top().second] != heap.top().first)
                    heap.pop();
                present[heap.top().second] = false;
                heap.pop();
                size--;
            }
            present[x] = true;
            size++;
        }
        current[x] = next[i];
        heap.push({next[i], x});
    }
    cout << misses;
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

题目编号可达十亿，不能按编号直接开数组。缓存初始为空；即使命中也要更新下次访问时间。

## [JSOI2011]分特产

### 题意

多种同类物品不可区分，分给n名有区别同学，人人至少一个。

### 思路

先允许空手。若只给s名指定同学，第j种a[j]件的非负分配数由隔板法得到C(a[j]+s−1,s−1)，不同种相乘。容斥选择k名空手者：答案Σ(-1)^k*C(n,k)*ΠC(a[j]+n−k−1,n−k−1)。对s≥1枚举，s=0仅当所有物品总数为0时有1种；n≥1且物品全0直接答案0。预处理不超过1999的阶乘、逆阶乘。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long long mod = 1000000007;
long long power(long long a, long long b) {
    long long result = 1;
    while (b) {
        if (b & 1)
            result = result * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> amount(m);
    long long total = 0;
    int maximum = 0;
    for (int &a : amount) {
        cin >> a;
        total += a;
        maximum = max(maximum, a);
    }
    if (!total) {
        cout << 0;
        return 0;
    }
    int limit = n + maximum;
    vector<long long> factorial(limit + 1, 1), inverse(limit + 1);
    for (int i = 1; i <= limit; i++)
        factorial[i] = factorial[i - 1] * i % mod;
    inverse[limit] = power(factorial[limit], mod - 2);
    for (int i = limit; i >= 1; i--)
        inverse[i - 1] = inverse[i] * i % mod;
    auto choose = [&](int a, int b) {
        return factorial[a] * inverse[b] % mod * inverse[a - b] % mod;
    };
    long long answer = 0;
    for (int empty = 0; empty < n; empty++) {
        int students = n - empty;
        long long ways = choose(n, empty);
        for (int a : amount)
            ways = ways * choose(a + students - 1, students - 1) % mod;
        answer = (answer + (empty % 2 ? mod - ways : ways)) % mod;
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(nm+n+\max a+\log P)$，空间 $O(n+m+\max a)$。

### 易错点

同类特产不可区分，不应给每件物品贴编号。容斥选的是同学集合，必须乘C(n,k)。

## 数颜色

### 题意

支持单点改色和区间不同颜色计数，按本题 n、m 各一万及至多一千次修改范围处理。

### 思路

先读入全部操作，将初始颜色与修改中会出现的颜色统一离散化；最多一万一千种颜色。把位置按约一百个一块划分，每块维护每种颜色出现次数，以及哪些颜色存在的压位集合。修改时只更新一个块的两种计数与对应位。

查询时，零散边缘逐个把颜色位设为一，完整块则把该块位集按机器字或进临时集合，最后统计一的数量。位集做的是集合并，不会重复计颜色；块内频数则保证删掉一个位置后，只有同色真的消失才清位。这里能预读操作且范围较小，压位分块足够，不需要假定输入是强制在线。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n), keys;
    for (int &x : a) {
        cin >> x;
        keys.push_back(x);
    }
    struct Operation {
        char type;
        int x, y;
    };
    vector<Operation> operations(m);
    for (auto &op : operations) {
        cin >> op.type >> op.x >> op.y;
        if (op.type == 'R')
            keys.push_back(op.y);
    }
    sort(keys.begin(), keys.end());
    keys.erase(unique(keys.begin(), keys.end()), keys.end());
    auto compressed = [&](int x) {
        return (int)(lower_bound(keys.begin(), keys.end(), x) - keys.begin());
    };
    for (int &x : a)
        x = compressed(x);
    for (auto &op : operations)
        if (op.type == 'R')
            op.y = compressed(op.y);
    int block = max(1, (int)sqrt(n)), blocks = (n + block - 1) / block, values = keys.size(),
        words = (values + 63) / 64;
    vector<vector<int>> count(blocks, vector<int>(values));
    vector<vector<unsigned long long>> present(blocks, vector<unsigned long long>(words));
    for (int i = 0; i < n; i++) {
        count[i / block][a[i]]++;
        present[i / block][a[i] / 64] |= 1ULL << (a[i] % 64);
    }
    for (auto op : operations) {
        if (op.type == 'R') {
            int p = op.x - 1, group = p / block, old = a[p];
            if (--count[group][old] == 0)
                present[group][old / 64] &= ~(1ULL << (old % 64));
            if (++count[group][op.y] == 1)
                present[group][op.y / 64] |= 1ULL << (op.y % 64);
            a[p] = op.y;
        } else {
            int l = op.x - 1, r = op.y - 1;
            vector<unsigned long long> colors(words);
            auto include = [&](int p) { colors[a[p] / 64] |= 1ULL << (a[p] % 64); };
            while (l <= r && l % block)
                include(l++);
            while (l + block - 1 <= r) {
                for (int w = 0; w < words; w++)
                    colors[w] |= present[l / block][w];
                l += block;
            }
            while (l <= r)
                include(l++);
            int answer = 0;
            for (auto word : colors)
                answer += __builtin_popcountll(word);
            cout << answer << '\n';
        }
    }
    return 0;
}
```

### 复杂度

设颜色种数为 $V$、块长 $B\approx\sqrt n$，修改 $O(1)$；查询 $O(B+(n/B)\lceil V/64\rceil)$，空间 $O((n/B)V+n+m)$。预处理离散化另需 $O((n+m)\log(n+m))$。

### 易错点

离散化时要包含未来修改的新颜色。修改成原颜色也合法，计数先减后加可正确还原。每条查询都重新清空临时集合。

## [SCOI2005]互不侵犯KING

### 题意

在n乘n棋盘放恰好k个互不攻击的国王，八方向近邻均攻击。

### 思路

预处理行内无相邻1的mask。两相邻行a、b相容，需a与b、b左移1、b右移1都不相交，分别排除竖直和两种斜攻击。dp[行mask][已放数]累加相容前行的方案，增加当前行1的数量。初始空前行、0个国王为1，处理n行后对放k个的所有末行求和。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<int> mask, count;
    for (int x = 0; x < (1 << n); x++)
        if (!(x & (x << 1))) {
            mask.push_back(x);
            count.push_back(__builtin_popcount((unsigned)x));
        }
    int states = mask.size();
    vector<vector<int>> compatible(states);
    for (int a = 0; a < states; a++)
        for (int b = 0; b < states; b++)
            if (!(mask[a] & mask[b]) && !(mask[a] & (mask[b] << 1)) && !(mask[a] & (mask[b] >> 1)))
                compatible[a].push_back(b);
    vector<vector<long long>> dp(states, vector<long long>(k + 1));
    dp[0][0] = 1;
    for (int r = 0; r < n; r++) {
        vector<vector<long long>> next(states, vector<long long>(k + 1));
        for (int a = 0; a < states; a++)
            for (int b : compatible[a])
                for (int used = 0; used + count[a] <= k; used++)
                    next[a][used + count[a]] += dp[b][used];
        dp.swap(next);
    }
    long long answer = 0;
    for (int x = 0; x < states; x++)
        answer += dp[x][k];
    cout << answer;
    return 0;
}
```

### 复杂度

行状态数 $S$，时间 $O(nkS^2+2^n)$，空间 $O(kS+S^2)$。

### 易错点

k=0时空棋盘有一种方案。方案数使用64位，题目不要求取模。

## [SCOI2005]扫雷MINE

### 题意

仅第一列可放雷，第二列给出相邻三格雷数，统计所有合法布雷。

### 思路

记第一列第 i 格是否有雷为 x[i]，边界 x[0]=x[n+1]=0。只需枚举 x[1] 为零或一；由 a[i]=x[i-1]+x[i]+x[i+1]，每个后续 x[i+1] 都被唯一确定。递推出的值必须为零或一，最后还必须满足棋盘外的 x[n+1]=0。统计两次尝试中合法的个数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++)
        cin >> a[i];
    int answer = 0;
    for (int first = 0; first <= 1; first++) {
        int previous = 0, current = first;
        bool valid = true;
        for (int i = 1; i <= n; i++) {
            int next = a[i] - previous - current;
            if (next < 0 || next > 1 || (i == n && next != 0)) {
                valid = false;
                break;
            }
            previous = current;
            current = next;
        }
        answer += valid;
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n)$，保存输入 $O(n)$。

### 易错点

越出上下边界均无雷，最后一项必须专门检查。后续位置已被方程强迫，不需要枚举二的 n 次方种布局。

## [SCOI2005]最大子矩阵

### 题意

只有一列或两列，选恰好k个互不重叠子矩形，最大化总分，格值可为负。

### 思路

按行扫描，一个矩形跨越多行时，其占据的列集合必须不变。两列时当前行只有五种覆盖形态：空、仅左、仅右、左右两个独立矩形、横跨两列的一个矩形。记录“已启动矩形数、当前形态”的最优分数。

从上一行转移时，当前每个矩形可继续上一行列集合完全相同的矩形，也可重新启动；没有相同列集合则必须启动。枚举可继续者的子集，新增数等于当前矩形数减去继续数，再加本行被覆盖格的分数。允许相邻两行同一列重新启动，因为两个上下接触的矩形仍互不重叠。单列仅保留空与仅左两种形态。最后取启动数恰为k的最大值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    vector<array<int, 2>> a(n);
    for (int r = 0; r < n; r++)
        for (int c = 0; c < m; c++)
            cin >> a[r][c];
    vector<vector<int>> pattern{{}, {1}, {2}, {1, 2}, {3}};
    int states = m == 1 ? 2 : 5;
    const long long neg = -(1LL << 60);
    vector<vector<long long>> dp(k + 1, vector<long long>(states, neg));
    dp[0][0] = 0;
    for (int r = 0; r < n; r++) {
        vector<vector<long long>> next(k + 1, vector<long long>(states, neg));
        for (int previous = 0; previous < states; previous++)
            for (int current = 0; current < states; current++) {
                int rectangles = pattern[current].size(), covered = 0, allowed = 0;
                for (int j = 0; j < rectangles; j++) {
                    int columns = pattern[current][j];
                    covered |= columns;
                    if (find(pattern[previous].begin(), pattern[previous].end(), columns) !=
                        pattern[previous].end())
                        allowed |= 1 << j;
                }
                long long gain = (covered & 1 ? a[r][0] : 0) + (covered & 2 ? a[r][1] : 0);
                for (int continuation = allowed;; continuation = (continuation - 1) & allowed) {
                    int starts = rectangles - __builtin_popcount((unsigned)continuation);
                    for (int count = 0; count + starts <= k; count++)
                        if (dp[count][previous] != neg)
                            next[count + starts][current] =
                                max(next[count + starts][current], dp[count][previous] + gain);
                    if (continuation == 0)
                        break;
                }
            }
        dp.swap(next);
    }
    cout << *max_element(dp[k].begin(), dp[k].end());
    return 0;
}
```

### 复杂度

形态数至多5、继续子集至多4，时间 $O(nk)$，空间 $O(k+n)$，常数由固定五形态决定。

### 易错点

两列同被覆盖时，必须区分一个宽矩形与两个窄矩形，否则会错误计算启动次数。负数情况下仍要求恰好k个，不能初始化全部状态为0。

## [SCOI2005]繁忙的都市

> 原题：[P2330](https://www.luogu.com.cn/problem/P2330)
> 解法：先确定$n-1$条，再最小化其中最大的分值 · C++17

### 题意

要求改造道路连接所有路口，先使改造道路条数最少，再使所选最大分值尽量小。输出条数与该最大分值。



### 思路

连通$n$个点至少需要$n-1$条边，生成树恰能达到。按分值递增做Kruskal，接受$n-1$条后停止，输出$n-1$及最后一条接受边的分值。此前较小分值边尚不能全连通，说明任何生成树都需要达到这个门槛。

![先把条数压到二，再最小化瓶颈；这张图应输出二与四十三。](data:image/svg+xml;base64,)

先把条数压到二，再最小化瓶颈；这张图应输出二与四十三。

时间 $O(m\log m+(n+m)\alpha(n))$，空间 $O(n+m)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
struct DSU {
    vector<int> parent, size;
    // 这里的n表示0至n-1共n个对象。
    explicit DSU(int n) : parent(n), size(n, 1) { iota(parent.begin(), parent.end(), 0); }
    int root(int u) {
        while (parent[u] != u) {
            parent[u] = parent[parent[u]];
            u = parent[u];
        }
        return u;
    }
    bool merge(int u, int v) {
        u = root(u);
        v = root(v);
        if (u == v)
            return false;
        if (size[u] < size[v])
            swap(u, v);
        parent[v] = u;
        size[u] += size[v];
        return true;
    }
};
struct Edge {
    int u, v;
    long long w;
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<Edge> edges(m);
    for (auto &e : edges) {
        cin >> e.u >> e.v >> e.w;
        --e.u;
        --e.v;
    }
    sort(edges.begin(), edges.end(), [](const Edge &a, const Edge &b) { return a.w < b.w; });
    DSU dsu(n);
    int selected = 0;
    long long largest = 0;
    for (const auto &e : edges)
        if (dsu.merge(e.u, e.v)) {
            largest = e.w;
            if (++selected == n - 1)
                break;
        }
    cout << selected << ' ' << largest << '\n';
    return 0;
}
```

### 易错点

优先条数，后比瓶颈；不输出分值和；合并失败的环边忽略；$n=1$为空方案。

## 树上子链

### 题意

点权可正可负，求非空简单路径上的最大点权和。

### 思路

down[u]表示从u向某个后代延伸的最大路径和。孩子中只取最大的正贡献加入u；以u为最高点的完整路径最多连接两个不同孩子，故取最大的两个非负down贡献，再加u权值更新全局答案。全局初值为负无穷，保证全负时仍选一个最大权点，而非空路径。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Tree {
    vector<vector<pair<int, long long>>> edge;
    vector<int> parent, order;
    vector<long long> incoming;
    explicit Tree(int n) : edge(n), parent(n, -1), incoming(n) {}
    void add(int u, int v, long long w = 1) {
        edge[u].push_back({v, w});
        edge[v].push_back({u, w});
    }
    void root(int start) {
        order = {start};
        parent[start] = start;
        for (size_t i = 0; i < order.size(); i++) {
            int u = order[i];
            for (auto [v, w] : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    incoming[v] = w;
                    order.push_back(v);
                }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> weight(n), down(n);
    for (auto &x : weight)
        cin >> x;
    Tree tree(n);
    for (int i = 1; i < n; i++) {
        int a, b;
        cin >> a >> b;
        tree.add(a - 1, b - 1);
    }
    tree.root(0);
    long long answer = -(1LL << 60);
    for (int i = n - 1; i >= 0; i--) {
        int u = tree.order[i];
        long long first = 0, second = 0;
        for (auto [v, w] : tree.edge[u])
            if (v != tree.parent[u]) {
                long long value = down[v];
                if (value > first) {
                    second = first;
                    first = value;
                } else if (value > second)
                    second = value;
            }
        down[u] = weight[u] + first;
        answer = max(answer, weight[u] + first + second);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间、空间均为 $O(n)$。

### 易错点

不是树边权直径，负权下不能用两次找最远点。每个点至多用一次，两条向下支路必须来自不同孩子。

## 仓库选址

### 题意

在需求矩阵中选仓库，使需求次数乘曼哈顿距离的总和最小。

### 思路

横纵距离可分开：将每行需求加总，得到选仓库行号的一维带权绝对距离问题；每列同理。每一维都取累计权重首次达到总权重一半的位置，即带权中位数，然后求所有权重乘与该位置的距离。两个一维最小费用相加就是答案，仓库可位于有需求的格子。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n, m;
        cin >> n >> m;
        vector<long long> rows(m), columns(n);
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++) {
                long long x;
                cin >> x;
                rows[r] += x;
                columns[c] += x;
            }
        auto cost = [](const vector<long long> &weights) {
            long long total = accumulate(weights.begin(), weights.end(), 0LL), prefix = 0,
                      answer = 0;
            int median = 0;
            for (int i = 0; i < (int)weights.size(); i++) {
                prefix += weights[i];
                if (prefix * 2 >= total) {
                    median = i;
                    break;
                }
            }
            for (int i = 0; i < (int)weights.size(); i++)
                answer += weights[i] * abs(i - median);
            return answer;
        };
        cout << cost(rows) + cost(columns) << '\n';
    }
    return 0;
}
```

### 复杂度

时间 $O(nm+n+m)$，额外空间 $O(n+m)$。

### 易错点

输入先给宽 n、高 m，之后是 m 行 n 列。每次需求只按题意计算运输距离，不额外乘二；样例首组答案二可核对这一点。

## 货物种类

### 题意

多次把某种货物放进连续仓库，求拥有不同货物种类最多的最小仓库编号。

### 思路

同一种货物重复覆盖同一仓库只算一种。先按货物编号、区间左端点排序，把每种货物的覆盖区间合并为互不重叠的段。对每个合并段 [l,r] 做差分 +1：d[l]++、d[r+1]--。最后前缀累加就是各仓库的种类数，从左到右仅在严格更大时更新答案。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<tuple<int, int, int>> intervals;
    for (int i = 0; i < m; i++) {
        int l, r, kind;
        cin >> l >> r >> kind;
        if (l > r)
            swap(l, r);
        intervals.push_back({kind, l, r});
    }
    sort(intervals.begin(), intervals.end());
    vector<int> difference(n + 2);
    int kind = -1, left = 0, right = -1;
    auto flush = [&]() {
        if (left <= right) {
            difference[left]++;
            difference[right + 1]--;
        }
    };
    for (auto [d, l, r] : intervals) {
        if (d == kind && l <= right + 1)
            right = max(right, r);
        else {
            flush();
            kind = d;
            left = l;
            right = r;
        }
    }
    flush();
    int count = 0, best = -1, answer = 1;
    for (int i = 1; i <= n; i++) {
        count += difference[i];
        if (count > best) {
            best = count;
            answer = i;
        }
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(m\log m+n)$，空间 $O(n+m)$。

### 易错点

直接对每条进货区间加一会把同种货物重复计算。需要先分货物做区间并集，再跨货物累加。

## 魔法数字

### 思路

把当前整数作为状态，三种操作都是一条权值1的边，BFS首次到达目标就是最少次数。只需搜索0到2*max(n,m)+2：从不超过最大端点M的数平方跳到大于2M的值后，只能靠逐次减一回到目标，代价超过直接从原数步行至目标；这种超大跳跃不会最优。负数也无益，因为到负数前必须经过0，平方负数可由正数同值状态更早达到。

### 参考代码

保留原站函数接口。

```cpp
#include <bits/stdc++.h>
using namespace std;
class Solution {
  public:
    int solve(int n, int m) {
        int bound = 2 * max(n, m) + 2;
        vector<int> distance(bound + 1, -1), queue{n};
        distance[n] = 0;
        for (size_t h = 0; h < queue.size(); h++) {
            int u = queue[h];
            if (u == m)
                return distance[u];
            for (long long v : {1LL * u - 1, 1LL * u + 1, 1LL * u * u})
                if (v >= 0 && v <= bound && distance[v] == -1) {
                    distance[v] = distance[u] + 1;
                    queue.push_back(v);
                }
        }
        return -1;
    }
};
```

### 复杂度

设M=max(n,m)，时间、空间均为O(M)。

### 易错点

平方先转64位再计算，之后检查搜索边界。三个操作代价相同，使用普通BFS。

## [SCOI2007]降雨量

### 题意

部分年份降雨已知，判断“X是自Y以来最多”的真假或不确定。

### 思路

二分找到Y、X是否已知，并查询严格中间(Y,X)内已知雨量最大值M。若两端已知且rain[Y]<rain[X]，必假；X已知且M≥rain[X]，必假；X未知但Y已知且M≥rain[Y]，也必假，因为X既须大于M又不能超过Y。

排除矛盾后，只有两端都已知且X−Y等于两端记录下标差，才说明整段每一年都已记录，可输出true；否则仍有未知年份，输出maybe。未知两端也不应擅自补为0。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct RangeMaximum {
    int size = 1;
    vector<long long> tree;
    RangeMaximum(int n) {
        while (size < n)
            size <<= 1;
        tree.assign(size * 2, LLONG_MIN);
    }
    void setValue(int p, long long value) {
        p += size;
        tree[p] = value;
        for (p >>= 1; p; p >>= 1)
            tree[p] = max(tree[p * 2], tree[p * 2 + 1]);
    }
    long long query(int l, int r) {
        long long result = LLONG_MIN;
        for (l += size, r += size; l < r; l >>= 1, r >>= 1) {
            if (l & 1)
                result = max(result, tree[l++]);
            if (r & 1)
                result = max(result, tree[--r]);
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> year(n), rain(n);
    RangeMaximum maximum(n);
    for (int i = 0; i < n; i++) {
        cin >> year[i] >> rain[i];
        maximum.setValue(i, rain[i]);
    }
    int q;
    cin >> q;
    while (q--) {
        long long y, x;
        cin >> y >> x;
        int iy = lower_bound(year.begin(), year.end(), y) - year.begin(),
            ix = lower_bound(year.begin(), year.end(), x) - year.begin();
        bool knownY = iy < n && year[iy] == y, knownX = ix < n && year[ix] == x;
        int left = upper_bound(year.begin(), year.end(), y) - year.begin(),
            right = lower_bound(year.begin(), year.end(), x) - year.begin();
        long long middle = maximum.query(left, right);
        bool bad = (knownY && knownX && rain[iy] < rain[ix]) || (knownX && middle >= rain[ix]) ||
                   (knownY && !knownX && middle >= rain[iy]);
        if (bad)
            cout << "false\n";
        else if (knownY && knownX && x - y == ix - iy)
            cout << "true\n";
        else
            cout << "maybe\n";
    }
    return 0;
}
```

### 复杂度

预处理 $O(n\log n)$，每问 $O(\log n)$，空间 $O(n)$。

### 易错点

中间年份降雨必须严格小于X，因此相等也是假。年份可能为负，差值用64位。原查询语义为Y<X。

## [SCOI2008]奖励关

> 原题：[P2473](https://www.luogu.com.cn/problem/P2473)
> 解法：观察本次宝物后决策，再对各种出现情况求平均 · C++17

### 题意

独立均匀抛出若干次宝物，可吃或放弃；吃某类前要吃过全部前提类，允许重复得分，求最优策略下总得分期望。



### 思路



![A负一且无前提，B一百且要求吃过A；四叶的原始观察概率均等，图右支的两种后续都无法获得正分。](data:image/svg+xml;base64,)

$f[r][S]$表示已吃过种类集合S、还剩$r$次时的最大未来期望。观察到种类$j$后，先检查前提，再比较放弃与“本次得分加剩余$r$减一次的期望”；重复吃仍能得分，只是集合不变。对每种观察分别选好，再按相同概率平均。时间层只读上一层，可滚动数组。

时间 $O(kn2^n)$，空间 $O(2^n+n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int throws, n;
    cin >> throws >> n;
    vector<int> score(n), required(n);
    for (int i = 0; i < n; i++) {
        cin >> score[i];
        int item;
        while (cin >> item && item)
            required[i] |= 1 << (item - 1);
    }
    int states = 1 << n;
    vector<double> dp(states), next(states);
    for (int r = 1; r <= throws; r++) {
        for (int mask = 0; mask < states; mask++) {
            double sum = 0;
            for (int j = 0; j < n; j++) {
                double best = dp[mask];
                if ((mask & required[j]) == required[j])
                    best = max(best, score[j] + dp[mask | (1 << j)]);
                sum += best;
            }
            next[mask] = sum / n;
        }
        dp.swap(next);
    }
    cout << fixed << setprecision(6) << dp[0] << '\n';
    return 0;
}
```

### 易错点

先观察再选择；不允许吃的出现也占一次机会；负分可解锁后续；重复吃仍得分；只记录至少吃过；读旧时间层。

## [SCOI2009]WINDY数

> 原题：[P2657](https://www.luogu.com.cn/problem/P2657)
> 解法：记住前一位，逐位统计满足相邻差的正整数 · C++17

### 题意

统计闭区间内不含前导零、且相邻十进制数字之差的绝对值至少为二的正整数。



### 思路



![数字135与132只差末位却合法性不同；0013代表13，占位零没有与真实首位形成相邻对。](data:image/svg+xml;base64,)

先求不超过$x$的合格正整数数目$F(x)$，答案为$F(b)$减F(a减一)。从高位向低位填，状态只需位置、前一实际数字和是否贴着上界。用十表示还没开始，前导补零不参与相邻比较；一旦开始，每个新数字与前一位差至少二。末尾仍没开始的全零路径不计数，只缓存已经小于上界的状态。

设十进制位数为D，时间 $O(100D)$，空间 $O(10D)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long a, b;
    cin >> a >> b;
    auto prefix = [&](long long x) {
        if (x <= 0)
            return 0LL;
        string digits = to_string(x);
        long long memo[20][11];
        memset(memo, -1, sizeof(memo));
        function<long long(int, int, bool)> dfs = [&](int pos, int previous,
                                                      bool tight) -> long long {
            if (pos == int(digits.size()))
                return previous != 10;
            if (!tight && memo[pos][previous] >= 0)
                return memo[pos][previous];
            long long count = 0;
            int limit = tight ? digits[pos] - '0' : 9;
            for (int d = 0; d <= limit; d++) {
                if (previous != 10 && abs(previous - d) < 2)
                    continue;
                int next = (previous == 10 && d == 0) ? 10 : d;
                count += dfs(pos + 1, next, tight && d == limit);
            }
            if (!tight)
                memo[pos][previous] = count;
            return count;
        };
        return dfs(0, 10, true);
    };
    cout << prefix(b) - prefix(a - 1) << '\n';
    return 0;
}
```

### 易错点

相邻差取绝对值；零开始后是实际数字；前导占位零不比较；排除零本身；闭区间减$a$减一；两个上界分别重建缓存。

## [SCOI2009]生日快乐

### 题意

用平行于边的贯穿切割把矩形分成N块等面积小矩形，最小化最大长宽比。

### 思路

当前矩形x×y要分k人。第一刀若一边给i人，面积必须占i/k，因此横切两块边长分别为 x*i/k、x*(k−i)/k，纵切同理。枚举i=1到k−1和两种方向，递归求两块各自的最优值；当前方案取两者最大值，再对所有切法取最小。k=1时直接返回max(x/y,y/x)。每个完整切割方案都有某一条第一刀，所以枚举不会漏。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    double x, y;
    int n;
    cin >> x >> y >> n;
    auto solve = [&](auto &&self, double a, double b, int count) -> double {
        if (count == 1)
            return max(a / b, b / a);
        double answer = 1e100;
        for (int left = 1; left < count; left++) {
            double ratio = (double)left / count;
            answer = min(answer, max(self(self, a * ratio, b, left),
                                     self(self, a * (1 - ratio), b, count - left)));
            answer = min(answer, max(self(self, a, b * ratio, left),
                                     self(self, a, b * (1 - ratio), count - left)));
        }
        return answer;
    };
    cout << fixed << setprecision(6) << solve(solve, x, y, n);
    return 0;
}
```

### 复杂度

递归调用数满足 $T(k)=4\sum_{i<k}T(i)+O(k)$，可界为 $O(5^N)$；栈空间 $O(N)$，$N\le10$。

### 易错点

不能只切等宽条；各子矩形可选不同切割方向。每刀分配的人数必须是整数，面积比例才确定。

## [SCOI2009]粉刷匠

### 题意

每次只能刷一条木板的一段，每格最多刷一次，总次数至多T，最大化正确颜色格数。

### 思路

先独立处理一条板。j次笔画可分成j个不相交段，每段涂成其中目标颜色的多数色，得分为两种颜色计数的最大值。允许不刷的间隙可延长相邻笔画覆盖，不会减少已正确格数，所以j≥1时可直接枚举把整板分成j个非空段。前缀计数求段得分，做分段DP得到gain[j]；gain[0]=0表示整板不刷。

再将每条木板当一组，枚举给这条板0到M次，做以总笔画次数为容量的分组背包。容量表示至多次数，故初始各容量0，最后取T处最优值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, budget;
    cin >> n >> m >> budget;
    budget = min(budget, n * m);
    vector<int> total(budget + 1);
    for (int row = 0; row < n; row++) {
        string s;
        cin >> s;
        vector<int> prefix(m + 1);
        for (int i = 0; i < m; i++)
            prefix[i + 1] = prefix[i] + (s[i] == '1');
        int cap = min(m, budget), neg = -1000000000;
        vector<int> gain(cap + 1), dp(m + 1, neg);
        dp[0] = 0;
        for (int strokes = 1; strokes <= cap; strokes++) {
            vector<int> next(m + 1, neg);
            for (int i = strokes; i <= m; i++)
                for (int p = strokes - 1; p < i; p++)
                    if (dp[p] != neg) {
                        int ones = prefix[i] - prefix[p];
                        next[i] = max(next[i], dp[p] + max(ones, i - p - ones));
                    }
            dp.swap(next);
            gain[strokes] = dp[m];
        }
        vector<int> next(budget + 1);
        for (int b = 0; b <= budget; b++)
            for (int use = 0; use <= cap && use <= b; use++)
                next[b] = max(next[b], total[b - use] + gain[use]);
        total.swap(next);
    }
    cout << total[budget];
    return 0;
}
```

### 复杂度

时间 $O(NM^3+NTM)$，空间 $O(M+T)$。

### 易错点

每格最多刷一次，与可以覆盖的“涂色”题不同。T可能超过格数，额外次数不增加收益，可截到N*M。

## 【入门班】急速行走

### 题意

从 A 沿第一线段、转为平面行走，再沿第二线段到 D，最小化耗时。

### 思路

令离开第一线段的位置 E=A+t(B-A)，进入第二线段的位置 F=C+u(D-C)，t、u 都在零到一。耗时为 |AE|/p+|EF|/r+|FD|/q。固定 t 后，它对 u 是凸函数，可三分求最小；联合表达式是凸函数，对 u 取最小后的函数对 t 仍凸，因此外层再三分。每层固定迭代一百次，最后求值；两端位置也在闭区间中，无须额外假设最优在内部。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long double ax, ay, bx, by, cx, cy, dx, dy, p, q, r;
    cin >> ax >> ay >> bx >> by >> cx >> cy >> dx >> dy >> p >> q >> r;
    auto inner = [&](long double t) {
        long double ex = ax + t * (bx - ax), ey = ay + t * (by - ay);
        auto cost = [&](long double u) {
            long double fx = cx + u * (dx - cx), fy = cy + u * (dy - cy);
            return hypotl(ex - ax, ey - ay) / p + hypotl(ex - fx, ey - fy) / r +
                   hypotl(dx - fx, dy - fy) / q;
        };
        long double low = 0, high = 1;
        for (int i = 0; i < 100; i++) {
            long double x = (2 * low + high) / 3, y = (low + 2 * high) / 3;
            if (cost(x) <= cost(y))
                high = y;
            else
                low = x;
        }
        return cost((low + high) / 2);
    };
    long double low = 0, high = 1;
    for (int i = 0; i < 100; i++) {
        long double x = (2 * low + high) / 3, y = (low + 2 * high) / 3;
        if (inner(x) <= inner(y))
            high = y;
        else
            low = x;
    }
    cout << fixed << setprecision(2) << inner((low + high) / 2);
    return 0;
}
```

### 复杂度

每层迭代 $K=100$ 次，时间 $O(K^2)$，额外空间 $O(1)$。

### 易错点

按原 SCOI 题及样例，p、q、r 是通常的速度，时间为距离除速度；不要被题面“单位时间每单位距离”的措辞误导。

## [SCOI2010]字符串

### 题意

n个1和m个0组成串，任意前缀中1不少于0，求数量模20100403。

### 思路

所有串有C(n+m,m)个。把1看成向上、0看成向下，非法串第一次到达高度−1前的步骤全部翻转，就得到含n+1个1、m−1个0的串；反过来也能唯一恢复第一次越界段。因此非法数是C(n+m,m−1)，答案为二者之差。模数20100403为素数，且n+m≤2000000小于模数，可预处理阶乘并用快速幂求逆阶乘。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    const long long mod = 20100403;
    int limit = n + m;
    vector<long long> factorial(limit + 1, 1), inverse(limit + 1);
    for (int i = 1; i <= limit; i++)
        factorial[i] = factorial[i - 1] * i % mod;
    auto power = [&](long long a, long long b) {
        long long result = 1;
        while (b) {
            if (b & 1)
                result = result * a % mod;
            a = a * a % mod;
            b >>= 1;
        }
        return result;
    };
    inverse[limit] = power(factorial[limit], mod - 2);
    for (int i = limit; i >= 1; i--)
        inverse[i - 1] = inverse[i] * i % mod;
    auto choose = [&](int k) {
        if (k < 0 || k > limit)
            return 0LL;
        return factorial[limit] * inverse[k] % mod * inverse[limit - k] % mod;
    };
    cout << (choose(m) - choose(m - 1) + mod) % mod;
    return 0;
}
```

### 复杂度

时间 $O(n+m+\log P)$，空间 $O(n+m)$。

### 易错点

非法串的反射是在第一次到达−1处，不是任意负前缀。最后做减法后加模数。

## [SCOI2011]糖果

### 题意

每人至少一个糖果，满足相等及严格、非严格比较关系，最小化总数。

### 思路

统一为lower[v]≥lower[u]+w，w只能0或1。相等连两条0边，A<B连A→B权1，A≥B连B→A权0，A>B连B→A权1，A≤B连A→B权0。非负边图中，矛盾等价于某个有向环包含1边；缩SCC后，只要内部有1边就输出−1。

其余SCC内全为0，所有人可取同一个最小值。缩点DAG上所有分量初值1，拓扑求最长下界d[v]=max(d[v],d[u]+w)。这些值同时达到全部约束的逐点最小值，因此按每个分量人数累加就是最小总糖果数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

pair<int, vector<int>> components(const vector<vector<int>> &graph,
                                  const vector<vector<int>> &reverse) {
    int n = graph.size();
    vector<bool> seen(n);
    vector<int> finish;
    for (int start = 0; start < n; start++)
        if (!seen[start]) {
            vector<pair<int, int>> stack{{start, 0}};
            seen[start] = true;
            while (!stack.empty()) {
                int u = stack.back().first, &position = stack.back().second;
                if (position == (int)graph[u].size()) {
                    finish.push_back(u);
                    stack.pop_back();
                } else {
                    int v = graph[u][position++];
                    if (!seen[v]) {
                        seen[v] = true;
                        stack.push_back({v, 0});
                    }
                }
            }
        }
    vector<int> component(n, -1);
    int count = 0;
    for (int i = n - 1; i >= 0; i--) {
        int start = finish[i];
        if (component[start] != -1)
            continue;
        vector<int> stack{start};
        component[start] = count;
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            for (int v : reverse[u])
                if (component[v] == -1) {
                    component[v] = count;
                    stack.push_back(v);
                }
        }
        count++;
    }
    return {count, component};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    struct Edge {
        int a, b, w;
    };
    vector<Edge> edges;
    vector<vector<int>> graph(n), reverse(n);
    auto addEdge = [&](int a, int b, int w) {
        edges.push_back({a, b, w});
        graph[a].push_back(b);
        reverse[b].push_back(a);
    };
    while (k--) {
        int type, a, b;
        cin >> type >> a >> b;
        --a;
        --b;
        if (type == 1) {
            addEdge(a, b, 0);
            addEdge(b, a, 0);
        } else if (type == 2)
            addEdge(a, b, 1);
        else if (type == 3)
            addEdge(b, a, 0);
        else if (type == 4)
            addEdge(b, a, 1);
        else
            addEdge(a, b, 0);
    }
    auto [count, component] = components(graph, reverse);
    vector<vector<pair<int, int>>> dag(count);
    vector<int> degree(count);
    for (auto e : edges) {
        int a = component[e.a], b = component[e.b];
        if (a == b) {
            if (e.w) {
                cout << -1;
                return 0;
            }
        } else {
            dag[a].push_back({b, e.w});
            degree[b]++;
        }
    }
    vector<int> queue;
    vector<long long> value(count, 1);
    for (int c = 0; c < count; c++)
        if (!degree[c])
            queue.push_back(c);
    for (size_t h = 0; h < queue.size(); h++) {
        int u = queue[h];
        for (auto [v, w] : dag[u]) {
            value[v] = max(value[v], value[u] + w);
            if (--degree[v] == 0)
                queue.push_back(v);
        }
    }
    long long answer = 0;
    for (int u = 0; u < n; u++)
        answer += value[component[u]];
    cout << answer;
    return 0;
}
```

### 复杂度

时间、空间均为 $O(N+K)$。

### 易错点

比较是整数，严格少于至少差1。相同编号的严格比较会形成1权自环，必须判无解。总数可能超过32位。

## [SDOI2008]仪仗队

### 题意

从方阵左下角观察，求不被同一直线上前方同学挡住的人数。

### 思路

以观察角为(0,0)，其余坐标0到N−1。正坐标点(x,y)可见当且仅当gcd(x,y)=1；否则沿同一射线先看到约去gcd后的格点。对x>y≥1按x分组，数量为phi(x)，关于对角线对称乘二；再加(1,1)及两个坐标轴上的首点。等价写成1+2*Σ(i=1..N−1)phi(i)。N=1没有其他人，答案0。用筛法初始化phi[i]=i，每个素数p对其倍数更新phi=phi/p*(p−1)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n == 1) {
        cout << 0;
        return 0;
    }
    vector<int> phi(n);
    iota(phi.begin(), phi.end(), 0);
    for (int p = 2; p < n; p++)
        if (phi[p] == p)
            for (int x = p; x < n; x += p)
                phi[x] = phi[x] / p * (p - 1);
    long long answer = 1;
    for (int i = 1; i < n; i++)
        answer += 2LL * phi[i];
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(N\log\log N)$，空间 $O(N)$。

### 易错点

实际坐标最大是N−1，不能把phi[N]也累加。phi[1]=1，已经把两条坐标轴的首个可见点计入公式。

## [SDOI2009]HH的项链

### 题意

多次查询静态颜色数组中，闭区间包含多少种不同颜色。

### 思路

将查询按右端点升序排列，依次把数组扫到当前右端。树状数组只在每种颜色最后出现的位置放一，较早的同色位置清零。这样，对于当前右端 R，颜色出现在 [L,R] 中，当且仅当它最后出现的位置不小于 L；树状数组的闭区间和就是不同颜色数。答案存回原查询编号，最后按输入顺序输出。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

class FastInput {
    static const int size = 1 << 16;
    char buffer[size];
    int position = 0, available = 0;
    int get() {
        if (position == available) {
            available = fread(buffer, 1, size, stdin);
            position = 0;
            if (!available)
                return EOF;
        }
        return buffer[position++];
    }

  public:
    int next() {
        int c = get(), sign = 1;
        while (c != '-' && (c < '0' || c > '9'))
            c = get();
        if (c == '-') {
            sign = -1;
            c = get();
        }
        long long x = 0;
        while (c >= '0' && c <= '9') {
            x = x * 10 + c - '0';
            c = get();
        }
        return (int)(x * sign);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    FastInput input;
    int n = input.next();
    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++)
        a[i] = input.next();
    int m = input.next();
    struct Query {
        int left, right, id;
    };
    vector<Query> queries(m);
    for (int i = 0; i < m; i++)
        queries[i] = {input.next(), input.next(), i};
    sort(queries.begin(), queries.end(),
         [](const Query &a, const Query &b) { return a.right < b.right; });
    vector<int> tree(n + 1), last(1000001), answer(m);
    auto change = [&](int position, int value) {
        for (int i = position; i <= n; i += i & -i)
            tree[i] += value;
    };
    auto sum = [&](int position) {
        int result = 0;
        for (int i = position; i > 0; i -= i & -i)
            result += tree[i];
        return result;
    };
    int right = 0;
    for (auto query : queries) {
        while (right < query.right) {
            right++;
            if (last[a[right]])
                change(last[a[right]], -1);
            change(right, 1);
            last[a[right]] = right;
        }
        answer[query.id] = sum(query.right) - sum(query.left - 1);
    }
    for (int value : answer)
        cout << value << '\n';
    return 0;
}
```

### 复杂度

时间 $O(m\log m+(n+m)\log n)$，空间 $O(n+m+V)$，颜色值域 $V=10^6$。

### 易错点

按题面备注中更大的范围支持一百万元素与询问，并支持颜色零。不能直接把每个出现位置都加一，那会得到长度而非种类数。

## [SDOI2016]征途

### 题意

将连续路段分成恰好m天，最小化日路程方差，输出方差乘m²。

### 思路

设总长S，m天路程为d[t]，方差乘m²等于m*Σd[t]²−S²，因此只需最小化每日路程平方和。用前缀和P，分层DP：new[i]=P[i]²+min(old[j]+P[j]²−2P[i]P[j])，j<i且j≥当前天数−1。每层重新建凸壳，直线斜率−2P[j]、截距old[j]+P[j]²，横坐标为P[i]。先查询再把j=i的旧层状态加入，确保每段至少有一个原路段。

直线斜率按非增顺序加入，查询横坐标非减。维护下凸壳：新线使末尾两线的交点顺序逆转时，删除中间线，交点顺序用交叉乘积精确比较。斜率相同时只保留截距更小者。查询时若第二条线不劣于第一条，就弹掉第一条；随着横坐标变大，它也不会重新更优。每条线至多进出队一次。代码用128位处理中间乘积，避免平方及交点比较溢出。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

using Wide = __int128;
struct MonotoneHull {
    struct Line {
        Wide slope, intercept;
        Wide at(Wide x) const { return slope * x + intercept; }
    };
    deque<Line> lines;
    void add(Wide slope, Wide intercept) {
        Line line{slope, intercept};
        while (!lines.empty() && lines.back().slope == slope) {
            if (lines.back().intercept <= intercept)
                return;
            lines.pop_back();
        }
        while (lines.size() >= 2) {
            auto a = lines[lines.size() - 2], b = lines.back();
            if ((b.intercept - a.intercept) * (b.slope - line.slope) <
                (line.intercept - b.intercept) * (a.slope - b.slope))
                break;
            lines.pop_back();
        }
        lines.push_back(line);
    }
    Wide minimum(Wide x) {
        while (lines.size() >= 2 && lines[1].at(x) <= lines[0].at(x))
            lines.pop_front();
        return lines.front().at(x);
    }
};
void printWide(Wide value) {
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string digits;
    do {
        digits += char('0' + value % 10);
        value /= 10;
    } while (value);
    reverse(digits.begin(), digits.end());
    cout << digits;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, days;
    cin >> n >> days;
    vector<Wide> prefix(n + 1);
    for (int i = 1; i <= n; i++) {
        long long x;
        cin >> x;
        prefix[i] = prefix[i - 1] + x;
    }
    const Wide inf = Wide(1) << 120;
    vector<Wide> previous(n + 1, inf), current(n + 1);
    previous[0] = 0;
    for (int day = 1; day <= days; day++) {
        fill(current.begin(), current.end(), inf);
        MonotoneHull hull;
        int initial = day - 1;
        hull.add(-2 * prefix[initial], previous[initial] + prefix[initial] * prefix[initial]);
        for (int i = day; i <= n; i++) {
            current[i] = prefix[i] * prefix[i] + hull.minimum(prefix[i]);
            if (previous[i] != inf)
                hull.add(-2 * prefix[i], previous[i] + prefix[i] * prefix[i]);
        }
        previous.swap(current);
    }
    printWide(days * previous[n] - prefix[n] * prefix[n]);
    return 0;
}
```

### 复杂度

时间 $O(mn)$，空间 $O(n)$。

### 易错点

不能漏乘m或误输出普通方差。每一层只用旧层值建线；费用与坐标取128位，避免上界或乘积影响比较。

## [SHOI2007]VOTE 善意的投票

### 题意

改变个人投票偏好与朋友分歧各付1，最少冲突。

### 思路

把源侧看作投1、汇侧看作投0。原偏好1者连源→人容量1，偏好0者连人→汇容量1，割掉时恰罚一次改票。朋友间连两个方向容量1，分在两侧时只有一个方向从源侧跨到汇侧，恰罚一次朋友分歧。总割容量与冲突数一一对应，求最大流。

Dinic先BFS建立剩余容量正边的层次图，再用当前弧DFS只沿层数加1的边增广，更新正反向残量；一轮阻塞流结束后重新分层。最大流等于最小割容量，反向残量允许撤回之前的分配。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Dinic {
    struct Edge {
        int to, reverse;
        long long capacity;
    };
    vector<vector<Edge>> graph;
    vector<int> level, current;
    explicit Dinic(int n) : graph(n), level(n), current(n) {}
    void resize(int n) {
        graph.resize(n);
        level.resize(n);
        current.resize(n);
    }
    int add(int u, int v, long long capacity) {
        int index = graph[u].size(), reverse = graph[v].size();
        graph[u].push_back({v, reverse, capacity});
        graph[v].push_back({u, index, 0});
        return index;
    }
    bool bfs(int source, int sink) {
        fill(level.begin(), level.end(), -1);
        vector<int> queue = {source};
        level[source] = 0;
        for (size_t i = 0; i < queue.size(); i++)
            for (auto e : graph[queue[i]])
                if (e.capacity > 0 && level[e.to] < 0) {
                    level[e.to] = level[queue[i]] + 1;
                    queue.push_back(e.to);
                }
        return level[sink] >= 0;
    }
    long long send(int u, int sink, long long amount) {
        if (u == sink)
            return amount;
        for (int &i = current[u]; i < (int)graph[u].size(); i++) {
            auto &e = graph[u][i];
            if (e.capacity > 0 && level[e.to] == level[u] + 1) {
                long long value = send(e.to, sink, min(amount, e.capacity));
                if (value) {
                    e.capacity -= value;
                    graph[e.to][e.reverse].capacity += value;
                    return value;
                }
            }
        }
        return 0;
    }
    long long maximum(int source, int sink, long long limit = LLONG_MAX / 4) {
        long long total = 0;
        while (total < limit && bfs(source, sink)) {
            fill(current.begin(), current.end(), 0);
            while (total < limit) {
                long long value = send(source, sink, limit - total);
                if (!value)
                    break;
                total += value;
            }
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    int source = n, sink = n + 1;
    Dinic flow(n + 2);
    for (int i = 0; i < n; i++) {
        int preference;
        cin >> preference;
        if (preference)
            flow.add(source, i, 1);
        else
            flow.add(i, sink, 1);
    }
    while (m--) {
        int u, v;
        cin >> u >> v;
        u--;
        v--;
        flow.add(u, v, 1);
        flow.add(v, u, 1);
    }
    cout << flow.maximum(source, sink);
    return 0;
}
```

### 复杂度

一般Dinic最坏 $O(V^2E)$，空间 $O(V+E)$。

### 易错点

朋友关系无向，两个方向各1；不是容量2。两侧含义必须与个人偏好边方向一致。

## 牛牛的三角形

### 题意

从数组中选三个不同位置的正数，组成任意一个非退化三角形。

### 思路

排序后只需检查相邻三项。若某三个数 x≤y≤z 能成三角形，选定 z 前面最大的两个数也不会更小，因此同样满足两短边之和大于长边。于是只要存在答案，某一组相邻三项一定是答案。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto &x : a)
        cin >> x;
    sort(a.begin(), a.end());
    for (int i = 2; i < n; i++)
        if (a[i - 2] + a[i - 1] > a[i]) {
            cout << a[i - 2] << ' ' << a[i - 1] << ' ' << a[i];
            return 0;
        }
    cout << "No solution";
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，数组空间 $O(n)$。

### 易错点

等号只能组成退化线段，不算三角形。同值元素可来自不同位置，不能去重。原题允许任意合法答案，验证按元素重数与三角不等式进行。

## 牛牛的木板

### 思路

把连续一段洗成全白，恰好要清洗其中所有的零，因此问题就是找至多含 m 个零的最长区间。右端每加入一个元素就更新零数；超过 m 时不断移出左端，直到合法。这样得到的是以当前右端结束的最长合法段，取所有长度的最大值。

### 参考代码

本题为函数题，保留原站的 `Solution::solve` 接口，直接返回答案。

```cpp
#include <bits/stdc++.h>
using namespace std;
class Solution {
  public:
    int solve(int n, int m, vector<int> &a) {
        int left = 0, zeros = 0, answer = 0;
        for (int right = 0; right < n; right++) {
            zeros += a[right] == 0;
            while (zeros > m) {
                zeros -= a[left] == 0;
                left++;
            }
            answer = max(answer, right - left + 1);
        }
        return answer;
    }
};
```

### 复杂度与易错点

左右指针都至多移动 n 次，时间 $O(n)$，额外空间 $O(1)$。一表示白色，零才需要清洗；不要求必须用完清洗剂。

## 中序序列

### 题意

由互异结点的先序与后序恢复中序，单个孩子固定视为左孩子。原站使用 `Solution::solve` 函数接口，返回数组，无需自行读取输入或输出。

### 思路

先序顺序决定新结点的出现顺序，后序顺序决定哪些子树已经结束。用栈保存尚未完成的祖先路径；准备放入下一个先序结点前，只要栈顶已等于后序中下一个待结束的结点，就将它弹出。剩余栈顶就是新结点父亲：还没有左孩子就挂左边，否则挂右边。这样唯一的一个孩子自然成为左孩子。建完树后，用显式栈完成中序遍历，避免十万层链上的递归栈溢出。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
class Solution {
  public:
    vector<int> solve(int n, vector<int> &pre, vector<int> &suf) {
        if (n == 0)
            return {};
        vector<int> left(n, -1), right(n, -1), path;
        int finished = 0;
        for (int i = 0; i < n; i++) {
            while (!path.empty() && finished < n && pre[path.back()] == suf[finished]) {
                path.pop_back();
                finished++;
            }
            if (!path.empty()) {
                int parent = path.back();
                if (left[parent] == -1)
                    left[parent] = i;
                else
                    right[parent] = i;
            }
            path.push_back(i);
        }
        vector<int> result, stack;
        int current = 0;
        while (current != -1 || !stack.empty()) {
            while (current != -1) {
                stack.push_back(current);
                current = left[current];
            }
            current = stack.back();
            stack.pop_back();
            result.push_back(pre[current]);
            current = right[current];
        }
        return result;
    }
};
```

### 复杂度

每个结点进出两次栈各一次，时间与数组空间均为 $O(n)$。

### 易错点

先序与后序本来不能唯一确定只有一个孩子时的左右关系，本题额外规定单孩子为左。原站给出的是参数与返回值样例，提交时保留指定类名、方法名和引用参数。

## [SHOI2017]期末考试

### 题意

通过调拨或增派老师提前成绩公告，连同学生等待费用，最小化总不愉快度。

### 思路

枚举所有课程最迟在第 D 天公布。晚于 D 的课程共需 need=Σmax(b[i]-D,0) 单位提前量；早于 D 的课程允许被推迟 room=Σmax(D-b[i],0) 单位，仍不超过 D。若调拨单价 A 比增派 B 便宜，就优先用 min(need,room) 单位调拨，其余增派；否则全用增派。学生等待费用为 C*Σmax(D-t[i],0)。

日期最大只有十万，可对 b 和 t 分别建立人数与日期和前缀，O(1) 求 need、room、等待天数，直接枚举 D=1 到 max(b)。超过原最迟日不会减少任何调整量，等待又只会增加，因此不需要。每个固定 D 的调整都能逐单位配对实现，取所有 D 的最小总费用就是答案。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long transfer, hire, wait;
    int n, m;
    cin >> transfer >> hire >> wait >> n >> m;
    const int limit = 100000;
    vector<long long> students(limit + 1), studentSum(limit + 1), courses(limit + 1),
        courseSum(limit + 1);
    for (int i = 0; i < n; i++) {
        int t;
        cin >> t;
        students[t]++;
        studentSum[t] += t;
    }
    int latest = 0;
    long long total = 0;
    for (int i = 0; i < m; i++) {
        int day;
        cin >> day;
        courses[day]++;
        courseSum[day] += day;
        total += day;
        latest = max(latest, day);
    }
    for (int day = 1; day <= limit; day++) {
        students[day] += students[day - 1];
        studentSum[day] += studentSum[day - 1];
        courses[day] += courses[day - 1];
        courseSum[day] += courseSum[day - 1];
    }
    long long answer = LLONG_MAX;
    for (long long day = 1; day <= latest; day++) {
        long long need = total - courseSum[day] - day * (m - courses[day]),
                  room = day * courses[day] - courseSum[day];
        long long moved = transfer < hire ? min(need, room) : 0;
        long long cost = moved * transfer + (need - moved) * hire +
                         (day * students[day] - studentSum[day]) * wait;
        answer = min(answer, cost);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

日期上限 $V=10^5$，时间 $O(n+m+V)$，空间 $O(V)$。

### 易错点

学生等待的是所有课程中的最晚公布日，不能按每门课分别计等待。调拨只能利用提前课程距离 D 的空余天数；把 A 与 B 比较后再决定是否值得调拨。

## 新集合

### 思路

n最多20，用二进制mask枚举所有子集。给每个数存不能与它同选的位集。去掉mask最低位得到rest；mask合法当且仅当rest合法，且新增数的禁配位集与rest不相交。每个mask常数次位运算即可，空集也算一种。

### 参考代码

原站已定义Point，提交时保留其x、y成员接口，无需重复定义。

```cpp
#include <bits/stdc++.h>
using namespace std;
// Point is supplied by the platform, with integer members x and y.
class Solution {
  public:
    int solve(int n, int m, vector<Point> &limit) {
        (void)m;
        vector<int> forbidden(n);
        for (auto p : limit) {
            forbidden[p.x - 1] |= 1 << (p.y - 1);
            forbidden[p.y - 1] |= 1 << (p.x - 1);
        }
        vector<bool> valid(1 << n);
        valid[0] = true;
        int answer = 1;
        for (int mask = 1; mask < (1 << n); mask++) {
            int bit = __builtin_ctz((unsigned)mask), rest = mask & (mask - 1);
            valid[mask] = valid[rest] && !(forbidden[bit] & rest);
            answer += valid[mask];
        }
        return answer;
    }
};
```

### 复杂度

时间O(m+2^n)，空间O(n+2^n)。

### 易错点

输入编号从1开始，压位前减一。限制重复不会多扣方案。

## 最大的差

### 题意

在 n 个整数中选两个，求最大的差值。

### 思路

任意差都不超过最大值减最小值，直接选这两个极值就能取到上界。读取时同时维护最大与最小值，最后相减。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    int lo = INT_MAX, hi = INT_MIN;
    for (int i = 0; i < n; i++) {
