            }
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int rows, cols;
    cin >> rows >> cols;
    int cells = rows * cols, source = cells, sink = cells + 1;
    Dinic flow(cells + 2);
    vector<long long> weight(cells);
    long long total = 0;
    for (auto &x : weight) {
        cin >> x;
        total += x;
    }
    const int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++) {
            int u = r * cols + c;
            if ((r + c) % 2 == 0) {
                flow.add(source, u, weight[u]);
                for (int d = 0; d < 4; d++) {
                    int rr = r + dr[d], cc = c + dc[d];
                    if (rr >= 0 && rr < rows && cc >= 0 && cc < cols)
                        flow.add(u, rr * cols + cc, total + 1);
                }
            } else
                flow.add(u, sink, weight[u]);
        }
    cout << total - flow.maximum(source, sink);
    return 0;
}
```

### 复杂度

一般Dinic最坏 $O(V²E)$，网格E=O(V)，空间 $O(V)$。

### 易错点

无穷容量取总权+1即可，不必取会溢出的极大值。答案是总权减割，不是割本身。

## [网络流24题]星际转移问题

### 题意

周期飞船运输k人从地球到月球，最短完成时间。

### 思路

先把每艘正容量飞船所停站点用并查集合并。允许任意等待，若地球与月球不在同一连通分量就永远无法转移，输出0；否则等待合适周期总能依次中转。

时间t建立每站副本，上一层站点到本层同站连容量k等待边；每艘飞船按其(t−1)模周期到t模周期的实际站点连容量H运输边。源只连t=0的地球，所有时刻月球连汇。逐天扩图，在已有残量网络上继续增广，首次总流达到k的天数即答案。等待边和运输边精确表示每人每分钟的合法选择。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, size;
    DSU(int n) : parent(n + 1), size(n + 1, 1) { iota(parent.begin(), parent.end(), 0); }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
};

struct Dinic {
    struct Edge {
        int to, reverse;
        long long capacity;
    };
    vector<vector<Edge>> graph;
    vector<int> level, current;
    explicit Dinic(int n) : graph(n), level(n), current(n) {}
    void resize(int n) {
        graph.resize(n);
        level.resize(n);
        current.resize(n);
    }
    int add(int u, int v, long long capacity) {
        int index = graph[u].size(), reverse = graph[v].size();
        graph[u].push_back({v, reverse, capacity});
        graph[v].push_back({u, index, 0});
        return index;
    }
    bool bfs(int source, int sink) {
        fill(level.begin(), level.end(), -1);
        vector<int> queue = {source};
        level[source] = 0;
        for (size_t i = 0; i < queue.size(); i++)
            for (auto e : graph[queue[i]])
                if (e.capacity > 0 && level[e.to] < 0) {
                    level[e.to] = level[queue[i]] + 1;
                    queue.push_back(e.to);
                }
        return level[sink] >= 0;
    }
    long long send(int u, int sink, long long amount) {
        if (u == sink)
            return amount;
        for (int &i = current[u]; i < (int)graph[u].size(); i++) {
            auto &e = graph[u][i];
            if (e.capacity > 0 && level[e.to] == level[u] + 1) {
                long long value = send(e.to, sink, min(amount, e.capacity));
                if (value) {
                    e.capacity -= value;
                    graph[e.to][e.reverse].capacity += value;
                    return value;
                }
            }
        }
        return 0;
    }
    long long maximum(int source, int sink, long long limit = LLONG_MAX / 4) {
        long long total = 0;
        while (total < limit && bfs(source, sink)) {
            fill(current.begin(), current.end(), 0);
            while (total < limit) {
                long long value = send(source, sink, limit - total);
                if (!value)
                    break;
                total += value;
            }
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    int stations = n + 2, moon = n + 1;
    struct Ship {
        int capacity;
        vector<int> route;
    };
    vector<Ship> ship(m);
    DSU dsu(stations);
    for (auto &s : ship) {
        int r;
        cin >> s.capacity >> r;
        s.route.resize(r);
        for (int &x : s.route) {
            cin >> x;
            if (x == -1)
                x = moon;
        }
        if (s.capacity > 0)
            for (int x : s.route)
                dsu.unite(s.route[0], x);
    }
    if (dsu.find(0) != dsu.find(moon)) {
        cout << 0;
        return 0;
    }
    auto vertex = [&](int time, int station) { return 2 + time * stations + station; };
    int source = 0, sink = 1;
    Dinic flow(2 + stations);
    flow.add(source, vertex(0, 0), k);
    flow.add(vertex(0, moon), sink, k);
    long long moved = 0;
    for (int day = 1;; day++) {
        flow.resize(2 + (day + 1) * stations);
        for (int s = 0; s < stations; s++)
            flow.add(vertex(day - 1, s), vertex(day, s), k);
        for (auto &s : ship) {
            int r = s.route.size();
            flow.add(vertex(day - 1, s.route[(day - 1) % r]), vertex(day, s.route[day % r]),
                     s.capacity);
        }
        flow.add(vertex(day, moon), sink, k);
        moved += flow.maximum(source, sink, k - moved);
        if (moved == k) {
            cout << day;
            break;
        }
    }
    return 0;
}
```

### 复杂度

若答案T，V=O(T(n+2))、E=O(T(n+m))；一般增量Dinic保守上界 $O(TV²E)$，实际复用既有流且总运量k≤50；空间 $O(V+E)$。

### 易错点

时刻0飞船在路线第一个站，第一分钟边是route[0]→route[1%r]。增量流要保留反向残量，允许重新分配早先乘客路线。

## [网络流24题]运输问题

### 题意

供需平衡运输，求最低与最高总费用。

### 思路

源→仓库容量供应，仓库→商店容量总货量、费用c，商店→汇容量需求。满流恰为合法全部运输方案，最小费用流给最小费用。再用独立网络把所有运输费用取负，求最小费用后取负得到最大费用。每次找残量最短路并增广瓶颈量，按流量乘路径费用累积。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct CostFlow {
    struct Edge {
        int to, reverse;
        long long capacity, cost;
    };
    vector<vector<Edge>> graph;
    explicit CostFlow(int n) : graph(n) {}
    void add(int u, int v, long long capacity, long long cost) {
        int a = graph[u].size(), b = graph[v].size();
        graph[u].push_back({v, b, capacity, cost});
        graph[v].push_back({u, a, 0, -cost});
    }
    pair<long long, long long> minimum(int source, int sink) {
        const long long inf = LLONG_MAX / 4;
        long long flow = 0, cost = 0;
        int n = graph.size();
        while (true) {
            vector<long long> distance(n, inf);
            vector<int> parent(n, -1), index(n);
            vector<bool> inQueue(n);
            queue<int> queue;
            queue.push(source);
            inQueue[source] = true;
            distance[source] = 0;
            while (!queue.empty()) {
                int u = queue.front();
                queue.pop();
                inQueue[u] = false;
                for (int i = 0; i < (int)graph[u].size(); i++) {
                    auto e = graph[u][i];
                    if (e.capacity > 0 && distance[e.to] > distance[u] + e.cost) {
                        distance[e.to] = distance[u] + e.cost;
                        parent[e.to] = u;
                        index[e.to] = i;
                        if (!inQueue[e.to]) {
                            inQueue[e.to] = true;
                            queue.push(e.to);
                        }
                    }
                }
            }
            if (parent[sink] < 0)
                break;
            long long amount = inf;
            for (int v = sink; v != source; v = parent[v])
                amount = min(amount, graph[parent[v]][index[v]].capacity);
            for (int v = sink; v != source; v = parent[v]) {
                auto &e = graph[parent[v]][index[v]];
                e.capacity -= amount;
                graph[v][e.reverse].capacity += amount;
            }
            flow += amount;
            cost += amount * distance[sink];
        }
        return {flow, cost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m, n;
    cin >> m >> n;
    vector<long long> supply(m), demand(n);
    long long total = 0;
    for (auto &x : supply) {
        cin >> x;
        total += x;
    }
    for (auto &x : demand)
        cin >> x;
    vector<vector<long long>> cost(m, vector<long long>(n));
    for (auto &row : cost)
        for (auto &x : row)
            cin >> x;
    auto solve = [&](int sign) {
        int source = m + n, sink = source + 1;
        CostFlow flow(sink + 1);
        for (int i = 0; i < m; i++)
            flow.add(source, i, supply[i], 0);
        for (int j = 0; j < n; j++)
            flow.add(m + j, sink, demand[j], 0);
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                flow.add(i, m + j, total, sign * cost[i][j]);
        return sign * flow.minimum(source, sink).second;
    };
    cout << solve(1) << '\n' << solve(-1);
    return 0;
}
```

### 复杂度

每次SPFA最坏 $O(VE)$，若增广A次总 $O(AVE)$，空间 $O(V+E)$。

### 易错点

两次计算必须新建网络，不能直接在已流满残量图上改费用。容量和总费用使用64位。

## [网络流24题]飞行员配对方案问题

### 题意

外籍与英国飞行员配对，求最大飞机数。

### 思路

把外籍编号1..m作为左侧，英国编号m+1..n作为右侧，给出的可配合关系连边。每人最多参与一次，所以最大匹配即最大可起飞飞机数。输入只要求输出数量，无需输出配对。

参考代码使用Hopcroft–Karp：从所有未匹配左点BFS标记最短增广路层数，再DFS沿这些层同时增广。每条增广路将匹配边与非匹配边交替翻转，匹配数增加1；不存在增广路时已达最大匹配。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Matching {
    int left, right, shortest;
    vector<vector<int>> edge;
    vector<int> mateLeft, mateRight, distance;
    Matching(int left, int right)
        : left(left), right(right), edge(left), mateLeft(left, -1), mateRight(right, -1),
          distance(left) {}
    bool bfs() {
        queue<int> queue;
        fill(distance.begin(), distance.end(), -1);
        for (int u = 0; u < left; u++)
            if (mateLeft[u] < 0) {
                distance[u] = 0;
                queue.push(u);
            }
        shortest = INT_MAX;
        while (!queue.empty()) {
            int u = queue.front();
            queue.pop();
            if (distance[u] + 1 > shortest)
                continue;
            for (int v : edge[u])
                if (mateRight[v] < 0)
                    shortest = min(shortest, distance[u] + 1);
                else if (distance[mateRight[v]] < 0) {
                    distance[mateRight[v]] = distance[u] + 1;
                    queue.push(mateRight[v]);
                }
        }
        return shortest < INT_MAX;
    }
    bool dfs(int u) {
        for (int v : edge[u])
            if ((mateRight[v] < 0 && distance[u] + 1 == shortest) ||
                (mateRight[v] >= 0 && distance[mateRight[v]] == distance[u] + 1 &&
                 dfs(mateRight[v]))) {
                mateLeft[u] = v;
                mateRight[v] = u;
                return true;
            }
        distance[u] = -1;
        return false;
    }
    int maximum() {
        int result = 0;
        while (bfs())
            for (int u = 0; u < left; u++)
                if (mateLeft[u] < 0 && dfs(u))
                    result++;
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    Matching match(m, n - m);
    int u, v;
    while (cin >> u >> v && u > 0 && v > 0)
        match.edge[u - 1].push_back(v - m - 1);
    cout << match.maximum();
    return 0;
}
```

### 复杂度

时间 $O(E\sqrt n)$，空间 $O(n+E)$。

### 易错点

当前题第一行先总人数n、后外籍数m，与某些原题版本顺序不同；按此页样例10 5读取。

## 芭芭拉冲鸭~（续）

### 题意

树路径上收集字母，可重排部分字母，求最长回文长度。

### 思路

任意字母可成对放在回文两侧，最多留下一个奇数频次字母放中心。路径长len、奇数频次字母数odd时，答案为len−max(0,odd−1)。用26位掩码记录根路径上字母频次奇偶，路径掩码为mask[x] xor mask[y] xor (1<<字母[LCA])，popcount得到odd。长度由深度和LCA求出。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct EulerTree {
    int n;
    vector<vector<int>> edge;
    vector<int> parent, depth, in, out, order;
    EulerTree(int n) : n(n), edge(n + 1), parent(n + 1), depth(n + 1), in(n + 1), out(n + 1) {}
    void add(int u, int v) {
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    void root(int start) {
        vector<int> stack = {start};
        parent[start] = 0;
        order.clear();
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            in[u] = order.size() + 1;
            order.push_back(u);
            for (int v : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack.push_back(v);
                }
        }
        vector<int> size(n + 1, 1);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            out[u] = in[u] + size[u] - 1;
            if (parent[u])
                size[parent[u]] += size[u];
        }
    }
};

struct Ancestors {
    const EulerTree &tree;
    vector<vector<int>> up;
    Ancestors(const EulerTree &tree) : tree(tree) {
        int levels = 1;
        while ((1LL << levels) <= tree.n)
            levels++;
        up.assign(levels, vector<int>(tree.n + 1));
        up[0] = tree.parent;
        for (int b = 1; b < levels; b++)
            for (int u = 1; u <= tree.n; u++)
                up[b][u] = up[b - 1][up[b - 1][u]];
    }
    int lca(int u, int v) const {
        if (tree.depth[u] < tree.depth[v])
            swap(u, v);
        int gap = tree.depth[u] - tree.depth[v];
        for (int b = 0; b < (int)up.size(); b++)
            if (gap >> b & 1)
                u = up[b][u];
        if (u == v)
            return u;
        for (int b = (int)up.size() - 1; b >= 0; b--)
            if (up[b][u] != up[b][v]) {
                u = up[b][u];
                v = up[b][v];
            }
        return up[0][u];
    }
    int distance(int u, int v) const {
        return tree.depth[u] + tree.depth[v] - 2 * tree.depth[lca(u, v)];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    EulerTree tree(n);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        tree.add(u, v);
    }
    string s;
    cin >> s;
    tree.root(1);
    Ancestors ancestor(tree);
    vector<unsigned> mask(n + 1);
    for (int u : tree.order)
        mask[u] = mask[tree.parent[u]] ^ (1U << (s[u - 1] - 'a'));
    int q;
    cin >> q;
    while (q--) {
        int x, y;
        cin >> x >> y;
        int a = ancestor.lca(x, y), length = tree.depth[x] + tree.depth[y] - 2 * tree.depth[a] + 1;
        int odd = __builtin_popcount(mask[x] ^ mask[y] ^ (1U << (s[a - 1] - 'a')));
        cout << length - max(0, odd - 1) << '\n';
    }
    return 0;
}
```

### 复杂度

预处理 $O(n\log n)$，每问 $O(\log n)$，空间 $O(n\log n)$。

### 易错点

LCA在两个前缀掩码中抵消，必须补回它的字母。题目允许重排，不是路径上的最长回文子串。

## lcryin的排序题

