### 复杂度

每组时间 $O(2^6\cdot5\cdot6)$，空间 $O(5\cdot6)$。

### 易错点

输出的是按键矩阵，不是最终灯状态。按题目保证可解的固定规格处理。

## 月月查华华的手机

### 题意

预处理一个长串，多次判断给定字符串是否为其子序列。

### 思路

分别保存每种字母在 s 中出现的所有下标。匹配一个查询时，维护已匹配到的位置 previous；对查询的每个字母，在它的下标列表里二分找第一个大于 previous 的位置。找不到就失败。每次尽量用最早位置，只会给后续留下更多空间，因此贪心匹配充分且必要。相比每次扫描完整 s，查询只处理自身字符。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    cin >> s;
    vector<int> positions[26];
    for (int i = 0; i < (int)s.size(); i++)
        positions[s[i] - 'a'].push_back(i);
    int q;
    cin >> q;
    while (q--) {
        string t;
        cin >> t;
        int previous = -1;
        bool valid = true;
        for (char c : t) {
            const auto &v = positions[c - 'a'];
            auto it = upper_bound(v.begin(), v.end(), previous);
            if (it == v.end()) {
                valid = false;
                break;
            }
            previous = *it;
        }
        cout << (valid ? "Yes\n" : "No\n");
    }
    return 0;
}
```

### 复杂度

设查询总长度为 $Q$，时间 $O(|s|+Q\log |s|)$，额外索引空间 $O(|s|)$。

### 易错点

下一位置必须严格大于上一位置，重复字母不能复用同一下标。每条查询都要从 previous=-1 重新开始。

## 华华开始学信息学

### 题意

给所有D倍数位置加K，询问区间和。

### 思路

按D大小分治。D≤B时，只累积small[D]，询问时该更新在[L,R]中的贡献是small[D]*(floor(R/D)−floor((L−1)/D))。D>B时，倍数至多N/B个，逐点加进树状数组；询问再加树状数组区间和。两类更新相互独立，可直接相加。代码取B约为sqrt(N log N)，平衡小D询问与大D逐点修改。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> tree;
    Fenwick(int n) : n(n), tree(n + 1) {}
    void add(int p, long long v) {
        for (; p <= n; p += p & -p)
            tree[p] += v;
    }
    long long sum(int p) {
        long long result = 0;
        for (; p; p -= p & -p)
            result += tree[p];
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    int boundary = max(1, (int)sqrt(n * max(1.0, log2(n + 1.0))));
    boundary = min(boundary, n);
    vector<long long> small(boundary + 1);
    Fenwick bit(n);
    while (m--) {
        int op, l;
        long long r;
        cin >> op >> l >> r;
        if (op == 1) {
            if (l <= boundary)
                small[l] += r;
            else
                for (int p = l; p <= n; p += l)
                    bit.add(p, r);
        } else {
            long long answer = bit.sum((int)r) - bit.sum(l - 1);
            for (int d = 1; d <= boundary; d++)
                answer += small[d] * (r / d - (l - 1) / d);
            cout << answer << '\n';
        }
    }
    return 0;
}
```

### 复杂度

修改最坏 $O((N/B)\log N)$，询问 $O(B+\log N)$，空间 $O(N+B)$。

### 易错点

多次小D更新要累加，不能覆盖。K至10^8、操作十万次，权值及区间和均用64位。

## Closest Pair of Segments

### 题意

互不相交的n条线段之间，求最近距离。

### 思路

两条线段最近点至少有一个是端点，因此两线段距离是四个“端点到另一线段距离”的最小值。为避免枚举全部线段对，二分距离d，把每条线段膨胀半径d/2，得到线段加圆盘的胶囊形；存在两胶囊相交，当且仅当原线段最近距离≤d。

每个胶囊是凸集，竖直截面是区间。按最左x−d/2插入、最右x+d/2删除，用有序集合维护竖直次序，每次只检查新增邻居的两胶囊是否相交。尚未相交时相对上下次序稳定；首次接触前必成为邻居。比较时可取原线段在扫描x处的y，x超出原线段范围时夹到最近端点；这个点总在胶囊截面内，足以确定两个不相交胶囊的次序，竖直线段取中点y。

插入序列与删除序列分别只需按原线段最左、最右x排序一次，每轮二分线性归并这两个事件序列。原线段互不相交是题目保证，所以距离计算无需再做线段相交分支。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

struct Segment {
    Point a, b;
};
vector<Segment> segment;
long double sweepX, threshold;
long double height(int i) {
    auto [a, b] = segment[i];
    if (a.x == b.x)
        return (a.y + b.y) / 2;
    long double x = clamp(sweepX, a.x, b.x);
    return a.y + (b.y - a.y) * (x - a.x) / (b.x - a.x);
}
struct Order {
    bool operator()(int a, int b) const {
        long double x = height(a), y = height(b);
        return x != y ? x < y : a < b;
    }
};
long double pointDistance(Point p, const Segment &s) {
    Point e = s.b - s.a;
    long double t = clamp(dot(p - s.a, e) / dot(e, e), 0.0L, 1.0L);
    return distance(p, s.a + e * t);
}
long double segmentDistance(int i, int j) {
    auto a = segment[i], b = segment[j];
    return min({pointDistance(a.a, b), pointDistance(a.b, b), pointDistance(b.a, a),
                pointDistance(b.b, a)});
}
bool within(long double gap, const vector<int> &start, const vector<int> &finish) {
    int n = segment.size();
    long double radius = gap / 2;
    set<int, Order> active;
    vector<set<int, Order>::iterator> position(n);
    auto close = [&](int a, int b) { return segmentDistance(a, b) <= gap; };
    int i = 0, j = 0;
    while (i < n || j < n) {
        bool enter =
            j == n || (i < n && segment[start[i]].a.x - radius <= segment[finish[j]].b.x + radius);
        int id = enter ? start[i++] : finish[j++];
        sweepX = enter ? segment[id].a.x - radius : segment[id].b.x + radius;
        if (enter) {
            auto it = active.insert(id).first;
            position[id] = it;
            if (it != active.begin() && close(*prev(it), *it))
                return true;
            if (next(it) != active.end() && close(*it, *next(it)))
                return true;
        } else {
            auto it = position[id], right = next(it);
            if (it != active.begin() && right != active.end() && close(*prev(it), *right))
                return true;
            active.erase(it);
        }
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        cin >> n;
        segment.resize(n);
        vector<int> start(n), finish(n);
        for (int i = 0; i < n; i++) {
            auto &s = segment[i];
            cin >> s.a.x >> s.a.y >> s.b.x >> s.b.y;
            if (s.a.x > s.b.x)
                swap(s.a, s.b);
            start[i] = finish[i] = i;
        }
        sort(start.begin(), start.end(),
             [](int a, int b) { return segment[a].a.x < segment[b].a.x; });
        sort(finish.begin(), finish.end(),
             [](int a, int b) { return segment[a].b.x < segment[b].b.x; });
        long double l = 0, r = segmentDistance(0, 1);
        for (int i = 1; i < min(n, 100); i++)
            r = min(r, segmentDistance(i - 1, i));
        for (int i = 0; i < 55; i++) {
            long double mid = (l + r) / 2;
            if (within(mid, start, finish))
                r = mid;
            else
                l = mid;
        }
        cout << fixed << setprecision(15) << r << '\n';
    }
    return 0;
}
```

### 复杂度

时间 $O(n\log n\log(C/\varepsilon))$，空间 $O(n)$。

### 易错点

只比较原始端点的最近点对会漏掉“端点到长线段内部”的距离。胶囊的排序代表点必须落在当前竖直截面内，不能无限外推原直线。

## A Bite of Teyvat

### 题意

圆心全部在x轴，每插入一个圆盘立即求总覆盖面积。

### 思路

上半圆高度平方是$r_i^2-(x-x_i)^2=-x^2+(2x_i x+r_i^2-x_i^2)$。公共项−x²不影响最大值，所以圆盘并的上边界，由直线$L_i(x)=2x_i x+r_i^2-x_i^2$的上包络决定。再将负的高度平方截为0，下半平面对称。

用按斜率有序的map维护上凸壳。相同圆心只保留最大半径；若连续三条线的相邻交点不递增，中间线永远不胜出，应删除。插入后只可能删掉两侧相邻的一段线，每条线至多被删一次。交点次序用128位整数比较。

每条保留线在与左右邻线的交点之间获胜，再与该圆自己的[x_i−r_i,x_i+r_i]相交。这个区间的面积贡献为2倍上半圆积分，其原函数为t*sqrt(r²−t²)+r²*asin(t/r)，t=x−x_i。插入、删除一条线，只会改动它和左右邻线的贡献：先减旧贡献，变更map，再加新贡献。用long double和补偿求和控制大量面积增减的误差。

