### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

using Wide = __int128_t;
struct Disc {
    long long x, r;
    long long intercept() const { return r * r - x * x; }
};
map<long long, Disc> hull;
long double total = 0, compensation = 0;
void accumulate(long double value) {
    long double adjusted = value - compensation, next = total + adjusted;
    compensation = (next - total) - adjusted;
    total = next;
}
long double contribution(map<long long, Disc>::iterator it) {
    if (it == hull.end())
        return 0;
    Disc d = it->second;
    long double l = d.x - d.r, r = d.x + d.r;
    auto crossing = [](const auto &a, const auto &b) {
        return (long double)(a.second.intercept() - b.second.intercept()) / (b.first - a.first);
    };
    if (it != hull.begin())
        l = max(l, crossing(*prev(it), *it));
    if (next(it) != hull.end())
        r = min(r, crossing(*it, *next(it)));
    if (l >= r)
        return 0;
    auto primitive = [&](long double x) {
        long double t = clamp(x - d.x, -(long double)d.r, (long double)d.r), radius = d.r;
        return t * sqrtl(max(0.0L, radius * radius - t * t)) +
               radius * radius * asinl(clamp(t / radius, -1.0L, 1.0L));
    };
    return primitive(r) - primitive(l);
}
void eraseLine(map<long long, Disc>::iterator it) {
    auto left = it == hull.begin() ? hull.end() : prev(it), right = next(it);
    accumulate(-contribution(left));
    accumulate(-contribution(it));
    accumulate(-contribution(right));
    hull.erase(it);
    accumulate(contribution(left));
    accumulate(contribution(right));
}
bool redundant(map<long long, Disc>::iterator it) {
    if (it == hull.begin() || next(it) == hull.end())
        return false;
    auto a = prev(it), b = it, c = next(it);
    return (Wide)(a->second.intercept() - b->second.intercept()) * (c->first - b->first) >=
           (Wide)(b->second.intercept() - c->second.intercept()) * (b->first - a->first);
}
void insertDisc(Disc d) {
    long long slope = 2 * d.x;
    auto old = hull.find(slope);
    if (old != hull.end()) {
        if (old->second.r >= d.r)
            return;
        eraseLine(old);
    }
    auto right = hull.lower_bound(slope), left = right == hull.begin() ? hull.end() : prev(right);
    accumulate(-contribution(left));
    accumulate(-contribution(right));
    auto it = hull.emplace(slope, d).first;
    accumulate(contribution(left));
    accumulate(contribution(it));
    accumulate(contribution(right));
    if (redundant(it)) {
        eraseLine(it);
        return;
    }
    while (it != hull.begin() && redundant(prev(it)))
        eraseLine(prev(it));
    while (next(it) != hull.end() && redundant(next(it)))
        eraseLine(next(it));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    while (n--) {
        Disc d;
        cin >> d.x >> d.r;
        insertDisc(d);
        cout << fixed << setprecision(12) << max(0.0L, total) << '\n';
    }
    return 0;
}
```

### 复杂度

总时间 $O(n\log n)$，空间 $O(n)$；每条线只插入、删除一次。

### 易错点

圆盘不能只按相邻圆心的两圆交面积容斥，会漏掉多圆重叠及包含。包络线即使在某段高度平方为负，也应保留到几何积分时再截零。

## Devu and Flowers

### 题意

n种花各有上限f，恰选s朵的方案数。

### 思路

无上限时非负解数量为C(s+n−1,n−1)。对违反第i种上限的变量先减f[i]+1，再用容斥枚举违规集合S：贡献(-1)^|S|*C(s−Σ(f[i]+1)+n−1,n−1)，剩余量为负时贡献0。

组合数上项可达10^14，但下项n−1≤19且小于模数，直接连乘上项起的n−1个因子，再乘(n−1)!逆元即可。这是整数多项式恒等式，允许上项大于模数，不必把整个阶乘预处理到上项。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long long mod = 1000000007;
long long power(long long a, long long b) {
    long long result = 1;
    while (b) {
        if (b & 1)
            result = result * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return result;
}
struct Combinations {
    vector<long long> factorial, inverse;
    Combinations(int n) : factorial(n + 1, 1), inverse(n + 1) {
        for (int i = 1; i <= n; i++)
            factorial[i] = factorial[i - 1] * i % mod;
        inverse[n] = power(factorial[n], mod - 2);
        for (int i = n; i >= 1; i--)
            inverse[i - 1] = inverse[i] * i % mod;
    }
    long long choose(int n, int k) const {
        if (k < 0 || k > n)
            return 0;
        return factorial[n] * inverse[k] % mod * inverse[n - k] % mod;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long s;
    cin >> n >> s;
    vector<long long> f(n);
    for (auto &x : f)
        cin >> x;
    long long factorial = 1;
    for (int i = 1; i < n; i++)
        factorial = factorial * i % mod;
    long long inverse = power(factorial, mod - 2);
    int size = 1 << n;
    vector<long long> removed(size);
    long long answer = 0;
    for (int mask = 0; mask < size; mask++) {
        if (mask) {
            int bit = __builtin_ctz((unsigned)mask);
            removed[mask] = removed[mask & (mask - 1)] + f[bit] + 1;
        }
        long long remaining = s - removed[mask];
        if (remaining < 0)
            continue;
        long long ways = inverse;
        for (int j = 1; j < n; j++)
            ways = ways * ((remaining + j) % mod) % mod;
        if (__builtin_popcount((unsigned)mask) & 1)
            answer = (answer - ways + mod) % mod;
        else
            answer = (answer + ways) % mod;
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n2^n+\log P)$，空间 $O(2^n+n)$。

### 易错点

上限f允许取等号，违规时应平移f+1。n=1时组合式为空乘积1，容斥自动判是否超上限。

## Blocks

### 题意

四种颜色长n序列，红绿数量均为偶数。

### 思路

对红、绿的次数分别用(1+(-1)^count)/2筛偶数，展开四项。代入每种颜色的权值，四个总权和分别为4、2、2、0，所以答案(4^n+2*2^n+0^n)/4。n≥1，最后一项为0，快速幂模10007，乘4逆元2502。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    const long long mod = 10007;
    auto power = [&](long long a, int n) {
        long long result = 1;
        while (n) {
            if (n & 1)
                result = result * a % mod;
            a = a * a % mod;
            n >>= 1;
        }
        return result;
    };
    while (tests--) {
        int n;
        cin >> n;
        cout << (power(4, n) + 2 * power(2, n)) % mod * 2502 % mod << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O(\log n)$，空间 $O(1)$。

### 易错点

两种颜色各自为偶数，比它们数量之和为偶数更严格。n=0不在输入范围内。

## Strange_Functions

### 题意

判断每个函数能否在某个自变量处严格小于其他所有函数。

### 思路

反正切在非负数上单调。把比较量$k_i/|\cos(x-a_i)|$取倒数，等价于让$|\cos(x-a_i)|/k_i$严格最大。展开余弦，令$v_i=(\cos a_i/k_i,\sin a_i/k_i)$、$u=(\cos x,\sin x)$，就是最大化$|u\cdot v_i|=\max(u\cdot v_i,u\cdot(-v_i))$。

因此构造所有±v_i的凸包。某个函数能够严格胜出，当且仅当它的一个点是严格凸包顶点，且该坐标没有另一个函数重复：顶点有一段非空外法向角域使它唯一取最大；边内点与内部点均不能唯一最大。a的单位为弧度，直接计算sin/cos，不转成度。删除共线中间点，最终标记保留下来的顶点所属函数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    struct Vertex {
        long double x, y;
        int id;
    };
    vector<Vertex> p;
    for (int i = 0; i < n; i++) {
        long double k, a;
        cin >> k >> a;
        long double x = cosl(a) / k, y = sinl(a) / k;
        p.push_back({x, y, i});
        p.push_back({-x, -y, i});
    }
    sort(p.begin(), p.end(), [](auto a, auto b) { return a.x != b.x ? a.x < b.x : a.y < b.y; });
    auto turn = [](Vertex a, Vertex b, Vertex c) {
        return (b.x - a.x) * (c.y - b.y) - (b.y - a.y) * (c.x - b.x);
    };
    vector<Vertex> hull;
    for (auto q : p) {
        while (hull.size() >= 2 && turn(hull[hull.size() - 2], hull.back(), q) <= 0)
            hull.pop_back();
        hull.push_back(q);
    }
    int lower = hull.size();
    for (int i = (int)p.size() - 2; i >= 0; i--) {
        while ((int)hull.size() > lower && turn(hull[hull.size() - 2], hull.back(), p[i]) <= 0)
            hull.pop_back();
        hull.push_back(p[i]);
    }
    if (hull.size() > 1)
        hull.pop_back();
    string answer(n, '0');
    for (auto q : hull)
        answer[q.id] = '1';
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

输入保证(k,a)不重复，a为整数弧度；非零整数不可能恰为π的整数倍，故不同函数不会产生完全相同的±v。用long double计算，不设过大绝对EPS去吞掉小半径凸包转角。

## Steadily Growing Steam

### 题意

选择卡牌分两组点数相等，可将至多k张点数翻倍，最大总价值。

### 思路

用差值D=两组点数差，维度j表示已经翻倍的张数。每张卡有五种有效去向：不选、正常放左/右、翻倍后放左/右；只要选中，不论哪组都加同一个v。用旧表转移到新表，防止重复使用。点数每张至13，全部翻倍后绝对差至2600，数组范围固定；最后在D=0、j≤k中取最大，空集给0。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<pair<long long, int>> card(n);
    int total = 0;
    for (auto &[v, t] : card) {
        cin >> v >> t;
        total += 2 * t;
    }
    int width = 2 * total + 1;
    const long long negative = LLONG_MIN / 4;
    vector<long long> dp((k + 1) * width, negative);
    dp[total] = 0;
    int processed = 0;
    for (auto [value, point] : card) {
        auto next = dp;
        for (int doubled = 0; doubled <= min(k, processed); doubled++)
            for (int d = -total; d <= total; d++) {
                long long old = dp[doubled * width + d + total];
                if (old == negative)
                    continue;
                for (int sign : {-1, 1}) {
                    int normal = d + sign * point;
                    if (abs(normal) <= total)
                        next[doubled * width + normal + total] =
                            max(next[doubled * width + normal + total], old + value);
                    int large = d + sign * 2 * point;
                    if (doubled < k && abs(large) <= total)
                        next[(doubled + 1) * width + large + total] =
                            max(next[(doubled + 1) * width + large + total], old + value);
                }
            }
        dp.swap(next);
        processed++;
    }
    long long answer = 0;
    for (int j = 0; j <= k; j++)
        answer = max(answer, dp[j * width + total]);
    cout << answer;
    return 0;
}
```

### 复杂度

总翻倍点数和B≤2600，时间 $O(nkB)$，空间 $O(kB)$。

### 易错点

负价值卡可能帮助点数平衡，不能直接删掉。翻倍的是点数t，价值v不翻倍。

## Partitions

### 题意

分成k个非空无序集合，权为每块大小乘块内权和，求全部划分权值和。

### 思路

固定一个元素i，其权w[i]在每个划分中乘所在块大小。块大小可写成1+Σ(j≠i)[j与i同块]。全部划分的第一项计S(n,k)次；对固定j，把i、j合并为一个元素，同块划分数为S(n−1,k)。故每个w的系数相同，为S(n,k)+(n−1)S(n−1,k)，乘总权值即可。

使用S(N,k)=Σ(i=0..k)(−1)^(k−i)*i^N/(i!*(k−i)!)，两式合并成Σ符号*i^(n−1)*(i+n−1)/(i!*(k−i)!)，预处理逆阶乘，每项一次快速幂。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long long mod = 1000000007;
long long power(long long a, long long b) {
    long long result = 1;
    while (b) {
        if (b & 1)
            result = result * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return result;
}
struct Combinations {
    vector<long long> factorial, inverse;
    Combinations(int n) : factorial(n + 1, 1), inverse(n + 1) {
        for (int i = 1; i <= n; i++)
            factorial[i] = factorial[i - 1] * i % mod;
        inverse[n] = power(factorial[n], mod - 2);
        for (int i = n; i >= 1; i--)
            inverse[i - 1] = inverse[i] * i % mod;
    }
    long long choose(int n, int k) const {
        if (k < 0 || k > n)
            return 0;
        return factorial[n] * inverse[k] % mod * inverse[n - k] % mod;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        long long x;
        cin >> x;
        sum = (sum + x) % mod;
    }
    Combinations comb(k);
    long long coefficient = 0;
    for (int i = 0; i <= k; i++) {
        long long term =
            power(i, n - 1) * (i + n - 1) % mod * comb.inverse[i] % mod * comb.inverse[k - i] % mod;
        if ((k - i) & 1)
            coefficient = (coefficient - term + mod) % mod;
        else
            coefficient = (coefficient + term) % mod;
    }
    cout << coefficient * sum % mod;
    return 0;
}
```

### 复杂度

时间 $O(n+k\log n+\log P)$，空间 $O(k)$。

### 易错点

集合块无编号，因此用第二类Stirling数，不能额外乘k!。n=1时0次幂按1，公式仍成立。

## Magic Rabbit

### 题意

三瓶浓度按非负比例混合，查询能否得到目标两维浓度。

### 思路

混合浓度是三个浓度点按体积比例的凸组合，因此目标能配出当且仅当在三点凸包中。非共线时用三条边叉积同号或0判断三角形内部含边界；共线时凸包为线段，检查点是否在任意一对端点的闭线段上，也支持三瓶完全相同。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    array<Point, 3> a;
    for (auto &p : a)
        cin >> p.x >> p.y;
    long double area = cross(a[1] - a[0], a[2] - a[0]);
    int n;
    cin >> n;
    while (n--) {
        Point p;
        cin >> p.x >> p.y;
        bool ok = false;
        if (area == 0) {
            for (int i = 0; i < 3; i++) {
                Point x = a[i], y = a[(i + 1) % 3];
                if (cross(y - x, p - x) == 0 && dot(p - x, p - y) <= 0)
                    ok = true;
            }
        } else {
            long double x = cross(a[1] - a[0], p - a[0]), y = cross(a[2] - a[1], p - a[1]),
                        z = cross(a[0] - a[2], p - a[2]);
            ok = (x >= 0 && y >= 0 && z >= 0) || (x <= 0 && y <= 0 && z <= 0);
        }
        cout << (ok ? "YES\n" : "NO\n");
    }
    return 0;
}
```

### 复杂度

每问时间 $O(1)$，空间 $O(1)$。

### 易错点

可以不使用某瓶，故边界可行。不能随意加入纯水；只有给定三瓶的凸组合可用。

## [2016WF]Oil

### 题意

一条钻井直线穿过水平油层，最大总宽度。

### 思路

最优非水平直线可平移到某层端点而不损失已穿过的层，枚举2n个端点P。用“水平位移/竖直位移”作为无向直线斜率参数，每个不同高度油层对应一个闭参数区间，两端为(x0−Px)/(y−Py)、(x1−Px)/(y−Py)，权重是油层宽。求所有闭区间的最大覆盖权值，再加P所在层宽。

同高的其他油层与非水平井不可能同时经过，直接忽略。事件比较用有理数交叉乘，分母统一为正；相同参数先加后减，保证端点接触也计入。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    struct Layer {
        long long l, r, y;
    };
    vector<Layer> layer(n);
    for (auto &a : layer) {
        cin >> a.l >> a.r >> a.y;
        if (a.l > a.r)
            swap(a.l, a.r);
    }
    struct Event {
        long long numerator, denominator, delta;
    };
    long long answer = 0;
    for (int pivot = 0; pivot < n; pivot++)
        for (long long px : {layer[pivot].l, layer[pivot].r}) {
            long long py = layer[pivot].y;
            vector<Event> event;
            for (int i = 0; i < n; i++)
                if (layer[i].y != py) {
                    long long denominator = layer[i].y - py, a = layer[i].l - px,
                              b = layer[i].r - px;
                    if (denominator < 0) {
                        denominator = -denominator;
                        a = -a;
                        b = -b;
                    }
                    if (a > b)
                        swap(a, b);
                    long long weight = layer[i].r - layer[i].l;
                    event.push_back({a, denominator, weight});
                    event.push_back({b, denominator, -weight});
                }
            sort(event.begin(), event.end(), [](auto a, auto b) {
                __int128 x = (__int128)a.numerator * b.denominator,
                         y = (__int128)b.numerator * a.denominator;
                return x != y ? x < y : a.delta > b.delta;
            });
            long long current = layer[pivot].r - layer[pivot].l;
            answer = max(answer, current);
            for (auto e : event) {
                current += e.delta;
                answer = max(answer, current);
            }
        }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n²\log n)$，空间 $O(n)$。

### 易错点

水平井不能从地表下钻到地下同高油层，样例2不能把两条同高不相交层相加。零宽点层权为0。

## [POI2008]Tro

### 题意

求所有三点三角形面积总和。

### 思路

固定顶点P，将其余向量极角排序。对每个向量v，用双指针找到逆时针半周内的全部向量w，使cross(v,w)≥0（同方向零叉积无影响，反方向端点不计）。这些叉积之和等于cross(v,Σw)，用向量前缀和常数计算。

每个非共线无序向量对恰按正叉积方向计一次。每个三角形又会在三个顶点各贡献一次“二倍面积”，所以全部累计除3得到二倍面积总和，再按整数或半整数输出一位小数。128位累加防止三角形数量放大总量。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

using Wide = __int128_t;
struct IPoint {
    long long x = 0, y = 0;
    IPoint operator+(IPoint b) const { return {x + b.x, y + b.y}; }
    IPoint operator-(IPoint b) const { return {x - b.x, y - b.y}; }
};
Wide cross(IPoint a, IPoint b) { return (Wide)a.x * b.y - (Wide)a.y * b.x; }
Wide dot(IPoint a, IPoint b) { return (Wide)a.x * b.x + (Wide)a.y * b.y; }
Wide absolute(Wide x) { return x < 0 ? -x : x; }
void printWide(Wide value) {
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string text;
    do {
        text.push_back('0' + value % 10);
        value /= 10;
    } while (value);
    reverse(text.begin(), text.end());
    cout << text;
}
bool angleLess(IPoint a, IPoint b) {
    auto half = [](IPoint p) { return p.y < 0 || (p.y == 0 && p.x < 0); };
    if (half(a) != half(b))
        return half(a) < half(b);
    return cross(a, b) > 0;
}
vector<IPoint> integerHull(vector<IPoint> point) {
    sort(point.begin(), point.end(),
         [](auto a, auto b) { return a.x != b.x ? a.x < b.x : a.y < b.y; });
    point.erase(
        unique(point.begin(), point.end(), [](auto a, auto b) { return a.x == b.x && a.y == b.y; }),
        point.end());
    if (point.size() < 2)
        return point;
    vector<IPoint> hull;
    for (auto p : point) {
        while (hull.size() >= 2 && cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    size_t lower = hull.size();
    for (int i = (int)point.size() - 2; i >= 0; i--) {
        auto p = point[i];
        while (hull.size() > lower &&
               cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    hull.pop_back();
    return hull;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<IPoint> p(n);
    for (auto &a : p)
        cin >> a.x >> a.y;
    Wide total = 0;
    for (int origin = 0; origin < n; origin++) {
        vector<IPoint> v;
        for (int i = 0; i < n; i++)
            if (i != origin && (p[i].x != p[origin].x || p[i].y != p[origin].y))
                v.push_back(p[i] - p[origin]);
        sort(v.begin(), v.end(), angleLess);
        int m = v.size();
        for (int i = 0; i < m; i++)
            v.push_back(v[i]);
        vector<IPoint> prefix(v.size() + 1);
        for (int i = 0; i < (int)v.size(); i++)
            prefix[i + 1] = prefix[i] + v[i];
        int right = 1;
        for (int i = 0; i < m; i++) {
            right = max(right, i + 1);
            while (right < i + m &&
                   (cross(v[i], v[right]) > 0 ||
                    (right < m && cross(v[i], v[right]) == 0 && dot(v[i], v[right]) > 0)))
                right++;
            total += cross(v[i], prefix[right] - prefix[i + 1]);
        }
    }
    Wide twice = total / 3;
    printWide(twice / 2);
    cout << (twice % 2 ? ".5" : ".0");
    return 0;
}
```

### 复杂度

时间 $O(n²\log n)$，空间 $O(n)$。

### 易错点

不能直接把正有向面积当全体面积，必须覆盖每个顶点的全极角并去三重计数。共线三点贡献0。

## [2020WF]Ley Lines

### 题意

固定宽度无限条带最多覆盖点数，n至3000。

### 思路

最优条带可平移到一侧边界经过某点P。用朝条带内部的单位法向量方向θ描述，其他点相对向量长度r、极角φ，入带条件为0≤r*cos(θ−φ)≤t。

r≤t时允许θ区间为[φ−π/2,φ+π/2]；r>t时分成[φ−π/2,φ−acos(t/r)]与[φ+acos(t/r),φ+π/2]。将跨2π区间拆开，扫描所有进入、离开事件取最大覆盖数，再加P。端点闭合，进入先于离开。t=0且无三点共线时直接答案2。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long double width;
    cin >> n >> width;
    vector<Point> p(n);
    for (auto &a : p)
        cin >> a.x >> a.y;
    if (width == 0) {
        cout << 2;
        return 0;
    }
    const long double pi = acosl(-1.0L), period = 2 * pi;
    int answer = 2;
    for (int origin = 0; origin < n; origin++) {
        vector<pair<long double, int>> event;
        auto add = [&](long double l, long double r) {
            while (l < 0) {
                l += period;
                r += period;
            }
            while (l >= period) {
                l -= period;
                r -= period;
            }
            if (r <= period) {
                event.push_back({l, 1});
                event.push_back({r, -1});
            } else {
                event.push_back({l, 1});
                event.push_back({period, -1});
                event.push_back({0, 1});
                event.push_back({r - period, -1});
            }
        };
        for (int i = 0; i < n; i++)
            if (i != origin) {
                Point v = p[i] - p[origin];
                long double r = norm(v), a = atan2l(v.y, v.x);
                if (r <= width)
                    add(a - pi / 2, a + pi / 2);
                else {
                    long double offset = acosl(min(1.0L, width / r));
                    add(a - pi / 2, a - offset);
                    add(a + offset, a + pi / 2);
                }
            }
        sort(event.begin(), event.end(), [](auto a, auto b) {
            return a.first != b.first ? a.first < b.first : a.second > b.second;
        });
        int current = 1;
        for (auto [angle, delta] : event) {
            current += delta;
            answer = max(answer, current);
        }
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n²\log n)$，空间 $O(n)$。

### 易错点

t是整个条带宽，不是半径，不能误用2t。题目保证宽度增减0.01不改变答案，可使用long double区间端点。

## 三角碰撞(Triangle Collision)

### 题意

等边三角形内弹性反射，小球第k次撞边的时间。

### 思路

把每次反射改为把三角形沿边镜像展开，小球便始终沿原速度直线走。平面铺成等边三角网格，撞边对应穿越三族平行网格线。设H=√3L/2，三个归一化坐标为u=y/H、v=x/L+y/(√3L)+1/2、w=−x/L+y/(√3L)+1/2；它们各自等于整数时位于相应族网格线。

每个坐标都是a+b*t。若b<0先整体取反，使b为正，则t时刻前穿线数为floor(a+b*t)−floor(a)。三族相加就是撞击数，题目保证前k次没有顶点重合事件，故不重复计数。倍增时间上界，再二分最小使穿线数≥k的时间，避免逐次模拟百万次碰撞。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    cout << fixed << setprecision(12);
    while (tests--) {
        long double length, x, y, vx, vy;
        long long k;
        cin >> length >> x >> y >> vx >> vy >> k;
        long double root = sqrtl(3.0L);
        array<long double, 3> initial = {2 * y / (root * length),
                                         x / length + y / (root * length) + 0.5L,
                                         -x / length + y / (root * length) + 0.5L};
        array<long double, 3> speed = {2 * vy / (root * length), vx / length + vy / (root * length),
                                       -vx / length + vy / (root * length)};
        for (int i = 0; i < 3; i++)
            if (speed[i] < 0) {
                speed[i] = -speed[i];
                initial[i] = -initial[i];
            }
        auto count = [&](long double t) {
            long long result = 0;
            for (int i = 0; i < 3; i++)
                if (speed[i] > 0) {
                    long double value = floorl(initial[i] + speed[i] * t) - floorl(initial[i]);
                    if (value >= k)
                        return k;
                    result += (long long)value;
                    if (result >= k)
                        return k;
                }
            return result;
        };
        long double low = 0, high = 1;
        while (count(high) < k)
            high *= 2;
        for (int iteration = 0; iteration < 100; iteration++) {
            long double mid = (low + high) / 2;
            if (count(mid) >= k)
                high = mid;
            else
                low = mid;
        }
        cout << high << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O(\log T+100)$，空间 $O(1)$。

### 易错点

横向撞线只是一族，必须加上两族斜线。小球半径10^−1000在此精度下按点处理；前k次无双边同时碰撞是计数前提。

## 计算几何spj hacker

### 题意

无输入，给a,b让错误浮点SPJ对任意标准值接受。

### 思路

输出0 0。按该SPJ使用的常见IEEE浮点语义，浮点0/0得到NaN，fabs(NaN−ans)仍为NaN，而NaN与阈值做“>”比较结果为false，于是程序不会进入WA分支。这是该题给定裁判缺少有限性检查的演示；健全实现应先拒绝b=0及非有限值。

