    sort(point.begin(), point.end(),
         [](auto a, auto b) { return a.x != b.x ? a.x < b.x : a.y < b.y; });
    point.erase(
        unique(point.begin(), point.end(), [](auto a, auto b) { return a.x == b.x && a.y == b.y; }),
        point.end());
    if (point.size() < 2)
        return point;
    vector<IPoint> hull;
    for (auto p : point) {
        while (hull.size() >= 2 && cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    size_t lower = hull.size();
    for (int i = (int)point.size() - 2; i >= 0; i--) {
        auto p = point[i];
        while (hull.size() > lower &&
               cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    hull.pop_back();
    return hull;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<IPoint> p(n);
    for (auto &q : p)
        cin >> q.x;
    for (auto &q : p)
        cin >> q.y;
    auto hull = integerHull(p);
    Wide maximum = 0;
    int h = hull.size();
    for (int i = 0; i < h; i++) {
        int k = i + 2;
        for (int j = i + 1; j + 1 < h; j++) {
            k = max(k, j + 1);
            auto area = [&](int z) { return cross(hull[j] - hull[i], hull[z] - hull[i]); };
            while (k + 1 < h && area(k + 1) > area(k))
                k++;
            maximum = max(maximum, area(k));
        }
    }
    vector<int> order(n), position(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(),
         [&](int a, int b) { return p[a].y != p[b].y ? p[a].y < p[b].y : p[a].x < p[b].x; });
    bool duplicate = false;
    for (int i = 0; i < n; i++) {
        position[order[i]] = i;
        if (i && p[order[i]].x == p[order[i - 1]].x && p[order[i]].y == p[order[i - 1]].y)
            duplicate = true;
    }
    Wide minimum = maximum;
    if (!duplicate && minimum) {
        struct Event {
            int dx, dy;
            uint16_t u, v;
        };
        vector<Event> events;
        events.reserve((long long)n * (n - 1) / 2);
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) {
                IPoint d = p[j] - p[i];
                if (d.y < 0 || (d.y == 0 && d.x < 0)) {
                    d.x = -d.x;
                    d.y = -d.y;
                }
                events.push_back({(int)d.x, (int)d.y, (uint16_t)i, (uint16_t)j});
            }
        sort(events.begin(), events.end(), [](const Event &a, const Event &b) {
            long long c = (long long)a.dx * b.dy - (long long)a.dy * b.dx;
            if (c)
                return c > 0;
            return a.u != b.u ? a.u < b.u : a.v < b.v;
        });
        for (auto e : events) {
            int u = position[e.u], v = position[e.v];
            if (u > v)
                swap(u, v);
            if (v - u != 1) {
                minimum = 0;
                break;
            }
            for (int at : {u - 1, v + 1})
                if (at >= 0 && at < n)
                    minimum = min(minimum, absolute(cross(p[e.v] - p[e.u], p[order[at]] - p[e.u])));
            if (!minimum)
                break;
            swap(order[u], order[v]);
            position[order[u]] = u;
            position[order[v]] = v;
        }
    } else if (duplicate)
        minimum = 0;
    printWide(minimum);
    cout << '\n';
    printWide(maximum);
    return 0;
}
```

### 复杂度

时间 $O(n^2\log n)$，空间 $O(n^2)$；事件12字节，n=3000时约54MB。

### 易错点

点对方向归一后都位于同一个半平面，叉积排序才有严格顺序。不能用atan2相等判三点共线，也不能用随机抽样代替最小值证明。

## Ice Walls

### 题意

穿过每道互不相交的轴平行冰墙加k时间，求s到t的欧氏距离加穿墙代价最小值。

### 思路

最短路径的转折只需发生在冰墙端点：在其他位置弯折，可以局部拉直且不改变严格穿墙次数。建立s、t和全部墙端点为节点的完全图，直连边权=欧氏距离+k*严格穿过的墙数，再跑Dijkstra。关键是将逐边数墙的O(n³)降下来。

从一个源点出发，将射线绕一周扫描。每道不经过源点的墙占据一个小于π的开角区间，进入时加入、离开时删除。墙两两不相交，因此当前射线与各墙交点由近到远的顺序不会变化。用支持排名的平衡树维护交点距离；射线对准一个目标时，查询交点参数t<1的墙数。

端点角度相同时，先删除结束的墙，再查询目标，最后加入开始的墙，所以射线仅碰墙端点不算穿墙；与源点相接的墙也不计。交点参数用整数叉积组成的分数，比较时用128位相乘。每个Dijkstra选中的节点执行一次角度扫描，随即松弛其他节点，无需存整张完全图。代码使用GNU C++17的PBDS排名树。

