        for (int origin = 0; origin < n; origin++) {
            vector<IPoint> v;
            for (int i = 0; i < n; i++)
                if (i != origin)
                    v.push_back(p[i] - p[origin]);
            sort(v.begin(), v.end(), angleLess);
            int m = v.size();
            for (int i = 0; i < m; i++)
                v.push_back(v[i]);
            int ninety = 1, straight = 1, after = 1;
            for (int i = 0; i < m; i++) {
                straight = max(straight, i + 1);
                while (straight < i + m && (cross(v[i], v[straight]) > 0 ||
                                            (straight < m && cross(v[i], v[straight]) == 0 &&
                                             dot(v[i], v[straight]) > 0)))
                    straight++;
                ninety = max(ninety, i + 1);
                while (ninety < straight && dot(v[i], v[ninety]) > 0)
                    ninety++;
                bad += straight - ninety;
                after = max(after, straight);
                while (after < i + m && cross(v[i], v[after]) == 0 && dot(v[i], v[after]) < 0)
                    after++;
                opposite += after - straight;
            }
        }
        cout << 1LL * n * (n - 1) * (n - 2) / 6 - bad - opposite / 2 << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n²\log n)$，空间 $O(n)$。

### 易错点

直角也不算锐角，点积为0要减去。共线退化三角形不能漏减或按两个方向减两次。

## Sort Points by Argument

### 题意

按arg从−π到π排序，负x轴算π，原点算0。

### 思路

先按四个连续角区分组：y<0；y=0且x≥0（含原点）；y>0；y=0且x<0。组内非共线时叉积>0者在前，同方向用输入编号打破平局。这样完全避免atan2精度，并把负x轴放在最后、原点与正x轴放在0角。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    struct P {
        long long x, y;
        int id;
    };
    vector<P> point(n);
    for (int i = 0; i < n; i++) {
        cin >> point[i].x >> point[i].y;
        point[i].id = i;
    }
    auto part = [](const P &p) {
        if (p.y < 0)
            return 0;
        if (p.y == 0 && p.x >= 0)
            return 1;
        if (p.y > 0)
            return 2;
        return 3;
    };
    sort(point.begin(), point.end(), [&](auto a, auto b) {
        int x = part(a), y = part(b);
        if (x != y)
            return x < y;
        __int128 value = (__int128)a.x * b.y - (__int128)a.y * b.x;
        if (value)
            return value > 0;
        return a.id < b.id;
    });
    for (auto p : point)
        cout << p.x << ' ' << p.y << '\n';
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

原点没有天然方向，题目指定arg=0，不能让它参与一般半平面叉积比较而破坏严格弱序。

## Amphiphilic Carbon Molecules

### 题意

用直线分两种分子到不同侧，线上的两种都可溶解，最大正确分类数。

### 思路

最优分界线可平移至经过一个粒子而不损失已溶解粒子，枚举该枢轴。把另一种颜色的相对向量反向，则“颜色0在一侧、颜色1在另一侧”统一成所有向量落在同一闭半平面。极角排序，双指针找角跨度≤π的最多向量，再加枢轴同坐标粒子数。

闭半平面允许两条反向边界射线，正好体现分界线上的所有粒子都溶解。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    const long double pi = acosl(-1.0L);
    while (cin >> n && n) {
        vector<Point> p(n);
        vector<int> color(n);
        for (int i = 0; i < n; i++)
            cin >> p[i].x >> p[i].y >> color[i];
        int answer = 0;
        for (int origin = 0; origin < n; origin++) {
            vector<long double> angle;
            int same = 0;
            for (int i = 0; i < n; i++) {
                Point v = p[i] - p[origin];
                if (v.x == 0 && v.y == 0) {
                    same++;
                    continue;
                }
                if (color[i])
                    v = v * (-1);
                angle.push_back(atan2l(v.y, v.x));
            }
            sort(angle.begin(), angle.end());
            int m = angle.size();
            for (int i = 0; i < m; i++)
                angle.push_back(angle[i] + 2 * pi);
            answer = max(answer, same);
            int right = 0;
            for (int left = 0; left < m; left++) {
                right = max(right, left);
                while (right < left + m && angle[right] - angle[left] <= pi + 1e-15L)
                    right++;
                answer = max(answer, same + right - left);
            }
        }
        cout << answer << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n²\log n)$，空间 $O(n)$。

### 易错点

同一坐标粒子在枢轴上都计入，包括不同颜色。向量反向依据粒子自身颜色，不依赖枢轴颜色。

## 美丽数

### 题意

统计能被所有非零数码整除的数。

### 思路

所有非零数码的最小公倍数L一定是2520的约数，共48种。数字只需保存模2520余数，因为最终判定r%L=0即可。加入非零d时L更新为lcm(L,d)，加入0时不变。预先列出2520全部约数及其转移，用(剩余位数,L编号,余数)缓存非贴界状态。前导0不改变L或余数，内部整数0也满足判定，但原区间l≥1，两个前缀相减会抵消它。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<int> divisor;
    for (int d = 1; d <= 2520; d++)
        if (2520 % d == 0)
            divisor.push_back(d);
    vector<int> index(2521);
    for (int i = 0; i < (int)divisor.size(); i++)
        index[divisor[i]] = i;
    vector<array<int, 10>> next(divisor.size());
    for (int i = 0; i < (int)divisor.size(); i++)
        for (int d = 0; d <= 9; d++)
            next[i][d] = index[d ? lcm(divisor[i], d) : divisor[i]];
    int states = divisor.size();
    vector<long long> memo(20 * states * 2520, -1);
    auto count = [&](long long bound) {
        if (bound < 0)
            return 0LL;
        string s = to_string(bound);
        auto dfs = [&](auto &&self, int p, int state, int remainder, bool tight) -> long long {
            if (p == (int)s.size())
                return remainder % divisor[state] == 0;
            long long &cache = memo[((s.size() - p) * states + state) * 2520 + remainder];
            if (!tight && cache != -1)
                return cache;
            int maximum = tight ? s[p] - '0' : 9;
            long long result = 0;
            for (int d = 0; d <= maximum; d++)
                result += self(self, p + 1, next[state][d], (remainder * 10 + d) % 2520,
                               tight && d == maximum);
            if (!tight)
                cache = result;
            return result;
        };
        return dfs(dfs, 0, index[1], 0, true);
    };
    int tests;
    cin >> tests;
    while (tests--) {
        long long l, r;
        cin >> l >> r;
        cout << count(r) - count(l - 1) << '\n';
    }
    return 0;
}
```

### 复杂度

缓存至多 $O(D\cdot48\cdot2520)$ 个状态，每状态10条转移；单边界另 $O(10D)$，空间同状态数。

### 易错点

0数码应忽略，不能令L变成0。余数必须模2520，不能随L变化后丢掉必要信息。

## 一袋小球

### 题意

P先抽，D抽黑后会多带出一个球，求P先抽到白球概率。

### 思路

f[w][b]为轮到P、袋内有w白b黑时P获胜概率。P直接抽白贡献w/(w+b)。若P与D都抽黑，概率b/(w+b)*(b−1)/(w+b−1)，再由D带出一球：带黑转f[w][b−3]，带白转f[w−1][b−2]，按剩余球比例加权。D抽到白则P失败，不加贡献。w=0时恒0，b=0且w>0时恒1。按w、b升序计算。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int w, b;
    cin >> w >> b;
    vector<vector<long double>> dp(w + 1, vector<long double>(b + 1));
    for (int white = 1; white <= w; white++)
        for (int black = 0; black <= b; black++) {
            long double total = white + black;
            dp[white][black] = white / total;
            if (black >= 2) {
                long double reach = black / total * (black - 1) / (total - 1),
                            remaining = total - 2;
                if (black >= 3)
                    dp[white][black] += reach * (black - 2) / remaining * dp[white][black - 3];
                dp[white][black] += reach * white / remaining * dp[white - 1][black - 2];
            }
        }
    cout << fixed << setprecision(12) << dp[w][b];
    return 0;
}
```

### 复杂度

时间、空间均 $O(wb)$。

### 易错点

带出白球不算D抽到白球，但会减少下一轮白球数。空袋判D赢，所以dp[0][0]=0。

## 一起玩音游

### 题意

独立O/X序列，每段连续O长度平方，求分数期望。

### 思路

设上一位置末尾连续O长度为L，本次成功会把对应段贡献从L²变成(L+1)²，增量2L+1；失败时总分不变、末尾长度清零。只维护末尾长度期望len：本次分数期望增加p*(2len+1)，之后len=p*(len+1)。利用期望线性性，不需要二阶矩。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    long double length = 0, answer = 0;
    while (n--) {
        long double p;
        cin >> p;
        answer += p * (2 * length + 1);
        length = p * (length + 1);
    }
    cout << fixed << setprecision(12) << answer;
    return 0;
}
```

### 复杂度

时间 $O(n)$，空间 $O(1)$。

### 易错点

先用旧len计算分数增量，再更新len。失败不会扣除此前已获得的连续段分数。

## 鱼

### 题意

鱼随机两两相遇并互食，求每条鱼最后存活概率。

### 思路

dp[mask]为当前存活集合恰是mask的概率，初始全体为1。集合有k条鱼时，每个无序鱼对相遇概率为1/C(k,2)。枚举集合中的i<j，按a[i][j]转移到删j的集合，按a[j][i]转移到删i的集合。删位后掩码严格变小，按掩码倒序即可保证前驱先处理。最终dp[1<<i]就是i独活概率。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<long double>> a(n, vector<long double>(n));
    for (auto &row : a)
        for (auto &x : row)
            cin >> x;
    int size = 1 << n;
    vector<long double> dp(size);
    dp[size - 1] = 1;
    for (int mask = size - 1; mask >= 1; mask--) {
        int count = __builtin_popcount((unsigned)mask);
        if (count < 2)
            continue;
        long double pairProbability = dp[mask] * 2 / (count * (count - 1));
        for (int bits = mask; bits; bits &= bits - 1) {
            int i = __builtin_ctz((unsigned)bits);
            int others = mask & ~((1 << (i + 1)) - 1);
            for (; others; others &= others - 1) {
                int j = __builtin_ctz((unsigned)others);
                dp[mask ^ (1 << j)] += pairProbability * a[i][j];
                dp[mask ^ (1 << i)] += pairProbability * a[j][i];
            }
        }
    }
    cout << fixed << setprecision(10);
    for (int i = 0; i < n; i++)
        cout << dp[1 << i] << (i + 1 == n ? '\n' : ' ');
    return 0;
}
```

### 复杂度

时间 $O(n^2 2^n)$，空间 $O(2^n+n^2)$。

### 易错点

相遇的是无序对，不能再次乘2。只从当前存活鱼中选择；n=1初始状态就是最终状态。

## 分数游戏

### 题意

双方每轮各加[-k,k]整数，统计t轮后先手分数更高的游戏数。

### 思路

L的每次增量取负后仍均匀遍历[-k,k]，所以M减L的总增量可视为2t个独立[-k,k]整数之和。每个数加k变成[0,2k]，若和为s，最终差为a−b+s−2kt，要求s>b−a+2kt。

DP统计2t个[0,2k]整数的和。每层新dp[s]为旧dp[s−2k..s]之和，用滑动窗口O(1)更新每个s。最后把满足严格不等式的和状态相加。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a, b, k, t;
    cin >> a >> b >> k >> t;
    const int mod = 1000000007;
    vector<int> dp(1, 1);
    for (int step = 0; step < 2 * t; step++) {
        int old = dp.size() - 1;
        vector<int> next(old + 2 * k + 1);
        long long sum = 0;
        for (int s = 0; s < (int)next.size(); s++) {
            if (s <= old)
                sum += dp[s];
            int remove = s - 2 * k - 1;
            if (remove >= 0 && remove <= old)
                sum -= dp[remove];
            sum = (sum % mod + mod) % mod;
            next[s] = sum;
        }
        dp.swap(next);
    }
    int threshold = b - a + 2 * k * t;
    long long answer = 0;
    for (int s = max(0, threshold + 1); s < (int)dp.size(); s++)
        answer = (answer + dp[s]) % mod;
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(kt^2)$，空间 $O(kt)$。

### 易错点

胜利要求严格大于，平分不能计入。每一轮每个人的取值独立，转换后仍需2t个变量。

## 宝藏猎人

### 题意

向东跳，跳长每次至多改变1，收集最多宝石。

### 思路

dp[position][jump]表示最后一次跳长为jump时的最多宝石。下一跳尝试jump−1、jump、jump+1，正长度且不越界即可。关键是限制跳长范围：从初始d增加或减少250，必须经历至少250次逐级变化，仅这些跳长的最小总和就超过30000；减小的情况还要求d≥251。因此只需保存jump∈[d−250,d+250]与正整数的交集。

位置严格增加，按位置升序转移。总宝石至30000，16位有符号数足够存答案及−1不可达标记，约30MB。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, d;
    cin >> n >> d;
    const int limit = 30000, width = 501;
    vector<int> gem(limit + 1);
    for (int i = 0; i < n; i++) {
        int p;
        cin >> p;
        gem[p]++;
    }
    vector<int16_t> dp((limit + 1) * width, -1);
    dp[d * width + 250] = gem[d];
    int answer = 0;
    for (int p = d; p <= limit; p++)
        for (int index = 0; index < width; index++) {
            int current = dp[p * width + index];
            if (current < 0)
                continue;
            answer = max(answer, current);
            int jump = d + index - 250;
            for (int change = -1; change <= 1; change++) {
                int next = index + change, length = jump + change;
                if (next >= 0 && next < width && length > 0 && p + length <= limit) {
                    auto &value = dp[(p + length) * width + next];
                    value = max((int)value, current + gem[p + length]);
                }
            }
        }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(30000\sqrt{30000})$，空间同状态数，每状态16位。

### 易错点

同一个位置可能有多颗宝石，必须累计频数。第一次强制跳到d，不能从0随意选择第一跳。

## 猫猫跳

### 题意

付费学若干双向跳长，要求能到达全部整数位置。

### 思路

可正反向使用跳长，能到达的位置恰是所选跳长gcd的倍数，所以目标是选出gcd=1的最小费用。dp[g]记录已处理卡片选择子集gcd为g的最少费用，空集用g=0。对每张卡，用旧表副本保留不选，再用gcd(g,l)更新选卡状态。相同gcd仅保留费用最小者。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> length(n), cost(n);
    for (int &x : length)
        cin >> x;
    for (int &x : cost)
        cin >> x;
    map<int, long long> dp = {{0, 0}};
    for (int i = 0; i < n; i++) {
        auto next = dp;
        for (auto [g, value] : dp) {
            int target = gcd(g, length[i]);
            long long candidate = value + cost[i];
            auto it = next.find(target);
            if (it == next.end() || candidate < it->second)
                next[target] = candidate;
        }
        dp.swap(next);
    }
    cout << (dp.count(1) ? dp[1] : -1);
    return 0;
}
```

### 复杂度

设最多S个不同gcd状态，时间 $O(nS(\log U+\log S))$，空间 $O(S)$。

### 易错点

允许反向跳，所以使用整数线性组合，不是非负背包。不能仅检查是否存在两张互素卡，可能需要更多张。

## 神奇数组

### 题意

每段免费去掉最小floor(长度/c)项，求分割后的最小收费和。

### 思路

先求最大折扣，再用总和减去。长度kc+r的段，原折扣是该段最小k项之和。把其中连续kc项分成k个长度c的块，剩下r项单独处理，每块各免其最小值，相当于从原段选了k项；任意k项之和不少于全局最小k项，因此这样细分折扣只会更大。

所以只需考虑互不重叠的长度c块。f[i]=max(f[i−1],f[i−c]+min(a[i−c+1..i]))，分别不以i结束块、选择该块。用单调队列维护长度c的滑动最小值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, c;
    cin >> n >> c;
    vector<long long> a(n + 1), dp(n + 1);
    long long sum = 0;
    deque<int> queue;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        sum += a[i];
        while (!queue.empty() && a[queue.back()] >= a[i])
            queue.pop_back();
        queue.push_back(i);
        while (!queue.empty() && queue.front() <= i - c)
            queue.pop_front();
        dp[i] = dp[i - 1];
        if (i >= c)
            dp[i] = max(dp[i], dp[i - c] + a[queue.front()]);
    }
    cout << sum - dp[n];
    return 0;
}
```

### 复杂度

时间、空间均 $O(n)$。

### 易错点

不是每c个元素固定一组，可以跳过部分元素选择更好的不重叠块。c=1时所有元素免费，答案0。

## 浇水大师

### 题意

长度2A到2B的装置恰铺满[0,L]，指定区间不能被切开。

### 思路

装置半径为整数，覆盖长度为偶数，所以从0开始所有分界都为偶数。令dp[i]表示覆盖到2i的最少装置数；若2i严格位于某个指定(S,E)内，此处不能作为分界。用差分标记全部禁用整数分界，端点S、E本身允许。

对允许的i，dp[i]=1+min(dp[j])，j∈[i−B,i−A]且j允许。维护这个移动窗口中dp递增的单调队列，dp[0]=0，答案dp[L/2]。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, length, a, b;
    cin >> n >> length >> a >> b;
    vector<int> difference(length + 2);
    for (int i = 0; i < n; i++) {
        int s, e;
        cin >> s >> e;
        difference[s + 1]++;
        difference[e]--;
    }
    vector<bool> allowed(length / 2 + 1);
    int active = 0;
    for (int x = 0; x <= length; x++) {
        active += difference[x];
        if (x % 2 == 0)
            allowed[x / 2] = active == 0;
    }
    int target = length / 2, inf = 1000000000;
    vector<int> dp(target + 1, inf);
    dp[0] = 0;
    deque<int> queue;
    for (int i = 1; i <= target; i++) {
        int enter = i - a;
        if (enter >= 0 && allowed[enter] && dp[enter] < inf) {
            while (!queue.empty() && dp[queue.back()] >= dp[enter])
                queue.pop_back();
            queue.push_back(enter);
        }
        while (!queue.empty() && queue.front() < i - b)
            queue.pop_front();
        if (allowed[i] && !queue.empty())
            dp[i] = dp[queue.front()] + 1;
    }
    cout << (dp[target] == inf ? -1 : dp[target]);
    return 0;
}
```

### 复杂度

时间 $O(L+N)$，空间 $O(L)$。

### 易错点

禁止切的是区间内部，不是两端；重叠约束用覆盖次数并集处理，不能只逐条判断。

## Nearest Point

### 题意

随机旋转后按x差找最近点，求各返回点概率。

### 思路

固定查询点i，对候选j的投影距离为|(Pj−Pi)·u(θ)|，θ均匀。两个候选j、k优劣改变，只可能发生在绝对投影相等，即(Pj−Pk)·u=0或(Pj+Pk−2Pi)·u=0。把这些事件角及0、π排序，因绝对投影以π为周期，只分析[0,π]。

每相邻事件之间候选顺序不变，取中点扫描全部候选，找投影差最小者，把该角区间长度/π加到对应概率。若候选关于i中心对称，它们恒相等，按编号较小者选择；零向量方程不产生事件。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<Point> p(n);
    for (auto &a : p)
        cin >> a.x >> a.y;
    const long double pi = acosl(-1.0L);
    vector<vector<long double>> probability(n, vector<long double>(n));
    for (int i = 0; i < n; i++) {
        vector<long double> event = {0, pi};
        auto add = [&](Point v) {
            if (v.x == 0 && v.y == 0)
                return;
            long double a = atan2l(v.y, v.x) + pi / 2;
            a = fmodl(a, pi);
            if (a < 0)
                a += pi;
            event.push_back(a);
        };
        for (int j = 0; j < n; j++)
            if (j != i)
                for (int k = j + 1; k < n; k++)
                    if (k != i) {
                        add(p[j] - p[k]);
                        add(p[j] + p[k] - p[i] * 2);
                    }
        sort(event.begin(), event.end());
        for (int t = 1; t < (int)event.size(); t++) {
            long double width = event[t] - event[t - 1];
            if (width <= 1e-18L)
                continue;
            long double angle = (event[t] + event[t - 1]) / 2;
            Point direction = {cosl(angle), sinl(angle)};
            long double best = 1e100L;
            int winner = -1;
            for (int j = 0; j < n; j++)
                if (j != i) {
                    long double value = fabsl(dot(p[j] - p[i], direction));
                    if (value < best - 1e-12L) {
                        best = value;
                        winner = j;
                    }
                }
            probability[i][winner] += width / pi;
        }
    }
    cout << fixed << setprecision(12);
    for (auto &row : probability)
        for (int j = 0; j < n; j++)
            cout << row[j] << (j + 1 == n ? '\n' : ' ');
    return 0;
}
```

### 复杂度

时间 $O(n⁴+n³\log n)$，空间 $O(n²)$，n≤50。

### 易错点

比较的是投影差，不是欧氏距离。事件本身只有零测度，但恒相等的候选必须按最小编号处理。

## 0的个数

### 题意

多组求[m,n]的十进制0总数，包含数字0自身。

### 思路

先求正整数1..n中0的次数。枚举十进制位place，拆成高位high、当前位current、低位low。高位为0时该位不能出现有效0；否则完整高位周期贡献(high−1)*place，再按当前位补low+1（current=0）或place（current>0）。减掉的一个周期正是非法前导零。

数字0自身有一个0，故F(n)=正数计数+1（n≥0）；最后用F(n)−F(m−1)。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

long long countDigit(long long n, int digit) {
    if (n <= 0)
        return 0;
    long long answer = 0;
    for (long long place = 1; place <= n;) {
        long long high = n / place / 10, current = n / place % 10, low = n % place;
        if (digit) {
            answer += high * place;
            if (current > digit)
                answer += place;
            else if (current == digit)
                answer += low + 1;
        } else if (high) {
            answer += (high - 1) * place;
            answer += current == 0 ? low + 1 : place;
        }
        if (place > n / 10)
            break;
        place *= 10;
    }
    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long m, n;
    auto prefix = [&](long long x) { return x < 0 ? 0LL : countDigit(x, 0) + 1; };
    while (cin >> m >> n && m >= 0 && n >= 0)
        cout << prefix(n) - prefix(m - 1) << '\n';
    return 0;
}
```

### 复杂度

每组时间 $O(\log n)$，空间 $O(1)$。

### 易错点

不能把0当成没有数位；负输入对是结束标记。高位为0的最高补零不能计数。

## 恶意竞争

### 题意

随机漏洞同时覆盖全部类型和全部组件的期望天数。

### 思路

E[i][j]为已见i种漏洞、j个组件时的剩余期望。一天后有四种情况：都旧ij，都新(n−i)(s−j)，仅类型新(n−i)j，仅组件新i(s−j)，总分母ns。把自环ij*E[i][j]移到左侧：E[i][j]=(ns+(n−i)jE[i+1][j]+i(s−j)E[i][j+1]+(n−i)(s−j)E[i+1][j+1])/(ns−ij)。终点E[n][s]=0，按i、j倒序计算，保留两行。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, s;
    cin >> n >> s;
    vector<long double> next(s + 2), current(s + 2);
    for (int i = n; i >= 0; i--) {
        fill(current.begin(), current.end(), 0);
        for (int j = s; j >= 0; j--) {
            if (i == n && j == s)
                continue;
            current[j] = ((long double)n * s + (long double)(n - i) * j * next[j] +
                          (long double)i * (s - j) * current[j + 1] +
                          (long double)(n - i) * (s - j) * next[j + 1]) /
                         ((long double)n * s - i * j);
        }
        next.swap(current);
    }
    cout << fixed << setprecision(10) << next[0];
    return 0;
}
```

### 复杂度

时间 $O(ns)$，空间 $O(s)$。

### 易错点

组件和类型是同时抽取的一对标签，不能分别求期望后直接取最大或相加。

## Fencing the Cows

### 题意

最短围栏包含所有点，支持单点及共线退化。

### 思路

包含全部点的最短闭合围栏就是凸包边界。按x、y排序，用单调链维护连续左转，删除内点和边上中间点，得到逆时针凸包。累加环上相邻距离。单点周长0，两点或全共线时凸包只剩两端，闭合周长为线段往返长度。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

vector<Point> convexHull(vector<Point> point) {
    sort(point.begin(), point.end(),
         [](Point a, Point b) { return a.x != b.x ? a.x < b.x : a.y < b.y; });
    point.erase(unique(point.begin(), point.end(),
                       [](Point a, Point b) { return a.x == b.x && a.y == b.y; }),
                point.end());
    if (point.size() < 2)
        return point;
    vector<Point> hull;
    for (Point p : point) {
        while (hull.size() >= 2 && cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    size_t lower = hull.size();
    for (int i = (int)point.size() - 2; i >= 0; i--) {
        Point p = point[i];
        while (hull.size() > lower &&
               cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    hull.pop_back();
    return hull;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<Point> p(n);
    for (auto &a : p)
        cin >> a.x >> a.y;
    auto hull = convexHull(p);
    long double answer = 0;
    for (int i = 0; i < (int)hull.size(); i++)
        answer += distance(hull[i], hull[(i + 1) % hull.size()]);
    cout << fixed << setprecision(12) << answer;
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

输入是实数，不能截断成整数。点重复先去重；两点答案是距离的2倍，与题目样例一致。

## Beauty Contest

### 题意

求最远点对距离平方，坐标可达2^31。

### 思路

最远点对都在凸包上。对每条凸包边，沿凸包移动对踵点j，直到它到该边的有向面积不再增大；j全程单调绕行，每条边只检查两端与j的距离，再在面积相等时检查j+1。两点退化直接求平方。

坐标差可能达到2^32，两个平方相加可达2^65，连无符号64位也不够。叉积、平方距离及输出全部使用128位整数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

using Wide = __int128_t;
struct IPoint {
    long long x = 0, y = 0;
    IPoint operator+(IPoint b) const { return {x + b.x, y + b.y}; }
    IPoint operator-(IPoint b) const { return {x - b.x, y - b.y}; }
};
Wide cross(IPoint a, IPoint b) { return (Wide)a.x * b.y - (Wide)a.y * b.x; }
Wide dot(IPoint a, IPoint b) { return (Wide)a.x * b.x + (Wide)a.y * b.y; }
Wide absolute(Wide x) { return x < 0 ? -x : x; }
void printWide(Wide value) {
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string text;
    do {
        text.push_back('0' + value % 10);
        value /= 10;
    } while (value);
    reverse(text.begin(), text.end());
    cout << text;
}
bool angleLess(IPoint a, IPoint b) {
    auto half = [](IPoint p) { return p.y < 0 || (p.y == 0 && p.x < 0); };
    if (half(a) != half(b))
        return half(a) < half(b);
    return cross(a, b) > 0;
}
vector<IPoint> integerHull(vector<IPoint> point) {
    sort(point.begin(), point.end(),
         [](auto a, auto b) { return a.x != b.x ? a.x < b.x : a.y < b.y; });
    point.erase(
        unique(point.begin(), point.end(), [](auto a, auto b) { return a.x == b.x && a.y == b.y; }),
        point.end());
    if (point.size() < 2)
        return point;
    vector<IPoint> hull;
    for (auto p : point) {
        while (hull.size() >= 2 && cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    size_t lower = hull.size();
    for (int i = (int)point.size() - 2; i >= 0; i--) {
        auto p = point[i];
        while (hull.size() > lower &&
               cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    hull.pop_back();
    return hull;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<IPoint> p(n);
    for (auto &a : p)
        cin >> a.x >> a.y;
    auto h = integerHull(p);
    int m = h.size();
    Wide answer = 0;
    auto squared = [](IPoint a, IPoint b) { return dot(a - b, a - b); };
    if (m == 2)
        answer = squared(h[0], h[1]);
    else if (m > 2) {
        int j = 1;
        for (int i = 0; i < m; i++) {
            int next = (i + 1) % m;
            auto area = [&](int k) { return absolute(cross(h[next] - h[i], h[k] - h[i])); };
            while (area((j + 1) % m) > area(j))
                j = (j + 1) % m;
            answer = max({answer, squared(h[i], h[j]), squared(h[next], h[j])});
            if (area((j + 1) % m) == area(j))
                answer =
                    max({answer, squared(h[i], h[(j + 1) % m]), squared(h[next], h[(j + 1) % m])});
        }
    }
    printWide(answer);
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，卡壳 $O(n)$，空间 $O(n)$。

### 易错点

输出平方，无需开方。求凸包时也使用128位叉积，否则极大坐标的边界就可能先算错。

## Chris and Road

### 题意

公交车向左，行人只沿竖线以至多u速度过路，求最短安全时间。

### 思路

把车固定，行人相对位置为(vt,y)。若立刻全速走，轨迹满足t−y/u=0。对车每个顶点算r=x/v−y/u，凸性使整车的r范围为[minR,maxR]。若0不在开区间内，立刻走就安全，时间w/u；否则必须等到从车后绕过，至少补足maxR的延迟。

等maxR后再全速即可实现总时间maxR+w/u。允许途中变速也不能更短：相对量t−y/u只能非减，要从凸障碍的后侧通过最终至少达到其最大r。边界接触不算撞，端点等号允许。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long double w, v, u;
    cin >> n >> w >> v >> u;
    long double minimum = 1e100L, maximum = -1e100L;
    for (int i = 0; i < n; i++) {
        long double x, y;
        cin >> x >> y;
        long double r = x / v - y / u;
        minimum = min(minimum, r);
        maximum = max(maximum, r);
    }
    long double answer = w / u;
    if (minimum < 0 && maximum > 0)
        answer += maximum;
    cout << fixed << setprecision(12) << answer;
    return 0;
}
```

### 复杂度

时间 $O(n)$，空间 $O(1)$。

### 易错点

车向负x移动，相对坐标要加vt。不能简单等车所有点都经过x=0，允许根据高度提前开始或贴边。

## Illuminations II

### 题意

外凸多边形边界随机放灯，内凸多边形被照亮周长期望。

### 思路

固定内多边形的一条逆时针边AB，外部光源在其右侧时这条边整条可见，在左侧时被内多边形挡住。因此该边期望贡献=边长*外边界位于其右半平面的长度/外周长，各边线性相加。

AB所在直线穿过外多边形内部，边界恰分为左右两条连续弧。用法向量支撑查询找到正侧、负侧极值顶点，再分别在两条顶点链上二分符号变化，得到两个交点所在边及线性插值位置。外周长前缀和将交点间右侧弧长化为常数求和。整数叉积判断侧别，只有交点比例与周长用long double。

