        if (point.size() < 3) {
            int best = 0;
            for (int i = 1; i < (int)point.size(); i++)
                if (dot(point[i], direction) > dot(point[best], direction))
                    best = i;
            return best;
        }
        auto it = lower_bound(normal.begin(), normal.end(), direction,
                              [](const auto &a, IPoint b) { return angleLess(a.first, b); });
        if (it == normal.end())
            it = normal.begin();
        return it->second;
    }
};
int visibleEdge(const vector<IPoint> &p, IPoint q) {
    int n = p.size();
    if (cross(p[1] - p[0], q - p[0]) < 0)
        return 0;
    if (cross(p[n - 1] - p[0], q - p[0]) > 0)
        return n - 1;
    int l = 1, r = n - 1;
    while (r - l > 1) {
        int mid = (l + r) / 2;
        if (cross(p[mid] - p[0], q - p[0]) >= 0)
            l = mid;
        else
            r = mid;
    }
    return cross(p[r] - p[l], q - p[l]) < 0 ? l : -1;
}
bool insideConvex(const vector<IPoint> &p, IPoint q, bool strict) {
    int n = p.size();
    if (n == 1)
        return !strict && q.x == p[0].x && q.y == p[0].y;
    if (n == 2)
        return !strict && cross(p[1] - p[0], q - p[0]) == 0 && dot(q - p[0], q - p[1]) <= 0;
    Wide a = cross(p[1] - p[0], q - p[0]), b = cross(p[n - 1] - p[0], q - p[0]);
    if (a < 0 || b > 0)
        return false;
    if (a == 0)
        return !strict && dot(q - p[0], q - p[1]) <= 0;
    if (b == 0)
        return !strict && dot(q - p[0], q - p[n - 1]) <= 0;
    int l = 1, r = n - 1;
    while (r - l > 1) {
        int mid = (l + r) / 2;
        if (cross(p[mid] - p[0], q - p[0]) >= 0)
            l = mid;
        else
            r = mid;
    }
    Wide side = cross(p[r] - p[l], q - p[l]);
    return strict ? side > 0 : side >= 0;
}
vector<IPoint> minkowski(vector<IPoint> a, vector<IPoint> b) {
    if (a.size() < 3 || b.size() < 3) {
        vector<IPoint> sum;
        for (auto p : a)
            for (auto q : b)
                sum.push_back(p + q);
        return integerHull(sum);
    }
    auto prepare = [](vector<IPoint> &p) {
        auto it = min_element(p.begin(), p.end(),
                              [](auto a, auto b) { return a.y != b.y ? a.y < b.y : a.x < b.x; });
        rotate(p.begin(), it, p.end());
    };
    prepare(a);
    prepare(b);
    int n = a.size(), m = b.size(), i = 0, j = 0;
    vector<IPoint> result;
    IPoint current = a[0] + b[0];
    result.push_back(current);
    while (i < n || j < m) {
        IPoint x = i < n ? a[(i + 1) % n] - a[i] : IPoint{},
               y = j < m ? b[(j + 1) % m] - b[j] : IPoint{};
        Wide c = cross(x, y);
        if (j == m || (i < n && c > 0)) {
            current = current + x;
            i++;
        } else if (i == n || c < 0) {
            current = current + y;
            j++;
        } else {
            current = current + x + y;
            i++;
            j++;
        }
        result.push_back(current);
    }
    result.pop_back();
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<IPoint> outer(n), inner(m);
    for (auto &p : outer)
        cin >> p.x >> p.y;
    for (auto &p : inner)
        cin >> p.x >> p.y;
    Support support(outer);
    vector<long double> length(n), prefix(n + 1);
    for (int i = 0; i < n; i++) {
        auto e = outer[(i + 1) % n] - outer[i];
        length[i] = sqrtl((long double)dot(e, e));
        prefix[i + 1] = prefix[i] + length[i];
    }
    long double perimeter = prefix[n], answer = 0;
    for (int i = 0; i < m; i++) {
        IPoint a = inner[i], e = inner[(i + 1) % m] - a, normal = {-e.y, e.x},
               negative = {e.y, -e.x};
        int positive = support.index(normal), minus = support.index(negative);
        auto side = [&](int vertex) { return cross(e, outer[vertex] - a); };
        auto crossing = [&](int start, int finish, bool sign) {
            int low = 0, high = (finish - start + n) % n;
            while (high - low > 1) {
                int mid = (low + high) / 2;
                if ((side((start + mid) % n) >= 0) == sign)
                    low = mid;
                else
                    high = mid;
            }
            int u = (start + low) % n, v = (u + 1) % n;
            Wide su = side(u), sv = side(v);
            long double ratio = (long double)su / (long double)(su - sv);
            return prefix[u] + ratio * length[u];
        };
        long double enter = crossing(positive, minus, true),
                    leave = crossing(minus, positive, false), arc = leave - enter;
        if (arc < 0)
            arc += perimeter;
        answer += sqrtl((long double)dot(e, e)) * arc / perimeter;
    }
    cout << fixed << setprecision(15) << answer;
    return 0;
}
```

### 复杂度

预处理 $O(n\log n)$，全部内边 $O(m\log n)$，空间 $O(n+m)$。

### 易错点

光源按外边界弧长均匀，不是外顶点均匀。内边整条可见与否由其支撑直线侧别决定，无需逐点数值积分。

## Enclosure

### 题意

已有k个点，加入一个候选点后最大凸包面积。

### 思路

先求已有点逆时针凸包及各边叉积前缀和。内点不改变面积；外点q会替换一段连续可见边，其中可见条件cross(edge,q−start)<0。用扇形二分找到一条可见边e。

以e的内法向量求最远支撑顶点，它的两条相邻边至少一条不可见：若q在两边外侧，沿此支撑方向的投影必超过最远顶点，和q位于e外侧矛盾。于是得到一个可见、一个不可见边。可见边在环上连续，分别沿两条弧二分找可见段首尾，得到两切点A、B。

新二倍面积=旧二倍面积−可见边叉积和+cross(A,q)+cross(q,B)。前缀和使面积替换常数完成，每个候选只做对数次支撑与侧别判断。全部面积用128位，精确输出.0或.5。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

using Wide = __int128_t;
struct IPoint {
    long long x = 0, y = 0;
    IPoint operator+(IPoint b) const { return {x + b.x, y + b.y}; }
    IPoint operator-(IPoint b) const { return {x - b.x, y - b.y}; }
};
Wide cross(IPoint a, IPoint b) { return (Wide)a.x * b.y - (Wide)a.y * b.x; }
Wide dot(IPoint a, IPoint b) { return (Wide)a.x * b.x + (Wide)a.y * b.y; }
Wide absolute(Wide x) { return x < 0 ? -x : x; }
void printWide(Wide value) {
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string text;
    do {
        text.push_back('0' + value % 10);
        value /= 10;
    } while (value);
    reverse(text.begin(), text.end());
    cout << text;
}
bool angleLess(IPoint a, IPoint b) {
    auto half = [](IPoint p) { return p.y < 0 || (p.y == 0 && p.x < 0); };
    if (half(a) != half(b))
        return half(a) < half(b);
    return cross(a, b) > 0;
}
vector<IPoint> integerHull(vector<IPoint> point) {
    sort(point.begin(), point.end(),
         [](auto a, auto b) { return a.x != b.x ? a.x < b.x : a.y < b.y; });
    point.erase(
        unique(point.begin(), point.end(), [](auto a, auto b) { return a.x == b.x && a.y == b.y; }),
        point.end());
    if (point.size() < 2)
        return point;
    vector<IPoint> hull;
    for (auto p : point) {
        while (hull.size() >= 2 && cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    size_t lower = hull.size();
    for (int i = (int)point.size() - 2; i >= 0; i--) {
        auto p = point[i];
        while (hull.size() > lower &&
               cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    hull.pop_back();
    return hull;
}

struct Support {
    const vector<IPoint> &point;
    vector<pair<IPoint, int>> normal;
    explicit Support(const vector<IPoint> &p) : point(p) {
        if (p.size() < 3)
            return;
        for (int i = 0; i < (int)p.size(); i++) {
            IPoint e = p[(i + 1) % p.size()] - p[i];
            normal.push_back({{e.y, -e.x}, i});
        }
        sort(normal.begin(), normal.end(),
             [](auto a, auto b) { return angleLess(a.first, b.first); });
    }
    int index(IPoint direction) const {
        if (point.size() < 3) {
            int best = 0;
            for (int i = 1; i < (int)point.size(); i++)
                if (dot(point[i], direction) > dot(point[best], direction))
                    best = i;
            return best;
        }
        auto it = lower_bound(normal.begin(), normal.end(), direction,
                              [](const auto &a, IPoint b) { return angleLess(a.first, b); });
        if (it == normal.end())
            it = normal.begin();
        return it->second;
    }
};
int visibleEdge(const vector<IPoint> &p, IPoint q) {
    int n = p.size();
    if (cross(p[1] - p[0], q - p[0]) < 0)
        return 0;
    if (cross(p[n - 1] - p[0], q - p[0]) > 0)
        return n - 1;
    int l = 1, r = n - 1;
    while (r - l > 1) {
        int mid = (l + r) / 2;
        if (cross(p[mid] - p[0], q - p[0]) >= 0)
            l = mid;
        else
            r = mid;
    }
    return cross(p[r] - p[l], q - p[l]) < 0 ? l : -1;
}
bool insideConvex(const vector<IPoint> &p, IPoint q, bool strict) {
    int n = p.size();
    if (n == 1)
        return !strict && q.x == p[0].x && q.y == p[0].y;
    if (n == 2)
        return !strict && cross(p[1] - p[0], q - p[0]) == 0 && dot(q - p[0], q - p[1]) <= 0;
    Wide a = cross(p[1] - p[0], q - p[0]), b = cross(p[n - 1] - p[0], q - p[0]);
    if (a < 0 || b > 0)
        return false;
    if (a == 0)
        return !strict && dot(q - p[0], q - p[1]) <= 0;
    if (b == 0)
        return !strict && dot(q - p[0], q - p[n - 1]) <= 0;
    int l = 1, r = n - 1;
    while (r - l > 1) {
        int mid = (l + r) / 2;
        if (cross(p[mid] - p[0], q - p[0]) >= 0)
            l = mid;
        else
            r = mid;
    }
    Wide side = cross(p[r] - p[l], q - p[l]);
    return strict ? side > 0 : side >= 0;
}
vector<IPoint> minkowski(vector<IPoint> a, vector<IPoint> b) {
    if (a.size() < 3 || b.size() < 3) {
        vector<IPoint> sum;
        for (auto p : a)
            for (auto q : b)
                sum.push_back(p + q);
        return integerHull(sum);
    }
    auto prepare = [](vector<IPoint> &p) {
        auto it = min_element(p.begin(), p.end(),
                              [](auto a, auto b) { return a.y != b.y ? a.y < b.y : a.x < b.x; });
        rotate(p.begin(), it, p.end());
    };
    prepare(a);
    prepare(b);
    int n = a.size(), m = b.size(), i = 0, j = 0;
    vector<IPoint> result;
    IPoint current = a[0] + b[0];
    result.push_back(current);
    while (i < n || j < m) {
        IPoint x = i < n ? a[(i + 1) % n] - a[i] : IPoint{},
               y = j < m ? b[(j + 1) % m] - b[j] : IPoint{};
        Wide c = cross(x, y);
        if (j == m || (i < n && c > 0)) {
            current = current + x;
            i++;
        } else if (i == n || c < 0) {
            current = current + y;
            j++;
        } else {
            current = current + x + y;
            i++;
            j++;
        }
        result.push_back(current);
    }
    result.pop_back();
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<IPoint> p(n);
    for (auto &a : p)
        cin >> a.x >> a.y;
    auto hull = integerHull(vector<IPoint>(p.begin(), p.begin() + k));
    int h = hull.size();
    Support support(hull);
    vector<Wide> prefix(2 * h + 1);
    for (int i = 0; i < 2 * h; i++)
        prefix[i + 1] = prefix[i] + cross(hull[i % h], hull[(i + 1) % h]);
    Wide base = prefix[h], answer = base;
    for (int i = k; i < n; i++) {
        IPoint q = p[i];
        int visible = visibleEdge(hull, q);
        if (visible < 0)
            continue;
        auto side = [&](int edge) {
            return cross(hull[(edge + 1) % h] - hull[edge], q - hull[edge]);
        };
        IPoint e = hull[(visible + 1) % h] - hull[visible], normal = {-e.y, e.x};
        int vertex = support.index(normal),
            hidden = side(vertex) > 0 ? vertex : (vertex + h - 1) % h;
        int distance = (hidden - visible + h) % h, low = 0, high = distance;
        while (high - low > 1) {
            int mid = (low + high) / 2;
            if (side((visible + mid) % h) < 0)
                low = mid;
            else
                high = mid;
        }
        int end = (visible + low) % h;
        distance = (visible - hidden + h) % h;
        low = 0;
        high = distance;
        while (high - low > 1) {
            int mid = (low + high) / 2;
            if (side((hidden + mid) % h) > 0)
                low = mid;
            else
                high = mid;
        }
        int start = (hidden + high) % h, count = (end - start + h) % h + 1;
        Wide removed = prefix[start + count] - prefix[start];
        Wide area = base - removed + cross(hull[start], q) + cross(q, hull[(end + 1) % h]);
        answer = max(answer, area);
    }
    printWide(answer / 2);
    cout << (answer % 2 ? ".5" : ".0");
    return 0;
}
```

### 复杂度

时间 $O(k\log k+(n-k)\log k)$，空间 $O(n+k)$。

### 易错点

无三点共线保证候选不会恰好落在某凸包边延长线上，侧别二分无零值歧义。不能只取离某一个点最远的候选。

## [WF2011]Trash Removal（改）

### 题意

物体可旋转后直线通过，求最小平行带宽。

### 思路

所需是点集的最小宽度，只由凸包决定。最优一侧支撑线可沿凸包某条边；对每条边，宽度为所有凸包点到其所在直线的最大距离。n≤100，直接枚举边和点，取各宽度最小即可。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

vector<Point> convexHull(vector<Point> point) {
    sort(point.begin(), point.end(),
         [](Point a, Point b) { return a.x != b.x ? a.x < b.x : a.y < b.y; });
    point.erase(unique(point.begin(), point.end(),
                       [](Point a, Point b) { return a.x == b.x && a.y == b.y; }),
                point.end());
    if (point.size() < 2)
        return point;
    vector<Point> hull;
    for (Point p : point) {
        while (hull.size() >= 2 && cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    size_t lower = hull.size();
    for (int i = (int)point.size() - 2; i >= 0; i--) {
        Point p = point[i];
        while (hull.size() > lower &&
               cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    hull.pop_back();
    return hull;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    while (cin >> n && n) {
        vector<Point> p(n);
        for (auto &a : p)
            cin >> a.x >> a.y;
        auto h = convexHull(p);
        long double answer = 0;
        if (h.size() > 2) {
            answer = 1e100L;
            for (int i = 0; i < (int)h.size(); i++) {
                Point e = h[(i + 1) % h.size()] - h[i];
                long double width = 0;
                for (auto q : h)
                    width = max(width, fabsl(cross(e, q - h[i])) / norm(e));
                answer = min(answer, width);
            }
        }
        cout << fixed << setprecision(12) << answer << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n²+n\log n)$，空间 $O(n)$。

### 易错点

此页修改版只输出高精度宽度，没有原WF版本的Case编号和向上取两位小数要求。

## Most Distant Point from the Sea

### 题意

求凸多边形内距离海岸最远的点到边界的距离。

### 思路

答案是最大内切圆半径。检验半径r时，圆心必须在每条逆时针边左侧，且到边所在直线距离至少r；把每条边沿单位左法向量向内平移r，求这些左半平面的交。交非空就可放置该圆，随着r增加可行域只会缩小，二分60轮足以达到1e−5精度。

半平面交将直线按方向角排序，同向线只保留更靠内的一条，用双端队列维护相邻交点：新约束不包含队尾或队首交点时弹出对应线，最后收尾闭合。代码加入远大于输入范围的辅助方框，统一处理过程中的无界交；它不改变本题有界答案。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

struct Line {
    Point p, d;
    long double angle;
};
Line line(Point a, Point b) {
    Point d = (b - a) / distance(a, b);
    return {a, d, atan2l(d.y, d.x)};
}
bool left(const Line &l, Point p) { return cross(l.d, p - l.p) >= -1e-15L; }
Point intersection(const Line &a, const Line &b) {
    return a.p + a.d * (cross(b.p - a.p, b.d) / cross(a.d, b.d));
}
vector<Point> halfplanes(vector<Line> input) {
    const long double box = 1e9L;
    vector<Point> corners = {{-box, -box}, {box, -box}, {box, box}, {-box, box}};
    for (int i = 0; i < 4; i++)
        input.push_back(line(corners[i], corners[(i + 1) % 4]));
    sort(input.begin(), input.end(),
         [](const Line &a, const Line &b) { return a.angle < b.angle; });
    vector<Line> unique;
    for (auto l : input) {
        if (!unique.empty() && fabsl(cross(unique.back().d, l.d)) < 1e-18L &&
            dot(unique.back().d, l.d) > 0) {
            if (cross(unique.back().d, l.p - unique.back().p) > 0)
                unique.back() = l;
        } else
            unique.push_back(l);
    }
    deque<Line> q;
    for (auto l : unique) {
        while (q.size() > 1 && !left(l, intersection(q[q.size() - 2], q.back())))
            q.pop_back();
        while (q.size() > 1 && !left(l, intersection(q[0], q[1])))
            q.pop_front();
        if (!q.empty() && fabsl(cross(q.back().d, l.d)) < 1e-18L)
            return {};
        q.push_back(l);
    }
    while (q.size() > 2 && !left(q.front(), intersection(q[q.size() - 2], q.back())))
        q.pop_back();
    while (q.size() > 2 && !left(q.back(), intersection(q[0], q[1])))
        q.pop_front();
    if (q.size() < 3 || fabsl(cross(q.front().d, q.back().d)) < 1e-18L)
        return {};
    vector<Point> result;
    for (int i = 0; i < (int)q.size(); i++)
        result.push_back(intersection(q[i], q[(i + 1) % q.size()]));
    return result;
}
long double polygonArea(const vector<Point> &p) {
    long double sum = 0;
    for (int i = 0; i < (int)p.size(); i++)
        sum += cross(p[i], p[(i + 1) % p.size()]);
    return fabsl(sum) / 2;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    while (cin >> n && n) {
        vector<Point> p(n);
        for (auto &q : p)
            cin >> q.x >> q.y;
        auto feasible = [&](long double radius) {
            vector<Line> lines;
            for (int i = 0; i < n; i++) {
                Point a = p[i], b = p[(i + 1) % n],
                      offset = rotate90((b - a) / distance(a, b)) * radius;
                lines.push_back(line(a + offset, b + offset));
            }
            return !halfplanes(lines).empty();
        };
        long double l = 0, r = 10000;
        for (int i = 0; i < 65; i++) {
            long double mid = (l + r) / 2;
            if (feasible(mid))
                l = mid;
            else
                r = mid;
        }
        cout << fixed << setprecision(12) << l << '\n';
    }
    return 0;
}
