## Jerome's House

### 题意

三个半径r圆完全在凸房间内，使三个圆心行列式绝对值最大。

### 思路

圆心可行域是房间各边向内平移r后的半平面交。输入顶点为顺时针，先反转成逆时针，再沿左法向量内缩。目标|w1+w2+w3|正是三个圆心构成三角形的二倍面积。固定另两点时面积对第三点是线性的，故最大值一定可在可行域顶点上取得。

得到凸多边形后，枚举第一个顶点i，第二个顶点j沿序前进，用单调指针k找离ij最远的顶点；凸性保证k不回退。每个i花O(h)，总O(h²)。输出二倍面积即可，题目允许圆毯互相重叠。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

struct Line {
    Point p, d;
    long double angle;
};
Line line(Point a, Point b) {
    Point d = (b - a) / distance(a, b);
    return {a, d, atan2l(d.y, d.x)};
}
bool left(const Line &l, Point p) { return cross(l.d, p - l.p) >= -1e-15L; }
Point intersection(const Line &a, const Line &b) {
    return a.p + a.d * (cross(b.p - a.p, b.d) / cross(a.d, b.d));
}
vector<Point> halfplanes(vector<Line> input) {
    const long double box = 1e9L;
    vector<Point> corners = {{-box, -box}, {box, -box}, {box, box}, {-box, box}};
    for (int i = 0; i < 4; i++)
        input.push_back(line(corners[i], corners[(i + 1) % 4]));
    sort(input.begin(), input.end(),
         [](const Line &a, const Line &b) { return a.angle < b.angle; });
    vector<Line> unique;
    for (auto l : input) {
        if (!unique.empty() && fabsl(cross(unique.back().d, l.d)) < 1e-18L &&
            dot(unique.back().d, l.d) > 0) {
            if (cross(unique.back().d, l.p - unique.back().p) > 0)
                unique.back() = l;
        } else
            unique.push_back(l);
    }
    deque<Line> q;
    for (auto l : unique) {
        while (q.size() > 1 && !left(l, intersection(q[q.size() - 2], q.back())))
            q.pop_back();
        while (q.size() > 1 && !left(l, intersection(q[0], q[1])))
            q.pop_front();
        if (!q.empty() && fabsl(cross(q.back().d, l.d)) < 1e-18L)
            return {};
        q.push_back(l);
    }
    while (q.size() > 2 && !left(q.front(), intersection(q[q.size() - 2], q.back())))
        q.pop_back();
    while (q.size() > 2 && !left(q.back(), intersection(q[0], q[1])))
        q.pop_front();
    if (q.size() < 3 || fabsl(cross(q.front().d, q.back().d)) < 1e-18L)
        return {};
    vector<Point> result;
    for (int i = 0; i < (int)q.size(); i++)
        result.push_back(intersection(q[i], q[(i + 1) % q.size()]));
    return result;
}
long double polygonArea(const vector<Point> &p) {
    long double sum = 0;
    for (int i = 0; i < (int)p.size(); i++)
        sum += cross(p[i], p[(i + 1) % p.size()]);
    return fabsl(sum) / 2;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        long double radius;
        cin >> n >> radius;
        vector<Point> p(n);
        for (auto &q : p)
            cin >> q.x >> q.y;
        reverse(p.begin(), p.end());
        vector<Line> lines;
        for (int i = 0; i < n; i++) {
            Point a = p[i], b = p[(i + 1) % n],
                  offset = rotate90((b - a) / distance(a, b)) * radius;
            lines.push_back(line(a + offset, b + offset));
        }
        auto q = halfplanes(lines);
        int h = q.size();
        long double answer = 0;
        for (int i = 0; i < h; i++) {
            int k = i + 2;
            for (int j = i + 1; j + 1 < h; j++) {
                k = max(k, j + 1);
                auto area = [&](int at) { return cross(q[j] - q[i], q[at] - q[i]); };
                while (k + 1 < h && area(k + 1) > area(k))
                    k++;
                answer = max(answer, area(k));
            }
        }
        cout << fixed << setprecision(4) << answer << '\n';
    }
    return 0;
}
```

### 复杂度

时间 $O(n\log n+h^2)$，空间 $O(n+h)$。

### 易错点

不需要给三个圆心互加距离≥2r的限制，题面并未禁止地毯重叠。行列式已经是题目价格，不能再除2。

## [WF2019]First of Her Name

### 题意

每位女士姓名为新字母接母亲姓名，批量统计给定姓名前缀。

### 思路

把姓名和查询都反转：反转姓名是从家族根到该女士的边字母序列，查询前缀变为这条根路径的后缀。将全部反转查询建AC自动机。母亲编号小于女儿，按编号计算state[i]=go(state[parent[i]],c[i])，给该状态计数加1。所有女士处理后按fail逆BFS汇总，查询终点计数即有该反转后缀的根路径数，也就是原问题答案。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Aho {
    struct Node {
        array<int, 26> next = {};
        int fail = 0, parent = 0, letter = 0, longest = 0;
    };
    vector<Node> node;
    vector<int> order;
    int alphabet;
    char base;
    Aho(int alphabet, char base, size_t capacity) : alphabet(alphabet), base(base) {
        node.reserve(capacity);
        node.emplace_back();
    }
    int insert(const string &s) {
        int u = 0;
        for (char ch : s) {
            int c = ch - base;
            if (!node[u].next[c]) {
                int v = node.size();
                node[u].next[c] = v;
                node.emplace_back();
                node[v].parent = u;
                node[v].letter = c;
            }
            u = node[u].next[c];
        }
        node[u].longest = max(node[u].longest, (int)s.size());
        return u;
    }
    void build() {
        order = {0};
        for (int c = 0; c < alphabet; c++)
            if (node[0].next[c])
                order.push_back(node[0].next[c]);
        for (size_t i = 1; i < order.size(); i++) {
            int u = order[i], f = node[u].fail;
            node[u].longest = max(node[u].longest, node[f].longest);
            for (int c = 0; c < alphabet; c++) {
                int v = node[u].next[c];
                if (v) {
                    node[v].fail = node[f].next[c];
                    order.push_back(v);
                } else
                    node[u].next[c] = node[f].next[c];
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<int> parent(n + 1);
    string letter(n + 1, 'A');
    for (int i = 1; i <= n; i++)
        cin >> letter[i] >> parent[i];
    vector<string> query(k);
    size_t total = 1;
    for (auto &s : query) {
        cin >> s;
        reverse(s.begin(), s.end());
        total += s.size();
    }
    Aho ac(26, 'A', total);
    vector<int> end(k);
    for (int i = 0; i < k; i++)
        end[i] = ac.insert(query[i]);
    ac.build();
    vector<int> state(n + 1);
    vector<long long> count(ac.node.size());
    for (int i = 1; i <= n; i++) {
        state[i] = ac.node[state[parent[i]]].next[letter[i] - 'A'];
        count[state[i]]++;
    }
    for (int i = (int)ac.order.size() - 1; i > 0; i--) {
        int u = ac.order[i];
        count[ac.node[u].fail] += count[u];
    }
    for (int u : end)
        cout << count[u] << '\n';
    return 0;
}
```

### 复杂度

查询总长L，时间 $O(26L+n+k)$，空间 $O(26L+n+k)$。

### 易错点

不要显式拼接每个完整姓名，链状家族会产生平方总长度。每位女士只贡献其整条根路径的结尾一次。

## [CERC2018]The ABCD Murderer

### 题意

用字典单词覆盖目标串，允许匹配部分重叠，最少单词数。

### 思路

AC自动机每个状态保存自身及fail链上的最长模式长度。扫描目标串，第i位得到的最长匹配区间[i−len+1,i]包含同终点的全部较短匹配，所以只保留它。对每个左端记录最远右端。

之后贪心覆盖：当前已覆盖[0,covered)，把左端≤covered的区间都纳入候选，选择能把右端推得最远的一个。若无法前进就无解。交换论证：任何可行下一块必须与当前覆盖衔接，选最远不会增加之后所需块数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Aho {
    struct Node {
        array<int, 26> next = {};
        int fail = 0, parent = 0, letter = 0, longest = 0;
    };
    vector<Node> node;
    vector<int> order;
    int alphabet;
    char base;
    Aho(int alphabet, char base, size_t capacity) : alphabet(alphabet), base(base) {
        node.reserve(capacity);
        node.emplace_back();
    }
    int insert(const string &s) {
        int u = 0;
        for (char ch : s) {
            int c = ch - base;
            if (!node[u].next[c]) {
                int v = node.size();
                node[u].next[c] = v;
                node.emplace_back();
                node[v].parent = u;
                node[v].letter = c;
            }
            u = node[u].next[c];
        }
        node[u].longest = max(node[u].longest, (int)s.size());
        return u;
    }
    void build() {
        order = {0};
        for (int c = 0; c < alphabet; c++)
            if (node[0].next[c])
                order.push_back(node[0].next[c]);
        for (size_t i = 1; i < order.size(); i++) {
            int u = order[i], f = node[u].fail;
            node[u].longest = max(node[u].longest, node[f].longest);
            for (int c = 0; c < alphabet; c++) {
                int v = node[u].next[c];
                if (v) {
                    node[v].fail = node[f].next[c];
                    order.push_back(v);
                } else
                    node[u].next[c] = node[f].next[c];
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string text;
    cin >> n >> text;
    vector<string> pattern(n);
    size_t total = 1;
    for (auto &s : pattern) {
        cin >> s;
        total += s.size();
    }
    Aho ac(26, 'a', total);
    for (auto &s : pattern)
        ac.insert(s);
    ac.build();
    vector<int> farthest(text.size(), -1);
    int u = 0;
    for (int i = 0; i < (int)text.size(); i++) {
        u = ac.node[u].next[text[i] - 'a'];
        int length = ac.node[u].longest;
        if (length) {
            int start = i - length + 1;
            farthest[start] = max(farthest[start], i + 1);
        }
    }
    int covered = 0, scan = 0, best = 0, answer = 0;
    while (covered < (int)text.size()) {
        while (scan <= (int)covered && scan < (int)text.size())
            best = max(best, farthest[scan++]);
        if (best <= covered) {
            cout << -1;
            return 0;
        }
        covered = best;
        answer++;
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(26L+N)$，空间 $O(26L+N)$。

### 易错点

允许重叠，所以不能用只允许首尾相接的分词DP。只使用完整单词的匹配区间，不任意裁剪单词。

## Mogohu-Rea Idol

### 题意

三凸城各选一祭坛，其等质量重心能否在查询山丘。

### 思路

重心q=(a+b+c)/3可行，当且仅当3q属于三个城市的闵可夫斯基和A+B+C。凸多边形和可按边向量极角线性合并，同方向向量相加；从各自最低顶点之和出发即可得到新凸包。先合并三城，再对3倍山丘坐标做含边界的凸多边形二分包含判断。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

using Wide = __int128_t;
struct IPoint {
    long long x = 0, y = 0;
    IPoint operator+(IPoint b) const { return {x + b.x, y + b.y}; }
    IPoint operator-(IPoint b) const { return {x - b.x, y - b.y}; }
};
Wide cross(IPoint a, IPoint b) { return (Wide)a.x * b.y - (Wide)a.y * b.x; }
Wide dot(IPoint a, IPoint b) { return (Wide)a.x * b.x + (Wide)a.y * b.y; }
Wide absolute(Wide x) { return x < 0 ? -x : x; }
void printWide(Wide value) {
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string text;
    do {
        text.push_back('0' + value % 10);
        value /= 10;
    } while (value);
    reverse(text.begin(), text.end());
    cout << text;
}
bool angleLess(IPoint a, IPoint b) {
    auto half = [](IPoint p) { return p.y < 0 || (p.y == 0 && p.x < 0); };
    if (half(a) != half(b))
        return half(a) < half(b);
    return cross(a, b) > 0;
}
vector<IPoint> integerHull(vector<IPoint> point) {
    sort(point.begin(), point.end(),
         [](auto a, auto b) { return a.x != b.x ? a.x < b.x : a.y < b.y; });
    point.erase(
        unique(point.begin(), point.end(), [](auto a, auto b) { return a.x == b.x && a.y == b.y; }),
        point.end());
    if (point.size() < 2)
        return point;
    vector<IPoint> hull;
    for (auto p : point) {
        while (hull.size() >= 2 && cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    size_t lower = hull.size();
    for (int i = (int)point.size() - 2; i >= 0; i--) {
        auto p = point[i];
        while (hull.size() > lower &&
               cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    hull.pop_back();
    return hull;
}

struct Support {
    const vector<IPoint> &point;
    vector<pair<IPoint, int>> normal;
    explicit Support(const vector<IPoint> &p) : point(p) {
        if (p.size() < 3)
            return;
        for (int i = 0; i < (int)p.size(); i++) {
            IPoint e = p[(i + 1) % p.size()] - p[i];
            normal.push_back({{e.y, -e.x}, i});
        }
        sort(normal.begin(), normal.end(),
             [](auto a, auto b) { return angleLess(a.first, b.first); });
    }
    int index(IPoint direction) const {
        if (point.size() < 3) {
            int best = 0;
            for (int i = 1; i < (int)point.size(); i++)
                if (dot(point[i], direction) > dot(point[best], direction))
                    best = i;
            return best;
        }
        auto it = lower_bound(normal.begin(), normal.end(), direction,
                              [](const auto &a, IPoint b) { return angleLess(a.first, b); });
        if (it == normal.end())
            it = normal.begin();
        return it->second;
    }
};
int visibleEdge(const vector<IPoint> &p, IPoint q) {
    int n = p.size();
    if (cross(p[1] - p[0], q - p[0]) < 0)
        return 0;
    if (cross(p[n - 1] - p[0], q - p[0]) > 0)
        return n - 1;
    int l = 1, r = n - 1;
    while (r - l > 1) {
        int mid = (l + r) / 2;
        if (cross(p[mid] - p[0], q - p[0]) >= 0)
            l = mid;
        else
            r = mid;
    }
    return cross(p[r] - p[l], q - p[l]) < 0 ? l : -1;
}
bool insideConvex(const vector<IPoint> &p, IPoint q, bool strict) {
    int n = p.size();
    if (n == 1)
        return !strict && q.x == p[0].x && q.y == p[0].y;
    if (n == 2)
        return !strict && cross(p[1] - p[0], q - p[0]) == 0 && dot(q - p[0], q - p[1]) <= 0;
    Wide a = cross(p[1] - p[0], q - p[0]), b = cross(p[n - 1] - p[0], q - p[0]);
    if (a < 0 || b > 0)
        return false;
    if (a == 0)
        return !strict && dot(q - p[0], q - p[1]) <= 0;
    if (b == 0)
        return !strict && dot(q - p[0], q - p[n - 1]) <= 0;
    int l = 1, r = n - 1;
    while (r - l > 1) {
        int mid = (l + r) / 2;
        if (cross(p[mid] - p[0], q - p[0]) >= 0)
            l = mid;
        else
            r = mid;
    }
    Wide side = cross(p[r] - p[l], q - p[l]);
    return strict ? side > 0 : side >= 0;
}
vector<IPoint> minkowski(vector<IPoint> a, vector<IPoint> b) {
    if (a.size() < 3 || b.size() < 3) {
        vector<IPoint> sum;
        for (auto p : a)
            for (auto q : b)
                sum.push_back(p + q);
        return integerHull(sum);
    }
    auto prepare = [](vector<IPoint> &p) {
        auto it = min_element(p.begin(), p.end(),
                              [](auto a, auto b) { return a.y != b.y ? a.y < b.y : a.x < b.x; });
        rotate(p.begin(), it, p.end());
    };
    prepare(a);
    prepare(b);
    int n = a.size(), m = b.size(), i = 0, j = 0;
    vector<IPoint> result;
    IPoint current = a[0] + b[0];
    result.push_back(current);
    while (i < n || j < m) {
        IPoint x = i < n ? a[(i + 1) % n] - a[i] : IPoint{},
               y = j < m ? b[(j + 1) % m] - b[j] : IPoint{};
        Wide c = cross(x, y);
        if (j == m || (i < n && c > 0)) {
            current = current + x;
            i++;
        } else if (i == n || c < 0) {
            current = current + y;
            j++;
        } else {
            current = current + x + y;
            i++;
            j++;
        }
        result.push_back(current);
    }
    result.pop_back();
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<IPoint> sum;
    for (int t = 0; t < 3; t++) {
        int n;
        cin >> n;
        vector<IPoint> p(n);
        for (auto &a : p)
            cin >> a.x >> a.y;
        if (!t)
            sum = p;
        else
            sum = minkowski(sum, p);
    }
    int m;
    cin >> m;
    while (m--) {
        IPoint q;
        cin >> q.x >> q.y;
        q.x *= 3;
        q.y *= 3;
        cout << (insideConvex(sum, q, false) ? "YES\n" : "NO\n");
    }
    return 0;
}
```

### 复杂度

合并 $O(n_1+n_2+n_3)$，每问 $O(\log(n_1+n_2+n_3))$，空间同总顶点数。

### 易错点

祭坛可位于城市边界，包含判断允许叉积0。用3q避免除3产生浮点误差，坐标与叉积分别用64/128位。

## 矩形面积并

### 题意

求有重叠轴平行矩形的并面积。

### 思路

按x扫描左右边界，每次对y区间覆盖次数加1或减1。将y端点离散化，树叶代表相邻端点之间的真实长度；节点覆盖次数>0时全段覆盖，否则覆盖长度由子节点相加。前后事件之间覆盖总长不变，面积增加x差乘根节点覆盖长度。输入上下角坐标先统一为升序。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct CoverTree {
    vector<long long> coordinate, length;
    vector<int> count;
    CoverTree(vector<long long> x)
        : coordinate(move(x)), length(coordinate.size() * 4 + 4), count(length.size()) {}
    void change(int u, int l, int r, int ql, int qr, int delta) {
        if (ql <= l && r <= qr)
            count[u] += delta;
        else {
            int mid = (l + r) / 2;
            if (ql <= mid)
                change(u * 2, l, mid, ql, qr, delta);
            if (qr > mid)
                change(u * 2 + 1, mid + 1, r, ql, qr, delta);
        }
        if (count[u])
            length[u] = coordinate[r + 1] - coordinate[l];
        else
            length[u] = l == r ? 0 : length[u * 2] + length[u * 2 + 1];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    struct Event {
        long long x, low, high;
        int delta;
    };
    vector<Event> event;
    vector<long long> y;
    for (int i = 0; i < n; i++) {
        long long x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        if (x1 > x2)
            swap(x1, x2);
        if (y1 > y2)
            swap(y1, y2);
        if (x1 == x2 || y1 == y2)
            continue;
        event.push_back({x1, y1, y2, 1});
        event.push_back({x2, y1, y2, -1});
        y.push_back(y1);
        y.push_back(y2);
    }
    if (event.empty()) {
        cout << 0;
        return 0;
    }
    sort(y.begin(), y.end());
    y.erase(unique(y.begin(), y.end()), y.end());
    sort(event.begin(), event.end(), [](auto a, auto b) { return a.x < b.x; });
    CoverTree tree(y);
    long long area = 0, previous = event[0].x;
    for (auto e : event) {
        area += (e.x - previous) * tree.length[1];
        previous = e.x;
        int l = lower_bound(y.begin(), y.end(), e.low) - y.begin();
        int r = lower_bound(y.begin(), y.end(), e.high) - y.begin() - 1;
        tree.change(1, 0, (int)y.size() - 2, l, r, e.delta);
    }
    cout << area;
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

离散下标距离不是几何长度，长度必须用原坐标相减。区间按半开[y1,y2)维护，对应叶下标到rank(y2)−1。

## Square Card

### 题意

正方形能旋转进入两个圆时，求同时获奖的条件概率。

### 思路

先确定可得分的正方形中心区域。中心距圆心为d时，旋转正方形，使一条边平行于中心连线，能使最远顶点距离最小，其平方为$(d+a/2)^2+(a/2)^2$。所以允许中心距为$\rho=\sqrt{r^2-a^2/4}-a/2$，可行中心区域是半径ρ的圆盘。

两次只要求“各自存在一个转角”，无需同一转角同时进入两个圆。因此条件概率是两个可行中心圆盘交面积除以第一圆盘面积。奖金圆若r≤a/√2，可行中心区域没有正面积，概率为0。相交面积分别处理相离、包含和相交两扇形减三角形。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

long double intersectionArea(long double r, long double s, long double d) {
    if (r <= 0 || s <= 0 || d >= r + s)
        return 0;
    const long double pi = acosl(-1.0L);
    if (d <= fabsl(r - s))
        return pi * min(r, s) * min(r, s);
    long double a = acosl(clamp((r * r + d * d - s * s) / (2 * r * d), -1.0L, 1.0L));
    long double b = acosl(clamp((s * s + d * d - r * r) / (2 * s * d), -1.0L, 1.0L));
    return r * r * (a - sinl(2 * a) / 2) + s * s * (b - sinl(2 * b) / 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        long double r, s, a;
        Point p, q;
        cin >> r >> p.x >> p.y >> s >> q.x >> q.y >> a;
        auto available = [&](long double radius) {
            if (2 * radius * radius <= a * a)
                return 0.0L;
            return sqrtl(radius * radius - a * a / 4) - a / 2;
        };
        r = available(r);
        s = available(s);
        cout << fixed << setprecision(6)
             << intersectionArea(r, s, distance(p, q)) / (acosl(-1.0L) * r * r) << '\n';
    }
    return 0;
}
```

### 复杂度

时间与额外空间均为 $O(1)$。

### 易错点

不能直接把大圆半径减去正方形外接圆半径：允许旋转时可行中心更大。严格内含只排除边界，对连续概率无影响。

## Jungle Outpost

### 题意

选择总部位置，使敌人至少删除尽量多的凸包顶点才失去严格保护。

### 思路

删除任意k个塔后仍严格受保护，等价于总部在所有“跳过k个连续顶点”的弦的左侧。原因是：把总部划到凸包外的分割线，其外侧塔在凸包环上连续；若能用k个任意删除达到目的，也能只删这一段至多k个连续塔。

将顶点改为逆时针。要让最少破坏数≥r，必须经得起删除r−1个塔，因此求所有有向弦P_i→P_(i+r)的左半平面交。总部必须严格在内部，交只有线段或一点时不合格，要有正面积。r增大时要求更强，二分最大可行r。上界floor((n−1)/2)：任一经过总部的直线两侧至少一侧不超过这个数量，边界本身也不受严格保护。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

struct Line {
    Point p, d;
    long double angle;
};
Line line(Point a, Point b) {
    Point d = (b - a) / distance(a, b);
    return {a, d, atan2l(d.y, d.x)};
}
bool left(const Line &l, Point p) { return cross(l.d, p - l.p) >= -1e-15L; }
Point intersection(const Line &a, const Line &b) {
    return a.p + a.d * (cross(b.p - a.p, b.d) / cross(a.d, b.d));
}
vector<Point> halfplanes(vector<Line> input) {
    const long double box = 1e9L;
    vector<Point> corners = {{-box, -box}, {box, -box}, {box, box}, {-box, box}};
    for (int i = 0; i < 4; i++)
        input.push_back(line(corners[i], corners[(i + 1) % 4]));
    sort(input.begin(), input.end(),
         [](const Line &a, const Line &b) { return a.angle < b.angle; });
    vector<Line> unique;
    for (auto l : input) {
        if (!unique.empty() && fabsl(cross(unique.back().d, l.d)) < 1e-18L &&
            dot(unique.back().d, l.d) > 0) {
            if (cross(unique.back().d, l.p - unique.back().p) > 0)
                unique.back() = l;
        } else
            unique.push_back(l);
    }
    deque<Line> q;
    for (auto l : unique) {
        while (q.size() > 1 && !left(l, intersection(q[q.size() - 2], q.back())))
            q.pop_back();
        while (q.size() > 1 && !left(l, intersection(q[0], q[1])))
            q.pop_front();
        if (!q.empty() && fabsl(cross(q.back().d, l.d)) < 1e-18L)
            return {};
        q.push_back(l);
    }
    while (q.size() > 2 && !left(q.front(), intersection(q[q.size() - 2], q.back())))
        q.pop_back();
    while (q.size() > 2 && !left(q.back(), intersection(q[0], q[1])))
        q.pop_front();
    if (q.size() < 3 || fabsl(cross(q.front().d, q.back().d)) < 1e-18L)
        return {};
    vector<Point> result;
    for (int i = 0; i < (int)q.size(); i++)
        result.push_back(intersection(q[i], q[(i + 1) % q.size()]));
    return result;
}
long double polygonArea(const vector<Point> &p) {
    long double sum = 0;
    for (int i = 0; i < (int)p.size(); i++)
        sum += cross(p[i], p[(i + 1) % p.size()]);
    return fabsl(sum) / 2;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<Point> p(n);
    for (auto &q : p)
        cin >> q.x >> q.y;
    reverse(p.begin(), p.end());
    auto feasible = [&](int step) {
        vector<Line> lines;
        for (int i = 0; i < n; i++)
            lines.push_back(line(p[i], p[(i + step) % n]));
        auto q = halfplanes(lines);
        return q.size() >= 3 && polygonArea(q) > 1e-16L;
    };
    int l = 1, r = (n + 1) / 2;
    while (r - l > 1) {
        int mid = (l + r) / 2;
        if (feasible(mid))
            l = mid;
        else
            r = mid;
    }
    cout << l;
    return 0;
}
```

### 复杂度

时间 $O(n\log^2 n)$，空间 $O(n)$。

### 易错点

严格内部很关键：四个塔组成正方形时，两条对角线交点会在删去一个塔后的边界上，最优破坏数仍是1。只判断闭半平面交非空会算错。

## 小A买彩票

### 题意

买n张三元彩票，奖金均匀为1到4元，求总奖金至少3n的精确概率。

### 思路

所有4^n种奖金序列等可能。dp[sum]记录已经买若干张后，奖金总和为sum的序列数，每张依次加1、2、3、4。最后把sum≥3n的计数相加作为分子，分母为4^n，用gcd约分。n≤30，4^30=2^60在64位范围内，无需浮点或大整数。n=0的空序列不亏，概率1/1。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> dp(4 * n + 1);
    dp[0] = 1;
    long long denominator = 1;
    for (int i = 0; i < n; i++) {
        vector<long long> next(4 * n + 1);
        for (int sum = 0; sum <= 4 * i; sum++)
            for (int reward = 1; reward <= 4; reward++)
                next[sum + reward] += dp[sum];
        dp.swap(next);
        denominator *= 4;
    }
    long long numerator = 0;
    for (int sum = 3 * n; sum <= 4 * n; sum++)
        numerator += dp[sum];
    long long divisor = gcd(numerator, denominator);
    cout << numerator / divisor << '/' << denominator / divisor;
    return 0;
}
```

### 复杂度

时间 $O(n^2)$，空间 $O(n)$。

### 易错点

不亏包括刚好收回3n。每张只能选四种奖金之一，不能把奖金总额视为等概率。

## 文本生成器加强版

### 题意

统计长M大写文本中至少出现一个模式的数量。

### 思路

先数没有任何模式的文本，用26^M减去。AC状态若自身或fail祖先是模式终点则禁用，DP只保留安全状态。朴素逐状态枚举26字符可以正确求解；为兼容M至10000的加强版，下面把每一层转移压到与节点数线性。

设mass[u]为本层DP在fail子树u中的总量，按逆BFS累加得到。先把全部质量乘26放入根作为默认转移。对每条真实Trie边u−c→v，把mass[u]从fallback转移目标移到v：fallback为go(fail[u],c)，根边的fallback为根。对同一个源状态和字符，沿其fail祖先上的这些改道正好依次抵消，只剩最长可用前缀边，所以等价于完整AC转移。最后把所有禁用状态置0。

每层只遍历节点和真实Trie边，既避免漏算重复字母转移，也减少加强版26倍循环。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Aho {
    struct Node {
        array<int, 26> next = {};
        int fail = 0, parent = 0, letter = 0, longest = 0;
    };
    vector<Node> node;
    vector<int> order;
    int alphabet;
    char base;
    Aho(int alphabet, char base, size_t capacity) : alphabet(alphabet), base(base) {
        node.reserve(capacity);
        node.emplace_back();
    }
    int insert(const string &s) {
        int u = 0;
        for (char ch : s) {
            int c = ch - base;
            if (!node[u].next[c]) {
                int v = node.size();
                node[u].next[c] = v;
                node.emplace_back();
                node[v].parent = u;
                node[v].letter = c;
            }
            u = node[u].next[c];
        }
        node[u].longest = max(node[u].longest, (int)s.size());
        return u;
    }
    void build() {
        order = {0};
        for (int c = 0; c < alphabet; c++)
            if (node[0].next[c])
                order.push_back(node[0].next[c]);
        for (size_t i = 1; i < order.size(); i++) {
            int u = order[i], f = node[u].fail;
            node[u].longest = max(node[u].longest, node[f].longest);
            for (int c = 0; c < alphabet; c++) {
                int v = node[u].next[c];
                if (v) {
                    node[v].fail = node[f].next[c];
                    order.push_back(v);
                } else
                    node[u].next[c] = node[f].next[c];
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<string> pattern(n);
    size_t total = 1;
    for (auto &s : pattern) {
        cin >> s;
        total += s.size();
    }
    Aho ac(26, 'A', total);
    for (auto &s : pattern)
        ac.insert(s);
    ac.build();
    const int mod = 10007;
    int size = ac.node.size();
    vector<int> dp(size), mass(size), next(size);
    dp[0] = 1;
    int all = 1;
    for (int step = 0; step < m; step++) {
        all = all * 26 % mod;
        mass = dp;
        for (int i = (int)ac.order.size() - 1; i > 0; i--) {
            int u = ac.order[i], f = ac.node[u].fail;
            mass[f] = (mass[f] + mass[u]) % mod;
        }
        fill(next.begin(), next.end(), 0);
        next[0] = 26 * mass[0] % mod;
        for (int v = 1; v < size; v++) {
            int u = ac.node[v].parent, c = ac.node[v].letter,
                fallback = u ? ac.node[ac.node[u].fail].next[c] : 0;
            next[v] = (next[v] + mass[u]) % mod;
            next[fallback] = (next[fallback] - mass[u] + mod) % mod;
        }
        for (int u = 0; u < size; u++)
            dp[u] = ac.node[u].longest ? 0 : next[u];
    }
    int safe = 0;
    for (int x : dp)
        safe = (safe + x) % mod;
    cout << (all - safe + mod) % mod;
    return 0;
}
```

### 复杂度

模式总长L，时间 $O(26L+ML)$，空间 $O(26L)$。

### 易错点

要把fail链上的模式终点也视为禁用。重定向只遍历原始Trie边，不能把补全的自动机边都当真实边。

## 【模板】AC 自动机（二次加强版）

### 题意

统计每个模式串在文本的出现次数，含重复模式。

### 思路

建立所有模式的Trie并构造fail指针，记录每个模式的终点。扫描文本时沿自动机转移，只给当前状态计数加1。若某模式是当前状态代表串的后缀，它的终点必在当前状态的fail祖先链上。扫描后按BFS序逆序把count[u]加到count[fail[u]]，一次性汇总全部后缀匹配。模式重复时共享终点，分别输出同一个计数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Aho {
    struct Node {
        array<int, 26> next = {};
        int fail = 0, parent = 0, letter = 0, longest = 0;
    };
    vector<Node> node;
    vector<int> order;
    int alphabet;
    char base;
    Aho(int alphabet, char base, size_t capacity) : alphabet(alphabet), base(base) {
        node.reserve(capacity);
        node.emplace_back();
    }
    int insert(const string &s) {
        int u = 0;
        for (char ch : s) {
            int c = ch - base;
            if (!node[u].next[c]) {
                int v = node.size();
                node[u].next[c] = v;
                node.emplace_back();
                node[v].parent = u;
                node[v].letter = c;
            }
            u = node[u].next[c];
        }
        node[u].longest = max(node[u].longest, (int)s.size());
        return u;
    }
    void build() {
        order = {0};
        for (int c = 0; c < alphabet; c++)
            if (node[0].next[c])
                order.push_back(node[0].next[c]);
        for (size_t i = 1; i < order.size(); i++) {
            int u = order[i], f = node[u].fail;
            node[u].longest = max(node[u].longest, node[f].longest);
            for (int c = 0; c < alphabet; c++) {
                int v = node[u].next[c];
                if (v) {
                    node[v].fail = node[f].next[c];
                    order.push_back(v);
                } else
                    node[u].next[c] = node[f].next[c];
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<string> pattern(n);
    size_t total = 1;
    for (auto &s : pattern) {
        cin >> s;
        total += s.size();
    }
    Aho ac(26, 'a', total);
    vector<int> end(n);
    for (int i = 0; i < n; i++)
        end[i] = ac.insert(pattern[i]);
    ac.build();
    string text;
    cin >> text;
    vector<long long> count(ac.node.size());
    int u = 0;
    for (char c : text) {
        u = ac.node[u].next[c - 'a'];
        count[u]++;
    }
    for (int i = (int)ac.order.size() - 1; i > 0; i--) {
        int v = ac.order[i];
        count[ac.node[v].fail] += count[v];
    }
    for (int v : end)
        cout << count[v] << '\n';
    return 0;
}
```

### 复杂度

模式总长L、文本长N，时间 $O(26L+N)$，空间 $O(26L+N)$。

### 易错点

不在每个字符处遍历整条fail链，否则重复字符数据可退化平方。出现允许重叠。

## 小A的最短路

### 题意

树上另有一条免费缆车边，批量求两点最少步行距离。

### 思路

最短路线若不用缆车，代价为树距离dist(x,y)；若使用，因为树边正权，免费缆车最多有必要用一次，分别考虑x→U、V→y以及x→V、U→y。取三个代价的最小值。树距离由深度和LCA得到，倍增预处理后每次查询对数时间。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct EulerTree {
    int n;
    vector<vector<int>> edge;
    vector<int> parent, depth, in, out, order;
    EulerTree(int n) : n(n), edge(n + 1), parent(n + 1), depth(n + 1), in(n + 1), out(n + 1) {}
    void add(int u, int v) {
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    void root(int start) {
        vector<int> stack = {start};
        parent[start] = 0;
        order.clear();
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            in[u] = order.size() + 1;
            order.push_back(u);
            for (int v : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack.push_back(v);
                }
        }
        vector<int> size(n + 1, 1);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            out[u] = in[u] + size[u] - 1;
            if (parent[u])
                size[parent[u]] += size[u];
        }
    }
};

struct Ancestors {
    const EulerTree &tree;
    vector<vector<int>> up;
    Ancestors(const EulerTree &tree) : tree(tree) {
        int levels = 1;
        while ((1LL << levels) <= tree.n)
            levels++;
        up.assign(levels, vector<int>(tree.n + 1));
        up[0] = tree.parent;
        for (int b = 1; b < levels; b++)
            for (int u = 1; u <= tree.n; u++)
                up[b][u] = up[b - 1][up[b - 1][u]];
    }
    int lca(int u, int v) const {
        if (tree.depth[u] < tree.depth[v])
            swap(u, v);
        int gap = tree.depth[u] - tree.depth[v];
        for (int b = 0; b < (int)up.size(); b++)
            if (gap >> b & 1)
                u = up[b][u];
        if (u == v)
            return u;
        for (int b = (int)up.size() - 1; b >= 0; b--)
            if (up[b][u] != up[b][v]) {
                u = up[b][u];
                v = up[b][v];
            }
        return up[0][u];
    }
    int distance(int u, int v) const {
        return tree.depth[u] + tree.depth[v] - 2 * tree.depth[lca(u, v)];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    EulerTree tree(n);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        tree.add(u, v);
    }
    tree.root(1);
    Ancestors ancestor(tree);
    int u, v, q;
    cin >> u >> v >> q;
    while (q--) {
        int x, y;
        cin >> x >> y;
        cout << min({ancestor.distance(x, y), ancestor.distance(x, u) + ancestor.distance(v, y),
                     ancestor.distance(x, v) + ancestor.distance(u, y)})
             << '\n';
    }
    return 0;
}
```

### 复杂度

预处理 $O(n\log n)$，每问 $O(\log n)$，空间 $O(n\log n)$。

### 易错点

缆车双向且代价为0，不要额外加1。迭代遍历避免长链递归栈溢出。

## Machining Disc Rotors

### 题意

互不相交的圆形切割之后，求原圆剩余部分的直径。

### 思路

剩余区域的凸包由原大圆上未被切掉的圆弧及连接弧端点的弦组成：每个切割造成向内的凹口，凹口圆弧不是凸包极点。直径因此可以只在剩余的大圆圆弧上寻找。

若存在一对保留的对径点，直径为2R。若不存在，对固定端点Q，与它距离最远的保留圆弧点，只能是Q的对径点或某个圆弧端点；前者不可用，所以最远点对都可取圆弧端点。端点就是切割圆与大圆的交点，最多2n个。

如何检查连续圆弧上有无对径点：保留角度集合与其平移π后的交集若非空，除整圆情形外，一定有一个交集端点来自某个圆弧端点。因此逐个检查端点的对径点是否在所有切割圆外即可；若大圆没有交点，整段大圆边界仍保留，直接2R。其余情况枚举端点两两距离。切口边界是否保留不影响直径的上确界。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

vector<Point> circleIntersections(Point a, long double r, Point b, long double s) {
    Point e = b - a;
    long double d = norm(e);
    if (d < EPS || d > r + s + EPS || d < fabsl(r - s) - EPS)
        return {};
    long double x = (r * r - s * s + d * d) / (2 * d), h2 = r * r - x * x;
    if (h2 < -EPS)
        return {};
    Point center = a + e * (x / d), offset = rotate90(e) * (sqrtl(max(0.0L, h2)) / d);
    if (norm(offset) < EPS)
        return {center};
    return {center + offset, center - offset};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    for (int t = 1; t <= tests; t++) {
        int n;
        long double R;
        cin >> n >> R;
        vector<Point> c(n), endpoint;
        vector<long double> radius(n);
        for (int i = 0; i < n; i++) {
            cin >> c[i].x >> c[i].y >> radius[i];
            auto points = circleIntersections({0, 0}, R, c[i], radius[i]);
            endpoint.insert(endpoint.end(), points.begin(), points.end());
        }
        bool diameterExists = endpoint.empty();
        for (Point p : endpoint) {
            Point opposite = p * (-1);
            bool valid = true;
            for (int i = 0; i < n; i++)
                if (dot(opposite - c[i], opposite - c[i]) < radius[i] * radius[i] - 1e-12L) {
                    valid = false;
                    break;
                }
            if (valid) {
                diameterExists = true;
                break;
            }
        }
        long double answer = 0;
        if (diameterExists)
            answer = 2 * R;
        else
            for (int i = 0; i < (int)endpoint.size(); i++)
                for (int j = i + 1; j < (int)endpoint.size(); j++)
                    answer = max(answer, distance(endpoint[i], endpoint[j]));
        cout << "Case #" << t << ": " << fixed << setprecision(15) << answer << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n^2)$，空间 $O(n)$。

### 易错点

利用了切割圆两两不相交、没有切割圆包含整个原圆这两个保证。必须先检查连续圆弧上的对径点，不能只枚举有限个交点。

## Signal Interference

### 题意

求简单多边形内满足|PB|≤k|PA|的区域面积。

### 思路

将距离平方展开配方，干扰区域是圆盘，圆心$C=(B-k^2A)/(1-k^2)$，半径$R=k|A-B|/(1-k^2)$。平移C到原点，按多边形边AB求有向三角形OAB与圆盘交面积，最后取总和绝对值。

把线段AB与圆的交点参数加入0、1并排序。每段的中点在圆内时，贡献cross(P,Q)/2；在圆外时，贡献R²*atan2(cross(P,Q),dot(P,Q))/2，即有向扇形面积。各边相加自动抵消内部射线，凹多边形和任意输入方向都能处理。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, t = 0;
    long double k;
    while (cin >> n >> k) {
        vector<Point> p(n);
        for (auto &q : p)
            cin >> q.x >> q.y;
        Point a, b;
        cin >> a.x >> a.y >> b.x >> b.y;
        Point center = (b - a * (k * k)) / (1 - k * k);
        long double radius = k * distance(a, b) / (1 - k * k), answer = 0;
        for (int i = 0; i < n; i++) {
            Point u = p[i] - center, v = p[(i + 1) % n] - center, e = v - u;
            vector<long double> cut = {0, 1};
            long double A = dot(e, e), B = 2 * dot(u, e), C = dot(u, u) - radius * radius,
                        discriminant = B * B - 4 * A * C;
            if (A > 0 && discriminant > 0) {
                long double root = sqrtl(discriminant);
                for (long double x : {(-B - root) / (2 * A), (-B + root) / (2 * A)})
                    if (x > 0 && x < 1)
                        cut.push_back(x);
            }
            sort(cut.begin(), cut.end());
            for (int j = 1; j < (int)cut.size(); j++) {
                Point x = u + e * cut[j - 1], y = u + e * cut[j], mid = (x + y) / 2;
                if (dot(mid, mid) <= radius * radius)
                    answer += cross(x, y) / 2;
                else
                    answer += radius * radius * atan2l(cross(x, y), dot(x, y)) / 2;
            }
        }
        cout << "Case " << ++t << ": " << fixed << setprecision(12) << fabsl(answer) << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n)$，空间 $O(n)$。

### 易错点

A、B塔不是多边形顶点。圆心分母是1−k²；面积累加有符号贡献，不能对每条边先取绝对值。

## 小A的回文串

### 题意

允许把前缀移到末尾，最大化旋转后某个回文子串的长度。

### 思路

令T=S+S。S任意旋转是T中一个长度n的窗口；反过来，T中任何长度不超过n的连续段，都能放入某个这样的窗口（越过第二份起点的段可整体左移n）。因此只需找T中长度不超过n的最长回文。

Manacher 的 odd[i] 表示以 i 为中心、包含中心的最大奇回文半径，长度为 2odd[i]-1；even[i] 表示中心在 i-1 与 i 之间的最大偶回文半径，长度为 2even[i]。维护已知最靠右的回文区间，利用镜像位置的半径初始化，再只向未知部分扩展。右边界只会前进，全部扩展次数为线性。

奇、偶回文分别把长度截到不超过n的最大同奇偶长度，取最大即可。截短同中心回文仍是回文，故不需要重新验证。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct PalindromeRadii {
    vector<int> odd, even;
    explicit PalindromeRadii(const string &s) {
        int n = s.size();
        odd.resize(n);
        even.resize(n);
        int left = 0, right = -1;
        for (int i = 0; i < n; i++) {
            int k = i > right ? 1 : min(odd[left + right - i], right - i + 1);
            while (i - k >= 0 && i + k < n && s[i - k] == s[i + k])
                k++;
            odd[i] = k;
            if (i + k - 1 > right) {
                left = i - k + 1;
                right = i + k - 1;
            }
        }
        left = 0;
        right = -1;
        for (int i = 0; i < n; i++) {
            int k = i > right ? 0 : min(even[left + right - i + 1], right - i + 1);
            while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k])
                k++;
            even[i] = k;
            if (i + k - 1 > right) {
                left = i - k;
                right = i + k - 1;
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    cin >> s;
    int n = s.size();
    string doubled = s + s;
    PalindromeRadii p(doubled);
    int oddLimit = n % 2 ? n : n - 1, evenLimit = n % 2 ? n - 1 : n, answer = 1;
    for (int i = 0; i < 2 * n; i++) {
        answer = max(answer, min(2 * p.odd[i] - 1, oddLimit));
        answer = max(answer, min(2 * p.even[i], evenLimit));
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间、空间均为 $O(n)$。

### 易错点

不能允许回文超过原串长度。截断奇回文与偶回文时要分别保留奇偶性。

## 素数的个数

### 题意

统计大端点短区间的素数个数。

### 思路

先筛出不超过sqrt(R)的素数，对每个p只标记[L,R]中的合数倍数，从max(p²,ceil(L/p)*p)开始。最后数未标记位置。L≥2，无需额外处理1。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> sieve(int n) {
    vector<bool> composite(n + 1);
    vector<int> primes;
    for (int p = 2; p <= n; p++)
        if (!composite[p]) {
            primes.push_back(p);
            if (1LL * p * p <= n)
                for (int x = p * p; x <= n; x += p)
                    composite[x] = true;
        }
    return primes;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long l, r;
    cin >> l >> r;
    auto primes = sieve(46341);
    vector<bool> composite(r - l + 1);
    for (long long p : primes) {
        if (p * p > r)
            break;
        for (long long x = max(p * p, (l + p - 1) / p * p); x <= r; x += p)
            composite[x - l] = true;
    }
    long long answer = 0;
    for (bool x : composite)
        answer += !x;
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O((R-L+1)\log\log R+\sqrt R\log\log R)$，空间 $O(R-L+\sqrt R)$。

### 易错点

从p²起防止把区间内的素数p自身划掉。扫描与乘法用64位。

## 田忌赛马

> 原题：[P1650](https://www.luogu.com.cn/problem/P1650)
> 解法：优先拿下可赢的两端对局 · C++17

### 题意

两方各有 $n$ 匹马，胜负收益分别为正负二百、平局零，求田忌能够取得的最大净收益。



### 思路

两方速度升序排好。自己的最快若能赢对方最快就配这对；否则自己的最慢若能赢对方最慢就配这对；两端都不能这样赢时，用自己最慢消耗对方最快，按实际胜负计分。

时间 $O(n\log n)$、空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> a(n), b(n);
    for (int &x : a)
        cin >> x;
    for (int &x : b)
        cin >> x;
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    int al = 0, ar = n - 1, bl = 0, br = n - 1, score = 0;
    while (al <= ar) {
        if (a[ar] > b[br]) {
            ++score;
            --ar;
            --br;
        } else if (a[al] > b[bl]) {
            ++score;
            ++al;
            ++bl;
        } else {
            score += (a[al] > b[br]) - (a[al] < b[br]);
            ++al;
            --br;
        }
    }
    cout << 200 * score << '\n';
    return 0;
}
```

### 易错点

允许速度相同，牺牲局也可能是平局；答案是净收益而非赢局数。

## Sramoc问题

### 题意

只用0..K−1数字组成能被M整除的最小正整数。

### 思路

按位追加数字时只需记录当前余数，转移为(10*r+d)%M。BFS按长度递增，并按数字升序扩展，就先得到最短、同长度字典序最小的数字。首位只枚举1..K−1，避免0这个无意义答案。每个余数只访问一次，保存父余数与末位，首次找到余数0后沿父链还原。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int k, m;
    cin >> k >> m;
    vector<int> parent(m, -2), digit(m);
    queue<int> queue;
    for (int d = 1; d < k; d++) {
        int r = d % m;
        if (parent[r] == -2) {
            parent[r] = -1;
            digit[r] = d;
            queue.push(r);
        }
    }
    while (parent[0] == -2 && !queue.empty()) {
        int r = queue.front();
        queue.pop();
        for (int d = 0; d < k; d++) {
            int next = (r * 10 + d) % m;
            if (parent[next] == -2) {
                parent[next] = r;
                digit[next] = d;
                queue.push(next);
            }
        }
    }
    string answer;
    for (int r = 0; r != -1; r = parent[r])
        answer.push_back('0' + digit[r]);
    reverse(answer.begin(), answer.end());
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(KM)$，空间 $O(M)$。

### 易错点

K是允许数码的上界，不是数制，构造的仍是十进制数。不能用普通整数保存可能很长的答案。

## 牛可乐的翻转游戏

### 题意

n×m翻灯变全黑或全白，最少按键数，m≤10。

### 思路

枚举目标颜色和第一行按键。第一行按法确定后，为消掉上一行残留，第i行按键被唯一确定。每行用m位掩码，按键p对本行的影响是p xor(p<<1) xor(p>>1)，再加上下行同列影响。依次强制推出所有行，检查最后一行是否清空，累计popcount取最少。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    int full = (1 << m) - 1;
    vector<int> original(n);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
            char c;
            cin >> c;
            original[i] |= (c - '0') << j;
        }
    int answer = INT_MAX;
    for (int target = 0; target < 2; target++) {
        vector<int> a = original;
        if (target)
            for (int &x : a)
                x ^= full;
        for (int first = 0; first <= full; first++) {
            vector<int> press(n);
            press[0] = first;
            for (int i = 1; i < n; i++)
                press[i] = (a[i - 1] ^ press[i - 1] ^ (press[i - 1] << 1) ^ (press[i - 1] >> 1) ^
                            (i >= 2 ? press[i - 2] : 0)) &
                           full;
            int last = (a[n - 1] ^ press[n - 1] ^ (press[n - 1] << 1) ^ (press[n - 1] >> 1) ^
                        (n >= 2 ? press[n - 2] : 0)) &
                       full;
            if (!last) {
                int count = 0;
                for (int p : press)
                    count += __builtin_popcount((unsigned)p);
                answer = min(answer, count);
            }
        }
    }
    if (answer == INT_MAX)
        cout << "Impossible";
    else
        cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(2^m n+nm)$，空间 $O(n)$。

### 易错点

必须同时考虑全黑和全白。每行位移后用full截掉棋盘外位。

## 晾衣服

### 题意

自然每分钟干1，单台烘干器每分钟使一件干k，求全部干的最短时间。

### 思路

若总时间T，每件自然干T，剩余max(0,a[i]−T)必须由烘干器的额外k−1效率补足，所需烘干分钟ceil(剩余/(k−1))。所有所需分钟之和≤T即能排入单台机器。可行性单调，二分0..max(a)。k=1时机器没有额外效果，直接取最大水量。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n);
    long long high = 0;
    for (auto &x : a) {
        cin >> x;
        high = max(high, x);
    }
    long long k;
    cin >> k;
    if (k == 1) {
        cout << high;
        return 0;
    }
    auto feasible = [&](long long time) {
        long long needed = 0;
        for (long long x : a)
            if (x > time) {
                needed += (x - time + k - 2) / (k - 1);
                if (needed > time)
                    return false;
            }
        return true;
    };
    long long low = 0;
    while (low < high) {
        long long mid = (low + high) / 2;
        if (feasible(mid))
            high = mid;
        else
            low = mid + 1;
    }
    cout << low;
    return 0;
}
```

### 复杂度

时间 $O(n\log\max a)$，空间 $O(n)$。

### 易错点

烘干时总下降k，不是自然1再额外k，所以额外效率为k−1。

## 数字组合

### 题意

四组各选一个数，统计和为0的方案数。

### 思路

枚举前两组的n²个和并排序。再枚举后两组和s，用equal_range统计前表中−s的出现次数，累加即可。各行只是输入四组数据，不限制选取数字来自同一行。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n), b(n), c(n), d(n);
    for (int i = 0; i < n; i++)
        cin >> a[i] >> b[i] >> c[i] >> d[i];
    vector<long long> sum;
    sum.reserve(n * n);
    for (auto x : a)
        for (auto y : b)
            sum.push_back(x + y);
    sort(sum.begin(), sum.end());
    long long answer = 0;
    for (auto x : c)
        for (auto y : d) {
            auto range = equal_range(sum.begin(), sum.end(), -x - y);
            answer += range.second - range.first;
        }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n^2\log n)$，空间 $O(n^2)$。

### 易错点

相同数值在不同下标属于不同选择，所以保留重复和。答案最多n⁴，使用64位。

## 星球大战

### 题意

横线或竖线轰炸，统计每次新摧毁的基地数。

### 思路

分别按x、y把基地编号分组。攻击某条线时遍历该组，未摧毁者计数并标记；处理后清空该组。同一基地最多在x组和y组各访问一次，总遍历量O(n)，重复轰炸空组不再扫描。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    map<long long, vector<int>> byX, byY;
    for (int i = 0; i < n; i++) {
        long long x, y;
        cin >> x >> y;
        byX[x].push_back(i);
        byY[y].push_back(i);
    }
    vector<bool> destroyed(n);
    while (m--) {
        int c;
        long long d;
        cin >> c >> d;
        auto &groups = c == 0 ? byX : byY;
        auto it = groups.find(d);
        int answer = 0;
        if (it != groups.end()) {
            for (int id : it->second)
                if (!destroyed[id]) {
                    destroyed[id] = true;
                    answer++;
                }
            groups.erase(it);
        }
        cout << answer << '\n';
    }
    return 0;
}
```

### 复杂度

时间 $O((n+m)\log n)$，空间 $O(n)$。

### 易错点

已经被另一方向攻击摧毁的基地不会再计数。删除整组后总扫描量才有线性界。

## 任务

### 题意

机器时间等级都不低于任务要求，最大任务数并最大报酬。

### 思路

任务按所需时间从大到小、同时间按等级从大到小处理；机器按可用时间降序。处理任务时，把时间足够的未用机器加入等级频数表，选择等级≥要求的最小等级机器。这样给当前任务留够能力，又保留高等级机器。时间每增1带来的500收益大于等级全部范围差的20收益，因此降序任务也对应优先较高报酬。

交换论证：可行分配若使用更强等级机器完成当前任务，可与贪心的较弱机器交换；若当前任务原本没被选，换掉其占用机器上的后续任务，任务数不减、报酬不降。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<pair<int, int>> machine(n), task(m);
    for (auto &[x, y] : machine)
        cin >> x >> y;
    for (auto &[x, y] : task)
        cin >> x >> y;
    sort(machine.rbegin(), machine.rend());
    sort(task.rbegin(), task.rend());
    array<int, 11> count = {};
    int p = 0, completed = 0;
    long long reward = 0;
    for (auto [time, level] : task) {
        while (p < n && machine[p].first >= time)
            count[machine[p++].second]++;
        for (int y = level; y <= 10; y++)
            if (count[y]) {
                count[y]--;
                completed++;
                reward += 500LL * time + 2 * level;
                break;
            }
    }
    cout << completed << ' ' << reward;
    return 0;
}
```

### 复杂度

时间 $O(n\log n+m\log m+11m)$，空间 $O(n+m)$。

### 易错点

每台机器至多一项任务；同所需时间时先安排等级高、收益也高的任务。

## 大魔法师牛可乐

### 题意

付费学若干双向跳长，要求能到达全部整数位置。

### 思路

可正反向使用跳长，能到达的位置恰是所选跳长gcd的倍数，所以目标是选出gcd=1的最小费用。dp[g]记录已处理卡片选择子集gcd为g的最少费用，空集用g=0。对每张卡，用旧表副本保留不选，再用gcd(g,l)更新选卡状态。相同gcd仅保留费用最小者。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> length(n), cost(n);
    for (int &x : length)
        cin >> x;
    for (int &x : cost)
        cin >> x;
    map<int, long long> dp = {{0, 0}};
    for (int i = 0; i < n; i++) {
        auto next = dp;
        for (auto [g, value] : dp) {
            int target = gcd(g, length[i]);
            long long candidate = value + cost[i];
            auto it = next.find(target);
            if (it == next.end() || candidate < it->second)
                next[target] = candidate;
        }
        dp.swap(next);
    }
    cout << (dp.count(1) ? dp[1] : -1);
    return 0;
}
```

### 复杂度

设最多S个不同gcd状态，时间 $O(nS(\log U+\log S))$，空间 $O(S)$。

### 易错点

允许反向跳，所以使用整数线性组合，不是非负背包。不能仅检查是否存在两张互素卡，可能需要更多张。

## 牛可乐和魔法封印

### 题意

有序数组，多次统计数值位于[x,y]的元素数。

### 思路

lower_bound(x)定位第一个≥x的位置，upper_bound(y)定位第一个>y的位置，两者相减恰好是闭区间内元素数。数组已保证非递减，重复元素全部保留。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto &x : a)
        cin >> x;
    int q;
    cin >> q;
    while (q--) {
        long long x, y;
        cin >> x >> y;
        cout << upper_bound(a.begin(), a.end(), y) - lower_bound(a.begin(), a.end(), x) << '\n';
    }
    return 0;
}
```

### 复杂度

时间 $O(n+q\log n)$，空间 $O(n)$。

### 易错点

右端用upper_bound，不要只查到第一个等于y的元素。

## 牛可乐与NCPC

### 题意

每次加入一位候选人，统计两个评分均越小越好的非支配者人数；完全同分者互不支配。

### 思路

非支配前沿按第一评分 x 递增后，第二评分 y 必须严格递减。用 map 将 x 映射到 (y,人数)。插入 (x,y) 时，先看同 x 的旧点：旧 y 更小则新点被支配；相等则增加人数；更大则旧点应删除。再看 x 更小的最近前驱，若其 y≤新 y，新点被支配。否则新点有效，并依次删除右侧所有 y≥新 y 的点。前沿的严格单调性保证被删除点连续，每个点最多删一次。答案维护人数而非不同评分对个数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    for (int tc = 1; tc <= tests; tc++) {
        int n;
        cin >> n;
        map<int, pair<int, int>> frontier;
        int total = 0;
        cout << "Case #" << tc << ":\n";
        for (int i = 0; i < n; i++) {
            int x, y;
            cin >> x >> y;
            auto it = frontier.lower_bound(x);
            bool dominated = false;
            if (it != frontier.begin() && prev(it)->second.first <= y)
                dominated = true;
            if (it != frontier.end() && it->first == x) {
                if (it->second.first < y)
                    dominated = true;
                else if (it->second.first == y) {
                    it->second.second++;
                    total++;
                    cout << total << '\n';
                    continue;
                }
            }
            if (!dominated) {
                while (it != frontier.end() && it->second.first >= y) {
                    total -= it->second.second;
                    it = frontier.erase(it);
                }
                frontier[x] = {y, 1};
                total++;
            }
            cout << total << '\n';
        }
        cout << '\n';
    }
    return 0;
}
```

### 复杂度

每组摊还时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

相同的两个评分必须保留两个人；支配定义要求至少一个评分严格更好。每组结束后额外输出一个空行。

## 牛牛国的战争

### 题意

每个我方部队只能攻击一次，必须消灭全部敌军，最大化战后我方存活总数。

### 思路

按敌军防御从大到小处理，将攻击力足够消灭当前敌人的全部未用我军放入按防御排序的 multiset。这些部队也都能打后面防御更低的敌人。若集合为空则无法完成。优先选防御严格大于敌军攻击的最小值，以存活且留下更强防御；若没有这样的部队，当前必有一支牺牲，选最小防御者。

交换论证：固定任一最优分配。当前贪心选的部队若原本分配给后面的敌人，可与最优方案当前用兵交换，攻击条件仍满足。选到最弱的可存活者时，被换到后面的部队防御不小于它，或当前方案原本要牺牲从而已多救一人；选到最弱且必死者时，其他可用部队也全会死，换到后面不会变差。故逐步固定贪心选择可保持最优。初始 n 支均存活，每次被敌军消灭才减一。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    for (int tc = 1; tc <= tests; tc++) {
        int n, m;
        cin >> n >> m;
        vector<pair<int, int>> ours(n), enemies(m);
        for (auto &[attack, defense] : ours)
            cin >> attack >> defense;
        for (auto &[defense, attack] : enemies)
            cin >> attack >> defense;
        sort(ours.rbegin(), ours.rend());
        sort(enemies.rbegin(), enemies.rend());
        multiset<int> defense;
        int j = 0, survivors = n;
        bool possible = true;
        for (auto [need, enemyAttack] : enemies) {
            while (j < n && ours[j].first >= need) {
                defense.insert(ours[j].second);
                j++;
            }
            if (defense.empty()) {
                possible = false;
                break;
            }
            auto it = defense.upper_bound(enemyAttack);
            if (it == defense.end()) {
                it = defense.begin();
                survivors--;
            }
            defense.erase(it);
        }
        cout << "Case #" << tc << ": " << (possible ? survivors : -1) << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O((n+m)\log(n+m))$，空间 $O(n+m)$。

### 易错点

攻击力等于防御力也会消灭对手，我军存活要求防御严格大于敌攻击。没出战的我军也计入存活数。

## 叠积木

### 题意

整列积木放到另一列顶，查询某块下方积木数。

### 思路

并查集根表示整列最底部，size[root]记录列高，distance[x]记录x到父节点下方偏移。把x列根rx接到y列根ry时，distance[rx]=size[ry]，再增大ry列高。路径压缩时把原父节点到底部的距离加上，最终distance[x]就是下方块数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const int limit = 30000;
    vector<int> parent(limit + 1), size(limit + 1, 1), distance(limit + 1);
    iota(parent.begin(), parent.end(), 0);
    auto find = [&](int x) {
        vector<int> path;
        int root = x;
        while (parent[root] != root) {
            path.push_back(root);
            root = parent[root];
        }
        int accumulated = 0;
        for (int i = (int)path.size() - 1; i >= 0; i--) {
            int u = path[i];
            accumulated += distance[u];
            parent[u] = root;
            distance[u] = accumulated;
        }
        return root;
    };
    int q;
    cin >> q;
    while (q--) {
        char op;
        int x;
        cin >> op >> x;
        if (op == 'M') {
            int y;
            cin >> y;
            int rx = find(x), ry = find(y);
            parent[rx] = ry;
            distance[rx] = size[ry];
            size[ry] += size[rx];
        } else {
            find(x);
            cout << distance[x] << '\n';
        }
    }
    return 0;
}
```

### 复杂度

路径压缩总计近线性，单次保守上界 $O(n)$；空间 $O(n)$，无递归压缩。

### 易错点

移动的是整列，不只是x上方部分。题目不输入n，按最大编号30000初始化。

## 牛可乐和最长公共子序列

### 题意

多组两个字符串，求LCS长度。

### 思路

f[i][j]表示前i、j字符的LCS长度。末字符相等时可由f[i−1][j−1]+1转移，否则从跳过其中一个末字符的两个状态取最大。仅依赖上一行和本行左方，滚动一维，另存被覆盖前的左上角值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s, t;
    while (cin >> s >> t) {
        vector<int> dp(t.size() + 1);
        for (char c : s) {
            int diagonal = 0;
            for (int j = 1; j <= (int)t.size(); j++) {
                int old = dp[j];
                if (c == t[j - 1])
                    dp[j] = diagonal + 1;
                else
                    dp[j] = max(dp[j], dp[j - 1]);
                diagonal = old;
            }
        }
        cout << dp.back() << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O(|s||t|)$，空间 $O(|t|)$。

### 易错点

子序列不要求连续；输入直到EOF，每组重新初始化。

## 牛可乐和公平点

### 题意

查询到x与y等距的树节点数。

### 思路

x=y时全树等距；路径长度为奇数时没有整数节点中点，答案0。长度为偶数时，等距点恰是去掉中点通向x、y的两条边后，包含中点的连通块。

若x、y同深度，中点为LCA，设其两侧儿子为a、b，答案n−size[a]−size[b]。否则令x较深，中点z在x一侧，令a为z通向x的儿子，答案size[z]−size[a]。用倍增跳指定步数得到这些点。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct EulerTree {
    int n;
    vector<vector<int>> edge;
    vector<int> parent, depth, in, out, order;
    EulerTree(int n) : n(n), edge(n + 1), parent(n + 1), depth(n + 1), in(n + 1), out(n + 1) {}
    void add(int u, int v) {
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    void root(int start) {
        vector<int> stack = {start};
        parent[start] = 0;
        order.clear();
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            in[u] = order.size() + 1;
            order.push_back(u);
            for (int v : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack.push_back(v);
                }
        }
        vector<int> size(n + 1, 1);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            out[u] = in[u] + size[u] - 1;
            if (parent[u])
                size[parent[u]] += size[u];
        }
    }
};

struct Ancestors {
    const EulerTree &tree;
    vector<vector<int>> up;
    Ancestors(const EulerTree &tree) : tree(tree) {
        int levels = 1;
        while ((1LL << levels) <= tree.n)
            levels++;
        up.assign(levels, vector<int>(tree.n + 1));
        up[0] = tree.parent;
        for (int b = 1; b < levels; b++)
            for (int u = 1; u <= tree.n; u++)
                up[b][u] = up[b - 1][up[b - 1][u]];
    }
    int lca(int u, int v) const {
        if (tree.depth[u] < tree.depth[v])
            swap(u, v);
        int gap = tree.depth[u] - tree.depth[v];
        for (int b = 0; b < (int)up.size(); b++)
            if (gap >> b & 1)
                u = up[b][u];
        if (u == v)
            return u;
        for (int b = (int)up.size() - 1; b >= 0; b--)
            if (up[b][u] != up[b][v]) {
                u = up[b][u];
                v = up[b][v];
            }
        return up[0][u];
    }
    int distance(int u, int v) const {
        return tree.depth[u] + tree.depth[v] - 2 * tree.depth[lca(u, v)];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    EulerTree tree(n);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        tree.add(u, v);
    }
    tree.root(1);
    Ancestors ancestor(tree);
    vector<int> size(n + 1, 1);
    for (int i = n - 1; i > 0; i--) {
        int u = tree.order[i];
        size[tree.parent[u]] += size[u];
    }
    auto jump = [&](int u, int steps) {
        for (int b = 0; steps; b++, steps >>= 1)
            if (steps & 1)
                u = ancestor.up[b][u];
        return u;
    };
    int q;
    cin >> q;
    while (q--) {
        int x, y;
        cin >> x >> y;
        if (x == y) {
            cout << n << '\n';
            continue;
        }
        int distance = ancestor.distance(x, y);
        if (distance % 2) {
            cout << 0 << '\n';
            continue;
        }
        int half = distance / 2;
        if (tree.depth[x] == tree.depth[y])
            cout << n - size[jump(x, half - 1)] - size[jump(y, half - 1)] << '\n';
        else {
            if (tree.depth[x] < tree.depth[y])
                swap(x, y);
            int z = jump(x, half), a = jump(x, half - 1);
            cout << size[z] - size[a] << '\n';
        }
    }
    return 0;
}
```

### 复杂度

预处理 $O(n\log n)$，每问 $O(\log n)$，空间 $O(n\log n)$。

### 易错点

等距点不是只算路径中点，还包含中点旁支。半长至少1，x=y已单独处理。

## 拆路

### 题意

动态删边并查询所在连通块最大繁荣度。

### 思路

读完全部操作，先用从未被删除的边建最终图。逆序处理，原删除变成加边，原查询则直接查当前并查集根的最大繁荣度。合并时同步取块最大值。逆序得到的查询答案最后反转输出。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, size;
    DSU(int n) : parent(n + 1), size(n + 1, 1) { iota(parent.begin(), parent.end(), 0); }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> value(n);
    for (int &x : value)
        cin >> x;
    vector<pair<int, int>> edge(m);
    map<pair<int, int>, int> index;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        u--;
        v--;
        if (u > v)
            swap(u, v);
        edge[i] = {u, v};
        index[edge[i]] = i;
    }
    int q;
    cin >> q;
    struct Operation {
        char type;
        int x, y;
    };
    vector<Operation> operation(q);
    vector<bool> removed(m);
    for (auto &op : operation) {
        cin >> op.type >> op.x;
        op.x--;
        op.y = -1;
        if (op.type == 'D') {
            cin >> op.y;
            op.y--;
            if (op.x > op.y)
                swap(op.x, op.y);
            removed[index[{op.x, op.y}]] = true;
        }
    }
    DSU dsu(n);
    auto unite = [&](int u, int v) {
        int a = dsu.find(u), b = dsu.find(v), maximum = max(value[a], value[b]);
        dsu.unite(a, b);
        value[dsu.find(a)] = maximum;
    };
    for (int i = 0; i < m; i++)
        if (!removed[i])
            unite(edge[i].first, edge[i].second);
    vector<int> answer;
    for (int i = q - 1; i >= 0; i--) {
        auto op = operation[i];
        if (op.type == 'D')
            unite(op.x, op.y);
        else
            answer.push_back(value[dsu.find(op.x)]);
    }
    reverse(answer.begin(), answer.end());
    for (int x : answer)
        cout << x << '\n';
    return 0;
}
```

### 复杂度

时间 $O((n+m+q)\log n)$，空间 $O(n+m+q)$。

### 易错点

无向边统一较小端在前，避免删除时找不到反向输入的边。查询答案要恢复原时间顺序。

## N皇后问题

### 题意

n≤12的N皇后方案数。

### 思路

逐行放皇后，用三个位掩码记录已占列、两类对角线在当前行的攻击位置。当前可放列available=full & ~(columns|left|right)，依次取最低位放置。进入下一行时左右对角线分别左移、右移；放满n行计一种。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    unsigned full = (1U << n) - 1;
    long long answer = 0;
    auto dfs = [&](auto &&self, unsigned columns, unsigned left, unsigned right) -> void {
        if (columns == full) {
            answer++;
            return;
        }
        unsigned available = full & ~(columns | left | right);
        while (available) {
            unsigned bit = available & -available;
            available -= bit;
            self(self, columns | bit, (left | bit) << 1, (right | bit) >> 1);
        }
    };
    dfs(dfs, 0, 0, 0);
    cout << answer;
    return 0;
}
```

### 复杂度

保守时间 $O(n!)$，递归空间 $O(n)$。

### 易错点

每行恰放一个，列掩码满了就完成。越界对角线位由full在下次候选计算时屏蔽。

## 马踏棋盘

### 题意

马只允许四种x增大的日字移动，求角到角路径数。

### 思路

四种允许移动都使横坐标x严格增加，因此按列从1到m计算是拓扑顺序。dp[x][y]为到此的路径数，将它加到四种不越界的下一位置。dp[1][1]=1，最后取dp[m][n]，即第m列第n行。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int rows, columns;
    cin >> rows >> columns;
    long long dp[16][16] = {};
    dp[1][1] = 1;
    const int dx[] = {1, 1, 2, 2}, dy[] = {2, -2, 1, -1};
    for (int x = 1; x <= columns; x++)
        for (int y = 1; y <= rows; y++)
            for (int d = 0; d < 4; d++) {
                int xx = x + dx[d], yy = y + dy[d];
                if (xx <= columns && yy >= 1 && yy <= rows)
                    dp[xx][yy] += dp[x][y];
            }
    cout << dp[columns][rows];
    return 0;
}
```

### 复杂度

时间、空间均 $O(nm)$。

### 易错点

原题坐标终点文字与“n行m列、不能向左”及样例不一致。按行列含义，横坐标x取1..m，纵坐标y取1..n，目标为(m,n)；样例4行5列仅有一条向右路线。只用列出的四种移动。1×1有一条空路径。

## 洋流

### 题意

顺当前格的洋流方向移动耗能0，其他七方向耗能1，多次求最少能量。

### 思路

八邻接边权只有0或1，使用01BFS：松弛0边放队首，1边放队尾，队列按待确定距离保持非递减。每个点首次出队时确定最短距离，之后重复记录跳过，目标确定后即可停止。为配合原题满数据时限，用数组实现循环双端队列，避免通用堆的对数因子和频繁节点分配。每条边至多成功入队一次的上界为8V，加初始结点后队列容量8V+2足够。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    while (cin >> n >> m) {
        vector<string> grid(n);
        for (auto &row : grid)
            cin >> row;
        int queries;
        cin >> queries;
        int size = n * m, capacity = 8 * size + 2;
        vector<int> queue(capacity), distance(size);
        vector<unsigned char> done(size);
        int dr[] = {-1, -1, 0, 1, 1, 1, 0, -1}, dc[] = {0, 1, 1, 1, 0, -1, -1, -1};
        while (queries--) {
            int a, b, c, d;
            cin >> a >> b >> c >> d;
            int start = (a - 1) * m + b - 1, target = (c - 1) * m + d - 1;
            fill(distance.begin(), distance.end(), 1000000000);
            fill(done.begin(), done.end(), 0);
            int head = 0, tail = 1;
            queue[0] = start;
            distance[start] = 0;
            while (head != tail) {
                int u = queue[head];
                if (++head == capacity)
                    head = 0;
                if (done[u])
                    continue;
                done[u] = 1;
                if (u == target)
                    break;
                int r = u / m, col = u % m, direction = grid[r][col] - '0';
                for (int k = 0; k < 8; k++) {
                    int rr = r + dr[k], cc = col + dc[k];
                    if (rr < 0 || rr >= n || cc < 0 || cc >= m)
                        continue;
                    int v = rr * m + cc, w = k != direction;
                    if (!done[v] && distance[v] > distance[u] + w) {
                        distance[v] = distance[u] + w;
                        if (w == 0) {
                            if (--head < 0)
                                head = capacity - 1;
                            queue[head] = v;
                        } else {
                            queue[tail] = v;
                            if (++tail == capacity)
                                tail = 0;
                        }
                    }
                }
            }
            cout << distance[target] << '\n';
        }
    }
    return 0;
}
```

### 复杂度

每次询问时间、空间均为 $O(nm)$，方向数8为常数。

### 易错点

边权由出发格的方向决定。输入坐标从1开始；0号方向是北，之后顺时针。起终点相同耗能0。

## 孙悟空救师傅

### 题意

按顺序拿钥匙，蛇首次经过多耗一分钟，最短救师时间。

### 思路

状态(position,keys,mask)中keys是已集齐的连续钥匙种数，mask是已击败蛇的集合（最多5只）。走到数字keys+1时keys加1；提前路过更大数字不会取得钥匙。经过尚未击败的蛇，费用2并设置其位，之后再经过费用1。所有边权1或2，用Dijkstra。取到全部钥匙并到达T的状态首次出堆时即最优。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<string> grid(n);
    for (auto &s : grid)
        cin >> s;
    int cells = n * n, start = 0, target = 0, snakes = 0;
    vector<int> snake(cells, -1);
    for (int u = 0; u < cells; u++) {
        char c = grid[u / n][u % n];
        if (c == 'K')
            start = u;
        if (c == 'T')
            target = u;
        if (c == 'S')
            snake[u] = snakes++;
    }
    int masks = 1 << snakes;
    auto encode = [&](int u, int keys, int mask) { return (keys * masks + mask) * cells + u; };
    const int inf = 1000000000;
    vector<int> distance((m + 1) * masks * cells, inf);
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> heap;
    int initial = encode(start, 0, 0);
    distance[initial] = 0;
    heap.push({0, initial});
    const int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};
    while (!heap.empty()) {
        auto [d, state] = heap.top();
        heap.pop();
        if (d != distance[state])
            continue;
        int u = state % cells, temporary = state / cells, mask = temporary % masks,
            keys = temporary / masks;
        if (u == target && keys == m) {
            cout << d;
            return 0;
        }
        for (int direction = 0; direction < 4; direction++) {
            int r = u / n + dr[direction], c = u % n + dc[direction];
            if (r < 0 || r >= n || c < 0 || c >= n || grid[r][c] == '#')
                continue;
            int v = r * n + c, nextKeys = keys, nextMask = mask, cost = 1;
            if (grid[r][c] >= '1' && grid[r][c] <= '9' && grid[r][c] - '0' == keys + 1)
                nextKeys++;
            if (snake[v] >= 0 && !(mask >> snake[v] & 1)) {
                nextMask |= 1 << snake[v];
                cost++;
            }
            int next = encode(v, nextKeys, nextMask);
            if (d + cost < distance[next]) {
                distance[next] = d + cost;
                heap.push({d + cost, next});
            }
        }
    }
    cout << "impossible";
    return 0;
}
```

### 复杂度

状态数V=n²(m+1)2^S，时间 $O(V\log V)$，空间 $O(V)$。

### 易错点

同一坐标但钥匙进度或蛇状态不同，不能合并。T也可以提前经过，只在keys=m时完成。

## 走楼梯

### 题意

n阶楼梯，每次1或2阶，求方案数。

### 思路

按最后一步拆分，f[n]=f[n−1]+f[n−2]，f[0]=1、f[1]=1。从2滚动计算，n≤50需64位。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    long long previous = 1, current = 1;
    for (int i = 2; i <= n; i++) {
        long long next = previous + current;
        previous = current;
        current = next;
    }
    cout << current;
    return 0;
}
```

### 复杂度

时间 $O(n)$，空间 $O(1)$。

### 易错点

空台阶有一种“已经完成”的方式，设f[0]=1才能正确得到f[2]=2。

## 最大子串和

### 题意

求最大非空连续子数组和。

### 思路

维护end为恰以当前元素x结尾的最大子段和，更新end=max(x,end+x)，再更新全局最大值。初始用第一个元素，保证全负数组仍选出最大的单个负数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    long long ending = 0, answer = LLONG_MIN;
    for (int i = 0; i < n; i++) {
        long long x;
        cin >> x;
        ending = i ? max(x, ending + x) : x;
        answer = max(answer, ending);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n)$，空间 $O(1)$。

### 易错点

至少选一个，不能用0作为最终答案下界。百万个十亿值相加需64位。

## 多重背包

### 题意

每种有限个物品，容量至100，最大价值。

### 思路

按物品种类逐层转移。用旧dp副本保留不选，对每个旧容量和数量1..x枚举，不能超过总容量。只从旧数组转移，保证同一类最多取x件。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, capacity;
    cin >> n >> capacity;
    vector<int> dp(capacity + 1);
    while (n--) {
        int count, weight, value;
        cin >> count >> weight >> value;
        auto next = dp;
        for (int used = 0; used <= capacity; used++)
            for (int k = 1; k <= count && used + k * weight <= capacity; k++)
                next[used + k * weight] = max(next[used + k * weight], dp[used] + k * value);
        dp.swap(next);
    }
    cout << *max_element(dp.begin(), dp.end());
    return 0;
}
```

### 复杂度

时间 $O(nT\max x)$，空间 $O(T)$。

### 易错点

输入顺序是数量、重量、价值。容量不要求恰好用满。

## 草药大师

### 题意

n≤100但容量与价值至10^9的精确0/1背包。

### 思路

这些约束不能直接开O(S)容量DP，价值和DP也可能过大。采用精确分支限界：按价值/时间降序排，搜索取或不取。对每个搜索节点，暂时允许剩余草药按比例分割，贪心装满得到分数背包上界；若上界不超过已有整数最优值，整棵分支可剪。所有剩余草药都能装下时直接全部选取。

比例比较用128位交叉乘，分数上界只在最后不能完整装入的一件上向下取整；最优值为整数，向下取整仍是合法上界。先搜索取当前物品，尽早得到较好下界。

通用0/1背包的精确求解最坏仍为指数级；按当前题面的大容量界，不能声称这个搜索有多项式最坏时间。这里给出不丢正确性的精确算法，并明确此性能限制。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long capacity;
    cin >> n >> capacity;
    struct Item {
        long long weight, value;
    };
    vector<Item> a;
    for (int i = 0; i < n; i++) {
        long long w, v;
        cin >> w >> v;
        if (w <= capacity)
            a.push_back({w, v});
    }
    sort(a.begin(), a.end(), [](auto x, auto y) {
        return (__int128)x.value * y.weight > (__int128)y.value * x.weight;
    });
    n = a.size();
    vector<long long> suffixWeight(n + 1), suffixValue(n + 1);
    for (int i = n - 1; i >= 0; i--) {
        suffixWeight[i] = suffixWeight[i + 1] + a[i].weight;
        suffixValue[i] = suffixValue[i + 1] + a[i].value;
    }
    long long answer = 0;
    auto dfs = [&](auto &&self, int i, long long remaining, long long value) -> void {
        answer = max(answer, value);
        if (i == n)
            return;
        if (suffixWeight[i] <= remaining) {
            answer = max(answer, value + suffixValue[i]);
            return;
        }
        long long bound = value, space = remaining;
        for (int j = i; j < n; j++) {
            if (a[j].weight <= space) {
                space -= a[j].weight;
                bound += a[j].value;
            } else {
                bound += (long long)((__int128)space * a[j].value / a[j].weight);
                break;
            }
        }
        if (bound <= answer)
            return;
        if (a[i].weight <= remaining)
            self(self, i + 1, remaining - a[i].weight, value + a[i].value);
        self(self, i + 1, remaining, value);
    };
    dfs(dfs, 0, capacity, 0);
    cout << answer;
    return 0;
}
```

### 复杂度

最坏 $O(n2^n)$ 时间，空间 $O(n)$；实际剪枝量依数据而定。

### 易错点

不要按单位价值直接贪心输出，那只对可分割物品成立。本代码仅把分数贪心用于安全上界，搜索仍精确。

## 最大m个子段和

### 题意

选择恰好m个互不重叠非空连续段，最大总和。

### 思路

end[k]为当前前缀中选k段且最后一段以当前元素结尾的最大值，best[k]为当前前缀任意位置结束的最优值。加入x时，end[k]=max(旧end[k]+x,旧best[k−1]+x)，分别代表延长最后一段、从当前元素新开一段；best[k]取原值与新end[k]较大者。k倒序，保证best[k−1]还未使用当前元素。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    const long long negative = LLONG_MIN / 4;
    vector<long long> ending(m + 1, negative), best(m + 1, negative);
    best[0] = 0;
    for (int i = 1; i <= n; i++) {
        long long x;
        cin >> x;
        for (int k = min(i, m); k >= 1; k--) {
            ending[k] = max(ending[k], best[k - 1]) + x;
            best[k] = max(best[k], ending[k]);
        }
    }
    cout << best[m];
    return 0;
}
```

### 复杂度

时间 $O(nm)$，空间 $O(m)$。

### 易错点

恰好m段，不能把所有状态初始化0；全负数组仍必须选够。原任务需要m≤n才有合法方案。

## 滑雪

### 题意

严格下降的四邻路径最大长度。

### 思路

把格子按高度升序处理，dp[u]=1+max(dp[v])，v为更低的四邻格；没有更低格时为1。低格已先处理，依赖顺序正确，最后对全部起点取最大。这样避免递归路径很长时的栈问题。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> height(n * m), order(n * m), dp(n * m, 1);
    for (int &x : height)
        cin >> x;
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) { return height[a] < height[b]; });
    int answer = 1;
    const int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};
    for (int u : order) {
        int r = u / m, c = u % m;
        for (int d = 0; d < 4; d++) {
            int rr = r + dr[d], cc = c + dc[d];
            if (rr >= 0 && rr < n && cc >= 0 && cc < m && height[rr * m + cc] < height[u])
                dp[u] = max(dp[u], dp[rr * m + cc] + 1);
        }
        answer = max(answer, dp[u]);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

格子数V=nm，时间 $O(V\log V)$，空间 $O(V)$。

### 易错点

相等高度不能滑动。路径长度按经过格子数，单格为1。

## Rake It In

### 题意

4×4棋盘交替选择2×2加总分再旋转，最多6步，求最优总分。

### 思路

只有9个可选2×2区域，深度2k≤6，直接极小极大搜索。Alice层取最大、Bob层取最小；每步先记四格和，再逆时针旋转，递归返回剩余最优分后加本步和。退出分支时恢复四格。

用Alpha-Beta界剪掉不可能影响祖先决策的分支。因递归值是“此后额外得分”，传入子节点的上下界都减去当前gain。Alice优先尝试高gain、Bob优先低gain，只改变搜索顺序，不改变结果。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int k;
        cin >> k;
        array<int, 16> board;
        for (int &x : board)
            cin >> x;
        auto search = [&](auto &&self, int remaining, bool maximize, int alpha, int beta) -> int {
            if (!remaining)
                return 0;
            vector<pair<int, int>> moves;
            for (int r = 0; r < 3; r++)
                for (int c = 0; c < 3; c++) {
                    int p = r * 4 + c;
                    int gain = board[p] + board[p + 1] + board[p + 4] + board[p + 5];
                    moves.push_back({gain, p});
                }
            sort(moves.begin(), moves.end());
            if (maximize)
                reverse(moves.begin(), moves.end());
            int best = maximize ? INT_MIN : INT_MAX;
            for (auto [gain, p] : moves) {
                array<int, 4> old = {board[p], board[p + 1], board[p + 5], board[p + 4]};
                board[p] = old[1];
                board[p + 1] = old[2];
                board[p + 5] = old[3];
                board[p + 4] = old[0];
                int value = gain + self(self, remaining - 1, !maximize, alpha - gain, beta - gain);
                board[p] = old[0];
                board[p + 1] = old[1];
                board[p + 5] = old[2];
                board[p + 4] = old[3];
                if (maximize) {
                    best = max(best, value);
                    alpha = max(alpha, best);
                } else {
                    best = min(best, value);
                    beta = min(beta, best);
                }
                if (alpha >= beta)
                    break;
            }
            return best;
        };
        cout << search(search, 2 * k, true, -1000000000, 1000000000) << '\n';
    }
    return 0;
}
```

### 复杂度

最坏 $O(9^{2k})$，排序9种动作视常数；递归空间 $O(k)$。

### 易错点

双方每步都向同一个总分加分，Bob也不是减去本步得分。旋转是逆时针，恢复棋盘必须与旋转前完全一致。

## Digital Deletions

### 题意

数字可减小，遇0可删该位及右侧，判断先手。

### 思路

最长6位，总共10+100+...+10^6种非空字符串，可全部预处理。按长度升序、同长按数值升序，每次操作都到更短或同长更小的状态，形成拓扑顺序。状态为固定长度下的数值，因此前导0不能丢失；用offset[len]+value编码。

若某位d>0，枚举降到0..d−1；若d=0，删除它和右侧，只留下左前缀。只要存在必败后继则当前必胜。空串为必败，因为上一手删空者已获胜。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    vector<string> query(tests);
    int maximum = 1;
    for (auto &s : query) {
        cin >> s;
        maximum = max(maximum, (int)s.size());
    }
    int power[7], offset[7];
    power[0] = 1;
    offset[0] = 0;
    for (int i = 1; i <= 6; i++) {
        power[i] = power[i - 1] * 10;
        offset[i] = offset[i - 1] + (i == 1 ? 1 : power[i - 1]);
    }
    vector<uint8_t> win(offset[maximum] + power[maximum]);
    for (int len = 1; len <= maximum; len++)
        for (int value = 0; value < power[len]; value++) {
            int id = offset[len] + value;
            for (int position = 0; position < len && !win[id]; position++) {
                int digit = value / power[position] % 10;
                if (!digit) {
                    int prefixLength = len - position - 1, prefix = value / power[position + 1];
                    if (!win[offset[prefixLength] + prefix])
                        win[id] = 1;
                } else
                    for (int smaller = 0; smaller < digit; smaller++)
                        if (!win[id - (digit - smaller) * power[position]]) {
                            win[id] = 1;
                            break;
                        }
            }
        }
    for (auto &s : query) {
        int value = stoi(s);
        cout << (win[offset[s.size()] + value] ? "Yes\n" : "No\n");
    }
    return 0;
}
```

### 复杂度

最多S=1111110种非空状态，时间 $O(S\cdot6\cdot10+T)$，空间 $O(S+6T)$。

### 易错点

字符串00与0是不同局面，必须保存长度。删除0包括该0本身，不只是右侧。

## Palindrome Game (hard version)

### 题意

翻0付1，非回文且前步非反转时可免费反转，费用少者胜。

### 思路

统计总0数z和不相等的对称对数d。若d=0，免费反转暂不能用：z=1时先手必须承担最后一次修改而输；z为偶数时后手用镜像回应也赢；z为奇数且>1时先手先改中心，再利用后手打破对称后的免费反转取得优势。z=0时双方费用都是0，平局。

若d>0，先手可先免费反转，把必须付费的责任交给后手。除一种边界外先手胜：恰有一个不对称对、总共两个0、中心也是0时，双方可以各付1，结果平局。此时一个0来自不对称对，另一个来自中心；其他非回文状态先手均可保持免费操作优势。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        string s;
        cin >> n >> s;
        int zeros = count(s.begin(), s.end(), '0'), different = 0;
        for (int i = 0; i < n / 2; i++)
            different += s[i] != s[n - 1 - i];
        if (!zeros)
            cout << "DRAW\n";
        else if (!different)
            cout << ((zeros > 1 && zeros % 2) ? "ALICE\n" : "BOB\n");
        else if (different == 1 && zeros == 2 && n % 2 && s[n / 2] == '0')
            cout << "DRAW\n";
        else
            cout << "ALICE\n";
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n)$，空间 $O(n)$ 存串。

### 易错点

非回文时也不能连续两步反转，这正是费用策略成立的条件。全1串无需操作，应平局。

## Bash游戏

### 题意

每次取1到K，取完赢，多组判断A/B。

### 思路

N是K+1倍数时必败，否则取余数使对手面对倍数。之后对手取x，就补K+1−x，始终能把倍数交回给对手。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        long long n, k;
        cin >> n >> k;
        cout << (n % (k + 1) ? "A\n" : "B\n");
    }
    return 0;
}
```

### 复杂度

每组时间、空间均 $O(1)$。

### 易错点

K可以大于N，此时先手直接取完。K+1与取模使用64位。

## Deleting Divisors

### 题意

整数减去非1非自身约数，无法操作者输。

### 思路

奇数n的合法约数也是奇数，减后为带奇因子>1的偶数；后者总能减去其奇因子，走回奇数。因此所有奇数均必败，所有含奇因子的偶数必胜。

剩下n=2^r。减去2^s，若s≤r−2，结果含奇因子>1，属于必胜态；只有减半能走到另一纯2幂2^(r−1)。n=2无合法约数必败，所以r奇数必败、r偶数必胜。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        unsigned n;
        cin >> n;
        bool alice = false;
        if (n % 2 == 0) {
            if ((n & (n - 1)) != 0)
                alice = true;
            else
                alice = __builtin_ctz(n) % 2 == 0;
        }
        cout << (alice ? "Alice\n" : "Bob\n");
    }
    return 0;
}
```

### 复杂度

每组时间、空间均 $O(1)$。

### 易错点

1和素数都无合法操作。纯2幂需要看指数奇偶，不能一概判偶数胜。

## Northcott Game

### 题意

每行黑白棋子可移动不可越过，黑方先走。

### 思路

把每行两棋子之间的空格数g=abs(T−J)−1看作Nim堆。朝对方移动会减小g，恰是取石子。背离对方移动虽会增大g，但对方可沿同方向跟进同样格数，恢复原间隔；这种无效退让只能有限进行，无法破坏Nim必胜策略。因此全部间隔异或非0先手胜。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    while (cin >> n >> m) {
        int total = 0;
        for (int i = 0; i < n; i++) {
            int a, b;
            cin >> a >> b;
            total ^= abs(a - b) - 1;
        }
        cout << (total ? "I WIN!\n" : "BAD LUCK!\n");
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n)$，空间 $O(1)$。

### 易错点

看的是两子之间空格数，距离要减1。题目允许棋子左右顺序任意，取绝对值。

## Georgia and Bob

### 题意

棋子只能向左、不越子，判断胜负。

### 思路

排序后从右向左两两配对，每对之间的空格数视为一堆Nim；若棋子数奇数，最左棋子与左边界0配成一对。每对右棋子左移可任意减少这一堆。每对左棋子左移会增大配对间隔，对方可让对应右棋子同移，恢复间隔；标准配对策略给出这些间隔异或为0恰为必败态。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        cin >> n;
        vector<int> a(n);
        for (int &x : a)
            cin >> x;
        sort(a.begin(), a.end());
        if (n % 2)
            a.insert(a.begin(), 0);
        int total = 0;
        for (int i = 1; i < (int)a.size(); i += 2)
            total ^= a[i] - a[i - 1] - 1;
        cout << (total ? "Georgia will win\n" : "Bob will win\n");
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

配对从右端确定，奇数个时补0在最左，不能漏掉最左棋子到边界的间隔。

## 货船

### 题意

十万件货物，容量十万，求最大可装总重量。

### 思路

用位集possible表示可达到的重量集合，初始仅0。加入重量w时possible |= possible<<w，移位后的每一位对应在旧方案上选当前货物；整条位集一次更新，避免O(nA)逐状态。重量>A的货物无法选，直接忽略。最后从A向下找第一个置位。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, capacity;
    cin >> n >> capacity;
    bitset<100001> possible;
    possible[0] = 1;
    while (n--) {
        int w;
        cin >> w;
        if (w <= capacity)
            possible |= possible << w;
    }
    for (int x = capacity; x >= 0; x--)
        if (possible[x]) {
            cout << x;
            break;
        }
    return 0;
}
```

### 复杂度

时间 $O(nU/机器字长+U)$，空间 $O(U/机器字长)$，U=100000。

### 易错点

每件只有一份，右侧移位基于操作前位集，不能改成完全背包。bitset上界覆盖题目最大容量。

## 宝藏猎人

### 题意

向东跳，跳长每次至多改变1，收集最多宝石。

### 思路

dp[position][jump]表示最后一次跳长为jump时的最多宝石。下一跳尝试jump−1、jump、jump+1，正长度且不越界即可。关键是限制跳长范围：从初始d增加或减少250，必须经历至少250次逐级变化，仅这些跳长的最小总和就超过30000；减小的情况还要求d≥251。因此只需保存jump∈[d−250,d+250]与正整数的交集。

位置严格增加，按位置升序转移。总宝石至30000，16位有符号数足够存答案及−1不可达标记，约30MB。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, d;
    cin >> n >> d;
    const int limit = 30000, width = 501;
    vector<int> gem(limit + 1);
    for (int i = 0; i < n; i++) {
        int p;
        cin >> p;
        gem[p]++;
    }
    vector<int16_t> dp((limit + 1) * width, -1);
    dp[d * width + 250] = gem[d];
    int answer = 0;
    for (int p = d; p <= limit; p++)
        for (int index = 0; index < width; index++) {
            int current = dp[p * width + index];
            if (current < 0)
                continue;
            answer = max(answer, current);
            int jump = d + index - 250;
            for (int change = -1; change <= 1; change++) {
                int next = index + change, length = jump + change;
                if (next >= 0 && next < width && length > 0 && p + length <= limit) {
                    auto &value = dp[(p + length) * width + next];
                    value = max((int)value, current + gem[p + length]);
                }
            }
        }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(30000\sqrt{30000})$，空间同状态数，每状态16位。

### 易错点

同一个位置可能有多颗宝石，必须累计频数。第一次强制跳到d，不能从0随意选择第一跳。

## 任务安排

### 题意

依赖任务并行执行，求最短总工期内可以拖延的任务。

### 思路

拓扑排序计算最早开始early[v]=max(early[u]+time[u])，所有任务最早完成时间最大值即总工期T。若拓扑点数不足n，存在环而无法完成。

再逆拓扑计算最迟开始：所有任务初始latest[u]=T−time[u]，对每条u→v用latest[v]−time[u]缩小latest[u]。early[u]<latest[u]说明存在正松弛，可以拖延；相等则位于某条关键路径。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<long long> duration(n), early(n), latest(n);
    for (auto &x : duration)
        cin >> x;
    vector<vector<int>> edge(n);
    vector<int> indegree(n);
    while (m--) {
        int u, v;
        cin >> u >> v;
        u--;
        v--;
        edge[u].push_back(v);
        indegree[v]++;
    }
    queue<int> queue;
    for (int u = 0; u < n; u++)
        if (!indegree[u])
            queue.push(u);
    vector<int> order;
    long long total = 0;
    while (!queue.empty()) {
        int u = queue.front();
        queue.pop();
        order.push_back(u);
        total = max(total, early[u] + duration[u]);
        for (int v : edge[u]) {
            early[v] = max(early[v], early[u] + duration[u]);
            if (--indegree[v] == 0)
                queue.push(v);
        }
    }
    if ((int)order.size() != n) {
        cout << -1;
        return 0;
    }
    for (int u = 0; u < n; u++)
        latest[u] = total - duration[u];
    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];
        for (int v : edge[u])
            latest[u] = min(latest[u], latest[v] - duration[u]);
    }
    vector<int> answer;
    for (int u = 0; u < n; u++)
        if (early[u] < latest[u])
            answer.push_back(u + 1);
    cout << answer.size() << '\n';
    for (int i = 0; i < (int)answer.size(); i++)
        cout << answer[i] << (i + 1 == (int)answer.size() ? '\n' : ' ');
    if (answer.empty())
        cout << '\n';
    return 0;
}
```

### 复杂度

时间、空间均 $O(n+m)$。

### 易错点

多个终点都受同一个总工期约束，不能只从任意一个终点反推。

## 分层图最短路

### 题意

邻层任意点付C移动，另有特殊边，同层不能免费互达。

### 思路

为每层建立入口汇集点hub[l]，让hub[l]到本层每个原点有0边；原点u只向hub[layer[u]−1]与hub[layer[u]+1]连C边，不能连向本层hub。这样恰好实现一次付费到相邻层任意原点，不引入同层免费通道。再加入特殊双向边，Dijkstra求1到n。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<long long> dijkstra(const vector<vector<pair<int, long long>>> &graph, int source) {
    const long long inf = 1LL << 60;
    vector<long long> distance(graph.size(), inf);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>,
                   greater<pair<long long, int>>>
        heap;
    distance[source] = 0;
    heap.push({0, source});
    while (!heap.empty()) {
        auto [cost, u] = heap.top();
        heap.pop();
        if (cost != distance[u])
            continue;
        for (auto [v, w] : graph[u])
            if (distance[v] > cost + w) {
                distance[v] = cost + w;
                heap.push({distance[v], v});
            }
    }
    return distance;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    long long cost;
    cin >> n >> m >> cost;
    vector<int> layer(n);
    for (int &x : layer)
        cin >> x;
    vector<vector<pair<int, long long>>> graph(2 * n);
    for (int u = 0; u < n; u++) {
        int l = layer[u] - 1;
        graph[n + l].push_back({u, 0});
        if (l)
            graph[u].push_back({n + l - 1, cost});
        if (l + 1 < n)
            graph[u].push_back({n + l + 1, cost});
    }
    while (m--) {
        int u, v;
        long long w;
        cin >> u >> v >> w;
        graph[u - 1].push_back({v - 1, w});
        graph[v - 1].push_back({u - 1, w});
    }
    auto distance = dijkstra(graph, 0);
    cout << (distance[n - 1] >= (1LL << 59) ? -1 : distance[n - 1]);
    return 0;
}
```

### 复杂度

时间 $O((n+m)\log n)$，空间 $O(n+m)$。

### 易错点

原点到本层hub若也连0，会误把同层任意两点免费连接。空层hub没有出边，无法作为中转通道。

## 小A的柱状图

### 题意

每根柱宽不同，求下端对齐柱状图内最大矩形面积。

### 思路

仍用高度不下降的单调栈，遇到更矮的第 i 柱时弹出 j。此时以 h[j] 为高度，范围为弹栈后栈顶 left 之后，到 i-1 为止。这里宽度不能用柱数，而应使用宽度前缀和 width[i-1]-width[left]。末尾补零高柱清栈，取所有结算面积最大值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> width(n + 2), height(n + 2);
    for (int i = 1; i <= n; i++) {
        long long x;
        cin >> x;
        width[i] = width[i - 1] + x;
    }
    for (int i = 1; i <= n; i++)
        cin >> height[i];
    vector<int> stack;
    long long answer = 0;
    for (int i = 1; i <= n + 1; i++) {
        while (!stack.empty() && height[stack.back()] > height[i]) {
            int j = stack.back();
            stack.pop_back();
            int left = stack.empty() ? 0 : stack.back();
            answer = max(answer, height[j] * (width[i - 1] - width[left]));
        }
        stack.push_back(i);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间、空间均为 $O(n)$。

### 易错点

总宽可达一亿，高度可达十亿，面积可达 10^17，必须使用 long long。柱宽只影响区间长度，不改变按高度找边界的规则。

## 分糖果

### 题意

合并糖果余数，最小正解保证小于2^31。

### 思路

按扩展CRT合并x≡R(mod M)，每次解M*t≡r−R(mod p)。但这里只保证解小，未保证所有模数最小公倍数小。利用解界B=2^31：一旦合并周期M≥B，区间[1,B)里至多剩一个候选R，后续只检查它是否满足每条同余，无需继续扩大周期。

进入冻结前M<B且p≤10^9，一步新周期至约2×10^18，64位可存，乘法中间用128位。若最终R=0且M<B，最小正解应取M；若冻结后R=0，界内无正解。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

long long extendedGcd(long long a, long long b, long long &x, long long &y) {
    if (!b) {
        x = 1;
        y = 0;
        return a;
    }
    long long previousX, previousY;
    long long g = extendedGcd(b, a % b, previousX, previousY);
    x = previousY;
    y = previousX - (a / b) * previousY;
    return g;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    const long long bound = 1LL << 31;
    long long remainder = 0, period = 1;
    bool possible = true, frozen = false;
    while (n--) {
        long long p, r;
        cin >> p >> r;
        if (!possible)
            continue;
        if (frozen) {
            if (remainder % p != r)
                possible = false;
            continue;
        }
        long long u, v, g = extendedGcd(period, p, u, v), delta = r - remainder;
        if (delta % g) {
            possible = false;
            continue;
        }
        long long reduced = p / g,
                  step = (long long)(((__int128)(delta / g) * u % reduced + reduced) % reduced),
                  nextPeriod = period * reduced;
        remainder = (long long)(((__int128)remainder + (__int128)period * step) % nextPeriod);
        period = nextPeriod;
        if (period >= bound) {
            frozen = true;
            if (remainder == 0 || remainder >= bound)
                possible = false;
        }
    }
    long long answer = remainder ? remainder : period;
    if (answer >= bound)
        possible = false;
    cout << (possible ? answer : -1);
    return 0;
}
```

### 复杂度

时间 $O(n\log U)$，空间 $O(\log U)$。

### 易错点

原题要求糖果数是正数，零余数系统的最小正解是周期，不是0。小解不意味着模数乘积小。

## 青蛙

### 题面口径核对

此页文字写“两只及以上”，但与给定样例冲突：m=12、步长9和10时，两只都能到的只有0、6，编号和是6；页面却输出42，它是至少一只可到的并集之和。两组样例及来源Frogs均对应并集。下文参考代码采用与样例一致的至少一只口径。若确实要求至少两只，应按每个gcd类别累计覆盖青蛙数，再以覆盖数≥2判断，而不能只做存在性标记。

## 题意

多只青蛙从0按各自固定步长绕环，求所有可到石头编号之和。

### 思路

步长a的青蛙能到的恰是gcd(a,m)的倍数。所有这些g都整除m，先去重。对于任意石头x，令d=gcd(x,m)，它被覆盖当且仅当某个g整除d。因此可以按m的因数d分组，只需检查因数之间的整除。

当d<m时，gcd(x,m)=d的非零石头有phi(m/d)个，这是把x除以d后的互质剩余类。累加所有被覆盖组的人数count。覆盖集合在x与m−x之间成对对称，每对编号和为m，所以编号总和为m*count/2；0不影响总和，单独排除d=m即可。m/2若是自对称点，m一定为偶数，公式仍是整数。分解m一次就能算各组欧拉函数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests = 1;

    for (int tc = 1; tc <= tests; tc++) {
        int n;
        long long m;
        cin >> n >> m;
        set<long long> groups;
        for (int i = 0; i < n; i++) {
            long long a;
            cin >> a;
            groups.insert(gcd(a, m));
        }
        vector<long long> divisors, primes;
        for (long long d = 1; d * d <= m; d++)
            if (m % d == 0) {
                divisors.push_back(d);
                if (d * d != m)
                    divisors.push_back(m / d);
            }
        long long remaining = m;
        for (long long p = 2; p * p <= remaining; p++)
            if (remaining % p == 0) {
                primes.push_back(p);
                while (remaining % p == 0)
                    remaining /= p;
            }
        if (remaining > 1)
            primes.push_back(remaining);
        long long count = 0;
        for (long long d : divisors)
            if (d < m) {
                bool covered = false;
                for (long long g : groups)
                    if (d % g == 0) {
                        covered = true;
                        break;
                    }
                if (!covered)
                    continue;
                long long q = m / d, phi = q;
                for (long long p : primes)
                    if (q % p == 0)
                        phi = phi / p * (p - 1);
                count += phi;
            }
        cout << m * count / 2 << '\n';
    }
    return 0;
}
```

### 复杂度

因数数 $D$、不同gcd数 $G\le D$，时间 $O(n\log m+\sqrt m+DG+D\omega(m))$，空间 $O(D+G)$。

### 易错点

不是把所有步长一起取一个gcd：不同青蛙的可达集合取并集，不是允许在途中任意切换步长。编号范围是0到m−1，不含m。答案和乘积使用64位。

## 传送门

### 题意

两人通过同类传送门付费移动，最早相遇时间与全部相遇点。

### 思路

每类传送门建一个虚拟点，原点到该类虚点费用t，虚点到其全部原点费用0，避免把S个点完全连边。分别从1与n跑Dijkstra。两人可等候，因此在点u相遇时间为max(d1[u],dn[u])，对原始点取最小，再升序输出全部达到该时间者。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<long long> dijkstra(const vector<vector<pair<int, long long>>> &graph, int source) {
    const long long inf = 1LL << 60;
    vector<long long> distance(graph.size(), inf);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>,
                   greater<pair<long long, int>>>
        heap;
    distance[source] = 0;
    heap.push({0, source});
    while (!heap.empty()) {
        auto [cost, u] = heap.top();
        heap.pop();
        if (cost != distance[u])
            continue;
        for (auto [v, w] : graph[u])
            if (distance[v] > cost + w) {
                distance[v] = cost + w;
                heap.push({distance[v], v});
            }
    }
    return distance;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int, long long>>> graph(n + m);
    for (int i = 0; i < m; i++) {
        long long t;
        int count;
        cin >> t >> count;
        while (count--) {
            int u;
            cin >> u;
            u--;
            graph[u].push_back({n + i, t});
            graph[n + i].push_back({u, 0});
        }
    }
    auto first = dijkstra(graph, 0), second = dijkstra(graph, n - 1);
    long long best = (1LL << 60);
    for (int u = 0; u < n; u++)
        best = min(best, max(first[u], second[u]));
    if (best >= (1LL << 59)) {
        cout << -1;
        return 0;
    }
    cout << best << '\n';
    bool space = false;
    for (int u = 0; u < n; u++)
        if (max(first[u], second[u]) == best) {
            if (space)
                cout << ' ';
            space = true;
            cout << u + 1;
        }
    cout << '\n';
    return 0;
}
```

### 复杂度

令L为传送门出现总数，时间 $O((n+m+L)\log(n+m))$，空间 $O(n+m+L)$。

### 易错点

虚拟点不是可相遇地点，最后只枚举原始n点。两人并行，取最大到达时间而非距离和。

## 集合与最大公因数

### 题意

n组四个数，两两gcd=k，组间不重复，最小化最大数。

### 思路

所有数都可除以k，问题变成每组四个数两两互素。一组至多一个偶数，因此4n个不同数中至少3n个为奇数，最大数至少6n−1。

对i=0..n−1构造{6i+1,6i+2,6i+3,6i+5}，恰用3个奇数和1个偶数。不同奇数差2或4，可能公共奇因子只有来自差的因子，故互素；偶数与两邻数连续，与6i+5差3但它不被3整除，也互素。所有组不重复，最大值6n−1达到下界。最后全体乘k。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, k;
    cin >> n >> k;
    cout << (6 * n - 1) * k << '\n';
    for (long long i = 0; i < n; i++)
        cout << (6 * i + 1) * k << ' ' << (6 * i + 2) * k << ' ' << (6 * i + 3) * k << ' '
             << (6 * i + 5) * k << '\n';
    return 0;
}
```

### 复杂度

时间 $O(n)$，额外空间 $O(1)$。

### 易错点

最大公因数恰好k，构造基础数必须两两互素，不能只让整组gcd为1。

## 石子游戏

### 题意

每次从一堆取任意正数石子，判断先手胜负。

### 思路

全部堆大小的异或X为0时，改变任一堆都会使异或非0；X非0时，取最高置位所在的一堆a，把它减为a xor X，该数小于a，且使总异或变0。故先手胜当且仅当异或非0。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    int total = 0;
    while (n--) {
        int x;
        cin >> x;
        total ^= x;
    }
    cout << (total ? "Alice" : "Bob");
    return 0;
}
```

### 复杂度

时间 $O(n)$，空间 $O(1)$。

### 易错点

每次只能改一堆，不能用总石子数奇偶判断。

## 序列求和

### 题意

区间向下开根，查询区间和。

### 思路

正整数反复向下开根很快变1，而1以后不变。用set只保存值>1的位置，修改区间时从lower_bound(l)遍历至r，逐点开根并给Fenwick加入差值，变1就从set移除。每个初值≤10^9最多约5次有效变化，总修改量远小于nQ。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> tree;
    Fenwick(int n) : n(n), tree(n + 1) {}
    void add(int p, long long v) {
        for (; p <= n; p += p & -p)
            tree[p] += v;
    }
    long long sum(int p) {
        long long result = 0;
        for (; p; p -= p & -p)
            result += tree[p];
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n + 1);
    Fenwick bit(n);
    set<int> active;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        bit.add(i, a[i]);
        if (a[i] > 1)
            active.insert(i);
    }
    while (q--) {
        int op, l, r;
        cin >> op >> l >> r;
        if (op == 2)
            cout << bit.sum(r) - bit.sum(l - 1) << '\n';
        else {
            auto it = active.lower_bound(l);
            while (it != active.end() && *it <= r) {
                int p = *it;
                long long x = sqrtl(a[p]);
                while ((x + 1) * (x + 1) <= a[p])
                    x++;
                while (x * x > a[p])
                    x--;
                bit.add(p, x - a[p]);
                a[p] = x;
                if (x == 1)
                    it = active.erase(it);
                else
                    it++;
            }
        }
    }
    return 0;
}
```

### 复杂度

总时间 $O((Q+n\log\log A)\log n)$，空间 $O(n)$。

### 易错点

不能把整个区间和开根。开方用整数平方校正，避免完全平方数的浮点误差。

## 树和序列

### 题意

动态加点，沿最近不小权祖先链在预算内取最多节点。

### 思路

每点下一步被规则唯一确定为“最近的权值不小于自己的祖先”，称单调父亲；沿此链权值非递减。新点挂在R下时，若w[R]够大就取R，否则沿R的单调祖先倍增跳过仍小于新权的节点，再取其单调父亲。这不会漏掉原树中合格祖先，因为被单调父亲跳过的点权都更小。

同时维护jump[b][u]及cost[b][u]：从u开始取2^b个链点的总代价与之后位置。查询从高位到低位尝试整块加入，预算够就扣除并前进。权值非负，跳过可支付的最长块是最优。0号为无穷权哨兵，防止越过根多计零节点，根1权为0可正常选一次。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    const int levels = 20;
    const unsigned long long inf = 4000000000000000000ULL;
    vector<array<int, levels>> up(q + 2);
    vector<array<unsigned long long, levels>> cost(q + 2);
    vector<unsigned long long> weight(q + 2, inf);
    cost[0].fill(inf);
    cost[1].fill(inf);
    cost[1][0] = 0;
    weight[1] = 0;
    int nodes = 1;
    unsigned long long last = 0;
    while (q--) {
        int op;
        unsigned long long p, value;
        cin >> op >> p >> value;
        int r = (int)(p ^ last);
        value ^= last;
        if (op == 1) {
            int parent = r;
            if (weight[parent] < value) {
                for (int b = levels - 1; b >= 0; b--)
                    if (weight[up[parent][b]] < value)
                        parent = up[parent][b];
                parent = up[parent][0];
            }
            int u = ++nodes;
            weight[u] = value;
            up[u][0] = parent;
            cost[u][0] = value;
            for (int b = 1; b < levels; b++) {
                int v = up[u][b - 1];
                up[u][b] = up[v][b - 1];
                cost[u][b] = min(inf, cost[u][b - 1] + cost[v][b - 1]);
            }
        } else {
            last = 0;
            int u = r;
            for (int b = levels - 1; b >= 0; b--)
                if (cost[u][b] <= value) {
                    value -= cost[u][b];
                    last += 1ULL << b;
                    u = up[u][b];
                }
            cout << last << '\n';
        }
    }
    return 0;
}
```

### 复杂度

每次操作 $O(\log Q)$，空间 $O(Q\log Q)$。

### 易错点

每行p、q都先与上次查询答案异或；添加操作不更新last。样例包含零权新点，代码同样支持。

## 石子游戏2

### 题意

堆栈增删石子堆，每天最小代价丢若干堆使Nim和为0。

### 思路

当前总异或为X，Bob获胜要求保留堆异或0，等价于丢弃子集异或X。令dp[s]为丢弃子集异或s的最小代价。添加(a,b)对应0/1异或背包，按x与x xor a成对更新，可原地同时使用两份旧值。

删除不能直接撤销最小值，所以先读完操作，把每个ADD到对应DEL之前的存在期记为时间区间。将物品加入覆盖其存在期的时间线段树。DFS进入节点时复制父DP，加入本节点物品；叶子查询dp[当日总异或]。兄弟节点各用父表，天然恢复删除前状态。

值小于2^14，DP最多16384项。若dp[a]≤b，新增物品可由已有更便宜的同异或子集替代，整件更新可以安全跳过；每节点按b升序加入，让这一支配剪枝尽早生效。代价为正，即使替代集合与原方案重叠，抵消重复元素只会更便宜。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    struct Item {
        int value, cost, left, right;
    };
    vector<Item> item;
    vector<int> stack, totalXor(n);
    int current = 0, maximum = 0;
    for (int day = 0; day < n; day++) {
        string op;
        cin >> op;
        if (op == "ADD") {
            int a, b;
            cin >> a >> b;
            item.push_back({a, b, day, n - 1});
            stack.push_back(item.size() - 1);
            current ^= a;
            maximum = max(maximum, a);
        } else {
            int id = stack.back();
            stack.pop_back();
            item[id].right = day - 1;
            current ^= item[id].value;
        }
        totalXor[day] = current;
    }
    int states = 1;
    while (states <= maximum)
        states <<= 1;
    vector<vector<int>> event(4 * n + 4);
    auto insert = [&](auto &&self, int u, int l, int r, int ql, int qr, int id) -> void {
        if (ql <= l && r <= qr) {
            event[u].push_back(id);
            return;
        }
        int mid = (l + r) / 2;
        if (ql <= mid)
            self(self, u * 2, l, mid, ql, qr, id);
        if (qr > mid)
            self(self, u * 2 + 1, mid + 1, r, ql, qr, id);
    };
    for (int id = 0; id < (int)item.size(); id++)
        insert(insert, 1, 0, n - 1, item[id].left, item[id].right, id);
    for (auto &row : event)
        sort(row.begin(), row.end(), [&](int a, int b) { return item[a].cost < item[b].cost; });
    const int inf = 1000000000;
    vector<int> initial(states, inf), answer(n);
    initial[0] = 0;
    auto solve = [&](auto &&self, int u, int l, int r, const vector<int> &parent) -> void {
        vector<int> dp = parent;
        for (int id : event[u]) {
            auto it = item[id];
            if (dp[it.value] <= it.cost)
                continue;
            int pivot = 1;
            while (pivot <= it.value / 2)
                pivot <<= 1;
            for (int block = 0; block < states; block += 2 * pivot)
                for (int offset = 0; offset < pivot; offset++) {
                    int x = block + offset, y = x ^ it.value, oldX = dp[x], oldY = dp[y];
                    dp[x] = min(oldX, oldY + it.cost);
                    dp[y] = min(oldY, oldX + it.cost);
                }
        }
        if (l == r)
            answer[l] = dp[totalXor[l]];
        else {
            int mid = (l + r) / 2;
            self(self, u * 2, l, mid, dp);
            self(self, u * 2 + 1, mid + 1, r, dp);
        }
    };
    solve(solve, 1, 0, n - 1, initial);
    for (int x : answer)
        cout << x << '\n';
    return 0;
}
```

### 复杂度

令U≤2^14、A为ADD次数，最坏时间 $O((A\log n+n)U)$，空间 $O(A\log n+U\log n+n)$；支配剪枝改善实际耗时，不改变最坏界。

### 易错点

当天DEL后该堆已不存在，生存区间右端为删除日−1。两个异或成对状态必须保存旧值后一起更新，避免同件重复使用。

## 序列游戏

### 题意

末尾追加0..255值，查询从指定位置已选后谁获胜。

### 思路

固定序列从后向前，令lose表示“选中此处后，下一人无必胜策略”的位置值集合。位置i若能走到某个lose位置，就是胜态；否则是lose并加入其值。可走条件是两个值相同或仅差一个二进制位，所以一旦某个值被lose集合的邻值覆盖，此后永远不会成为lose。

因此同一个数只需看它的最后一次出现；按256种值的最后位置从大到小扫描，若该值尚未被覆盖，就选为lose，并覆盖自身及8个一位差邻值。为每种值v记录所有已选lose邻值的最大位置threshold[v]。

查询起点k已经由Alice选中，轮到Bob；Bob能赢当且仅当存在位置>k的lose邻值，即threshold[a[k]]>k。追加时把该值移到最近使用链表表头，重算256种值的覆盖即可；查询常数时间。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a;
    a.reserve(n + m);
    array<int, 256> latest = {}, threshold = {};
    for (int i = 1; i <= n; i++) {
        int x;
        cin >> x;
        a.push_back(x);
        latest[x] = i;
    }
    list<int> order;
    vector<int> values;
    for (int v = 0; v < 256; v++)
        if (latest[v])
            values.push_back(v);
    sort(values.begin(), values.end(), [&](int x, int y) { return latest[x] > latest[y]; });
    array<list<int>::iterator, 256> where;
    for (int v : values) {
        order.push_back(v);
        where[v] = prev(order.end());
    }
    auto rebuild = [&]() {
        array<bool, 256> blocked = {};
        threshold.fill(0);
        for (int v : order)
            if (!blocked[v]) {
                auto cover = [&](int x) {
                    blocked[x] = true;
                    threshold[x] = max(threshold[x], latest[v]);
                };
                cover(v);
                for (int b = 0; b < 8; b++)
                    cover(v ^ (1 << b));
            }
    };
    rebuild();
    while (m--) {
        int op, k;
        cin >> op >> k;
        if (op == 1) {
            if (latest[k])
                order.erase(where[k]);
            order.push_front(k);
            where[k] = order.begin();
            a.push_back(k);
            latest[k] = a.size();
            rebuild();
        } else
            cout << (threshold[a[k - 1]] > k ? "Bob\n" : "Alice\n");
    }
    return 0;
}
```

### 复杂度

初始化 $O(n+256\log256)$，追加 $O(256\cdot9)$，查询 $O(1)$；空间 $O(n+m+256)$。

### 易错点

相同数也可跳，邻域包含自身。全局记录中位置≤k的lose点不会误判，因为查询要求严格大于k。

## 二叉树游戏

### 题意

每次删除一棵完美二叉子树，判断胜负。

### 思路

题目定义的“完全二叉”实际是每层全满的完美二叉树，节点数为2^h−1，永远为奇数。因此每步删除奇数个节点，节点总数奇偶每步翻转。只要还剩节点就有叶子，单节点子树可以删除，游戏必在空树结束。总操作次数与初始n同奇偶，所以n奇数先手胜，偶数后手胜。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
    }
    cout << (n % 2 ? "Alice" : "Bob");
    return 0;
}
```

### 复杂度

读入时间 $O(n)$，额外空间 $O(1)$。

### 易错点

按题目给出的“所有叶同深度且非叶都有两儿子”定义，不能套用通常仅最后一层可缺的完全二叉树。

## Mountain Is Quiet and Alone

### 题意

长1线段沿单调山坡逆时针滚动，遇到更低接触点更换支点，求头端总路程。

### 思路

两次接触事件之间，线段绕当前最低支点O做纯旋转，头部走一段半径|OH|的圆弧，路程=半径×转角。下一接触只有两类：山坡顶点碰到线段内部，或线段某个端点碰到山坡边内部。第一类枚举支点左下方、距离不超过相应半臂长度的山坡顶点；第二类求以O为圆心、头臂/尾臂长度为半径的圆与每条山坡边的交点。

对每个候选接触，把从当前线段朝向转到候选朝向的逆时针角归一到[0,2π)，取最小。新接触点必须严格低于O；同一时刻有多个接触时选最低的那个。头端朝向候选点，尾端则朝向其反方向。除此以外，单独求头部圆轨迹与y=0的交会角，若它更早发生就结束。

转过事件角后同时旋转头和尾，累加头弧长，再换支点。半臂长度并非总为1：支点可能在身体内部，头臂为0时头暂时不动。山坡还包括从(0,0)向左的水平地面。每个坡顶最多成为一次更低支点，两次坡顶接触之间的端点滚动每步沿坡推进一个单位，所以事件数受n与坡线长度共同限制。

