### 动态示例

![按原题样例2与同一份参考程序的接触事件绘制：观察尾、头及支点的切换，并按各阶段头臂长度累加圆弧路程。](assets/rolling-contact-events.gif)

按原题样例2与同一份参考程序的接触事件绘制：观察尾、头及支点的切换，并按各阶段头臂长度累加圆弧路程。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

Point rotated(Point p, long double angle) {
    return {p.x * cosl(angle) - p.y * sinl(angle), p.x * sinl(angle) + p.y * cosl(angle)};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<Point> mountain = {{-10000, 0}, {0, 0}};
    for (int i = 0; i < n; i++) {
        Point p;
        cin >> p.x >> p.y;
        mountain.push_back(p);
    }
    Point pivot = mountain.back(), tail = pivot, head = pivot + Point{0, 1};
    long double answer = 0, pi = acosl(-1.0L);
    while (head.y > 1e-11L) {
        Point body = head - tail;
        long double h = distance(head, pivot), t = distance(tail, pivot), best = 2 * pi;
        Point contact;
        bool stop = false;
        auto angleTo = [&](Point d) {
            long double angle = atan2l(cross(body, d), dot(body, d));
            if (angle < -1e-12L)
                angle += 2 * pi;
            return max(0.0L, angle);
        };
        auto candidate = [&](Point p, bool headSide) {
            if (p.y >= pivot.y - 1e-11L)
                return;
            Point d = headSide ? p - pivot : pivot - p;
            long double angle = angleTo(d);
            if (angle < best - 1e-12L || (fabsl(angle - best) <= 1e-12L && p.y < contact.y)) {
                best = angle;
                contact = p;
                stop = false;
            }
        };
        if (h > 1e-14L && pivot.y <= h + 1e-12L) {
            long double a = asinl(clamp(-pivot.y / h, -1.0L, 1.0L));
            for (long double angle : {a, pi - a}) {
                Point d = {cosl(angle), sinl(angle)};
                long double turn = angleTo(d);
                if (turn < best) {
                    best = turn;
                    stop = true;
                }
            }
        }
        for (int i = 1; i < (int)mountain.size(); i++) {
            Point p = mountain[i];
            if (p.y < pivot.y - 1e-11L) {
                long double d = distance(p, pivot);
                if (d <= h + 1e-12L)
                    candidate(p, true);
                if (d <= t + 1e-12L)
                    candidate(p, false);
            }
        }
        for (int i = 0; i + 1 < (int)mountain.size(); i++) {
            Point a = mountain[i], e = mountain[i + 1] - a;
            for (auto [radius, headSide] : {pair<long double, bool>{h, true}, {t, false}}) {
                if (radius < 1e-14L)
                    continue;
                Point offset = a - pivot;
                long double A = dot(e, e), B = 2 * dot(e, offset),
                            C = dot(offset, offset) - radius * radius,
                            discriminant = B * B - 4 * A * C;
                if (discriminant < -1e-12L)
                    continue;
                long double root = sqrtl(max(0.0L, discriminant));
                for (long double u : {(-B - root) / (2 * A), (-B + root) / (2 * A)})
                    if (u >= -1e-12L && u <= 1 + 1e-12L)
                        candidate(a + e * clamp(u, 0.0L, 1.0L), headSide);
            }
        }
        answer += h * best;
        head = pivot + rotated(head - pivot, best);
        tail = pivot + rotated(tail - pivot, best);
        if (stop)
            break;
        pivot = contact;
    }
    cout << fixed << setprecision(15) << answer;
    return 0;
}
```

### 复杂度

设坡线总长L<2000，事件数 $O(n+L)$，总时间 $O(n(n+L))$，空间 $O(n)$。

### 易错点

不能只在山坡顶点换支点，身体端点落在边中间也会触发事件。不能把整条身体的转动角直接累加成头路程，必须乘当前头臂长度。题目保证端点接触远离坡顶，可避免端点与坡顶数值重合。

## Light of Stars

### 题意

相同角度区间光线照向其他星星，统计每个星星收到几次照射。

### 思路

角度从正x轴顺时针，且所有区间在[0,180)内。因此光源q一定在目标p的上方或同高。先计算Fθ(p)：向量p−q的顺时针角≤θ的光源数。0<θ<180时，这等价于q.y≥p.y，且sinθ*q.x+cosθ*q.y≤sinθ*p.x+cosθ*p.y。

按y降序扫描，先加入同y的所有光源，再用旋转投影值上的树状数组查前缀。求区间[l,r]时用F≤r−F<l，严格版本把upper_bound改为lower_bound。同一点不照射自身，≤查询减去自身，严格<查询天然排除自身。θ=0单独按同一行从左向右计数。

整数坐标能精确落在整数度数边界的非零向量，仅可能对应0、45、90、135度，分别用整数线性式处理，其他角使用long double。结果缓存相同端点的查询。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<pair<int, int>> p(n);
    for (auto &q : p)
        cin >> q.first >> q.second;
    vector<pair<int, int>> interval(k);
    for (auto &q : interval)
        cin >> q.first >> q.second;
    map<pair<int, bool>, vector<int>> cache;
    auto calculate = [&](int degree, bool strict) {
        vector<int> result(n);
        if (degree == 0) {
            if (strict)
                return result;
            vector<int> id(n);
            iota(id.begin(), id.end(), 0);
            sort(id.begin(), id.end(), [&](int a, int b) {
                return p[a].second != p[b].second ? p[a].second < p[b].second
                                                  : p[a].first < p[b].first;
            });
            int start = 0;
            for (int i = 0; i < n; i++) {
                if (i == 0 || p[id[i]].second != p[id[i - 1]].second)
                    start = i;
                result[id[i]] = i - start;
            }
            return result;
        }
        long double a = sinl(degree * acosl(-1.0L) / 180), b = cosl(degree * acosl(-1.0L) / 180);
        if (degree == 45) {
            a = 1;
            b = 1;
        }
        if (degree == 90) {
            a = 1;
            b = 0;
        }
        if (degree == 135) {
            a = 1;
            b = -1;
        }
        vector<long double> value(n), coordinate;
        vector<int> order(n);
        for (int i = 0; i < n; i++) {
            value[i] = a * p[i].first + b * p[i].second;
            order[i] = i;
        }
        coordinate = value;
        sort(coordinate.begin(), coordinate.end());
        coordinate.erase(unique(coordinate.begin(), coordinate.end()), coordinate.end());
        sort(order.begin(), order.end(), [&](int x, int y) { return p[x].second > p[y].second; });
        vector<int> bit(coordinate.size() + 1);
        auto add = [&](int at) {
            for (; at < (int)bit.size(); at += at & -at)
                bit[at]++;
        };
        for (int i = 0; i < n;) {
            int j = i;
            while (j < n && p[order[j]].second == p[order[i]].second) {
                int id = order[j++];
                add(lower_bound(coordinate.begin(), coordinate.end(), value[id]) -
                    coordinate.begin() + 1);
            }
            for (int at = i; at < j; at++) {
                int id = order[at],
                    rank = (strict ? lower_bound(coordinate.begin(), coordinate.end(), value[id])
                                   : upper_bound(coordinate.begin(), coordinate.end(), value[id])) -
                           coordinate.begin();
                int count = 0;
                for (; rank; rank -= rank & -rank)
                    count += bit[rank];
                result[id] = count - !strict;
            }
            i = j;
        }
        return result;
    };
    vector<long long> answer(n);
    for (auto [l, r] : interval) {
        for (auto [angle, strict, sign] : {tuple<int, bool, int>{r, false, 1}, {l, true, -1}}) {
            auto key = make_pair(angle, strict);
            if (!cache.count(key))
                cache[key] = calculate(angle, strict);
            for (int i = 0; i < n; i++)
                answer[i] += sign * cache[key][i];
        }
    }
    for (auto x : answer)
        cout << x << ' ';
    return 0;
}
```

### 复杂度

时间 $O(kn\log n)$，缓存空间 $O(kn)$。

### 易错点

输入是顺时针角，不能沿用常见逆时针极角。边界包含，左端必须减严格小于l的数量。各光区互不相交，最终可直接求和。

## [国家集训队]拉拉队排练

### 题意

所有奇数长度回文子串按长度降序，求前 K 个长度的乘积。

### 思路

用 Manacher 得到每个中心的最长奇回文长度。若某中心最长为 L，它就恰好给 L、L-2、……、1 各贡献一次。因此先按最长长度计数，再沿奇数长度从大到小累加后缀，得到每个长度的实际出现次数。每个长度取 min(剩余K,出现次数) 项，用快速幂把这一长度的重复乘法一次完成。全部用尽仍不足 K 则输出 -1。

Manacher 的 odd[i] 表示以 i 为中心、包含中心的最大奇回文半径，长度为 2odd[i]-1；even[i] 表示中心在 i-1 与 i 之间的最大偶回文半径，长度为 2even[i]。维护已知最靠右的回文区间，利用镜像位置的半径初始化，再只向未知部分扩展。右边界只会前进，全部扩展次数为线性。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct PalindromeRadii {
    vector<int> odd, even;
    explicit PalindromeRadii(const string &s) {
        int n = s.size();
        odd.resize(n);
        even.resize(n);
        int left = 0, right = -1;
        for (int i = 0; i < n; i++) {
            int k = i > right ? 1 : min(odd[left + right - i], right - i + 1);
            while (i - k >= 0 && i + k < n && s[i - k] == s[i + k])
                k++;
            odd[i] = k;
            if (i + k - 1 > right) {
                left = i - k + 1;
                right = i + k - 1;
            }
        }
        left = 0;
        right = -1;
        for (int i = 0; i < n; i++) {
            int k = i > right ? 0 : min(even[left + right - i + 1], right - i + 1);
            while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k])
                k++;
            even[i] = k;
            if (i + k - 1 > right) {
                left = i - k;
                right = i + k - 1;
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    string s;
    cin >> n >> k >> s;
    PalindromeRadii radius(s);
    vector<long long> count(n + 3);
    for (int r : radius.odd)
        count[2 * r - 1]++;
    const long long mod = 19930726;
    auto power = [&](long long a, long long exponent) {
        long long result = 1;
        while (exponent) {
            if (exponent & 1)
                result = result * a % mod;
            a = a * a % mod;
            exponent >>= 1;
        }
        return result;
    };
    long long answer = 1;
    for (int length = n % 2 ? n : n - 1; length >= 1 && k > 0; length -= 2) {
        count[length] += count[length + 2];
        long long take = min(k, count[length]);
        answer = answer * power(length, take) % mod;
        k -= take;
    }
    cout << (k ? -1 : answer);
    return 0;
}
```

### 复杂度

预处理 $O(n)$，选取阶段 $O(n\log(K+1))$ 的上界，空间 $O(n)$。

### 易错点

位置不同的相同回文也分别计数。只考虑奇数长度，K 最大万亿，不能逐项枚举。模数不必为素数，普通快速幂仍可用。

## [国家集训队]最长双回文串

### 题意

求可拆成两个相邻非空回文的最长连续子串。

### 思路

预处理 end[i] 为恰在 i 结束的最长回文长度，start[i] 为恰在 i 开始的最长回文长度。先把每个中心的最大奇、偶回文记到它的左右端点。一个长度 L 的回文去掉两端后，得到向内缩一格、长度 L-2 的回文，所以 end 从右向左按 end[i+1]-2 传播，start 从左向右按 start[i-1]-2 传播，就补齐所有较短半径。最后枚举分割缝 i|i+1，最大化 end[i]+start[i+1]。两段正好相邻且都非空。

Manacher 的 odd[i] 表示以 i 为中心、包含中心的最大奇回文半径，长度为 2odd[i]-1；even[i] 表示中心在 i-1 与 i 之间的最大偶回文半径，长度为 2even[i]。维护已知最靠右的回文区间，利用镜像位置的半径初始化，再只向未知部分扩展。右边界只会前进，全部扩展次数为线性。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct PalindromeRadii {
    vector<int> odd, even;
    explicit PalindromeRadii(const string &s) {
        int n = s.size();
        odd.resize(n);
        even.resize(n);
        int left = 0, right = -1;
        for (int i = 0; i < n; i++) {
            int k = i > right ? 1 : min(odd[left + right - i], right - i + 1);
            while (i - k >= 0 && i + k < n && s[i - k] == s[i + k])
                k++;
            odd[i] = k;
            if (i + k - 1 > right) {
                left = i - k + 1;
                right = i + k - 1;
            }
        }
        left = 0;
        right = -1;
        for (int i = 0; i < n; i++) {
            int k = i > right ? 0 : min(even[left + right - i + 1], right - i + 1);
            while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k])
                k++;
            even[i] = k;
            if (i + k - 1 > right) {
                left = i - k;
                right = i + k - 1;
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    cin >> s;
    int n = s.size();
    PalindromeRadii radius(s);
    vector<int> ending(n), starting(n);
    for (int i = 0; i < n; i++) {
        int r = radius.odd[i], length = 2 * r - 1;
        ending[i + r - 1] = max(ending[i + r - 1], length);
        starting[i - r + 1] = max(starting[i - r + 1], length);
        r = radius.even[i];
        if (r) {
            length = 2 * r;
            ending[i + r - 1] = max(ending[i + r - 1], length);
            starting[i - r] = max(starting[i - r], length);
        }
    }
    for (int i = n - 2; i >= 0; i--)
        ending[i] = max(ending[i], ending[i + 1] - 2);
    for (int i = 1; i < n; i++)
        starting[i] = max(starting[i], starting[i - 1] - 2);
    int answer = 0;
    for (int i = 0; i + 1 < n; i++)
        answer = max(answer, ending[i] + starting[i + 1]);
    cout << answer;
    return 0;
}
```

### 复杂度

时间、空间均为 $O(n)$。

### 易错点

这是两个相邻回文，不能拿两个可能相交的全局最长回文直接相加。较短回文也可能参与最优答案，端点传播不能省略。

## [POI2010]ANT-Antisymmetry

### 题意

统计反转并零一取反后保持不变的非空子串。

### 思路

反对称串不可能为奇数长度，因为中心字符无法与自身取反后相同。对所有位置 i，把原二进制字符异或 i 的奇偶性，得到 t[i]。偶长度子串中任意一对镜像下标奇偶性相反，所以原字符不同，当且仅当变换后的字符相同。因此原串的反对称子串，恰好对应变换串的偶长度回文。求 Manacher 的偶半径并求和即可，每个半径的一到其最大值各对应一个不同位置的子串。

Manacher 的 odd[i] 表示以 i 为中心、包含中心的最大奇回文半径，长度为 2odd[i]-1；even[i] 表示中心在 i-1 与 i 之间的最大偶回文半径，长度为 2even[i]。维护已知最靠右的回文区间，利用镜像位置的半径初始化，再只向未知部分扩展。右边界只会前进，全部扩展次数为线性。

### 参考代码

```cpp
#include <bits/stdc++.h>
