}
```

### 复杂度

时间、空间均为 $O(n)$。

### 易错点

只累计偶回文半径，不能加入奇回文。即使内容相同，只要起止位置不同也分别计数，答案需要 long long。

## [APIO2014]回文串

### 题意

回文子串长度乘出现次数的最大值。

### 思路

回文树每个非根节点代表一个不同回文串，两个根分别为长度−1、0。加入字符c时，从当前最长回文后缀沿fail找能被c两侧包住的后缀，得到新回文；若节点不存在则建立并寻找其最长真回文后缀fail。给当前最长回文后缀次数加1。

每个位置结束的较短回文都在其fail链上，因此最后按创建编号逆序向fail累加次数，得到每个回文的真实出现次数。fail节点总比自己早建，逆编号即可。取len*count最大值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string s;
    cin >> n >> s;
    struct Node {
        array<int, 26> next = {};
        int length = 0, fail = 0, count = 0;
    };
    vector<Node> node;
    node.reserve(n + 2);
    node.emplace_back();
    node.emplace_back();
    node[0].length = -1;
    node[1].fail = 0;
    int last = 1;
    auto find = [&](int u, int position) {
        while (position - node[u].length - 1 < 0 || s[position - node[u].length - 1] != s[position])
            u = node[u].fail;
        return u;
    };
    for (int i = 0; i < n; i++) {
        int c = s[i] - 'a', p = find(last, i);
        if (!node[p].next[c]) {
            int u = node.size();
            node.emplace_back();
            node[u].length = node[p].length + 2;
            node[u].fail = node[u].length == 1 ? 1 : node[find(node[p].fail, i)].next[c];
            node[p].next[c] = u;
        }
        last = node[p].next[c];
        node[last].count++;
    }
    long long answer = 0;
    for (int u = (int)node.size() - 1; u >= 2; u--) {
        answer = max(answer, 1LL * node[u].length * node[u].count);
        node[node[u].fail].count += node[u].count;
    }
    cout << answer;
    return 0;
}
```

### 复杂度

固定字母表时间 $O(n)$，空间 $O(26n)$。

### 易错点

长度−1根保证总能扩展，不参与答案。重复出现可重叠，不能只计不同回文节点数量。

## Colorful String

### 题意

每个回文子串的价值为不同字母数，累计所有回文出现的价值。

### 思路

按字母分别计贡献。对某字母 c，所有包含 c 的回文各贡献一；其数量等于全部回文数，减去不含 c 的回文数。把字符串按 c 的出现位置切成若干个不含 c 的连续段，不含 c 的回文必完整落在其中某一段，在各段独立用 Manacher 计数即可。于是答案是 26*全部回文数，再减去二十六次所有无 c 段中的回文数。固定字母只有二十六种，每轮段长之和不超过 n，所以总共线性乘一个常数。

计数函数分别求奇、偶回文半径，将半径求和；数组可在各段间复用。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

long long countPalindromes(const string &s, int begin, int end, vector<int> &radius) {
    long long answer = 0;
    int left = begin, right = begin - 1;
    for (int i = begin; i < end; i++) {
        int k = i > right ? 1 : min(radius[left + right - i], right - i + 1);
        while (i - k >= begin && i + k < end && s[i - k] == s[i + k])
            k++;
        radius[i] = k;
        answer += k;
        if (i + k - 1 > right) {
            left = i - k + 1;
            right = i + k - 1;
        }
    }
    left = begin;
    right = begin - 1;
    for (int i = begin; i < end; i++) {
        int k = i > right ? 0 : min(radius[left + right - i + 1], right - i + 1);
        while (i - k - 1 >= begin && i + k < end && s[i - k - 1] == s[i + k])
            k++;
        radius[i] = k;
        answer += k;
        if (i + k - 1 > right) {
            left = i - k;
            right = i + k - 1;
        }
    }
    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    cin >> s;
    int n = s.size();
    vector<int> radius(n);
    long long total = countPalindromes(s, 0, n, radius), answer = 26 * total;
    for (char c = 'a'; c <= 'z'; c++) {
        int begin = 0;
        for (int i = 0; i <= n; i++)
            if (i == n || s[i] == c) {
                answer -= countPalindromes(s, begin, i, radius);
                begin = i + 1;
            }
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(26n)$，额外空间 $O(n)$。

### 易错点

同一个字母在回文里出现多次仍只贡献一。不能把“回文长度”当价值；空段没有回文。总贡献可超过 32 位。

## A Chess Game

### 题意

DAG上若干棋子独立移动，判断先手。

### 思路

单棋子在u的SG值为所有后继SG的mex，终点为0。题目保证边指向更大编号，按编号倒序计算即可。多个棋子是独立游戏和，SG异或非0时先手赢。重复棋子也逐个异或，相同状态两枚会抵消。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> edge(n);
    for (auto &row : edge) {
        int k;
        cin >> k;
        row.resize(k);
        for (int &v : row)
            cin >> v;
    }
    vector<int> sg(n);
    for (int u = n - 1; u >= 0; u--) {
        vector<bool> seen(edge[u].size() + 1);
        for (int v : edge[u])
            if (sg[v] < (int)seen.size())
                seen[sg[v]] = true;
        while (sg[u] < (int)seen.size() && seen[sg[u]])
            sg[u]++;
    }
    int m;
    while (cin >> m && m) {
        int total = 0;
        while (m--) {
            int u;
            cin >> u;
            total ^= sg[u];
        }
        cout << (total ? "WIN\n" : "LOSE\n");
    }
    return 0;
}
```

### 复杂度

预处理 $O(n+E)$，每问 $O(m)$，空间 $O(n+E)$。

### 易错点

输出说明一处误写LOST，样例与来源使用LOSE，代码采用LOSE。mex只需标记到出度，因为mex不会超过可达状态数。

## S-Nim

### 题意

允许减集合S中数的多堆游戏，输出每问胜负字母。

### 思路

预处理0..10000的SG：sg[h]=mex{sg[h−s]，s∈S且s≤h}。用时间戳数组标记本轮后继，避免每个h清大数组。询问把各堆SG异或，非0输出W，否则L，所有询问连成一串。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int k;
    cin >> k;
    vector<int> move(k);
    for (int &x : move)
        cin >> x;
    sort(move.begin(), move.end());
    const int limit = 10000;
    vector<int> sg(limit + 1), seen(k + 2, -1);
    for (int h = 1; h <= limit; h++) {
        for (int s : move) {
            if (s > h)
                break;
            if (sg[h - s] < (int)seen.size())
                seen[sg[h - s]] = h;
        }
        while (seen[sg[h]] == h)
            sg[h]++;
    }
    int m;
    cin >> m;
    string answer;
    while (m--) {
        int count;
        cin >> count;
        int total = 0;
        while (count--) {
            int h;
            cin >> h;
            total ^= sg[h];
        }
        answer.push_back(total ? 'W' : 'L');
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(10000k+\sum l)$，空间 $O(10000+k)$。

### 易错点

空堆SG为0；不能只预处理单堆胜负，因为多堆组合需要完整SG值。

## Stone Game

### 题意

每箱一次可添1到当前石子平方个，不超容量，多箱组合。

### 思路

单箱容量s、当前c。若c=0，无论剩余容量多少都不能放，SG=0。若c²≥s−c，一步可到任意更大c，故SG=s−c。

否则令t为满足t(t+1)≥s的最小整数。所有c≥t都属于上一种情形。对c<t，跨入高区的后继SG最小为s−(c+c²)，而s≥t²−t+1，所以它≥(t−1−c)(t+c)+1>t−1−c。这些高SG不会影响只看低区时的mex（低区后继总数不超过t−1−c），因此可把容量缩为t−1，SG不变。反复平方根缩小后进入直接求值情形，最后各箱SG异或。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    auto grundy = [](long long s, long long c) {
        if (!c)
            return 0LL;
        while (c * c < s - c) {
            long long t = sqrtl(s);
            while (t * (t + 1) < s)
                t++;
            while (t > 0 && (t - 1) * t >= s)
                t--;
            s = t - 1;
        }
        return s - c;
    };
    long long total = 0;
    while (n--) {
        long long s, c;
        cin >> s >> c;
        total ^= grundy(s, c);
    }
    cout << (total ? "Yes" : "No");
    return 0;
}
```

### 复杂度

每箱 $O(\log\log s)$ 轮整数阈值计算，空间 $O(1)$。

### 易错点

c=0时不能添加，必须单独返回0。缩减的是容量s，当前c保持不变。

## Christmas Game

### 题意

每次向k级祖先移动任意多石子，对全部树根判胜负。

### 思路

固定根时，把深度按长度k分块。仅奇数块（floor(depth/k)为奇数）的石子堆参与Nim异或：每次上移k层恰在奇偶块之间转移，0异或局面任何移动都会改变一个被计入堆；非0时可从某奇块堆减到令异或为0的大小，再把取出的石子移入偶块，因此判定成立。

只需知道距离模2k，令down[u][r]为u子树中距离u模2k等于r的a异或。后序将儿子余数整体+1合并。换根到儿子v时，先从u的全树余数表中异或去v子树贡献，再把其余部分距离+1并入v。每个根取余数k..2k−1的异或。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct EulerTree {
    int n;
    vector<vector<int>> edge;
    vector<int> parent, depth, in, out, order;
    EulerTree(int n) : n(n), edge(n + 1), parent(n + 1), depth(n + 1), in(n + 1), out(n + 1) {}
    void add(int u, int v) {
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    void root(int start) {
        vector<int> stack = {start};
        parent[start] = 0;
        order.clear();
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            in[u] = order.size() + 1;
            order.push_back(u);
            for (int v : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack.push_back(v);
                }
        }
        vector<int> size(n + 1, 1);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            out[u] = in[u] + size[u] - 1;
            if (parent[u])
                size[parent[u]] += size[u];
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    EulerTree tree(n);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        tree.add(u, v);
    }
    int period = 2 * k;
    vector<vector<int>> dp(n + 1, vector<int>(period));
    for (int u = 1; u <= n; u++)
        cin >> dp[u][0];
    tree.root(1);
    for (int i = n - 1; i > 0; i--) {
        int u = tree.order[i], p = tree.parent[u];
        for (int r = 0; r < period; r++)
            dp[p][(r + 1) % period] ^= dp[u][r];
    }
    vector<int> answer(n + 1);
    for (int u : tree.order) {
        int value = 0;
        for (int r = k; r < period; r++)
            value ^= dp[u][r];
        answer[u] = value != 0;
        for (int v : tree.edge[u])
            if (tree.parent[v] == u) {
                auto old = dp[v];
                for (int r = 0; r < period; r++)
                    dp[v][r] =
                        old[r] ^ dp[u][(r - 1 + period) % period] ^ old[(r - 2 + period) % period];
            }
    }
    for (int u = 1; u <= n; u++)
        cout << answer[u] << (u == n ? '\n' : ' ');
    return 0;
}
```

### 复杂度

时间、空间均 $O(nk)$。

### 易错点

参与的是距离模2k落在后半段，不是距离模k。换根计算需保存儿子旧子树表，不能边覆盖边读取。

## A New Tetris Game(2)

### 题意

多个有禁格棋盘放2×2，最后不能放者输。

### 思路

把每个初始可放的2×2位置视为一种动作，两个动作若共享格子就冲突。状态mask表示仍可选动作，选择i后删除其自身及全部冲突邻居，SG取所有后继SG的mex。R*C<50且可用格≤40，动作数量可用64位保存。

若剩余动作冲突图分成连通分量，不同分量独立，SG是各分量SG异或。每次先按位BFS拆分，再对连通状态记忆化搜索，减少长条棋盘和分裂局面的重复枚举。不同棋盘再作SG异或。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int boards;
    cin >> boards;
    int total = 0;
    while (boards--) {
        int rows, cols;
        cin >> rows >> cols;
        vector<string> grid(rows);
        for (auto &s : grid)
            cin >> s;
        vector<unsigned long long> cells;
        for (int r = 0; r + 1 < rows; r++)
            for (int c = 0; c + 1 < cols; c++)
                if (grid[r][c] == '0' && grid[r + 1][c] == '0' && grid[r][c + 1] == '0' &&
                    grid[r + 1][c + 1] == '0')
                    cells.push_back((1ULL << (r * cols + c)) | (1ULL << (r * cols + c + 1)) |
                                    (1ULL << ((r + 1) * cols + c)) |
                                    (1ULL << ((r + 1) * cols + c + 1)));
        int moves = cells.size();
        vector<unsigned long long> conflict(moves);
        for (int i = 0; i < moves; i++)
            for (int j = 0; j < moves; j++)
                if (cells[i] & cells[j])
                    conflict[i] |= 1ULL << j;
        unordered_map<unsigned long long, int> memo;
        memo[0] = 0;
        auto grundy = [&](auto &&self, unsigned long long mask) -> int {
            auto found = memo.find(mask);
            if (found != memo.end())
                return found->second;
            unsigned long long component = 0, frontier = mask & -mask;
            while (frontier) {
                component |= frontier;
                unsigned long long next = 0;
                for (auto bits = frontier; bits; bits &= bits - 1)
                    next |= conflict[__builtin_ctzll(bits)];
                frontier = next & mask & ~component;
            }
            if (component != mask)
                return memo[mask] = self(self, component) ^ self(self, mask ^ component);
            unsigned long long seen = 0;
            for (auto bits = mask; bits; bits &= bits - 1) {
                int i = __builtin_ctzll(bits);
                seen |= 1ULL << self(self, mask & ~conflict[i]);
            }
            int value = __builtin_ctzll(~seen);
            return memo[mask] = value;
        };
        total ^= grundy(grundy, moves ? (1ULL << moves) - 1 : 0);
    }
    cout << (total ? "Yes" : "No");
    return 0;
}
```

### 复杂度

设初始动作数M（本范围小于64）、访问状态数Z，最坏 $O(ZM²)$，空间 $O(Z+M)$；连通分解通常显著减少Z。

### 易错点

压缩的是可放动作，状态转移必须删除所有重叠动作。空棋盘SG=0。精确记忆化最坏仍指数。

## Be the Winner

### 题意

每次删某堆连续苹果，可从中间分裂，取最后者输。

### 思路

长度a的一堆删连续段后剩两段b、c，b+c<a，故b xor c≤b+c<a；而只从一端删可达到0..a−1的任意值。因此普通规则单堆SG=a，新增分裂动作不会引入SG≥a的后继。

反常规则仍按反常Nim判定：若全为1，堆数偶数先手胜；否则总异或非0先手胜。证明必败大堆局面异或0时，分裂一堆将其SG从a改成严格更小的b xor c，不能保持异或0；又不可能一步进入错误的全1终局。其他局面用普通Nim的一端取法就能走到反常Nim必败态。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    int total = 0;
    bool allOne = true;
    for (int i = 0; i < n; i++) {
        int a;
        cin >> a;
        total ^= a;
        allOne = allOne && a == 1;
    }
    cout << ((allOne ? n % 2 == 0 : total != 0) ? "Yes" : "No");
    return 0;
}
```

### 复杂度

时间 $O(n)$，空间 $O(1)$。

### 易错点

最后取者输，全1时与普通Nim结论相反。允许中间删不等于能把任意两堆合并。

## A tree game

### 题意

剪去一边并丢掉不连根部分，多组判断胜者。

### 思路

根的各儿子分支互相独立，按Sprague–Grundy定理异或。一个分支是“父边接一棵子树”，绿树删边博弈的加根边规则使其SG为子树SG+1：剪掉父边可到0，其余动作对应子树内部删边，mex归纳得到加1。于是sg[u]=xor(sg[v]+1)，叶子为0，根SG非0则Alice胜。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct EulerTree {
    int n;
    vector<vector<int>> edge;
    vector<int> parent, depth, in, out, order;
    EulerTree(int n) : n(n), edge(n + 1), parent(n + 1), depth(n + 1), in(n + 1), out(n + 1) {}
    void add(int u, int v) {
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    void root(int start) {
        vector<int> stack = {start};
        parent[start] = 0;
        order.clear();
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            in[u] = order.size() + 1;
            order.push_back(u);
            for (int v : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack.push_back(v);
                }
        }
        vector<int> size(n + 1, 1);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            out[u] = in[u] + size[u] - 1;
            if (parent[u])
                size[parent[u]] += size[u];
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        cin >> n;
        EulerTree tree(n);
        for (int i = 1; i < n; i++) {
            int u, v;
            cin >> u >> v;
            tree.add(u, v);
        }
        tree.root(1);
        vector<int> sg(n + 1);
        for (int i = n - 1; i > 0; i--) {
            int u = tree.order[i];
            sg[tree.parent[u]] ^= sg[u] + 1;
        }
        cout << (sg[1] ? "Alice\n" : "Bob\n");
    }
    return 0;
}
```

### 复杂度

每组时间、空间均 $O(n)$。

### 易错点

独立分支先加1再异或，不能先把儿子SG异或后统一加1。没有边的单根树先手输。

## SA模板测试

### 题意

多组输出后缀字典序排名的起点和相邻LCP。

### 思路

后缀数组将全部后缀按字典序排序，height[i] 为相邻后缀 sa[i-1]、sa[i] 的最长公共前缀长度。参考代码采用倍增：已有长度 L 的排名后，用两个半段排名确定长度 2L 的排名，计数排序每轮线性；末尾补唯一最小符号零，把普通后缀排序转成循环移位排序。最后用 Kasai 方法在线性时间构造 height，每次从上一次公共长度减一处继续比较。所有实际字符和分隔符编码都大于零。

字符编码为1..26，调用后输出sa+1转换成原题一基位置，height首项已置0。倍增每轮只按已有排名做计数排序，不调用比较排序处理整条后缀。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SuffixArray {
    vector<int> sa, height;
    explicit SuffixArray(const vector<int> &data) {
        int size = data.size(), n = size + 1;
        vector<int> symbols = data;
        symbols.push_back(0);
        int alphabet = *max_element(symbols.begin(), symbols.end()) + 1;
        vector<int> order(n), rank(n), shifted(n), nextRank(n), count(max(n, alphabet), 0);
        for (int x : symbols)
            count[x]++;
        for (int x = 1; x < alphabet; x++)
            count[x] += count[x - 1];
        for (int i = n - 1; i >= 0; i--)
            order[--count[symbols[i]]] = i;
        int classes = 1;
        rank[order[0]] = 0;
        for (int i = 1; i < n; i++) {
            if (symbols[order[i]] != symbols[order[i - 1]])
                classes++;
            rank[order[i]] = classes - 1;
        }
        for (int length = 1; length < n && classes < n; length *= 2) {
            for (int i = 0; i < n; i++) {
                shifted[i] = order[i] - length;
                if (shifted[i] < 0)
                    shifted[i] += n;
            }
            fill(count.begin(), count.begin() + classes, 0);
            for (int x : shifted)
                count[rank[x]]++;
            for (int i = 1; i < classes; i++)
                count[i] += count[i - 1];
            for (int i = n - 1; i >= 0; i--)
                order[--count[rank[shifted[i]]]] = shifted[i];
            int nextClasses = 1;
            nextRank[order[0]] = 0;
            for (int i = 1; i < n; i++) {
                int a = order[i - 1], b = order[i];
                if (rank[a] != rank[b] || rank[(a + length) % n] != rank[(b + length) % n])
                    nextClasses++;
                nextRank[b] = nextClasses - 1;
            }
            rank.swap(nextRank);
            classes = nextClasses;
        }
        sa.assign(order.begin() + 1, order.end());
        for (int i = 0; i < size; i++)
            rank[sa[i]] = i;
        height.assign(size, 0);
        int common = 0;
        for (int i = 0; i < size; i++) {
            int position = rank[i];
            if (position == 0) {
                common = 0;
                continue;
            }
            int j = sa[position - 1];
            while (i + common < size && j + common < size && data[i + common] == data[j + common])
                common++;
            height[position] = common;
            if (common)
                common--;
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        string s;
        cin >> s;
        vector<int> data;
        for (char c : s)
            data.push_back(c - 'a' + 1);
        SuffixArray index(data);
        for (int i = 0; i < (int)s.size(); i++)
            cout << index.sa[i] + 1 << (i + 1 == (int)s.size() ? '\n' : ' ');
        for (int i = 0; i < (int)s.size(); i++)
            cout << index.height[i] << (i + 1 == (int)s.size() ? '\n' : ' ');
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

后缀排名从1输出，代码内部从0开始；height[0]=0，不与最后后缀循环比较。

## 本质不同子串个数

### 题意

统计本质不同的非空子串数。

### 思路

后缀自动机把结束位置集合相同的子串合并为一个状态。状态u代表的长度恰为(len[link[u]],len[u]]，这些子串出现次数相同。每加入一个字符，建立当前完整前缀的状态并令初始次数为1；必要时克隆旧状态，分离较短的结束位置类，克隆初始次数为0。按len降序把次数加到link，得到每个状态的真实出现次数；link长度严格减小，所以可以用计数排序得到传播顺序。

每个状态u贡献len[u]−len[link[u]]种不同子串，各状态之间结束位置集合不同，不会重复。累加所有非根状态即可。次数不影响本题答案，但模板仍包含正确的次数传播，便于理解同一类状态的用途。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SuffixAutomaton {
    struct Node {
        array<int, 26> next = {};
        int link = -1, length = 0, count = 0;
    };
    vector<Node> node;
    vector<int> prefix, order;
    int last = 0;
    explicit SuffixAutomaton(const string &s) {
        node.reserve(2 * s.size() + 1);
        node.emplace_back();
        prefix.reserve(s.size() + 1);
        prefix.push_back(0);
        for (char ch : s) {
            int c = ch - 'a', current = node.size();
            node.emplace_back();
            node[current].length = node[last].length + 1;
            node[current].count = 1;
            int p = last;
            while (p != -1 && !node[p].next[c]) {
                node[p].next[c] = current;
                p = node[p].link;
            }
            if (p == -1)
                node[current].link = 0;
            else {
                int q = node[p].next[c];
                if (node[p].length + 1 == node[q].length)
                    node[current].link = q;
                else {
                    int clone = node.size();
                    node.push_back(node[q]);
                    node[clone].length = node[p].length + 1;
                    node[clone].count = 0;
                    while (p != -1 && node[p].next[c] == q) {
                        node[p].next[c] = clone;
                        p = node[p].link;
                    }
                    node[q].link = node[current].link = clone;
                }
            }
            last = current;
            prefix.push_back(last);
        }
        vector<int> count(s.size() + 1);
        for (auto &v : node)
            count[v.length]++;
        for (size_t i = 1; i < count.size(); i++)
            count[i] += count[i - 1];
        order.resize(node.size());
        for (int u = (int)node.size() - 1; u >= 0; u--)
            order[--count[node[u].length]] = u;
        for (int i = (int)order.size() - 1; i > 0; i--) {
            int u = order[i];
            node[node[u].link].count += node[u].count;
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    cin >> s;
    SuffixAutomaton sam(s);
    long long answer = 0;
    for (int u = 1; u < (int)sam.node.size(); u++)
        answer += sam.node[u].length - sam.node[sam.node[u].link].length;
    cout << answer;
    return 0;
}
```

### 复杂度

固定字母表时间 $O(n)$，空间 $O(26n)$。

### 易错点

子串非空，根不贡献。不同位置出现的相同字符串只计算一次。

## 最长公共子串

### 题意

求两个长度各不超过五十万的小写字符串的最长公共子串长度。

### 思路

将两个串中间放一个未出现在字母表中的分隔符，拼成一个整数序列。建立后缀数组与相邻 LCP，扫描来源不同的相邻后缀，取其 LCP 最大值。若某个公共子串长度为 L，那么所有以它开头的后缀在后缀数组中连续，里面同时有两个源串的后缀，必存在一对来源不同的相邻后缀，LCP 至少为 L；所以只看相邻项已足够。分隔符后缀不参与答案。

后缀数组将全部后缀按字典序排序，height[i] 为相邻后缀 sa[i-1]、sa[i] 的最长公共前缀长度。参考代码采用倍增：已有长度 L 的排名后，用两个半段排名确定长度 2L 的排名，计数排序每轮线性；末尾补唯一最小符号零，把普通后缀排序转成循环移位排序。最后用 Kasai 方法在线性时间构造 height，每次从上一次公共长度减一处继续比较。所有实际字符和分隔符编码都大于零。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SuffixArray {
    vector<int> sa, height;
    explicit SuffixArray(const vector<int> &data) {
        int size = data.size(), n = size + 1;
        vector<int> symbols = data;
        symbols.push_back(0);
        int alphabet = *max_element(symbols.begin(), symbols.end()) + 1;
        vector<int> order(n), rank(n), shifted(n), nextRank(n), count(max(n, alphabet), 0);
        for (int x : symbols)
            count[x]++;
        for (int x = 1; x < alphabet; x++)
            count[x] += count[x - 1];
        for (int i = n - 1; i >= 0; i--)
            order[--count[symbols[i]]] = i;
        int classes = 1;
        rank[order[0]] = 0;
        for (int i = 1; i < n; i++) {
            if (symbols[order[i]] != symbols[order[i - 1]])
                classes++;
            rank[order[i]] = classes - 1;
        }
        for (int length = 1; length < n && classes < n; length *= 2) {
            for (int i = 0; i < n; i++) {
                shifted[i] = order[i] - length;
                if (shifted[i] < 0)
                    shifted[i] += n;
            }
            fill(count.begin(), count.begin() + classes, 0);
            for (int x : shifted)
                count[rank[x]]++;
            for (int i = 1; i < classes; i++)
                count[i] += count[i - 1];
            for (int i = n - 1; i >= 0; i--)
                order[--count[rank[shifted[i]]]] = shifted[i];
            int nextClasses = 1;
            nextRank[order[0]] = 0;
            for (int i = 1; i < n; i++) {
                int a = order[i - 1], b = order[i];
                if (rank[a] != rank[b] || rank[(a + length) % n] != rank[(b + length) % n])
                    nextClasses++;
                nextRank[b] = nextClasses - 1;
            }
            rank.swap(nextRank);
            classes = nextClasses;
        }
        sa.assign(order.begin() + 1, order.end());
        for (int i = 0; i < size; i++)
            rank[sa[i]] = i;
        height.assign(size, 0);
        int common = 0;
        for (int i = 0; i < size; i++) {
            int position = rank[i];
            if (position == 0) {
                common = 0;
                continue;
            }
            int j = sa[position - 1];
            while (i + common < size && j + common < size && data[i + common] == data[j + common])
                common++;
            height[position] = common;
            if (common)
                common--;
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s, t;
    cin >> s >> t;
    vector<int> data;
    data.reserve(s.size() + t.size() + 1);
    for (char c : s)
        data.push_back(c - 'a' + 2);
    int separator = data.size();
    data.push_back(1);
    for (char c : t)
        data.push_back(c - 'a' + 2);
    SuffixArray index(data);
    auto owner = [&](int p) { return p < separator ? 0 : p == separator ? -1 : 1; };
    int answer = 0;
    for (int i = 1; i < (int)index.sa.size(); i++) {
        int a = owner(index.sa[i - 1]), b = owner(index.sa[i]);
        if (a >= 0 && b >= 0 && a != b)
            answer = max(answer, index.height[i]);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

总长 $N=|s|+|t|+1$，时间 $O(N\log N)$，空间 $O(N)$。

### 易错点

求的是连续子串，不是最长公共子序列。分隔符必须不同于所有字符，防止公共前缀跨越两个源串。

## 本质不同公共子串个数

### 题意

求两串本质不同公共子串数量。

### 思路

后缀自动机把结束位置集合相同的子串合并为一个状态。状态u代表的长度恰为(len[link[u]],len[u]]，这些子串出现次数相同。每加入一个字符，建立当前完整前缀的状态并令初始次数为1；必要时克隆旧状态，分离较短的结束位置类，克隆初始次数为0。按len降序把次数加到link，得到每个状态的真实出现次数；link长度严格减小，所以可以用计数排序得到传播顺序。

对s建SAM，扫描t维护当前最长匹配后缀长度L和状态u；失配时沿link缩短，能转移后继续匹配，并记best[u]=max(best[u],L)。扫描后按len降序把best[u]传给link父亲，传递长度不能超过父亲len。

状态u原本代表(len[parent],len[u]]内的不同子串，如今t能匹配的最长长度为best[u]，所以公共贡献为max(0,min(best[u],len[u])−len[parent])。逐状态累加就不会重复统计。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SuffixAutomaton {
    struct Node {
        array<int, 26> next = {};
        int link = -1, length = 0, count = 0;
    };
    vector<Node> node;
    vector<int> prefix, order;
    int last = 0;
    explicit SuffixAutomaton(const string &s) {
        node.reserve(2 * s.size() + 1);
        node.emplace_back();
        prefix.reserve(s.size() + 1);
        prefix.push_back(0);
        for (char ch : s) {
            int c = ch - 'a', current = node.size();
            node.emplace_back();
            node[current].length = node[last].length + 1;
            node[current].count = 1;
            int p = last;
            while (p != -1 && !node[p].next[c]) {
                node[p].next[c] = current;
                p = node[p].link;
            }
            if (p == -1)
                node[current].link = 0;
            else {
                int q = node[p].next[c];
                if (node[p].length + 1 == node[q].length)
                    node[current].link = q;
                else {
                    int clone = node.size();
                    node.push_back(node[q]);
                    node[clone].length = node[p].length + 1;
                    node[clone].count = 0;
                    while (p != -1 && node[p].next[c] == q) {
                        node[p].next[c] = clone;
                        p = node[p].link;
                    }
                    node[q].link = node[current].link = clone;
                }
            }
            last = current;
            prefix.push_back(last);
        }
        vector<int> count(s.size() + 1);
        for (auto &v : node)
            count[v.length]++;
        for (size_t i = 1; i < count.size(); i++)
            count[i] += count[i - 1];
        order.resize(node.size());
        for (int u = (int)node.size() - 1; u >= 0; u--)
            order[--count[node[u].length]] = u;
        for (int i = (int)order.size() - 1; i > 0; i--) {
            int u = order[i];
            node[node[u].link].count += node[u].count;
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s, t;
    cin >> s >> t;
    SuffixAutomaton sam(s);
    vector<int> best(sam.node.size());
    int u = 0, length = 0;
    for (char ch : t) {
        int c = ch - 'a';
        while (u && !sam.node[u].next[c]) {
            u = sam.node[u].link;
            length = sam.node[u].length;
        }
        if (sam.node[u].next[c]) {
            u = sam.node[u].next[c];
            length++;
        } else {
            u = 0;
            length = 0;
        }
        best[u] = max(best[u], length);
    }
    for (int i = (int)sam.order.size() - 1; i > 0; i--) {
        int v = sam.order[i], p = sam.node[v].link;
        best[p] = max(best[p], min(best[v], sam.node[p].length));
    }
    long long answer = 0;
    for (int v = 1; v < (int)sam.node.size(); v++)
        answer += max(0, min(best[v], sam.node[v].length) - sam.node[sam.node[v].link].length);
    cout << answer;
    return 0;
}
```

### 复杂度

固定字母表时间 $O(|s|+|t|)$，空间 $O(26|s|+|t|)$。

### 易错点

这里只计不同字符串，不乘出现次数。向link传播时须截断为父状态长度。

## 【模板】后缀自动机 (SAM)

### 题意

重复子串的长度乘出现次数最大值。

### 思路

后缀自动机把结束位置集合相同的子串合并为一个状态。状态u代表的长度恰为(len[link[u]],len[u]]，这些子串出现次数相同。每加入一个字符，建立当前完整前缀的状态并令初始次数为1；必要时克隆旧状态，分离较短的结束位置类，克隆初始次数为0。按len降序把次数加到link，得到每个状态的真实出现次数；link长度严格减小，所以可以用计数排序得到传播顺序。

