            else {
                int q = node[p].next[c];
                if (node[p].length + 1 == node[q].length)
                    node[current].link = q;
                else {
                    int clone = node.size();
                    node.push_back(node[q]);
                    node[clone].length = node[p].length + 1;
                    node[clone].count = 0;
                    while (p != -1 && node[p].next[c] == q) {
                        node[p].next[c] = clone;
                        p = node[p].link;
                    }
                    node[q].link = node[current].link = clone;
                }
            }
            last = current;
            prefix.push_back(last);
        }
        vector<int> count(s.size() + 1);
        for (auto &v : node)
            count[v.length]++;
        for (size_t i = 1; i < count.size(); i++)
            count[i] += count[i - 1];
        order.resize(node.size());
        for (int u = (int)node.size() - 1; u >= 0; u--)
            order[--count[node[u].length]] = u;
        for (int i = (int)order.size() - 1; i > 0; i--) {
            int u = order[i];
            node[node[u].link].count += node[u].count;
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    long long p, q;
    cin >> s >> p >> q;
    int n = s.size();
    SuffixAutomaton sam(s);
    int size = sam.node.size(), levels = 1;
    while ((1LL << levels) <= size)
        levels++;
    vector<int> minimum(size, n + 1);
    for (int i = 1; i <= n; i++)
        minimum[sam.prefix[i]] = min(minimum[sam.prefix[i]], i);
    for (int i = (int)sam.order.size() - 1; i > 0; i--) {
        int u = sam.order[i];
        minimum[sam.node[u].link] = min(minimum[sam.node[u].link], minimum[u]);
    }
    vector<vector<int>> up(levels, vector<int>(size));
    for (int u = 1; u < size; u++)
        up[0][u] = sam.node[u].link;
    for (int b = 1; b < levels; b++)
        for (int u = 0; u < size; u++)
            up[b][u] = up[b - 1][up[b - 1][u]];
    vector<long long> dp(n + 1);
    for (int i = 1; i <= n; i++) {
        int u = sam.prefix[i];
        for (int b = levels - 1; b >= 0; b--) {
            int v = up[b][u];
            if (v && minimum[v] + sam.node[v].length > i)
                u = v;
        }
        int parent = sam.node[u].link,
            length = max(sam.node[parent].length, min(sam.node[u].length, i - minimum[u]));
        dp[i] = dp[i - 1] + p;
        if (length > 0)
            dp[i] = min(dp[i], dp[i - length] + q);
    }
    cout << dp[n];
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(26n+n\log n)$。

### 易错点

复制源必须完整位于此次粘贴之前，不允许一边粘贴一边借用新输出字符。用minEnd条件排除重叠。

## 多模式最长公共子串

### 题意

求同时是所有给定字符串子串的最长字符串长度。

### 思路

给每个源串分配不同的分隔符，将它们拼接后建立后缀数组与相邻 LCP。每个后缀标记其起点所属源串，分隔符位置记为无来源。在后缀数组上滑动窗口，维护每种来源出现次数；窗口包含全部源串时，这些后缀的公共前缀长度是 height[left+1..right] 的最小值，用递增单调队列求它。记录答案后移出左端继续缩短，直到缺少一种来源。

正确性来自字典序的连续性：任何公共子串都对应一整段以它为前缀的后缀，其中包含所有来源；反过来，某窗口里全部后缀的公共前缀也出现在所有来源中。对固定右端，缩短窗口不会降低 LCP 最小值，因此把可行窗口逐一缩短不会漏掉最优值。

后缀数组将全部后缀按字典序排序，height[i] 为相邻后缀 sa[i-1]、sa[i] 的最长公共前缀长度。参考代码采用倍增：已有长度 L 的排名后，用两个半段排名确定长度 2L 的排名，计数排序每轮线性；末尾补唯一最小符号零，把普通后缀排序转成循环移位排序。最后用 Kasai 方法在线性时间构造 height，每次从上一次公共长度减一处继续比较。所有实际字符和分隔符编码都大于零。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct SuffixArray {
    vector<int> sa, height;
    explicit SuffixArray(const vector<int> &data) {
        int size = data.size(), n = size + 1;
        vector<int> symbols = data;
        symbols.push_back(0);
        int alphabet = *max_element(symbols.begin(), symbols.end()) + 1;
        vector<int> order(n), rank(n), shifted(n), nextRank(n), count(max(n, alphabet), 0);
        for (int x : symbols)
            count[x]++;
        for (int x = 1; x < alphabet; x++)
            count[x] += count[x - 1];
        for (int i = n - 1; i >= 0; i--)
            order[--count[symbols[i]]] = i;
        int classes = 1;
        rank[order[0]] = 0;
        for (int i = 1; i < n; i++) {
            if (symbols[order[i]] != symbols[order[i - 1]])
                classes++;
            rank[order[i]] = classes - 1;
        }
        for (int length = 1; length < n && classes < n; length *= 2) {
            for (int i = 0; i < n; i++) {
                shifted[i] = order[i] - length;
                if (shifted[i] < 0)
                    shifted[i] += n;
            }
            fill(count.begin(), count.begin() + classes, 0);
            for (int x : shifted)
                count[rank[x]]++;
            for (int i = 1; i < classes; i++)
                count[i] += count[i - 1];
            for (int i = n - 1; i >= 0; i--)
                order[--count[rank[shifted[i]]]] = shifted[i];
            int nextClasses = 1;
            nextRank[order[0]] = 0;
            for (int i = 1; i < n; i++) {
                int a = order[i - 1], b = order[i];
                if (rank[a] != rank[b] || rank[(a + length) % n] != rank[(b + length) % n])
                    nextClasses++;
                nextRank[b] = nextClasses - 1;
            }
            rank.swap(nextRank);
            classes = nextClasses;
        }
        sa.assign(order.begin() + 1, order.end());
        for (int i = 0; i < size; i++)
            rank[sa[i]] = i;
        height.assign(size, 0);
        int common = 0;
        for (int i = 0; i < size; i++) {
            int position = rank[i];
            if (position == 0) {
                common = 0;
                continue;
            }
            int j = sa[position - 1];
            while (i + common < size && j + common < size && data[i + common] == data[j + common])
                common++;
            height[position] = common;
            if (common)
                common--;
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int sources;
    cin >> sources;
    vector<int> data, owner;
    data.reserve(1100000);
    owner.reserve(1100000);
    for (int id = 0; id < sources; id++) {
        string s;
        cin >> s;
        for (char c : s) {
            data.push_back(sources + 1 + c - 'a');
            owner.push_back(id);
        }
        data.push_back(id + 1);
        owner.push_back(-1);
    }
    SuffixArray index(data);
    vector<int> count(sources);
    deque<int> minimum;
    int left = 0, kinds = 0, answer = 0;
    for (int right = 0; right < (int)index.sa.size(); right++) {
        int id = owner[index.sa[right]];
        if (id >= 0 && count[id]++ == 0)
            kinds++;
        while (!minimum.empty() && index.height[minimum.back()] >= index.height[right])
            minimum.pop_back();
        minimum.push_back(right);
        while (kinds == sources) {
            while (!minimum.empty() && minimum.front() <= left)
                minimum.pop_front();
            if (!minimum.empty())
                answer = max(answer, index.height[minimum.front()]);
            int removed = owner[index.sa[left++]];
            if (removed >= 0 && --count[removed] == 0)
                kinds--;
        }
    }
    cout << answer;
    return 0;
}
```

### 复杂度

拼接总长 $N$，时间 $O(N\log N)$，空间 $O(N)$。

### 易错点

多个分隔符也必须彼此不同，避免公共前缀穿过串尾。队列保存的是 LCP 下标，窗口左端对应的 height[left] 在窗口之外，要删去。

## RC Kaboom Show

### 题意

各车可延迟启动但只沿固定射线前进，求最早能安排碰撞的时间。

### 思路

给定结束时间T，第i辆车能到达射线上从起点到p_i+v_i*T的整条线段；能安排碰撞当且仅当某两条这样的线段相交。若车提前到达交点，可把启动时刻延后，让两车同时到达。可行性对T单调，用二分。

相交判定用竖直扫描线：按线段左右端点排序，维护当前线段的上下顺序，插入时检查新出现的两对邻居，删除时检查被连成新邻居的一对。若真有相交，在首次相交前线段次序不会改变，相交双方一定会先成为邻居，因此不会漏判。比较器随扫描x变化，仅在尚未发现交点的前提下维护有序结构；检查的是整条线段是否相交，发现后立即结束。

两车检查直接由原始整数射线计算最早碰撞时间，避免用巨大T生成的端点做不稳定叉积。非平行时求唯一射线交点，并取两车到达时间最大值；同向共线时后车追到前车起点，反向相向时双方同时开动，背向则无解。上界10^13超过本题整数坐标、方向参数能产生的有限交会时间。

扫描线思路可对照[原比赛讲解](https://codeforces.com/blog/entry/78116)。下面代码独立实现射线到达时间与端点事件。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

struct Car {
    Point p, d, v;
    long double speed;
    long long x, y, dx, dy;
};
vector<Car> car;
vector<pair<Point, Point>> segment;
long double sweepX, duration;
long double height(int i) {
    auto [a, b] = segment[i];
    if (a.x > b.x)
        swap(a, b);
    long double x = clamp(sweepX, a.x, b.x);
    return a.y + (b.y - a.y) * (x - a.x) / (b.x - a.x);
}
struct Order {
    bool operator()(int a, int b) const {
        long double x = height(a), y = height(b);
        return x != y ? x < y : a < b;
    }
};
long double collision(int i, int j) {
    const auto &a = car[i];
    const auto &b = car[j];
    long long x = b.x - a.x, y = b.y - a.y, den = a.dx * b.dy - a.dy * b.dx;
    if (den) {
        long double u = (long double)(x * b.dy - y * b.dx) / den,
                    v = (long double)(x * a.dy - y * a.dx) / den;
        if (u < 0 || v < 0)
            return 1e100L;
        return max(u * norm(a.d) / a.speed, v * norm(b.d) / b.speed);
    }
    if (x * a.dy - y * a.dx)
        return 1e100L;
    long double z = dot(b.p - a.p, a.d) / norm(a.d);
    if (dot(a.d, b.d) > 0)
        return z >= 0 ? z / a.speed : -z / b.speed;
    return z >= 0 ? z / (a.speed + b.speed) : 1e100L;
}
bool canCrash(long double time) {
    duration = time;
    int n = car.size();
    segment.resize(n);
    struct Event {
        long double x;
        int kind, id;
    };
    vector<Event> event;
    for (int i = 0; i < n; i++) {
        Point a = car[i].p, b = a + car[i].v * time;
        if (a.x > b.x)
            swap(a, b);
        segment[i] = {a, b};
        event.push_back({a.x, 0, i});
        event.push_back({b.x, 1, i});
    }
    sort(event.begin(), event.end(),
         [](auto a, auto b) { return a.x != b.x ? a.x < b.x : a.kind < b.kind; });
    set<int, Order> active;
    vector<set<int, Order>::iterator> position(n);
    auto intersect = [&](int a, int b) { return collision(a, b) <= time; };
    for (auto e : event) {
        sweepX = e.x;
        if (e.kind == 0) {
            auto it = active.insert(e.id).first;
            position[e.id] = it;
            if (it != active.begin() && intersect(*prev(it), *it))
                return true;
            if (next(it) != active.end() && intersect(*it, *next(it)))
                return true;
        } else {
            auto it = position[e.id], right = next(it);
            if (it != active.begin() && right != active.end() && intersect(*prev(it), *right))
                return true;
            active.erase(it);
        }
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    car.resize(n);
    for (auto &a : car) {
        cin >> a.x >> a.y >> a.dx >> a.dy >> a.speed;
        a.p = {(long double)a.x, (long double)a.y};
        a.d = {(long double)a.dx, (long double)a.dy};
        a.v = a.d * (a.speed / norm(a.d));
    }
    long double l = 0, r = 1e13L;
    if (!canCrash(r)) {
        cout << "No show :(";
        return 0;
    }
    for (int i = 0; i < 75; i++) {
        long double mid = (l + r) / 2;
        if (canCrash(mid))
            r = mid;
        else
            l = mid;
    }
    cout << fixed << setprecision(15) << r;
    return 0;
}
```

### 复杂度

时间 $O(n\log n\log(C/\varepsilon))$，空间 $O(n)$。

### 易错点

速度si是长度/秒，应将方向向量归一化。不能要求两车从0时刻同时启动。起点互异，但共线射线仍需专门处理。

## Master Spark

### 题意

在矩形0≤x≤X、0≤y≤Y内，判断是否存在不落入任何闭条带C≤Ax+By≤D的点。

### 思路

本地原题正文漏掉了区域的数学定义，上述题意依据[原比赛题面](https://codeforces.com/gym/103447/problem/F)补全。条带包含边界，目标是严格避开全部条带。

若存在安全点，安全区域作为有限个闭条带的补集，具有一小块二维开区域。该区域边界必有一段来自矩形边或某条带边界的线段。于是枚举4条矩形边（向内侧移动）和每个条带两条边（向条带外侧移动），寻找某段边界，沿指定侧无限小移动后仍安全。

固定候选直线Ax+By=C，用x作参数（竖直线改用y），先截取矩形内的参数区间。其他非平行条带在线上覆盖一个闭区间，把这些区间求并；有正长度空隙，就可从空隙中点向指定侧移动。平行条带单独处理：若整条线在其内部，或恰在边界且指定移动方向进入该条带，候选整条作废；零宽条带不阻止向任一侧离开。若候选线在矩形边上，还要保证指定方向进入矩形。

交点参数全部保存为整数分子、正分母，用128位交叉相乘比较，因此即使安全区域很窄，也不会因浮点面积消失。仅有单点空隙不算安全段，区间端点相接时没有间隙。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

using Wide = __int128_t;
struct Fraction {
    long long a, b;
    Fraction(long long x = 0, long long y = 1) : a(x), b(y) {
        if (b < 0) {
            a = -a;
            b = -b;
        }
    }
    bool operator<(const Fraction &v) const { return (Wide)a * v.b < (Wide)v.a * b; }
    bool operator==(const Fraction &v) const { return (Wide)a * v.b == (Wide)v.a * b; }
};
struct Strip {
    long long a, b, c, d;
};
struct Boundary {
    long long a, b, c, sign;
};
bool uncovered(const Boundary &line, const vector<Strip> &strips, long long X, long long Y) {
    auto [a, b, c, sign] = line;
    Fraction low, high;
    if (b) {
        low = Fraction(0);
        high = Fraction(X);
        if (a) {
            Fraction x(c, a), y(c - b * Y, a);
            if (y < x)
                swap(x, y);
            low = max(low, x);
            high = min(high, y);
        } else {
            Fraction y(c, b);
            if (y < Fraction(0) || Fraction(Y) < y)
                return false;
        }
    } else {
        Fraction x(c, a);
        if (x < Fraction(0) || Fraction(X) < x)
            return false;
        low = Fraction(0);
        high = Fraction(Y);
    }
    if (!(low < high))
        return false;
    if (!b) {
        Fraction x(c, a);
        if ((x == Fraction(0) && sign * a < 0) || (x == Fraction(X) && sign * a > 0))
            return false;
    }
    if (!a) {
        Fraction y(c, b);
        if ((y == Fraction(0) && sign * b < 0) || (y == Fraction(Y) && sign * b > 0))
            return false;
    }
    vector<pair<Fraction, Fraction>> interval;
    long long norm = a * a + b * b;
    for (auto s : strips) {
        long long parallel = a * s.b - b * s.a;
        if (!parallel) {
            long long value = c * (a * s.a + b * s.b), lower = s.c * norm, upper = s.d * norm,
                      move = sign * (a * s.a + b * s.b);
            if (lower < value && value < upper)
                return false;
            if (s.c != s.d && ((value == lower && move > 0) || (value == upper && move < 0)))
                return false;
            continue;
        }
        Fraction l, r;
        if (b) {
            long long coefficient = s.a * b - s.b * a;
            l = Fraction(s.c * b - s.b * c, coefficient);
            r = Fraction(s.d * b - s.b * c, coefficient);
        } else {
            l = Fraction(s.c * a - s.a * c, s.b * a);
            r = Fraction(s.d * a - s.a * c, s.b * a);
        }
        if (r < l)
            swap(l, r);
        l = max(l, low);
        r = min(r, high);
        if (l < r)
            interval.push_back({l, r});
    }
    sort(interval.begin(), interval.end(),
         [](const auto &x, const auto &y) { return x.first < y.first; });
    Fraction reach = low;
    for (auto [l, r] : interval) {
        if (reach < l)
            return true;
        reach = max(reach, r);
    }
    return reach < high;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    string answer;
    while (tests--) {
        long long X, Y;
        int n;
        cin >> X >> Y >> n;
        vector<Strip> strips(n);
        vector<Boundary> boundary = {{1, 0, 0, 1}, {1, 0, X, -1}, {0, 1, 0, 1}, {0, 1, Y, -1}};
        for (auto &s : strips) {
            cin >> s.a >> s.b >> s.c >> s.d;
            boundary.push_back({s.a, s.b, s.c, -1});
            boundary.push_back({s.a, s.b, s.d, 1});
        }
        bool found = false;
        for (auto l : boundary)
            if (uncovered(l, strips, X, Y)) {
                found = true;
                break;
            }
        answer.push_back(found ? '1' : '0');
    }
    cout << answer;
    return 0;
}
```

### 复杂度

每组时间 $O(n^2\log n)$，空间 $O(n)$；各组n总和≤2000。

### 易错点

“只看矩形四个角”会漏掉内部安全洞。只对条带并面积做浮点比较，也可能把极窄安全区误判为全覆盖。参数区间与平行侧别均需精确处理。

## DongDong认亲戚

### 题意

按姓名合并亲戚关系并查询连通性，重名视为同一个人。

### 思路

先把不同姓名映射到整数编号，重复姓名复用原编号。亲戚关系满足传递性，因此每个家族是一个并查集集合；类型一合并，类型二比较根。按集合大小合并并压缩路径。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, size;
    DSU(int n) : parent(n + 1), size(n + 1, 1) { iota(parent.begin(), parent.end(), 0); }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    map<string, int> id;
    int count = 0;
    for (int i = 0; i < n; i++) {
        string name;
        cin >> name;
        if (!id.count(name))
            id[name] = ++count;
    }
    DSU dsu(count);
    while (m--) {
        int type;
        string a, b;
        cin >> type >> a >> b;
        if (type == 1)
            dsu.unite(id.at(a), id.at(b));
        else
            cout << (dsu.find(id.at(a)) == dsu.find(id.at(b))) << '\n';
    }
    return 0;
}
```

### 复杂度

映射使用平衡树，时间 $O((n+m)\log n)$，空间 $O(n)$。

### 易错点

两条相同姓名记录不能分配不同结点；查询不新增关系。

## [USACO 2016 Jan S]Angry Cows

### 题意

用最多 K 个半径相同的爆炸闭区间覆盖数轴上所有草捆，求最小整数半径。

### 思路

排序后，半径 R 的爆炸最多覆盖长度 2R 的区间。每次取最左未覆盖点 x，把爆炸中心放在 x+R，使覆盖右端尽量到 x+2R；跳过这段内所有点。任何覆盖 x 的爆炸都不可能比这更向右，因此该贪心使用最少牛。次数不超过 K 则 R 可行，二分最小值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<long long> x(n);
    for (auto &v : x)
        cin >> v;
    sort(x.begin(), x.end());
    auto possible = [&](long long radius) {
        int next = 0, used = 0;
        while (next < n) {
            if (++used > k)
                return false;
            long long right = x[next] + 2 * radius;
            while (next < n && x[next] <= right)
                next++;
        }
        return true;
    };
    long long low = 0, high = x.back() - x.front();
    while (low < high) {
        long long mid = (low + high) / 2;
        if (possible(mid))
            high = mid;
        else
            low = mid + 1;
    }
    cout << low;
    return 0;
}
```

### 复杂度

时间 $O(n\log n+n\log X)$，空间 $O(n)$，$X$ 是坐标跨度。

### 易错点

爆炸中心不必是草捆位置。覆盖总长度为直径 2R，不是半径 R；一个点或已有足够多牛时允许 R=0。

## Max Flow

### 题意

树上批量路径计数。

### 思路

每条点路径u→v对所有经过节点加1。设a=LCA(u,v)，差分标记diff[u]++、diff[v]++、diff[a]−−、diff[parent(a)]−−。逆序累加子树到父节点后，a以下两条链各得到1，a本身也得到1，a以上抵消为0。全部路径累加后取最大节点值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct EulerTree {
    int n;
    vector<vector<int>> edge;
    vector<int> parent, depth, in, out, order;
    EulerTree(int n) : n(n), edge(n + 1), parent(n + 1), depth(n + 1), in(n + 1), out(n + 1) {}
    void add(int u, int v) {
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    void root(int start) {
        vector<int> stack = {start};
        parent[start] = 0;
        order.clear();
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            in[u] = order.size() + 1;
            order.push_back(u);
            for (int v : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack.push_back(v);
                }
        }
        vector<int> size(n + 1, 1);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            out[u] = in[u] + size[u] - 1;
            if (parent[u])
                size[parent[u]] += size[u];
        }
    }
};

struct Ancestors {
    const EulerTree &tree;
    vector<vector<int>> up;
    Ancestors(const EulerTree &tree) : tree(tree) {
        int levels = 1;
        while ((1LL << levels) <= tree.n)
            levels++;
        up.assign(levels, vector<int>(tree.n + 1));
        up[0] = tree.parent;
        for (int b = 1; b < levels; b++)
            for (int u = 1; u <= tree.n; u++)
                up[b][u] = up[b - 1][up[b - 1][u]];
    }
    int lca(int u, int v) const {
        if (tree.depth[u] < tree.depth[v])
            swap(u, v);
        int gap = tree.depth[u] - tree.depth[v];
        for (int b = 0; b < (int)up.size(); b++)
            if (gap >> b & 1)
                u = up[b][u];
        if (u == v)
            return u;
        for (int b = (int)up.size() - 1; b >= 0; b--)
            if (up[b][u] != up[b][v]) {
                u = up[b][u];
                v = up[b][v];
            }
        return up[0][u];
    }
    int distance(int u, int v) const {
        return tree.depth[u] + tree.depth[v] - 2 * tree.depth[lca(u, v)];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    int k;
    cin >> n >> k;
    vector<int> visit;
    EulerTree tree(n);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        tree.add(u, v);
    }
    tree.root(1);
    Ancestors ancestor(tree);
    vector<long long> difference(n + 1);
    auto addPath = [&](int u, int v) {
        int a = ancestor.lca(u, v);
        difference[u]++;
        difference[v]++;
        difference[a]--;
        difference[tree.parent[a]]--;
    };
    while (k--) {
        int u, v;
        cin >> u >> v;
        addPath(u, v);
    }
    for (int i = n - 1; i > 0; i--) {
        int u = tree.order[i];
        difference[tree.parent[u]] += difference[u];
    }
    cout << *max_element(difference.begin() + 1, difference.end());
    return 0;
}
```

### 复杂度

时间 $O((n+q)\log n)$，空间 $O(n\log n)$。

### 易错点

这里统计点而非边，LCA本身必须保留一次；根的父亲用0哨兵，不向它继续累加。

## [USACO 2017 Jan P]Promotion Counting

### 题意

每个节点统计子树中能力严格更高的后代数。

### 思路

先用DFS序得到每个子树区间，然后按能力从高到低插入节点。处理u时，已插入的恰是能力更高者，查询其子树区间计数就是答案，随后把u插入。原题能力互不相同，因此无需同值分组。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct EulerTree {
    int n;
    vector<vector<int>> edge;
    vector<int> parent, depth, in, out, order;
    EulerTree(int n) : n(n), edge(n + 1), parent(n + 1), depth(n + 1), in(n + 1), out(n + 1) {}
    void add(int u, int v) {
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    void root(int start) {
        vector<int> stack = {start};
        parent[start] = 0;
        order.clear();
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            in[u] = order.size() + 1;
            order.push_back(u);
            for (int v : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack.push_back(v);
                }
        }
        vector<int> size(n + 1, 1);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            out[u] = in[u] + size[u] - 1;
            if (parent[u])
                size[parent[u]] += size[u];
        }
    }
};

struct Fenwick {
    int n;
    vector<long long> tree;
    Fenwick(int n) : n(n), tree(n + 1) {}
    void add(int p, long long v) {
        for (; p <= n; p += p & -p)
            tree[p] += v;
    }
    long long sum(int p) {
        long long result = 0;
        for (; p; p -= p & -p)
            result += tree[p];
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> power(n + 1);
    vector<int> order(n);
    for (int i = 1; i <= n; i++) {
        cin >> power[i];
        order[i - 1] = i;
    }
    EulerTree tree(n);
    for (int v = 2; v <= n; v++) {
        int p;
        cin >> p;
        tree.add(p, v);
    }
    tree.root(1);
    sort(order.begin(), order.end(), [&](int a, int b) { return power[a] > power[b]; });
    Fenwick bit(n);
    vector<int> answer(n + 1);
    for (int u : order) {
        answer[u] = bit.sum(tree.out[u]) - bit.sum(tree.in[u] - 1);
        bit.add(tree.in[u], 1);
    }
    for (int u = 1; u <= n; u++)
        cout << answer[u] << '\n';
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

先查询后插入，避免把自身算入后代。统计严格高于而非不低于。

## Greedy Gift Takers

### 题意

队首牛领取礼物后按固定插队数归队，求永远拿不到礼物的牛数。

### 思路

未拿过礼物的牛之间不能互相越过，因此能拿到的牛是原队列的一个前缀。令 d[i]=N-c[i]，表示领取后插回的一基位置。判断前 x 头是否已能形成永久阻塞：统计这 x 个 d 中，是否存在 j 使 d<=j 的牛至少有 j 头。若存在，这 j 头总能挡在后续未领取者前面：队首拿完后仍插在前 j 位，不会跑到目标牛后方。反之，第一头永远无法领取的牛最终会稳定在某个正位置 j，其前方的 j 头领取后都不越过它，所以恰有至少 j 个 d<=j。该条件充分且必要。

对前 x 头按 d 做频次数组，再扫前缀计数检查条件。它随 x 增加只会从假变真。二分第一个满足条件的 x，前 x 头都至少领取一次，之后 N-x 头永远不能领取。x=N 时总能满足，统一涵盖所有牛都拿得到的情况。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> position(n), frequency(n + 1);
    for (int &x : position) {
        cin >> x;
        x = n - x;
    }
    auto blocks = [&](int count) {
        fill(frequency.begin(), frequency.end(), 0);
        for (int i = 0; i < count; i++)
            frequency[position[i]]++;
        int prefix = 0;
        for (int j = 1; j <= n; j++) {
            prefix += frequency[j];
            if (prefix >= j)
                return true;
        }
        return false;
    };
    int low = 1, high = n;
    while (low < high) {
        int mid = (low + high) / 2;
        if (blocks(mid))
            high = mid;
        else
            low = mid + 1;
    }
    cout << n - low;
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

插回位置是 N-c[i]，不要混同为原始插队数。无限过程不能靠给一个任意模拟步数来断言永远领不到。

## [USACO 2015 Jan G]Moovie Mooving

### 题意

每部电影至多选一个场次，可中途进入退出，连续覆盖时间0到L，最少看几部。

### 思路

dp[mask]表示使用这些不同电影后，能从0连续覆盖到的最晚时刻，初始dp[0]=0，其余不可达。加入未选电影i时，在它的场次中二分找不晚于当前结束时刻的最晚开场；它结束也最晚。若该场仍在放映，就能接上，结束时刻扩展到开场+片长。

同一电影集合只保留最远结束是充分的：既然已经覆盖到更远处，任何能从较早结束继续并向外延伸的下一场，要么也能从更远处接上，要么早已落在已覆盖区间内，后者无助于继续向外覆盖。枚举所有达到L的mask，取置一位数最小。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, target;
    cin >> n >> target;
    vector<int> duration(n);
    vector<vector<int>> show(n);
    for (int i = 0; i < n; i++) {
        int count;
        cin >> duration[i] >> count;
        show[i].resize(count);
        for (int &x : show[i])
            cin >> x;
    }
    vector<int> dp(1 << n, -1);
    dp[0] = 0;
    int answer = n + 1;
    for (int mask = 0; mask < (1 << n); mask++)
        if (dp[mask] != -1) {
            int used = __builtin_popcount((unsigned)mask);
            if (dp[mask] >= target) {
                answer = min(answer, used);
                continue;
            }
            if (used >= answer)
                continue;
            for (int i = 0; i < n; i++)
                if (!(mask >> i & 1)) {
                    auto it = upper_bound(show[i].begin(), show[i].end(), dp[mask]);
                    if (it == show[i].begin())
                        continue;
                    int end = *prev(it) + duration[i];
                    if (end > dp[mask])
                        dp[mask | (1 << i)] = max(dp[mask | (1 << i)], end);
                }
        }
    cout << (answer == n + 1 ? -1 : answer);
    return 0;
}
```

### 复杂度

每电影最多 $C$ 场，时间 $O(n2^n\log C)$，空间 $O(2^n+\sum C_i)$。

### 易错点

必须从0开始无空档观看。可进入已经放映的场次，不要求开场恰好等于上一部结束时间；同一电影不能换场次重复使用。

## Directory Traversal

### 题意

选择起始文件夹，使访问全部文件的相对路径字符串长度总和最小。

### 思路

先从顶层向下，统计每个子树文件数count和从该目录出发访问其子树全部文件的路径长度。走进孩子目录v，会给其全部文件多加len(name[v])+1字符（含斜杠）；孩子是文件则只加文件名长度。根的初始总代价因此可自底向上求得。

把起始目录从u移到孩子目录v：v子树内每个文件都省去name[v]/，共减count[v]*(len[v]+1)；外部文件都要多走../，共加(总文件数−count[v])*3。这个换根式常数时间得到每个目录的全局代价，文件不能作为起始目录。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> children(n);
    vector<int> length(n);
    for (int u = 0; u < n; u++) {
        string name;
        int m;
        cin >> name >> m;
        length[u] = name.size();
        while (m--) {
            int v;
            cin >> v;
            children[u].push_back(v - 1);
        }
    }
    vector<int> order{0};
    for (size_t i = 0; i < order.size(); i++)
        for (int v : children[order[i]])
            order.push_back(v);
    vector<long long> files(n), inside(n), total(n);
    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];
        if (children[u].empty())
            files[u] = 1;
        else
            for (int v : children[u]) {
                files[u] += files[v];
                inside[u] += inside[v] + files[v] * (length[v] + !children[v].empty());
            }
    }
    total[0] = inside[0];
    long long answer = total[0];
    for (int u : order)
        if (!children[u].empty()) {
            answer = min(answer, total[u]);
            for (int v : children[u])
                if (!children[v].empty())
                    total[v] = total[u] - files[v] * (length[v] + 1) + (files[0] - files[v]) * 3;
        }
    cout << answer;
    return 0;
}
```

### 复杂度

时间、空间均为 $O(n)$。

### 易错点

根目录本身的名字不计入相对路径。文件名后没有斜杠，目录名后有；../固定3字符。总长度用64位。

## Overplanting (Silver)

### 题意

求有重叠轴平行矩形的并面积。

### 思路

按x扫描左右边界，每次对y区间覆盖次数加1或减1。将y端点离散化，树叶代表相邻端点之间的真实长度；节点覆盖次数>0时全段覆盖，否则覆盖长度由子节点相加。前后事件之间覆盖总长不变，面积增加x差乘根节点覆盖长度。输入上下角坐标先统一为升序。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct CoverTree {
    vector<long long> coordinate, length;
    vector<int> count;
    CoverTree(vector<long long> x)
        : coordinate(move(x)), length(coordinate.size() * 4 + 4), count(length.size()) {}
    void change(int u, int l, int r, int ql, int qr, int delta) {
        if (ql <= l && r <= qr)
            count[u] += delta;
        else {
            int mid = (l + r) / 2;
            if (ql <= mid)
                change(u * 2, l, mid, ql, qr, delta);
            if (qr > mid)
                change(u * 2 + 1, mid + 1, r, ql, qr, delta);
        }
        if (count[u])
            length[u] = coordinate[r + 1] - coordinate[l];
        else
            length[u] = l == r ? 0 : length[u * 2] + length[u * 2 + 1];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    struct Event {
        long long x, low, high;
        int delta;
    };
    vector<Event> event;
    vector<long long> y;
    for (int i = 0; i < n; i++) {
        long long x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        if (x1 > x2)
            swap(x1, x2);
        if (y1 > y2)
            swap(y1, y2);
        if (x1 == x2 || y1 == y2)
            continue;
        event.push_back({x1, y1, y2, 1});
        event.push_back({x2, y1, y2, -1});
        y.push_back(y1);
        y.push_back(y2);
    }
    if (event.empty()) {
        cout << 0;
        return 0;
    }
    sort(y.begin(), y.end());
    y.erase(unique(y.begin(), y.end()), y.end());
    sort(event.begin(), event.end(), [](auto a, auto b) { return a.x < b.x; });
    CoverTree tree(y);
    long long area = 0, previous = event[0].x;
    for (auto e : event) {
        area += (e.x - previous) * tree.length[1];
        previous = e.x;
        int l = lower_bound(y.begin(), y.end(), e.low) - y.begin();
        int r = lower_bound(y.begin(), y.end(), e.high) - y.begin() - 1;
        tree.change(1, 0, (int)y.size() - 2, l, r, e.delta);
    }
    cout << area;
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

离散下标距离不是几何长度，长度必须用原坐标相减。区间按半开[y1,y2)维护，对应叶下标到rank(y2)−1。

## Problem of Apollonius

### 题意

构造经过给定点且与两个已知圆外切的全部圆。

### 思路

以给定点P为反演中心，反演半径取1。将P平移到原点，已知圆(c,r)变成(c/(|c|²−r²), r/(|c|²−r²))。未知圆经过原点，反演后变成一条直线；原先与两个圆外切，等价于这条线是两反演圆的公外切线，且原点与两圆位于线的同一侧。

把切线写成单位法向量n·x=d，两圆在线的≤侧，则n·(c1−c2)=r2−r1。设e为两圆心连线单位向量，t=(r2−r1)/|c1−c2|，两个候选法向量是t*e±sqrt(1−t²)*rotate90(e)。d=n·c1+r1，只有d>0满足原点在线的同侧。反演回去得到圆心n/(2d)、半径1/(2d)，再平移P。

本题允许任意答案顺序，验证同时检查解数、过点以及与两圆的外切等式。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        Point a, b, p;
        long double r, s;
        cin >> a.x >> a.y >> r >> b.x >> b.y >> s >> p.x >> p.y;
        a = a - p;
        b = b - p;
        long double da = dot(a, a) - r * r, db = dot(b, b) - s * s;
        a = a / da;
        r /= da;
        b = b / db;
        s /= db;
        Point e = a - b;
        long double length = norm(e), t = (s - r) / length;
        vector<array<long double, 3>> answer;
        if (fabsl(t) <= 1 + EPS) {
            e = e / length;
            long double h = sqrtl(max(0.0L, 1 - t * t));
            for (int sign : {-1, 1}) {
                Point normal = e * t + rotate90(e) * (sign * h);
                long double d = dot(normal, a) + r;
                if (d <= 1e-18L)
                    continue;
                Point center = p + normal / (2 * d);
                long double radius = 1 / (2 * d);
                if (!answer.empty() && distance(center, {answer[0][0], answer[0][1]}) < 1e-10L)
                    continue;
                answer.push_back({center.x, center.y, radius});
            }
        }
        cout << answer.size() << '\n';
        for (auto q : answer)
            cout << fixed << setprecision(12) << q[0] << ' ' << q[1] << ' ' << q[2] << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间与空间均为 $O(1)$。

### 易错点

反演中心严格在两个已知圆外，两个分母均为正。只解公切线还不够，必须检查d>0，否则反演得到的圆会包住已知圆。

## The Designer

### 题意

两个内切圆之间按图示顺序填圆，求前N个小圆面积之和。

### 思路

先令大半径R、小半径r，d=R−r。第一个填圆半径为d，之后上、下两侧对称地各形成一条相切圆链。固定两个大圆的带符号曲率为−1/R、1/r；由Descartes定理，圆链曲率的二阶差分为$2(1/r-1/R)$，对称性给出$q_k=1/d+k^2d/(Rr)$，半径$\rho_k=dRr/(Rr+k^2d^2)$。

顺序是k=0一个，k=1两个，k=2两个……因此成对计入前floor((N−1)/2)层；若N为偶数，还需加下一层的一个。N可达10^7，不能对所有层逐个求和。当k>K时有$\rho_k\le A/k^2$，其中$A=Rr/d\le9900$，两条链剩余总面积不超过$2\pi A^2/(3K^3)$。取K=30000，此界小于$8\times10^{-6}$，严格低于允许的$10^{-4}$。所以只算到该层即可，舍弃有明确误差界的尾项。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    const long double pi = acosl(-1.0L);
    while (tests--) {
        long double R, r;
        long long n;
        cin >> R >> r >> n;
        if (R < r)
            swap(R, r);
        long double d = R - r;
        if (d == 0) {
            cout << "0.000000000000\n";
            continue;
        }
        auto radius = [&](long long k) { return d * R * r / (R * r + (long double)k * k * d * d); };
        long long pairs = (n - 1) / 2;
        long double answer = pi * d * d;
        for (int k = 1; k <= min(30000LL, pairs); k++) {
            long double value = radius(k);
            answer += 2 * pi * value * value;
        }
        if (n % 2 == 0 && n / 2 <= 30000) {
            long double value = radius(n / 2);
            answer += pi * value * value;
        }
        cout << fixed << setprecision(12) << answer << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间 $O(\min(N,30000))$，额外空间 $O(1)$。

### 易错点

R1、R2大小顺序没有保证，应先交换。圆2和圆3半径相等，不能按同一侧链把每个编号都当成新层。截断由尾项积分界保证精度。

## Finding the Radius for an Inserted Circl

### 题意

三个等半径外切圆之间不断插入小圆，求第k个半径整数部分。

### 思路

以大圆曲率1/R为单位，两个固定圆的曲率均为1，尚未插圆时第三个大圆也是1。Descartes定理的两个解满足新旧曲率和为两倍其余三个圆曲率和，因此相邻插入圆的曲率满足$q_k=4+2q_{k-1}-q_{k-2}$。首项$q_0=1$、$q_1=3+2\sqrt3$，解得$q_k=2k^2+2\sqrt3k+1$，所以$R_k=R/q_k$。k最多10，直接代入并向下取整。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    long double R;
    cin >> tests >> R;
    while (tests--) {
        int k;
        cin >> k;
        long double curvature = 2.0L * k * k + 2 * sqrtl(3.0L) * k + 1;
        cout << k << ' ' << (long long)floorl(R / curvature) << '\n';
    }
    return 0;
}
```

### 复杂度

时间与额外空间均为 $O(1)$。

### 易错点

这里输出整数部分，不是四舍五入。输入末尾−1是结束标志，不属于T个询问。π并不参与相切圆半径公式。

## [USACO 2012 Mar S]Flowerpot

### 题意

选最窄的水平花盆区间，使接到的雨滴最高与最低落地时间差至少 D。

### 思路

落地速度为一，时间差就是窗口内 y 的最大值减最小值。按 x 排序后，维护窗口的最大 y、最小 y 两条单调队列。每次扩张右端，只要高度差已至少 D，就记录 x[right]-x[left] 并移出左端，继续尝试更窄区间；不再满足时再扩张右端。两队列各自按下标移除过期项。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, d;
    cin >> n >> d;
    vector<pair<int, int>> drops(n);
    for (auto &[x, y] : drops)
        cin >> x >> y;
    sort(drops.begin(), drops.end());
    deque<int> maximum, minimum;
    int left = 0, answer = INT_MAX;
    for (int right = 0; right < n; right++) {
        while (!maximum.empty() && drops[maximum.back()].second <= drops[right].second)
            maximum.pop_back();
        while (!minimum.empty() && drops[minimum.back()].second >= drops[right].second)
            minimum.pop_back();
        maximum.push_back(right);
        minimum.push_back(right);
        while (!maximum.empty() &&
               drops[maximum.front()].second - drops[minimum.front()].second >= d) {
            answer = min(answer, drops[right].first - drops[left].first);
            if (maximum.front() == left)
                maximum.pop_front();
            if (minimum.front() == left)
                minimum.pop_front();
            left++;
        }
    }
    cout << (answer == INT_MAX ? -1 : answer);
    return 0;
}
```

### 复杂度

排序 $O(n\log n)$，滑动窗口 $O(n)$，空间 $O(n)$。

### 易错点

雨滴落在盆边也算命中，所以宽度就是端点坐标之差，不加一。同一 x 可有不同高度的雨滴，最小宽度可能为零。

## Milk Routing

### 题意

路径耗时为延迟和加X除以最小容量，求最小耗时向下取整。

### 思路

最优路径的瓶颈容量一定等于某条边容量。枚举容量下限c，只用容量≥c的边，Dijkstra求最小延迟L，再用L+floor(X/c)更新答案。若实际路径容量更大，本轮估计只会偏大；而枚举到其真实瓶颈时会得到不差于最优路径的延迟，因此最终恰为最优。所有候选的向下取整可先做再取最小，无需浮点。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    long long milk;
    cin >> n >> m >> milk;
    struct Edge {
        int to, latency, capacity;
    };
    vector<vector<Edge>> graph(n);
    vector<int> capacities;
    while (m--) {
        int a, b, l, c;
        cin >> a >> b >> l >> c;
        --a;
        --b;
        graph[a].push_back({b, l, c});
        graph[b].push_back({a, l, c});
        capacities.push_back(c);
    }
    if (n == 1) {
        cout << 0;
        return 0;
    }
    sort(capacities.begin(), capacities.end());
    capacities.erase(unique(capacities.begin(), capacities.end()), capacities.end());
    const long long inf = 1LL << 60;
    long long answer = inf;
    for (int threshold : capacities) {
        vector<long long> distance(n, inf);
        priority_queue<pair<long long, int>, vector<pair<long long, int>>,
                       greater<pair<long long, int>>>
            heap;
        distance[0] = 0;
        heap.push({0, 0});
        while (!heap.empty()) {
            auto [cost, u] = heap.top();
            heap.pop();
            if (cost != distance[u])
                continue;
            if (u == n - 1)
                break;
            for (auto e : graph[u])
                if (e.capacity >= threshold && distance[e.to] > cost + e.latency) {
                    distance[e.to] = cost + e.latency;
                    heap.push({distance[e.to], e.to});
                }
        }
        if (distance[n - 1] != inf)
            answer = min(answer, distance[n - 1] + milk / threshold);
    }
    cout << (answer == inf ? -1 : answer);
    return 0;
}
```

### 复杂度

不同容量数 $K\le M$，时间 $O(K(N+M)\log N)$，空间 $O(N+M)$。

### 易错点

不能只求一次最短延迟后再算容量；更长延迟可能换来更大容量。原题输出向下取整，不四舍五入。

## 2D Geometry 110 in 1!

### 题意

处理六种圆相关构造命令，严格按列表与元组格式输出。

### 思路

把六个命令统一成“圆心在哪里”的交点问题。外接圆：解到三个顶点等距的两条线性方程；内切圆：三个顶点按对边长度加权，半径=二倍面积/周长。

过点切线：点在圆内无解，在圆上一条切线，在圆外两条，方向角为圆心到点方向±asin(r/d)，按无向直线归一到[0,180)。

过点且与直线相切、半径固定：圆心在过该点的半径r圆上，同时在给定直线两侧各平移r的直线上，求圆线交点。与两条不平行直线相切：分别平移±r，两两相交得到4个圆心。与两不相交圆外切：圆心到两已知圆心的距离分别为r+r1、r+r2，求两圆交点。

将几何计算与输出分开：点列表按x、y排序并去重，切线角排序并去重，统一4位小数，不添加空格，消除−0.0000。相切时只输出一个交点。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

struct Circle {
    Point center;
    long double radius = -1;
};
bool contains(Circle c, Point p) { return distance(c.center, p) <= c.radius + 1e-12L; }
Circle diameter(Point a, Point b) {
    Point c = (a + b) / 2;
    return {c, distance(a, b) / 2};
}
Circle throughThree(Point a, Point b, Point c) {
    Point u = b - a, v = c - a;
    long double den = 2 * cross(u, v);
    if (fabsl(den) < 1e-24L) {
        Circle best = {{}, numeric_limits<long double>::infinity()};
        for (auto d : {diameter(a, b), diameter(a, c), diameter(b, c)})
            if (contains(d, a) && contains(d, b) && contains(d, c) && d.radius < best.radius)
                best = d;
        return best;
    }
    Point offset = {(dot(u, u) * v.y - dot(v, v) * u.y) / den,
                    (u.x * dot(v, v) - v.x * dot(u, u)) / den};
    Point center = a + offset;
    return {center, distance(center, a)};
}

vector<Point> circleIntersections(Point a, long double r, Point b, long double s) {
    Point e = b - a;
    long double d = norm(e);
    if (d < EPS || d > r + s + EPS || d < fabsl(r - s) - EPS)
        return {};
    long double x = (r * r - s * s + d * d) / (2 * d), h2 = r * r - x * x;
    if (h2 < -EPS)
        return {};
    Point center = a + e * (x / d), offset = rotate90(e) * (sqrtl(max(0.0L, h2)) / d);
    if (norm(offset) < EPS)
        return {center};
    return {center + offset, center - offset};
}

Point lineIntersection(Point a, Point u, Point b, Point v) {
    return a + u * (cross(b - a, v) / cross(u, v));
}
vector<Point> lineCircle(Point a, Point d, Point center, long double radius) {
    Point projection = a + d * (dot(center - a, d) / dot(d, d));
    long double h2 = radius * radius - dot(projection - center, projection - center);
    if (h2 < -1e-9L)
        return {};
    if (fabsl(h2) < 1e-14L * max(1.0L, radius * radius))
        h2 = 0;
    Point offset = d * (sqrtl(max(0.0L, h2)) / norm(d));
    if (norm(offset) < 1e-10L)
        return {projection};
    return {projection - offset, projection + offset};
}
long double clean(long double x) { return fabsl(x) < 0.000049999L ? 0 : x; }
void pointOutput(Point p) { cout << '(' << clean(p.x) << ',' << clean(p.y) << ')'; }
void pointsOutput(vector<Point> points) {
    sort(points.begin(), points.end(),
         [](Point a, Point b) { return fabsl(a.x - b.x) > 1e-9L ? a.x < b.x : a.y < b.y; });
    points.erase(unique(points.begin(), points.end(),
                        [](Point a, Point b) { return distance(a, b) < 1e-9L; }),
                 points.end());
    cout << '[';
    for (int i = 0; i < (int)points.size(); i++) {
        if (i)
            cout << ',';
        pointOutput(points[i]);
    }
    cout << "]\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string command;
    cout << fixed << setprecision(4);
    const long double pi = acosl(-1.0L);
    while (cin >> command) {
        if (command == "CircumscribedCircle" || command == "InscribedCircle") {
            Point a, b, c;
            cin >> a.x >> a.y >> b.x >> b.y >> c.x >> c.y;
            Circle result;
            if (command == "CircumscribedCircle")
                result = throughThree(a, b, c);
            else {
                long double x = distance(b, c), y = distance(a, c), z = distance(a, b),
                            sum = x + y + z;
                result = {(a * x + b * y + c * z) / sum, fabsl(cross(b - a, c - a)) / sum};
            }
            cout << '(' << clean(result.center.x) << ',' << clean(result.center.y) << ','
                 << clean(result.radius) << ")\n";
        } else if (command == "TangentLineThroughPoint") {
            Point c, p;
            long double r;
            cin >> c.x >> c.y >> r >> p.x >> p.y;
            Point d = p - c;
            long double length = norm(d);
            vector<long double> angle;
            if (length >= r - 1e-10L) {
                long double base = atan2l(d.y, d.x), delta = asinl(clamp(r / length, -1.0L, 1.0L));
                for (long double a : {base - delta, base + delta}) {
                    a = fmodl(a, pi);
                    if (a < 0)
                        a += pi;
                    if (a > pi - 1e-12L)
                        a = 0;
                    angle.push_back(a * 180 / pi);
                }
                sort(angle.begin(), angle.end());
                angle.erase(unique(angle.begin(), angle.end(),
                                   [](auto a, auto b) { return fabsl(a - b) < 1e-8L; }),
                            angle.end());
            }
            cout << '[';
            for (int i = 0; i < (int)angle.size(); i++) {
                if (i)
                    cout << ',';
                cout << clean(angle[i]);
            }
            cout << "]\n";
        } else if (command == "CircleThroughAPointAndTangentToALineWithRadius") {
            Point p, a, b;
            long double r;
            cin >> p.x >> p.y >> a.x >> a.y >> b.x >> b.y >> r;
            Point d = b - a, n = rotate90(d) * (r / norm(d));
            vector<Point> answer;
            for (int sign : {-1, 1}) {
                auto points = lineCircle(a + n * sign, d, p, r);
                answer.insert(answer.end(), points.begin(), points.end());
            }
            pointsOutput(answer);
        } else if (command == "CircleTangentToTwoLinesWithRadius") {
            Point a, b, c, d;
            long double r;
            cin >> a.x >> a.y >> b.x >> b.y >> c.x >> c.y >> d.x >> d.y >> r;
            Point u = b - a, v = d - c, n = rotate90(u) * (r / norm(u)),
                  m = rotate90(v) * (r / norm(v));
            vector<Point> answer;
            for (int x : {-1, 1})
                for (int y : {-1, 1})
                    answer.push_back(lineIntersection(a + n * x, u, c + m * y, v));
            pointsOutput(answer);
        } else {
            Point a, b;
            long double r, s, t;
            cin >> a.x >> a.y >> r >> b.x >> b.y >> s >> t;
            pointsOutput(circleIntersections(a, r + t, b, s + t));
        }
    }
    return 0;
}
```

### 复杂度

每条命令时间、额外空间均为 $O(1)$。

### 易错点

这版要求4位小数，原UVA题的6位不能照搬。圆心列表只输出(x,y)，前两个三角形命令输出(x,y,r)。切线角是无向直线角，180度要归零。

## [Violet]天使玩偶/SJY摆棋子

### 题意

在线序列只有插入点与查询最近曼哈顿距离，离线求每次答案。

### 思路

先只考虑候选点$(x,y)$在询问$(X,Y)$左下方，即$x\le X,y\le Y$，距离是$X+Y-(x+y)$。按时间做CDQ，左半插入只能影响右半询问；左右按x归并扫描，用y上的树状数组维护左半插入的最大x+y，右半询问查y前缀即可。这样同时满足时间、x、y三维约束。

分别将所有坐标乘上(+,+)、(+,-)、(-,+)、(-,-)四种符号，每次都求左下方候选，最后取四个方向距离最小。初始点作为早于所有操作的插入事件。CDQ递归返回时数组按x排序，但所属时间区间始终由归并前的划分固定。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Event {
    long long x, y;
    int kind, id, rank;
};
vector<Event> event, buffer;
vector<long long> bit, answer;
const long long NEG = -(1LL << 60);
void add(int p, long long value) {
    for (; p < (int)bit.size(); p += p & -p)
        bit[p] = max(bit[p], value);
}
long long maximum(int p) {
    long long value = NEG;
    for (; p; p -= p & -p)
        value = max(value, bit[p]);
    return value;
}
void cdq(int l, int r) {
    if (r - l <= 1)
        return;
    int mid = (l + r) / 2;
    cdq(l, mid);
    cdq(mid, r);
    int i = l;
    for (int j = mid; j < r; j++) {
        while (i < mid && event[i].x <= event[j].x) {
            if (event[i].kind == 1)
                add(event[i].rank, event[i].x + event[i].y);
            i++;
        }
        if (event[j].kind == 2) {
            long long best = maximum(event[j].rank);
            if (best != NEG)
                answer[event[j].id] = min(answer[event[j].id], event[j].x + event[j].y - best);
        }
    }
    for (int j = l; j < i; j++)
        if (event[j].kind == 1)
            for (int p = event[j].rank; p < (int)bit.size(); p += p & -p)
                bit[p] = NEG;
    merge(event.begin() + l, event.begin() + mid, event.begin() + mid, event.begin() + r,
          buffer.begin() + l, [](const Event &a, const Event &b) { return a.x < b.x; });
    copy(buffer.begin() + l, buffer.begin() + r, event.begin() + l);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<Event> base;
    for (int i = 0; i < n; i++) {
        long long x, y;
        cin >> x >> y;
        base.push_back({x, y, 1, -1, 0});
    }
    int queries = 0;
    for (int i = 0; i < m; i++) {
        int kind;
        long long x, y;
        cin >> kind >> x >> y;
        base.push_back({x, y, kind, kind == 2 ? queries++ : -1, 0});
    }
    answer.assign(queries, LLONG_MAX);
    for (int sx : {-1, 1})
        for (int sy : {-1, 1}) {
            event = base;
            vector<long long> coordinate;
            for (auto &q : event) {
                q.x *= sx;
                q.y *= sy;
                coordinate.push_back(q.y);
            }
            sort(coordinate.begin(), coordinate.end());
            coordinate.erase(unique(coordinate.begin(), coordinate.end()), coordinate.end());
            for (auto &q : event)
                q.rank =
                    lower_bound(coordinate.begin(), coordinate.end(), q.y) - coordinate.begin() + 1;
            bit.assign(coordinate.size() + 1, NEG);
            buffer.resize(event.size());
            cdq(0, event.size());
        }
    for (auto value : answer)
        cout << value << '\n';
    return 0;
}
```

### 复杂度

时间 $O((n+m)\log^2(n+m))$，空间 $O(n+m)$。

### 易错点

树状数组维护最大值不能用减法回滚；每次归并完成后，将本轮更新经过的节点恢复负无穷。各递归层不同时保留树状数组状态，所以清空有效。

## 【模板】三维偏序（陌上花开）

### 题意

统计每个点被多少其他点三维同时不大于，并输出频数分布。

### 思路

先按(a,b,c)字典序排序，把完全相同的点合成一个带count的点。CDQ按此顺序分左右，左组a不会大于右组；递归后两组各按b排序，扫右点时把所有左组b≤当前b的count加入c上的树状数组，查c前缀即跨组贡献。回滚本轮加入后，按b归并。一个合并点最终答案=跨组smaller+自身count−1，频数桶增加count。

相同a也可计入：字典序下，若两个不同合并点可互相满足偏序，必然b、c也相同，早已被合并；否则只有排在前面的点可能支配后面的点。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Node {
    int a, b, c, count;
    long long smaller = 0;
};
vector<Node> node, buffer;
vector<int> bit;
void update(int p, int value) {
    for (; p < (int)bit.size(); p += p & -p)
        bit[p] += value;
}
int query(int p) {
    int sum = 0;
    for (; p; p -= p & -p)
        sum += bit[p];
    return sum;
}
void solve(int l, int r) {
    if (r - l <= 1)
        return;
    int mid = (l + r) / 2;
    solve(l, mid);
    solve(mid, r);
    int i = l;
    for (int j = mid; j < r; j++) {
        while (i < mid && node[i].b <= node[j].b) {
            update(node[i].c, node[i].count);
            i++;
        }
        node[j].smaller += query(node[j].c);
    }
    for (int j = l; j < i; j++)
        update(node[j].c, -node[j].count);
    merge(node.begin() + l, node.begin() + mid, node.begin() + mid, node.begin() + r,
          buffer.begin() + l, [](const auto &a, const auto &b) { return a.b < b.b; });
    copy(buffer.begin() + l, buffer.begin() + r, node.begin() + l);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<array<int, 3>> p(n);
    for (auto &q : p)
        cin >> q[0] >> q[1] >> q[2];
    sort(p.begin(), p.end());
    for (auto q : p) {
        if (!node.empty() && node.back().a == q[0] && node.back().b == q[1] &&
            node.back().c == q[2])
            node.back().count++;
        else
            node.push_back({q[0], q[1], q[2], 1, 0});
    }
    buffer.resize(node.size());
    bit.resize(k + 1);
    solve(0, node.size());
    vector<int> answer(n);
    for (auto q : node)
        answer[q.smaller + q.count - 1] += q.count;
    for (int x : answer)
        cout << x << '\n';
    return 0;
}
```

### 复杂度

时间 $O(n\log n\log k)$，空间 $O(n+k)$。

### 易错点

≤条件含等号，扫b时不能写成<。必须合并完全重复三元组，不然同组重复点的贡献会随输入顺序丢失。

## 最小圆覆盖

### 题意

求实数点集的最小覆盖圆及圆心。

### 思路

随机打乱点。依次加入第i点：若已在圆内，当前最优圆无需变化；否则新圆必经过它，先设为半径0的圆。重扫此前点j，若j在圆外，则固定i、j为边界，设为两点直径圆；再重扫k，若k仍在圆外，用i、j、k的外接圆更新。三重循环是边界点逐层固定，不是枚举全部三元组；随机顺序下期望线性。三点共线时取能包含三点的最远点对直径圆。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

constexpr long double EPS = 1e-12L;
struct Point {
    long double x = 0, y = 0;
    Point operator+(Point b) const { return {x + b.x, y + b.y}; }
    Point operator-(Point b) const { return {x - b.x, y - b.y}; }
    Point operator*(long double t) const { return {x * t, y * t}; }
    Point operator/(long double t) const { return {x / t, y / t}; }
};
long double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
long double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
long double norm(Point a) { return sqrtl(dot(a, a)); }
long double distance(Point a, Point b) { return norm(a - b); }
Point rotate90(Point a) { return {-a.y, a.x}; }

struct Circle {
    Point center;
    long double radius = -1;
};
bool contains(Circle c, Point p) { return distance(c.center, p) <= c.radius + 1e-12L; }
Circle diameter(Point a, Point b) {
    Point c = (a + b) / 2;
    return {c, distance(a, b) / 2};
}
Circle throughThree(Point a, Point b, Point c) {
    Point u = b - a, v = c - a;
    long double den = 2 * cross(u, v);
    if (fabsl(den) < 1e-24L) {
        Circle best = {{}, numeric_limits<long double>::infinity()};
        for (auto d : {diameter(a, b), diameter(a, c), diameter(b, c)})
            if (contains(d, a) && contains(d, b) && contains(d, c) && d.radius < best.radius)
                best = d;
        return best;
    }
    Point offset = {(dot(u, u) * v.y - dot(v, v) * u.y) / den,
                    (u.x * dot(v, v) - v.x * dot(u, u)) / den};
    Point center = a + offset;
    return {center, distance(center, a)};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<Point> p(n);
    for (auto &q : p)
        cin >> q.x >> q.y;
    mt19937 engine(712367821);
    shuffle(p.begin(), p.end(), engine);
    Circle circle;
    for (int i = 0; i < n; i++)
        if (!contains(circle, p[i])) {
            circle = {p[i], 0};
            for (int j = 0; j < i; j++)
                if (!contains(circle, p[j])) {
                    circle = diameter(p[i], p[j]);
                    for (int k = 0; k < j; k++)
                        if (!contains(circle, p[k]))
                            circle = throughThree(p[i], p[j], p[k]);
                }
        }
    cout << fixed << setprecision(15) << circle.radius << '\n'
         << circle.center.x << ' ' << circle.center.y;
    return 0;
}
```

### 复杂度

随机顺序下期望 $O(n)$，最坏 $O(n^3)$；空间 $O(n)$。

### 易错点

内部计算使用long double，输出15位小数。避免用普通double配过大的EPS，否则1e−9精度要求可能失守。

## [USACO 2013 Nov G]No Change

### 题意

依次购买全部物品，每次用一枚硬币付一段连续购买且不找零，最大化剩下硬币面值。

### 思路

对固定的一枚硬币、固定的已买前缀，尽量多付连续物品不会更差：后续硬币从更靠后的前缀开始，其能覆盖到的最终位置也不会更靠前。用正价格前缀和和双指针，预处理jump[coin][prefix]表示这枚硬币能把已买前缀从prefix推进到哪里。

dp[mask]记录已使用硬币集合mask能买完的最长前缀，枚举下一枚硬币用jump推进。同一集合只需最远前缀，因为正价格使每枚后续硬币的推进函数单调。若已覆盖N件，剩余面值为硬币总和减mask面值和，更新最大值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int k, n;
    cin >> k >> n;
    vector<long long> coin(k), prefix(n + 1);
    long long total = 0;
    for (auto &x : coin) {
        cin >> x;
        total += x;
    }
    for (int i = 1; i <= n; i++) {
        int x;
        cin >> x;
        prefix[i] = prefix[i - 1] + x;
    }
    vector<vector<int>> jump(k, vector<int>(n + 1));
    for (int i = 0; i < k; i++) {
        int end = 0;
        for (int begin = 0; begin <= n; begin++) {
            end = max(end, begin);
            while (end < n && prefix[end + 1] - prefix[begin] <= coin[i])
                end++;
            jump[i][begin] = end;
        }
    }
    int masks = 1 << k;
    vector<int> dp(masks, -1);
    vector<long long> spent(masks);
    dp[0] = 0;
    long long answer = -1;
    for (int mask = 0; mask < masks; mask++) {
        if (mask) {
            int bit = __builtin_ctz((unsigned)mask);
            spent[mask] = spent[mask & (mask - 1)] + coin[bit];
        }
        if (dp[mask] == -1)
            continue;
        if (dp[mask] == n) {
            answer = max(answer, total - spent[mask]);
            continue;
        }
        for (int i = 0; i < k; i++)
            if (!(mask >> i & 1))
                dp[mask | (1 << i)] = max(dp[mask | (1 << i)], jump[i][dp[mask]]);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(KN+K2^K)$，空间 $O(KN+2^K)$。

### 易错点

剩余的是未使用硬币，已用硬币多付的部分不能找回。物品顺序固定，不可跨过买不起的当前物品。

## [USACO 2013 Dec G]Optimal Milking

### 题意

一排不选相邻机器，逐日单点修改，累加每天最大收益。

### 思路

每个区间保存2×2状态，索引为左端、右端是否选中，值为该限制下的最大独立集权和。合并两段时枚举相接的两个端点状态，禁止它们同时选中，其余取最大。叶子只有(0,0)=0、(1,1)=权值合法。点修改后沿树重算，根的四状态最大值为当日最优，累加到总答案。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, days;
    cin >> n >> days;
    const long long negative = LLONG_MIN / 4;
    struct Node {
        long long value[2][2];
        bool empty = true;
        Node() {
            for (auto &row : value)
                for (auto &x : row)
                    x = negative;
        }
    };
    auto leaf = [&](long long x) {
        Node node;
        node.empty = false;
        node.value[0][0] = 0;
        node.value[1][1] = x;
        return node;
    };
    auto merge = [&](const Node &a, const Node &b) {
        if (a.empty)
            return b;
        if (b.empty)
            return a;
        Node c;
        c.empty = false;
        for (int l = 0; l < 2; l++)
            for (int r = 0; r < 2; r++)
                for (int x = 0; x < 2; x++)
                    for (int y = 0; y < 2; y++)
                        if (!x || !y)
                            c.value[l][r] = max(c.value[l][r], a.value[l][x] + b.value[y][r]);
        return c;
    };
    int size = 1;
    while (size < n)
        size <<= 1;
    vector<Node> tree(2 * size);
    for (int i = 0; i < n; i++) {
        long long x;
        cin >> x;
        tree[size + i] = leaf(x);
    }
    for (int u = size - 1; u; u--)
        tree[u] = merge(tree[u * 2], tree[u * 2 + 1]);
    long long total = 0;
    while (days--) {
        int p;
        long long x;
        cin >> p >> x;
        p += size - 1;
        tree[p] = leaf(x);
        for (p >>= 1; p; p >>= 1)
            tree[p] = merge(tree[p * 2], tree[p * 2 + 1]);
        long long best = 0;
        for (auto &row : tree[1].value)
            for (long long v : row)
                best = max(best, v);
        total += best;
    }
    cout << total;
    return 0;
}
```

### 复杂度

构建 $O(n)$，每天 $O(\log n)$，空间 $O(n)$。

### 易错点

每次更新在当天开始生效，累加更新后的根答案。空填充叶设empty，避免把无效负无穷与实际状态混合。

## [USACO 2016 Ope P]262144

### 题意

相邻相等值可合成加一的值，最大化最后能生成的某个数字，N至262144。

### 思路

对目标值v，end[v][l]表示从l开始能完整合成一个v的区间的右开端点，不存在记0。若原a[l]=v，区间就是单点；否则要把两个相邻的v−1拼起来，设mid=end[v−1][l]，再接end[v−1][mid]。

为什么每个起点、目标值只有一个可能端点？把数x看成质量2^x，合并保持总质量；所有初始质量正，固定起点的前缀质量严格递增，所以给定2^v至多对应一个端点。只需上一层end数组，v最多40+log2N≤58，滚动处理并记录有解的最大v。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a)
        cin >> x;
    vector<int> previous(n + 1), current(n + 1);
    int answer = 0;
    for (int value = 1; value <= 58; value++) {
        fill(current.begin(), current.end(), 0);
        for (int l = n - 1; l >= 0; l--) {
            if (a[l] == value)
                current[l] = l + 1;
            else {
                int mid = previous[l];
                if (mid > 0 && mid < n)
                    current[l] = previous[mid];
            }
            if (current[l])
                answer = value;
        }
        previous.swap(current);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(58n)$，空间 $O(n)$。

### 易错点

不能总是先合并最左边的一对，样例已经给出反例。右端点用右开下标，n表示恰好用到末尾，不能再接第二段。

## Watering the Fields

> 原题：[P2212](https://www.luogu.com.cn/problem/P2212)
> 解法：只允许平方距离至少$c$的边，隐式做Prim · C++17

### 题意

连接两点的费用是欧氏距离平方；费用小于$c$的连边禁止。求使全部点连通的最小总费用，无法连通输出-1。



### 思路

将所有合法点对看作边，权为平方距离，在这张图上求最小生成树。用Prim按需计算当前点与其它点的平方距离，只有距离平方$\ge c$才更新。若某轮最小候选仍无穷，剩余点无法接入。答案累加平方距离，不能开根号。

![红色边被平方费用下限排除，仍可通过远处三号把一号与二号连通；费用相加九与十，不开根号。](data:image/svg+xml;base64,)

红色边被平方费用下限排除，仍可通过远处三号把一号与二号连通；费用相加九与十，不开根号。

时间 $O(n^2)$，额外空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long c;
    cin >> n >> c;
    vector<long long> x(n), y(n);
    for (int i = 0; i < n; i++)
        cin >> x[i] >> y[i];
    const long long INF = (1LL << 60);
    vector<long long> best(n, INF);
    vector<char> used(n);
    best[0] = 0;
    long long answer = 0;
    for (int step = 0; step < n; step++) {
        int u = -1;
        for (int v = 0; v < n; v++)
            if (!used[v] && (u == -1 || best[v] < best[u]))
                u = v;
        if (u == -1 || best[u] == INF) {
            cout << -1 << '\n';
            return 0;
        }
        used[u] = true;
        answer += best[u];
        for (int v = 0; v < n; v++)
            if (!used[v]) {
                long long dx = x[u] - x[v], dy = y[u] - y[v], w = dx * dx + dy * dy;
                if (w >= c)
                    best[v] = min(best[v], w);
            }
    }
    cout << answer << '\n';
    return 0;
}
```

### 易错点

费用是平方距离本身；太短的边禁止，等于门槛允许；无法跨割才判不连通；总和用long long；单点费用零。

## Corn Maze

> 原题：[P1825](https://www.luogu.com.cn/problem/P1825)
> 解法：把踏入传送门与瞬移合成一次移动 · C++17

### 题意

四向移动花一时间，踏入大写字母格必须立刻传到同字母另一格，传送不花时间。求从 @ 到 = 的最短时间。



### 思路

先记录每对传送端。BFS 扩展相邻格，若是字母，就把本次移动的终点替换为另一端，整条边仍只花一时间。访问标记与距离记在传送后的落脚点；到达另一端后可以走离它，不会在同一次移动里无限传回。

时间、空间均为 $O(nm)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<string> grid(n);
    vector<pair<int, int>> port[26];
    int sx = 0, sy = 0;
    for (int i = 0; i < n; i++) {
        cin >> grid[i];
        for (int j = 0; j < m; j++) {
            char c = grid[i][j];
            if (c == '@') {
                sx = i;
                sy = j;
            }
            if ('A' <= c && c <= 'Z')
                port[c - 'A'].push_back({i, j});
        }
    }
    vector<vector<int>> distance(n, vector<int>(m, -1));
    queue<pair<int, int>> todo;
    todo.push({sx, sy});
    distance[sx][sy] = 0;
    int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    while (!todo.empty()) {
        auto [x, y] = todo.front();
        todo.pop();
        if (grid[x][y] == '=') {
            cout << distance[x][y] << '\n';
            return 0;
        }
        for (int d = 0; d < 4; d++) {
            int nx = x + dr[d], ny = y + dc[d];
            if (nx < 0 || nx >= n || ny < 0 || ny >= m || grid[nx][ny] == '#')
                continue;
            char c = grid[nx][ny];
            if ('A' <= c && c <= 'Z') {
                auto &ends = port[c - 'A'];
                pair<int, int> entered = {nx, ny};
                auto destination = (ends[0] == entered ? ends[1] : ends[0]);
                nx = destination.first;
                ny = destination.second; // 同一次行动只传送一次。
            }
            if (distance[nx][ny] == -1) {
                distance[nx][ny] = distance[x][y] + 1;
                todo.push({nx, ny});
            }
        }
    }
    cout << -1 << '\n';
    return 0;
}
```

### 易错点

踏入门必须传送且只传一次；两端是不同落脚状态；访问标记放在传送后位置。

## [USACO 2011 Ope S]Learning Languages

### 题意

有共同语言的牛能互相传话，最少买语言书使所有牛连通，并输出具体教书方案。

### 思路

每种语言记一只已经会它的牛，以后遇到也会该语言的牛就将两者合并。得到 c 个牛的连通块后，一本书最多使两个块连起来，因此至少 c−1 本。选牛1已经会的一种语言，给其余每个块的一只代表牛各买一本这种语言的书，恰好 c−1 本便全部连通。每只牛至少会一种语言，故所选公共语言一定存在。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, size;
    DSU(int n) : parent(n + 1), size(n + 1, 1) { iota(parent.begin(), parent.end(), 0); }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    DSU dsu(n);
    vector<int> owner(m + 1);
    int common = 0;
    for (int cow = 1; cow <= n; cow++) {
        int k;
        cin >> k;
        while (k--) {
            int language;
            cin >> language;
            if (cow == 1 && common == 0)
                common = language;
            if (owner[language])
                dsu.unite(cow, owner[language]);
            else
                owner[language] = cow;
        }
    }
    vector<int> representatives;
    for (int cow = 1; cow <= n; cow++)
        if (dsu.find(cow) == cow && dsu.find(cow) != dsu.find(1))
            representatives.push_back(cow);
    cout << representatives.size() << '\n';
    for (int cow : representatives)
        cout << common << ' ' << cow << '\n';
    return 0;
}
```

### 复杂度

总已知语言条数 $L$，时间 $O((n+L)\alpha(n)+m)$，空间 $O(n+m)$。

### 易错点

未被任何牛使用的语言不构成需要连通的块。输出先是语言编号，再是牛编号；题面样例只给书本数，但完整提交仍要输出方案。

## Brownie Slicing

### 题意

先水平切为 A 条，每条独立竖切为 B 块，最大化所有块中的最少巧克力数。

### 思路

二分每块至少 target。对当前横条累计每列的巧克力，沿列从左到右累计到至少 target 就竖切一块；若可切出至少 B 块，这个横条就合格，立即在当前行后横切并清空列和。两层都采用最早可行的切点：巧克力非负，把切点向后拖只会占用后续可用的行或列，不会改善后续机会。能得到至少 A 个横条就成功。剩余列、剩余行并入各自最后一块即可。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int rows, columns, a, b;
    cin >> rows >> columns >> a >> b;
    vector<vector<long long>> grid(rows, vector<long long>(columns));
    long long total = 0;
    for (auto &row : grid)
        for (auto &x : row) {
            cin >> x;
            total += x;
        }
    auto possible = [&](long long target) {
        vector<long long> sums(columns);
        int strips = 0;
        for (const auto &row : grid) {
            for (int c = 0; c < columns; c++)
                sums[c] += row[c];
            long long sum = 0;
            int pieces = 0;
            for (long long x : sums) {
                sum += x;
                if (sum >= target) {
                    pieces++;
                    sum = 0;
                }
            }
            if (pieces >= b) {
                strips++;
                if (strips >= a)
                    return true;
                fill(sums.begin(), sums.end(), 0);
            }
        }
        return false;
    };
    long long low = 0, high = total / a / b;
    while (low < high) {
        long long mid = low + (high - low + 1) / 2;
        if (possible(mid))
            low = mid;
        else
            high = mid - 1;
    }
    cout << low;
    return 0;
}
```

### 复杂度

时间 $O(RC\log(H+1))$，空间 $O(RC)$，$H$ 为总巧克力数。

### 易错点

每条横带的竖切位置可独立选择，不要求整块布朗尼使用相同竖线。target=0 时每块仍须非空，代码每列至多切出一块。

## Tree Decoration

### 题意

每个子树有最少装饰数量，每个结点单件安装费用不同，求最小总费用。

### 思路

自底向上处理。每个子树维护已满足子树内部约束的装饰总数、总费用，以及本子树的最低单件安装费。先累加各孩子的装饰与费用，最低费用同时与本结点比较。若当前子树数量还不足C[u]，就在本子树最便宜结点补齐；这不会破坏任何后代下界，只会增加计数。后面祖先新增装饰同样不能替代当前子树已经必须付出的最低费用，因此局部补齐最优。迭代得到遍历顺序，再逆序处理避免长链递归。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> children(n);
    vector<long long> required(n), count(n), cost(n);
    vector<int> cheapest(n);
    int root = 0;
    for (int u = 0; u < n; u++) {
        int parent;
        cin >> parent >> required[u] >> cheapest[u];
        if (parent == -1)
            root = u;
        else
            children[parent - 1].push_back(u);
    }
    vector<int> order{root};
    for (size_t i = 0; i < order.size(); i++)
        for (int v : children[order[i]])
            order.push_back(v);
    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];
        for (int v : children[u]) {
            count[u] += count[v];
            cost[u] += cost[v];
            cheapest[u] = min(cheapest[u], cheapest[v]);
        }
        if (count[u] < required[u]) {
            cost[u] += (required[u] - count[u]) * cheapest[u];
            count[u] = required[u];
        }
    }
    cout << cost[root];
    return 0;
}
```

### 复杂度

时间、空间均为 $O(n)$。

### 易错点

父亲编号不一定小于孩子，不能直接按编号逆序。最低单价允许来自任何后代，不仅当前点。

## 值周

### 题意

在长度上亿的整数道路上删除多个闭区间中的树，求剩余棵数。

### 思路

道路共有 l+1 棵树，不能逐点建数组。把删除区间按左端点排序，维护当前合并段 [left,right]；新区间若与当前段重叠或相邻就扩展右端，否则结算 right-left+1 并开始下一段。最后扣除删除并集大小。相邻整数段可以合并，因为两段间没有遗漏整数点。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long length;
    int n;
    cin >> length >> n;
    vector<pair<long long, long long>> a(n);
    for (auto &[l, r] : a)
        cin >> l >> r;
    sort(a.begin(), a.end());
    long long left = a[0].first, right = a[0].second, removed = 0;
    for (int i = 1; i < n; i++) {
        if (a[i].first <= right + 1)
            right = max(right, a[i].second);
        else {
            removed += right - left + 1;
            left = a[i].first;
            right = a[i].second;
        }
    }
    removed += right - left + 1;
    cout << length + 1 - removed;
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

闭区间长度是 right-left+1，不是几何长度。道路的零号位置也有树。

## [USACO 2010 Feb S]Chocolate Eating

### 题意

顺序吃巧克力，隔夜快乐减半，最大化 d 天结束时的最低快乐并给出吃法。

### 思路

二分每天最低值 target。判定时按天模拟，先将上一天快乐减半，再按原顺序吃到至少 target 就停，把未必需要的巧克力留到以后。提前多吃只会让它的贡献在夜晚减半，延后到真正需要时不会更差，所以这种最晚食用的贪心判定充分。若巧克力耗尽仍不足就失败。目标越小越容易，二分上界可取全部快乐总和。最后按最优值重跑并记录食用日期；剩余巧克力全部放在末日，保证每块都有安排，也不会降低最低值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, days;
    cin >> n >> days;
    vector<long long> a(n);
    long long total = 0;
    for (auto &x : a) {
        cin >> x;
        total += x;
    }
    vector<int> plan(n);
    auto possible = [&](long long target, bool record) {
        long long happiness = 0;
        int next = 0;
        for (int day = 1; day <= days; day++) {
            happiness /= 2;
            while (happiness < target && next < n) {
                happiness += a[next];
                if (record)
                    plan[next] = day;
                next++;
            }
            if (happiness < target)
                return false;
        }
        if (record)
            while (next < n)
                plan[next++] = days;
        return true;
    };
    long long low = 0, high = total;
    while (low < high) {
        long long mid = low + (high - low + 1) / 2;
        if (possible(mid, false))
            low = mid;
        else
            high = mid - 1;
    }
    possible(low, true);
    cout << low << '\n';
    for (int day : plan)
        cout << day << '\n';
    return 0;
}
```

### 复杂度

总快乐为 $H$，时间 $O((n+d)\log(H+1))$，空间 $O(n)$。

### 易错点

同一天可以吃零块或多块。隔夜减半必须向下取整；日程应保持原巧克力顺序，任意最优日程均可。

## [USACO 2010 Feb G]Slowing down

### 题意

牛依次从根走向各自牧场，统计经过已到达牛的次数。

### 思路

已停在节点u的牛，会使后来目标位于u子树的牛减速。因此每到达一头牛，就给u的整个DFS子树区间加1；下一头牛的减速次数是其目标点当前位置值。用差分树状数组做区间加、单点查询，先查询再加入。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct EulerTree {
    int n;
    vector<vector<int>> edge;
    vector<int> parent, depth, in, out, order;
    EulerTree(int n) : n(n), edge(n + 1), parent(n + 1), depth(n + 1), in(n + 1), out(n + 1) {}
    void add(int u, int v) {
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    void root(int start) {
        vector<int> stack = {start};
        parent[start] = 0;
        order.clear();
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            in[u] = order.size() + 1;
            order.push_back(u);
            for (int v : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    stack.push_back(v);
                }
        }
        vector<int> size(n + 1, 1);
        for (int i = (int)order.size() - 1; i >= 0; i--) {
            int u = order[i];
            out[u] = in[u] + size[u] - 1;
            if (parent[u])
                size[parent[u]] += size[u];
        }
    }
};

struct Fenwick {
    int n;
    vector<long long> tree;
    Fenwick(int n) : n(n), tree(n + 1) {}
    void add(int p, long long v) {
        for (; p <= n; p += p & -p)
            tree[p] += v;
    }
    long long sum(int p) {
        long long result = 0;
        for (; p; p -= p & -p)
            result += tree[p];
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    EulerTree tree(n);
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        tree.add(u, v);
    }
    tree.root(1);
    Fenwick bit(n);
    for (int i = 0; i < n; i++) {
        int u;
        cin >> u;
        cout << bit.sum(tree.in[u]) << '\n';
        bit.add(tree.in[u], 1);
        if (tree.out[u] < n)
            bit.add(tree.out[u] + 1, -1);
    }
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

根节点也可能是某头牛的牧场，会影响之后所有牛。当前牛尚未到达，不能先插入再查询。

## [USACO 2010 Mar G]Great Cow Gathering

> 原题：[P2986](https://www.luogu.com.cn/problem/P2986)
> 解法：先算一个集会点，再沿边换根调整总路程 · C++17

### 题意

树边有长度，每点有若干奶牛，选择某点聚会，使每只牛走来的路程总和最小，输出这个最小值。



### 思路



![树边长度为二与三，点上的牛数为零一二；费用按每头牛到棚的路径长度逐头相加。](data:image/svg+xml;base64,)

先选任意根，计算每棵子树奶牛数mass与根处总代价F。把集会点沿长$w$的边移到孩子$v$，$v$子树内奶牛各少走$w$，其余各多走$w$，所以新总代价增加$w$乘总牛数减两倍$mass[v]$。顺着树算完所有候选点，取最小，数量和费用均用六十四位。

时间与空间均为 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> cows(n);
    long long total = 0;
    for (auto &x : cows) {
        cin >> x;
        total += x;
    }
    struct Edge {
        int to;
        long long length;
    };
    vector<vector<Edge>> g(n);
    for (int i = 1, u, v; i < n; i++) {
        long long w;
        cin >> u >> v >> w;
        --u;
        --v;
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }
    vector<int> parent(n, -1), order = {0};
    parent[0] = 0;
    vector<long long> distance(n), mass = cows, value(n);
    for (size_t pos = 0; pos < order.size(); ++pos) {
        int u = order[pos];
        value[0] += cows[u] * distance[u];
        for (auto edge : g[u])
            if (edge.to != parent[u]) {
                parent[edge.to] = u;
                distance[edge.to] = distance[u] + edge.length;
                order.push_back(edge.to);
            }
    }
    for (int pos = n - 1; pos > 0; --pos) {
        int u = order[pos];
        mass[parent[u]] += mass[u];
    }
    long long answer = value[0];
    for (int u : order) {
        for (auto edge : g[u])
            if (parent[edge.to] == u) {
                int v = edge.to;
                value[v] = value[u] + edge.length * (total - 2 * mass[v]);
                answer = min(answer, value[v]);
            }
    }
    cout << answer << '\n';
    return 0;
}
```

### 易错点

每只牛分别计距离；零牛点也可聚会；换根时固定使用原子树牛数；子树内减、外部加；输出最小费用；六十四位。

## Lake Counting

### 题意

统计八方向相邻的水格形成多少池塘。

### 思路

逐格扫描，每遇到未处理的W就新增一个池塘，从该格BFS淹没整个八连通块。入队时把W改成点，保证每个水格只处理一次。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<string> grid(n);
    for (auto &row : grid)
        cin >> row;
    int answer = 0;
    for (int r = 0; r < n; r++)
        for (int c = 0; c < m; c++)
            if (grid[r][c] == 'W') {
                answer++;
                vector<pair<int, int>> queue{{r, c}};
                grid[r][c] = '.';
                for (size_t h = 0; h < queue.size(); h++) {
                    auto [x, y] = queue[h];
                    for (int dx = -1; dx <= 1; dx++)
                        for (int dy = -1; dy <= 1; dy++) {
                            int xx = x + dx, yy = y + dy;
                            if (xx >= 0 && xx < n && yy >= 0 && yy < m && grid[xx][yy] == 'W') {
                                grid[xx][yy] = '.';
                                queue.push_back({xx, yy});
                            }
                        }
                }
            }
    cout << answer;
    return 0;
}
```

### 复杂度

时间、空间均为 $O(nm)$。

### 易错点

斜对角也连通，不能只用四方向。这里直接修改地图作访问标记。

## [USACO 2010 Nov G]Cow Photographs

### 题意

排列经相邻交换变为任意循环升序排列的最少次数。

### 思路

固定目标1,2,...,n时，最少相邻交换数就是原排列逆序数，用树状数组求出。把目标首项v移到目标末尾，相当于v从最小变最大：原排列中在v前面的p−1个元素原来与它构成逆序，现在消失；后面的n−p个元素新产生逆序。所以代价变化n+1−2p。记录每个编号原位置，依次枚举n种目标起点并取最小。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> tree;
    Fenwick(int n) : n(n), tree(n + 1) {}
    void add(int p, long long v) {
        for (; p <= n; p += p & -p)
            tree[p] += v;
    }
    long long sum(int p) {
        long long result = 0;
        for (; p; p -= p & -p)
            result += tree[p];
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> position(n + 1);
    Fenwick bit(n);
    long long inversions = 0;
    for (int i = 1; i <= n; i++) {
        int x;
        cin >> x;
        position[x] = i;
        inversions += i - 1 - bit.sum(x);
        bit.add(x, 1);
    }
    long long answer = inversions;
    for (int value = 1; value < n; value++) {
        inversions += n + 1 - 2LL * position[value];
        answer = min(answer, inversions);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

旋转的是目标编号顺序，变化量使用该编号在原排列中的位置，不是编号本身。

## [USACO 2010 Dec S]Apple Delivery

### 题意

从PB出发，把苹果送到PA1、PA2，先后任选，不需回起点。

### 思路

仅两种顺序：PB→PA1→PA2，或PB→PA2→PA1。图无向，两目标间距离共用，答案为dist(PA1,PA2)+min(dist(PB,PA1),dist(PB,PA2))。分别从两个目标做Dijkstra即可取得这三个距离。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

vector<long long> dijkstra(const vector<vector<pair<int, long long>>> &graph, int source) {
    const long long inf = 1LL << 60;
    vector<long long> distance(graph.size(), inf);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>,
                   greater<pair<long long, int>>>
        heap;
    distance[source] = 0;
    heap.push({0, source});
    while (!heap.empty()) {
        auto [cost, u] = heap.top();
        heap.pop();
        if (cost != distance[u])
            continue;
        for (auto [v, w] : graph[u])
            if (distance[v] > cost + w) {
                distance[v] = cost + w;
                heap.push({distance[v], v});
            }
    }
    return distance;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m, n, start, a, b;
    cin >> m >> n >> start >> a >> b;
    --start;
    --a;
    --b;
    vector<vector<pair<int, long long>>> graph(n);
    while (m--) {
        int u, v;
        long long w;
        cin >> u >> v >> w;
        --u;
        --v;
        graph[u].push_back({v, w});
        graph[v].push_back({u, w});
    }
    auto da = dijkstra(graph, a), db = dijkstra(graph, b);
    cout << da[b] + min(da[start], db[start]);
    return 0;
}
```

### 复杂度

时间 $O((P+C)\log P)$，空间 $O(P+C)$。

### 易错点

首行先给道路数C，再给草地数P。距离和保证输入边总长不超过二十亿，但组合运算仍使用64位。

## Look Up

### 题意

对每个位置，求右侧第一个严格更大元素的下标，没有则为零。

### 思路

从右往左维护候选栈。处理 a[i] 时，栈顶若不大于 a[i] 就弹出：它既不满足当前查询，也会被更近且不小的 a[i] 取代。弹完后栈顶就是最近的严格更大位置，再把 i 入栈。每个位置只进出栈一次。

<!-- nowcoder-animation:monotonic-stack -->

### 动态示例

![相同数值也要弹出；栈里保存下标，而不是只保存数值。](assets/monotonic-stack.gif)

相同数值也要弹出；栈里保存下标，而不是只保存数值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> a(n), ans(n), st;
    for (int &x : a)
        cin >> x;
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty() && a[st.back()] <= a[i])
            st.pop_back();
        ans[i] = st.empty() ? 0 : st.back() + 1;
        st.push_back(i);
    }
    for (int i = 0; i < n; i++) {
        if (i)
            cout << ' ';
        cout << ans[i];
    }
    return 0;
}
```

### 复杂度

时间与数组空间均为 $O(n)$。

### 易错点

相等的值也必须弹出，因为要求严格大于。最后按一行输出，返回一开始的下标。

## [USACO 2009 Oct G]Bessie's Weight Problem

> 原题：[P2639](https://www.luogu.com.cn/problem/P2639)
> 解法：记录每个草料总重能否由若干捆恰好组成 · C++17

### 题意

每捆草料最多取一次，背包最多装H，求不超过H的最大总重量。相同重量的不同捆仍可各取一次。



### 思路



![圆表示三捆独立草料，两个五虽然数字相同，仍然是两件可各取一次的物品。](data:image/svg+xml;base64,)

$reachable[s]$记录能否恰好组成总重$s$，只把零初始化为真。每读一捆重量$w$，从H倒序到$w$，把$reachable[s-w]$合入$reachable[s]$。最后从H向零找第一个可达值。

时间 $O(NH)$，空间 $O(H)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int h, n;
    cin >> h >> n;
    vector<char> reachable(h + 1);
    reachable[0] = true;
    for (int i = 0, w; i < n; i++) {
        cin >> w;
        // 倒序读取未使用当前捆的旧状态。
        for (int sum = h; sum >= w; --sum) {
            if (reachable[sum - w])
                reachable[sum] = true;
        }
    }
    for (int sum = h; sum >= 0; --sum) {
        if (reachable[sum]) {
            cout << sum << '\n';
            break;
        }
    }
    return 0;
}
```

### 易错点

每捆一次；同重不去重；只初始化总重零；不要求装满；总重倒序。

## Job Hunt

### 题意

每到一城可赚D，路免费、航线收费且可借款，求最大余额或可无限赚钱。

### 思路

初始在S先赚D。免费道路u→v增加D，航线增加D−票价，问题变为从S出发可随时结束的最长收益路。用Bellman-Ford最大化余额，仅从可达状态松弛。若第C轮仍有更新，存在从S可达的正收益环，可以无限重复，输出−1；否则最优路可删掉非正环，至多C−1条边，取所有城市余额最大值。允许用未来收入付机票，所以中间余额可为负，不能限制边的可走性。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int income, p, n, f, start;
    cin >> income >> p >> n >> f >> start;
    struct Edge {
        int a, b, gain;
    };
    vector<Edge> edges;
    for (int i = 0; i < p; i++) {
        int a, b;
        cin >> a >> b;
        edges.push_back({a - 1, b - 1, income});
    }
    for (int i = 0; i < f; i++) {
        int a, b, price;
        cin >> a >> b >> price;
        edges.push_back({a - 1, b - 1, income - price});
    }
    const long long neg = -(1LL << 60);
    vector<long long> best(n, neg);
    best[start - 1] = income;
    bool unlimited = false;
    for (int round = 1; round <= n; round++) {
        bool changed = false;
        for (auto e : edges)
            if (best[e.a] != neg && best[e.b] < best[e.a] + e.gain) {
                best[e.b] = best[e.a] + e.gain;
                changed = true;
            }
        if (!changed)
            break;
        if (round == n)
            unlimited = true;
    }
    cout << (unlimited ? -1 : *max_element(best.begin(), best.end()));
    return 0;
}
```

### 复杂度

时间 $O(C(P+F))$，空间 $O(C+P+F)$。

### 易错点

只需任意可达正环，不要求还能去某个指定终点。无法从S到达的正环不影响答案。起始城市的D也计入。

## [USACO 2009 Dec S]Music Notes

### 题意

按各音符持续拍数，查询零起算时刻正在播放哪个音符。

### 思路

prefix[i] 为前 i 个音符的总拍数，第 i 个音符占据 [prefix[i-1],prefix[i])。给定 t，找第一个严格大于 t 的结束时间，它的下标就是答案。严格比较恰好把切换时刻归到下一个音符。

