                    cout << ' ';
                first = false;
                cout << a[queue.front()];
            }
        }
        cout << '\n';
    }
    return 0;
}
```

### 易错点

本题包含当前位置；只输出完整窗口；每行$n$减$k$加一项；存下标以处理过期；两次比较方向相反；不把最小int取负；重复值保留较新者。

## 同余方程

### 题意

保证有解，求a*x模b等于1的最小正整数x。

### 思路

扩展欧几里得求a*x+b*y=gcd(a,b)。题目保证逆元存在，即gcd为1，所以所得x就是一组解；全部解相差b的整数倍，归一化到[0,b)后就是最小正解。b≥2且互质，结果不会为0。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

long long extendedGcd(long long a, long long b, long long &x, long long &y) {
    if (!b) {
        x = 1;
        y = 0;
        return a;
    }
    long long previousX, previousY;
    long long g = extendedGcd(b, a % b, previousX, previousY);
    x = previousY;
    y = previousX - (a / b) * previousY;
    return g;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long a, b, x, y;
    cin >> a >> b;
    extendedGcd(a, b, x, y);
    cout << (x % b + b) % b;
    return 0;
}
```

### 复杂度

时间 $O(\log\min(a,b))$，递归栈空间同阶。

### 易错点

系数可以为负，要归一化两次取模。参数至二十亿，系数更新使用64位。

## 取石子游戏 1

### 题意

一堆N石子，每步取1到K，取完者胜。

### 思路

0是必败态。若剩余量是K+1的倍数，任何一步都会离开倍数；否则可取余数使对手面对倍数。之后对手取x，就取K+1−x回应。因此N mod(K+1)=0时后手胜，其余先手胜。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    cout << (n % (k + 1) ? 1 : 2);
    return 0;
}
```

### 复杂度

时间、空间均 $O(1)$。

### 易错点

这是最后取者胜的规则，取值范围包含K。

## 取石子游戏 2

### 题意

每次从一堆取任意正数石子，判断先手胜负。

### 思路

全部堆大小的异或X为0时，改变任一堆都会使异或非0；X非0时，取最高置位所在的一堆a，把它减为a xor X，该数小于a，且使总异或变0。故先手胜当且仅当异或非0。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    int total = 0;
    while (n--) {
        int x;
        cin >> x;
        total ^= x;
    }
    cout << (total ? "win" : "lose");
    return 0;
}
```

### 复杂度

时间 $O(n)$，空间 $O(1)$。

### 易错点

每次只能改一堆，不能用总石子数奇偶判断。

## 货仓选址

### 题意

数轴上放一个货仓，最小化到各店的距离总和。

### 思路

排序后将最左与最右两店配对。货仓放在这一对之间时，两段距离之和恒等于两店间距；放到区间外只会更大。所有配对区间的公共部分正是中位数位置（偶数时为中间两数之间），因此取任一中位数最优。计算到它的绝对距离总和。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto &x : a)
        cin >> x;
    sort(a.begin(), a.end());
    long long median = a[n / 2], answer = 0;
    for (long long x : a)
        answer += abs(x - median);
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

输出最小距离和，而非仓库坐标；总和可能超过32位。

## Running Median

### 题意

每读入奇数个数，就输出当前中位数，答案每行至多十个。

### 思路

用大根堆存较小的一半，小根堆存较大的一半。插入时先按大根堆顶分边，再调整到左堆个数等于右堆或多一。保持左堆所有数不大于右堆所有数后，奇数时左堆堆顶就是中位数。每组先输出原数据编号与答案个数，随后按十个一行输出。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int id, n;
        cin >> id >> n;
        priority_queue<int> left;
        priority_queue<int, vector<int>, greater<int>> right;
        vector<int> answer;
        for (int i = 0; i < n; i++) {
            int x;
            cin >> x;
            if (left.empty() || x <= left.top())
                left.push(x);
            else
                right.push(x);
            if (left.size() > right.size() + 1) {
                right.push(left.top());
                left.pop();
            }
            if (left.size() < right.size()) {
                left.push(right.top());
                right.pop();
            }
            if (i % 2 == 0)
                answer.push_back(left.top());
        }
        cout << id << ' ' << answer.size() << '\n';
        for (int i = 0; i < (int)answer.size(); i++) {
            cout << answer[i];
            cout << ((i % 10 == 9 || i + 1 == (int)answer.size()) ? '\n' : ' ');
        }
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

比较原整数，不把两个堆顶相加，避免32位有符号整数溢出。本题只在奇数长度时输出，无需求偶数中位数。

## To the Max

> 原题：[P1719](https://www.luogu.com.cn/problem/P1719)
> 解法：枚举上下边界，压成非空最大子段和 · C++17

### 题意

求整数方阵中非空、边与网格平行的子矩形最大元素和，允许所有元素都是负数。



### 思路

枚举上边 top，再逐行向下扩展 bottom，维护每一列在两行之间的总和。固定上下边后，找最佳左右边等价于求这个列和数组的最大非空连续子段和，用“在本列重新开始，或延长上一段”线性递推。

![每个压缩值是同一列在所选行带内的真实总和；不是把不相邻列任意挑选。](data:image/svg+xml;base64,)

每个压缩值是同一列在所选行带内的真实总和；不是把不相邻列任意挑选。

时间 $O(n^3)$、输入矩阵空间 $O(n^2)$，列和额外空间 $O(n)$。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<long long>> a(n, vector<long long>(n));
    for (auto &row : a)
        for (auto &x : row)
            cin >> x;
    long long answer = LLONG_MIN;
    for (int top = 0; top < n; top++) {
        vector<long long> sum(n);
        for (int bottom = top; bottom < n; bottom++) {
            for (int column = 0; column < n; column++)
                sum[column] += a[bottom][column];
            long long ending = sum[0];
            answer = max(answer, ending);
            for (int column = 1; column < n; column++) {
                ending = max(sum[column], ending + sum[column]);
                answer = max(answer, ending);
            }
        }
    }
    cout << answer << '\n';
    return 0;
}
```

### 易错点

矩形不能空；全负数组应返回最大单格值；每换上边界重新清空列和。

## Largest Rectangle in a Histogram

### 题意

多个单位宽柱状图中求最大矩形面积，读到 n=0 结束。

### 思路

栈保存高度不下降的柱下标。读到更矮柱 i 时，栈顶柱 j 的向右扩展第一次被挡住，弹栈后新的栈顶 left 是左侧边界，矩形可占 left+1 到 i-1，面积 h[j]*(i-left-1)。相等高度可暂时都留在栈中，最终最左的同高柱会覆盖完整跨度。末尾补一根零高柱，结算全部正高度。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    while (cin >> n && n) {
        vector<long long> height(n + 2);
        for (int i = 1; i <= n; i++)
            cin >> height[i];
        vector<int> stack;
        long long answer = 0;
        for (int i = 1; i <= n + 1; i++) {
            while (!stack.empty() && height[stack.back()] > height[i]) {
                int j = stack.back();
                stack.pop_back();
                int left = stack.empty() ? 0 : stack.back();
                answer = max(answer, height[j] * (i - left - 1));
            }
            stack.push_back(i);
        }
        cout << answer << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间、空间均为 $O(n)$。

### 易错点

最高柱不一定给出最大面积。面积可达 10^14，使用 long long；结束标记零不是一个需输出答案的测试。

## The XOR Largest Pair

### 题意

从非负31位整数中选两数，最大化异或值。

### 思路

把每个整数从第30位到第0位插入二进制 Trie。查询 x 时，从高位到低位优先走与 x 当前位相反的分支，使结果这一位为一；不存在才走相同分支。高位一的收益超过所有低位之和，因此每步贪心成立。对所有 x 取查询结果的最大值。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> a(n);
    vector<array<int, 2>> trie(1);
    trie.reserve(1 + 31 * n);
    for (int &x : a) {
        cin >> x;
        int node = 0;
        for (int b = 30; b >= 0; b--) {
            int bit = x >> b & 1;
            if (!trie[node][bit]) {
                trie[node][bit] = trie.size();
                trie.push_back({0, 0});
            }
            node = trie[node][bit];
        }
    }
    int answer = 0;
    for (int x : a) {
        int node = 0, value = 0;
        for (int b = 30; b >= 0; b--) {
            int bit = x >> b & 1;
            if (trie[node][bit ^ 1]) {
                value |= 1 << b;
                node = trie[node][bit ^ 1];
            } else
                node = trie[node][bit];
        }
        answer = max(answer, value);
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(31n)$，最坏空间 $O(31n)$。

### 易错点

最高允许位是第30位，共31位。这里输出异或值，不是组成该值的两个原整数；重复数也可插入。

## 表达式计算4

### 题意

计算带加减乘整除和乘方的短表达式，支持负数、括号以及题目提到的多余括号。

### 思路

先用括号栈配对，删除没有匹配对象的额外括号。然后按优先级写四层递归下降：表达式处理加减，项处理乘除，幂处理乘方，原子处理整数、符号和括号。每一层用循环依次合并同级运算，采用该原题公开参考实现使用的从左到右顺序。整数除法用绝对值整除后恢复符号，保持向零截断。Python 整数保存精确中间值，即使两个很大的幂最后相减得到小结果，也不会先溢出。

### 参考代码

```python
import sys


def remove_unmatched_parentheses(source):
    stack = []
    matched = set()
    for i, char in enumerate(source):
        if char == '(':
            stack.append(i)
        elif char == ')' and stack:
            matched.add(stack.pop())
            matched.add(i)
    return ''.join(char for i, char in enumerate(source) if char not in '()' or i in matched)


def divide(a, b):
    quotient = abs(a) // abs(b)
    return -quotient if (a < 0) != (b < 0) else quotient


class Parser:
    def __init__(self, source):
        self.source = source
        self.pos = 0

    def atom(self):
        if self.source[self.pos] in '+-':
            sign = self.source[self.pos]
            self.pos += 1
            value = self.atom()
            return value if sign == '+' else -value
        if self.source[self.pos] == '(':
            self.pos += 1
            value = self.expression()
            self.pos += 1
            return value
        value = 0
        while self.pos < len(self.source) and self.source[self.pos].isdigit():
            value = value * 10 + int(self.source[self.pos])
            self.pos += 1
        return value

    def power(self):
        value = self.atom()
        while self.pos < len(self.source) and self.source[self.pos] == '^':
            self.pos += 1
            exponent = self.atom()
            if exponent < 0:
                if value == 1:
                    value = 1
                elif value == -1:
                    value = -1 if exponent % 2 else 1
                else:
                    value = 0
            else:
                value = pow(value, exponent)
        return value

    def term(self):
        value = self.power()
        while self.pos < len(self.source) and self.source[self.pos] in '*/':
            op = self.source[self.pos]
            self.pos += 1
            right = self.power()
            value = value * right if op == '*' else divide(value, right)
        return value

    def expression(self):
        value = self.term()
        while self.pos < len(self.source) and self.source[self.pos] in '+-':
            op = self.source[self.pos]
            self.pos += 1
            right = self.term()
            value = value + right if op == '+' else value - right
        return value


def main():
    source = remove_unmatched_parentheses(sys.stdin.readline().strip())
    print(Parser(source).expression())


if __name__ == '__main__':
    main()
```

### 复杂度

语法扫描与递归调用数为 $O(L)$，其中 $L≤30$。整数算术还需计入实际中间值位数的运算成本；递归和语法存储为 $O(L)$。

### 易错点

Python 的 // 对负数向下取整，题目整除应向零截断，所以单独实现 divide。乘方优先级高于乘除，配对的括号内部要完整递归。不要直接用 eval 解释原串，原题的额外括号和同级乘方规则需要明确处理。

## Sliding Window

> 原题：[P1886](https://www.luogu.com.cn/problem/P1886)
> 解法：同一数组分别维护完整窗口的最小与最大候选 · C++17

### 题意

给定长度$k$的滑动窗口，依次输出每个完整窗口的最小值与最大值，各占一行。



### 思路



![原样例八项给出六个完整窗口，尚未读满三项时不输出。](data:image/svg+xml;base64,)

数组保存下来，分别做最小值与最大值两遍扫描。队列存下标，先从队首移走窗口左侧的过期项，再从队尾删去被当前值支配的候选，加入当前下标。只有已读满$k$项才输出队首。最小队列弹不小于当前值者，最大队列弹不大于当前值者；直接比较可覆盖最小int输入。

时间 $O(n)$，空间 $O(n+k)$，含输入数组。

