### 动态示例

![使用原样例展示按莫队顺序移动左右端点；绿色为窗口，加入先算新增对，删除先减频次。](assets/mo-socks-pairs.gif)

使用原样例展示按莫队顺序移动左右端点；绿色为窗口，加入先算新增对，删除先减频次。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> color(n + 1);
    for (int i = 1; i <= n; i++)
        cin >> color[i];
    int block = max(1, (int)sqrt(n));
    struct Query {
        int l, r, id;
    };
    vector<Query> queries(m);
    for (int i = 0; i < m; i++) {
        cin >> queries[i].l >> queries[i].r;
        queries[i].id = i;
    }
    sort(queries.begin(), queries.end(), [&](auto a, auto b) {
        int x = a.l / block, y = b.l / block;
        if (x != y)
            return x < y;
        return x % 2 ? a.r > b.r : a.r < b.r;
    });
    vector<long long> count(n + 1);
    vector<pair<long long, long long>> answer(m);
    long long pairs = 0;
    int left = 1, right = 0;
    auto add = [&](int p) { pairs += count[color[p]]++; };
    auto remove = [&](int p) { pairs -= --count[color[p]]; };
    for (auto q : queries) {
        while (left > q.l)
            add(--left);
        while (right < q.r)
            add(++right);
        while (left < q.l)
            remove(left++);
        while (right > q.r)
            remove(right--);
        long long length = q.r - q.l + 1, total = length * (length - 1) / 2;
        if (pairs == 0 || total == 0)
            answer[q.id] = {0, 1};
        else {
            long long divisor = gcd(pairs, total);
            answer[q.id] = {pairs / divisor, total / divisor};
        }
    }
    for (auto [a, b] : answer)
        cout << a << '/' << b << '\n';
    return 0;
}
```

### 复杂度

时间 $O((n+m)\sqrt n+m\log m)$，空间 $O(n+m)$。

### 易错点

加入与删除时修改计数的先后不同，写反会漏或多算一组。分子、分母都要 long long；输出按原查询顺序恢复。

## 普通平衡树

### 题意

支持重复值的插删、排名、第k小、严格前驱后继。

### 思路

FHQ Treap按键保持BST、按随机优先级保持堆。split将树拆成≤key与>key，merge合并键值范围有序的两棵树。每个不同键存重复次数count，size为含重复的子树大小。插删时两次split隔离该键；排名按左子树size累加，第k小按左右数量定位，前驱后继沿BST下降。

重复插入只增count，删除只减一份，减至0才合并两个儿子替换该节点。随机优先级使树高期望对数。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Treap {
    struct Node {
        int left = 0, right = 0, count = 1, size = 1;
        long long key = 0;
        unsigned priority = 0;
    };
    vector<Node> tree;
    mt19937 random{20261108};
    int root = 0;
    Treap(int n) {
        tree.reserve(n + 1);
        tree.emplace_back();
        tree[0].count = tree[0].size = 0;
    }
    void pull(int u) {
        if (u)
            tree[u].size = tree[tree[u].left].size + tree[tree[u].right].size + tree[u].count;
    }
    void split(int u, long long key, int &a, int &b) {
        if (!u) {
            a = b = 0;
            return;
        }
        if (tree[u].key <= key) {
            a = u;
            split(tree[u].right, key, tree[u].right, b);
            pull(a);
        } else {
            b = u;
            split(tree[u].left, key, a, tree[u].left);
            pull(b);
        }
    }
    int merge(int a, int b) {
        if (!a || !b)
            return a ? a : b;
        if (tree[a].priority < tree[b].priority) {
            tree[a].right = merge(tree[a].right, b);
            pull(a);
            return a;
        }
        tree[b].left = merge(a, tree[b].left);
        pull(b);
        return b;
    }
    void change(long long key, bool insert) {
        int a, b, c;
        split(root, key - 1, a, b);
        split(b, key, b, c);
        if (insert) {
            if (b) {
                tree[b].count++;
                pull(b);
            } else {
                b = tree.size();
                tree.emplace_back();
                tree[b].key = key;
                tree[b].priority = random();
            }
        } else if (b) {
            if (--tree[b].count == 0)
                b = merge(tree[b].left, tree[b].right);
            else
                pull(b);
        }
        root = merge(merge(a, b), c);
    }
    int rank(long long key) {
        int u = root, answer = 1;
        while (u) {
            if (tree[u].key < key) {
                answer += tree[tree[u].left].size + tree[u].count;
                u = tree[u].right;
            } else
                u = tree[u].left;
        }
        return answer;
    }
    long long kth(int k) {
        int u = root;
        while (u) {
            int left = tree[tree[u].left].size;
            if (k <= left)
                u = tree[u].left;
            else if (k <= left + tree[u].count)
                return tree[u].key;
            else {
                k -= left + tree[u].count;
                u = tree[u].right;
            }
        }
        return 0;
    }
    long long neighbor(long long key, bool successor) {
        int u = root;
        long long answer = 0;
        while (u) {
            if (successor ? tree[u].key > key : tree[u].key < key) {
                answer = tree[u].key;
                u = successor ? tree[u].left : tree[u].right;
            } else
                u = successor ? tree[u].right : tree[u].left;
        }
        return answer;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    Treap tree(n);
    while (n--) {
        int op;
        long long x;
        cin >> op >> x;
        if (op == 1 || op == 2)
            tree.change(x, op == 1);
        else if (op == 3)
            cout << tree.rank(x) << '\n';
        else if (op == 4)
            cout << tree.kth(x) << '\n';
        else
            cout << tree.neighbor(x, op == 6) << '\n';
    }
    return 0;
}
```

### 复杂度

每次期望 $O(\log n)$，极端优先级下最坏 $O(n)$；空间 $O(n)$。

### 易错点

严格前驱/后继不包含相等值。key用64位，split(key−1)不会在原32位边界溢出。题目查询需要存在合法答案。

## 石子合并

### 题意

线性排列的相邻沙堆依次合并，求最小总代价。

### 思路

dp[l][r]为把连续区间[l,r]合成一堆的最小代价。最后一定由[l,k]、[k+1,r]两堆合并，故枚举k，并加上区间总重量。长度1代价0，其余从短到长计算；前缀和常数时间求最后合并费用。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> prefix(n + 1);
    for (int i = 1; i <= n; i++) {
        long long x;
        cin >> x;
        prefix[i] = prefix[i - 1] + x;
    }
    vector<vector<long long>> dp(n, vector<long long>(n));
    for (int length = 2; length <= n; length++)
        for (int l = 0; l + length <= n; l++) {
            int r = l + length - 1;
            dp[l][r] = 1LL << 60;
            for (int k = l; k < r; k++)
                dp[l][r] = min(dp[l][r], dp[l][k] + dp[k + 1][r] + prefix[r + 1] - prefix[l]);
        }
    cout << dp[0][n - 1];
    return 0;
}
```

### 复杂度

时间 $O(n^3)$，空间 $O(n^2)$。

### 易错点

这里是一排，不能复制成环后另选起点。只有两子区间合并完成后，才加一次整个区间总重。

## 没有上司的舞会

### 题意

员工与直接上司不能同时参加，快乐值可为负，求最大总快乐。

### 思路

每点维护选、不选两状态。选u时各孩子都不选；不选u时每个孩子独立取两状态较大者。叶子选值等于自己的快乐，不选为0，允许全不选。由无父亲的校长向下遍历，再逆序计算，答案为根两状态最大。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> happiness(n);
    for (auto &x : happiness)
        cin >> x;
    vector<vector<int>> children(n);
    vector<int> parent(n, -1);
    int child, boss;
    while (cin >> child >> boss && (child || boss)) {
        child--;
        boss--;
        children[boss].push_back(child);
        parent[child] = boss;
    }
    int root = 0;
    while (parent[root] != -1)
        root = parent[root];
    vector<int> order{root};
    for (size_t i = 0; i < order.size(); i++)
        for (int v : children[order[i]])
            order.push_back(v);
    vector<array<long long, 2>> dp(n);
    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];
        dp[u][1] = happiness[u];
        for (int v : children[u]) {
            dp[u][0] += max(dp[v][0], dp[v][1]);
            dp[u][1] += dp[v][0];
        }
    }
    cout << max(dp[root][0], dp[root][1]);
    return 0;
}
```

### 复杂度

时间、空间均为 $O(n)$。

### 易错点

输入是下属L、上司K，边方向不要反。只禁止直接上司和下属同场，祖孙可以同选。

## 选课

### 题意

恰选M门课程，有先修依赖，每课最多一个直接先修，最大化学分。

### 思路

将没有先修课的课程接到虚拟根0，虚拟根学分0。dp[u][j]表示选u且在其子树共选j门的最大分，初始dp[u][1]=本课学分。逐孩子做数量背包，可选孩子子树0门，或者选择一个包含孩子根的合法状态。中途不能从“不选u”状态接孩子，保证先修必选。处理完后给dp[u][0]=0，供父亲表示整棵不选。目标是dp[0][M+1]，多出的一个是虚拟根。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> children(n + 1);
    vector<int> credit(n + 1);
    for (int u = 1; u <= n; u++) {
        int p;
        cin >> p >> credit[u];
        children[p].push_back(u);
    }
    vector<int> order{0};
    for (size_t i = 0; i < order.size(); i++)
        for (int v : children[order[i]])
            order.push_back(v);
    const int neg = -1000000000;
    int target = m + 1;
    vector<vector<int>> dp(n + 1);
    for (int index = n; index >= 0; index--) {
        int u = order[index];
        dp[u] = {0, credit[u]};
        for (int v : children[u]) {
            int cap = min(target, (int)dp[u].size() + (int)dp[v].size() - 2);
            vector<int> next(cap + 1, neg);
            next[0] = 0;
            for (int i = 1; i < (int)dp[u].size(); i++)
                for (int j = 0; j < (int)dp[v].size() && i + j <= cap; j++)
                    if (dp[u][i] != neg && dp[v][j] != neg)
                        next[i + j] = max(next[i + j], dp[u][i] + dp[v][j]);
            dp[u].swap(next);
        }
    }
    cout << dp[0][target];
    return 0;
}
```

### 复杂度

保守时间 $O(nM^2)$，使用实际子树规模限制卷积；空间 $O(nM)$。

### 易错点

必须恰好M门，不能直接取至多M的最大值。虚拟根必须算进选课计数后，再把目标改为M+1。

## Accumulation Degree

### 题意

每边有容量，节点向其他原始叶子能送出的总流量取最大，求最优源点。

### 思路

树上不同分支在离开当前点后互不共享边，因此分支流量相加。以任意根求down[u]：通向孩子v的贡献若v是原始叶子，就等于边容量；否则为min(边容量,down[v])，对子节点相加。

换根时，令up[u]为u经父边去父侧终端的可送流量，total[u]=down[u]+up[u]。给孩子v传父侧流量，要从total[u]减去v分支贡献，再与父子边容量取小。例外是u本身原度为1，此时它就是v方向的一个终端，可直接接收全部边容量，不能用删去v后的空和0。遍历所有u的total取最大，源点自身即使是叶子也不接收自己的流。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Tree {
    vector<vector<pair<int, long long>>> edge;
    vector<int> parent, order;
    vector<long long> incoming;
    explicit Tree(int n) : edge(n), parent(n, -1), incoming(n) {}
    void add(int u, int v, long long w = 1) {
        edge[u].push_back({v, w});
        edge[v].push_back({u, w});
    }
    void root(int start) {
        order = {start};
        parent[start] = start;
        for (size_t i = 0; i < order.size(); i++) {
            int u = order[i];
            for (auto [v, w] : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    incoming[v] = w;
                    order.push_back(v);
                }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        cin >> n;
        Tree tree(n);
        for (int i = 1; i < n; i++) {
            int a, b;
            long long w;
            cin >> a >> b >> w;
            tree.add(a - 1, b - 1, w);
        }
        tree.root(0);
        vector<long long> down(n), up(n);
        for (int i = n - 1; i >= 0; i--) {
            int u = tree.order[i];
            for (auto [v, w] : tree.edge[u])
                if (v != tree.parent[u])
                    down[u] += tree.edge[v].size() == 1 ? w : min(w, down[v]);
        }
        long long answer = 0;
        for (int u : tree.order) {
            long long total = down[u] + up[u];
            answer = max(answer, total);
            for (auto [v, w] : tree.edge[u])
                if (v != tree.parent[u]) {
                    long long contribution = tree.edge[v].size() == 1 ? w : min(w, down[v]);
                    up[v] = tree.edge[u].size() == 1 ? w : min(w, total - contribution);
                }
        }
        cout << answer << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间、空间均为 $O(n)$。

### 易错点

叶子身份由原树度数决定，不随计算根变化。两点树两端都为终端，答案为唯一边容量；单点没有其他终端，答案0。

## Mondriaan's Dream

### 题意

用1乘2或2乘1骨牌铺满矩形，统计全部不同铺法，多组0 0结束。

### 思路

取较短边作列宽。行mask表示当前行哪些格已被上一行竖骨牌占住。对每个mask从左到右递归填剩余格：横放占当前行相邻两空格；竖放占当前格，并把下一行对应位设1。填完当前行后得到一个下一行mask转移。预处理全部行转移，再按行累加。初态与终态都必须为0，保证没有骨牌伸出上下边界。面积奇数时直接0。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int rows, cols;
    while (cin >> rows >> cols && (rows || cols)) {
        if ((rows * cols) % 2) {
            cout << "0\n";
            continue;
        }
        if (cols > rows)
            swap(rows, cols);
        int masks = 1 << cols;
        vector<vector<int>> transition(masks);
        for (int incoming = 0; incoming < masks; incoming++) {
            auto fill = [&](auto &&self, int c, int outgoing) -> void {
                if (c == cols) {
                    transition[incoming].push_back(outgoing);
                    return;
                }
                if (incoming >> c & 1)
                    self(self, c + 1, outgoing);
                else {
                    self(self, c + 1, outgoing | (1 << c));
                    if (c + 1 < cols && !(incoming >> (c + 1) & 1))
                        self(self, c + 2, outgoing);
                }
            };
            fill(fill, 0, 0);
        }
        vector<long long> dp(masks), next(masks);
        dp[0] = 1;
        for (int r = 0; r < rows; r++) {
            fill(next.begin(), next.end(), 0);
            for (int mask = 0; mask < masks; mask++)
                for (int out : transition[mask])
                    next[out] += dp[mask];
            dp.swap(next);
        }
        cout << dp[0] << '\n';
    }
    return 0;
}
```

### 复杂度

短边 $W\le11$，行转移总数 $E$，时间 $O(2^W3^W+HE)$ 为保守界，空间 $O(2^W+E)$。

### 易错点

对称、旋转后不同的铺法依然分别计数。最后不是所有mask求和，只能取没有悬空竖骨牌的0。

## Cut the Sequence

### 题意

切成若干连续段，每段和≤M，最小化每段最大值之和。

### 思路

设dp[i]为前i项最优值。末段在j后开始，转移为dp[j]+max(a[j+1..i])，并要求末段和≤M。非负数使合法j形成一段后缀，可双指针维护最早末段起点L。

在段树的叶子j维护这个转移候选。追加a[i]时，先将新叶i−1置为dp[i−1]+a[i]。旧候选的最大值如何变化？用值递减的单调栈保存当前后缀最大值的分段。弹出位置p时，弹后栈顶q（无则0），原来以a[p]为最大值的分界j恰为[q,p−1]，这些叶统一增加a[i]−a[p]。弹完后压i，在允许分界区间[L−1,i−1]查询最小，即得dp[i]。每个下标只弹一次，总更新线性次，每次段树对数时间。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct RangeMinimum {
    int n;
    const long long inf = 1LL << 60;
    vector<long long> value, lazy;
    explicit RangeMinimum(int n) : n(n), value(4 * n, 1LL << 60), lazy(4 * n) {}
    void apply(int p, long long delta) {
        value[p] += delta;
        lazy[p] += delta;
    }
    void push(int p) {
        if (lazy[p]) {
            apply(p * 2, lazy[p]);
            apply(p * 2 + 1, lazy[p]);
            lazy[p] = 0;
        }
    }
    void assign(int p, int l, int r, int position, long long x) {
        if (l == r) {
            value[p] = x;
            lazy[p] = 0;
            return;
        }
        push(p);
        int mid = (l + r) / 2;
        if (position <= mid)
            assign(p * 2, l, mid, position, x);
        else
            assign(p * 2 + 1, mid + 1, r, position, x);
        value[p] = min(value[p * 2], value[p * 2 + 1]);
    }
    void add(int p, int l, int r, int ql, int qr, long long delta) {
        if (ql <= l && r <= qr) {
            apply(p, delta);
            return;
        }
        push(p);
        int mid = (l + r) / 2;
        if (ql <= mid)
            add(p * 2, l, mid, ql, qr, delta);
        if (qr > mid)
            add(p * 2 + 1, mid + 1, r, ql, qr, delta);
        value[p] = min(value[p * 2], value[p * 2 + 1]);
    }
    long long query(int p, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr)
            return value[p];
        push(p);
        int mid = (l + r) / 2;
        long long answer = inf;
        if (ql <= mid)
            answer = min(answer, query(p * 2, l, mid, ql, qr));
        if (qr > mid)
            answer = min(answer, query(p * 2 + 1, mid + 1, r, ql, qr));
        return answer;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long limit;
    cin >> n >> limit;
    vector<long long> a(n + 1), prefix(n + 1), dp(n + 1);
    bool possible = true;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        prefix[i] = prefix[i - 1] + a[i];
        if (a[i] > limit)
            possible = false;
    }
    if (!possible) {
        cout << -1;
        return 0;
    }
    RangeMinimum tree(n);
    vector<int> stack;
    int left = 1;
    for (int i = 1; i <= n; i++) {
        while (!stack.empty() && a[stack.back()] <= a[i]) {
            int p = stack.back();
            stack.pop_back();
            int q = stack.empty() ? 0 : stack.back();
            tree.add(1, 0, n - 1, q, p - 1, a[i] - a[p]);
        }
        stack.push_back(i);
        tree.assign(1, 0, n - 1, i - 1, dp[i - 1] + a[i]);
        while (prefix[i] - prefix[left - 1] > limit)
            left++;
        dp[i] = tree.query(1, 0, n - 1, left - 1, i - 1);
    }
    cout << dp[n];
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

单个元素>M立即无解。M、前缀和、DP用64位；数组含0仍保持窗口合法性和单调栈分段。栈更新的是所有分界候选，不能只维护一个当前最大值。

## 花店橱窗

### 题意

按花束顺序选不同花瓶，最大化可为负的美观总值，同值时位置序列字典序最小。

### 思路

用后缀DP：dp[i][j]表示花i到末尾只能使用花瓶j到末尾的最优值。可跳过瓶j，或把花i放入j并转到dp[i+1][j+1]。没有剩余花时值为0，有花而无瓶时不可达，用负无穷。恢复时从左向右为每束花找最早的j，使本次美观值加剩余最优值仍等于当前最优值，立即选择。这样每一位都尽量靠前，保证全局字典序最小。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int f, v;
    cin >> f >> v;
    vector<vector<long long>> value(f, vector<long long>(v));
    for (auto &row : value)
        for (auto &x : row)
            cin >> x;
    const long long neg = -(1LL << 60);
    vector<vector<long long>> dp(f + 1, vector<long long>(v + 1, neg));
    fill(dp[f].begin(), dp[f].end(), 0);
    for (int i = f - 1; i >= 0; i--)
        for (int j = v - 1; j >= 0; j--) {
            dp[i][j] = dp[i][j + 1];
            if (dp[i + 1][j + 1] != neg)
                dp[i][j] = max(dp[i][j], value[i][j] + dp[i + 1][j + 1]);
        }
    cout << dp[0][0] << '\n';
    int start = 0;
    long long remaining = dp[0][0];
    for (int i = 0; i < f; i++)
        for (int j = start; j < v; j++)
            if (dp[i + 1][j + 1] != neg && value[i][j] + dp[i + 1][j + 1] == remaining) {
                cout << j + 1 << (i + 1 == f ? '\n' : ' ');
                remaining -= value[i][j];
                start = j + 1;
                break;
            }
    return 0;
}
```

### 复杂度

时间、空间均为 $O(FV)$。

### 易错点

负数美观值也必须放完所有花，不能用全0初始化不可达状态。普通正向回溯随意处理平局可能不满足字典序。

## Strategic game

### 题意

在树上选最少点，每条边至少一个端点有士兵。

### 思路

这是覆盖边的最小顶点覆盖。dp[u][0/1]表示u不选或选的最小数：u不选时每个孩子必须选，u选时孩子任选较少的状态。结点编号从0开始，输入每条边只出现一次，先建无向树再任取根处理。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Tree {
    vector<vector<pair<int, long long>>> edge;
    vector<int> parent, order;
    vector<long long> incoming;
    explicit Tree(int n) : edge(n), parent(n, -1), incoming(n) {}
    void add(int u, int v, long long w = 1) {
        edge[u].push_back({v, w});
        edge[v].push_back({u, w});
    }
    void root(int start) {
        order = {start};
        parent[start] = start;
        for (size_t i = 0; i < order.size(); i++) {
            int u = order[i];
            for (auto [v, w] : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    incoming[v] = w;
                    order.push_back(v);
                }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    while (cin >> n) {
        Tree tree(n);
        for (int i = 0; i < n; i++) {
            int u, k;
            char colon, open, close;
            cin >> u >> colon >> open >> k >> close;
            while (k--) {
                int v;
                cin >> v;
                tree.add(u, v);
            }
        }
        tree.root(0);
        vector<array<int, 2>> dp(n);
        for (int i = n - 1; i >= 0; i--) {
            int u = tree.order[i];
            dp[u][1] = 1;
            for (auto [v, w] : tree.edge[u])
                if (v != tree.parent[u]) {
                    dp[u][0] += dp[v][1];
                    dp[u][1] += min(dp[v][0], dp[v][1]);
                }
        }
        cout << min(dp[0][0], dp[0][1]) << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间、空间均为 $O(n)$。

### 易错点

题目覆盖全部边，孤立单点无需士兵。输入含冒号与括号，可逐字符读取，结点描述顺序不保证根先出现。

## Network of Schools

### 题意

最少起始软件副本，以及最少加边使全图强连通。

### 思路

缩点DAG中，每个源分量必须得到一个初始副本，其他点都能由源到达，所以第一问为源数。若只有一个SCC，第二问为0；否则至少要给每个源补入边、每个汇补出边，下界max(源数,汇数)。通过把源到汇的可达链连接成环并接入其余源汇可达到此界，因此第二问为两者最大。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

pair<int, vector<int>> components(const vector<vector<int>> &graph,
                                  const vector<vector<int>> &reverse) {
    int n = graph.size();
    vector<bool> seen(n);
    vector<int> finish;
    for (int start = 0; start < n; start++)
        if (!seen[start]) {
            vector<pair<int, int>> stack{{start, 0}};
            seen[start] = true;
            while (!stack.empty()) {
                int u = stack.back().first, &position = stack.back().second;
                if (position == (int)graph[u].size()) {
                    finish.push_back(u);
                    stack.pop_back();
                } else {
                    int v = graph[u][position++];
                    if (!seen[v]) {
                        seen[v] = true;
                        stack.push_back({v, 0});
                    }
                }
            }
        }
    vector<int> component(n, -1);
    int count = 0;
    for (int i = n - 1; i >= 0; i--) {
        int start = finish[i];
        if (component[start] != -1)
            continue;
        vector<int> stack{start};
        component[start] = count;
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            for (int v : reverse[u])
                if (component[v] == -1) {
                    component[v] = count;
                    stack.push_back(v);
                }
        }
        count++;
    }
    return {count, component};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> graph(n), reverse(n);
    for (int u = 0; u < n; u++) {
        int v;
        while (cin >> v && v) {
            v--;
            graph[u].push_back(v);
            reverse[v].push_back(u);
        }
    }
    auto [count, component] = components(graph, reverse);
    vector<int> in(count), out(count);
    for (int u = 0; u < n; u++)
        for (int v : graph[u])
            if (component[u] != component[v]) {
                in[component[v]]++;
                out[component[u]]++;
            }
    int sources = 0, sinks = 0;
    for (int c = 0; c < count; c++) {
        sources += in[c] == 0;
        sinks += out[c] == 0;
    }
    cout << sources << '\n' << (count == 1 ? 0 : max(sources, sinks));
    return 0;
}
```

### 复杂度

时间、空间均 $O(n+m)$。

### 易错点

已经强连通时第一问仍需1份副本，第二问才是0。

## 棋盘覆盖

### 题意

有禁格棋盘最多放多少1×2骨牌。

### 思路

按(r+c)奇偶把可用格分为两侧，相邻格总异色，每块骨牌对应一条相邻边。骨牌不重叠恰好是匹配约束，因此最大匹配数就是最大骨牌数。题目输出文字“覆盖格数”有歧义，但8×8样例输出32，显然按骨牌块数，不乘2。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Matching {
    int left, right, shortest;
    vector<vector<int>> edge;
    vector<int> mateLeft, mateRight, distance;
    Matching(int left, int right)
        : left(left), right(right), edge(left), mateLeft(left, -1), mateRight(right, -1),
          distance(left) {}
    bool bfs() {
        queue<int> queue;
        fill(distance.begin(), distance.end(), -1);
        for (int u = 0; u < left; u++)
            if (mateLeft[u] < 0) {
                distance[u] = 0;
                queue.push(u);
            }
        shortest = INT_MAX;
        while (!queue.empty()) {
            int u = queue.front();
            queue.pop();
            if (distance[u] + 1 > shortest)
                continue;
            for (int v : edge[u])
                if (mateRight[v] < 0)
                    shortest = min(shortest, distance[u] + 1);
                else if (distance[mateRight[v]] < 0) {
                    distance[mateRight[v]] = distance[u] + 1;
                    queue.push(mateRight[v]);
                }
        }
        return shortest < INT_MAX;
    }
    bool dfs(int u) {
        for (int v : edge[u])
            if ((mateRight[v] < 0 && distance[u] + 1 == shortest) ||
                (mateRight[v] >= 0 && distance[mateRight[v]] == distance[u] + 1 &&
                 dfs(mateRight[v]))) {
                mateLeft[u] = v;
                mateRight[v] = u;
                return true;
            }
        distance[u] = -1;
        return false;
    }
    int maximum() {
        int result = 0;
        while (bfs())
            for (int u = 0; u < left; u++)
                if (mateLeft[u] < 0 && dfs(u))
                    result++;
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<bool> blocked(n * n);
    while (m--) {
        int x, y;
        cin >> x >> y;
        blocked[(x - 1) * n + y - 1] = true;
    }
    Matching match(n * n, n * n);
    const int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};
    for (int r = 0; r < n; r++)
        for (int c = 0; c < n; c++)
            if ((r + c) % 2 == 0 && !blocked[r * n + c])
                for (int d = 0; d < 4; d++) {
                    int rr = r + dr[d], cc = c + dc[d];
                    if (rr >= 0 && rr < n && cc >= 0 && cc < n && !blocked[rr * n + cc])
                        match.edge[r * n + c].push_back(rr * n + cc);
                }
    cout << match.maximum();
    return 0;
}
```

### 复杂度

令V=n²，时间 $O(V\sqrt V)$，空间 $O(V)$。

### 易错点

只从一种格子颜色向另一种建边，避免把每格既当左点又当右点而重复使用。

## Redundant Paths

### 题意

加最少无向边让任意两点有两条边不重合路线。

### 思路

两条边不相交路径等价于没有桥。找出所有桥，把非桥边相连的点缩为边双连通分量，原连通图缩成一棵桥树。每个叶分量都需要至少一条新边接到外部，一条边最多照顾两个叶子，因此下界ceil(叶子数/2)；按DFS叶序跨半圈配对可让新边形成的环覆盖所有桥，达到下界。桥树只有一个节点时答案0。

参考代码用迭代DFS记录dfn/low，回退时判low[child]>dfn[parent]为桥。以边编号跳过父边，保留平行边的回边作用。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, size;
    DSU(int n) : parent(n + 1), size(n + 1, 1) { iota(parent.begin(), parent.end(), 0); }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int, int>>> edge(n);
    vector<pair<int, int>> endpoints(m);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        u--;
        v--;
        endpoints[i] = {u, v};
        edge[u].push_back({v, i});
        edge[v].push_back({u, i});
    }
    vector<int> dfn(n), low(n), parent(n, -1), parentEdge(n, -1), next(n), stack = {0};
    vector<bool> bridge(m);
    int timer = 1;
    dfn[0] = low[0] = 1;
    while (!stack.empty()) {
        int u = stack.back();
        if (next[u] < (int)edge[u].size()) {
            auto [v, id] = edge[u][next[u]++];
            if (id == parentEdge[u])
                continue;
            if (!dfn[v]) {
                parent[v] = u;
                parentEdge[v] = id;
                dfn[v] = low[v] = ++timer;
                stack.push_back(v);
            } else
                low[u] = min(low[u], dfn[v]);
        } else {
            stack.pop_back();
            if (parent[u] >= 0) {
                int p = parent[u];
                low[p] = min(low[p], low[u]);
                if (low[u] > dfn[p])
                    bridge[parentEdge[u]] = true;
            }
        }
    }
    DSU dsu(n);
    for (int i = 0; i < m; i++)
        if (!bridge[i])
            dsu.unite(endpoints[i].first, endpoints[i].second);
    vector<int> degree(n);
    for (int i = 0; i < m; i++)
        if (bridge[i]) {
            degree[dsu.find(endpoints[i].first)]++;
            degree[dsu.find(endpoints[i].second)]++;
        }
    int leaves = 0;
    for (int x : degree)
        leaves += x == 1;
    cout << (leaves + 1) / 2;
    return 0;
}
```

### 复杂度

时间 $O(n+m\alpha(n))$，空间 $O(n+m)$。

### 易错点

原图允许重边，不能仅用父节点编号跳过所有返父边。题目保证原图连通。

## Going Home

### 题意

每人各进不同房屋，最小曼哈顿移动总费用。

### 思路

地图没有障碍，每个人到每间房的最短路为曼哈顿距离。建立源→人容量1、人→房容量1费用距离、房→汇容量1的费用流图。逐次最短增广得到n单位流的最小费用；反向边费用取负，允许撤回之前指派来改进组合。代码用SPFA在残量图找最短路。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct CostFlow {
    struct Edge {
        int to, reverse;
        long long capacity, cost;
    };
    vector<vector<Edge>> graph;
    explicit CostFlow(int n) : graph(n) {}
    void add(int u, int v, long long capacity, long long cost) {
        int a = graph[u].size(), b = graph[v].size();
        graph[u].push_back({v, b, capacity, cost});
        graph[v].push_back({u, a, 0, -cost});
    }
    pair<long long, long long> minimum(int source, int sink) {
        const long long inf = LLONG_MAX / 4;
        long long flow = 0, cost = 0;
        int n = graph.size();
        while (true) {
            vector<long long> distance(n, inf);
            vector<int> parent(n, -1), index(n);
            vector<bool> inQueue(n);
            queue<int> queue;
            queue.push(source);
            inQueue[source] = true;
            distance[source] = 0;
            while (!queue.empty()) {
                int u = queue.front();
                queue.pop();
                inQueue[u] = false;
                for (int i = 0; i < (int)graph[u].size(); i++) {
                    auto e = graph[u][i];
                    if (e.capacity > 0 && distance[e.to] > distance[u] + e.cost) {
                        distance[e.to] = distance[u] + e.cost;
                        parent[e.to] = u;
                        index[e.to] = i;
                        if (!inQueue[e.to]) {
                            inQueue[e.to] = true;
                            queue.push(e.to);
                        }
                    }
                }
            }
            if (parent[sink] < 0)
                break;
            long long amount = inf;
            for (int v = sink; v != source; v = parent[v])
                amount = min(amount, graph[parent[v]][index[v]].capacity);
            for (int v = sink; v != source; v = parent[v]) {
                auto &e = graph[parent[v]][index[v]];
                e.capacity -= amount;
                graph[v][e.reverse].capacity += amount;
            }
            flow += amount;
            cost += amount * distance[sink];
        }
        return {flow, cost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int rows, cols;
    while (cin >> rows >> cols && (rows || cols)) {
        vector<pair<int, int>> people, house;
        for (int r = 0; r < rows; r++) {
            string s;
            cin >> s;
            for (int c = 0; c < cols; c++) {
                if (s[c] == 'm')
                    people.push_back({r, c});
                if (s[c] == 'H')
                    house.push_back({r, c});
            }
        }
        int n = people.size(), source = 2 * n, sink = source + 1;
        CostFlow flow(sink + 1);
        for (int i = 0; i < n; i++) {
            flow.add(source, i, 1, 0);
            flow.add(n + i, sink, 1, 0);
            for (int j = 0; j < n; j++)
                flow.add(i, n + j, 1,
                         abs(people[i].first - house[j].first) +
                             abs(people[i].second - house[j].second));
        }
        cout << flow.minimum(source, sink).second << '\n';
    }
    return 0;
}
```

### 复杂度

V=2n+2、E=O(n²)，最坏SPFA增广 $O(nVE)$，空间 $O(E)$。

### 易错点

可以穿过其他房屋而不入住，也可多人经过同一格，不添加网格占用冲突。

## King's Quest

### 题意

给定完美婚配，求每个男孩可在某个完美匹配中迎娶的女孩。

### 思路

设owner[g]是给定匹配中女孩g的男孩。每条喜欢边u→g转成男孩图边u→owner[g]。把u改配g会挤占另一个男孩，若可沿此图回到u，便能沿交替环轮换所有婚配。故喜欢边可选当且仅当u和owner[g]在同一个SCC；原匹配对应自环自然可选。每人筛选后按女孩编号排序。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

pair<int, vector<int>> components(const vector<vector<int>> &graph,
                                  const vector<vector<int>> &reverse) {
    int n = graph.size();
    vector<bool> seen(n);
    vector<int> finish;
    for (int start = 0; start < n; start++)
        if (!seen[start]) {
            vector<pair<int, int>> stack{{start, 0}};
            seen[start] = true;
            while (!stack.empty()) {
                int u = stack.back().first, &position = stack.back().second;
                if (position == (int)graph[u].size()) {
                    finish.push_back(u);
                    stack.pop_back();
                } else {
                    int v = graph[u][position++];
                    if (!seen[v]) {
                        seen[v] = true;
                        stack.push_back({v, 0});
                    }
                }
            }
        }
    vector<int> component(n, -1);
    int count = 0;
    for (int i = n - 1; i >= 0; i--) {
        int start = finish[i];
        if (component[start] != -1)
            continue;
        vector<int> stack{start};
        component[start] = count;
        while (!stack.empty()) {
            int u = stack.back();
            stack.pop_back();
            for (int v : reverse[u])
                if (component[v] == -1) {
                    component[v] = count;
                    stack.push_back(v);
                }
        }
        count++;
    }
    return {count, component};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> likes(n);
    for (auto &row : likes) {
        int k;
        cin >> k;
        row.resize(k);
        for (int &g : row) {
            cin >> g;
            g--;
        }
    }
    vector<int> owner(n);
    for (int u = 0; u < n; u++) {
        int g;
        cin >> g;
        owner[g - 1] = u;
    }
    vector<vector<int>> graph(n), reverse(n);
    for (int u = 0; u < n; u++)
        for (int g : likes[u]) {
            int v = owner[g];
            graph[u].push_back(v);
            reverse[v].push_back(u);
        }
    auto [count, component] = components(graph, reverse);
    for (int u = 0; u < n; u++) {
        vector<int> answer;
        for (int g : likes[u])
            if (component[u] == component[owner[g]])
                answer.push_back(g + 1);
        sort(answer.begin(), answer.end());
        cout << answer.size();
        for (int g : answer)
            cout << ' ' << g;
        cout << '\n';
    }
    return 0;
}
```

### 复杂度

时间 $O(n+E+E\log n)$（含输出排序），空间 $O(n+E)$。

### 易错点

两完美匹配的对称差是交替环，所以条件既必要又充分。只在原喜欢列表中筛，不输出不喜欢的女孩。

## 扫雷

### 题意

地雷保留星号，其他格输出八邻域中的地雷数。

### 思路

保存原棋盘。对每个非雷格，枚举行偏移和列偏移各为负一、零、一的九种组合，排除自身和越界位置，统计原棋盘中的雷。输出过程中不修改原棋盘，避免把已填的数字误当成输入。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<string> a(n);
    for (string &s : a)
        cin >> s;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (a[i][j] == '*') {
                cout << '*';
                continue;
            }
            int count = 0;
            for (int dx = -1; dx <= 1; dx++)
                for (int dy = -1; dy <= 1; dy++) {
                    int x = i + dx, y = j + dy;
                    if (dx == 0 && dy == 0)
                        continue;
                    if (x >= 0 && x < n && y >= 0 && y < m && a[x][y] == '*')
                        count++;
                }
            cout << count;
        }
        cout << '\n';
    }
    return 0;
}
```

### 复杂度

时间与棋盘空间均为 $O(nm)$。

### 易错点

斜向四格也在邻域中；边界处要先检查坐标再访问。

## Highway

### 题意

完全图的边权为原树两点距离，求最大生成树的总权。

### 思路

求原树直径端点A、B。树的非负边权保证任一点v的最远点可在A、B中取，所以偏心距ecc[v]=max(distA[v],distB[v])。先连A、B，其余每点连到较远端点，得到一棵树，总权为Σecc[v]−直径长度。

上界也恰为此值：任意生成树以A为根，每个v≠A的父边至多ecc[v]，所以总权≤Σ(v≠A)ecc[v]=Σecc[v]−dist(A,B)。上述构造达到上界，因此最优。三次迭代树遍历先找A，再求distA并找B，最后求distB。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Tree {
    vector<vector<pair<int, long long>>> edge;
    vector<int> parent, order;
    vector<long long> incoming;
    explicit Tree(int n) : edge(n), parent(n, -1), incoming(n) {}
    void add(int u, int v, long long w = 1) {
        edge[u].push_back({v, w});
        edge[v].push_back({u, w});
    }
    void root(int start) {
        order = {start};
        parent[start] = start;
        for (size_t i = 0; i < order.size(); i++) {
            int u = order[i];
            for (auto [v, w] : edge[u])
                if (v != parent[u]) {
                    parent[v] = u;
                    incoming[v] = w;
                    order.push_back(v);
                }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    while (cin >> n) {
        Tree tree(n);
        for (int i = 1; i < n; i++) {
            int a, b;
            long long w;
            cin >> a >> b >> w;
            tree.add(a - 1, b - 1, w);
        }
        auto distances = [&](int source) {
            vector<long long> d(n, -1);
            vector<int> queue{source};
            d[source] = 0;
            for (size_t h = 0; h < queue.size(); h++) {
                int u = queue[h];
                for (auto [v, w] : tree.edge[u])
                    if (d[v] == -1) {
                        d[v] = d[u] + w;
                        queue.push_back(v);
                    }
            }
            return d;
        };
        auto first = distances(0);
        int a = max_element(first.begin(), first.end()) - first.begin();
        auto da = distances(a);
        int b = max_element(da.begin(), da.end()) - da.begin();
        auto db = distances(b);
        long long answer = -da[b];
        for (int u = 0; u < n; u++)
            answer += max(da[u], db[u]);
        cout << answer << '\n';
    }
    return 0;
}
```

### 复杂度

每组时间、空间均为 $O(n)$。

### 易错点

求的是最大生成树，不能直接把原树边权相加。原树路径唯一，用普通遍历累加距离即可，无须Dijkstra。

## Forsaken喜欢独一无二的树

### 题意

删除最小权值总和的边，让原MST权值不变且MST唯一。

### 思路

按权值分组Kruskal。进入权值w组前，先按更小权边收缩连通块。组内两端已在同一旧块的边永远不在任何MST中，可保留；其余候选边若在收缩图中有环，环上等权边可替换，MST就不唯一。必须把这些候选边删成森林，最少删除数为候选边数减该组的连通秩。

先完整收集本组所有候选边，再对它们做并查集合并。成功合并的数就是秩，失败合并的候选边各必须删除一条，费用同为w，累计即可。收缩图每个分量保留任意生成树都能使后续Kruskal连通关系不变，所以原MST权值保持。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, size;
    DSU(int n) : parent(n + 1), size(n + 1, 1) { iota(parent.begin(), parent.end(), 0); }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (size[a] < size[b])
            swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    struct Edge {
        int a, b;
        long long w;
    };
    vector<Edge> edges(m);
    for (auto &e : edges)
        cin >> e.a >> e.b >> e.w;
    sort(edges.begin(), edges.end(), [](auto a, auto b) { return a.w < b.w; });
    DSU dsu(n);
    long long answer = 0;
    for (int l = 0; l < m;) {
        int r = l;
        while (r < m && edges[r].w == edges[l].w)
            r++;
        vector<pair<int, int>> candidates;
        for (int i = l; i < r; i++) {
            int a = dsu.find(edges[i].a), b = dsu.find(edges[i].b);
            if (a != b)
                candidates.push_back({a, b});
        }
        for (auto [a, b] : candidates)
            if (!dsu.unite(a, b))
                answer += edges[l].w;
        l = r;
    }
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(m\log m+(n+m)\alpha(n))$，空间 $O(n+m)$。

### 易错点

必须在合并本组任何边之前筛候选，不能把本组造成的同根误认为更小权已经连通。原来就不是MST候选的重边或环边无需删除。

## Forsaken喜欢数论

### 题意

求1到n每个数的最小质因子之和，n至三千万，1的贡献为0。

### 思路

所有偶数的最小质因子都是2。奇数只需存一个16位最小质因子：奇合数的最小质因子≤sqrt(n)<5500，未填表示奇素数。按递增奇素数p，从p²起每隔2p给尚未填的奇合数记录p，第一次填入就是最小质因子。最后逐数求和，奇数未填时加它自身。只为奇数开数组，约三千万字节，避免每个数用32位因子的内存。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<uint16_t> smallest(n / 2 + 1);
    for (int p = 3; 1LL * p * p <= n; p += 2)
        if (!smallest[p / 2])
            for (int x = p * p; x <= n; x += 2 * p)
                if (!smallest[x / 2])
                    smallest[x / 2] = p;
    long long answer = 2LL * (n / 2);
    for (int x = 3; x <= n; x += 2)
        answer += smallest[x / 2] ? smallest[x / 2] : x;
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(n\log\log n)$，存约 $n/2$ 个16位数，空间 $O(n)$ 字节。

### 易错点

未填的奇数是素数，其贡献不是0。1单独跳过；总和用64位。

## 两个人的星座

### 题意

每个三角形含三色，统计彼此完全不相交的无序三角形对。

### 思路

两个不相交凸三角形恰有两条内公切线，每条线各经过两个三角形的一个顶点，且两个三角形位于其两侧。固定有向线P→Q，先令P所属三角形其余两顶点在左侧、Q所属三角形其余两顶点在右侧；按颜色计数，方案数是左侧除P颜色外两种数量之积，乘右侧除Q颜色外两种数量之积。再加上左右互换的另一种情况。

对每个P极角排序Q，用半周双指针维护严格左侧三色数量，右侧由总数减去左侧和P、Q得到。累计有向线两侧方案后除4：每对三角形有两条内公切线，每条又被两个方向各统计一次。无三点共线保证切线不重合、其余点不会落在线上。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

using Wide = __int128_t;
struct IPoint {
    long long x = 0, y = 0;
    IPoint operator+(IPoint b) const { return {x + b.x, y + b.y}; }
    IPoint operator-(IPoint b) const { return {x - b.x, y - b.y}; }
};
Wide cross(IPoint a, IPoint b) { return (Wide)a.x * b.y - (Wide)a.y * b.x; }
Wide dot(IPoint a, IPoint b) { return (Wide)a.x * b.x + (Wide)a.y * b.y; }
Wide absolute(Wide x) { return x < 0 ? -x : x; }
void printWide(Wide value) {
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string text;
    do {
        text.push_back('0' + value % 10);
        value /= 10;
    } while (value);
    reverse(text.begin(), text.end());
    cout << text;
}
bool angleLess(IPoint a, IPoint b) {
    auto half = [](IPoint p) { return p.y < 0 || (p.y == 0 && p.x < 0); };
    if (half(a) != half(b))
        return half(a) < half(b);
    return cross(a, b) > 0;
}
vector<IPoint> integerHull(vector<IPoint> point) {
    sort(point.begin(), point.end(),
         [](auto a, auto b) { return a.x != b.x ? a.x < b.x : a.y < b.y; });
    point.erase(
        unique(point.begin(), point.end(), [](auto a, auto b) { return a.x == b.x && a.y == b.y; }),
        point.end());
    if (point.size() < 2)
        return point;
    vector<IPoint> hull;
    for (auto p : point) {
        while (hull.size() >= 2 && cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    size_t lower = hull.size();
    for (int i = (int)point.size() - 2; i >= 0; i--) {
        auto p = point[i];
        while (hull.size() > lower &&
               cross(hull.back() - hull[hull.size() - 2], p - hull.back()) <= 0)
            hull.pop_back();
        hull.push_back(p);
    }
    hull.pop_back();
    return hull;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<IPoint> p(n);
    vector<int> color(n);
    array<long long, 3> total = {};
    for (int i = 0; i < n; i++) {
        cin >> p[i].x >> p[i].y >> color[i];
        total[color[i]]++;
    }
    Wide answer = 0;
    for (int origin = 0; origin < n; origin++) {
        struct V {
            IPoint direction;
            int color;
        };
        vector<V> v;
        for (int i = 0; i < n; i++)
            if (i != origin)
                v.push_back({p[i] - p[origin], color[i]});
        sort(v.begin(), v.end(),
             [](auto a, auto b) { return angleLess(a.direction, b.direction); });
        int m = v.size();
        for (int i = 0; i < m; i++)
            v.push_back(v[i]);
        array<long long, 3> left = {};
        int right = 1;
        for (int i = 0; i < m; i++) {
            right = max(right, i + 1);
            while (right < i + m && cross(v[i].direction, v[right].direction) > 0) {
                left[v[right].color]++;
                right++;
            }
            auto other = total;
            other[color[origin]]--;
            other[v[i].color]--;
            for (int c = 0; c < 3; c++)
                other[c] -= left[c];
            Wide ways = 1, reverseWays = 1;
            for (int c = 0; c < 3; c++) {
                if (c != color[origin]) {
                    ways *= left[c];
                    reverseWays *= other[c];
                }
                if (c != v[i].color) {
                    ways *= other[c];
                    reverseWays *= left[c];
                }
            }
            answer += ways + reverseWays;
            if (i + 1 < right)
                left[v[i + 1].color]--;
        }
    }
    printWide(answer / 4);
    return 0;
}
```

### 复杂度

时间 $O(n²\log n)$，空间 $O(n)$。

### 易错点

两个三角形的6个点必须互不相同，P、Q都从左右计数中扣除。这里统计分离公切线，交叉或包含的三角形不会贡献。

## Forsaken的三维数点

### 题意

动态加入三维点，查询以原点为心覆盖至少k点的最小整数半径。

### 思路

每个点仅由距离平方d=x²+y²+z²决定。先读操作，离散化全部插入点的d，再按时间执行。树状数组维护距离频数，用二进制提升查第k小距离平方，最后输出ceil(sqrt(d))。k=0时半径0；已插入数量不足k时输出−1。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> tree;
    Fenwick(int n) : n(n), tree(n + 1) {}
    void add(int p, long long v) {
        for (; p <= n; p += p & -p)
            tree[p] += v;
    }
    long long sum(int p) {
        long long result = 0;
        for (; p; p -= p & -p)
            result += tree[p];
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    struct Operation {
        int type, k;
        long long distance;
    };
    vector<Operation> operation;
    vector<long long> coordinate;
    for (int i = 0; i < n; i++) {
        int op;
        cin >> op;
        if (op == 1) {
            long long x, y, z;
            cin >> x >> y >> z;
            long long d = x * x + y * y + z * z;
            operation.push_back({1, 0, d});
            coordinate.push_back(d);
        } else {
            int k;
            cin >> k;
            operation.push_back({2, k, 0});
        }
    }
    sort(coordinate.begin(), coordinate.end());
    coordinate.erase(unique(coordinate.begin(), coordinate.end()), coordinate.end());
    Fenwick bit(coordinate.size());
    int total = 0;
    for (auto op : operation) {
        if (op.type == 1) {
            int rank = lower_bound(coordinate.begin(), coordinate.end(), op.distance) -
                       coordinate.begin() + 1;
            bit.add(rank, 1);
            total++;
        } else if (!op.k)
            cout << 0 << '\n';
        else if (op.k > total)
            cout << -1 << '\n';
        else {
            int p = 0;
            long long remaining = op.k;
            int step = 1;
            while (step <= bit.n / 2)
                step <<= 1;
            for (; step; step >>= 1)
                if (p + step <= bit.n && bit.tree[p + step] < remaining) {
                    p += step;
                    remaining -= bit.tree[p];
                }
            long long d = coordinate[p], r = sqrtl(d);
            while (r * r < d)
                r++;
            while (r > 0 && (r - 1) * (r - 1) >= d)
                r--;
            cout << r << '\n';
        }
    }
    return 0;
}
```

### 复杂度

时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

重复坐标也会增加能量，频数要累加。距离平方用64位，最后用整数平方校正浮点开方。

## 「木」迷雾森林

### 题意

从左下走到右上，只能向上或向右，避开树，方案数模2333。

### 思路

反过来从右上向左下走，允许向下或向左，路径一一对应。这样可以按输入从上到下逐行处理，并在每行从右往左更新。dp[c]原来是上一行同列的方案，加上当前行右侧dp[c+1]；遇树则清零。首行右上角的起点单独初始化为1。只需保留一行，不存九百万格地图。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int rows, cols;
    cin >> rows >> cols;
    vector<int> dp(cols + 1), blocked(cols);
    for (int r = 0; r < rows; r++) {
        for (int &x : blocked)
            cin >> x;
        for (int c = cols - 1; c >= 0; c--) {
            if (blocked[c])
                dp[c] = 0;
            else if (r == 0 && c == cols - 1)
                dp[c] = 1;
            else
                dp[c] = (dp[c] + dp[c + 1]) % 2333;
        }
    }
    cout << dp[0];
    return 0;
}
```

### 复杂度

时间 $O(mn)$，额外空间 $O(n)$。

### 易错点

原题起点在左下，按左上起点普通转移会算错。反向路径允许流式读取，仍需每行先读完才能倒序更新。

## 「土」秘法地震

### 题意

统计地图中含至少一座建筑的 k 乘 k 正方形窗口数。

### 思路

二维前缀和 prefix[r][c] 保存左上矩形建筑数量。枚举所有能完整放入地图的 k 乘 k 窗口，用四项容斥得到窗口总和；大于零就让答案加一。即使窗口内有多个建筑也只算一种施法位置。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    cin >> n >> m >> k;
    vector<vector<int>> prefix(n + 1, vector<int>(m + 1));
    for (int r = 1; r <= n; r++)
        for (int c = 1; c <= m; c++) {
            char x;
            cin >> x;
            prefix[r][c] = prefix[r - 1][c] + prefix[r][c - 1] - prefix[r - 1][c - 1] + (x == '1');
        }
    int answer = 0;
    for (int r = k; r <= n; r++)
        for (int c = k; c <= m; c++)
            if (prefix[r][c] - prefix[r - k][c] - prefix[r][c - k] + prefix[r - k][c - k] > 0)
                answer++;
    cout << answer;
    return 0;
}
```

### 复杂度

时间、空间均为 $O(nm)$。

### 易错点

矩阵样例是不带空格的字符串，逐字符读入也能兼容有空格的写法。窗口不能越出地图。

## 「金」点石成金

### 题意

每块石头二选一，财富或魔法低于0就归零，最大化最后乘积。

### 思路

n最多15，直接DFS枚举每块石头的两种选择。转移时马上把被减少的量截到0，不能把负数留到最后。到第n块后计算乘积取最大。搜索深度只有15，不需要记忆化。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<array<long long, 4>> a(n);
    for (auto &x : a)
        for (auto &v : x)
            cin >> v;
    long long answer = 0;
    auto dfs = [&](auto &&self, int i, long long wealth, long long magic) -> void {
        if (i == n) {
            answer = max(answer, wealth * magic);
            return;
        }
        auto [gain, cost, recover, loss] = a[i];
        self(self, i + 1, wealth + gain, max(0LL, magic - cost));
        self(self, i + 1, max(0LL, wealth - loss), magic + recover);
    };
    dfs(dfs, 0, 0, 0);
    cout << answer;
    return 0;
}
```

### 复杂度

时间 $O(2^n)$，额外空间 $O(n)$。

### 易错点

每步都归零，不能把减少量当欠债。两个累计量可达一千五百万，乘积用64位。

## 「土」巨石滚滚

### 题意

安排先损失 a、再回复 b 的障碍顺序，判断初始稳定性能否完成全部障碍。

### 思路

先处理 b>=a 的不亏障碍，按 a 升序；越容易的增益越应先拿，完成后不会降低后续可行性。再处理 b<a 的亏损障碍，按 b 降序。对两个亏损障碍 A、B，若 bA>=bB，先 A 再 B 所需初始量 max(aA,aA-bA+aB)，不超过反序所需的 max(aB,aB-bB+aA)，因此该顺序安全。按排序模拟，每次先检查当前量至少为 a，再加 b-a。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        long long stability;
        cin >> n >> stability;
        vector<pair<long long, long long>> a(n);
        for (auto &[loss, gain] : a)
            cin >> loss >> gain;
        sort(a.begin(), a.end(), [](const auto &x, const auto &y) {
            bool gx = x.second >= x.first, gy = y.second >= y.first;
            if (gx != gy)
                return gx > gy;
            return gx ? x.first < y.first : x.second > y.second;
        });
        bool possible = true;
        for (auto [loss, gain] : a) {
            if (stability < loss) {
                possible = false;
                break;
            }
            stability += gain - loss;
        }
        cout << (possible ? "Yes\n" : "No\n");
    }
    return 0;
}
```

### 复杂度

每组时间 $O(n\log n)$，空间 $O(n)$。

### 易错点

必须先承担损失才收到回复；即使 a=b，也不能在当前稳定性小于 a 时通过。零稳定性允许存在，负数才散架。

## 矩阵元素定位

### 题意

读入矩阵后，查询一开始编号的第 x 行第 y 列。

### 思路

按行列保存全部数据，再把输入的一开始坐标减一，访问 a[x-1][y-1]。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> a(n, vector<int>(m));
    for (auto &row : a)
        for (int &x : row)
            cin >> x;
    int x, y;
    cin >> x >> y;
    cout << a[x - 1][y - 1];
